/* 2026 题库：6月LC押题×4 + 9月300题×2 + 6月真题汇编×2 + 11月300题×3（自动生成，仅供内部学习） */
var EXAM_JUN2026 = [{"id":"jun-law1","subject":"law","name":"6月押题 · 法规卷一","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"jun-law1-0","subject":"law","source":"6月押题 LC","type":"单选","q":"证券金融公司向证券公司转融通的期限不得超过()个月。","options":["12","6","3","9"],"answer":"B","explain":"B 选项正确，证券金融公司向证券公司转融通的期限不得超过 6 个月。故本题选 B 选项。"},{"id":"jun-law1-1","subject":"law","source":"6月押题 LC","type":"单选","q":"证券金融公司开展转融通业务，应当向证券公司收取一定比例的保证金，保证金可以证券充抵，但货币资金占应收取保证金的比例不得低于 ()。","options":["8%","10%","12%","15%"],"answer":"D","explain":"证券金融公司开展转融通业务，应当向证券公司收取一定比例的保证金，保证金可以证券充抵，但货币资金占应收取保证金的比例不得低于 15%(D 选项正确)，可充抵保证金证券的种类和折算率由证券金融公司确定并公布。故本题选 D 选项。"},{"id":"jun-law1-2","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司中应对违反职责范围内的内部控制要求所导致的风险和损失承担首要责任的是 ()。","options":["直接从事业务经营活动的相关人员","董事会","经理层","合规部门"],"answer":"A","explain":"A 选项正确，直接从事业务经营活动的业务部门和分支机构的相关人员有义务向证券公司报告内部控制的缺陷，并及时加以纠正。相关人员应对违反职责范围内的内部控制导致的风险和损失承担首要责任。故本题选 A 选项。"},{"id":"jun-law1-3","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司证券自营业务投资运作的最高管理机构是()，负责确定具体的资产配置策略、投资事项和投资品种等。","options":["股东会","自营业务部门","董事会","投资决策机构"],"answer":"D","explain":"D 选项正确，投资决策机构是自营业务投资运作的最高管理机构，负责确定具体的资产配置策略、投资事项和投资品种等。故本题选 D 选项。【乐知识】股东会是公司的权力机构。"},{"id":"jun-law1-4","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司应当在全公司推行的风险文化是 ()。","options":["积极","保守","激进","稳健"],"answer":"D","explain":"D 选项正确，证券公司应当在全公司推行稳健的风险文化，形成与本公司相适应的风险管理理念、价值准则、职业操守，建立培训、宣导和监督机制并纳入考核体系。故本题选 D 选项。"},{"id":"jun-law1-5","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司应当于每年 ()前，完成对上一年网络和信息安全工作的专项评估，编制网络和信息安全管理年报，报送中国证监会及其派出机构。","options":["8 月 31 日","12 月 31 日","4 月 30 日","6 月 30 日"],"answer":"C","explain":"C 选项正确，证券公司应当于每年 4 月 30 日前，完成对上一年网络和信息安全工作的专项评估，编制网络和信息安全管理年报，报送中国证监会及其派出机构。故本题选 C 选项。"},{"id":"jun-law1-6","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司应当 ()负责与客户进行沟通，处理客户投诉等事宜。","options":["由营业部营销人员","设立营业部员工轮岗机制","由公司合规部","设立专职部门或岗位"],"answer":"D","explain":"证券公司对客户的义务包括完善客户沟通、投诉处理机制。证券公司应当设专职部门或者岗位 (D 选项正确)，负责与客户进行沟通，处理客户的投诉等事宜。故本题选 D 选项。"},{"id":"jun-law1-7","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司派内部单位工作人员，借调至贫困山区参与扶贫项目，参与扶贫攻坚，体现了其 ()。","options":["承担社会责任","遵守法律法规","接受政府和公众的监督","遵守社会公德"],"answer":"A","explain":"A 选项正确，证券公司派员参与扶贫攻坚，属于积极响应国家脱贫攻坚战略，主动投入资源助力社会发展，是典型的社会责任体现。故本题选 A 选项。【乐知识】公司从事经营活动，应当遵守法律法规，遵守社会公德、 商业道德、诚实守信、接受政府和社会公众的监督。"},{"id":"jun-law1-8","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司分类评价设定正常经营的证券公司基准分为 ()。","options":["90 分","120 分","80 分","100 分"],"answer":"D","explain":"D 选项正确，证券公司分类评价首先设定正常经营的证券公司基准分为 100 分。故本题选 D 选项。"},{"id":"jun-law1-9","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司的分支机构应当配备具备 ()年以上证券、金融、法律、会计、信息技术等有关领域工作经历，具备与履行合规管理职责相适应的专业知识和技能的合规管理人员。","options":["1","2","3","4"],"answer":"C","explain":"C 选项正确，证券公司业务部门、分支机构应当配备具备 3 年以上证券、金融、法律、会计、信息技术等有关领域工作经历，具备与履行合规管理职责相适应的专业知识和技能的合规管理人员。故本题选 C 选项。"},{"id":"jun-law1-10","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司持续合规状况的评价依据之一为 ()采取的刑事处罚措施。","options":["中国证监会","司法机关","中国证监会及其派出机构","中国人民银行"],"answer":"B","explain":"B 选项正确，证券公司持续合规状况主要根据司法机关采取的刑事处罚措施、中国证监会及其派出机构采取的行政处罚措施、行政监管措施及证券期货行业自律组织纪律处分、自律管理措施等情况进行评价。故本题选 B 选项。"},{"id":"jun-law1-11","subject":"law","source":"6月押题 LC","type":"单选","q":"证券的包销、代销期限最长不超过 () 。","options":["180 日","90 日","60 日","360 日"],"answer":"B","explain":"B 选项正确，证券的代销、包销期限最长不得超过 90 天。故本题选 B 选项。"},{"id":"jun-law1-12","subject":"law","source":"6月押题 LC","type":"单选","q":"债券交易人员薪酬与激励合计超过人民币 ()万元的，超过部分应按照等分原则递延发放，周期不少于 2 年。","options":["50","100","200","500"],"answer":"B","explain":"B 选项正确，债券交易人员薪酬与激励合计超过人民币 100 万元的，超过部分应按照等分原则递延发放，周期不少于 2 年。故本题选 B 选项。"},{"id":"jun-law1-13","subject":"law","source":"6月押题 LC","type":"单选","q":"有权决定国有独资公司合并分立的是 ()。","options":["股东会","董事会","国有资产监督管理机构","监事会"],"answer":"C","explain":"C 选项正确，国务院或者地方人民政府可以授权国有资产监督管理机构或者其他部门、机构代表本级人民政府对国家出资公司履行出资人职责。国有独资公司的合并、分立、解散、申请破产，增加或者减少注册资本，分配利润，应当由履行出资人职责的机构决定。故本题选 C 选项。"},{"id":"jun-law1-14","subject":"law","source":"6月押题 LC","type":"单选","q":"由发起人认购设立公司时发行的全部股份而设立股份有限公司，称为 ()。","options":["认购设立","募集设立","核准设立","发起设立"],"answer":"D","explain":"D 选项正确，发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。发起设立适用于有限责任公司和股份有限公司。故本题选 D 选项。"},{"id":"jun-law1-15","subject":"law","source":"6月押题 LC","type":"单选","q":"下列有关证券公司证券自营业务禁止性行为的说法，错误的是 ()。","options":["证券自营业务不得违反规定委托他人代为买卖证券","证券公司不得利用本公司投资银行业务内幕信息从事证券交易活动","证券自营业务不得违反规定购买本证券公司控股股东发行的证券","证券公司可以将自营业务与经纪业务混合操作"],"answer":"D","explain":"证券自营业务的禁止性行为：(1)禁止内幕交易。证券公司从事证券自营业务时，严禁以获取利益或者减少损失为目的，利用证券交易内幕信息的知情人和非法获取内幕信息的人利用内幕信息从事证券交易活动 (B 选项正确)。(2)禁止操纵市场。(3)其他禁止的行为。包括：①违反规定委托他人代为买卖证券 (A 选项正确)；②违反规定购买本证券公司控股股东或者与本证券公司有其他重大利害关系的发行人发行的证券 (C 选项正确)；③将自营业务与经纪业务混合操作 (D 选项错误)。故本题选 D 选项。【乐知识】证券自营业务其他禁止的行为包括：(1)假借他人名义或者个人名义进行自营业务；(2)违反规定委托他人代为买卖证券；(3)违反规定购买本证券公司控股股东或者与本证券公司有其他重大利害关系的发行人发行的证券；(4)将自营账户借给他人使用；(5)将自营业务与经纪业务混合操作；(6)法律、行政法规或中国证监会禁止的其他行为。"},{"id":"jun-law1-16","subject":"law","source":"6月押题 LC","type":"单选","q":"下列关于证券投资咨询机构及其执业人员向社会公众开展证券投资咨询业务活动的说法，错误的是 ()。","options":["证券投资咨询从业人员向公众提供证券投资咨询服务时，需先行取得所在机构的认可","证券公司财务顾问专业人员在离开原岗位后的 6 个月内不得从事面向公众开展的投资咨询业务","证券投资咨询机构可参加媒体等机构举办的模拟证券投资大赛的节目，但证券投资咨询人员除外","经证监会核准的公开发行证券的企业的承销商及其所属的证券投资咨询机构，不得在公众传播媒体上刊登其为客户撰写的投资价值分析报告"],"answer":"C","explain":"C 选项错误，证券投资咨询机构及其从业人员不得参加(并非\"可参加\")媒体等机构举办的荐股\"擂台赛\"、模拟证券投资大赛或类似的栏目或节目。故本题选 C 选项。"},{"id":"jun-law1-17","subject":"law","source":"6月押题 LC","type":"单选","q":"下列关于分公司法律地位的说法，正确的是 () 。","options":["分公司具有法人资格","分公司的责任由公司承担","分公司有自己的章程","分公司独立承担民事责任"],"answer":"B","explain":"B 选项正确，公司可以设立分公司。分公司不具有法人资格，其民事责任由公司承担。故本题选 B 选项。"},{"id":"jun-law1-18","subject":"law","source":"6月押题 LC","type":"单选","q":"下列关于非公开基金投资范围的说法中，错误的是() 。","options":["非公开募集基金可以买卖股指期货","非公开募集基金可以买卖基金份额","非公开募集基金可以买卖股权","非公开募集基金可以买卖基金合同约定以外的投资标的"],"answer":"D","explain":"非公开募集基金财产的投资包括买卖股票、股权 (C 选项正确)、债券、期货 (A选项正确)、期权、基金份额 (B 选项正确)及投资合同约定的其他投资标的 (D选项错误)。故本题选 D 选项。"},{"id":"jun-law1-19","subject":"law","source":"6月押题 LC","type":"单选","q":"我国证券市场法律法规体系主要层级包括 ()。","options":["法律、行政法规、部门规章三个层级","法律、行政法规、部门规章、规范性文件、行业自律规则五个层级","法律、行政法规、部门规章、规范性文件四个层级","法律、行政法规、部门规章、规范性文件、行业自律规则、各组织机构规章制度六个层级"],"answer":"B","explain":"B 选项正确，我国证券市场法律法规体系的主要层级包括五级：法律、行政法规、部门规章、规范性文件、行业自律规则。故本题选 B 选项。"},{"id":"jun-law1-20","subject":"law","source":"6月押题 LC","type":"单选","q":"我国有限责任公司股东不得超过 ()人。","options":["50","100","150","20 割"],"answer":"A","explain":"A 选项正确，有限责任公司由 1 个以上 50 个以下股东出资设立。故本题选 A 选项。"},{"id":"jun-law1-21","subject":"law","source":"6月押题 LC","type":"单选","q":"投资者融券卖出时，私募证券投资基金的融券保证金比例不得低于 ()。","options":["50%","70%","90%","120%"],"answer":"D","explain":"投资者融券卖出时，融券保证金比例不得低于 100%，其中私募证券投资基金的融券保证金比例不得低于 120%(D 选项正确)。故本题选 D 选项。"},{"id":"jun-law1-22","subject":"law","source":"6月押题 LC","type":"单选","q":"甲证券营业部客服人员李某向张某销售某集合资产管理计划，李某向普通投资者张某进行了背景调查，并告知了适当性匹配意见及相关警示内容，并提供了书面文件。下列关于了解投资者信息的说法，错误的是() 。","options":["李某向张某销售产品，应当了解张某的诚信记录","李某向张某提供服务，应当了解张某的直系亲属信息","李某向张某提供服务，应当了解张某的投资经验","李某向张某提供服务，应当了解张某的风险偏好及可承受的损失"],"answer":"B","explain":"根据《证券期货投资者适当性管理办法》的要求，经营机构向投资者销售产品或者提供服务时，应当了解投资者的下列信息：(1) 自然人的姓名、住址、职业、年龄、联系方式，法人或者其他组织的名称、注册地址、办公地址、性质、资质及经营范围等基本信息 (B 选项错误，并非\"直系亲属\")；(2)投资相关的学习、工作经历及投资经验 (C 选项正确)；(3)风险偏好及可承受的损失 (D 选项正确)；(4)诚信记录 (A 选项正确)。故本题选 B 选项。【乐补充】经营机构向投资者销售产品或者提供服务时还应当了解投资者的下列信息：(1)收入来源和数额、资产、债务等财务状况；(2)投资期限、品种、期望收益等投资目标；(3)实际控制投资者的自然人和交易的实际受益人；(4)法律法规、自律规则规定的投资者准入要求相关信息；(5)其他必要信息。"},{"id":"jun-law1-23","subject":"law","source":"6月押题 LC","type":"单选","q":"基金财产保管职责应由 ()承担。","options":["基金管理人","基金销售机构","基金注册登记机构","基金托管人"],"answer":"D","explain":"D 选项正确，基金托管人，是指按照法律、法规的规定和基金合同的约定，在证券投资基金活动中承担基金资产保管、基金资金清算、交易监督、会计核算等职责的商业银行或其他金融机构。故本题选 D 选项。"},{"id":"jun-law1-24","subject":"law","source":"6月押题 LC","type":"单选","q":"国有独资公司、国有控股公司、国有参股公司是按照 ()划分的。","options":["国有出资比例","股东出资方式","投资者出资额","注册方式"],"answer":"A","explain":"A 选项正确，依公司是否有国有资本及其所占比重，可分为国有独资公司、国有控股公司、国有参股公司、非国有公司等。故本题选 A 选项。"},{"id":"jun-law1-25","subject":"law","source":"6月押题 LC","type":"单选","q":"关于诱骗投资者买卖证券、期货合约罪的犯罪构成，以下说法错误的是 ()。","options":["主体包含证券公司、期货公司从业人员，不包含证券期货监督管理部门的工作人员","主观方面为故意","侵犯的客体是证券、期货市场的正常交易管理秩序和证券、期货投资人的合法利益","客观要件包含行为人故意提供虚假信息诱骗投资者买卖证券，造成严重后果的行为"],"answer":"A","explain":"诱骗投资者买卖证券、期货合约罪犯罪的主体是特殊主体，主要包括两个方面：(1)证券交易所、期货交易所、证券公司、期货经纪公司的从业人员；(2)证券业协会、期货业协会或者证券期货监督管理部门的工作人员 (A 选项错误)。故本题选 A 选项。"},{"id":"jun-law1-26","subject":"law","source":"6月押题 LC","type":"单选","q":"股份有限公司以超过股票票面金额的发行价格发行股份所得的溢价款应当列为公司的 ()。","options":["资本公积金","任意公积金","股本溢价","法定公积金"],"answer":"A","explain":"A 选项正确，公司以超过股票票面金额的发行价格发行股份所得的溢价款、发行无面额股所得股款未计入注册资本的金额以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司资本公积金。故本题选 A 选项。【乐知识】公司分配当年税后利润时，应当提取利润的 10%列入公司法定公积金。公司从税后利润中提取法定公积金后，经股东会决议，还可以从税后利润中提取任意公积金。股本溢价是资本公积金下的明细科目 (资本公积金包含股本溢价、其他资本公积等)，题目问的是整体归属，而非具体明细，法规题目要遵从法律原文表述。"},{"id":"jun-law1-27","subject":"law","source":"6月押题 LC","type":"单选","q":"公司应当自作出合并决议之日起 () 日内通知债权人，并于 30 日内在报纸上公告。","options":["15","10","20","30"],"answer":"B","explain":"B 选项正确，公司合并，应当由合并各方签订合并协议，并编制资产负债表及财产清单。公司应当自作出合并决议之日起 10 日内通知债权人，并于 30 日内在报纸上或者国家企业信用信息公示系统公告。故本题选 B 选项。"},{"id":"jun-law1-28","subject":"law","source":"6月押题 LC","type":"单选","q":"根据证券公司应持续符合的风险控制指标标准，证券公司资本杠杆率不得低于 ()。","options":["0.05","0.08","0.1","0.07"],"answer":"B","explain":"证券公司必须持续符合下列风险控制指标标准：(1)风险覆盖率不得低于 100%；(2)资本杠杆率不得低于 8%(B 选项正确)；(3)流动性覆盖率不得低于 100%；(4)净稳定资金率不得低于 100%。故本题选 B 选项。"},{"id":"jun-law1-29","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券行业诚信准则》，下列选项中，属于证券公司及其工作人员应当遵守的勤勉尽责要求的是","options":["自觉学习了解并遵守相关法律法规、监管规定、自律规则、业务规范和内部规章制度","尊重同行，公平竞争，禁止商业贿赂，自觉维护市场竞争秩序，坚决反对不正当竞争的行为、对自己的专业能力有充分认识，不承诺力不能及或不能如期完成的业务，不推诿应承担的责任",""],"answer":"C","explain":"A 选项错误，属于合法合规的要求。B 选项错误，属于公平竞争的要求。C 选项正确，属于勤勉尽责的要求。D 选项错误，属于言行一致的要求。故本题选 C 选项。【乐知识】机构及其工作人员应当自觉遵守以下勤勉尽责要求:(1)恪守职业操守，忠实勤勉，履行对投资者及其他利益相关方的责任和义务;(2)持续学习，不断提升专业能力，保证服务质量;(3)专业审慎，尽到合理专业的注意义务，履职尽责;(4)对自己的专业能力有充分认识，不承诺力不能及或不能如期完成的业务，不推诿应承担的责任;(5)实事求是，独立、审慎、客观、公正开展业务，不受其他单位和个人的非法干预和影响;(6)按规定做好相关工作底稿档案的记录、归集和保存管理。"},{"id":"jun-law1-30","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券市场资信评级业务管理办法》，证券评级机构评级委员会委员及评级从业人员在开展证券评级业务期间，下列关于证券资信评级业务人员的回避情形，错误的是()","options":["本人、直系亲属持有受评级机构或者受评级证券发行人的股份达到 5%以上","本人、直系亲属为受评级机构或者受评级证券发行人的普通员工","本人、直系亲属持有受评级证券或者受评级机构发行的证券金额超过50 万元","本人、直系亲属担任受评级机构或者受评级证券发行人聘任的会计师事务所、律师事务所、财务顾问等证券服务机构的负责人或者项目签字人"],"answer":"B","explain":"证券评级机构应当建立回避制度。证券评级机构评级委员会委员及评级从业人员在开展证券评级业务期间有下列情形之一的，应当回避:(1)本人、直系亲属持有评级委托方、受评级机构或者受评级证券发行人的股份达到 5%以上，或者是受评级机构、受评级证券发行人的实际控制人(A 选项正确)(2)本人、直系亲属担任评级委托方、受评级机构或者受评级证券发行人的董事、监事和高级管理人员;(3)本人、直系亲属担任评级委托方、受评级机构或者受评级证券发行人聘任的会计师事务所、律师事务所、财务顾问等证券服务机构的负责人或者项目签字人(D 选项正确);(4)本人、直系亲属持有评级委托方、受评级证券或者受评级机构发行的证券金额超过 50 万元，或者与评级委托方、受评级机构、受评级证券发行人发生累计超过 50 万元的交易(C 选项正确);(5)中国证监会认定的足以影响独立、客观、公正、审慎性原则的其他情形。B 选项错误，不包括普通员工。"},{"id":"jun-law1-31","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司声誉风险管理指引 I》，下列不属于声誉风险管理应遵循的原则是()","options":["从高层做起原则","预防第一原则","审慎管理原则","快速响应原则"],"answer":"A","explain":"声誉风险管理应遵循全程全员原则、预防第一原则(B 选项不符合题意)、审慎管理原则(C 选项不符合题。意)、快速响应原则(D 选项不符合题意)0 故本题选 A选项。"},{"id":"jun-law1-32","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，证券公司合规管理基本制度应当经()审议通过后实施。","options":["股东会","董事会","风险控制委员会","经营管理层"],"answer":"B","explain":"证券公司应当制定合规管理的基本制度，经董事会审议通过后实施(B 选项正确)。合规管理的基本制度应当明确合规管理的目标、基本原则、机构设置及其职责、履职保障、合规考核、违法违规行为及合规风险隐患的报告、处理和责任追究等内容。"},{"id":"jun-law1-33","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券法》，证券的发行、交易活动，必须遵循的原则不包括()。","options":["公开","公正","公平","公允"],"answer":"D","explain":"证券的发行、交易活动，必须遵循公开(A 选项不符合题意)、公平(C 选项不符合题意)、公正(B 选项不符合题意)\"三公\"原则。故本题选 D 选项。"},{"id":"jun-law1-34","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券法》，证券承销业务的种类不包括() 。","options":["自行销售","代销","全额包销","余额包销"],"answer":"A","explain":"A 选项符合题意，证券承销业务采取代销或者包销方式(B 选项不符合题意)，其中包销分为全额包销和余额包销 (C、D 选项不符合题意)。故本题选 A 选项。"},{"id":"jun-law1-35","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《上海证券交易所科创板股票交易特别规定》，关于投资者参与科创板股票交易需满足的适当性条件，下列说法正确的是 () 。","options":["机构投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币 50 万元，或者参与证券交易 24 个月以上","机构投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币 50 万元，并且参与证券交易 24 个月以上","个人投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币 50 万元 (不包括该投资者通过融资融券融入的资金和证券)，或者参与证券交易 24 个月以上","个人投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币 50 万元 (不包括该投资者通过融资融券融入的资金和证券)，并且参与证券交易 24 个月以上"],"answer":"D","explain":"投资者参与科创板股票交易的具体条件：(1)个人投资者 (而非机构投资者)申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币 50 万元 (不包括该投资者通过融资融券融入的资金和证券)，并且 (而非或者)参与证券交易 24 个月以上(A、B、C 选项错误, D选项正确)。(2)符合法律法规及上交所规定的机构投资者，可直接申请开通科创板股票交易权限。(3)投资者仅需向其委托的证券公司申请，在已有沪市 A 股证券账户上开通科创板股票交易权限即可，无须在中国结算开立新的证券账户。故本题选 D 选项。"},{"id":"jun-law1-36","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《公司法》，关于有限责任公司股东会职权的说法，错误的是 ()。","options":["对发行公司债券作出决议","制定公司的基本管理制度","审议批准公司的利润分配方案和弥补亏损方案","审议批准董事会的报告"],"answer":"B","explain":"有限责任公司股东会由全体股东组成。股东会是公司的权力机构，依法行使职权。股东会行使下列法定职权：(1)对发行公司债券作出决议 (A 选项正确)；(2)审议批准公司的利润分配方案和弥补亏损方案 (C 选项正确)；(3)审议批准董事会的报告 (D 选项正确)。B 选项错误，制定公司的基本管理制度属于董事会的职责。故本题选 B 选项。【乐补充】股东会行使的法定职权还包括：(1)选举和更换董事、监事，决定有关董事、监事的报酬事项；(2)审议批准监事会的报告；(3)对公司增加或者减少注册资本作出决议；(4)对公司合并、分立、解散、清算或者变更公司形式作出决议；(5)修改公司章程；(6)公司章程规定的其他职权。"},{"id":"jun-law1-37","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《反洗钱法》规定，反洗钱不包括 () 。","options":["合同违反","恐怖活动","贪污贿赂","金融诈骗"],"answer":"A","explain":"A 选项符合题意，合同违反属于一般的民事违约行为或行政违法行为，不属于《反洗钱法》列举的严重刑事犯罪范畴，因此，反洗钱工作不直接针对\"合同违反\"行为。反洗钱是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪 (B 选项不符合题意)、走私犯罪、贪污贿赂犯罪 (C 选项不符合题意)、破坏金融管理秩序犯罪、金融诈骗犯罪 (D 选项不符合题意)和其他犯罪所得及其收益的来源和性质的洗钱活动，遏制相关违法犯罪活动，依照《反洗钱法》等法律法规采取相关措施的行为。故本题选 A 选项。"},{"id":"jun-law1-38","subject":"law","source":"6月押题 LC","type":"单选","q":"法律主体是法律关系的参加者，主要包括 ()。","options":["权利、行为和义务","物、人格和精神成果","自然人、组织和国家","主体、客体和内容"],"answer":"C","explain":"C 选项正确，法律主体是法律关系的参加者，主要包括自然人、组织和国家三类。故本题选 C 选项。【乐知识】法律关系由主体、客体与内容三个要素构成。(1)法律主体是法律关系的参加者，主要包括自然人、组织和国家三类。权利能力和行为能力是成为法律关系主体的必备资格。(2)法律关系客体包括：物、人身及人格、精神成果和行为。(3)法律关系的内容是指法律关系中的权利和义务。"},{"id":"jun-law1-39","subject":"law","source":"6月押题 LC","type":"单选","q":"按照《证券公司风险控制指标计算标准规定》，证券公司自营权益类证券及其衍生品的合计额不得超过净资本的 ()。","options":["100%","500%","50%","80%"],"answer":"A","explain":"A 选项正确，根据《证券公司风险控制指标计算标准规定》，证券公司经营自营业务，其持仓规模必须符合规定：自营权益类证券及其衍生品的合计额不得超过净资本的 100%。故本题选 A 选项。"},{"id":"jun-law1-40","subject":"law","source":"6月押题 LC","type":"多选","q":"流动性风险，是指证券公司无法以合理成本及时获得充足资金，以()的资金需求的风险。","options":["进行套期保值","履行其他支付义务","满足正常业务开展","偿付到期债务"],"answer":"BCD","explain":"A 选项错误，套期保值，是指交易者为管理因其资产、负债等价值变化产生的风险而达成与上述资产、负债等基本吻合的期货交易和衍生品交易的活动。是证券公司管理市场风险的一种手段或业务活动，其本身不是流动性风险的直接成因或目的。流动性风险，是指证券公司无法以合理成本及时获得充足资金，以偿付到期债务(D 选项正确)、履行其他支付义务 (B 选项正确)和满足正常业务开展 (C选项正确)的资金需求的风险。故本题选 BCD 选项。"},{"id":"jun-law1-41","subject":"law","source":"6月押题 LC","type":"多选","q":"下列属于受法律规范调整的社会关系的有 ()。","options":["恋爱关系","朋友关系","代理关系","继承关系"],"answer":"CD","explain":"并不是所有的社会关系均受到法律规范的调整，有些社会关系，如恋爱关系 (A选项不符合题意)、朋友关系(B 选项不符合题意)或社会团体内部成员之间的关系，一般不存在相应的法律规定，不受法律规范的调整，因此，不产生法律关系，也不存在合法或非法的评价。故本题选 CD 选项。"},{"id":"jun-law1-42","subject":"law","source":"6月押题 LC","type":"多选","q":"下列属于证券公司开展自营业务应遵循的法律法规、自律规则的有 ()。","options":["《证券公司监督管理条例》","《公司债券承销业务规范》","《证券公司证券自营业务指引》","《上海证券交易所债券交易实施细则》"],"answer":"AC","explain":"证券公司开展自营业务应遵循的法律法规、自律规则的有关规定主要包括《证券公司监督管理条例》 (A 选项正确)、《证券公司业务范围审批暂行规定》、《证券公司内部控制指引》以及《证券公司证券自营业务指引》(C 选项正确)等。B 选项错误，《公司债券承销业务规范》是规范证券公司投资银行业务的自律规则，与证券自营业务的监管要求无关。D 选项错误，《上海证券交易所债券交易实施细则》是上海证券交易所制定的，规范在该交易所内进行债券交易的具体细则，并非专门针对“证券公司自营业务”的监管法规或自律规则。故本题选 AC 选项。"},{"id":"jun-law1-43","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《金融机构洗钱和恐怖融资风险评估及客户分类管理指引》，下列关于证券公司开展洗钱风险评估及客户分类管理的说法，错误的有 ()。","options":["证券公司应对客户参与不同的业务进行不同的风险等级划分，同一客户在证券公司不应有唯一的风险等级","对高风险客户应采取强化的客户尽职调查及其他风险控制措施","对于首次建立业务关系的客户，无论风险等级高低，证券公司在初次确定其风险等级后的三年内至少应进行一次复核","对于已确立过风险等级的客户，证券公司不得再根据其风险程度设置相应的重新审核期限"],"answer":"AD","explain":"A 选项错误，对于新建立业务关系的客户，证券公司应在建立业务关系后的 10个工作日内，按照收集信息、筛选分析信息、初评和复评的流程，划分其风险等级，同一客户在证券公司应有唯一的风险等级。B 选项正确，证券公司应在客户风险等级划分的基础上，采取相应的客户尽职调查及其他风险管控措施。对于风险等级较高的客户，证券公司应当根据风险情形采取相匹配的一种或者多种强化尽职调查措施。C 选项正确、D 选项错误，对于已确立过风险等级的客户，证券公司应根据其风险程度设置相应的重新审核期限，实现对风险的动态追踪。原则上，风险等级最高的客户的审核期限不得超过半年，低一等级客户的审核期限不得超出上一级客户审核期限时长的两倍。对于首次建立业务关系的客户，无论其风险等级高低，证券公司在初次确定其风险等级后的 3 年内至少应进行一次复核。故本题选 AD 选项。"},{"id":"jun-law1-44","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券法》，下列关于证券交易所交易规则的说法，正确的有 () 。","options":["证券交易所不得允许非会员直接参与股票的集中交易","证券交易即时行情的权益由证券交易所依法享有，未经证券交易所许可，任何单位和个人不得发布证券交易即时行情","证券交易所根据需要，可以按照业务规则对出现重大异常交易情况的证券账户的投资者限制交易，并报国务院备案","进入实行会员制的证券交易所参与集中交易的，必须是证券交易所的会员"],"answer":"ABD","explain":"A、D 选项正确，进入实行会员制的证券交易所参与集中交易的，必须是证券交易所的会员。证券交易所不得允许非会员直接参与股票的集中交易。B 选项正确，证券交易即时行情的权益由证券交易所依法享有。未经证券交易所许可，任何单位和个人不得发布证券交易即时行情。C 选项错误，证券交易所对证券交易实行实时监控，并按照国务院证券监督管理机构的要求，对异常的交易情况提出报告。证券交易所根据需要，可以按照业务规则对出现重大异常交易情况的证券账户的投资者限制交易，并及时报告国务院证券监督管理机构 (并非国务院)。故本题选 ABD 选项。"},{"id":"jun-law1-45","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，下列关于证券公司合规风险的说法，正确的有() 。","options":["证券公司违反法律法规规定，出现商业信誉损失的风险属于合规风险","市场利率上行导致持仓债券价格下跌属于合规风险","证券公司违反法律法规规定，被采取监管措施属于合规风险","证券公司违反法律法规规定，出现财产损失属于合规风险"],"answer":"ACD","explain":"证券公司的合规风险，是指因证券公司或其工作人员的经营管理或执业行为违反法律法规和准则而使证券公司被依法追究法律责任、采取监管措施 (C 选项正确)、给予纪律处分、出现财产损失 (D 选项正确)或商业信誉损失 (A 选项正确)的风险。B 选项错误，属于市场风险。故本题选 ACD 选项。"},{"id":"jun-law1-46","subject":"law","source":"6月押题 LC","type":"多选","q":"下列属于从事证券投资咨询业务的投资咨询人员的有 ()。","options":["证券经纪人","证券分析师","证券交易员","证券投资顾问人员"],"answer":"BD","explain":"证券投资咨询人员主要包括证券投资顾问人员 (D 选项符合题意)及证券分析师(B 选项符合题意)两类。故本题选 BD 选项。"},{"id":"jun-law1-47","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于有限合伙企业解散事由的说法，错误的有() 。","options":["合伙期限届满，合伙人决定不再经营，应当解散","部分合伙人决定解散，应当解散","合伙协议约定的解散事由出现，应当解散","合伙人不具备法定人数，应当立即解散"],"answer":"BD","explain":"合伙企业有下列情形之一的，应当解散：(1)合伙期限届满，合伙人决定不再经营 (A 选项正确)；(2)合伙协议约定的解散事由出现 (C 选项正确)；(3)全体合伙人决定解散 (B 选项错误，并非“部分”)；(4)合伙人已不具备法定人数满 30 天 (D 选项错误，并非“立即”)；(5)合伙协议约定的合伙目的已经实现或者无法实现；(6)依法被吊销营业执照、责令关闭或者被撤销；(7)法律、行政法规规定的其他原因。故本题选 BD 选项。"},{"id":"jun-law1-48","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于证券投资顾问与发布证券研究报告基本关系的说法，错误的有 ()。","options":["立场相同","服务方式和内容相同","服务对象有所不同","市场影响有所不同"],"answer":"AB","explain":"证券投资顾问业务和发布证券研究报告的区别：(1)立场不同 (A 选项错误)；(2)服务方式和内容不同 (B 选项错误)；(3)服务对象有所不同 (C 选项正确)；(4)市场影响有所不同 (D 选项正确)。故本题选 AB 选项。"},{"id":"jun-law1-49","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于非公开募集基金的募集与宣传推介的说法，正确的有 ()。","options":["不得通过讲座、报告会、分析会等方式向其现有投资者宣传推介","不得通过报刊、电台、电视台等公众传播媒体向不特定对象宣传推介","不得在互联网上向不特定对象宣传推介","不得向合格投资者之外的单位和个人募集资金"],"answer":"BCD","explain":"A 选项错误，现有投资者属于合格投资者，可以通过讲座、报告会、分析会等方式向其宣传推介。B、C 选项正确，私募基金应非公开募集，不得通过报刊、电台、电视台、互联网等大众传播媒介，电话、短信、即时通信工具、电子邮件、传单，或者讲座、报告会、分析会等方式向不特定对象宣传推介。D 选项正确，非公开募集基金不得向合格投资者之外的单位和个人募集资金。故本题选 BCD 选项。【乐补充】私募基金还不得以虚假、片面、夸大等方式宣传推介；不得以私募基金托管人名义宣传推介；不得向投资者承诺投资本金不受损失或者承诺最低收益。私募基金管理人应当自行募集资金，不得委托他人募集资金，但国务院证券监督管理机构另有规定的除外。"},{"id":"jun-law1-50","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司全面风险管理规范》，证券公司应要求并确保子公司在整体风险偏好和风险管理制度框架下，建立健全自身的 ()，保障全面风险管理的一致性和有效性。","options":["风险管理组织架构","风控指标体系","信息技术系统","制度流程"],"answer":"ABCD","explain":"证券公司应当依法依规通过公司治理程序将所有子公司(被证券公司控制)纳入全面风险管理体系，要求并确保子公司在整体风险偏好和风险管理制度框架下，建立健全自身的风险管理组织架构 (A 选项正确)、制度流程 (D 选项正确)、信息技术系统 (C 选项正确)和风控指标体系 (B 选项正确)，保障全面风险管理的一致性和有效性。故本题选 ABCD 选项。"},{"id":"jun-law1-51","subject":"law","source":"6月押题 LC","type":"多选","q":"关于证券金融公司开展转融通业务的证券来源，说法正确的有 ()。","options":["证券金融公司通过证券交易所的业务平台融入的证券","证券金融公司直接使用证券公司客户的证券","证券金融公司通过转融通担保证券账户持有的证券","证券金融公司自有证券"],"answer":"AD","explain":"证券金融公司开展转融通业务，可以使用下列资金和证券：(1)自有资金和证券 (D 选项正确)；(2)通过证券交易所的业务平台融入的资金和证券 (A 选项正确)；(3)通过证券金融公司的业务平台融入的资金；(4)依法筹集的其他资金和证券。B 选项错误，证券金融公司直接使用证券公司客户的证券是严格禁止行为。C 选项错误，证券金融公司通过转融通担保证券账户持有的证券不计入其自有证券。故本题选 AD 选项。"},{"id":"jun-law1-52","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于公司对外担保的说法，符合我国《公司法》要求的有 ()。","options":["除法律另有规定外，公司向其他企业投资时，不得成为对所投资企业的债务承担连带责任的出资人","公司向其他企业投资或者为他人提供担保，必须经股东会决议","公司不能为公司股东和实际控制人提供担保","公司章程可以对担保的总额作出规定"],"answer":"AD","explain":"A 选项正确，公司可以向其他企业投资，但是，除法律另有规定外，不得成为对所投资企业的债务承担连带责任的出资人。B 选项错误，公司向其他企业投资或者为他人提供担保，按照公司章程的规定，由董事会或者股东会决议。C 选项错误，公司为公司股东或者实际控制人提供担保的，应当经股东会决议。D 选项正确，公司章程对投资或者担保的总额及单项投资或者担保的数额有限额规定的，不得超过规定的限额。故本题选 AD 选项。"},{"id":"jun-law1-53","subject":"law","source":"6月押题 LC","type":"多选","q":"不得担任财务顾问主办人的条件包括 () 。","options":["最近 24 个月内有违反诚信的不良记录","最近 36 个月因执业行为违法违规受到处罚","最近 24 个月因执业行为违反行业规范而受到行业自律组织的纪律处分","有大额贷款，到期未清偿"],"answer":"ABCD","explain":"财务顾问主办人应当具备下列条件：(1)具备中国证监会规定的投资银行业务经历；(2)具备从事相关业务的专业能力；(3)所任职机构同意推荐其担任本机构的财务顾问主办人；(4)未负有数额较大到期未清偿的债务 (D 选项符合题意)；(5)最近 24 个月无违反诚信的不良记录 (A 选项符合题意)；(6)最近 24 个月未因执业行为违反行业规范而受到行业自律组织的纪律处分 (C选项符合题意)；(7)最近 36 个月未因执业行为违法违规受到处罚 (B 选项符合题意)；(8)中国证监会规定的其他条件。故本题选 ABCD 选项。"},{"id":"jun-law1-54","subject":"law","source":"6月押题 LC","type":"多选","q":"下列规章及规范性文件涉及上市公司收购以及上市公司重大资产重组的有()。","options":["《科创板上市公司重大资产重组特别规定》","《上市公司并购重组财务顾问业务管理办法》","《证券投资顾问业务暂行规定》","《上市公司重大资产重组管理办法》"],"answer":"ABD","explain":"C 选项错误，是与证券投资咨询业务相关的法律法规、自律规则。故本题选 ABD 选项。"},{"id":"jun-law1-55","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券法》，下列关于证券公司承销证券的说法，正确的有 ()。","options":["证券公司承销证券，发现公开发行募集文件有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动","证券公司承销证券，不得进行虚假的或者误导投资者的广告宣传","证券公司承销证券，发现公开发行募集文件有虚假记载、误导性陈述或者重大遗漏，已经销售的，必须立即停止销售活动，并采取纠正措施","证券公司承销证券，不得以不正当竞争手段招揽承销业务"],"answer":"ABCD","explain":"证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查。发现有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动 (A 选项正确)；已经销售的，必须立即停止销售活动，并采取纠正措施 (C 选项正确)。证券公司承销证券，不得有下列行为：(1)进行虚假的或者误导投资者的广告宣传或者其他宣传推介活动 (B 选项正确)；(2)以不正当竞争手段招揽承销业务 (D 选项正确)；(3)其他违反证券承销业务规定的行为。故本题选 ABCD 选项。"},{"id":"jun-law1-56","subject":"law","source":"6月押题 LC","type":"多选","q":"关于证券公司风险控制指标标准，下列表述正确的是 ()。","options":["风险覆盖率不低于 100%","流动性覆盖率不低于 100%","净稳定资金率不低于 100%","资本杠杆率不低于 100%"],"answer":"ABC","explain":"证券公司必须持续符合下列风险控制指标标准：(1)风险覆盖率不得低于 100%(A 选项正确)；(2)资本杠杆率不得低于 8%(D 选项错误，并非\"100%\")；(3)流动性覆盖率不得低于 100%(B 选项正确)；(4)净稳定资金率不得低于 100%(C 选项正确)。故本题选 ABC 选项。"},{"id":"jun-law1-57","subject":"law","source":"6月押题 LC","type":"多选","q":"甲证券公司不得为 ()开立信用业务账户。","options":["未按照要求提供有关情况的张某","从事证券交易时间不足半年，缺乏风险承担能力的李某","最近 20 个交易日日均证券类资产低于 50 万元或者有重大违约记录的王某","最近 20 个交易日日均证券类资产高于 50 万元的赵某"],"answer":"ABC","explain":"证券公司不得为客户开立信用业务账户的情形：(1)未按照要求提供有关情况 (A 选项正确)。(2)从事证券交易时间不足半年，缺乏风险承担能力(B 选项正确)。(3)最近20个交易日日均证券类资产低于50万元或者有重大违约记录的客户 (C选项正确、D 选项错误)。(4)本公司的股东 (不包括仅持有上市证券公司 5%以下流通股份的股东)、关联人。故本题选 ABC 选项。"},{"id":"jun-law1-58","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于股份有限公司监事会的表述正确的有() 。","options":["监事会设主席一人，并应当设副主席","监事会主席由全体监事过半数选举产生","董事、高级管理人员不得兼任监事","监事会成员不得少于三人"],"answer":"BCD","explain":"股份有限公司设监事会， 《公司法》第一百二十一条第一款、第一百三十三条另有规定的除外。A 选项错误，监事会设主席 1 人，可以设副主席 (并非\"应当\")。B 选项正确，监事会主席和副主席由全体监事过半数选举产生。C 选项正确，董事、高级管理人员不得兼任监事。D 选项正确，监事会成员为 3 人以上。故本题选 BCD 选项。【乐知识】监事会成员应当包括股东代表和适当比例的公司职工代表，其中职工代表的比例不得低于 1/3，具体比例由公司章程规定。监事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生。"},{"id":"jun-law1-59","subject":"law","source":"6月押题 LC","type":"多选","q":"普通投资者应至少在 ()享有特别保护。","options":["信息告知","风险警示","适当性匹配","保证本金"],"answer":"ABC","explain":"根据《证券期货投资者适当性管理办法》的规定，投资者分为普通投资者与专业投资者。普通投资者在信息告知 (A 选项正确)、风险警示 (B 选项正确)、适当性匹配 (C 选项正确)等方面享有特别保护。D 选项错误，\"保证本金\"属于禁止行为。故本题选 ABC 选项。"},{"id":"jun-law1-60","subject":"law","source":"6月押题 LC","type":"多选","q":"不具备证券自营业务资格的证券公司，其自有资金能够从事 ()。","options":["不以对冲风险为目的的金融衍生产品交易","以对冲风险为目的的金融衍生产品交易","以套期保值为目的的股票期权交易","公开发行并上市的股票交易"],"answer":"BC","explain":"A 选项错误、B 选项正确，具备证券自营业务资格的证券公司可以从事金融衍生产品交易，不具备证券自营业务资格的证券公司只能以对冲风险为目的，从事金融衍生产品交易。C 选项正确、D 选项错误，证券公司以自有资金参与股票期权交易试点的，应当具备证券自营业务资格。不具备证券自营业务资格的证券公司，其自有资金只能以套期保值为目的，参与股票期权交易。故本题选 BC 选项。"},{"id":"jun-law1-61","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《私募投资基金监督管理暂行办法》，私募基金管理人不得实施的行为有 () 。","options":["从事损害基金财产的投资活动","公平地对待其管理的基金财产","玩忽职守，不按规定履行职责","挪用基金财产"],"answer":"ACD","explain":"私募基金管理人及其从业人员从事私募基金业务，不得有以下行为：(1)将其固有财产或者他人财产混同于基金财产从事投资活动；(2)不公平地对待其管理的不同基金财产；(3)利用基金财产或者职务之便，为本人或者投资者以外的人牟取利益，进行利益输送；(4)侵占、挪用基金财产 (D 选项正确)；(5)泄露因职务便利获取的未公开信息，利用该信息从事或者明示、暗示他人从事相关的交易活动；(6)从事损害基金财产和投资者利益的投资活动 (A 选项正确)；(7)玩忽职守，不按照规定履行职责 (C 选项正确)；(8)从事内幕交易、操纵交易价格及其他不正当交易活动。故本题选 ACD 选项。"},{"id":"jun-law1-62","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司信用风险管理指引》，下列关于证券公司信用风险管理的说法，正确的有 ()。","options":["证券公司相关业务部门是信用风险管理的一线主体","证券公司董事会应承担信用风险管理的监督责任","证券公司应建立有效的信用风险管理组织架构","证券公司应建立健全有效的考核及问责机制"],"answer":"ACD","explain":"B 选项错误，证券公司监事会 (或行使监事会职权的监事或董事会设置的由董事组成的审计委员会)承担全面风险管理的监督责任。因此，监事会承担信用风险管理的监督责任。故本题选 ACD 选项。"},{"id":"jun-law1-63","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券法》，证券发行交易活动的当事人应当遵守的原则包括 ()。","options":["诚实信用","自愿","有偿","稳健"],"answer":"ABC","explain":"证券发行、交易活动的当事人具有平等的法律地位，应当遵守自愿 (B 选项符合题意)、有偿 (C 选项符合题意)、诚实信用 (A 选项符合题意)的原则。D 选项不符合题意，不包括稳健。故本题选 ABC 选项。"},{"id":"jun-law1-64","subject":"law","source":"6月押题 LC","type":"多选","q":"证券公司融资融券的业务决策机构主要负责 ()。","options":["保证金收取和交易执行等业务操作","确定对单一客户和单一证券的授信额度","决定与融资融券业务有关的部门设置","确定融资融券的期限和利率费率"],"answer":"BD","explain":"业务决策机构由有关高级管理人员及部门负责人组成，负责制定融资融券业务操作流程，选择可从事融资融券业务的分支机构，确定对单一客户和单一证券的授信额度 (B 选项正确)、融资融券的期限和利率 (费率)(D 选项正确)、保证金比例和最低维持担保比例、可充抵保证金的证券种类及折算率、客户可融资买入和融券卖出的证券种类。A 选项错误，分支机构在公司总部的集中监控下，按照公司的统一规定和决定，具体负责客户征信、签约、开户、保证金收取和交易执行等业务操作。C 选项错误，董事会负责制定融资融券业务的基本管理制度，决定与融资融券业务有关的部门设置及各部门职责，确定融资融券业务的总规模。故本题选 BD 选项。"},{"id":"jun-law1-65","subject":"law","source":"6月押题 LC","type":"多选","q":"下列属于期货交易制度的有 ()。","options":["账户实名制","当日无负债结算制度","保证金制度","持仓限额制度"],"answer":"ABCD","explain":"期货交易的基本制度包括：(1)账户实名制 (A 选项符合题意)；(2)保证金制度 (C 选项符合题意)；(3)持仓限额制度 (D 选项符合题意)；(4)实际控制关系报备制度；(5)程序化交易报备制度。期货交易实行当日无负债结算制度 (B 选项符合题意)。"},{"id":"jun-law1-66","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《刑法》，下列关于违规披露、不披露重要信息罪构成要件的说法，正确的有 () 。","options":["本罪侵犯的客体是国家有关公司、企业的财会报告及其他重要信息的管理秩序和股东、社会公众和其他利害关系人的合法权益","本罪在客观方面表现为向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告等，严重损害股东或者其他人利益的行为","本罪主观方面既可以是故意，也可以是过失","本罪的主体是特殊主体，即依法负有信息披露义务的公司、企业及相关责任人员"],"answer":"ABD","explain":"A 选项正确，本罪侵犯的客体是国家有关公司、企业的财会报告及其他重要信息的管理秩序和股东、社会公众和其他利害关系人的合法权益。B 选项正确，本罪在客观方面表现为向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告等，严重损害股东或者其他人利益的行为。C 选项错误，本罪犯罪主观方面只能由故意构成，过失不构成本罪。D 选项正确，本罪的犯罪主体为特殊主体，即依法负有信息披露义务的公司、企业及相关责任人员。故本题选 ABD 选项。"},{"id":"jun-law1-67","subject":"law","source":"6月押题 LC","type":"多选","q":"股份有限公司董事，监事，高级管理人员持有本公司股票转让方式正确的有() 。","options":["在任职期间每年转让的股份不得超过其所持有本公司股份总数的 25%","在离职后一年内不得转让","上市交易之日起一年内不得转让","上市交易之日起半年内不得转让"],"answer":"AC","explain":"公司董事、监事、高级管理人员应当向公司申报所持有的本公司的股份及其变动情况，在就任时确定的任职期间每年转让的股份不得超过其所持有本公司股份总数的 25%(A 选项正确)；所持本公司股份自公司股票上市交易之日起 1 年内不得转让 (C 选项正确、D 选项错误)。上述人员离职后半年内，不得转让其所持有的本公司股份 (B 选项错误)。故本题选 AC 选项。"},{"id":"jun-law1-68","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司经营数据和客户信息保护的说法正确的有 ()。","options":["证券公司应当记录经营数据和客户信息的使用情况，并持续监督信息技术服务机构等相关方落实保密协议的情况","证券公司发现信息技术服务机构等相关方违规存储或者使用自身经营数据和客户信息的，应当责令其立即改正并销毁已获取的经营数据和客户信息","信息技术服务机构等相关方拒绝配合整改的，证券公司应当立即停止与其合作，并采取措施维护自身及客户的合法权益","证券公司在收集使用客户信息之前，可以不用公开收集、使用的规则和目的，但应当征得客户同意"],"answer":"ABC","explain":"D 选项错误，在收集使用客户信息之前，证券公司应当公开收集、使用的规则和目的 (并非\"可以不用\")，并征得客户同意。故本题选 ABC 选项。"},{"id":"jun-law1-69","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券投资基金法》，下列关于基金管理人、基金托管人及其董事、监事、高级管理人员和其他从业人员不公平地对待其管理的不同基金财产的法律责任，正确的有()。","options":["没有违法所得或者违法所得不足一百万元的，并处五十万元以上一百万元以下罚款","责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款","责令改正，没收违法所得，并处违法所得一倍以上三倍以下罚款","没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款"],"answer":"BD","explain":"根据《证券投资基金法》第二十条及第一百二十三条的规定，基金管理人、基金托管人及其董事、监事、高级管理人员和其他从业人员不公平地对待其管理的不同基金财产的，责令改正，没收违法所得，并处违法所得 1 倍以上 5 倍以下罚款(B 选项正确、C 选项错误)；没有违法所得或者违法所得不足 100 万元的，并处10 万元以上 100 万元以下罚款 (A 选项错误、D 选项正确)；基金管理人、基金托管人有上述行为的，还应当对其直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金从业资格，并处 3 万元以上 30 万元以下罚款。故本题选 BD 选项。"},{"id":"jun-law1-70","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于证券公司对敏感信息采取保密措施的说法，正确的有 () 。","options":["与证券公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密","对可能知悉敏感信息的工作人员使用的公司及个人各类信息系统或设备形成的电子邮件、即时通信信息和其他通讯信息进行监测","建立内幕信息知情人管理制度","加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全"],"answer":"ACD","explain":"(1)与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密 (A 选项正确)；(2)加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全 (D 选项正确)；(3)对可能知悉敏感信息的工作人员使用公司 (并不包括个人)的信息系统或配发的设备形成的电子邮件、即时通信信息和其他通信信息进行监测 (B 选项错误)；(4)建立内幕信息知情人管理制度 (C 选项正确)。故本题选 ACD 选项。"},{"id":"jun-law1-71","subject":"law","source":"6月押题 LC","type":"多选","q":"证券公司承销证券，同发行人签订的证券代销协议必备的条款包括 ()。","options":["代销证券的发行价格","代销的期限及起止日期","代销证券的种类、数量","代销证券的金额"],"answer":"ABCD","explain":"证券公司承销证券，应当同发行人签订代销或者包销协议，载明下列事项：(1)当事人的名称、住所及法定代表人姓名。(2)代销、包销证券的种类、数量、金额及发行价格 (A、C、D 选项正确)。(3)代销、包销的期限及起止日期 (B 选项正确)。(4)代销、包销的付款方式及日期。(5)代销、包销的费用和结算办法。(6)违约责任。(7)国务院证券监督管理机构规定的其他事项。故本题选 ABCD 选项。"},{"id":"jun-law1-72","subject":"law","source":"6月押题 LC","type":"多选","q":"某证券公司的下列实践中，能够反映证券行业文化建设基本要求中\"牢记社会责任，展现良好形象\"的有() 。","options":["将对口帮扶地区的农副产品引入工会慰问品采购名单并鼓励会员优先选","多措并举增加注册资本并积极推动上市","建立各业务条线负责人必须出席的定期合规展业交流机制","积极参与证券行业支持民营企业发展系列资管计划 (纾困基金)的设立"],"answer":"AD","explain":"牢记社会责任，展现良好形象。要求坚持义利兼顾，正道直行，发挥专业特长，加强经济形势分析研究，合力维护市场健康舆论生态，助力国家精准扶贫和乡村振兴，积极参与社会公益事业 (A、D 选项符合题意)，与经济社会共生共荣、融合发展。B 选项不符合题意，增加注册资本和推动上市属于证券公司自身资本运作和经营发展策略，核心目的是增强资本实力、拓展业务规模，属于商业行为范畴。该行为未直接体现\"社会责任\"或\"良好形象\"。C 选项不符合题意，合规展业交流机制属于公司内部治理和合规管理范畴，目的是确保业务开展符合法律法规要求，属于行业文化中\"坚持依法合规，筑牢发展基础\"的要求，而非社会责任。故本题选 AD 选项。"},{"id":"jun-law1-73","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司监督管理条例》，证券公司对客户负有诚信义务，不得侵犯客户的合法权益，具体包括() 。","options":["不得侵犯客户的财产权","不得侵犯客户的公平交易权","不得侵犯客户的知情权","不得侵犯客户的选择权"],"answer":"ABCD","explain":"证券公司对客户负有诚信义务，不得侵犯客户的财产权(A 选项符合题意)、选择权 (D 选项符合题意)、公平交易权 (B 选项符合题意)、知情权 (C 选项符合题意)及其他合法权益。故本题选 ABCD 选项。"},{"id":"jun-law1-74","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券发行与承销管理办法》证券发行与承销信息披露的有关规定，首次公开发行股票的发行人和主承销商应当在发行和承销过程中公开披露信息的具体内容包括 ()。","options":["招股意向书刊登首日在发行公告中披露包括发行定价方式、程序、股票配售原则等信息","在发行结果公告中披露获配投资者名称以及每个获配投资者的报价、申购数量等信息","网上申购前披露每位网下投资者的详细报价情况","采用询价方式且存在规定情形之一的，应当在网上申购前发布投资风险特别公告，详细说明定价合理性，提示投资者注意投资风险"],"answer":"ABCD","explain":"A 选项正确，招股意向书刊登首日，应当在发行公告中披露发行定价方式、定价程序、参与网下询价投资者条件、证券配售原则、配售方式、有效报价的确定方式、中止发行安排、发行时间安排和路演推介相关安排等信息。B 选项正确，在发行结果公告中披露获配投资者名称以及每个获配投资者的报价、申购数量和获配数量等，并明确说明自主配售的结果是否符合事先公布的配售原则。C 选项正确，网上申购前，应当披露每位网下投资者的详细报价情况，包括投资者名称、申购价格及对应的拟申购数量。D 选项正确，采用询价方式且存在规定情形之一的，应当在网上申购前发布投资风险特别公告，详细说明定价合理性，提示投资者注意投资风险。故本题选 ABCD 选项。"},{"id":"jun-law1-75","subject":"law","source":"6月押题 LC","type":"多选","q":"根据合伙人对合伙企业债务承担责任的不同，合伙企业可分为 ()。","options":["有限合伙企业","普通合伙企业","个人合伙企业","合资合伙企业"],"answer":"AB","explain":"根据合伙人对合伙企业债务承担责任的不同，合伙企业可分为普通合伙企业 (B选项正确)和有限合伙企业(A 选项正确)。故本题选 AB 选项。"},{"id":"jun-law1-76","subject":"law","source":"6月押题 LC","type":"多选","q":"下列属于风险控制指标体系的有 () 。","options":["净资本","净稳定资金率","资本杠杆率","风险覆盖率"],"answer":"ABCD","explain":"为了建立以净资本和流动性为核心的风险控制指标体系，加强证券公司风险监管，督促证券公司加强内部控制、提升风险管理水平、防范风险，证券公司应当计算净资本 (A 选项正确)、风险覆盖率 (D 选项正确)、资本杠杆率 (C 选项正确)、流动性覆盖率、净稳定资金率 (B 选项正确)等各项风险控制指标。故本题选 ABCD 选项。"},{"id":"jun-law1-77","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于封闭式基金与开放式基金区别的说法，正确的有 ()。","options":["基金合同期限不同","申购和赎回份额的限制不同","基金规模不同","基金份额交易方式不同"],"answer":"ABCD","explain":"二者的区别如下：(1)基金合同期限不同 (A 选项正确)；(2)申购和赎回份额的限制不同 (B 选项正确)；(3)基金规模不同 (C 选项正确)；(4)基金份额交易方式不同 (D 选项正确)；(5)流动性管理要求不同。故本题选 ABCD 选项。"},{"id":"jun-law1-78","subject":"law","source":"6月押题 LC","type":"多选","q":"证券投资咨询业务的基本形式包括 ()。","options":["证券投资顾问","委托理财","发布证券研究报告","销售基金"],"answer":"AC","explain":"证券投资顾问业务和发布证券研究报告是证券投资咨询业务的两种基本形式 (A、C 选项符合题意)。故本题选 AC 选项。"},{"id":"jun-law1-79","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券法》，下列属于可能对上市公司、股票在国务院批准的其他全国性证券交易场所交易的公司股票交易价格产生较大影响的重大事件的有 ()。","options":["公司的经营方针和经营范围的重大变化","公司发生亏损或者损失","公司的经理发生变动","实际控制人持有股份情况发生较大变化"],"answer":"ACD","explain":"重大事件包括：(1)公司的经营方针和经营范围的重大变化 (A 选项符合题意)；(2)公司发生重大亏损或者重大损失 (B 选项不符合题意，未强调重大)；(3)公司的董事、1/3 以上监事或者经理发生变动，董事长或者经理无法履行职责 (C 选项符合题意)；(4)持有公司 5%以上股份的股东或者实际控制人持有股份或者控制公司的情况发生较大变化，公司的实际控制人及其控制的其他企业从事与公司相同或者相似业务的情况发生较大变化 (D 选项符合题意)。故本题选 ACD 选项。【乐补充】重大事件还包括：(1)公司的重大投资行为，公司在一年内购买、出售重大资产超过公司资产总额30%，或者公司营业用主要资产的抵押、质押、出售或者报废一次超过该资产的30%;(2)公司订立重要合同、提供重大担保或者从事关联交易，可能对公司的资产、负债、权益和经营成果产生重要影响；(3)公司发生重大债务和未能清偿到期重大债务的违约情况；(4)公司生产经营的外部条件发生的重大变化；(5)公司分配股利、增资的计划，公司股权结构的重要变化，公司减资、合并、分立、解散及申请破产的决定，或依法进入破产程序、被责令关闭；(6)涉及公司的重大诉讼、仲裁，股东会、董事会决议被依法撤销或者宣告无效；(7)公司涉嫌犯罪被依法立案调查，公司的控股股东、实际控制人、董事、监事、高级管理人员涉嫌犯罪被依法采取强制措施；(8)国务院证券监督管理机构规定的其他事项。"},{"id":"jun-law1-80","subject":"law","source":"6月押题 LC","type":"判断","q":"《公司法》对有限责任公司的公司章程应当载明事项作出列举性规定，设立方式不属于其应当载明的事项之一。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。有限责任公司章程应当载明下列事项：(1)公司名称和住所；(2)公司经营范围；(3)公司注册资本；(4)股东的姓名或者名称；(5)股东的出资额、出资方式和出资日期；(6)公司的机构及其产生办法、职权、议事规则；(7)公司法定代表人产生、变更办法；(8)股东会会议认为需要规定的其他事项。股东应当在公司章程上签名或者盖章。"},{"id":"jun-law1-81","subject":"law","source":"6月押题 LC","type":"判断","q":"证券发行上市保荐业务中，保荐人出具有重大遗漏的保荐书，处罚措施中包括：责令改正，给予警告，没收业务收入，并处以业务收入 1 倍以上 10 倍以下罚款。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。保荐人出具有虚假记载、误导性陈述或者重大遗漏的保荐书，或者不履行其他法定职责的，责令改正，给予警告，没收业务收入，并处以业务收入 1 倍以上 10倍以下的罚款。"},{"id":"jun-law1-82","subject":"law","source":"6月押题 LC","type":"判断","q":"操纵证券、期货市场罪的客观方面包括在自己实际控制的账户之间进行大量证券交易，造成股票价格上升后卖出获利。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。操纵证券、期货市场罪，是指有下列情形，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：在自己实际控制的账户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的。操纵证券、期货市场罪的客观方面表现为利用其资金、信息等优势或者滥用职权操纵市场、制造市场假象，影响证券、期货交易价格或者证券、期货交易量，情节严重的行为。【乐知识】操纵证券、期货市场罪，是指有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：(1)单独或者合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买卖；(2)与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易；(3)在自己实际控制的账户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的；(4)不以成交为目的，频繁或者大量申报买入、卖出证券、期货合约并撤销申报；(5)利用虚假或者不确定的重大信息，诱导投资者进行证券、期货交易；(6)对证券、证券发行人、期货交易标的公开作出评价、预测或者投资建议，同时进行反向证券交易或者相关期货交易；(7)以其他方法操纵证券、期货市场的。"},{"id":"jun-law1-83","subject":"law","source":"6月押题 LC","type":"判断","q":"股票发行采用代销方式，代销期限届满， 向投资者出售的股票数量未达到拟公开发行股票数量 70%的，为发行失败。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。股票发行采用代销方式，代销期限届满，向投资者出售的股票数量未达到拟公开发行股票数量 70%的，为发行失败。发行人应当按照发行价并加算银行同期存款利息返还股票认购人。"},{"id":"jun-law1-84","subject":"law","source":"6月押题 LC","type":"判断","q":"按照《证券公司内部控制指引》的要求，证券公司内部控制的组织结构要求设立严密有效的三道业务防线，其中， 第二道防线是建立重要一线岗位双人、双职、双责为基础的防线。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司应建立重要一线岗位双人、双职、双责为基础的\"第一道防线\"，并加强对单人单岗业务的监控。题干中的表述应为第一道防线，而非第二道防线。【乐知识】证券公司应建立清晰合理的组织结构，依据所处环境和自身经营特点设立严密有效的三道业务监控防线：(1)建立重要一线岗位双人、双职、双责为基础的\"第一道防线\"，并加强对单人单岗业务的监控。与资金、有价证券、重要空白凭证、业务合同、印章等直接接触的岗位和涉及信息系统安全的岗位，应当实行双人负责制。(2)建立相关部门、相关岗位之间相互制衡、监督的\"第二道防线\"。不同部门应有明确的职责分工不相容职务应适当分离。(3)建立独立的监督检查部门对各项业务、各部门、各分支机构、各岗位全面实施监控、检查和反馈的\"第三道防线\"。"},{"id":"jun-law1-85","subject":"law","source":"6月押题 LC","type":"判断","q":"中国证监会、国务院其他主管部门等其他省部级以上单位作出的表彰、奖励应当记入中国证监会建立的全国统一的证券期货市场诚信档案数据库。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。中国证监会、国务院其他主管部门等其他省部级及以上单位和证券期货交易场所、证券期货市场行业协会、证券登记结算机构等全国性证券期货市场行业组织作出的表彰、奖励、评比，以及信用评级机构、诚信评估机构作出的信用评级、诚信评估，记入诚信档案。"},{"id":"jun-law1-86","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券公司风险处置条例》，证券公司风险控制指标不符合有关规定，在规定期限内未能完成整改的，中国证券业协会可以责令证券公司停止部分或者全部业务进行整顿。停业整顿的期限不超过 3 个月。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司风险控制指标不符合有关规定，在规定期限内未能完成整改的，国务院证券监督管理机构 (而非中国证券业协会)可以责令证券公司停止部分或者全部业务进行整顿。停业整顿的期限不超过 3 个月。"},{"id":"jun-law1-87","subject":"law","source":"6月押题 LC","type":"判断","q":"规模失控是证券公司建立健全自营业务和受托资产管理业务内部控制制度时均应重点防范的风险。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司应加强自营业务投资决策、资金、账户、清算、交易和保密等的管理，重点防范规模失控、决策失误、超越授权、变相自营、账外自营、操纵市场、内幕交易等风险。证券公司在建立健全受托投资管理业务内部控制体制机制时，应重点防范规模失控、决策失误、越权操作、账外经营、挪用客户资产和其他损害客户利益的行为以及保本保底所导致的风险。"},{"id":"jun-law1-88","subject":"law","source":"6月押题 LC","type":"判断","q":"证券经营机构向普通投资者销售高风险产品或提供相关服务，且在营业网点向普通投资者进行告知、警示的，应当全过程录音或者录像。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券经营机构向普通投资者销售高风险产品或者提供相关服务，且在营业网点向普通投资者进行告知、警示的，应当全过程录音或录像。"},{"id":"jun-law1-89","subject":"law","source":"6月押题 LC","type":"判断","q":"公司以其全部财产对公司的债务承担责任。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。公司是企业法人，有独立的法人财产，享有法人财产权。公司以其全部财产对公司的债务承担责任。"},{"id":"jun-law1-90","subject":"law","source":"6月押题 LC","type":"判断","q":"证券公司应当建立健全投资者回访制度，为回访提供充分的人力与物质保障，不得委托第三方实施回访。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司应当建立健全投资者回访制度，持续了解投资者状况，及时发现并纠正不规范行为。证券公司应当为回访提供充分的人力和物质保障，保证必要的回访比例。证券公司可以委托第三方专业机构实施回访 (并非\"不得委托\")，但法律责任仍由证券公司承担。"},{"id":"jun-law1-91","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券投资基金法》，采用封闭式运作方式的基金，是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。封闭式基金是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金；开放式基金是指基金份额总额不固定，基金份额可以在基金合同约定的时间和场所申购或者赎回的基金。"},{"id":"jun-law1-92","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券公司董事、监事、高级管理人员及从业人员管理规则》，总公司董事、上海分公司投资顾问、营业厅经理，都属于证券从业人员。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。从业人员是指在证券基金经营机构从事证券基金业务和相关管理工作的人员，包括从事证券经纪、证券投资咨询、与证券交易及证券投资活动有关的财务顾问、证券承销与保荐、证券融资融券、证券自营、证券做市交易、证券资产管理等业务和相关管理工作的人员。证券公司董事长、从事业务管理工作的其他董事和监事、高级管理人员、分支机构负责人均为从业人员。"},{"id":"jun-law1-93","subject":"law","source":"6月押题 LC","type":"判断","q":"中国证监会根据证券公司评价计分的高低，将证券公司分为五大类十一个级别，其中 D 级是正常经营状态的最低等级。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。中国证监会根据证券公司评价计分的高低，将证券公司分为 A (AAA、AA、A) 、B (BBB、BB、B) 、C(CCC、CC、C) 、D、E 五大类 11 个级别。其中, C 级是正常经营状态的最低等级 (并非\"D 级\")。"},{"id":"jun-law1-94","subject":"law","source":"6月押题 LC","type":"判断","q":"当客户维持担保比例低于最低维持担保比例时，证券公司应当通知客户在约定的期限内追加担保物，客户经证券公司认可后，可以提交除可充抵保证金证券外的其他证券、不动产、股权等依法可以担保的财产或财产权利作为其他担保物。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。当客户维持担保比例低于最低维持担保比例时，证券公司应当通知客户在约定的期限内追加担保物，客户经证券公司认可后，可以提交除可充抵保证金证券外的其他证券、不动产、股权等依法可以担保的财产或财产权利作为其他担保物。"},{"id":"jun-law1-95","subject":"law","source":"6月押题 LC","type":"判断","q":"中华人民共和国境内股票、公司债券、存托凭证和国务院认定的其他证券的发行和交易，政府债券、证券投资基金份额的上市交易应当适用《证券法》有关规定。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。《证券法》的适用范围包括以下四类：一是在中华人民共和国境内，股票、公司债券、存托凭证和国务院依法认定的其他证券的发行和交易；二是政府债券、证券投资基金份额的上市交易；三是资产支持证券、资产管理产品发行、交易的管理办法，由国务院依照《证券法》的原则规定；四是在中华人民共和国境外的证券发行和交易活动，扰乱中华人民共和国境内市场秩序，损害境内投资者合法权益的，依照《证券法》有关规定处理并追究法律责任。"},{"id":"jun-law1-96","subject":"law","source":"6月押题 LC","type":"判断","q":"向投资者销售或者提供荐股软件并直接或间接获取经济利益的属于从事证券投资咨询业务，应当由证监会许可，符合证券投资咨询业务相关条件。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。根据《关于加强对利用\"荐股软件\"从事证券投资咨询业务监管的暂行规定》，向投资者销售或者提供\"荐股软件\"，并直接或间接获取经济利益的，属于从事证券投资咨询业务，应当经中国证监会许可，符合证券投资咨询业务条件。"},{"id":"jun-law1-97","subject":"law","source":"6月押题 LC","type":"判断","q":"合伙人企业中，有限合伙企业只存在普通合伙人，该公司应该被注销。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。有限合伙企业仅剩普通合伙人的，转为普通合伙企业(并非注销)。"},{"id":"jun-law1-98","subject":"law","source":"6月押题 LC","type":"判断","q":"合规管理人员工作称职的，其年度薪酬收入总额原则上不低于所在机构同等条件 (同岗位类型、同职级、同考核结果)人员的平均水平。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。合规负责人工作称职的，其年度薪酬收入总额在公司高级管理人员年度薪酬收入总额中的排名应当不低于中位数。其他合规管理人员工作称职的，其年度薪酬收入总额应当不低于公司同级别人员的平均水平。"},{"id":"jun-law1-99","subject":"law","source":"6月押题 LC","type":"判断","q":"对已经公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，但已经偿还的，可以再次公开发行公司债券。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态的，不得再次公开发行公司债券。已经偿还则不处于继续状态，故可以再次公开发行公司债券。"},{"id":"jun-law1-100","subject":"law","source":"6月押题 LC","type":"判断","q":"声誉风险不包括战略风险和法律风险。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。声誉风险是指由于证券经营机构行为或外部事件，及其工作人员违反廉洁规定、职业道德、业务规范、行规行约等相关行为，导致投资者、发行人、监管机构、自律组织、社会公众、媒体等对证券公司形成负面评价，从而损害其品牌价值，不利其正常经营，甚至影响到市场稳定和社会稳定的风险。声誉风险、战略风险、法律风险是并列的风险类型。声誉风险不包括战略风险和法律风险，它们之间是\"可能相互引发，但本质不同\"的关系。"},{"id":"jun-law1-101","subject":"law","source":"6月押题 LC","type":"判断","q":"经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务之一的， 注册资本最低限额为 1 亿元。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务之一的，注册资本最低限额为人民币 1 亿元。【乐引申】证券公司经营证券经纪，证券投资咨询，与证券交易、证券投资活动有关的财务顾问业务的，注册资本最低限额为人民币 5000 万元；经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务中两项以上的，注册资本最低限额为人民币 5 亿元。"},{"id":"jun-law1-102","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券公司融资融券业务管理办法》，对客户信用交易担保证券账户记录的证券，由证券公司以自己的名义，为客户的利益，行使对证券发行人的权利。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。对客户信用交易担保证券账户记录的证券，由证券公司以自己的名义，为客户的利益，行使对证券发行人的权利。证券公司行使对证券发行人的权利，应当事先征求客户的意见，并按照其意见办理。客户未表达意见的，证券公司不得行使对发行人的权利。"},{"id":"jun-law1-103","subject":"law","source":"6月押题 LC","type":"判断","q":"未向社会公开宣传，在亲友或者单位内部针对特定对象吸收资金的，不属于非法吸收或者变相吸收公众存款。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。违反国家金融管理法律规定，向社会公众 (包括单位和个人)吸收资金的行为，同时具备下列四个条件的，除刑法另有规定的以外，应当认定为刑法第一百七十六条规定的\"非法吸收公众存款或者变相吸收公众存款\"：(1)未经有关部门依法许可或者借用合法经营的形式吸收资金；(2)通过网络、媒体、推介会、传单、手机信息等途径向社会公开宣传；(3)承诺在一定期限内以货币、实物、股权等方式还本付息或者给付回报；(4)向社会公众即社会不特定对象吸收资金。未向社会公开宣传，在亲友或者单位内部针对特定对象吸收资金的，不属于非法吸收或者变相吸收公众存款。"},{"id":"jun-law1-104","subject":"law","source":"6月押题 LC","type":"判断","q":"分公司指的是业务， 资金，人事方面受本公司管理，但具有独立法人资格的独立机构。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。公司可以设立分公司。分公司不具有法人资格 (并非具有独立法人资格)，其民事责任由公司承担。"},{"id":"jun-law1-105","subject":"law","source":"6月押题 LC","type":"判断","q":"在上交所开展的股票质押式回购业务融入方违约处置完成后，证券公司向中国证券业协会、证券交易所、中国结算提交违约处置结果报告。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。违约处置完成后，证券公司向交易所、中国结算和中国证券投资者保护基金有限责任公司提交违约处置结果报告 (并非\"中国证券业协会\") 。"},{"id":"jun-law1-106","subject":"law","source":"6月押题 LC","type":"判断","q":"上市公司要约收购中，收购人在要约期限内有权撤销收购要约。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。在收购要约确定的承诺期限内，收购人不得撤销其收购要约 (并非\"有权撤销\")。收购人需要变更收购要约的，应当及时公告，载明具体变更事项。"},{"id":"jun-law1-107","subject":"law","source":"6月押题 LC","type":"判断","q":"诱骗投资者买卖证券、期货合约罪的主体不包含证券期货监督管理部门的工作人员。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。诱骗投资者买卖证券、期货合约罪的主体是特殊主体，主要包括两个方面：(1)证券交易所、期货交易所、证券公司、期货经纪公司的从业人员；(2)证券业协会、期货业协会或者证券期货监督管理部门的工作人员 (并非\"不包含\") 。"},{"id":"jun-law1-108","subject":"law","source":"6月押题 LC","type":"判断","q":"股份有限公司的设立，可以采取发起设立或募集设立的方式。以募集设立方式设立股份有限公司的，发起人认购的股份不得少于公司股份总数的 25%。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。公司的设立方式有两种，即发起设立和募集设立。募集设立只适用于股份有限公司。其中，发起人认购的股份不得少于公司章程规定的公司设立时应发行股份总数的 35%(并非\"25%\")，但是法律、行政法规另有规定的，从其规定。"},{"id":"jun-law1-109","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券经营机构投资者适当性管理实施指引(试行)》，证券经营机构可以要求投资者提供证明材料，符合条件的投资者经核验属实后，将认定结果报证券业协会，待其无异议后将其认定为专业投资者，并将认定结果书面告知投资者。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券经营机构应当要求符合一定条件的专业投资者提供证明材料，经经营机构核验属实的可以直接认定为专业投资者 (并不需要等待证券业协会无异议)。"},{"id":"jun-law1-110","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】某公司董事长张某、财务总监王某为使公司上市，组织单位工作人\n员通过使用自制的银行单据等方式，虚增当期利润总额达 50%，并在上市申请文\n件的定期财务报告和招股说明书中均载入上述内容。该公司上市后，张某和王某\n继续使用相同手段，连续三年均虚增当期营业收入总额 40%以上，并在年报中使\n用上述虚增经营数据，给公众投资者造成重大损失。\n请根据上述背景信息回答以下问题。\n\n【问题】依据张某和王某在上市申请文件和招股说明书中使用虚构财务数据的行为，可能触犯的罪名是 ()。","options":["提供虚假证明文件、出具证明文件重大失实罪","欺诈发行证券罪","操纵证券、期货市场罪","非法吸收公众存款罪"],"answer":"B","explain":"B 选项正确，欺诈发行证券的定义是指发行人不符合发行条件，以欺骗手段骗取发行注册的行为。如果情节严重构成犯罪的，以欺诈发行证券罪定罪处罚。欺诈发行证券罪的客观方面表现为：①行为人必须实施在招股说明书、认股书、公司、企业债券募集办法等发行文件中隐瞒重要事实或者编造重大虚假内容的行为；②行为人必须实施了发行证券的行为。如果行为人仅是制作了虚假的上述文件，而未实施发行证券的行为，不构成本罪。必须是既制作了虚假的上述文件，且已经发行证券的才构成本罪；③行为人制作虚假的招股说明书、认股书、公司、企业债券募集办法等发行文件发行证券的行为，必须达到一定的严重程度，即达到\"数额巨大、后果严重或者有其他严重情节的\"，才构成犯罪。张某和王某满足上述条件。"},{"id":"jun-law1-111","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】某公司董事长张某、财务总监王某为使公司上市，组织单位工作人\n员通过使用自制的银行单据等方式，虚增当期利润总额达 50%，并在上市申请文\n件的定期财务报告和招股说明书中均载入上述内容。该公司上市后，张某和王某\n继续使用相同手段，连续三年均虚增当期营业收入总额 40%以上，并在年报中使\n用上述虚增经营数据，给公众投资者造成重大损失。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于张某和王某就虚构上市公司财务数据并在年报中进行披露的行为应承担的法律责任的说法，错误的有() 。","options":["可能触犯违规披露、不披露重要信息罪","可能触犯背信运用受托财产罪","可能触犯提供虚假证明文件、出具证明文件重大失实罪","若王某不配合监管机关调查且伪造证据，应予从重处罚"],"answer":"BC","explain":"A 选项正确，违规披露、不披露重要信息罪，是指依法负有信息披露义务的公司、企业向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告，或者对依法应当披露的其他重要信息不按照规定披露，严重损害股东或者其他人利益，或有其他严重情节的行为。B 选项错误，背信运用受托财产，是指商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重的行为。C 选项错误，提供虚假证明文件、出具证明文件重大失实的犯罪主体主要指承担资产评估、验资、验证、会计、审计、法律服务、保荐、安全评价、环境影响评价、环境监测等职责的中介组织的人员。张某、王某是公司内部人员，不构成此罪。D 选项正确，不配合证券监管机构监管，或者拒绝、阻碍证券监管机构及其工作人员执法，甚至以暴力、威胁及其他手段干扰执法，应当从重处罚；在信息披露违法案件中变造、隐瞒、毁灭证据，或者提供伪证，妨碍调查，应当从重处罚。故本题选 BC 选项。"},{"id":"jun-law1-112","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】2021 年底，国内甲证券公司担任乙股份公司的保荐机构，甲证券公\n司按照协议全部购入乙公司将要发行的全部股票，然后分销给其他投资者。甲证\n券公司承担销售和价格的全部风险，甲证券公司本次承销活动非常顺利，在短时\n间内将所承销股票全部售出。此后，甲证券公司以自有资金在证券市场上对乙公\n司的股票进行买卖，并赚取了买卖差价。\n\n【问题】甲证券公司在承销证券时，应对公开发行募集文件的()进行核查。","options":["真实性","合理性","准确性","完整性"],"answer":"ACD","explain":"证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查 (B 选项错误，A、C、D 选项正确)。发现有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动。已经销售的，必须立即停止销售活动，并采取纠正措施。故本题选 ACD 选项。"},{"id":"jun-law1-113","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】2021 年底，国内甲证券公司担任乙股份公司的保荐机构，甲证券公\n司按照协议全部购入乙公司将要发行的全部股票，然后分销给其他投资者。甲证\n券公司承担销售和价格的全部风险，甲证券公司本次承销活动非常顺利，在短时\n间内将所承销股票全部售出。此后，甲证券公司以自有资金在证券市场上对乙公\n司的股票进行买卖，并赚取了买卖差价。\n\n【问题】甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价，证券公司在承销证券要求包括 ()。","options":["注册资本不低于 1 亿元人民币","注册资本不低于 5 亿元人民币","净资本不低于 2 亿元人民币","净资本不低于 5000 万元人民币"],"answer":"BC","explain":"经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务中两项以上的，注册资本最低限额为人民币 5 亿元。经营证券承销与保荐、证券自营、证券资产管理、其他证券业务中两项及两项以上的，其净资本不得低于人民币 2 亿元。B、C 选项符合题意，本题中甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价，属于证券自营业务，同时甲证券公司经营证券承销业务，属于经营证券承销和自营业务两种。故本题选 BC 选项。"},{"id":"jun-law1-114","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过\n董事会同意，拟向中国证监会申请为期货公司提供中间介绍业务的资格。\n\n【问题】如果甲证券公司的申请获得了中国证监会的批准，甲可以接受 ()的委托从事中间介绍业务。","options":["与甲证券公司长期具有贸易往来的期货公司","甲证券公司全资拥有的期货公司","与甲证券公司属于同一机构控制的期货公司","甲证券公司控股的期货公司"],"answer":"BCD","explain":"证券公司只能接受其全资拥有或者控股的 (B、D 选项正确)，或者被同一机构控制的期货公司的委托从事介绍业务 (C 选项正确)，不能接受其他期货公司的委托从事介绍业务 (A 选项错误) 。故本题选 BCD 选项。"},{"id":"jun-law1-115","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过\n董事会同意，拟向中国证监会申请为期货公司提供中间介绍业务的资格。\n\n【问题】甲证券公司受期货公司委托从事介绍业务，不得从事() 。","options":["提供期货行情信息、交易设施","代理客户进行期货交易","代期货公司、客户收付期货保证金","利用证券资金账户为客户存取、划转期货保证"],"answer":"BCD","explain":"证券公司受期货公司委托从事介绍业务，应当提供下列服务：①协助办理开户手续；②提供期货行情信息、交易设施 (A 选项错误)；③中国证监会规定的其他服务。证券公司不得代理客户进行期货交易、结算或者交割(B 选项正确)，不得代期货公司、客户收付期货保证金 (C 选项正确)，不得利用证券资金账户为客户存取、划转期货保证金 (D 选项正确)。"},{"id":"jun-law1-116","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】甲证券公司为了扩大公司规模，提高自己在市场上的竞争力，经过\n董事会同意，拟向中国证监会申请为期货公司提供中间介绍业务的资格。\n\n【问题】甲证券公司从事介绍业务，应当与期货公司签订书面委托协议，委托协议应当载明 () 。","options":["客户投诉的接待处理方式","介绍业务的范围","报酬支付及相关费用的分担方式","介绍业务对接规则"],"answer":"ABCD","explain":"证券公司从事介绍业务，应当与期货公司签订书面委托协议。委托协议应当载明下列事项：①介绍业务的范围 (B 选项正确)；②执行期货保证金安全存管制度的措施；③介绍业务对接规则 (D 选项正确)；④客户投诉的接待处理方式 (A 选项正确)；⑤报酬支付及相关费用的分担方式 (C 选项正确)；⑥违约责任；⑦中国证监会规定的其他事项。故本题选 ABCD 选项。"},{"id":"jun-law1-117","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022 年 6月 1 日，\n张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从\n事投资业务。\n\n【问题】张某作为私募资产管理业务的投资经理，应当具备() 。","options":["从事证券业务所需的专业能力","2 年以上投资管理、投资研究、投资咨询等相关业务经验","良好的诚信记录和职业操守","法律法规规定的其他条件"],"answer":"ACD","explain":"私募资产管理业务投资经理应当依法取得基金从业资格(A 选项正确)，具有3 年以上投资管理、投资研究、投资咨询等相关业务经验 (B 选项错误，并非\"2 年以上\")，具备良好的诚信记录和职业操守 (C 选项正确)，且最近 3 年未被监管机构采取重大行政监管措施、行政处罚，符合法律法规规定的其他条件 (D选项正确)。故本题选 ACD 选项。"},{"id":"jun-law1-118","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022 年 6月 1 日，\n张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从\n事投资业务。\n\n【问题】关于张某的离任审查，下列说法正确的有 ()。","options":["张某离任时，甲证券公司应当立即对其进行离任审查","张某在 2022 年 12 月 1 日方可在乙证券公司担任私募资产管理业务投资经理","甲证券公司应当自张某离任之日起 3 个月内形成离任审查报告，以存档备查","甲证券公司应当自张某离任之日起 30 个工作日内将审查报告报送中国证监会相关派出机构和证券投资基金业协会"],"answer":"AB","explain":"私募资产管理业务投资经理离任的，证券期货经营机构应当立即对其进行离任审查 (A 选项正确)，并自离任之日起 30 个工作日内将审查报告报送中国证监会相关派出机构 (D 选项错误)。投资经理离任的，证券基金经营机构应当对其进行离任审查，并自离任之日起2个月内形成离任审查报告，以存档备查 (C 选项错误)。证券基金经营机构不得聘用从其他证券基金经营机构离任未满 6 个月的投资经理，从事投资、研究、交易等相关业务 (B 选项正确, 2022 年 6 月 1 日至 2022年 12 月 1 日已满 6 个月)。故本题选 AB 选项。"},{"id":"jun-law1-119","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】张某担任甲证券公司私募资产管理业务投资经理。2022 年 6月 1 日，\n张某从甲证券公司离任，拟入职乙证券公司担任私募资产管理业务投资经理，从\n事投资业务。\n\n【问题】甲、乙证券公司应当针对私募资产管理业务的主要业务人员和相关管理人员建立收入递延支付机制，递延支付年限原则上不少于 ()年。","options":["1","2","3","4"],"answer":"C","explain":"C 选项正确，证券期货经营机构应当针对私募资产管理业务的主要业务人员和相关管理人员建立收入递延支付机制，合理确定收入递延支付标准、递延支付年限和比例。递延支付年限原则上不少于 3 年，递延支付的收入金额原则上不少于40%。故本题选 C 选项。"}]},{"id":"jun-law2","subject":"law","name":"6月押题 · 法规卷二","stats":{"单选":41,"多选":40,"判断":30,"案例":8},"questions":[{"id":"jun-law2-0","subject":"law","source":"6月押题 LC","type":"单选","q":"中国证监会根据证券公司评价计分的高低，将证券公司分为五大类十一个级别，其中 ()是正常经营状态的最低等级。","options":["D 级","B 级","E 级","C 级"],"answer":"D","explain":"答案解析：中国证监会根据证券公司评价计分的高低，将证券公司分为 A (AAA、AA、A) 、B (BBB、BB、B) 、C(CCC、CC、C) 、D、E 五大类十一个级别。其中，C 级是正常经营状态的最低等级 (D 选项正确) 。故本题选 D 选项。"},{"id":"jun-law2-1","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司应当按照 ()的原则，建立健全风险管理与内部控制制度，防范和控制风险。","options":["审慎经营","自主经营","独立经营","诚信经营"],"answer":"A","explain":"答案解析：A 选项正确，证券公司应当按照审慎经营的原则，建立健全风险管理与内部控制制度，防范和控制风险。故本题选 A 选项。"},{"id":"jun-law2-2","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司风险管理部门人员工作称职的，其薪酬收入总额应当不低于公司总部业务部门同职级人员的() 。","options":["一定比例","最低水平","中位数","平均水平"],"answer":"D","explain":"答案解析：D 选项正确，风险管理部门人员工作称职的，其薪酬收入总额应当不低于公司总部业务部门同职级人员的平均水平。故本题选 D 选项。"},{"id":"jun-law2-3","subject":"law","source":"6月押题 LC","type":"单选","q":"证券公司从事证券自营业务，可以依据 ()的附件《证券公司证券自营投资品种清单》买卖其中所列的证券。","options":["《证券公司证券自营业务指引》","《证券公司内部控制指引》","《证券公司风险控制指标管理办法》","《关于证券公司证券自营业务投资范围及有关事项的规定》"],"answer":"D","explain":"答案解析：D 选项正确，根据《关于证券公司证券自营业务投资范围及有关事项的规定》，证券公司从事证券自营业务，可以买卖此规定附件《证券公司证券自营投资品种清单》所列证券。故本题选 D 选项。"},{"id":"jun-law2-4","subject":"law","source":"6月押题 LC","type":"单选","q":"以下属于证监会等监管机构制定证券经纪业务相关监管政策、实施监督管理的重要法规依据的是 ()。","options":["《证券登记结算管理办法》","《信托法》","《公司法》","《证券公司监督管理条例》"],"answer":"D","explain":"答案解析：D 选项正确， 《证券法》 《证券公司监督管理条例》是中国证监会等监管机构制定证券经纪业务相关监管政策、实施监督管理的重要法律依据。故本题选 D选项。"},{"id":"jun-law2-5","subject":"law","source":"6月押题 LC","type":"单选","q":"以下可能不属于专业投资者的是() 。","options":["金融资产 300 万的个人投资者","商业银行","保险公司","私募基金管理者"],"answer":"A","explain":"答案解析：(1)第一类专业投资者具体包括：经有关金融监管部门批准设立的金融机构，包括证券公司、期货公司、基金管理公司及其子公司、商业银行 (B 选项不符合题意)、保险公司 (C 选项不符合题意)、信托公司、财务公司等；经行业协会备案或者登记的证券公司子公司、期货公司子公司、私募基金管理人 (D 选项不符合题意) 。(2)第二类专业投资者包括：同时符合下列条件的自然人：①金融资产不低于500万元 (A选项符合题意)，或者最近3年个人年均收入不低于50万元；②具有 2 年以上证券、基金、期货、黄金、外汇等投资经历，或者具有 2年以上金融产品设计、投资、风险管理及相关工作经历，或者属于前述第一类专业投资者中的第 1 部分的金融机构的高级管理人员、获得职业资格认证的从事金融相关业务的注册会计师和律师。故本题选 A 选项。"},{"id":"jun-law2-6","subject":"law","source":"6月押题 LC","type":"单选","q":"以下关于信息安全的说法，错误的是 () 。","options":["证券公司已经或可能掌握内幕信息的，应当将内幕信息所涉公司或证券列入限制名单","与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密","加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全","对可能知悉敏感信息的工作人员使用公司的信息系统或配发的设备形成的电子邮件、即时通信信息和其他通信信息进行监测"],"answer":"A","explain":"答案解析：A 选项错误，证券公司已经或者可能掌握内幕信息的，应当将内幕信息所涉公司或者证券列入观察名单 (并非\"限制名单\") 。故本题选 A 选项。"},{"id":"jun-law2-7","subject":"law","source":"6月押题 LC","type":"单选","q":"下列关于资产管理产品的说法，错误的是 () 。","options":["资产管理产品按投资性质不同可分为三类，即固定收益类产品、权益类产品、期货和衍生品类产品","固定收益类产品投资于债权类资产比例不低于 80%","权益类产品投资于股权类资产比例不低于 80%","期货和衍生品的持仓合约价值的比例不低于资产管理计划总资产的 80%"],"answer":"A","explain":"答案解析：A 选项错误，资产管理产品按照投资性质不同，分为固定收益类产品、权益类产品、期货和衍生品类产品和混合类产品。故本题选 A 选项。"},{"id":"jun-law2-8","subject":"law","source":"6月押题 LC","type":"单选","q":"下列关于证券公司开展证券承销业务行为规范的说法，错误的是 ()。","options":["证券公司作为承销商应当对发行募集文件的真实性、准确性、完整性进行核查","证券公司不得以返回承销费等方式招揽承销业务","证券公司在销售启动后发现募集文件存在重大遗漏的，应当全额包销剩余证券","证券公司发现发行募集文件存在虚假记载的，不得进行销售活动"],"answer":"C","explain":"答案解析：证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查 (A 选项正确)。发现有虚假记载、误导性陈述或者重大遗漏的，不得进行销售活动 (D 选项正确)；已经销售的，必须立即停止销售活动并采取纠正措施(C选项错误)。证券公司承销证券，不得有下列行为：(1)进行虚假的或者误导投资者的广告宣传或者其他宣传推介活动；(2)以不正当竞争手段招揽承销业务 (B选项正确)；(3)其他违反证券承销业务规定的行为。故本题选 C 选项。"},{"id":"jun-law2-9","subject":"law","source":"6月押题 LC","type":"单选","q":"下列关于有限合伙企业注销后责任承担的说法，正确的是 ()。","options":["全体合伙人对合伙企业存续期间的债务承担无限连带责任","全体合伙人对合伙企业存续期间的债务无须承担责任","有限合伙人对存续期间的债务承担补充责任","普通合伙人对合伙企业存续期间的债务承担无限连带责任"],"answer":"D","explain":"答案解析：A、B、C 选项错误，D 选项正确，合伙企业注销后，原普通合伙人对合伙企业存续期间的债务仍应承担无限连带责任。有限合伙人以其认缴的出资额为限对合伙企业债务承担责任。"},{"id":"jun-law2-10","subject":"law","source":"6月押题 LC","type":"单选","q":"下列各项中，不属于有限责任公司监事会行使的职权是 ()。","options":["对董事执行公司职务的行为进行监督","检查公司财务","提议召开临时股东会会议","决定公司内部管理机构的设置"],"answer":"D","explain":"答案解析：监事会行使下列职权：(1)检查公司财务 (B 选项不符合题意)；(2)对董事、高级管理人员执行职务的行为进行监督(A 选项不符合题意)，对违反法律、行政法规、公司章程或者股东会决议的董事、高级管理人员提出解任的建议；(3)提议召开临时股东会会议，在董事会不履行《公司法》规定的召集和主持股东会会议职责时召集和主持股东会会议 (C 选项不符合题意) 。D 选项符合题意，决定公司内部管理机构的设置属于董事会的职责。故本题选 D 选项。"},{"id":"jun-law2-11","subject":"law","source":"6月押题 LC","type":"单选","q":"我国《证券法》规定，持有公司 ()以上股份的股东为知悉证券交易内幕信息的知情人员。","options":["10%","20%","3%","5%"],"answer":"D","explain":"答案解析：D 选项正确，证券交易内幕信息的知情人包括：持有公司 5%以上股份的股东及其董事、监事、高级管理人员，公司的实际控制人及其董事、监事、高级管理人员。故本题选 D 选项。"},{"id":"jun-law2-12","subject":"law","source":"6月押题 LC","type":"单选","q":"上市公司在一年内担保金额超过公司资产总额 ()的，应当由股东会作出决议，并经出席会议的股东所持表决权的  以上通过。","options":["10%","50%","20%","30%"],"answer":"D","explain":"答案解析：D 选项正确，上市公司在 1 年内向他人提供担保的金额超过公司资产总额30%的，应当由股东会作出决议，并经出席会议的股东所持表决权的 2/3 以上通过。故本题选 D 选项。"},{"id":"jun-law2-13","subject":"law","source":"6月押题 LC","type":"单选","q":"期货交易实行 ()，在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算，结算参与人应当根据期货结算机构的结算结果对交易者进行结算。","options":["当日无负债结算制度","套期保值","保证金制度","持仓限额制度"],"answer":"A","explain":"答案解析：A 选项正确，期货交易实行当日无负债结算制度。在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算；结算参与人应当根据期货结算机构的结算结果对交易者进行结算。故本题选 A 选项。"},{"id":"jun-law2-14","subject":"law","source":"6月押题 LC","type":"单选","q":"某个人投资者要参加上交所科创板股票交易，要求具备的条件，不包括 ()。","options":["参与证券交易 24 个月以上","符合法律法规及上交所规定的机构投资者","申请权限开通后资金账户内的资金不低于人民币 50 万元","申请权限开通前 20 个交易日证券账户及资金账户内的自有资产日均不低于人民币 50 万元 (不包括该投资者通过融资融券融入的资金和证券)"],"answer":"C","explain":"答案解析：明确投资者参与科创板股票交易的具体条件：个人投资者申请权限开通前 20 个交易日证券账户及资金账户内的资产日均不低于人民币 50 万元 (不包括该投资者通过融资融券融入的资金和证券) (D 选项不符合题意)，并且参与证券交易24个月以上 (A 选项不符合题意)；符合法律法规及上交所规定的机构投资者 (B选项不符合题意)，可直接申请开通科创板股票交易权限。故本题选 C 选项。"},{"id":"jun-law2-15","subject":"law","source":"6月押题 LC","type":"单选","q":"李某为某基金公司的基金经理，其管理的基金拟在某日重仓买入 Y 股票，李某妻弟在无意中获悉消息后大量买入 Y 股票，待价格上涨后卖出， 获利 2000万元。根据《刑法》，李某妻弟的行为构成 ()。","options":["泄露内幕信息罪","利用未公开信息交易罪","背信运用受托财产罪","操纵证券市场罪"],"answer":"B","explain":"答案解析：利用未公开信息交易，是指证券交易所、期货交易所、证券公司、期货经纪公司、基金管理公司、商业银行、保险公司等金融机构的从业人员以及有关监管部门或者行业协会的工作人员，利用因职务便利获取的内幕信息以外的其他未公开的信息，违反规定，从事与该信息相关的证券、期货交易活动，或者明示、暗示他人从事相关交易活动，情节严重的行为。B 选项正确，李某妻弟利用从李某处获得的消息进行交易，构成利用未公开信息交易罪。故本题选 B 选项。"},{"id":"jun-law2-16","subject":"law","source":"6月押题 LC","type":"单选","q":"经国务院期货监督管理机构核准，期货公司可以从事的业务不包括 ()。","options":["期货经纪业务","期货交易咨询","期货做市交易","期货自营业务"],"answer":"D","explain":"答案解析：期货公司经国务院期货监督管理机构核准可以从事下列期货业务：(1)期货经纪(A 选项不符合题意)；(2)期货交易咨询 (B 选项不符合题意)；(3)期货做市交易(C 选项不符合题意)；(4)其他期货业务。故本题选 D 选项。"},{"id":"jun-law2-17","subject":"law","source":"6月押题 LC","type":"单选","q":"甲与乙串通， 以事先约定的时间、价格和方式相互进行证券交易，影响证券交易价格，获得巨大非法收益，则甲与乙的行为构成 ()罪。","options":["内幕交易","利用未公开信息交易","操纵证券市场","背信运用受托财产"],"answer":"C","explain":"答案解析：操纵证券、期货市场罪，是指有下列情形的，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易 (C 选项正确)。故本题选 C 选项。"},{"id":"jun-law2-18","subject":"law","source":"6月押题 LC","type":"单选","q":"关于证券金融公司开展转融通业务的资金来源的说法，错误的是 ()。","options":["证券金融公司通过证券交易所的业务平台融入的资金","证券金融公司不得使用向股东借入次级债融入的资金","证券金融公司自有资金","证券金融公司通过自己的业务平台融入的资金"],"answer":"B","explain":"答案解析：证券金融公司开展转融通业务，可以使用下列资金和证券：(1)自有资金和证券(C 选项正确)；(2)通过证券交易所的业务平台融入的资金和证券 (A 选项正确)；(3)通过证券金融公司的业务平台融入的资金 (D 选项正确)；(4)依法筹集的其他资金和证券。B 选项错误，证券金融公司可以向股东或其他符合条件的机构投资者借入次级债，作为其资金来源之一。故本题选 B 选项。"},{"id":"jun-law2-19","subject":"law","source":"6月押题 LC","type":"单选","q":"公司依据股东人数和股份流动性可分为 ()。","options":["母公司与子公司","国有公司和非国有公司","上市公司和非上市公司","有限责任公司和股份有限公司"],"answer":"D","explain":"答案解析：D 选项正确，公司可依照不同的分类标准作不同的分类。依股东人数和股份流动性等，可分为有限责任公司和股份有限公司。故本题选 D 选项。"},{"id":"jun-law2-20","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券投资基金法》，下列关于基金财产独立性的说法，正确的是 ()。","options":["不同基金财产的债权债务不得相互抵扣，公募基金除外","基金管理人因基金财产的管理、运用或者其他情形而取得的财产和收益，归入基金管理人","基金管理人、基金托管人因依法解散、被依法撤销或者被依法宣告破产等原因进行清算的，基金财产不属于其清算财产","基金财产的债务由基金管理人本身承担，基金管理公司股东以其出资为限对基金财产的债务承担责任"],"answer":"C","explain":"答案解析：A 选项错误，不同基金财产的债权债务，不得相互抵销。B 选项错误，基金管理人、基金托管人因基金财产的管理、运用或者其他情形而取得的财产和收益，归入基金财产。C 选项正确，基金管理人、基金托管人因依法解散、被依法撤销或者被依法宣告破产等原因进行清算的，基金财产不属于其清算财产。基金销售机构、基金销售支付机构或者基金份额登记机构破产或者清算时，基金销售结算资金、基金份额不属于其破产财产或者清算财产。D 选项错误，基金财产的债务由基金财产本身承担，基金份额持有人以其出资为限对基金财产的债务承担责任。故本题选 C 选项。"},{"id":"jun-law2-21","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券投资基金法》，基金财产的债务由 ()承担。","options":["基金管理人","基金托管人","基金财产本身","基金份额持有人"],"answer":"C","explain":"答案解析：C 选项符合题意，基金财产的债务由基金财产本身承担，基金份额持有人以其出资为限对基金财产的债务承担责任。故本题选 C 选项。"},{"id":"jun-law2-22","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，证券从业人员的以下行为，不违反从业人员履职限制及禁止行为的是 ()。","options":["泄露因职务便利获取的未公开信息","接受他人赠送的股票","买卖上市公司发行的可转换公司债券","公平进行业务竞争"],"answer":"D","explain":"答案解析：根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，从业人员不得从事下列行为：(1)不正当交易或者利益输送 (B 选项不符合题意)；(2)泄露因职务便利获取的未公开信息、利用该信息从事或者明示、暗示他人从事相关的交易活动 (A 选项不符合题意)；(3)违反法律法规和中国证监会的规定，从事证券、基金和未上市企业股权投资 (C 选项不符合题意)。D 选项符合题意，公平进行业务竞争不违反从业人员的履职限制及禁止行为。故本题选 D 选项。"},{"id":"jun-law2-23","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司证券自营业务指引》，关于自营业务资金出入的相关规定，下列行为正确的是 ()。","options":["以个人名义从自营账户调出资金","以公司名义从自营账户提取现金","以个人名义调入资金","以公司名义调入资金"],"answer":"D","explain":"答案解析：自营业务资金的出入必须以公司名义进行 (D 选项正确)，禁止以个人名义从自营账户中调入调出资金(A、C 选项错误)，禁止从自营账户中提取现金 (B选项错误)。故本题选 D 选项。"},{"id":"jun-law2-24","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司监督管理条例》，证券公司合并、分立的，涉及客户权益的()应当经具有证券相关业务资格的资产评估机构评估。","options":["重大资产转让","重大利润分配","重大股权变化","重大债务变化"],"answer":"A","explain":"答案解析：A 选项正确，合并、分立中涉及客户权益的重大资产转让应当经具有证券相关业务资格的资产评估机构评估。故本题选 A 选项。"},{"id":"jun-law2-25","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，证券公司不采纳合规负责人的合规审查意见的，应当将有关事项提交 ()审议决定。","options":["经理层","董事会","监事会","股东会"],"answer":"B","explain":"答案解析：B 选项正确，规定公司不采纳合规负责人的合规审查意见的，应当将有关事项提交董事会审议决定。故本题选 B 选项。"},{"id":"jun-law2-26","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司风险控制指标管理办法》规定，下列关于证券公司风险控制指标标准的说法，错误的是() 。","options":["风险覆盖率不得低于 80%","资本杠杆率不得低于 8%","净稳定资金率不得低于 100%","流动性覆盖率不得低于 100%"],"answer":"A","explain":"答案解析：证券公司必须持续符合下列风险控制指标标准：(1)风险覆盖率不得低于100%(A选项错误，并非 80%) ;(2)资本杠杆率不得低于 8%(B 选项正确)；(3)流动性覆盖率不得低于100%(D选项正确)；(4)净稳定资金率不得低于100%(C选项正确) 。故本题选 A 选项。"},{"id":"jun-law2-27","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司风险处置条例》有关规定，下列关于禁止参与处置证券公司风险工作的机构或人员的情形，错误的是 () 。","options":["曾因一般违法行为受过行政处罚","涉嫌犯罪正在被立案侦查、起诉","涉嫌严重违法正在被行政管理部门立案稽查","处于证券市场禁入期"],"answer":"A","explain":"答案解析：有下列情形之一的机构或者人员，禁止参与处置证券公司风险工作：(1)曾受过刑事处罚或者涉嫌犯罪正在被立案侦查、起诉 (A 选项错误、B 选项正确) ；(2)涉嫌严重违法正在被行政管理部门立案稽查或者曾因严重违法行为受到行政处罚未逾 3 年 (C 选项正确) ;(3)仍处于证券市场禁入期 (D 选项正确)；(4)内部控制薄弱、存在重大风险隐患；(5)与被处置证券公司处置事项有利害关系；(6)国务院证券监督管理机构认定不宜参与处置证券公司风险工作的其他情形。故本题选 A 选项。"},{"id":"jun-law2-28","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券公司风险处置条例》，下列关于证券公司进行行政重组的说法，错误的是 ()。","options":["证券公司可以采取注资、合并的方式进行行政重组","证券公司可以采取股权重组、债务重组、资产重组的方式进行行政重组","重组期限内行政重组未完成的，证券公司应直接申请破产，不得延长重组期限","中国证监会对证券公司的行政重组进行协调和指导"],"answer":"C","explain":"答案解析：C 选项错误，行政重组期限一般不超过12 个月。满 12 个月，行政重组未完成的，国务院证券监督管理机构可以决定延长行政重组期限 (并非不得延长重组期限)，但延长行政重组期限最长不得超过 6 个月。故本题选 C 选项。"},{"id":"jun-law2-29","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券法》，证券的发行、交易活动， 必须遵循 ()的原则。","options":["公开、公平、客观","公允、合理、客观","公开、公平、公正","合理、合法、有效"],"answer":"C","explain":"答案解析：C 选项正确，证券的发行、交易活动，必须遵循公开、公平、公正\"三公\"原则。故本题选 C 选项。"},{"id":"jun-law2-30","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券法》，下列关于证券交易行为的有关说法，错误的是 () 。","options":["任何单位和个人不得违反规定，出借自己的证券账户或者借用他人的证券账户从事证券交易","依法拓宽资金入市渠道，禁止资金违规流入股市","禁止投资者以任何方式利用财政资金、银行信贷资金、银行理财资金买卖证券","禁止任何单位和个人编造、传播虚假信息或者误导性信息，扰乱证券市场"],"answer":"C","explain":"答案解析：A 选项正确，任何单位和个人不得违反规定，出借自己的证券账户或者借用他人的证券账户从事证券交易。B 选项正确、C 选项错误，依法拓宽资金入市渠道，禁止资金违规流入股市。禁止投资者违规利用财政资金、银行信贷资金买卖证券。D 选项正确，禁止任何单位和个人编造、传播虚假信息或者误导性信息，扰乱证券市场。故本题选 C 选项。"},{"id":"jun-law2-31","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《证券法》，公开发行股票，代销、包销期限届满，发行人应当在规定的期限内将股票发行情况报()备案。","options":["证券交易所","国务院证券监督管理机构","中国证券业协会","证券登记结算公司"],"answer":"B","explain":"答案解析：证券的代销、包销期限最长不得超过 90 日。证券公司在代销、包销期内，对所代销、包销的证券应当保证先行出售给认购人，证券公司不得为本公司预留所代销的证券和预先购入并留存所包销的证券。公开发行股票，代销、包销期限届满，发行人应当在规定的期限内将股票发行情况报国务院证券监督管理机构备案 (B选项正确) 。故本题选 B 选项。"},{"id":"jun-law2-32","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《私募投资基金监督管理条例》，投资者分配收益和承担风险的依据不包括 ()。","options":["公司章程","基金合同","合伙协议","口头约定"],"answer":"D","explain":"答案解析：投资者分配收益和承担风险的依据一般是基金合同 (B 选项不符合题意)。私募基金管理人可能是公司，因此还可以以公司章程(A 选项不符合题意)为依据，也可能是合伙企业，因此还可以以合伙协议 (C 选项不符合题意)为依据。但不能以口头约定 (D 选项符合题意)收益分配。故本题选 D 选项。【引申]私募基金管理人应当履行下列职责:(1)依法募集资金，办理私募基金备案;(2)对所管理的不同私募基金财产分别管理、分别记账，进行投资;(3)按照基金合同约定管理私募基金并进行投资，建立有效的风险控制制度;(4)按照基金合同约定确定私募基金收益分配方案，向投资者分配收益:(5)按照基金合同约定向投资者提供与私募基金管理业务活动相关的信息;(6)保存私募基金财产管理业务活动的记录、账册、报表和其他有关资料;(7)国务院证券监督管理机构规定和基金合同约定的其他职责。"},{"id":"jun-law2-33","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《公司法》，下列不能作为股东出资的是() 。","options":["土地使用权","劳务","货币","知识产权"],"answer":"B","explain":"答案解析：有限责任公司股东可以用货币出资，也可以用实物、知识产权、土地使用权、股权、债权等可以用货币估价并可以依法转让的非货币财产作价出资 (A、C、D 选项不符合题意)；但是，法律、行政法规规定不得作为出资的财产除外，如劳务、姓名等 (B 选项符合题意)。故本题选 B 选项。"},{"id":"jun-law2-34","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《反洗钱法》规定，反洗钱不包括 () 。","options":["贪污贿赂犯罪","走私犯罪","金融诈骗犯罪","故意伤害罪"],"answer":"D","explain":"答案解析：反洗钱是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪(B 选项不符合题意)、贪污贿赂犯罪 (A 选项不符合题意)、破坏金融管理秩序犯罪、金融诈骗犯罪 (C 选项不符合题意)和其他犯罪所得及其收益的来源和性质的洗钱活动。D 选项符合题意，故意伤害罪是反洗钱不包括的犯罪类型。"},{"id":"jun-law2-35","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《发布证券研究报告暂行规定》和《发布证券研究报告执业规范》，下列不属于证券公司、证券投资咨询机构发布证券研究报告需载明事项的是 ()。","options":["证券分析师姓名及登记编码","使用证券研究报告的收费环节说明","具备证券投资咨询业务资格的说明","证券研究报告采用的信息和资料来源"],"answer":"B","explain":"答案解析：经营机构发布的证券研究报告，应当载明下列事项:(1)\"证券研究报告\"字样;(2)经营机构名称;(3)具备证券投资咨询业务资格的说明(C 选项不符合题意)(4)证券分析师姓名及其登记编码(A 选项不符合题意);(5) 发布证券研究报告的时间;(6)证券研究报告采用的信息和资料来源(D 选项不符合题意);(7)使用证券研究报告的风险提示。故本题选 B 选项。"},{"id":"jun-law2-36","subject":"law","source":"6月押题 LC","type":"单选","q":"根据《发布证券研究报告暂行规定》和《发布证券研究报告执业规范》，下列不属于证券公司、证券投资咨询机构发布证券研究报告需载明事项的是 ()。","options":["证券分析师姓名及登记编码","使用证券研究报告的收费环节说明","具备证券投资咨询业务资格的说明","证券研究报告采用的信息和资料来源"],"answer":"B","explain":"答案解析：经营机构发布的证券研究报告，应当载明下列事项：(1) \"证券研究报告\"字样；(2)经营机构名称；(3)具备证券投资咨询业务资格的说明 (C 选项不符合题意)；(4)证券分析师姓名及其登记编码 (A 选项不符合题意) ;(5)发布证券研究报告的时间；(6)证券研究报告采用的信息和资料来源 (D选项不符合题意)；(7)使用证券研究报告的风险提示。故本题选 B 选项。"},{"id":"jun-law2-37","subject":"law","source":"6月押题 LC","type":"单选","q":"对于债券发行与承销业务的监管，下列说法不正确的有 ()。","options":["中国证监会对公司债券的公开发行、非公开发行及交易转让活动进行监督管理","中国银行间市场交易商协会对公司债券的公开发行及交易转让等活动进行自律管理","中国证监会对企业债券的发行、托管、兑付、信息披露等事项进行监督管理","中国人民银行对金融债券的发行进行监督管理"],"answer":"B","explain":"答案解析：A 选项正确，中国证监会依法对公司债券的公开发行、非公开发行及其交易或转让活动进行监督管理。B 选项错误，交易商协会依据《银行间债券市场非金融企业债务融资工具管理办法》及中国人民银行相关规定对债务融资工具的发行与交易实施自律管理。C 选项正确，中国证监会依法对企业债券的发行、托管、兑付、信息披露、募集资金使用等相关事项进行监督管理。D 选项正确，中国人民银行依法对金融债券的发行进行监督管理。故本题选 B 选项。"},{"id":"jun-law2-38","subject":"law","source":"6月押题 LC","type":"单选","q":"对于流动性风险限额的评估 () 。","options":["每半年一次","每三年一次","每两年一次","每一年一次"],"answer":"D","explain":"答案解析：D 选项正确，证券公司应至少每年对流动性风险限额进行一次评估，必要时进行调整。故本题选 D 选项。"},{"id":"jun-law2-39","subject":"law","source":"6月押题 LC","type":"单选","q":"不可以召开全体基金份额持有人大会的为 ()。","options":["基金托管人","基金销售机构","基金份额持有人","基金管理人"],"answer":"B","explain":"答案解析：A 选项错误，基金托管人的职责包括：按照规定召集基金份额持有人大会。C 选项错误，基金份额持有人依法享有的权利包括：按照规定要求召开基金份额持有人大会或者召集基金份额持有人大会。D 选项错误，基金管理人的职责包括：按照规定召集基金份额持有人大会。故本题选 B 选项。"},{"id":"jun-law2-40","subject":"law","source":"6月押题 LC","type":"单选","q":"按照《证券业从业人员执业行为准则》及相关规则的规定，一般证券从业人员应接受协会和所在机构组织的后续职业培训，且每年的培训不少于 ()","options":["20 学时","15 学时","10 学时","5 学时"],"answer":"B","explain":"答案解析：B 选项正确，从业人员自首次执业登记日的下一年起，每个自然年为一个培训周期。证券公司应当要求其从业人员在每个培训周期内完成一定时间的业务培训，建议不少于 15 学时，每学时为 45 分钟。故本题选 B 选项。"},{"id":"jun-law2-41","subject":"law","source":"6月押题 LC","type":"多选","q":"证券期货经营机构违反适当性管理规定，有下列()情形的，给予警告，并处以 3 万元以下罚款；对直接负责的主管人员和其他直接责任人员，给予警告，并处以 3 万元以下罚款。","options":["未按规定对普通投资者进行细化分类和管理的","未按规定进行投资者类别转化的","未建立或者更新投资者评估数据库的","未按规定了解所销售产品或者所提供服务信息或者履行分级义务的"],"answer":"ABCD","explain":"答案解析：经营机构有下列情形之一的，给予警告，并处以 3 万元以下罚款；对直接负责的主管人员和其他直接责任人员，给予警告，并处以 3 万元以下罚款：①未按规定对普通投资者进行细化分类和管理的 (A 选项正确)；②未按规定进行投资者类别转化的 (B 选项正确)；③未建立或者更新投资者评估数据库的 (C 选项正确)；④未按规定了解所销售产品或者所提供服务信息或者履行分级义务的 (D 选项正确)；⑤未按规定划分产品或者服务风险等级的；⑥未按规定录音录像或者采取配套留痕安排的；⑦未按规定制定或者落实适当性内部管理制度和相关制度机制的；⑧未按规定开展适当性自查的；⑨未按规定妥善保存相关信息资料的。故本题选 ABCD 选项。"},{"id":"jun-law2-42","subject":"law","source":"6月押题 LC","type":"多选","q":"证券期货经营机构及其工作人员违反《证券期货经营机构及其工作人员廉洁从业规定》，有()情形的，中国证监会应当从重处理。","options":["连续或者多次违反该规定","违反该规定后及时报告","涉及金额较大","曾为公职人员"],"answer":"ACD","explain":"答案解析：证券期货经营机构及其工作人员违反本《廉洁规定》，有下列情形之一的，中国证监会应当从重处理：(1)直接、间接或者唆使、协助他人向监管人员输送利益；(2)连续或者多次违反本规定 (A 选项符合题意)；(3)涉及金额较大或者涉及人员较多 (C 选项符合题意) ;(4)产生恶劣社会影响；(5)曾为公职人员特别是监管人员，以及曾任证券期货经营机构合规风控职务的人员违反本规定 (D选项符合题意)；(6)中国证监会认定应当从重处理的其他情形。B 选项不符合题意，证券期货经营机构工作人员违反《廉洁规定》，事后及时向中国证监会报告，或者积极配合调查的，依法免于追究责任或者从轻、减轻处理。故本题选 ACD 选项。"},{"id":"jun-law2-43","subject":"law","source":"6月押题 LC","type":"多选","q":"证券公司应当依法向社会公开披露其基本情况、负债及或有负债情况、 ()、高级管理人员薪酬和其他有关信息。","options":["经营管理状况","参股及控股情况","人均薪酬情况","财务收支状况"],"answer":"ABD","explain":"答案解析：根据《证券公司监督管理条例》第六十六条的规定，证券公司应当依法向社会公开披露其基本情况、参股及控股情况 (B 选项正确)、负债及或有负债情况、经营管理状况 (A 选项正确)、财务收支状况 (D 选项正确)、高级管理人员薪酬和其他有关信息。具体办法由国务院证券监督管理机构制定。C 选项错误，披露薪酬信息的焦点在于\"高级管理人员薪酬\"，而非全体员工的人均薪酬。故本题选ABD 选项。"},{"id":"jun-law2-44","subject":"law","source":"6月押题 LC","type":"多选","q":"证券公司净资本或者其他风险控制指标不符合规定标准的，中国证监会派出机构应当责令公司限期改正。整改期内，中国证监会及其派出机构应当区别情形，可以对证券公司采取的措施有 () 。","options":["限制转让财产或在财产上设定其他权利","限制薪酬发放","限制分配红利","停止批准新业务"],"answer":"ACD","explain":"答案解析：整改期内，中国证监会及其派出机构应当区别情形，对证券公司采取下列措施：(1)停止批准新业务 (D 选项正确)；(2)停止批准增设、收购营业性分支机构；(3)限制分配红利 (C 选项正确)；(4)限制转让财产或在财产上设定其他权利 (A选项正确) 。B 选项错误，综上所述，\"限制薪酬发放\"不是整改期内，中国证监会及其派出机构应当区别情形，可以对证券公司采取的措施。故本题选 ACD选项。"},{"id":"jun-law2-45","subject":"law","source":"6月押题 LC","type":"多选","q":"证券公司合规部门具备 3 年以上的有关领域工作经历的人员占公司总部员工比例应不低于 1.5%，包括() 。","options":["金融","法律","证券","新闻"],"answer":"ABC","explain":"答案解析：证券公司应当为合规部门配备足够的、具备与履行合规管理职责相适应的专业知识和技能的合规管理人员。合规部门中具备3年以上证券 (C选项正确)、金融 (A选项正确)、法律 (B 选项正确)、会计、信息技术等有关领域工作经历的合规管理人员数量不得低于公司总部人数的 1.5%， 且不得少于 5 人。D 选项错误，不属于其经历要求。故本题选 ABC 选项。"},{"id":"jun-law2-46","subject":"law","source":"6月押题 LC","type":"多选","q":"证券公司、证券投资咨询机构或者其他财务顾问机构存在下列 ()情形时，不得担任上市公司独立财务顾问。","options":["持有或者通过协议、其他安排与他人共同持有上市公司股份达到 2%","上市公司持有或者通过协议、其他安排与他人共同持有财务顾问的股份达到2%","财务顾问的监事在上市公司任职","最近 1 年财务顾问为上市公司提供过融资服务"],"answer":"CD","explain":"答案解析： 存在下列情形之一的，不得担任独立财务顾问：(1)持有或者通过协议、其他安排与他人共同持有上市公司股份达到或者超过 5%(A 选项错误)，或者选派代表担任上市公司董事；(2)上市公司持有或者通过协议、其他安排与他人共同持有财务顾问的股份达到或者超过 5%(B 选项错误)，或者选派代表担任财务顾问的董事；(3)最近 2 年财务顾问与上市公司存在资产委托管理关系、相互提供担保，或者最近一年财务顾问为上市公司提供融资服务 (D 选项正确)；(4)财务顾问的董事、监事、高级管理人员、财务顾问主办人或者其直系亲属有在上市公司任职等影响公正履行职责的情形 (C 选项正确) ；(5)在并购重组中为上市公司的交易对方提供财务顾问服务；(6)与上市公司存在利害关系、可能影响财务顾问及其财务顾问主办人独立性的其他情形。故本题选 CD 选项。"},{"id":"jun-law2-47","subject":"law","source":"6月押题 LC","type":"多选","q":"以下属于非公开募集基金投资范围的有 ()。","options":["股票、债券","基金份额","期货、期权","股权"],"answer":"ABCD","explain":"答案解析：非公开募集基金财产的投资包括买卖股票、债券 (A 选项符合题意)、股权 (D选项符合题意)、期货、期权(C 选项符合题意)、基金份额 (B 选项符合题意)及投资合同约定的其他投资标的。故本题选 ABCD 选项。"},{"id":"jun-law2-48","subject":"law","source":"6月押题 LC","type":"多选","q":"下列职权中，属于股份有限公司股东会职权的是() 。","options":["对公司增加或者减少注册资本作出决议","决定公司的经营计划和投资方案","对公司合并、分立、解散、清算或者变更公司形式作出决议","修改公司章程"],"answer":"ACD","explain":"答案解析：股东会行使下列法定职权：(1)对公司增加或者减少注册资本作出决议 (A 选项符合题意)；(2)对公司合并、分立、解散、清算或者变更公司形式作出决议 (C选项符合题意)；(3)修改公司章程 (D 选项符合题意) 。B 选项不符合题意，属于董事会的职权。故本题选 ACD 选项。"},{"id":"jun-law2-49","subject":"law","source":"6月押题 LC","type":"多选","q":"下列行为不属于资产管理业务禁止行为的有 ()。","options":["为规避监管的期货业务提供交易便利","投资决策错误导致资产管理计划业绩回报处于同类产品末端","系统故障导致交易无法达成，造成资产管理计划财产受损","向投资者返还管理费"],"answer":"BC","explain":"答案解析：证券公司、托管人、投资顾问及相关从业人员从事私募资产管理业务，不得有下列行为：(1)为违法或者规避监管的证券期货业务活动提供交易便利 (A 选项不符合题意)；(2)直接或者间接向投资者返还管理费 (D 选项不符合题意)。B 选项符合题意，是资产管理业务中可能发生的正常商业风险，不属于禁止行为。C 选项符合题意，属于技术风险或操作风险事件，不属于禁止行为。故本题选 BC 选项。"},{"id":"jun-law2-50","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于子公司法律地位的说法，正确的有 ()。","options":["子公司具有独立的法人资格","子公司从事经营活动的民事责任由其母公司承担","子公司拥有独立的组织机构","子公司可以依法独立从事生产经营活动"],"answer":"ACD","explain":"答案解析：B 选项错误，子公司具有法人资格，依法独立承担民事责任 (并非\"由其母公司承担\") 。故本题选 ACD 选项。"},{"id":"jun-law2-51","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于证券公司合规管理的说法，错误的有() 。","options":["证券公司首次开展行业已有可借鉴先例的业务，不需要进行新产品、新业务的评估与决策","经过合规负责人审核的材料，其他相关高级管理人员不需再对其中的内容负责","合规负责人发现公司存在合规风险隐患的，应依照公司章程及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改","合规负责人直接向总经理办公会负责"],"answer":"ABD","explain":"答案解析：A 选项错误，证券公司应当建立新产品、新业务评估与决策机制，合规负责人和合规部门应当对新产品、新业务发表合规审查意见，证券公司在进行相关决策时，应当充分考虑和采纳合规审查意见。B 选项错误，中国证监会及其派出机构、自律组织要求对证券公司报送的申请材料或报告进行合规审查的，合规负责人应当审查，并在该申请材料或报告上签署合规审查意见。其他相关高级管理人员等应当对申请材料或报告中基本事实和业务数据的真实性、准确性及完整性负责。C选项正确，合规负责人发现证券公司存在违法违规行为或合规风险隐患的，应当依照公司章程规定及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改。D 选项错误，合规负责人是高级管理人员，直接向董事会负责。故本题选 ABD 选项。"},{"id":"jun-law2-52","subject":"law","source":"6月押题 LC","type":"多选","q":"下列关于境外有关部门以涉及恐怖活动为由要求证券公司提供协助时的做法，正确的有 ()。","options":["证券公司不得自行采取冻结措施","证券公司可以直接提供客户身份信息及交易信息","证券公司可以自行决定是否提供协助","证券公司应当告知对方通过外交途径或者司法协助途径提出请求"],"answer":"AD","explain":"答案解析：境外有关部门以涉及恐怖活动为由，要求证券公司冻结相关资产、提供客户身份信息及交易信息的，证券公司应当告知对方通过外交途径或者司法协助途径提出请求(C 选项错误、D 选项正确)；不得擅自采取冻结措施(A 选项正确)，不得擅自提供客户身份信息及交易信息 (B 选项错误)。故本题选 AD 选项。"},{"id":"jun-law2-53","subject":"law","source":"6月押题 LC","type":"多选","q":"下列符合欺诈发行证券罪的刑事立案追诉标准，应予立案追诉的有 ()。","options":["非法募集资金金额在 500 万元以上的","伪造、变造国家机关公文、有效证明文件或者相关凭证、单据的","利用募集的资金进行违法活动的","向负有金融监督管理职责的单位或者人员行贿的"],"answer":"BCD","explain":"答案解析：涉嫌下列情形之一的，应予立案追诉：(1)非法募集资金金额在 1000 万元以上的(A 选项错误, 并非 500 万元) ;(2)为欺诈发行证券而伪造、变造国家机关公文、有效证明文件或者相关凭证、单据的 (B 选项正确)；(3)募集的资金全部或者主要用于违法犯罪活动的 (C 选项正确)；(4)为欺诈发行证券向负有金融监督管理职责的单位或者人员行贿的 (D 选项正确) 。故本题选 BCD 选项。"},{"id":"jun-law2-54","subject":"law","source":"6月押题 LC","type":"多选","q":"下列符合《证券分析师执业行为准则》的行为有() 。","options":["证券分析师最多同时在两家机构执业","证券分析师应当通过个人邮件方式向特定客户提供尚未发布的证券研究报告内容和观点","证券分析师不得担任上市公司的独立董事","证券分析师制作发布证券研究报告、提供相关服务，应当向客户进行必要的风险提示"],"answer":"CD","explain":"答案解析：A 选项不符合题意，证券分析师只能与一家经营机构签订劳动合同，不得以任何形式同时在 2 家或 2 家以上的机构执业。B 选项不符合题意，证券分析师应当通过公司规定的系统平台发布证券研究报告，不得通过短信、个人邮件等方式向特定客户、公司内部部门提供或泄露尚未发布的证券研究报告内容和观点。C 选项符合题意，证券分析师不得在公司内部或外部兼任有损其独立性与客观性的其他职务，包括担任上市公司的独立董事。D 选项符合题意，证券分析师制作发布证券研究报告、提供相关服务，应当向客户进行必要的风险提示。故本题选 CD 选项。"},{"id":"jun-law2-55","subject":"law","source":"6月押题 LC","type":"多选","q":"融资融券标的证券为交易型开放式指数基金的，应当符合下列 ()条件。","options":["上市交易超过 5 个交易日","最近 5 个交易日内的日平均资产规模不低于 5 亿元","过去 3 个月内，日均涨跌幅平均值与基准指数涨跌幅平均值的偏离值未超过4%","基金持有户数不少于 2000 户"],"answer":"ABD","explain":"答案解析：标的证券为交易型开放式指数基金 (ETF)的，应当符合下列条件：(1)上市交易超过 5 个交易日 (A 选项正确)；(2)最近 5 个交易日内的日平均资产规模不低于5 亿元(B 选项正确)；(3)基金持有户数不少于 2000 户 (D 选项正确)；(4)交易所规定的其他条件。C 选项错误，属于标的证券为股票的条件。故本题选ABD 选项。"},{"id":"jun-law2-56","subject":"law","source":"6月押题 LC","type":"多选","q":"客户申请开展融资融券业务要在证券公司开立实名() 。","options":["客户信用交易担保证券账户","信用证券账户","客户信用交易担保资金账户","信用资金台账"],"answer":"BD","explain":"答案解析：A、C 选项错误，证券公司经营融资融券业务，应当以自己的名义，在证券登记结算机构分别开立融券专用证券账户、客户信用交易担保证券账户、信用交易证券交收账户和信用交易资金交收账户；以自己的名义在商业银行分别开立融资专用资金账户和客户信用交易担保资金账户。B、D 选项正确，客户通过证券公司开展融资融券业务，应当在证券公司开立实名信用资金台账和信用证券账户，在指定的商业银行开立实名信用资金账户。故本题选 BD 选项。"},{"id":"jun-law2-57","subject":"law","source":"6月押题 LC","type":"多选","q":"积极培育中国特色金融文化，要做到 ()。","options":["诚实守信，不逾越底线","以义取利，不唯利是图","稳健审慎，不急功近利","守正创新，不脱实向虚"],"answer":"ABCD","explain":"答案解析：一要诚实守信，不逾越底线 (A 选项正确)。二要以义取利，不唯利是图 (B 选项正确)。三要稳健审慎，不急功近利 (C 选项正确)。四要守正创新，不脱实向虚(D 选项正确)。五要依法合规，不胡作非为。故本题选 ABCD 选项。"},{"id":"jun-law2-58","subject":"law","source":"6月押题 LC","type":"多选","q":"国务院证券监督管理机构有权采取下列 ()措施，对证券公司的业务活动、财务状况、经营管理情况进行检查。","options":["询问证券公司的董事、监事、工作人员，要求其对有关检查事项作出说明","进入证券公司的办公场所或者营业场所进行检查","查阅、复制与检查事项有关的文件、资料，对与检查相关的文件、资料、电子设备全部予以封存","检查证券公司的计算机信息管理系统，复制有关数据资料"],"answer":"ABD","explain":"答案解析：国务院证券监督管理机构有权采取下列措施，对证券公司的业务活动、财务状况、经营管理情况进行检查：(1)询问证券公司的董事、监事、工作人员，要求其对有关检查事项作出说明 (A 选项符合题意)；(2)进入证券公司的办公场所或者营业场所进行检查(B 选项符合题意)；(3)查阅、复制与检查事项有关的文件、资料，对可能被转移、隐匿或者毁损的文件、资料、电子设备予以封存 (C选项不符合题意，并非\"全部予以封存\")；(4)检查证券公司的计算机信息管理系统，复制有关数据资料 (D 选项符合题意)。故本题选 ABD 选项。"},{"id":"jun-law2-59","subject":"law","source":"6月押题 LC","type":"多选","q":"关于操纵证券期货市场的刑事责任，下列说法正确的有 ()。","options":["本罪的主体是一般主体，凡达到刑事责任年龄并具有刑事责任能力的自然人均可成为本罪主体","本罪的主观方面为故意","本罪侵害了国家证券、期货管理制度和投资者的合法权益","本罪的主体为一般主体，单位不能成为本罪的犯罪主体"],"answer":"ABC","explain":"答案解析：操作证券、期货市场罪的主体为一般主体。凡达到刑事责任年龄并且具有刑事责任能力的自然人均可成为本罪主体 (A 选项正确)；单位亦能构成本罪 (D选项错误)；该罪的主观方面由故意构成 (B 选项正确)；该罪的客体是侵犯国家证券、期货管理制度和投资者合法权益 (C 选项正确)，该罪的客观方面表现为利用其资金、信息等优势或者滥用职权操纵市场、制造市场假象，影响证券、期货交易价格或者证券、期货交易量，情节严重的行为。故本题选 ABC 选项。"},{"id":"jun-law2-60","subject":"law","source":"6月押题 LC","type":"多选","q":"公司章程未作其他规定的情况下，下列不属于公司高级管理人员的有 ()。","options":["副董事长","监事长","人力资源负责人","财务负责人"],"answer":"ABC","explain":"答案解析：高级管理人员，是指公司的经理、副经理、财务负责人(D 选项不符合题意)，上市公司董事会秘书和公司章程规定的其他人员。故本题选 ABC 选项。"},{"id":"jun-law2-61","subject":"law","source":"6月押题 LC","type":"多选","q":"公司应当向聘用的会计师事务所提供真实、完整的() ， 不得拒绝、 隐匿、谎报。","options":["会计凭证","会计账簿","财务会计报告","其他会计资料"],"answer":"ABCD","explain":"答案解析：公司应当向聘用的会计师事务所提供真实、完整的会计凭证 (A 选项正确)、会计账簿 (B 选项正确)、财务会计报告 (C 选项正确)及其他会计资料 (D 选项正确)，不得拒绝、隐匿、谎报。故本题选 ABCD 选项。"},{"id":"jun-law2-62","subject":"law","source":"6月押题 LC","type":"多选","q":"根据证券投资咨询人员注册登记要求的有关规定，下列关于证券投资咨询人员注册登记要求，正确的有() 。","options":["注册登记为证券投资顾问的人员，其申请从事的证券业务类别为证券投资咨询业务 (投资顾问)","证券投资咨询人员应在中国证券业协会注册登记","证券投资咨询机构从业人员可以同时在两家或两家以上的证券经营机构执业","注册登记为证券分析师的人员，其申请从事的证券业务类别为证券投资咨询业务 (分析师)"],"answer":"ABD","explain":"答案解析：C 选项错误，证券投资咨询机构人员只能与一家证券经营机构签订劳动合同，不得以任何形式同时在两家或两家以上证券经营机构执业。故本题选 ABD 选项。"},{"id":"jun-law2-63","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券市场禁入规定》，下列属于中国证监会及其派出机构可以采取证券市场禁入措施的适用对象的有 ()。","options":["证券发行人的董事、监事、高级管理人员","证券服务机构、债券受托管理人的董事、监事、高级管理人员","编造、传播虚假信息或者误导性信息的有关责任人员","执法单位及相关自律组织的工作人员"],"answer":"ABCD","explain":"答案解析：根据《证券市场禁入规定》，下列人员违反法律、行政法规或者中国证监会有关规定，情节严重的，执法单位可以根据情节严重的程度，采取证券市场禁入措施：(1)证券发行人的董事、监事、高级管理人员，其他信息披露义务人或其他信息披露义务人的董事、监事、高级管理人员，证券发行人、其他信息披露义务人持股 5%以上的股东、实际控制人，证券发行人、其他信息披露义务人持股 5%以上的股东、实际控制人的董事、监事、高级管理人员，或者执法单位认定的其他对欺诈发行或信息披露违法行为直接负责的主管人员或其他直接责任人员 (A 选项符合题意)；(2)证券服务机构、债券受托管理人的董事、监事、高级管理人员、合伙人、负责人及工作人员，证券服务机构、债券受托管理人的股东、实际控制人或者股东、实际控制人的董事、监事、高级管理人员 (B 选项符合题意)；(3)编造、传播虚假信息或者误导性信息的有关责任人员 (C 选项符合题意)；(4)执法单位及相关自律组织的工作人员 (D 选项符合题意)。故本题选 ABCD 选项。"},{"id":"jun-law2-64","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司信息系统安全的说法，正确的有 ()。","options":["证券公司应当结合公司发展战略、市场交易规模等因素定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要","证券公司应当确保重要信息系统具备可审计功能，并可以根据监管部门的要求转换、提供数据","证券公司应当建立健全信息系统安全监测机制，设定监测指标并持续监测重要信息系统的运行状况","证券公司重要信息系统计划停止使用的，可不用开展技术和业务影响评估"],"answer":"ABC","explain":"答案解析：A 选项正确，证券公司应当结合公司发展战略、市场交易规模等因素定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要。B 选项正确，证券公司应当确保重要信息系统具备可审计功能，并可以根据监管部门的要求转换、提供数据。C 选项正确，证券公司应当建立健全信息系统安全监测机制，设定监测指标并持续监测重要信息系统的运行状况。证券公司应当指定专人跟踪监测发现的异常情形，及时处置并定期开展评估分析。D 选项错误，证券公司重要信息系统计划停止使用的，应当开展 (并非\"可不用开展\")技术和业务影响评估，制定完整的系统停用和数据迁移保管方案，并组织必要的评审及停用后的安全检查。故本题选 ABC 选项。"},{"id":"jun-law2-65","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，下列关于履职限制的做法，错误的有 ()。","options":["甲证券公司上海分公司负责人张某，兼职担任上海某投资管理有限公司的法定代表人","乙证券公司大连某证券营业部负责人王某，在任职期间从事其他经营性活动的行为","丙证券公司总经理李某在任职期间担任了深圳市某集团有限公司等 4 家公司董事","丁证券公司副总经理赵某在公司参股的私募基金公司担任董事"],"answer":"ABC","explain":"答案解析：A、B、C选项错误，证券基金经营机构的高级管理人员(李某)、部门负责人和分支机构负责人 (张某和王某)，不得在证券基金经营机构参股或者控股的公司以外的营利性机构兼职。D 选项正确，证券基金经营机构的高级管理人员 (赵某)在证券基金经营机构参股的公司仅可兼任董事、监事，且数量不得超过 2 家。故本题选 ABC 选项。"},{"id":"jun-law2-66","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司信用风险管理指引》，证券公司应当建立常态化的信用风险压力测试机制，并根据 ()在压力测试中充分考虑信用风险因素。","options":["市场变化情况","业务变化情况","风险水平情况","信息治理情况"],"answer":"ABC","explain":"答案解析：证券公司应当根据全面风险管理要求，建立常态化的信用风险压力测试机制，并根据市场变化 (A 选项正确)、业务变化 (B 选项正确)和风险水平情况 (C 选项正确)，在压力测试中充分考虑信用风险因素。D 选项错误，信息治理是风险管理和内控的基础性工作，虽然良好的信息治理有助于压力测试数据的准确性，但它本身不是启动或调整压力测试的直接条件。故本题选 ABC 选项。"},{"id":"jun-law2-67","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司全面风险管理规范》，下列关于证券公司风险文化的说法，错误的有 ()。","options":["仅在总部推行稳健的风险文化","在分支机构推行保守的风险文化","形成与本公司相适应的风险管理理念","形成仅与行业相适应的风险管理理念"],"answer":"ABD","explain":"答案解析：证券公司应当在全公司推行稳健的风险文化 (A、B 选项错误)，形成与本公司相适应的风险管理理念 (C 选项正确、D 选项错误)、价值准则、职业操守，建立培训、宣导和监督机制并纳入考核体系。故本题选 ABD 选项。"},{"id":"jun-law2-68","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司全面风险管理规范》，全面风险管理体系应当包括 ()。","options":["可操作的管理制度、健全的组织架构","专业的人才队伍","可靠的信息技术系统、量化的风险指标体系","有效的风险应对机制"],"answer":"ABCD","explain":"答案解析：全面风险管理体系应包括可操作的管理制度、健全的组织架构 (A 选项符合题意)、可靠的信息技术系统、量化的风险指标体系 (C 选项符合题意)、专业的人才队伍 (B 选项符合题意)、有效的风险应对机制 (D 选项符合题意)。故本题选 ABCD 选项。"},{"id":"jun-law2-69","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司风险处置条例》，下列关于禁止参与处置证券公司风险工作的机构或人员的情形，正确的有 ()。","options":["曾受过刑事处罚","因严重违法行为受到行政处罚已逾 3 年","涉嫌严重违法正在被行政管理部门立案稽查","涉嫌犯罪正在被立案侦查、起诉"],"answer":"ACD","explain":"答案解析：有下列情形之一的机构或者人员，禁止参与处置证券公司风险工作：(1)曾受过刑事处罚 (A 选项正确)或者涉嫌犯罪正在被立案侦查、起诉 (D 选项正确)；(2)涉嫌严重违法正在被行政管理部门立案稽查 (C 选项正确)或曾因严重违法行为受到行政处罚未逾 3 年 (B 选项错误)；(3)仍处于证券市场禁入期；(4)内部控制薄弱、存在重大风险隐患；(5)与被处置证券公司处置事项有利害关系；(6)国务院证券监督管理机构认定不宜参与处置证券公司风险工作的其他情形。故本题选 ACD 选项。"},{"id":"jun-law2-70","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券公司分类监管规定》，某证券公司进行分类评价，为了全面准确评估自身风险管理能力，该公司需要准备本公司上一年度 5 月 1 日至本年度 4月 30 日的相关风险管理能力的数据资料，必须具备的数据资料包括 ()方面的内容。","options":["资本充足、公司治理与合规管理","全面风险管理、信息技术管理","客户权益保护、信息披露","经营管理能力、创新能力"],"answer":"ABC","explain":"答案解析：证券公司分类评价的评价指标体系：风险管理能力主要根据资本充足、公司治理与合规管理 (A 选项正确)、全面风险管理、信息技术管理 (B 选项正确)、客户权益保护、信息披露 (C 选项正确)六类评价指标进行评价，体现证券公司对流动性风险、合规风险、市场风险、信用风险、技术风险及操作风险等管理能力。D 选项错误，经营管理能力、创新能力虽然与公司竞争力和发展相关，但在分类评价框架下，它们通常被纳入\"市场竞争力\"的评价范畴，而非\"风险管理能力\"的指标体系中。故本题选 ABC 选项。"},{"id":"jun-law2-71","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券法》，下列关于上市公司收购相关法律责任的说法，错误的有 ()。","options":["收购人的控股股东利用上市公司收购，损害被收购公司及其股东的合法权益，应当由被收购公司承担赔偿责任","收购人利用上市公司收购，损害被收购公司股东的合法权益，无需承担赔偿责任","收购人未按照规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处以罚款","收购人控股股东未按照规定履行上市公司收购的公告、发出收购要约义务的，给予警告，并处以罚款"],"answer":"AB","explain":"答案解析：A、B 选项错误，收购人及其控股股东、实际控制人利用上市公司收购，给被收购公司及其股东造成损失的，应当依法承担赔偿责任。C、D 选项正确，收购人未按照《证券法》的规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处以 50 万元以上 500 万元以下的罚款。对直接负责的主管人员和其他直接责任人员 (如控股股东)给予警告，并处以 20 万元以上 200 万元以下的罚款。故本题选 AB 选项。"},{"id":"jun-law2-72","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《证券法》，下列关于上市公司收购的说法，正确的有()。","options":["在及时公告并载明具体变更事项的情况下，收购人可以缩短收购期限","在及时公告并载明具体变更事项的情况下，收购人可以减少预定收购股份数额","在收购要约确定的承诺期限内，收购人不得撤销其收购要约","收购人需要变更收购要约的，应当及时公告，载明具体变更事项，且不得降低收购价格"],"answer":"CD","explain":"答案解析：在收购要约确定的承诺期限内，收购人不得撤销其收购要约 (C 选项正确)。收购人需要变更收购要约的，应当及时公告，载明具体变更事项，且不得存在下列情形：(1)降低收购价格 (D 选项正确)；(2)减少预定收购股份数额 (B 选项错误)；(3)缩短收购期限 (A 选项错误)；(4)国务院证券监督管理机构规定的其他情形。故本题选 CD 选项。"},{"id":"jun-law2-73","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《融资融券合同必备条款》，下列关于融资融券合同所包含内容的说法，正确的有 ()。","options":["约定融资融券交易涉及的权益处理事项","约定融资融券特定的财产信托关系","载明开立信用业务相关账户的有关内容","订立合同的目的和依据"],"answer":"ABCD","explain":"答案解析：融资融券业务合同的基本内容应包含：(1)订立合同的目的和依据 (D 选项正确)。(2)合同应载明开立信用业务相关账户的有关内容 (C 选项正确)。(3)合同应约定融资融券特定的财产信托关系，即信托目的、信托财产范围、信托的成立和生效、信托财产的管理、信托财产的处分及信托的终止 (B 选项正确) 。(4)约定融资融券交易所涉及的权益处理事项 (A 选项正确)。故本题选 ABCD 选项。"},{"id":"jun-law2-74","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《关于加强对利用\"荐股软件\"从事证券投资咨询业务监管的暂行规定》，具备 ()功能的软件产品、软件工具或者终端设备是\"荐股软件\"。","options":["提供具体证券投资品种选择建议","提供具体证券投资品种的买卖时机建议","提供涉及具体证券投资品种的投资分析意见，或者预测具体证券投资品种的价格走势","具备证券信息汇总或者证券投资品种历史数据统计功能"],"answer":"ABC","explain":"答案解析：荐股软件是指具备下列一项或多项证券投资咨询服务功能的软件产品、软件工具或者终端设备：(1)提供涉及具体证券投资品种的投资分析意见，或者预测具体证券投资品种的价格走势 (C 选项正确)；(2)提供具体证券投资品种选择建议 (A 选项正确)；(3)提供具体证券投资品种的买卖时机建议 (B 选项正确) ;(4)提供其他证券投资分析、预测或者建议。D 选项错误，具备证券信息汇总或者证券投资品种历史数据统计功能，但不具备上述第一点至第四点所列功能的软件产品、软件工具或者终端设备，不属于\"荐股软件\"。故本题选 ABC 选项。"},{"id":"jun-law2-75","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《关于规范债券市场参与者债券交易业务的通知》，债券交易包括 ()等符合规定的债券交易业务。","options":["现券买卖","债券回购","债券远期","债券借贷"],"answer":"ABCD","explain":"答案解析：债券交易包括现券买卖 (A 选项符合题意)、债券回购(B 选项符合题意)、债券远期 (C 选项符合题意)、债券借贷 (D 选项符合题意)等符合规定的债券交易业务。故本题选 ABCD 选项。"},{"id":"jun-law2-76","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《公司法》，下列关于虚假出资、抽逃出资法律责任的说法，正确的有() 。","options":["处以虚假出资金额或者所抽逃出资金额的 5%以上 15%以下的罚款","违法行为主体包括公司发起人、股东","由公司登记机关责令改正","撤销公司登记或者吊销营业执照"],"answer":"ABC","explain":"答案解析：(1)抽逃出资的法律责任。公司的发起人、股东在公司成立后，抽逃其出资的，由公司登记机关责令改正，处以所抽逃出资金额 5%以上 15%以下的罚款；对直接负责的主管人员和其他直接责任人员处以 3 万元以上 30 万元以下的罚款 (A、C选项正确)。(2)虚假出资的法律责任。公司的发起人、股东虚假出资，未交付或者未按期交付作为出资的货币或者非货币财产的，由公司登记机关责令改正，可以处以 5万元以上 20 万元以下的罚款；情节严重的，处以虚假出资或未出资金额5%以上15%以下的罚款 (B、C 选项正确)；对直接负责的主管人员和其他直接责任人员处以 1 万元以上 10 万元以下的罚款。D 选项错误，虚假出资、抽逃出资的条款中并未规定\"撤销登记或吊销执照\"这一项处罚。故本题选 ABC 选项。"},{"id":"jun-law2-77","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《公司法》，股份有限公司募集设立是指由发起人认购公司应发行股份的一部分，其余股份通过募集而设立公司，其中募集的方式包括 ()。","options":["向社会公开募集","发起募集","向特定对象募集","内部募集"],"answer":"AC","explain":"答案解析：股份有限公司的设立，可以采取发起设立或者募集设立的方式。A、C 选项正确，募集设立，是指由发起人认购设立公司时应发行股份的一部分，其余股份向社会公开募集或者向特定对象募集而设立公司。发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。故本题选 AC 选项。"},{"id":"jun-law2-78","subject":"law","source":"6月押题 LC","type":"多选","q":"根据《非上市公众公司监督管理办法》，对挂牌公司进行持续监管，防范风险，维护证券市场秩序的监管主体包括 ()。","options":["国务院有关部门","商业银行","地方人民政府","中国证监会"],"answer":"ACD","explain":"答案解析：中国证监会会同国务院有关部门 (A、D 选项正确)、地方人民政府 (C 选项正确)，依照法律法规和国务院有关规定，各司其职，分工协作，对挂牌公司进行持续监管，防范风险，维护证券市场秩序。B 选项错误，商业银行是金融机构，不具备对非上市公众公司进行证券市场监管的法定职责。故本题选 ACD 选项。"},{"id":"jun-law2-79","subject":"law","source":"6月押题 LC","type":"多选","q":"法律关系的特征主要有 () 。","options":["以权利和义务为内容的一种社会关系","法律主体之间的一种社会关系","以法律规范为基础形成的一种社会关系","社会组织之间的一种市场关系"],"answer":"ABC","explain":"答案解析：法律关系的特征：(1)法律关系是一种以法律规范为基础形成的社会关系 (C 选项正确)；(2)法律关系是以权利和义务为内容的社会关系 (A 选项正确)；(3)法律关系是法律主体之间的社会关系 (B 选项正确) 。D 选项错误，法律关系的主体不仅包括\"社会组织\"，还包括自然人、国家等。法律关系是社会关系，其内容不仅限于\"市场关系\"，因此，此选项将法律关系限定在\"社会组织\"之间的\"市场关系\"，大大缩小了其范围。故本题选 ABC 选项。"},{"id":"jun-law2-80","subject":"law","source":"6月押题 LC","type":"多选","q":"对违反《公司债券发行与交易管理办法》的， 中国证监会可以对相关机构和人员采取的监管措施有 ()。","options":["责令公开说明","监管谈话","责令定期报告","出具警示函"],"answer":"ABCD","explain":"答案解析：对违反法律法规及《公司债券发行与交易管理办法》规定的机构和人员，中国证监会可以对相关机构和人员采取责令改正、监管谈话 (B 选项正确)、出具警示函(D 选项正确)、责令公开说明 (A 选项正确)、责令定期报告 (C 选项正确)等相关监管措施；依法应予行政处罚的，依照《证券法》 《行政处罚法》等法律法规和中国证监会的有关规定进行处罚；涉嫌犯罪的，依法移送司法机关，追究其刑事责任。故本题选 ABCD 选项。"},{"id":"jun-law2-81","subject":"law","source":"6月押题 LC","type":"判断","q":"证券投资顾问不得通过广播、电视、网络、报刊等公众媒体，作出买入、卖出或者持有具体证券的投资建议。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。证券投资顾问不得通过广播、电视、网络、报刊等公众媒体，作出买入、卖出或者持有具体证券的投资建议。"},{"id":"jun-law2-82","subject":"law","source":"6月押题 LC","type":"判断","q":"证券经纪人是指接受证券公司的委托，代理其从事客户招揽和客户服务等活动的证券公司以外的自然人或法人。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券经纪人是指接受证券公司的委托，代理其从事客户招揽和客户服务等活动的证券公司以外的自然人 (不包括法人)。"},{"id":"jun-law2-83","subject":"law","source":"6月押题 LC","type":"判断","q":"证券经纪人是证券从业人员。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。证券经纪人为证券从业人员。从业人员是指在证券基金经营机构从事证券基金业务和相关管理工作的人员，包括从事证券经纪、证券投资咨询、与证券交易及证券投资活动有关的财务顾问、证券承销与保荐、证券融资融券、证券自营、证券做市交易、证券资产管理等业务和相关管理工作的人员。"},{"id":"jun-law2-84","subject":"law","source":"6月押题 LC","type":"判断","q":"证券金融公司应当按照规定固定比例来提取风险准备金。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券金融公司应当每年按照税后利润的 10%提取风险准备金。中国证监会可以根据防范证券金融公司风险的需要，对提取比例进行调整。"},{"id":"jun-law2-85","subject":"law","source":"6月押题 LC","type":"判断","q":"证券基金经营机构应当委托提供港股投资顾问服务的香港机构直接执行投资指令。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券基金经营机构应当履行主动管理职责，自主作出投资决策，不得委托提供港股投资顾问服务的中国香港机构直接执行投资指令，证券基金经营机构作为基金管理人依法应当承担的责任不因委托而免除。"},{"id":"jun-law2-86","subject":"law","source":"6月押题 LC","type":"判断","q":"证券公司应对客户参与不同的业务进行不同的风险等级划分，同一客户在证券公司不应有唯一的风险等级。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。对于新建立业务关系的客户，证券公司应在建立业务关系后的 10 个工作日内，按照收集信息、筛选分析信息、初评和复评的流程，划分其风险等级，同一客户在证券公司应有唯一的风险等级。"},{"id":"jun-law2-87","subject":"law","source":"6月押题 LC","type":"判断","q":"证券公司应当将敏感信息所涉公司或证券列入限制名单。限制名单属于高度保密名单。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券公司采取信息隔离和披露措施难以有效管理利益冲突的，应当将敏感信息所涉公司或证券列入限制名单。观察名单 (并非\"限制名单\")属于高度保密的名单。"},{"id":"jun-law2-88","subject":"law","source":"6月押题 LC","type":"判断","q":"证券公司可以为单一投资者设立单一资产管理计划，也可以为多个投资者设立集合资产管理计划。集合资产管理计划的投资者人数不少于 50 人，不超过100人。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券公司可以为单一投资者设立单一资产管理计划，也可以为多个投资者设立集合资产管理计划。集合资产管理计划的投资者人数不少于 2 人，不得超过 200 人。"},{"id":"jun-law2-89","subject":"law","source":"6月押题 LC","type":"判断","q":"证券公司借助信息技术手段从事证券基金业务活动的，可以委托信息技术服务机构提供产品或服务，应当签署协议明确双方权利义务，在协议明确的范围内，证券公司的相应责任可以减轻但不得免除。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券公司借助信息技术手段从事证券基金业务活动的，可以委托信息技术服务机构提供产品或服务，但证券公司依法应当承担的责任不因委托而免除或减轻 (并非\"可以减轻\")。"},{"id":"jun-law2-90","subject":"law","source":"6月押题 LC","type":"判断","q":"证券公司代销证券期限最长不得超过 60 日。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券的代销、包销期限最长不得超过 90 日 (并非\"60 日\") 。"},{"id":"jun-law2-91","subject":"law","source":"6月押题 LC","type":"判断","q":"证券包销是指证券公司将发行人的证券按照协议全部购入或者在承销期结束时将售后剩余证券全部退还给发行人的承销方式。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。证券包销，是指证券公司将发行人的证券按照协议全部购入，或者在承销期结束时将售后剩余证券全部自行购入的承销方式。证券代销，是指证券公司代发行人发售证券，在承销期结束时，将未售出的证券全部退还给发行人的承销方式。题干后半句混淆了证券包销和证券代销的概念。"},{"id":"jun-law2-92","subject":"law","source":"6月押题 LC","type":"判断","q":"在证券公司经营过程中，证券公司的债权人将其债权转为证券公司股权的，不受货币出资限制。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。证券公司的股东应当用货币或证券公司经营必需的非货币财产出资。证券公司股东的非货币财产出资总额不得超过证券公司注册资本的 30%。但是，在证券公司经营过程中，证券公司的债权人将其债权转为证券公司股权的，不受前述规定的限制。"},{"id":"jun-law2-93","subject":"law","source":"6月押题 LC","type":"判断","q":"在证券公司从事基金产品销售需要具有基金从业资格证。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。未经注册，任何单位或者个人不得从事基金销售业务。基金销售机构应当强化人员资质管理，确保基金销售人员具有基金从业资格。"},{"id":"jun-law2-94","subject":"law","source":"6月押题 LC","type":"判断","q":"在融资融券业务当中，融资专用资金账户是客户在指定商业银行开立的用于记载客户交存的担保资金的明细数据的账户。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。融资专用资金账户：用于存放证券公司拟向客户融出的资金及客户归还的资金。客户信用资金账户：客户在指定的商业银行开立的用于记载客户交存的担保资金的明细数据的账户。"},{"id":"jun-law2-95","subject":"law","source":"6月押题 LC","type":"判断","q":"有限责任公司的董事任期可以不由公司章程规定，但每届任期不得超过三年。董事任期届满，连选可以连任。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。董事任期由公司章程规定，但每届任期不得超过 3 年。董事任期届满，连选可以连任。"},{"id":"jun-law2-96","subject":"law","source":"6月押题 LC","type":"判断","q":"有限合伙人变成普通合伙人，企业也变成普通合伙企业。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。有限合伙企业仅剩普通合伙人的，转为普通合伙企业。若其中仍然有其他有限合伙人，则仍然是一个有限合伙企业。"},{"id":"jun-law2-97","subject":"law","source":"6月押题 LC","type":"判断","q":"王某在 2020 年 3 月因证券违法行为受到过行政处罚，2022 年 9 月其参与内幕交易获利 30 万元，其行为应予立案追诉。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。内幕交易获利或者避免损失数额在 25 万元以上，并且在 2 年内因证券、期货违法行为受过行政处罚的(2020 年 3 月至 2022 年 9 月已经超出 2 年的限制)，应予立案追诉。"},{"id":"jun-law2-98","subject":"law","source":"6月押题 LC","type":"判断","q":"设立管理公开募集基金的基金管理公司应当具备的条件之一是所有股东应当具有经营金融业务或者管理金融机构的良好业绩、良好的财务状况和社会信誉，资产规模达到国务院规定的标准，最近 3 年没有违法记录。()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。基金管理公司的设立条件：(1)有符合《证券投资基金法》和《公司法》规定的章程；(2)注册资本不低于人民币 1 亿元，且必须为实缴货币资本；(3)主要股东 (是主要股东而非所有股东)应当具有经营金融业务或管理金融机构的良好业绩、良好的财务状况和社会信誉，资产规模达到国务院规定的标准，最近 3 年没有违法记录；(4)取得基金从业资格的人员达到法定人数；(5)董事、监事、高级管理人员具备相应的任职条件；(6)有符合要求的营业场所、安全防范设施和与基金管理业务有关的其他设施；(7)有良好的内部治理结构、完善的内部稽核监控制度、风险控制制度；(8)法律、行政法规规定的和经国务院批准的国务院证券监督管理机构规定的其他条件。"},{"id":"jun-law2-99","subject":"law","source":"6月押题 LC","type":"判断","q":"期货交易者未按照要求提供信息的，期货经营机构应当告知其后果，并按照规定拒绝提供服务。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。交易者在参与期货交易和接受服务时，应当按照期货经营机构明示的要求提供上述所列真实信息。拒绝提供或者未按照要求提供信息的，期货经营机构应当告知其后果，并按照规定拒绝提供服务。"},{"id":"jun-law2-100","subject":"law","source":"6月押题 LC","type":"判断","q":"普通投资者应至少在信息告知、风险警示、适当性匹配三个方面享有特别保护。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。【知识】(1)信息告知：告知的信息真实、准确、完整，采取通俗易懂的方式介绍；(2)风险警示：进行充分的风险警示，销售高风险产品或服务时，在营业网点向普通投资者进行告知、警示的，应全过程录音录像等；(3)适当性匹配：提供明确具体的适当性匹配意见，并通过书面或电子方式进行留痕。"},{"id":"jun-law2-101","subject":"law","source":"6月押题 LC","type":"判断","q":"某证券资产管理公司投资经理因业绩不佳，转任行业研究员岗。该证券资产管理公司应当对该投资经理进行离任审查。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，投资经理离任的，证券基金经营机构应当对其进行离任审查，并自离任之日起2个月内形成离任审查报告，以存档备查。"},{"id":"jun-law2-102","subject":"law","source":"6月押题 LC","type":"判断","q":"合伙企业设立时，合伙协议应由全体合伙人协商一致且必须以书面形式订立。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。合伙企业设立时，合伙协议应由全体合伙人协商一致，且必须以书面形式订立。"},{"id":"jun-law2-103","subject":"law","source":"6月押题 LC","type":"判断","q":"根据金融债券发行与承销信息披露的有关规定，对影响发行人履行债务的重大事件，发行人应在第一时间向中国证监会报告。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。对影响发行人履行债务的重大事件，发行人应在第一时间向中国人民银行报告，并按照中国人民银行指定的方式披露 (并非\"中国证监会\") 。"},{"id":"jun-law2-104","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券期货投资者适当性管理办法》， 自律组织认定的高风险产品或者服务，经营机构应当审慎评估其风险等级。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。产品或者服务存在下列因素的，应当审慎评估其风险等级：(1)存在本金损失的可能性，因杠杆交易等因素容易导致本金大部分或全部损失的产品或服务；(2)产品或服务的流动变现能力，因无公开交易市场、参与投资者少等因素导致难以在短期内以合理价格顺利变现的产品或服务；(3)产品或服务的可理解性，因结构复杂、不易估值等因素导致普通人难以理解其条款和特征的产品或服务；(4)产品或服务的募集方式，涉及面广、影响力大的公募产品或相关服务；(5)产品或服务的跨境因素，存在市场差异、适用境外法律等情形的跨境发行或交易的产品或服务；(6)自律组织认定的高风险产品或服务；(7)其他可能构成投资风险的因素。"},{"id":"jun-law2-105","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，合规负责人发现公司存在合规风险隐患的，应当依照公司章程规定及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。合规负责人发现证券公司存在违法违规行为或合规风险隐患的，应当按照如下办法处理：依照公司章程规定及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改；合规负责人应当同时督促公司及时向中国证监会相关派出机构报告；公司未及时报告的，应当直接向中国证监会相关派出机构报告；有关行为违反行业规范和自律规则的，还应当向有关自律组织报告。"},{"id":"jun-law2-106","subject":"law","source":"6月押题 LC","type":"判断","q":"根据《证券公司风险处置条例》，被撤销证券业务许可的证券公司可以暂停经营证券业务，按照公司便利的原则将客户安置到其他证券公司，安置过程中相关各方应当采取必要措施保证客户证券交易的正常进行。()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。被撤销证券业务许可的证券公司应当停止经营证券业务，按照客户自愿 (并非公司便利)的原则将客户安置到其他证券公司，安置过程中相关各方应当采取必要措施保证客户证券交易的正常进行。"},{"id":"jun-law2-107","subject":"law","source":"6月押题 LC","type":"判断","q":"发起人持有的股份有限公司公开发行股份前已发行的股份， 自公司成立之日起 1 年内不得转让。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日 (并非公司成立之日)起 1 年内不得转让。"},{"id":"jun-law2-108","subject":"law","source":"6月押题 LC","type":"判断","q":"代为履行总经理职务的时间不得超过 6 个月。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析： 本题说法正确。证券基金经营机构董事长、总经理、合规负责人因故不能履行职务的，证券基金经营机构应当按照《公司法》和公司章程的规定，在 15 个工作日内决定由符合任职条件的人员代为履行职务，相关人员代为履行职务应当谨慎勤勉尽责，且时间不得超过 6 个月。中国证监会另有规定的，从其规定。"},{"id":"jun-law2-109","subject":"law","source":"6月押题 LC","type":"判断","q":"财务顾问在进行尽职调查时，不得利用其他证券服务机构出具的专业意见，以保持其独立判断。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。财务顾问在开展工作时可利用其他证券服务机构出具的专业意见，但应当对其进行必要的审慎核查，对委托人提供的资料和披露的信息进行独立判断。"},{"id":"jun-law2-110","subject":"law","source":"6月押题 LC","type":"判断","q":"不具备证券承销业务资格的证券公司只能以对冲风险为目的，从事金融衍生产品交易。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析： 本题说法错误。不具备证券自营业务资格的证券公司只能以对冲风险为目的，从事金融衍生产品交易。"},{"id":"jun-law2-111","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】某证券公司作为保荐机构指派员工李某、王某担任一家股份公司首\n次公开发行股票并上市项目的保荐代表人。\n\n【问题】下列 ()是证券公司作为保荐机构的职责。","options":["部门设置职责","尽职推荐职责","持续督导职责","程序优化职责"],"answer":"ABCD","explain":"答案解析： 保荐机构履行保荐职责，应当指定 2 名品行良好、具备组织实施保荐项目专业能力的保荐代表人具体负责 1 家发行人的保荐工作。B、C 选项正确，证券公司作为保荐机构的职责：尽职推荐职责、持续督导职责。故本题选 BC 选项。要求 2： 中国证监会在审核过程中发现保荐机构及保荐代表人在保荐过程中未勤勉尽责，可采取的监管措施有 ()。A、重点关注B、出具警示函C、责令公开说明D、认定为不适当人选答案解析： 保荐机构、保荐代表人、保荐业务负责人、内核负责人、保荐业务部门负责人及其他保荐业务相关人员违反相关规定，未诚实守信、勤勉尽责地履行相关义务的，中国证监会可以对其采取重点关注 (A 选项正确)、责令进行业务学习、出具警示函 (B 选项正确)、责令公开说明 (C 选项正确)、责令改正、责令增加内部合规检查的次数并提交合规检查报告、监管谈话、责令处分有关责任人员并报告结果、依法认定为不适当人选 (D 选项正确)等监管措施；依法应给予行政处罚的，依照有关规定进行处罚；情节严重涉嫌犯罪的，依法移送司法机关，追究其刑事责任。故本题选 ABCD 选项。"},{"id":"jun-law2-112","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】张某在某基金销售公司担任销售部经理，同时又在 A 证券公司担任\n证券经纪人。为拓展业务，张某将 A 证券公司开户二维码转发给其基金销售公司\n六名下属，委托他们协助其招揽 A 证券公司客户，对开户成功客户张某会长期推\n荐\"黑马\"股票，并承诺年化投资收益可以达到 10%。\n\n【问题】下列关于 A 证券公司经纪人张某存在违规行为的说法，错误的是 ()。","options":["张某存在\"自营或者为他人经营与所任证券公司同类或者存在利益冲突业务\"的行为","张某存在\"向客户违规承诺收益或者承担损失\"的行为","张某存在\"泄露因职务便利获取的未公开信息\"的行为","张某存在\"超出法规规定和证券公司授权的范围从事业务\"的行为"],"answer":"A","explain":"答案解析： A 选项正确，\"张某在某基金销售公司担任销售部经理，同时又在 A证券公司担任证券经纪人\"，从业人员不得自营或者为他人经营与所在证券公司同类或者存在利益冲突的业务。B 选项正确，\"张某承诺年化投资收益可以达到 10%\"，从业人员不得向客户违规承诺收益、承诺承担损失。C 选项错误，题干未提及未公开信息、泄露信息的内容。未公开信息交易是指利用因职务便利获取的内幕信息以外的其他未公开的信息，如机构持仓、交易动向、投资决策等。黑马股票只是经纪人随口忽悠、拍胸脯推荐、吹牛说会涨，并未说明其推荐依据是\"因职务便利获取的未公开信息\"。因此不存在\"泄露因职务便利获取的未公开信息\"的行为。D 选项正确，证券经纪人不能委托他人招揽客户、不能私下推荐股票、不能承诺收益，超出了证券公司的授权范围和法规规定的范围，属于违规行为。故本题选 C 选项。2.A 证券公司的下列情况中符合《证券经纪人管理暂行规定》的是 ()。A、A 证券公司建立健全证券经纪人管理制度，采取有效措施，对证券经纪人及其执业行为实施集中统一管理B、A 证券公司应当对证券经纪人进行不少于 40 个小时的执业前培训，其中法律法规和职业道德的培训时间不少于 20 个小时C、A 证券公司负责电话回访的人员从事客户招揽和客户服务活动D、A 证券公司对证券经纪人所招揽和服务客户的账户进行有效监控，并规定出现异常情况的，记录存档并在 3 个工作日内查明原因答案解析： A 选项正确，证券公司应当建立健全证券经纪人管理制度，采取有效措施，对证券经纪人及其执业行为实施集中统一管理，保障证券经纪人具备基本的职业道德和业务素质，防止证券经纪人在执业过程中从事违法违规或者超越代理权限、损害客户合法权益的行为。B选项错误，证券公司应当对证券经纪人进行不少于60个小时的执业前培训 (并非\"40 个小时\")，其中法律法规和职业道德的培训时间不少于 20 个小时。C 选项错误，负责电话回访的人员不得从事客户招揽和客户服务活动。D 选项错误，证券公司应当对证券经纪人所招揽和服务客户的账户进行有效监控，发现异常情况的，应立即查明原因并按照规定处理。没有\"3 个工作日内\"这一具体时限。故本题选 A 选项。"},{"id":"jun-law2-113","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】秦某在 A 证券有限公司营业部执业过程中存在以下问题：一是向某\n投资者提供证券投资建议时无合理依据，且未提示投资风险；二是收受某投资者\n提供的礼金，秦某因违规行为被出具行政监管措施。\n\n【问题】下列关于了解投资者信息的说法，正确的是 ()。","options":["向投资者销售产品，应当了解投资者的诚信记录","向投资者提供服务，应当了解投资者的近亲属信息","向投资者提供服务，应当了解投资者的工作经历","向投资者提供服务，应当了解投资者的风险偏好及可承受的损失"],"answer":"ACD","explain":"答案解析： 根据《证券期货投资者适当性管理办法》的要求，经营机构向投资者销售产品或者提供服务时，应当了解投资者的下列信息：①投资相关的学习、工作经历及投资经验 (C 选项正确) ;②风险偏好及可承受的损失 (D 选项正确)；③诚信记录 (A 选项正确)。B 选项错误，法规要求了解的是\"实际控制投资者的自然人和交易的实际受益人\"信息，这主要出于反洗钱等合规目的，而非泛指所有\"近亲属信息\"。故本题选 ACD 选项。【知识】经营机构向投资者销售产品或者提供服务时，还应当了解投资者的下列信息：①自然人的姓名、住址、职业、年龄、联系方式，法人或者其他组织的名称、注册地址、办公地址、性质、资质及经营范围等基本信息；②收入来源和数额、资产、债务等财务状况；③投资期限、品种、期望收益等投资目标；④实际控制投资者的自然人和交易的实际受益人；⑤法律法规、自律规则规定的投资者准入要求相关信息；⑥其他必要信息。"},{"id":"jun-law2-114","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】秦某在 A 证券有限公司营业部执业过程中存在以下问题：一是向某\n投资者提供证券投资建议时无合理依据，且未提示投资风险；二是收受某投资者\n提供的礼金，秦某因违规行为被出具行政监管措施。\n\n【问题】下列属于投资者适当性禁止行为的是 ()。","options":["向符合准入要求的投资者销售产品或者提供服务","向投资者就不确定事项提供确定性的判断","向普通投资者推介适当的产品或者服务","保护投资者的合法权益"],"answer":"B","explain":"答案解析： 经营机构在销售产品或者提供服务的过程中，应当将适当的产品或者服务提供给适合的投资者 (C 选项不符合题意)，并禁止进行下列活动：①向不符合准入要求的投资者销售产品或者提供服务(A 选项不符合题意)；②向投资者就不确定事项提供确定性的判断，或者告知投资者有可能使其误认为具有确定性的意见 (B 选项符合题意)；③其他违背适当性要求，损害投资者合法权益的行为(D 选项不符合题意)。故本题选 B 选项。【知识】经营机构在销售产品或者提供服务的过程中，还应当禁止进行下列活动：①向普通投资者主动推介风险等级高于其风险承受能力的产品或者服务；②向普通投资者主动推介不符合其投资目标的产品或者服务；③向风险承受能力最低类别的投资者销售或者提供风险等级高于其风险承受能力的产品或者服务。"},{"id":"jun-law2-115","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】秦某在 A 证券有限公司营业部执业过程中存在以下问题：一是向某\n投资者提供证券投资建议时无合理依据，且未提示投资风险；二是收受某投资者\n提供的礼金，秦某因违规行为被出具行政监管措施。\n\n【问题】经营机构向普通投资者销售产品或者提供服务前，应当告知的信息包括 ()。","options":["可能直接导致本金亏损的事项","可能直接导致超过原始本金损失的事项","因经营机构的业务或者财产状况变化，影响客户判断的重要事由","限制销售对象权利行使期限或者可解除合同期限等全部限制内容"],"answer":"ABCD","explain":"答案解析： 经营机构向普通投资者销售产品或提供服务前，应当告知下列信息：①可能直接导致本金亏损的事项 (A 选项符合题意)；②可能直接导致超过原始本金损失的事项 (B 选项符合题意)；③因经营机构的业务或财产状况变化，可能导致本金或原始本金亏损的事项；④因经营机构的业务或财产状况变化，影响客户判断的重要事由 (C 选项符合题意)；⑤限制销售对象权利行使期限或可解除合同期限等全部限制内容 (D 选项符合题意) ；⑥投资者适当性匹配意见。"},{"id":"jun-law2-116","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】甲公司因经营不善、流动资金不足，公司董事长卢某研究决定发行\n私募债券融资。为顺利发行债券，卢某经与公司法定代表人文某、财务负责人华\n某合谋，大额虚增营业收入、利润、资本公积，并提供虚假财务报表、凭证等，\n致使 A 会计师事务所出具内容重大失实的审计报告，承销商 B 证券公司以此为基\n础出具了募集说明书。经向证券交易所备案，甲公司非公开发行私募债券共计1\n亿元。该私募债券到期后，甲公司无力偿付债券本金和利息，造成投资人重大经\n济损失。\n假设上述案例所述情形均发生在现行相关法律法规生效时间之后，且不考虑各备\n选项之间的相关影响，请根据上述背景信息回答以下问题。\n\n【问题】下列关于对甲公司应当认定罪名的说法，正确的是() 。","options":["构成违规不披露重要信息罪","构成集资诈骗罪","构成欺诈发行证券罪","构成擅自发行公司债券罪"],"answer":"C","explain":"答案解析： C 选项正确，发行人 (即甲公司)不符合发行条件，以欺骗手段骗取发行注册的行为属于欺诈发行证券罪。A、B、D 选项错误，甲公司提供虚假的财务账簿、凭证，最终目的是发行证券。故本题选 C 选项。"},{"id":"jun-law2-117","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】甲公司因经营不善、流动资金不足，公司董事长卢某研究决定发行\n私募债券融资。为顺利发行债券，卢某经与公司法定代表人文某、财务负责人华\n某合谋，大额虚增营业收入、利润、资本公积，并提供虚假财务报表、凭证等，\n致使 A 会计师事务所出具内容重大失实的审计报告，承销商 B 证券公司以此为基\n础出具了募集说明书。经向证券交易所备案，甲公司非公开发行私募债券共计1\n亿元。该私募债券到期后，甲公司无力偿付债券本金和利息，造成投资人重大经\n济损失。\n假设上述案例所述情形均发生在现行相关法律法规生效时间之后，且不考虑各备\n选项之间的相关影响，请根据上述背景信息回答以下问题。\n\n【问题】下列关于甲公司及其责任人员可能受到的处罚，正确的有 ()。","options":["判处甲公司罪名成立，并判处非法募集资金金额 20%以上 1 倍以下的罚金","对甲公司处以非法募集资金金额 10%以上 1 倍以下的罚款","判处卢某、文某、华某罪名成立，判处有期徒刑","对卢某、文某、华某处以一定金额的罚款"],"answer":"ABCD","explain":"答案解析：①发行人的刑事责任：欺诈发行股票，数额巨大、后果严重或者有其他严重情节的，处 5 年以下有期徒刑或者拘役，并处或者单处罚金。数额特别巨大、后果特别严重或者有其他特别严重情节的，处 5 年以上有期徒刑，并处罚金 (C、D 选项正确) 。单位犯前述罪的，对单位判处非法募集资金金额 20%以上 1 倍以下罚金，并对其直接负责的主管人员和其他直接责任人员，依照《刑法》第一百六十条第一款的规定处罚 (A 选项正确)。②发行人的行政责任：发行人在其公告的证券发行文件中隐瞒重要事实或者编造重大虚假内容，已经发行证券的，处以非法所募资金金额 10%以上 1 倍以下的罚款；发行人的控股股东、实际控制人组织、指使从事前款违法行为的，没收违法所得，并处以违法所得10%以上 1 倍以下的罚款 (B 选项正确) 。故本题选 ABCD 选项。"},{"id":"jun-law2-118","subject":"law","source":"6月押题 LC","type":"案例","q":"【资料】甲公司因经营不善、流动资金不足，公司董事长卢某研究决定发行\n私募债券融资。为顺利发行债券，卢某经与公司法定代表人文某、财务负责人华\n某合谋，大额虚增营业收入、利润、资本公积，并提供虚假财务报表、凭证等，\n致使 A 会计师事务所出具内容重大失实的审计报告，承销商 B 证券公司以此为基\n础出具了募集说明书。经向证券交易所备案，甲公司非公开发行私募债券共计1\n亿元。该私募债券到期后，甲公司无力偿付债券本金和利息，造成投资人重大经\n济损失。\n假设上述案例所述情形均发生在现行相关法律法规生效时间之后，且不考虑各备\n选项之间的相关影响，请根据上述背景信息回答以下问题。\n\n【问题】下列关于甲公司发行债券相关中介机构及人员法律责任的说法，错误的是() 。","options":["A 会计师事务所和 B 证券公司可能与甲公司承担连带民事赔偿责任","A 会计师事务所和 B 证券公司可能构成欺诈发行证券罪","A 会计师事务所和 B 证券公司相关人员可能被追究行政责任","A 会计师事务所和 B 证券公司可能被追究行政责任"],"answer":"B","explain":"答案解析：B 选项错误，欺诈发行证券罪的主观方面只能由故意构成，过失不构成本罪。A会计师事务所和 B 证券公司并不知情，主观上不属于故意，所以不构成欺诈发行证券罪，但是必须承担行政责任和连带民事赔偿责任。故本题选 B 选项。"}]},{"id":"jun-bas1","subject":"basics","name":"6月押题 · 金融卷一","stats":{"单选":40,"多选":40,"判断":30,"案例":9},"questions":[{"id":"jun-bas1-0","subject":"basics","source":"6月押题 LC","type":"单选","q":"中国人民银行公开市场业务债券交易不包括 ()。","options":["现券交易","回购交易","发行中央银行票据","调整贴现利率"],"answer":"D","explain":"中国人民银行公开市场业务债券交易主要包括回购交易、现券交易和发行央行票据。故本题选 D 选项。"},{"id":"jun-bas1-1","subject":"basics","source":"6月押题 LC","type":"单选","q":"只能用于基金、国债及其他债券的认购及交易的账户是 ()。","options":["债券账户","基金账户","资金账户","股票账户"],"answer":"B","explain":"投资者买卖交易所上市的封闭式基金必须开立深、沪证券账户或深、沪基金账户及资金账户。基金账户只能用于基金、国债及其他债券的认购及交易。故本题选B 选项。"},{"id":"jun-bas1-2","subject":"basics","source":"6月押题 LC","type":"单选","q":"政府机构投资者中的 ()可以通过公开市场操作来进行宏观调控。","options":["股份制商业银行","大型商业银行","中央银行","政策性银行"],"answer":"C","explain":"中央银行以公开市场操作为政策手段，通过买卖政府债券或金融债券，影响货币供应量进行宏观调控。故本题选 C 选项。"},{"id":"jun-bas1-3","subject":"basics","source":"6月押题 LC","type":"单选","q":"证券交易的三先原则首要是 () 。","options":["价格优先","时间优先","开户优先","委托优先"],"answer":"A","explain":"竞价原则的主要内容是\"三先\"，即价格优先、时间优先、客户委托优先。故本题选 A 选项。"},{"id":"jun-bas1-4","subject":"basics","source":"6月押题 LC","type":"单选","q":"证券承销是指证券公司代理 ()发行证券的行为。","options":["投资银行","证券发行人","商业银行","金融机构"],"answer":"B","explain":"证券承销是指证券公司代理证券发行人发行证券的行为。发行人向不特定对象公开发行的证券，法律、行政法规规定应当由证券公司承销的，发行人应当同证券公司签订承销协议。故本题选 B 选项。"},{"id":"jun-bas1-5","subject":"basics","source":"6月押题 LC","type":"单选","q":"在证券交易中，指令驱动和报价驱动的分类标准是() 。","options":["是否有经纪商参与","投资者交易对象","订单类型","交易价格的决定特点"],"answer":"D","explain":"从交易价格的决定特点划分，可以将证券交易机制划分为指令驱动和报价驱动。故本题选 D 选项。"},{"id":"jun-bas1-6","subject":"basics","source":"6月押题 LC","type":"单选","q":"在美国发行的外国债券被称为 ()。","options":["扬基债券","武士债券","熊猫债券","无国籍债券"],"answer":"A","explain":"国际债券是指一国借款人在国际证券市场上以外国货币为面值，向外国投资者发行的债券。在美国发行的外国债券称为\"扬基债券\"，它是由非美国发行人在美国债券市场发行的吸收美元资金的债券。在日本发行的外国债券称为\"武士债券\"。故本题选 A 选项。"},{"id":"jun-bas1-7","subject":"basics","source":"6月押题 LC","type":"单选","q":"在金融期货的主要交易制度中，能使套期保值者用少量资金为价值量很大的现货找到回避价格风险的手段的是 ()。","options":["保证金制度","集中交易制度","断路器规则","限仓制度"],"answer":"A","explain":"在金融期货的保证金交易制度中，由于期货交易的保证金比率很低，因此有高度的杠杆作用，这一杠杆作用使套期保值者能用少量的资金为价值量很大的现货资产找到规避价格风险的手段，也为投机者提供了用少量资金获取盈利的机会。故本题选 A 选项。"},{"id":"jun-bas1-8","subject":"basics","source":"6月押题 LC","type":"单选","q":"在基金管理人的投资管理活动中，基金投资面临着外部风险与内部风险，下列属于外部风险的是 ()。","options":["合规风险","操作风险","职业道德风险","市场风险"],"answer":"D","explain":"在基金管理人的投资管理活动中，基金投资面临外部风险与内部风险。其中，外部风险包括市场风险、政策风险等系统性风险和信用风险、经营风险等非系统性风险；内部风险包括基金管理人的合规风险、操作风险和职业道德风险等。故本题选 D 选项。"},{"id":"jun-bas1-9","subject":"basics","source":"6月押题 LC","type":"单选","q":"在构建我国的证券公司监管制度方面，有以诚信与资质为标准的 ()制度。","options":["市场准入","专业评价","风险控制","事前审核"],"answer":"A","explain":"在长期的实践探索基础上，对证券公司实施有效监管的基础性制度已经基本形成，主要包括证券公司业务许可制度、以诚信与资质为标准的市场准入制度、分类监管制度、以净资本和流动性为核心的风险监控和预警制度、合规管理制度、客户交易结算资金第三方存管制度、信息报送与披露制度等。故本题选 A 选项。"},{"id":"jun-bas1-10","subject":"basics","source":"6月押题 LC","type":"单选","q":"影响股票投资价值的外部因素是 () 。","options":["盈利水平","股份分割","市场因素","并购重组"],"answer":"C","explain":"影响股票价值的外部因素有：宏观经济因素、行业因素、市场因素。影响股票投资价值的内部因素主要包括公司净资产、盈利水平、股利政策、股份分割、增资和减资以及并购重组等。故本题选 C 选项。"},{"id":"jun-bas1-11","subject":"basics","source":"6月押题 LC","type":"单选","q":"以下是证券交易所会员大会的职权有 ()。","options":["制定修改证券交易所章程","审议制定证券交易所财务决算","审定对会员的接纳","制定修改证券交易所业务规则"],"answer":"A","explain":"会员大会作为证券交易所的最高权力机构，行使下列职权：(1)制定和修改证券交易所章程；(2)选举和罢免会员理事、会员监事；(3)审议和通过理事会、监事会和总经理的工作报告；(4)审议和通过证券交易所的财务预算、决算报告；(5)法律、行政法规、部门规章和证券交易所章程规定的其他重大事项。"},{"id":"jun-bas1-12","subject":"basics","source":"6月押题 LC","type":"单选","q":"以下不属于科创板重点投资/重点支持行业的是() 。","options":["生物医药","新能源","新一代信息技术 (或高端装备/新材料/节能环保)","金融行业/金融产品"],"answer":"D","explain":"申报科创板发行上市的发行人，应当属于下列行业领域：(1)新一代信息技术领域；(2)高端装备领域；(3)新材料领域；(4)新能源领域；(5)节能环保领域；(6)生物医药领域；(7)符合科创板定位的其他领域。限制金融科技、模式创新企业在科创板上市，禁止房地产和主要从事金融、投资类业务的企业在科创板上市。故本题选 D 选项。"},{"id":"jun-bas1-13","subject":"basics","source":"6月押题 LC","type":"单选","q":"向投资者销售或者提供\"荐股软件\"，并直接或者间接获取经济利益的，应当经中国证监会许可，取得 ()资格。","options":["承销与保荐业务","证券经纪业务","证券投资咨询业务","一般证券业务"],"answer":"C","explain":"证券投资咨询业务是指从事证券投资咨询业务的机构及其投资咨询人员为证券投资人或者客户提供证券投资分析、预测或者建议等直接或者间接有偿咨询服务的活动。故本题选 C 选项。"},{"id":"jun-bas1-14","subject":"basics","source":"6月押题 LC","type":"单选","q":"相比股票、债券，基金的收益和风险水平是 () 。","options":["风险大收益大","风险小收益小","风险适中，收益相对稳健","风险小收益大"],"answer":"C","explain":"股票的直接收益取决于发行公司的经营效益，不确定性强，投资于股票有较大的风险。债券的直接收益取决于债券利率，而债券利率一般是事先确定的，投资风险相对较小。基金主要投资于有价证券，投资选择灵活多样，从而使基金的收益有可能高于债券，投资风险又可能小于股票，因此，基金属于风险适中，收益相对稳健的产品。故本题选 C 选项。"},{"id":"jun-bas1-15","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列有关影响国债销售价格的说法，错误的是() 。","options":["市场利率的高低及其变化对国债销售价格起着显著的导向作用，市场利率趋于上升时，就限制了承销商确定销售价格的空间","国债销售的价格一般不应高于承销商与发行人的结算价格；否则，就有可能发生亏损","在国债承销中，承销商可获得其承销金额一定比例的手续费收入，为了促进分销活动，承销商有可能压低国债销售价格","降低国债销售价格，承销商的分销过程会缩短，资金的回收速度会加快，承销商可以通过获取这部分资金占用其中的利息来降低总成本，提高收益"],"answer":"B","explain":"影响国债销售价格的因素：(1)市场利率。市场利率的高低及其变化对国债销售价格起着显著的导向作用。市场利率趋于上升，就限制了承销商确定销售价格的空间；市场利率趋于下降，就为承销商确定销售价格拓宽了空间。(2)承销商承销国债的中标成本。国债销售的价格一般不应低于承销商与发行人的结算价格；反之，就有可能发生亏损。(3)流通市场中可比国债的收益率水平。(4)国债承销的手续费收入。在国债承销中，承销商可获得其承销金额一定比例的手续费收入。对于不同品种的国债，该比例可能不一样，一般为千分之几。由于该项手续费收入的存在，为了促进分销活动，承销商有可能压低销售价格。(5)承销商所期望的资金回收速度。降低销售价格，承销商的分销过程会缩短，资金的回收速度会加快，承销商可以通过获取这部分资金占用其中的利息收入来降低总成本，提高收益。(6)其他国债分销过程中的成本。故本题选 B 选项。"},{"id":"jun-bas1-16","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列说法正确的是 ()。","options":["投机性资金流动属于国际短期资金流动","国际直接融资属于国际短期资金流动","国际间接融资属于国际短期资金流动","国际信贷属于国际短期资金流动"],"answer":"A","explain":"国际短期资金流动，是指期限为 1 年或 1 年以下的资金的跨国流动。国际短期资金流动主要包括贸易资金的流动、套利性资金的流动、保值性资金的流动以及投机性资金的流动四种类型。国际长期资金流动，是指期限在 1 年以上的资金的跨国流动，包括国际直接投资、国际间接投资和国际信贷三种形式。故本题选 A选项。"},{"id":"jun-bas1-17","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列属于证券市场融资活动的是 () 。","options":["商业票据融资","银行信贷","融资租赁","债券融资"],"answer":"D","explain":"一般来说，证券市场融资活动的方式主要包括股票融资和债券融资。另外，近年来，国内外兴起的投资基金融资也是证券融资的一种方式。故本题选 D 选项。"},{"id":"jun-bas1-18","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于证券公司次级债券的发行条件的说法中，错误的是 ()。","options":["次级债应以现金或中国证监会认可的其他形式借入或融入","借入或募集资金有合理用途","净资本与负债的比例、净资产与负债的比例等各项风险控制指标不触及预警标准","长期次级债计入净资本的数额不得超过净资本(不含长期次级债累计计入净资本的数额)的 30%"],"answer":"D","explain":"根据《证券公司次级债管理规定》，证券公司借入或发行次级债应符合以下条件：(1)借入或募集资金有合理用途；(2)次级债应以现金或中国证监会认可的其他形式借入或融入；(3)借入或发行次级债数额应符合相关规定：长期次级债计入净资本的数额不得超过净资本(不含长期次级债累计计入净资本的数额)的 50%；净资本与负债的比例、净资产与负债的比例等各项风险控制指标不触及预警标准；(4)募集说明书内容或次级债务合同条款符合证券公司监管规定。故本题选 D 选项。"},{"id":"jun-bas1-19","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于债券评级的说法，错误的是 () 。","options":["信用等级评审会议的参会评审委员不得少于 5 人","评级项目组至少由两名评级分析人员组成","委托人同时委托多家证券评级机构对同一评级对象进行评级，受委托的证券评级机构应当同时对外公布评级结果","评级机构受理复评申请后应当从尽职调查开始重新执行评级程序"],"answer":"D","explain":"A 选项正确，信用等级评审会议由信用评审委员会主任或其书面委托的其他委员主持，参会评审委员不得少于 5人。B 选项正确，证券评级机构应当聘用具有评级相关知识或经验的信用评级分析人员，并根据评级项目特点组成项目组。项目组实行组长负责制，至少由两名信用评级分析人员组成。C 选项正确，委托人同时委托多家证券评级机构对同一评级对象进行评级，或委托人对评级结果有异议另行委托其他证券评级机构的，受委托的证券评级机构应当同时对外公布评级结果。D 选项错误，证券评级机构受理复评申请后，项目组根据评级对象提供的补充资料修改评级报告，并将修改后的评级报告、建议信用等级、补充资料等提交信用评审委员会，由信用评审委员会确定复评结果。故本题选 D 选项。"},{"id":"jun-bas1-20","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于信用风险衡量的说法，错误的是 () 。","options":["信用打分模型是一种传统的信用风险量化模型","在诸多专家分析系统中，对企业信用分析的 5Ps 系统使用的最为广泛","内部评级所反映的被评级对象的风险特征主要是借款者的违约概率和交易工具的违约损失率","CreditMetrics 模型的核心内容是等级转移矩阵"],"answer":"B","explain":"A 选项正确，信用打分模型是一种传统的信用风险量化模型，它用可观察到的债务人特征变量计算出一个数值(打分)来代表债务人的违约概率或者将贷款人归类于不同的违约风险类别。B 选项错误，在诸多专家分析系统中，对企业信用分析的 5Cs 系统使用得最为广泛。C 选项正确，内部评级所反映的被评级对象的风险特征主要是借款者的违约概率和交易工具的违约损失率。D 选项正确,CreditMetrics模型与CreditPortfolioView模型的核心都是要计算等级转移矩阵。故本题选 B 选项。"},{"id":"jun-bas1-21","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于金融市场的说法，正确的是 () 。","options":["由于金融业属于服务行业，金融市场是产品或服务的一种","金融市场是创造和交易货币的市场","金融市场是以金融资产为交易对象而形成的供求关系和交易机制的总和","证券交易所是现代金融市场的主体"],"answer":"C","explain":"金融市场是创造和交易金融资产的市场，是以金融资产为交易对象而形成的供求关系和交易机制的总和。故本题选 C 选项。"},{"id":"jun-bas1-22","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于基金利润分配的说法，错误的是 () 。","options":["一般开放式基金份额持有人事先未做出选择的，利润分配默认的方式应当采用红利再投资","现金分红指根据基金可供分配利润的情况，基金管理人以投资者持有基金份额数量的多少，将利润分配给投资者","一般开放式基金的分红方式有两种","封闭式基金的收益分配每年不得少于一次"],"answer":"A","explain":"A 选项错误，根据有关规定，一般开放式基金利润分配默认的方式应当采用现金分红。开放式基金的基金份额持有人可以事先选择分红再投资。基金份额持有人事先未作出选择的，基金管理人应当支付现金。B 选项正确，现金分红指根据基金可供分配利润的情况，基金管理人以投资者持有基金份额数量的多少，将利润分配给投资者。这是基金分配最普遍的形式。C 选项正确，一般开放式基金的分红方式有两种：现金分红和红利再投资。D 选项正确，根据有关规定，封闭式基金的收益分配每年不得少于一次。故本题选 A 选项。"},{"id":"jun-bas1-23","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于股利政策的说法，错误的是 () 。","options":["股利政策是公司资本管理事项中经常要涉及的一个与股票相关的概念","股利政策体现了公司的发展战略和经营思路","稳定可预测的股利政策是股份公司稳健经营的重要指标","股利政策与股东利益最大化不相关"],"answer":"D","explain":"A 选项正确，公司的股利政策直接影响股票投资价值。股利政策是公司资本管理事项中经常要涉及的一个与股票相关的概念。B、C 选项正确，D 选项错误，股利政策体现了公司的发展战略和经营思路，稳定可预测的股利政策有利于股东利益最大化，是股份公司稳健经营的重要指标。"},{"id":"jun-bas1-24","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于风险偏好的说法，错误的是 () 。","options":["风险偏好也称为\"风险胃口\"","风险偏好是企业为了增加每一分盈利愿意多承担多少风险","风险偏好是战术性的，通常以定量描述为主","风险偏好是企业在追求战略和业务目标过程中对风险的态度"],"answer":"C","explain":"风险偏好为企业在追求战略和业务目标过程中对风险的态度，包括愿意承担的风险的种类、大小、数量、以何种方式承担，以及为了增加每一分盈利愿意多承担多少风险等，有时候也译为\"风险胃口\"。风险偏好是战略性的，通常以定性描述为主。故本题选 C 选项。"},{"id":"jun-bas1-25","subject":"basics","source":"6月押题 LC","type":"单选","q":"无论是哪种金融衍生品，都会影响投资者未来一定时期或某一时点的现金流，这体现了金融衍生品的() 。","options":["跨期性","高风险性","联动性","杠杆性"],"answer":"A","explain":"A 选项符合题意，跨期性：金融衍生工具是交易双方通过对利率、汇率、股价等因素变动趋势的预测，约定在未来某一时间按照一定条件进行交易或选择是否交易的合约。无论是哪一种金融衍生工具，都会影响交易者在未来一段时间内或未来某时点上的现金流，跨期交易的特点十分突出。"},{"id":"jun-bas1-26","subject":"basics","source":"6月押题 LC","type":"单选","q":"我国中长期附息债天数按 ()计算，并且算头不算尾。","options":["包括闰年 2 月 29 日","一个月 30 天","实际天数","一年 360 天"],"answer":"C","explain":"C 选项正确，我国交易所市场对附息债券的计息规定是全年天数统一按 365天计算；利息累计天数规则是按实际天数计算，算头不算尾，闰年 2 月 29 日不计息。故本题选 C 选项。"},{"id":"jun-bas1-27","subject":"basics","source":"6月押题 LC","type":"单选","q":"我国证券市场监督管理的主要手段是 () 。","options":["行政手段","法律手段","经济手段","窗口指导"],"answer":"B","explain":"B 选项正确，法律手段是通过建立完善的证券法律、法规体系和严格执法来实现的。这是证券市场监管部门的主要手段，具有较强的威慑力和约束力。故本题选B 选项。"},{"id":"jun-bas1-28","subject":"basics","source":"6月押题 LC","type":"单选","q":"我国证券交易所的证券交易采取 ()即一般投资者只能委托会员间接进行交易。","options":["代理制","经纪制","实名制","会员制"],"answer":"B","explain":"B 选项正确，参加交易者为具备会员资格的证券经营机构，交易采取经纪制度，即一般投资者不能直接进入交易所买卖证券，只能委托会员作为经纪人间接进行交易。故本题选 B 选项。"},{"id":"jun-bas1-29","subject":"basics","source":"6月押题 LC","type":"单选","q":"我国股票发行史上不包括 ()方式发行股票。","options":["注册制","核准制","审批制","备案制"],"answer":"D","explain":"股票发行监管制度主要有三种：审批制、核准制和注册制，每一种发行监管制度都对应一定的市场发展状况。故本题选 D 选项。"},{"id":"jun-bas1-30","subject":"basics","source":"6月押题 LC","type":"单选","q":"为推进市场化改革，提高金融机构自主定价能力，健全货币政策传导机制，培育货币市场基准利率， ()于 2007 开始试运行上海银行间同业拆借利率。","options":["中国证监会","中国人民银行","财政部","中国银监会"],"answer":"B","explain":"B 选项正确，为推进利率市场化改革，提高金融机构自主定价能力，健全货币政策传导机制，培育货币市场基准利率，中国人民银行于 2007 年开始试运行上海银行间同业拆借利率 (SHIBOR) 。故本题选 B 选项。"},{"id":"jun-bas1-31","subject":"basics","source":"6月押题 LC","type":"单选","q":"属于远期合约的衍生工具是 () 。","options":["远期股票期权","远期利率协议","远期股票指数期货","远期货币期货"],"answer":"B","explain":"金融衍生工具包括远期、期货、期权和互换。根据基础资产划分，常见的金融远期合约包括四个大类：股权类资产的远期合约、债权类资产的远期合约、远期利率协议、远期汇率协议。故本题选 B 选项。"},{"id":"jun-bas1-32","subject":"basics","source":"6月押题 LC","type":"单选","q":"属于声誉风险的管理行为是 () 。","options":["市场评估","内部审计","舆情监测","操作失误"],"answer":"C","explain":"声誉风险管理方法包括：事前识别与评估、应急机制、媒体沟通和信息披露、舆情监测分析。故本题选 C 选项。"},{"id":"jun-bas1-33","subject":"basics","source":"6月押题 LC","type":"单选","q":"基金监管对于维护证券市场的良好秩序、提高证券市场效率和 ()均具有重大意义。","options":["优化基金投资者结构","保护基金份额持有人利益","保护个人基金投资者的利益","促进基金市场规模稳定健康扩大"],"answer":"B","explain":"基金监管对于维护证券市场的良好秩序、提高证券市场效率、保护基金份额持有人利益均具有重大意义。故本题选 B 选项。"},{"id":"jun-bas1-34","subject":"basics","source":"6月押题 LC","type":"单选","q":"关于开放式基金，下列不可以通过基金管理人的直销中心办理的是 ()。","options":["赎回","申购","认购","兑换"],"answer":"D","explain":"D 选项符合题意，开放式基金的申购和赎回与认购一样，可以通过基金管理人的直销中心与基金销售机构的代销网点办理；没有基金兑换这个说法。故本题选D选项。"},{"id":"jun-bas1-35","subject":"basics","source":"6月押题 LC","type":"单选","q":"根据商业银行的业务分类，下列属于商业银行资产业务的是 ()。","options":["银行承兑汇票","吸收存款","资产托管","贷款业务"],"answer":"D","explain":"D 选项符合题意，商业银行的资产业务主要包括现金资产、贷款业务、票据贴现、投资业务等。故本题选 D 选项。"},{"id":"jun-bas1-36","subject":"basics","source":"6月押题 LC","type":"单选","q":"根据风险定义，下列不涉及风险特征的是 () 。","options":["不可预测性","不确定性","损失","波动性"],"answer":"C","explain":"目前，国内外金融理论界对风险的定义或界定主要有以下三类观点：(1)风险是结果的不确定性，是一种变化；(2)风险是损失发生的可能性，或可能发生的损失；(3)风险是结果对期望的偏离，是(收益的)波动性。C 选项符合题意，损失是风险可能导致的结果，而非风险的特征。故本题选 C 选项。"},{"id":"jun-bas1-37","subject":"basics","source":"6月押题 LC","type":"单选","q":"根据《上海证券交易所股票上市规则 (2025 年 4 月修订)》 《深圳证券交易所股票上市规则 (2025 年 4 月修订)》，以下不属于强制退市的是 ()。","options":["违规类强制退市","财务类强制退市","规范类强制退市","重大违法类强制退市"],"answer":"A","explain":"强制退市分为交易类强制退市、财务类强制退市(B 选项不符合题意)、规范类强制退市(C 选项不符合题意)和重大违法类强制退市(D 选项不符合题意)四类情形。故本题选 A 选项。"},{"id":"jun-bas1-38","subject":"basics","source":"6月押题 LC","type":"单选","q":"按股东享有权利的不同，股票可以分为","options":["份额股票和比例股票","有面额股票和无面额股票","普通股票和特别股票","记名股票和无记名股票"],"answer":"C","explain":"C 选项正确，按股东享有权利的不同，股票可以分为普通股票和特别股票。故本题选 C 选项。"},{"id":"jun-bas1-39","subject":"basics","source":"6月押题 LC","type":"单选","q":"()是全球最大的外汇批发市场。","options":["英国的伦敦外汇市场","美国的纽约外汇市场","日本的东京外汇市场","中国的香港外汇市场"],"answer":"A","explain":"英国的伦敦外汇市场是全球最大的外汇批发市场。到 2007 年，通过电子经纪及电子交易系统进行的交易占总成交金额的比例已经提高到 30%以上。故本题选 A选项。"},{"id":"jun-bas1-40","subject":"basics","source":"6月押题 LC","type":"多选","q":"注册制与核准制的实质区别表现在 ()。","options":["坚持开门搞审核","大幅优化发行上市条件","切实把好信息披露质量关","审核部门要准确对企业的投资价值作出判断"],"answer":"ABC","explain":"注册制与核准制的实质区别：(1)大幅优化发行上市条件。改革后，仅保留了企业公开发行股票必要的资格条件、合规条件，将核准制下的实质性门槛尽可能转化为信息披露要求，审核部门不再对企业的投资价值作出判断。(2)切实把好信息披露质量关。实行注册制，绝不意味着放松质量要求，审核把关更加严格。审核工作主要通过问询来进行，督促发行人真实、准确、完整披露信息。(3)坚持开门搞审核。审核注册的标准、程序、内容、过程、结果全部向社会公开，公权力运行全程透明、严格制衡，接受社会监督，与核准制有根本的区别。D 选项错误，证券监管机构对证券的价值好坏、价格高低不作实质性判断。故本题选 ABC 选项。"},{"id":"jun-bas1-41","subject":"basics","source":"6月押题 LC","type":"多选","q":"证券投资基金侧袋机制中的特定资产包括 ()。","options":["无可参考的活跃市场价格且采用估值技术仍导致公允价值存在重大不确定性的资产","按摊余成本计量且计提资产减值准备仍导致资产价值存在重大不确定性的资产","基金其他资产价值存在重大不确定性的资产","基金表外资产价值存在重大不确定性的资产"],"answer":"ABC","explain":"侧袋机制实施期间，原有账户称为主袋账户，专门账户称为侧袋账户。特定资产包括：无可参考的活跃市场价格且采用估值技术仍导致公允价值存在重大不确定性的资产、按摊余成本计量且计提资产减值准备仍导致资产价值存在重大不确定性的资产、其他资产价值存在重大不确定性的资产。故本题选 ABC 选项。"},{"id":"jun-bas1-42","subject":"basics","source":"6月押题 LC","type":"多选","q":"证券交易所可根据需要对每日股价涨跌幅予以适当的限制， ()委托是无效的。","options":["高于涨幅限制价格","高于跌幅限制价格","低于涨幅限制价格","低于跌幅限制价格"],"answer":"AD","explain":"为保护投资者利益，防止股价暴涨暴跌和投机盛行，证券交易所可根据需要对每日股票价格的涨跌幅度予以适当的限制。高于涨幅限制价格的委托和低于跌幅限制价格的委托无效。故本题选 AD 选项。"},{"id":"jun-bas1-43","subject":"basics","source":"6月押题 LC","type":"多选","q":"证券公司根据市场状况和风险控制的需要，确定和调整转融通的 ()。","options":["佣金","费率","数量占比","保证金的比例"],"answer":"BD","explain":"证券金融公司应当按照国家宏观政策，根据市场状况和风险控制需要，确定和调整转融通费率和保证金的比例。故本题选 BD 选项。"},{"id":"jun-bas1-44","subject":"basics","source":"6月押题 LC","type":"多选","q":"证券发行人是指为筹措资金而发行债券、股票等证券的发行主体。证券发行人主要包括 ()。","options":["中央政府及其直属机构","金融机构","地方政府","企业 (公司)"],"answer":"ABCD","explain":"证券发行人，是指为筹措资金而发行债券、股票等证券的发行主体。证券发行人主要包括政府及其机构、企业 (公司) 和金融机构。故本题选 ABCD 选项。"},{"id":"jun-bas1-45","subject":"basics","source":"6月押题 LC","type":"多选","q":"影响债券价值的基本因素有 () 。","options":["面值","票面利率","到期时间","折现率"],"answer":"ABCD","explain":"影响债券价值的基本因素和主要表现如下：(1)面值：面值越大，债券价值越大。(2)票面利率：票面利率越大，债券价值越大。(3)折现率：折现率越大，债券价值越小。(4)到期时间：对于平息债券，当折现率一直保持至到期日不变时，随着到期时间的缩短，债券价值逐渐接近其票面价值。故本题选 ABCD 选项。"},{"id":"jun-bas1-46","subject":"basics","source":"6月押题 LC","type":"多选","q":"以下关于沪港通说法正确的是 () 。","options":["沪股通是指香港投资者委托香港经纪商，经由联交所设立的证券交易服务公司，向上交所进行申报，买卖规定范围内的上交所上市的股票","港股通是指内地投资者委托内地证券公司，经由上交所设立的证券交易服务公司，向联交所进行申报，买卖规定范围内的联交所上市的股票","港股通是指内地投资者委托内地证券公司，经由联交所设立的证券交易服务公司，向上交所进行申报，买卖规定范围内的上交所上市的股票","沪股通是指香港投资者委托香港经纪商，经由上交所设立的证券交易服务公司，向上交所进行申报"],"answer":"AB","explain":"A 选项正确、D 选项错误，沪股通，是指投资者委托香港联合交易所参与者，经由香港联合交易所在上海设立的证券交易服务公司，向上海证券交易所进行申报，买卖沪港通规定范围内的上海证券交易所上市的股票。B 选项正确、C 选项错误，沪港通下的港股通，是指投资者委托上海证券交易所会员，经由上海证券交易公司在香港设立的证券交易服务公司，向香港联合交易所进行申报，买卖沪港通规定范围内的香港联合交易所上市的股票。故本题选AB 选项。"},{"id":"jun-bas1-47","subject":"basics","source":"6月押题 LC","type":"多选","q":"一般性货币政策工具包括 () 。","options":["存款准备金率","货币供给增长率","公开市场业务","再贴现率"],"answer":"ACD","explain":"一般性货币政策工具是指中央银行普遍或常规运用的货币政策工具，其实施对象是整体经济和金融活动，主要包括存款准备金制度、再贴现政策和公开市场业务三大工具。故本题选 ACD 选项。"},{"id":"jun-bas1-48","subject":"basics","source":"6月押题 LC","type":"多选","q":"信用风险衡量中的信用风险经典量化模型包括() 。","options":["Logit 模型","KMV 模型","CreditMetrics 模型","CreditPortfolioView 模型"],"answer":"BCD","explain":"信用风险经典量化模型包括：(1) CreditMetrics 模型；(2) CreditPortfolioView 模型；(3) CreditMonitor 模型:通常又称 KMV 模型，是 KMV 公司开发的一种违约率模型。故本题选 BCD 选项。"},{"id":"jun-bas1-49","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列与直接融资相关的说法，错误的有 () 。","options":["部分直接融资方式具有不可逆性","当前我国提高间接融资比重平衡金融体系结构，可以起到分散过度集中于银行的金融风险作用，有利于金融和经济的平稳运行","当前提高我国直接融资比重，特别是发展多种债权融资方式能够弥补间接融资的不足，也有利于提高实体经济的健康稳定发展","直接融资中债权融资和股权融资的比例反映了一国金融体系配置的效率是否与实体经济相匹配"],"answer":"BCD","explain":"部分融资方式具有不可逆性。如发行股票所得资金不需要返还，股票只能够在不同投资者之间相互转让。直接融资和间接融资的比例反映了一国金融体系风险的分布情况。提高直接融资比重，平衡金融体系结构，可以起到分散过度集中于银行的金融风险的作用，有利于金融和经济的平稳运行。直接融资和间接融资的比例反映了一国金融体系配置的效率是否与实体经济相匹配。我国正处于转变经济发展方式、调整产业结构的经济转型期，在这个过程中提高直接融资比重，特别是发展多种股权融资方式能够弥补间接融资的不足，也有利于促进实体经济的健康稳定发展。故本题选 BCD 选项。"},{"id":"jun-bas1-50","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列属于债券票面基本要素的有 ()。","options":["债券发行人名称","债券承销者名称","债券的票面利率","债券到期期限"],"answer":"ACD","explain":"债券作为证明债权债务关系的凭证，一般以有一定格式的票面形式来表现。通常，债券票面上有四个基本要素：(1)债券的票面价值。(2)债券的到期期限。(3)债券的票面利率。(4)债券发行人名称。故本题选 ACD 选项。"},{"id":"jun-bas1-51","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列属于我国证券市场专业机构投资者的有 ()。","options":["风险投资基金","私募基金","企业年金","证券投资基金"],"answer":"ABCD","explain":"经过十几年的发展，我国证券市场初步形成了包括证券投资基金、保险资金、社会保障资金、企业年金、合格境外机构投资者、私募基金、风险投资基金、信托基金等多元化的专业机构投资者队伍。故本题选 ABCD 选项。"},{"id":"jun-bas1-52","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于证券投资者保护基金公司设立意义的说法，正确的有 ()。","options":["可以在证券公司出现关闭破产等重大风险时依据国家政策用于保护投资者权益，通过简捷的渠道快速地对投资者特别是机构投资者予以保护","有助于稳定市场、防止证券公司个案风险的传递和扩散","为我国建立国际成熟市场通行的证券投资者保护机制搭建了平台，为我国资本市场制度建设向国际化靠拢提供了契机","是对现有的国家行政监管部门、证券业协会和证券交易所等行业自律组织、市场中介机构等组成的全方位、多层级监管体系的一个重要补充"],"answer":"BCD","explain":"国家设立保护基金制度是投资者保护体系的一个重要组成部分。其意义在于：(1)可以在证券公司出现关闭、破产等重大风险时依据国家政策用于保护投资者权益，通过便捷的渠道快速地对投资者特别是中小投资者予以保护；(2)有助于稳定市场，防止证券公司个案风险的传递和扩散；(3)是对现有的国家行政监管部门、证券业协会和证券交易所等行业自律组织、市场中介机构等组成的全方位、多层次监管体系的一个重要补充；(4)为我国建立国际成熟市场通行的证券投资者保护机制搭建了平台，为我国资本市场制度建设向国际化靠拢提供了契机。故本题选 BCD 选项。"},{"id":"jun-bas1-53","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于证券市场个人投资者特点的说法，错误的有 ()。","options":["个人投资者资金规模有限，用于投资的资金主要来源于融入资金","个人投资者的投资行为具有随意性、分散性和长期性的特点","与职业投资机构相比，个人投资者的专业知识相对匮乏","个人投资者的投资灵活性较弱，在投资决策和实施的时滞上比较长，较之机构投资者有更少的短期投资获利机会"],"answer":"ABD","explain":"A 选项错误，作为个体参与者，个人投资者用于投资的资金主要来源于自有资金。B 选项错误，个人投资者投资行为具有随意性、分散性和短期性的特点。C 选项正确，个人投资者专业知识比较相对匮乏。D 选项错误，个人投资者投资的灵活性强。个人投资者由于投资规模相对较小，进退较职业投资机构更为容易，在投资决策和实施的时滞上比较短，仅从这个意义上讲，他们较机构投资者有更多的短期投资获利机会。故本题选 ABD 选项。"},{"id":"jun-bas1-54","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于债券交易的说法， 正确的有 () 。","options":["期货交易即交易双方在集中性的市场以公开竞价方式所进行的期货合约的交易","交易所现券交易的证券买卖双方在成交后并不立即办理交收手续","回购交易是指债券买卖双方在成交的同时，约定未来进行反向交易的行为","现券交易也称为债券的即期交易"],"answer":"ACD","explain":"期货交易是在交易所进行的标准化的远期交易，即交易双方在集中性的市场以公开竞价方式所进行的期货合约的交易。现券交易，也称为债券的即期交易，是指证券买卖双方在成交后就办理交收手续。回购交易是指债券买卖双方在成交的同时，约定于未来某一时间以某一约定价格双方再进行反向交易的行为。故本题选 ACD 选项。"},{"id":"jun-bas1-55","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于信用违约互换的说法，正确的有 () 。","options":["信用违约互换实际上是在一定期限内，买卖双方就指定的信用事件进行风险转换的一个合约","在信用违约互换交易中，合约买方在合约期限内或在信用事件发生前定期向卖方就某个参考实体的信用事件支付费用，以换取信用事件发生后的赔偿","在信用违约互换交易中，合约买方一般需要真正持有作为参考的信用工具","信用违约互换具有较高的杠杆性"],"answer":"ABD","explain":"A 选项正确，信用违约互换是国外债券市场中最常见的信用衍生产品。实际上是在一定期限内，买卖双方就指定的信用事件进行风险转换的一个合约。B 选项正确，在信用违约互换交易中，信用风险保护的买方在合约期限内或在信用事件发生前定期向信用风险保护的卖方就某个参照实体的信用事件支付费用，以换取信用事件发生后的赔付。C 选项错误，信用违约互换交易中，信用保护的买方并不需要真正持有作为参考的信用工具。D 选项正确，信用违约互换具有较高的杠杆性。故本题选 ABD 选项。"},{"id":"jun-bas1-56","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于凭证式国债承销的说法，正确的有 ()。","options":["凭证式国债是一种可上市流通的储蓄型债券，由具备凭证式国债承销团资格的机构承销","承销商在分得所承销的国债后，通过各自的代理网点发售","各类商业银行均有资格申请加入凭证式国债承销团","财政部和中国人民银行一般每年确定一次凭证式国债承销团资格"],"answer":"BCD","explain":"凭证式国债的承销程序：凭证式国债是一种不可上市流通的储蓄型债券，由具备凭证式国债承销团资格的机构承销。财政部和中国人民银行一般每年确定一次凭证式国债承销团资格，各类商业银行均有资格申请加入凭证式国债承销团。财政部一般委托中国人民银行分配承销数额。承销商在分得所承销的国债后，通过各自的代理网点发售。故本题选 BCD 选项。"},{"id":"jun-bas1-57","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于基金类投资者的说法，错误的有 () 。","options":["我国的证券投资基金可投资于上市交易的股票、债券，不得投资于衍生品","企业年金是社保基金的一种形式，是指企业及其职工在依法参加基本养老保险的基础上，强制建立的补充养老保险基金","社会保障基金的投资采取社保基金理事会直接运作与委托投资管理人运作结合的方式、风险小的投资由社保基金理事会直接运作，风险较高的投资则委托专业性投资管理机构进行投资运作","社保基金理事会直接运作的社保基金投资范围限于银行存款、国债、信用等级在投资级以上的企业债和金融债"],"answer":"ABD","explain":"A 选项错误，我国的证券投资基金可投资于上市交易的股票、债券和国务院证券监督管理机构规定的其他证券及其衍生品种。B 选项错误，企业年金，是指企业及其职工在依法参加基本养老保险的基础上，自愿建立的补充养老保险基金。C 选项正确，社会保障基金的投资采取社保基金理事会直接运作与委托投资管理人运作相结合的方式，风险小的投资由社保基金理事会直接运作，风险较高的投资则委托专业性投资管理机构进行投资运作。D 选项错误，理事会直接运作的社保基金的投资范围限于银行存款、在一级市场购买国债，其他投资需委托社保基金投资管理人管理和运作。故本题选 ABD选项。"},{"id":"jun-bas1-58","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于风险定义的说法，正确的有 () 。","options":["风险是结果的不确定性","风险是结果对期望的偏离","风险是收益的波动性","风险是损失发生的可能性"],"answer":"ABCD","explain":"目前，国内外金融理论界对风险的定义或界定主要有以下三类观点：(1)风险是结果的不确定性，是一种变化；(2)风险是损失发生的可能性，或可能发生的损失；(3)风险是结果对期望的偏离，是(收益的)波动性。故本题选 ABCD 选项。"},{"id":"jun-bas1-59","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于多层次资本市场的说法，正确的有 ()。","options":["多层次资本市场可以满足不同投资者对不同投资品种的偏好","多层次资本市场可以满足企业不同阶段的融资需求和融资特点","多层次资本市场的各层次之间单独平行、彼此交错","多层次资本市场特性体现在投资者结构、中介机构和监管体系的多层次"],"answer":"ABD","explain":"A、B 选项正确，资本市场的层次结构，是指资本市场根据企业在不同发展阶段的融资需求和融资特点，针对各种市场主体不同的、特定的需求，提供的具有不同内在逻辑次序、不同服务对象和不同内在特点的市场形式。因此多层次资本市场可以满足投资者对不同投资品种的偏好、满足企业不同阶段的融资需求和融资特点。C 选项错误，多层次资本市场的各层次之间并不是单独平行，彼此隔离的，而是既互相区分，又相互交错并不断演进的结构。D 选项正确，资本市场的多层次特性还体现在投资者结构、中介机构和监管体系的多层次，交易定价、交割清算方式的多样性，它们与多层次市场共同构成了一个有机平衡的金融生态系统。故本题选 ABD 选项。"},{"id":"jun-bas1-60","subject":"basics","source":"6月押题 LC","type":"多选","q":"我国银行间债券市场的发展现状主要表现在 ()。","options":["市场规模快速扩大，银行间债券市场已经逐步确立了其在我国债券市场中的主板地位","与国际市场相比较，市场交易活跃性较高","市场成员不断扩容，参与主体日渐多元","投资者结构持续优化，市场风险不断分散"],"answer":"ACD","explain":"其发展现状表现在以下几个方面：(1)市场规模快速扩大，银行间债券市场已经逐步确立了其在我国债券市场中的主板地位；(2)市场成员不断扩容，参与主体日渐多元；(3)市场功能逐步显现，兼具投资和流动性管理功能；(4)发行主体以国有企业为主，其他主体积极参与；(5)投资者结构持续优化，市场风险不断分散；(6)与国际市场相比较，市场交易活跃性仍然较低。故本题选 ACD 选项。"},{"id":"jun-bas1-61","subject":"basics","source":"6月押题 LC","type":"多选","q":"属于普通股股东的义务有 () 。","options":["出资义务","忠实义务","不滥用股东权利义务","勤勉义务"],"answer":"AC","explain":"按照我国《公司法》的规定，普通股股东负有以下义务：(1)出资义务；(2)不得滥用股东权利的义务。忠实义务和勤勉义务属于公司董事、监事、高级管理人员等主体的义务。故本题选 AC 选项。"},{"id":"jun-bas1-62","subject":"basics","source":"6月押题 LC","type":"多选","q":"目前中国企业发行境外债券总体可以分为三类，分别是 ()。","options":["非人民币债券","点心债","合成型债券","熊猫债"],"answer":"ABC","explain":"目前中国企业发行境外债券总体可以分为三类：第一类是在境外市场以非人民币发行和结算的债券，称为非人民币债券；第二类是以人民币发行、以人民币结算的债券，称为点心债；第三类是以人民币发行、以其他国货币结算的债券，称为合成型债券。D 选项不符合题意，在中国发行的以人民币计价的外国债券称为\"熊猫债券\"。故本题选 ABC 选项。"},{"id":"jun-bas1-63","subject":"basics","source":"6月押题 LC","type":"多选","q":"开展基础设施基金经纪业务的证券公司和基金管理人及基金销售机构应当制定《公开募集基础设施证券投资基金 (REITs)交易风险揭示书》，该《风险揭示书》需揭示的风险包括 ()。","options":["税收等政策调整风险","基金价格波动风险","流动性风险","基础设施项目运营风险"],"answer":"ABCD","explain":"《风险揭示书》需揭示的风险包括：基金价格波动风险、基础设施项目运营风险、流动性风险、终止上市风险、税收等政策调整风险。故本题选 ABCD 选项。"},{"id":"jun-bas1-64","subject":"basics","source":"6月押题 LC","type":"多选","q":"金融衍生工具的基本特征包括 () 。","options":["联动性","不确定性或高风险性","杠杆性","跨期性"],"answer":"ABCD","explain":"金融衍生工具又称金融衍生产品，是与基础金融产品相对应的一个概念，指建立在基础产品或基础变量之上，其价格取决于基础金融产品价格变动的派生金融产品。由金融衍生工具的定义可以看出，它们具有下列四个显著特征：(1)跨期性；(2)杠杆性；(3)联动性；(4)不确定性或高风险性。故本题选 ABCD 选项。"},{"id":"jun-bas1-65","subject":"basics","source":"6月押题 LC","type":"多选","q":"截至目前， 我国期货交易所有 () 。","options":["北京期货交易所","大连商品交易所","郑州商品交易所","广州期货交易所"],"answer":"BCD","explain":"目前有上海期货交易所、大连商品交易所、郑州商品交易所、广州期货交易所四大商品期货交易所和中金所。故本题选 BCD 选项。"},{"id":"jun-bas1-66","subject":"basics","source":"6月押题 LC","type":"多选","q":"基金市场的参与主体， 包括 () 。","options":["基金服务机构","基金的自律组织","基金的监管机构","基金当事人"],"answer":"ABCD","explain":"基金市场上存在许多不同的参与主体，依据所承担的责任与作用的不同，可以将基金市场的参与主体分为基金当事人、基金服务机构、基金的监管机构和自律组织三大类。故本题选 ABCD 选项"},{"id":"jun-bas1-67","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于我国基金监管的目标，下列说法正确的有降低市场的系统性风险 A","options":["","保证市场的公平、效率和透明","保护投资人及相关当事人的合法权益"],"answer":"ABC","explain":"基金监管的目标是指基金监管所要达到的目的和效果，是基金监管活动的出发点和价值归宿。我国基金监管的目标是:(1)保护投资人及相关当事人的合法权益(C 选项正确);(2)规范基金活动，保证市场的公平、效率和透明，降低系统风险(A、B 选项正确);(3)促进证券投资基金和资本市场的健康发展。故本题选 ABC 选项。"},{"id":"jun-bas1-68","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于利率的期限结构，下列说法正确的有（）","options":["对未来利率变动方向的预期会影响利率的期限结构","债券期限与收益率的关系被称为利率的期限结构","债券的收益率曲线仅有向上倾斜、向下倾斜两种类型","债券预期收益中可能存在的流动性溢价会影响利率的期限结构"],"answer":"ABCD","explain":"利率期限结构是指在某一时点上，不同期限债券的收益率与到期期限之间的关系(B 选项正确)从形状上来看，收益率曲线主要包括四种类型:向上倾斜、向下倾斜、平直、拱形利率曲线(C 选项错误)。在任一时点上，都有以下三种因素影响期限结构的形状:(1)对未来利率变动方向的预期(A 选项正确);(2)债券预期收益中可能存在的流动性溢价(D 选项正确);(3)市场效率低下或者资金从长期(或短期)市场向短期(或长期)市场流动可能存在的障碍。利率期限结构理论就是基于这三种因素分别建立起来的。故本题选ABD 选项。[乐知识】从形状上来看，收益率曲线主要包括四种类型:(1)一条向上倾斜的利率曲线，表示期限越长的债券利率越高。这种曲线形状被称为正向的利率曲线;(2)一条向下倾斜的利率曲线，表示期限越长的债券利率越低。这种曲线形状被称为相反的或反向的利率曲线;(3) 一条平直的利率曲线，表示不同期限的债券利率相等，这通常是正利率曲线与反利率曲线转化过程中出现的暂时现象;(4) 拱形利率曲线，表示期限相对较短的债券，利率与期限呈正向关系;期限相对较长的债券，利率与期限呈反向关系。"},{"id":"jun-bas1-69","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于基金自身投资活动中产生的税收，下列说法正确的有 ()。","options":["证券投资基金管理人运用基金买卖股票、债券转让收入免征增值税","基金买卖股票实行单向征收印花税，向卖出方征收","对证券投资基金取得的债券利息收入，发行债券的企业和银行在向基金支付上述收入时代扣代缴 20%个人所得税","对证券投资基金从证券市场中取得的收入，暂不征收企业所得税"],"answer":"ABCD","explain":"A 选项正确，证券投资基金管理人运用基金买卖股票、债券转让收入免征增值税。B 选项正确，基金卖出股票按照 0.05%的税率征收交易印花税，买入交易不征收印花税，即对印花税实行单向征收。C 选项正确，对基金取得的债券利息收入，发行债券的企业和银行在向基金支付上述收入时代扣代缴 20%的个人所得税。D 选项正确，对证券投资基金从证券市场中取得的收入，包括买卖股票、债券的差价收入，股权的股息、红利收入，债券的利息收入及其他收入，暂不征收企业所得税。故本题选 ABCD 选项。"},{"id":"jun-bas1-70","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于股票的价值，下面说法中正确的有 () 。","options":["股票的票面价值又被称为面值，即在股票票面上标明的金额","股票的内在价值即理论价值，也就是股票未来收益的现值","股票的清算价值是公司清算时每一股份所代表的实际价值","股票的账面价值又被称为股票净值或每股净资产"],"answer":"ABCD","explain":"A 选项正确，股票的票面价值又称面值，即在股票票面上标明的金额。B 选项正确，股票的内在价值即理论价值，即股票未来收益的现值。C 选项正确，股票的清算价值是公司清算时每一股份所代表的实际价值。D 选择正确，股票的账面价值又称股票净值或每股净资产。故本题选 ABCD 选项。"},{"id":"jun-bas1-71","subject":"basics","source":"6月押题 LC","type":"多选","q":"根据《国务院关于开展优先股试点的指导意见》，下列关于优先股股东\"恢复的表决权\"说法，错误的有() 。","options":["恢复的表决权并不是一直存在，当公司 80%(含)支付所欠优先股股息时，优先股股东将不再享有这类表决权","优先股股东恢复到与普通股股东同样的表决权，可以参与公司经营决策，与普通股一同参加投票","累计 2 个会计年度未按约定支付优先股股息的，优先股股东可以享有公司章程规定的表决权","连续 2 个会计年度未按约定支付优先股股息的，优先股股东可以享有公司章程规定的表决权"],"answer":"AC","explain":"由于公司长期未按约定分配股息，优先股股东恢复到与普通股股东同样的表决权，可以参与公司经营决策，与普通股一同参加投票 (B 选项正确)，这类表决权可以被称为优先股\"恢复的表决权\"。2013 年 11 月 30 日发布的《国务院关于开展优先股试点的指导意见》规定公司累计 3 个会计年度或连续 2 个会计年度未按约定支付优先股股息的，优先股股东可以享有公司章程规定的表决权 (C 选项错误、D 选项正确)。需要注意的是，\"恢复的表决权\"并不是一直存在的，当公司全额支付所欠优先股股息时 (A 选项错误)，优先股股东将不再享有这类表决权。故本题选 AC 选项。"},{"id":"jun-bas1-72","subject":"basics","source":"6月押题 LC","type":"多选","q":"根据《公司债券发行与交易管理办法》，公开发行公司债券，应当符合 () 条件。","options":["最近五年平均可分配利润足以支付公司债券一年的利息","具有合理的资产负债结构和正常的现金流量","国务院规定的相关条件","具备健全且运行良好的组织机构"],"answer":"BCD","explain":"根据《公司债券发行与交易管理办法》，公开发行公司债券，应当符合下列条件：(1)具备健全且运行良好的组织机构 (D 选项正确)；(2)最近三年平均可分配利润足以支付公司债券一年的利息 (A 选项错误)；(3)具有合理的资产负债结构和正常的现金流量 (B 选项正确)；(4)国务院规定的其他条件 (C 选项正确)。故本题选 BCD 选项。"},{"id":"jun-bas1-73","subject":"basics","source":"6月押题 LC","type":"多选","q":"风险管理的流程主要包括 () 。","options":["风险的传导","风险的衡量","风险的监测、预警与报告","风险的识别"],"answer":"BCD","explain":"一般情况下，风险管理的流程主要包括：风险的识别 (D 选项正确)、风险的衡量 (B 选项正确)、风险的监测、预警与报告 (C 选项正确)以及风险的应对。故本题选 BCD 选项。"},{"id":"jun-bas1-74","subject":"basics","source":"6月押题 LC","type":"多选","q":"当期权合约的买方具有在约定期限内 (或合约到期内)按行权价格买入一定数量基础金融工具的权利时，这种合约指 ()。","options":["看涨期权","认沽期权","看跌期权","认购期权"],"answer":"AD","explain":"认购期权 (D 选项正确)也称为看涨期权 (A 选项正确)，指期权的买方具有在约定期限内 (或合约到期日)按行权价格 (也称为敲定价格或执行价格)向期权的卖方买入一定数量基础金融工具的权利。故本题选 AD 选项。【乐知识】认沽期权也称为看跌期权，指期权的买方具有在约定期限内按行权价格向期权的卖方卖出一定数量标的资产的权利。"},{"id":"jun-bas1-75","subject":"basics","source":"6月押题 LC","type":"多选","q":"从事基金服务业务的机构，按照中国证监会的有关规定应进行注册或者备案，这些机构包括 ()。","options":["从事公募基金的销售机构","从事公募基金的信息技术系统服务的机构","从事公募基金份额登记的机构","从事公募基金的投资顾问的机构"],"answer":"ABCD","explain":"基金管理人、基金托管人既是基金的当事人，又是基金的主要服务机构。除基金管理人与基金托管人外，基金市场上还有许多面向基金提供各类服务的其他服务机构。这些机构主要包括基金销售机构 (A 选项正确)、基金销售支付机构、基金份额登记机构 (C 选项正确)、基金估值核算机构、基金投资顾问机构 (D 选项正确)、基金评价机构、律师事务所、会计师事务所、信息技术系统服务机构 (B选项正确)等。从事基金服务业务的机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。故本题选 ABCD 选项。"},{"id":"jun-bas1-76","subject":"basics","source":"6月押题 LC","type":"多选","q":"程序化交易的优势包括 () 。","options":["扩展市场准入条件","为市场提供流动性","反应速度快于人脑","促进价格发现"],"answer":"BCD","explain":"程序化交易的优势主要在于：(1)程序化可以在交易过程中克服人性的弱点，不受交易者思想的干扰，排除人为情感因素，严格按照程序化的设定交易，用电脑取代人性，消除交易时人性的恐惧、贪婪、迟疑及赌性等四大情绪因子，完全实现人脑无法达到的稳定性。(2)程序化交易反应速度快于人脑 (C 选项正确)，可以突破人的生理极限，交易者在从大脑所想到手动需要一段时间来完成，特别是当投资者为了分散风险而进行多品种组合时，如果选择品种多一些更能降低交易风险，但是当行情激烈时多品种同时发生信号交易，那投资者的行为是顾及不了的，而电脑可以轻松完成。此外，程序化交易有助于为市场提供流动性 (B 选项正确)，促进价格发现 (D选项正确)。故本题选 BCD 选项。"},{"id":"jun-bas1-77","subject":"basics","source":"6月押题 LC","type":"多选","q":"承销是发行人将股票销售业务委托给专门的证券经营机构 (承销商)销售。承销方式有 ()。","options":["自销","包销","代销","直销"],"answer":"BC","explain":"B、C 选项正确，证券承销业务可以采取包销或者代销方式。故本题选 BC 选项。"},{"id":"jun-bas1-78","subject":"basics","source":"6月押题 LC","type":"多选","q":"北京证券交易所上市公司向特定对象发行股票的要求包括 ()。","options":["具备健全且运行良好的组织机构","具有独立稳定经营能力，不存在对持续经营有重大不利影响的情形","最近一年财务会计报告无虚假记载，未被出具否定意见或者无法表示意见的审计报告","最近一年财务会计报告被出具保留意见事项对上市公司意见的审计报告，保留意见所涉及的重大不利影响已经消除"],"answer":"ABCD","explain":"北交所上市公司向特定对象发行股票，应当符合下列规定：(1)具备健全且运行良好的组织机构 (A 选项正确)；(2)具有独立、稳定经营能力，不存在对持续经营有重大不利影响的情形 (B 选项正确)；(3)最近一年财务会计报告无虚假记载，未被出具否定意见或无法表示意见的审计报告 (C 选项正确)；(4)最近一年财务会计报告被出具保留意见的审计报告，保留意见所涉及事项对上市公司的重大不利影响已经消除(本次发行涉及重大资产重组的除外) (D 选项正确)；(5)合法规范经营，依法履行信息披露义务。故本题选 ABCD 选项。"},{"id":"jun-bas1-79","subject":"basics","source":"6月押题 LC","type":"多选","q":"2012 年 12 月修订后的《证券投资基金法》在许多方面实现了重大突破，主要有 () 。","options":["降低基金公司股东门槛","允许合资基金管理公司成立","允许保险资产管理机构发行公募基金","私募基金纳入监管"],"answer":"ACD","explain":"2012 年 12 月，修订后的《证券投资基金法》颁布并于 2013 年 6 月 1 日正式实施。新《证券投资基金法》在许多方面实现了重大突破，如将私募基金纳入监管(D 选项正确)；放开机构准入，允许券商、保险、私募等资产管理机构发行公募基金 (C 选项正确)；降低基金公司股东门槛 (A 选项正确)；放宽基金投资范围等。故本题选 ACD 选项。"},{"id":"jun-bas1-80","subject":"basics","source":"6月押题 LC","type":"判断","q":"企业短期融资券应由已在中国证监会备案的金融机构承销。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。企业发行短期融资券应由符合条件的金融机构承销，企业可自主选择主承销商。需要组织承销团的，由主承销商组织承销团。"},{"id":"jun-bas1-81","subject":"basics","source":"6月押题 LC","type":"判断","q":"目前，在我国基金投资活动中，基金买卖股票按照 0.1%的税率征收交易印花税，即对印花税实行双向征收。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基金卖出股票按照 0.05%的税率征收交易印花税，买入交易不征收印花税，即对印花税实行单向征收。"},{"id":"jun-bas1-82","subject":"basics","source":"6月押题 LC","type":"判断","q":"场外期权交易不只是机构投资者参与。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。场外期权交易仅限专业机构投资者参与，对于一般法人和机构投资者，其交易对手仅限符合一定条件的机构投资者，比如经验丰富的投资银行、商业银行等专业金融机构，期权合约的内容、交易方式等均由经验丰富的交易对手设计。"},{"id":"jun-bas1-83","subject":"basics","source":"6月押题 LC","type":"判断","q":"中长期银行贷款市场属于资本市场。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。资本市场，是指所交易金融资产到期期限在 1 年以上或者没有到期期限的金融市场，如股票市场、中长期国债市场、中长期银行贷款市场等。"},{"id":"jun-bas1-84","subject":"basics","source":"6月押题 LC","type":"判断","q":"我国已经逐渐形成了一个由货币市场、债券市场、股票市场、外汇市场、黄金市场、商品期货市场和金融衍生品市场等构成的，具有交易场所多层次、交易品种多样化和交易机制多元化等特征的金融市场体系。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。中国已经逐渐形成了一个由货币市场、债券市场、股票市场、外汇市场、黄金市场、商品期货市场和金融衍生品市场等构成的，具有交易场所多层次、交易品种多样化和交易机制多元化等特征的金融市场体系。"},{"id":"jun-bas1-85","subject":"basics","source":"6月押题 LC","type":"判断","q":"国债 (包括附息国债) 、企业债、公司债、证券公司次级债、中小企业私募债均可以跨市场转托管。其中，国债转托管速度最快， 目前已实现 T + 1 日到账，其他债券品种只能实现 T + 2 或 T + 3 日到账。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。目前，除了国债 (包括附息国债和地方债)和企业债可以跨市场转托管，其他债券品种 (包括公司债、证券公司次级债、中小企业私募债)都不能跨市场转托管。目前，最快的国债转托管能实现 T+1 日到账，其他大部分债券只能实现 T+2日甚至 T+3 日到账。"},{"id":"jun-bas1-86","subject":"basics","source":"6月押题 LC","type":"判断","q":"募集证券投资基金有一定人数和募集基金限额要求。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。封闭式基金需满足募集的基金份额总额达到核准规模的 80%以上，并且基金份额持有人人数达到 200 人以上；开放式基金需满足募集份额总额不少于 2 亿份，基金募集金额不少于 2 亿元人民币，基金份额持有人的人数不少于 200 人。"},{"id":"jun-bas1-87","subject":"basics","source":"6月押题 LC","type":"判断","q":"金融市场只能通过政府的干预性的价格决定 (利率)，将货币资金配置到生产效率最高的经济主体或部门，使这些部门能够获得更多的生产要素，从而提高全社会的产出，使资源的利用效率得到提高。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。金融市场通过竞争性的价格决定 (利率)，将货币资金配置到生产效率最高的经济主体或部门，使这些部门能够获得更多生产要素 (土地、资本、技术、劳动力)从而提高了全社会的产出，使资源的利用效率得到提高。"},{"id":"jun-bas1-88","subject":"basics","source":"6月押题 LC","type":"判断","q":"风险容忍度更接近于业务单元与实际风险特征联系紧密， 通常采用\"自下而上\"和\"自上而下\"相结合的方式设定。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。风险偏好的设定通常从战略角度出发，采取\"自上而下\"的设定方法；而风险容忍度更接近于业务单元，与实际风险特征联系紧密，通常采用\"自下而上\"和\"自上而下\"相结合的方式设定。"},{"id":"jun-bas1-89","subject":"basics","source":"6月押题 LC","type":"判断","q":"证券公司将合规管理有效性评估纳入内部控制评价的，其合规管理有效性评估工作应当符合该指引的要求，不必单独出具合规管理有效性评估报告。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。为指导证券公司开展合规管理有效性评估，有效防范和控制合规风险，2021年 5月28日，中国证券业协会发布《证券公司合规管理有效性评估指引 (2021修订)》。证券公司将合规管理有效性评估纳入内部控制评价的，其合规管理有效性评估工作应当符合该指引的要求，并单独出具合规管理有效性评估报告。"},{"id":"jun-bas1-90","subject":"basics","source":"6月押题 LC","type":"判断","q":"投资者应当以书面形式承诺其符合合格投资者标准，投资者的评估结果有效期最长不得超过 5 年。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。在向投资者推介私募基金之前，募集机构应当采取问卷调查等方式履行特定对象确定程序，对投资者的风险识别能力和风险承担能力进行评估。投资者应当以书面形式承诺其符合合格投资者标准。投资者的评估结果有效期最长不得超过 3 年。"},{"id":"jun-bas1-91","subject":"basics","source":"6月押题 LC","type":"判断","q":"根据金融资产确认和计量的会计准则，一旦被确认为衍生产品或可分离的嵌入式衍生产品，相关机构应把这一部分资产归入交易性资产类别，按照公允价格计价。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。根据金融资产确认和计量的会计准则，一旦被确认为衍生产品或可分离的嵌入式衍生产品，相关机构就要把这一部分资产归入交易性资产类别，按照公允价格计价。"},{"id":"jun-bas1-92","subject":"basics","source":"6月押题 LC","type":"判断","q":"可交换债券和可转换债券不同，可转换债券是上市公司股东发行，可交换债券是上市公司本身发行。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。可交换债券与可转换债券也有明显的区别。其中发行主体不同：可交换债券的发行主体是上市公司的股东，而可转换债券的发行主体是上市公司本身。"},{"id":"jun-bas1-93","subject":"basics","source":"6月押题 LC","type":"判断","q":"中国证券业协会依据相关法规，监督、检查会员、从业人员行为，对违反法律、行政法规等情形的，可按照规定采取责令改正、监管谈话、出具警示函等措施。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。责令改正、监管谈话、出具警示函属于国务院证券监督管理机构的权限。【乐知识】为防范证券市场风险，维护市场秩序，国务院证券监督管理机构可以采取责令改正、监管谈话、出具警示函等措施。"},{"id":"jun-bas1-94","subject":"basics","source":"6月押题 LC","type":"判断","q":"按股东享有权利的不同，股票可以分为普通股票和特殊股票。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。按股东享有权利的不同，股票可以分为普通股票和特别股票。"},{"id":"jun-bas1-95","subject":"basics","source":"6月押题 LC","type":"判断","q":"可转换债券的回购是指当公司股票价格在一段时间内连续高于转换价格达到一定幅度时，可转换公司债券持有人按事先约定的价格将所持可转换债券卖给发行人的行为。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。可转换公司债券的赎回条件一般是当公司股票价格在一段时间内连续高于转换价格达到一定幅度时，公司可按照事先约定的赎回价格买回发行在外尚未转股的可转换债券。可转换公司债券的回售是指公司股票在一段时间内连续低于转换价格达到某一幅度时，可转换债券持有人按事先约定的价格将所持可转换债券卖给发行人的行为。"},{"id":"jun-bas1-96","subject":"basics","source":"6月押题 LC","type":"判断","q":"股票和债券都是直接投资的金融工具，筹集的资金主要投向实业。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。股票和债券是直接投资工具，筹集的资金主要投向实业；而基金是间接投资工具，筹集的资金主要投向有价证券等金融工具。"},{"id":"jun-bas1-97","subject":"basics","source":"6月押题 LC","type":"判断","q":"根据《证券公司监督管理条例》，证券公司从事证券经纪业务，可以委托证券公司以外的金融机构作为证券经纪人，代理其进行客户招揽、客户服务等活动。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据《证券公司监督管理条例》，证券公司从事证券经纪业务，可以委托证券公司以外的人员作为证券经纪人(委托自然人而非机构)，代理其进行客户招揽、客户服务。【乐知识】证券经纪业务又称为代理买卖证券业务，是指证券公司接受客户委托代客户买卖有价证券的业务。在证券经纪业务中，证券公司只收取一定比例的佣金作为业务收入。"},{"id":"jun-bas1-98","subject":"basics","source":"6月押题 LC","type":"判断","q":"影响股票投资价值的内部因素主要包括公司净资产、盈利水平、股利政策、股份分割、增资和减资以及并购重组等。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。影响股票投资价值的内部因素主要包括公司净资产、盈利水平、股利政策、股份分割、增资和减资以及并购重组等。"},{"id":"jun-bas1-99","subject":"basics","source":"6月押题 LC","type":"判断","q":"根据损失事件类型可将操作风险划分为八种表现形式。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。操作风险根据损失事件类型划分为七种表现形式：内部欺诈，外部欺诈，就业制度和工作场所安全，客户、产品和业务活动，实物资产的损坏，营业中断和信息技术系统瘫痪，执行、交割和流程管理。"},{"id":"jun-bas1-100","subject":"basics","source":"6月押题 LC","type":"判断","q":"目前，我国创业板上市实行备案制。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。2020 年 4 月 27 日，中央全面深化改革委员会第十三次会议审议通过了《创业板改革并试点注册制总体实施方案》。2020 年 8 月 24 日，深圳市创业板改革并试点注册制平稳落地。首批 18 家创业板注册制企业上市交易。2023 年 2 月 17 日，中国证监会及交易所等发布全面实行股票发行注册制制度规则，覆盖主板、科创板、创业板和北交所。目前，我国创业板上市实行的是注册制，而非备案制。"},{"id":"jun-bas1-101","subject":"basics","source":"6月押题 LC","type":"判断","q":"中央政府债券可视为无风险证券。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。中央政府拥有税收、货币发行特权，通常情况下，中央政府债券不存在违约风险，因此，这一类证券被视为无风险证券，相对应的证券收益率被称为无风险利率，是金融市场上最重要的价格指标。"},{"id":"jun-bas1-102","subject":"basics","source":"6月押题 LC","type":"判断","q":"按照委托时效可以把委托分为：当日委托，定时委托， 限价委托， 当周委托， 无限期委托， 开市委托， 收市委托。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据委托时效限制，可分为当日委托、当周委托、无期限委托、开市委托和收市委托等。"},{"id":"jun-bas1-103","subject":"basics","source":"6月押题 LC","type":"判断","q":"国债的竞争性招标方式包括单一价格、修正的多重价格招标方式 (即混合式)，招标标的仅为利率。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。国债的竞争性招标方式包括单一价格、修正的多重价格招标方式 (即混合式)，招标标的为利率或价格 (并非仅为利率)。"},{"id":"jun-bas1-104","subject":"basics","source":"6月押题 LC","type":"判断","q":"基金经营活动中，买卖债券、股票等实现的差价收益为利息收入。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。投资收益是指基金经营活动中因买卖股票、债券、资产支持证券、基金等实现的差价收益，具体可分为股票投资收益、债券投资收益、资产支持证券投资收益、基金投资收益、衍生工具收益、股利收益等。"},{"id":"jun-bas1-105","subject":"basics","source":"6月押题 LC","type":"判断","q":"首次公开发行证券，持有一定数量的非限售股份或国债的投资者才能参与网上申购。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。首次公开发行证券，网上投资者应当持有一定数量非限售股份或存托凭证 (并非\"国债\")，并自主表达申购意向，不得概括委托证券公司进行证券申购。采用其他方式进行网上申购和配售的，应当符合中国证监会的有关规定。"},{"id":"jun-bas1-106","subject":"basics","source":"6月押题 LC","type":"判断","q":"按收益保障性分类可将结构化金融衍生产品分为股权联结型产品、利率联结型产品、汇率联结型产品和商品联结型产品等种类。 ()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。按联结的基础产品分类 (并非按收益保障性分类)，结构化金融衍生产品可分为股权联结型产品 (其收益与单只股票、股票组合或股票价格指数相联系)、利率联结型产品、汇率联结型产品、商品联结型产品等种类。"},{"id":"jun-bas1-107","subject":"basics","source":"6月押题 LC","type":"判断","q":"按交割方式，金融市场可为现货市场和衍生品市场。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。按交割方式金融市场可分为现货市场和衍生品市场。"},{"id":"jun-bas1-108","subject":"basics","source":"6月押题 LC","type":"判断","q":"货币供给额与基础货币之间的倍数关系，称为货币乘数。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。商业银行可以根据基础货币，创造出数倍的货币供给额，其中，基础货币和货币供给之间的倍数关系，被称为货币乘数。"},{"id":"jun-bas1-109","subject":"basics","source":"6月押题 LC","type":"判断","q":"金融风险是指包括金融机构在内的各个经济主体在金融活动或投资经营活动中，因各种因素的不确定变动而遭受损失的可能。 ()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。金融风险，是指包括金融机构在内的各个经济主体在金融活动或投资经营活动中，因各种因素的不确定变动而遭受损失的可能性。"},{"id":"jun-bas1-110","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】2023 年 2 月 1 日, 某票面利率 5%, 面值 100 元, 每年付息 1次的债\n券，T+0 成交净价 101 元，该只债券上次付息为 2022 年 12 月 31 日。\n请根据上述材料回答问题。\n\n【问题】成交当天该只债券的累计天数是 () 。","options":["31","30","33","32"],"answer":"A","explain":"A 选项正确, 按实际天数/360 (ACT/360) 计算, 累计天数 (算头不算尾) =31 (1月) +0 天 (2 月) =31 天。故本题选 A 选项。"},{"id":"jun-bas1-111","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】2023 年 2 月 1 日, 某票面利率 5%, 面值 100 元, 每年付息 1次的债\n券，T+0 成交净价 101 元，该只债券上次付息为 2022 年 12 月 31 日。\n请根据上述材料回答问题。\n\n【问题】该只债券的实际支付价格是 () 。","options":["101.43","100.66","101.12","100.44"],"answer":"A","explain":"从 2022 年 12 月 31 日到 2023 年 2 月 1 日大约是一个月的时间(31 天)。一年有365 天，所以这段时间占一年的比例是:31/365, 债券的年利息是面值的 5%,即:100 元×5%=5 元。因此，这一个月的利息是：5 元×31/365≈0.43；实际支付价格=101+0.43=101.43元 (A 选项正确) 。故本题选 A 选项。"},{"id":"jun-bas1-112","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】A 公司于 2016 年在上海证券交易所上市，上市后该公司一直保持盈\n利，但盈利水平逐年降低，至 2021 年，其一个完整会计年度经审计的净利润为\n负且营业收入低于人民币 1 亿元。\n暂不考虑其他因素，请根据上述背景信息回答以下问题。\n1. 2022 年度，该公司一个完整会计年度经审计的期末净资产为负值。上海证券\n交易所可以决定 ()。\nA、报告中国证监会提请对该公司进行现场稽查\nB、终止该公司股票上市\nC、责令该公司股票停牌 2 个月\nD、对该公司股票实施退市风险警示\n正确答案： B\n名师解析：\n根据规定，上市公司最近连续两个会计年度经审计的财务会计报告相关财务指标\n触及规定的财务类强制退市情形的，证券交易所决定终止其股票上市。\n本题中，该公司 2021 年度、2022 年度连续 2 个会计年度触及财务类退市情形，\n证券交易所可以决定终止其股票上市 (B 选项正确)。\n故本题选 B 选项。\n\n【问题】截至 2021 年，其一个完整会计年度经审计的净利润为负且营业收入低于人民币 1 亿元。根据上海证券交易所的相关规则，下列有关说法错误的有 ()。","options":["上海证券交易所可以决定对该公司股票实施退市风险警示","上海证券交易所可以决定暂停该公司股票上市","上海证券交易所可以对该公司股票停牌","上海证券交易所可以决定直接终止该公司股票上市"],"answer":"BCD","explain":"A 选项正确，上市公司 2021 年度财务指标触及财务类强制退市情形第一条，证券交易所对其股票实施退市风险警示。故本题选 BCD 选项。【乐知识】上市公司出现下列财务类强制退市情形之一的，证券交易所对其股票实施退市风险警示：①最近一个会计年度经审计的利润总额、净利润或者扣除非经常性损益后的净利润孰低者为负值且营业收入低于 3 亿元，或追溯重述后最近一个会计年度利润总额、净利润或者扣除非经常性损益后的净利润孰低者为负值且营业收入低于 3亿元。②最近一个会计年度经审计的期末净资产为负值，或追溯重述后最近一个会计年度期末净资产为负值。③最近一个会计年度的财务会计报告被出具无法表示意见或否定意见的审计报告。④中国证监会行政处罚决定书表明公司已披露的最近一个会计年度经审计的年度报告存在虚假记载、误导性陈述或者重大遗漏，导致该年度相关财务指标实际已触及第①项、第②项情形的。⑤证券交易所认定的其他情形。上市公司最近一个会计年度经审计的财务会计报告相关财务指标触及规定的财务类强制退市情形的，证券交易所对其股票实施退市风险警示。上市公司最近连续两个会计年度经审计的财务会计报告相关财务指标触及规定的财务类强制退市情形的，证券交易所决定终止其股票上市。"},{"id":"jun-bas1-113","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】假定商业银行法定存款准备金率为 20%，超额存款准备金率为 5%，\n并且实行客户一切款项均存入商业银行的非现金结算制度，客户李某将 10000\n元现金存入商业银行，一段时间以后，中央银行取消了超额存款准备金率和非现\n金结算制度，现金比率定为 5%，这时客户王某将 30000 元现金存入商业银行。\n不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】在中央银行货币政策调整前，李某的原始存款货币乘数为 ()。","options":["20","4","6.67","5"],"answer":"B","explain":"完整的货币乘数公式为： m = (c + 1) / (c + r + e)。因为没有考虑到现金比率，( c = 0 )，因此 m=1/ (20%+5%)= 4 (B 选项正确)。故本题选 B 选项。"},{"id":"jun-bas1-114","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】假定商业银行法定存款准备金率为 20%，超额存款准备金率为 5%，\n并且实行客户一切款项均存入商业银行的非现金结算制度，客户李某将 10000\n元现金存入商业银行，一段时间以后，中央银行取消了超额存款准备金率和非现\n金结算制度，现金比率定为 5%，这时客户王某将 30000 元现金存入商业银行。\n不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】在中央银行货币政策调整后，王某的原始存款可以被商业银行创造出 ()万元货币供给。","options":["12.6","12","20","15"],"answer":"A","explain":"现实中，完整的货币乘数公式为： m = (c + 1) / (c + r + e)；其中 c为提现率 (即现金比率)，为客户提取的现金与活期存款总额之比；e 为超额存款准备金率，为超额准备金与存款总额的比例。本题中，在中央银行货币政策调整后，取消了超额存款准备金率，因此 e = 0 ；现金比率 c = 5% ；法定存款准备金率r = 20% ，将数值代入公式得 m = (5% +1) / (5% + 20% + 0) = 4.2 。王某将 30000 元现金存入商业银行，因此他的原始存款为 3 万元。货币供给=原始存款×货币乘数，则王某可以被商业银行创造出的货币为 3 万 × 4.2 = 12.6万元 (A 选项正确) 。故本题选 A 选项。"},{"id":"jun-bas1-115","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】假定商业银行法定存款准备金率为 20%，超额存款准备金率为 5%，\n并且实行客户一切款项均存入商业银行的非现金结算制度，客户李某将 10000\n元现金存入商业银行，一段时间以后，中央银行取消了超额存款准备金率和非现\n金结算制度，现金比率定为 5%，这时客户王某将 30000 元现金存入商业银行。\n不考虑其他相关影响因素，请根据上述背景信息回答以下问题。\n\n【问题】如不考虑其他因素影响，关于中央银行调整货币政策的措施与效果，下列说法正确的有 ()。","options":["取消非现金结算制度将使货币乘数增加","降低超额存款准备金率将使货币乘数增加","提高现金比率将使货币乘数减小","提高法定存款准备金率将使货币乘数减小"],"answer":"BCD","explain":"现实中，影响货币乘数的因素主要为法定存款准备金率、超额准备金率及提现率。这些因素和货币乘数为反向变动的关系，即提高这些比率将降低货币乘数，而降低这些比率将增加货币乘数。取消非现金结算制度说明允许客户使用现金结算，则一部分存款以现金的形式被公众提取出来，并持续地保留在公众手中，那就意味着提现率 (现金比率)的增加。提现率增加将使货币乘数减少 (A 选项错误)。降低超额存款准备金率将使货币乘数增加 (B 选项正确) 。提高现金比率将使货币乘数减小 (C 选项正确)。提高法定存款准备金率将使货币乘数减小 (D 选项正确) 。故本题选 BCD 选项。"},{"id":"jun-bas1-116","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】证券金融公司履行《转融通业务监督管理试行办法》规定的职责，为证券\n公司融资融券业务提供资金和证券的转融通服务等，其不以盈利为目的，但是因\n为开展转融通业务，有稳定的营业收入和利润。某证券公司于 202x 年 5 月 4 日\n按照规定取得融资融券和转融通业务资格，与证券金融公司于 6 月 1 日签订转融\n通业务合同。6 月 20 日证券金融公司决定向该证券公司交付首笔转融通资金，\n并于 6 月 25 日实际交付完成该笔资金。证券金融公司按照规定向该证券公司收\n取一定的保证金，保证金由货币资金和证券冲抵。\n不考虑其他相关影响因素，请根据上述背景信息回答下列问题。\n\n【问题】关于证券金融公司可用于开展转融通业务的资金来源，下列说法正确的有 ()。","options":["自有资金","通过证券交易所的业务平台融入的资金","通过证券金融公司的业务平台融入的资金","自有证券"],"answer":"ABC","explain":"证券金融公司开展转融通业务的资金和证券来源：①自有资金和证券 (A 选项正确、D 选项错误，题目问的是资金来源)；②通过证券交易所的业务平台融入的资金和证券 (B 选项正确)；③通过证券金融公司的业务平台融入的资金或者依法筹集的其他资金和证券 (C选项正确)；④证券金融公司可以发行公司债券，也可以向股东或者其他特定投资者借入次级债。故本题选 ABC 选项。"},{"id":"jun-bas1-117","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】证券金融公司履行《转融通业务监督管理试行办法》规定的职责，为证券\n公司融资融券业务提供资金和证券的转融通服务等，其不以盈利为目的，但是因\n为开展转融通业务，有稳定的营业收入和利润。某证券公司于 202x 年 5 月 4 日\n按照规定取得融资融券和转融通业务资格，与证券金融公司于 6 月 1 日签订转融\n通业务合同。6 月 20 日证券金融公司决定向该证券公司交付首笔转融通资金，\n并于 6 月 25 日实际交付完成该笔资金。证券金融公司按照规定向该证券公司收\n取一定的保证金，保证金由货币资金和证券冲抵。\n不考虑其他相关影响因素，请根据上述背景信息回答下列问题。\n\n【问题】不考虑特殊情况下转融通期限的顺延或者缩短的情形，该证券公司获得的首笔转融通资金的期限截止日不得超过当年的 ()。","options":["11 月 4 日","12 月 1 日","12 月 20 日","12 月 25 日"],"answer":"D","explain":"证券金融公司向证券公司转融通的期限不得超过 6 个月。转融通的期限，自资金或者证券实际交付之日起算。本题 6 月 20 日证券金融公司决定向该证券公司交付首笔转融通资金，并于 6 月"},{"id":"jun-bas1-118","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】证券金融公司履行《转融通业务监督管理试行办法》规定的职责，为证券\n公司融资融券业务提供资金和证券的转融通服务等，其不以盈利为目的，但是因\n为开展转融通业务，有稳定的营业收入和利润。某证券公司于 202x 年 5 月 4 日\n按照规定取得融资融券和转融通业务资格，与证券金融公司于 6 月 1 日签订转融\n通业务合同。6 月 20 日证券金融公司决定向该证券公司交付首笔转融通资金，\n并于 6 月 25 日实际交付完成该笔资金。证券金融公司按照规定向该证券公司收\n取一定的保证金，保证金由货币资金和证券冲抵。\n不考虑其他相关影响因素，请根据上述背景信息回答下列问题。\n\n【问题】根据相关规定，该证券公司交存的货币资金占应收取保证金的比例最低为()。","options":["10%","12%","15%","20%"],"answer":"C","explain":"证券金融公司开展转融通业务，应当向证券公司收取一定比例的保证金。保证金可以证券充抵，但货币资金占应收取保证金的比例不得低于 15%(C 选项正确)。故本题选 C 选项"}]},{"id":"jun-bas2","subject":"basics","name":"6月押题 · 金融卷二","stats":{"单选":40,"多选":40,"判断":30,"案例":1},"questions":[{"id":"jun-bas2-0","subject":"basics","source":"6月押题 LC","type":"单选","q":"做市商交易的基本特征是 () 。","options":["证券交易的买价和卖价都由做市商给出","以买卖双向价格为基准进行撮合","成交时点是不连续的","投资者买卖证券的对手是其他投资者"],"answer":"A","explain":"答案解析：A 选项正确，在做市商交易市场中，证券交易的买价和卖价都由做市商给出，做市商将根据市场的买卖力量和自身情况进行证券的双向报价。投资者之间并不直接成交，而是从做市商手中买进证券或向做市商卖出证券。B、D 选项错误，属于指令驱动的特点。指令驱动是一种竞价市场，也称为订单驱动市场。在竞价市场中，证券交易价格是由市场上的买方订单和卖方订单共同驱动的。指令驱动的特点有：第一，证券交易价格由买方和卖方的力量直接决定；第二，投资者买卖证券的对手是其他投资者。C 选项错误，成交时间不连续，是定期交易的特点。"},{"id":"jun-bas2-1","subject":"basics","source":"6月押题 LC","type":"单选","q":"主板市场对发行人的营业期限、股本大小、盈利水平、最低市值等方面的要求标准较高，上市企业多为() 。","options":["创新型企业","大型成熟企业","创业型企业","成长型企业"],"answer":"B","explain":"答案解析：B 选项正确，主板市场对发行人的营业期限、股本大小、盈利水平、最低市值等方面的要求标准较高，上市企业多为大型成熟企业，具有较大的资本规模以及稳定的盈利能力。故本题选 B 选项。"},{"id":"jun-bas2-2","subject":"basics","source":"6月押题 LC","type":"单选","q":"中国证券业协会采取 ()的组织形式。","options":["行纪制","契约制","会员制","经纪制"],"answer":"C","explain":"答案解析：C 选项正确，中国证券业协会采取会员制的组织形式，证券公司应当加入中国证券业协会。故本题选 C 选项。"},{"id":"jun-bas2-3","subject":"basics","source":"6月押题 LC","type":"单选","q":"证券业协会是证券行业的 ()。","options":["证券监督机构","证券服务机构","自律性组织","会员单位"],"answer":"C","explain":"答案解析：C 选项正确，中国证券业协会是证券业的自律性组织，是社会团体法人。故本题选 C 选项。"},{"id":"jun-bas2-4","subject":"basics","source":"6月押题 LC","type":"单选","q":"证券公司为客户提供证券代理买卖业务收取的费用是 ()。","options":["佣金","过户费","投顾费","印花税"],"answer":"A","explain":"答案解析：证券经纪业务又称为代理买卖证券业务，是指证券公司接受客户委托代客户买卖有价证券的业务。在证券经纪业务中，证券公司只收取一定比例的佣金(A 选项正确)作为业务收入。"},{"id":"jun-bas2-5","subject":"basics","source":"6月押题 LC","type":"单选","q":"债券现券买卖的交易方式为 ()，结算方式为() 。","options":["全价交易；全价结算","净价交易；净价结算","净价交易；全价结算","全价交易；净价结算"],"answer":"C","explain":"答案解析：C 选项正确，现券买卖，是指交易成员约定以某一价格转让其持有债券的交易行为。现券买卖按净价交易，全价结算。故本题选 C 选项。"},{"id":"jun-bas2-6","subject":"basics","source":"6月押题 LC","type":"单选","q":"在全球金融体系的主要参与者中，不属于存款吸收机构的是()。","options":["储蓄银行","证券交易商","抵押贷款银行","信用合作社"],"answer":"B","explain":"答案解析：存款吸收机构，是指通过自己的账户，以中介的方式将资金从贷款人转向借款人的单位。存款吸收机构包括商业银行 (在支付系统中处于核心地位)和其他存款吸收机构。其他存款吸收机构包括储蓄银行 (A 选项不符合题意)、开发银行、信用合作社 (D 选项不符合题意)、投资银行、抵押贷款银行 (C 选项不符合题意)以及建房互助协会、吸收存款的小额贷款机构。故本题选 B 选项。"},{"id":"jun-bas2-7","subject":"basics","source":"6月押题 LC","type":"单选","q":"优先股的股息率固定这一点与 ()相似。","options":["期权","普通股票","债券","期货"],"answer":"C","explain":"答案解析：普通股票、期权和期货的收益都不是固定的 (A、B、D 选项错误)。故本题选 C选项。"},{"id":"jun-bas2-8","subject":"basics","source":"6月押题 LC","type":"单选","q":"影响我国金融市场的政策因素不包括 () 。","options":["法律政策","财政政策","收入政策","货币政策"],"answer":"A","explain":"答案解析：影响中国金融市场运行的政策因素主要包括：(1)金融监管政策；(2)货币政策 (D选项不符合题意，属于宏观经济政策) ;(3)财政政策 (B 选项不符合题意，属于宏观经济政策) ;(4)收入政策 (C 选项不符合题意，属于宏观经济政策) 。A 选项符合题意，不包括法律政策。"},{"id":"jun-bas2-9","subject":"basics","source":"6月押题 LC","type":"单选","q":"一只年息 5%、面值 100 元、每年付息一次的 2 年期债券，可以分拆为 () 。","options":["面值为 5 元的 1 年期零息债券+面值为 105 元的 2 年期零息债券","面值为 5 元的 2 年期零息债券+面值为 110 元的 1 年期零息债券","面值为 5 元的 2 年期零息债券+面值为 105 元的 1 年期零息债券","面值为 5 元的 1 年期零息债券+面值为 110 元的 2 年期零息债券"],"answer":"A","explain":"答案解析：(1)原债券的现金流：①第 1 年末:支付利息=100×5%=5 元;②第 2 年末:支付本金+利息=100+100×5%=105 元。(2)匹配零息债券：①第 1 年末的 5 元现金流，对应面值 5 元、期限 1 年的零息债券；②第 2 年末的 105 元现金流，对应面值105 元、期限 2 年的零息债券。即可以分拆为：面值为 5 元的 1 年期零息债券+面值为 105 元的 2 年期零息债券 (A 选项正确)。"},{"id":"jun-bas2-10","subject":"basics","source":"6月押题 LC","type":"单选","q":"一般性货币政策工具不包括 () 。","options":["存款准备金率","货币供给增长率","公开市场业务","再贴现率"],"answer":"B","explain":"答案解析：一般性货币政策工具是指中央银行普遍或常规运用的货币政策工具，其实施对象是整体经济和金融活动，主要包括存款准备金制度 (A 选项不符合题意)、再贴现政策 (D 选项不符合题意)和公开市场业务 (C 选项不符合题意)三大工具。故本题选 B 选项。"},{"id":"jun-bas2-11","subject":"basics","source":"6月押题 LC","type":"单选","q":"一般而言，基金全部资产的价值总和指的是 () 。","options":["基金份额净值","基金负债","基金资产总值","基金总份额"],"answer":"C","explain":"答案解析：C 选项正确，基金资产总值，是指基金全部资产的价值总和。故本题选 C 选项。"},{"id":"jun-bas2-12","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列情形符合面向专业投资者公开发行公司债券要求的是 ()。","options":["发行人最近三年平均可分配利润足以支付公司债券一年的利息","违反《证券法》规定，改变公开发行公司债券所募资金用途","发行人对已公开发行的公司债券有违约的事实，仍处于继续状态","发行人对已公开发行的公司债券有延迟支付本息的事实，仍处于继续状态"],"answer":"A","explain":"答案解析：(1)根据《公司债券发行与交易管理办法》，公开发行公司债券，应当符合下列条件：①具备健全且运行良好的组织机构；②最近三年平均可分配利润足以支付公司债券一年的利息 (A 选项正确)；③具有合理的资产负债结构和正常的现金流量；④国务院规定的其他条件。(2)存在下列情形之一的，不得再次公开发行公司债券：①对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态 (C、D 选项错误) ;②违反《证券法》规定，改变公开发行公司债券所募资金用途 (B 选项错误)。"},{"id":"jun-bas2-13","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于中小非金融企业集合票据的说法，错误的是 ()。","options":["设立投资者保护机制更加重要","企业发行集合票据应披露集合票据债项评级、各企业主体信用评级","能解决单个企业独立发行规模小、流动性不足的问题","集合票据相关政策指引对发行期限做出了硬性规定"],"answer":"D","explain":"答案解析：A 选项正确，中小企业集合票据发行主体通常信用级别较低，设立投资者保护机制就变得尤为必要。企业应在集合票据发行文件中约定投资者保护机制，包括应对任一企业及信用增进机构主体信用评级下降或财务状况恶化、集合票据债项评级下降以及其他可能影响投资者利益情况的有效措施。B 选项正确，企业发行集合票据应披露集合票据债项评级、各企业主体信用评级以及专业信用增进机构(若有)主体信用评级。C 选项正确，集合票据由多家中小企业构成的联合发行人作为债券发行主体集合发行，各发行企业作为独立负债主体，在各自的发行额度内承担按期还本付息的义务，并按照相应比例承担发行费用，集合发行能够解决单个企业独立发行规模小、流动性不足的问题。D 选项错误，中小非金融企业集合票据的特点之一是发行期限灵活， 《银行间债券市场中小非金融企业集合票据业务指引》未对发行期限作出硬性规定，但由于中小企业经营发展具有较大的不确定性，为有效控制风险，中小企业集合票据的期限也不宜过长，具体产品期限结构可由主承销商和发行主体结合市场环境协商确定。故本题选 D 选项。"},{"id":"jun-bas2-14","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于中国证监会派出机构的说法，错误的是() 。","options":["中国证监会在省、自治区、直辖市和计划单列市设立了 36 个证券监管局","派出机构以中国证监会的名义履行监管职责，负责辖区内一线监管工作","中国证监会在上海、深圳设立了证券监管专员办事处","派出机构受中国证监会垂直领导"],"answer":"B","explain":"答案解析：中国证监会在省、自治区、直辖市和计划单列市设立了36 个证券监管局，以及上海、深圳证券监管专员办事处(A、C 选项正确) 。根据《中国证监会派出机构监管职责规定》 (2022 年修订)，派出机构受中国证监会垂直领导，依法以自己的名义履行监管职责，派出机构负责证券期货市场一线监管工作 (B 选项错误、D 选项正确)。故本题选 B 选项。"},{"id":"jun-bas2-15","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于直接融资和间接融资的说法，正确的是() 。","options":["商业信用融资属于直接融资的一种","租赁融资属于直接融资的一种","风险投资由风险投资机构提供，属于间接融资的一种","民间借贷属于间接融资的一种"],"answer":"A","explain":"答案解析：A 选项正确，C、D 选项错误；直接融资的方式有：股票市场融资、证券市场融资、风险投资融资、商业信用融资、民间借贷。B 选项错误，间接融资的方式有：银行信用融资、消费信用融资、租赁融资。"},{"id":"jun-bas2-16","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于我国多层次资本市场意义的说法，错误的是 ()。","options":["可以提供更为高效透明的定价机制和灵活多样的支付工具与融资手段，推动产业结构调整","尽管无助于增强中国在国际大宗商品领域的话语权，但可以提高我国资本市场和证券期货服务业的国际竞争力","可以提供多种类型的金融产品和交易场所，有利于促进生产要素自由流动，激发经济增长活力","可以通过提供风险投资、私募股权投资等建立融资方和投资方风险共担、利益共享的机制，缓解中小企业和科技创新型企业融资难问题"],"answer":"B","explain":"答案解析：A 选项正确，多层次资本市场可以提供更加高效透明的定价机制和灵活多样的支付工具与融资手段，推动产业结构调整。B 选项错误，健全多层次资本市场体系有利于增强中国在国际大宗商品领域的话语权，提高中国资本市场和证券期货服务业的国际竞争力。C 选项正确，多层次资本市场体系可以提供多种类型的金融产品和交易场所，为多样化的投融资需求打造高效匹配的平台，有利于促进生产要素自由流动，激发经济增长活力。D 选项正确，多层次资本市场可以通过提供风险投资、私募股权投资等建立融资方和投资方风险共担、利益共享的机制，缓解中小企业和科技创新型企业融资难问题。故本题选 B 选项。"},{"id":"jun-bas2-17","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于投资理念的说法，错误的是 () 。","options":["不同类型的基金具有相同的投资理念","投资理念的确定隐含对投资期限的抉择","投资理念包含投资目的","投资理念包含投资方法"],"answer":"A","explain":"答案解析：投资理念包含两个层面：一是为什么要投资，即投资的目的是什么 (C 选项正确)；二是怎样投资，即投资的方法是什么 (D 选项正确)。投资理念的确定隐含着一系列投资抉择，包括对投资风险偏好的抉择、对投资期限的抉择、对投资策略的抉择等 (B 选项正确)。不同类型的基金具有各自不同的投资理念和投资风格(A选项错误)，对投资收益的追求与风险的控制也各不相同，对基金类型的判断和认定，将有助于投资者对适合自己风险偏好和收益目标的基金进行投资。"},{"id":"jun-bas2-18","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于认购与申购的说法，错误的是 () 。","options":["认购是指发生在基金设立募集期内的购买行为","申购基金时，基金申购价格已知","申购是指发生在基金合同生效后的购买行为","认购期内产生的利息在基金合同生效时一般会自动转换为投资者的基金份额"],"answer":"B","explain":"答案解析：A 选项正确，认购指在基金设立募集期内，投资者申请购买基金份额的行为。B选项错误，申购基金时，基金申购价格未知，依据申购日基金份额净值加、减有关费用计算。C 选项正确，申购指在基金合同生效后，投资者申请购买基金份额的行为。D 选项正确.在认购期内产生的利息在基金合同生效时，一般会自动转换为投资者的基金份额，基金份额在基金合同生效时确认，并且在开放期才能赎回。故本题选 B 选项。"},{"id":"jun-bas2-19","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列关于基金利润分配的说法，错误的是 () 。","options":["封闭式基金年度收益分配比例不得低于基金年度可供分配利润的 10%","根据有关规定，封闭式基金的收益分配每年不得少于一次，基金分配后，基金份额净值不得低于面值","普通货币市场基金在每日进行利润分配时，当日申购的基金份额自下一个工作日起享有基金的分配权益，当日赎回的基金份额自下一个工作日起不享有基金的分配权益","根据有关规定，一般开放式基金利润分配默认的方式应当采用现金分红。开放式基金的基金份额持有人可以事先选择分红再投资。基金份额持有人事先未作出选择的，基金管理人应当支付现金"],"answer":"A","explain":"答案解析：A 选项错误，封闭式基金年度收益分配比例不得低于基金年度可供分配利润的90%。B 选项正确，根据有关规定，封闭式基金的收益分配每年不得少于一次，基金分配后，基金份额净值不得低于面值。C 选项正确，普通货币市场基金在每日进行利润分配时，当日申购的基金份额自下一个工作日起享有基金的分配权益，当日赎回的基金份额自下一个工作日起不享有基金的分配权益。D 选项正确，根据有关规定，一般开放式基金利润分配默认的方式应当采用现金分红。开放式基金的基金份额持有人可以事先选择分红再投资。基金份额持有人事先未作出选择的，基金管理人应当支付现金。"},{"id":"jun-bas2-20","subject":"basics","source":"6月押题 LC","type":"单选","q":"下列各项中，属于证券公司战略风险内部来源的是() 。","options":["行业风险","竞争对手风险","决策执行不当风险","客户风险"],"answer":"C","explain":"答案解析：战略风险是指证券公司在追求短期商业目的和长期发展目标的过程中，因不适当的发展规划和战略决策给证券公司造成损失或不利影响的风险。战略风险来源于两个方面：(1)证券公司内部经营管理活动，包括宏观战略、中观管理和微观执行三个层面 (C 选项正确)；(2) 外部政治. 经济、 社会、 科技等环境的变化..包括行业风险 (A 选项错误)、技术风险、品牌风险、竞争对手风险 (B 选项错误)、客户风险 (D 选项错误) 、项目风险、发展停滞风险等。故本题选 C 选项。"},{"id":"jun-bas2-21","subject":"basics","source":"6月押题 LC","type":"单选","q":"我国某大型金融机构通过发行金融债券进行直接融资，该金融债券的特点之一是 () 。","options":["一般需记名、可挂失","该金融债券表示的是银行等金融机构与金融债券持有者之间的债权债务关系","该金融债券的利息计复利，能提前支取","该金融债券利率一般低于同期储蓄利率"],"answer":"B","explain":"答案解析：金融债券作为债券的一种特殊类型，它具有以下特点：(1)金融债券表示的是银行等金融机构与金融债券持有者之间的债权债务关系 (B 选项符合题意)；(2)金融债券一般不记名、不挂失，但可以抵押和转让 (A 选项不符合题意)；(3)金融债券的利息不计复利，不能提前支取，延期兑付亦不计逾期利息 (C 选项不符合题意)；(4)金融债券的利率固定，一般都高于同期储蓄利率(D 选项不符合题意)；(5)我国发行金融债券所筹集的资金一般都专款专用，如中国建设银行曾发行的投资债券，其主要用途就是为国家大中型建设项目筹措资金。故本题选 B 选项。"},{"id":"jun-bas2-22","subject":"basics","source":"6月押题 LC","type":"单选","q":"通过各种通信方式，不通过集中的交易所，实行分散的、一对一交易的金融衍生工具符合 () 的特征。","options":["嵌入式衍生工具","OTC 交易的衍生工具","结构化金融衍生工具","交易所交易的衍生工具"],"answer":"B","explain":"答案解析：B 选项正确，场外交易市场 (OTC)交易的衍生工具是指通过各种通讯方式，不通过集中的交易所，实行分散的、一对一交易的衍生工具，例如金融机构之间、金融机构与大规模交易者之间进行的各类互换交易和信用衍生产品交易。故本题选B 选项。"},{"id":"jun-bas2-23","subject":"basics","source":"6月押题 LC","type":"单选","q":"首次公开发行股票并在主板上市，发行人应符合最近 ()内主营业务董事、高级管理人员没有发生重大变化，实际控制人没有发生变更。","options":["5 年","2 年","1 年","3 年"],"answer":"D","explain":"答案解析：D 选项正确，发行人应符合主营业务、控制权和管理团队稳定，首次公开发行股票并在主板上市的，最近三年内主营业务和董事、高级管理人员均没有发生重大不利变化。故本题选 D 选项。【补充】发行人业务完整，具有直接面向市场独立持续经营的能力：(1)资产完整，业务及人员、财务、机构独立，与控股股东、实际控制人及其控制的其他企业间不存在对发行人构成重大不利影响的同业竞争，不存在严重影响独立性或者显失公平的关联交易。(2)主营业务、控制权和管理团队稳定，首次公开发行股票并在主板上市的，最近三年内主营业务和董事、高级管理人员均没有发生重大不利变化；首次公开发行股票并在科创板、创业板上市的，最近二年内主营业务和董事、高级管理人员均没有发生重大不利变化；首次公开发行股票并在科创板上市的，核心技术人员应当稳定且最近二年内没有发生重大不利变化；发行人的股份权属清晰，不存在导致控制权可能变更的重大权属纠纷，首次公开发行股票并在主板上市的，最近三年实际控制人没有发生变更；首次公开发行股票并在科创板、创业板上市的，最近二年实际控制人没有发生变更。(3)不存在涉及主要资产、核心技术、商标等的重大权属纠纷，重大偿债风险，重大担保、诉讼、仲裁等或有事项，经营环境已经或者将要发生重大变化等对持续经营有重大不利影响的事项。"},{"id":"jun-bas2-24","subject":"basics","source":"6月押题 LC","type":"单选","q":"流动性风险通常被分为 () 。","options":["资产流动性风险和现金流动性风险","资产流动性风险和投资流动性风险","融资流动性风险和投资流动性风险","融资流动性风险和资产流动性风险"],"answer":"D","explain":"答案解析：流动性风险，是指金融市场参与者无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求的风险，通常被分为融资流动性风险和资产流动性风险 (D 选项正确)。故本题选 D 选项。"},{"id":"jun-bas2-25","subject":"basics","source":"6月押题 LC","type":"单选","q":"基金投资者想投资一篮子股票，使 80%以上的资金资产投资于股票，则他应该投资的证券基金类型是() 。","options":["债券基金","股票基金","偏股型基金","混合基金"],"answer":"B","explain":"答案解析：B 选项符合题意，股票基金是指以股票为主要投资对象的证券投资基金。在我国，根据中国证监会对基金类别的分类标准，80%以上的基金资产投资于股票的，为股票基金。故本题选 B 选项。【引申】A 选项不符合题意，债券基金是一种以债券为主要投资对象的证券投资基金。在我国，根据中国证监会对基金类别的分类标准，80%以上的基金资产投资于债券的，为债券基金。C、D 选项不符合题意，混合基金是指可以同时投资于股票与债券的基金，该类基金由于资产配置比例不同，分为偏股型基金、偏债型基金、股债平衡型基金、灵活配置型基金等。"},{"id":"jun-bas2-26","subject":"basics","source":"6月押题 LC","type":"单选","q":"基础设施公募 REITS 要求收益分配比例不低于合并后基金年度可供分配金额的 ()。","options":["90%","80%","60%","70%"],"answer":"A","explain":"答案解析：A 选项正确，基础设施公募 REITs 采取封闭式运作，收益分配比例不低于合并后基金年度可供分配金额的 90%。"},{"id":"jun-bas2-27","subject":"basics","source":"6月押题 LC","type":"单选","q":"机构投资者与个人投资者差异明显，下列各项属于机构投资者特点的是()。","options":["投资行为具有随意性","投资规模有限","投资结构组合化","投资灵活性强"],"answer":"C","explain":"答案解析： 与个人投资者相比，机构投资者具有以下特点：(1)投资资金规模化(B 选项错误)。(2)投资管理专业化。(3)投资结构组合化 (C 选项正确)。(4)投资行为规范化 (A 选项错误)。D选项错误，属于个人投资者的特点。故本题选C选项。"},{"id":"jun-bas2-28","subject":"basics","source":"6月押题 LC","type":"单选","q":"沪深 300 股指期货合约的合约乘数为每点价值 300 元人民币，假设期货报价为 4000 点，则每张合约名义金额为 ()元人民币。","options":["120000","12000","4000","1200000"],"answer":"D","explain":"答案解析：合约乘数定为每点价值 300 元人民币，假设期货报价为 4000 点, 则每张合约名义金额为 300×4000=1200000 元人民币 (D 选项正确)。故本题选 D 选项。"},{"id":"jun-bas2-29","subject":"basics","source":"6月押题 LC","type":"单选","q":"关于优先股与普通股的关系，表达最准确的是() 。","options":["普通股包含优先股","优先股股东相对于普通股股东，有些权利是优先的，有些权利又受到限制","优先股包含普通股","普通股和优先股没有关系"],"answer":"B","explain":"答案解析：A、C、D选项错误，按股东享有权利的不同，股票可以分为普通股票和特别股票。优先股是一种最常见的特别股票，因此普通股和优先股并不是包含关系。B 选项正确，优先股既像债券，又像股票。优先股股东享有优先派发股息和分派剩余财产的权利，但是其他一些股东权利是受限的。"},{"id":"jun-bas2-30","subject":"basics","source":"6月押题 LC","type":"单选","q":"关于私募基金信息披露说法错误的是 () 。","options":["基金信息披露是一种自愿性信息披露","信息披露义务人应当保证所披露信息的真实性、准确性和完整性","信息披露义务人委托第三方机构代为披露信息的，不得免除信息披露义务人法定应承担的信息披露义务","信息披露义务人应当向投资者披露的信息包括基金净值、投资组合情况和主要财务指标"],"answer":"A","explain":"答案解析：A 选项错误，在我国，基金的信息披露具有强制性，《证券投资基金法》和《公开募集证券投资基金信息披露管理办法》及一系列配套法规对基金信息披露的原则、内容、禁止行为等各方面作出了明确、严格的规定。"},{"id":"jun-bas2-31","subject":"basics","source":"6月押题 LC","type":"单选","q":"股票的理论价值又称 () 。","options":["票面价值","账面价值","内在价值","股票净值"],"answer":"C","explain":"答案解析：A 选项错误，股票的票面价值又称面值，即在股票票面上标明的金额。B、D 选项错误，股票的账面价值又称股票净值或每股净资产，在没有优先股的条件下，每股账面价值等于公司净资产除以发行在外的普通股票的股数。C 选项正确，股票的内在价值即理论价值，即股票未来收益的现值。故本题选 C 选项。"},{"id":"jun-bas2-32","subject":"basics","source":"6月押题 LC","type":"单选","q":"对客户撤销的委托，证券经纪商应 () 。","options":["只解冻证券","每日收盘后解冻资金和证券","只解冻资金","及时解冻资金和证券"],"answer":"D","explain":"答案解析：在委托未成交之前，客户变更或撤销委托，在采用证券经纪商场内交易员进行申报的情况下，证券经纪商营业部业务员须即刻通知场内交易员，经场内交易员操作确认后，立即将执行结果告知客户。在采用客户或证券经纪商营业部业务员直接申报的情况下，客户或证券经纪商营业部业务员可直接将撤单信息通过电脑终端输入证券交易所交易系统，办理撤单。对客户撤销的委托，证券经纪商须及时将冻结的资金或证券解冻(D 选项正确)。故本题选 D 选项。"},{"id":"jun-bas2-33","subject":"basics","source":"6月押题 LC","type":"单选","q":"地方债是 ()根据本地区经济发展和资金需求状况，以承担还本付息责任为前提，向社会募集资金的债务凭证。","options":["地方政府","地方金融机构","中央政府","地方企业"],"answer":"A","explain":"答案解析：A 选项正确，地方政府债券简称\"地方债券\"，也可以称地方公债或地方债，是地方政府根据本地区经济发展和资金需求状况，以承担还本付息责任为前提，向社会筹集资金的债务凭证。筹集的资金一般用于弥补地方财政资金的不足，或者兴建地方大型项目。"},{"id":"jun-bas2-34","subject":"basics","source":"6月押题 LC","type":"单选","q":"当投资者买入看涨期权后，如果判断正确，则可以获得 ()。","options":["标的资产市价与行权价格之间的差额","利息","期权标的资产","期权费"],"answer":"A","explain":"答案解析：认购期权也称为看涨期权，指期权的买方具有在约定期限内 (或合约到期日)按行权价格 (也称为敲定价格或执行价格)向期权的卖方买入一定数量标的资产的权利。交易者之所以买入认购期权，是因为他预期基础金融工具的价格在合约期限内将会上涨。如果判断正确，按行权价格买入该项金融工具并以市价卖出，可赚取市价与行权价格之间的差额 (A 选项正确)；如果判断失误，则放弃行权，仅损失期权费。"},{"id":"jun-bas2-35","subject":"basics","source":"6月押题 LC","type":"单选","q":"当金融机构提供贷款时，需要第三方担保， 当借款人不能按时还款时，融出方可要求担保人还款，这是风险控制中的()。","options":["风险转移","风险控制","风险补充与流动金","风险规避"],"answer":"A","explain":"答案解析：投资者通过购买某种金融产品或采取某些合法的手段将风险转移给愿意和有能力承接的主体，称为风险转移。风险转移可分为保险转移和非保险转移。其中非保险转移通常采用担保和备用信用证等方式将风险转移给第三方。例如，当金融机构提供信用贷款时，通常需要借款人提供第三方担保，如不能到期偿还贷款，由担保方代为偿还 (A 选项符合题意)。"},{"id":"jun-bas2-36","subject":"basics","source":"6月押题 LC","type":"单选","q":"从交易结构上看，可以将互换交易视为一系列 ()的组合。","options":["期货交易","现货交易","远期交易","期权交易"],"answer":"C","explain":"答案解析：互换是指两个或两个以上的当事人按共同商定的条件，在约定的时间内定期交换现金流的金融交易。从交易结构上看，可以将互换交易视为一系列远期交易(C选项正确)的组合。故本题选 C 选项。"},{"id":"jun-bas2-37","subject":"basics","source":"6月押题 LC","type":"单选","q":"不属于我国普通国债发行情况的是 () 。","options":["发行方式趋于市场化","发行成本越来越高","期限趋于多样化","规模越来越大"],"answer":"B","explain":"答案解析：我国发行普通国债的总体情况大致如下：(1)规模越来越大 (D 选项正确)；(2)期限趋于多样化 (C 选项正确)；(3)发行方式趋于市场化 (A 选项正确)。故本题选 B 选项。"},{"id":"jun-bas2-38","subject":"basics","source":"6月押题 LC","type":"单选","q":"《证券公司融资融券业务内部控制指引》规定，证券公司应当建立以 ()为核心的融资融券业务规模监控和调整机制。","options":["净收入","总资产","净资产","净资本"],"answer":"D","explain":"答案解析：《证券公司融资融券业务内部控制指引》规定，证券公司应当建立以净资本 (D选项正确)为核心的融资融券业务规模监控和调整机制。证券公司应当建立融资融券业务的集中风险监控系统。故本题选 D 选项。"},{"id":"jun-bas2-39","subject":"basics","source":"6月押题 LC","type":"单选","q":"()拥有全球最发达的股票市场。","options":["中国","日本","英国","美国"],"answer":"D","explain":"答案解析： 美国 (D 选项正确)是当今世界第一大经济体，其金融业也居全球霸主地位。拥有全球最发达的股票市场、最大债券市场、最大衍生品市场和全球第二大外汇市场。故本题选 D 选项。"},{"id":"jun-bas2-40","subject":"basics","source":"6月押题 LC","type":"多选","q":"直接融资的特点包括 () 。","options":["融资的主动权主要掌握在金融中介机构手中","融资者有相对较强的自主性","融资信誉的差异性较大","融资的相对集中性"],"answer":"BC","explain":"答案解析：直接融资的特点有：直接性、分散性 (D 选项错误，并非相对集中性)、融资的信誉有较大的差异性 (C 选项正确)、部分融资的不可逆性、融资者有相对较强的自主性 (B 选项正确)。A 选项错误，间接融资主动权主要掌握在金融中介机构手中。故本题选 BC 选项。"},{"id":"jun-bas2-41","subject":"basics","source":"6月押题 LC","type":"多选","q":"证券公司风险管理的组织架构包括 () 。","options":["风险管理部门","子公司","高级管理层","董事会及其风险管理委员会"],"answer":"ABCD","explain":"答案解析：证券公司风险管理的组织架构包括：董事会及其委员会(D 选项正确)、经理层 (C选项正确)、风险管理部门 (A 选项正确)、子公司 (B 选项正确)、风险管理的\"三道防线\"。故本题选 ABCD 选项。"},{"id":"jun-bas2-42","subject":"basics","source":"6月押题 LC","type":"多选","q":"证券登记结算制度包括 () 。","options":["证券实名制","货银对付的交收制度","全额结算制度","净额结算制度"],"answer":"ABD","explain":"答案解析：A、B、D 选项正确，证券登记结算制度包括证券实名制、货银对付的交收制度、分级结算制度和结算参与人制度、净额结算制度、结算证券和资金的专用性制度。故本题选 ABD 选项。"},{"id":"jun-bas2-43","subject":"basics","source":"6月押题 LC","type":"多选","q":"影响我国金融市场运行的因素有 () 。","options":["经济因素，如经济增长、周期波动和财政货币经济政策等","信息技术的发展程度","投资者的心理预期","文化因素"],"answer":"ABCD","explain":"答案解析：影响中国金融市场运行的因素来自诸多方面，可以将之大体归纳为政策因素、经济因素 (A 选项正确)、法律因素、市场因素、技术因素 (B 选项正确)、心理因素(C 选项正确)以及其他因素 (D 选项正确，文化因素属于其他因素)七个方面。故本题选 ABCD 选项。【知识】其他因素：影响金融市场的因素还包括文化因素、人口因素等。文化对各国或者区域金融体系及其发展有着重要的影响。"},{"id":"jun-bas2-44","subject":"basics","source":"6月押题 LC","type":"多选","q":"以下关于基金销售服务费的说法正确的是 ()。","options":["基金托管是投资者委托基金管理公司保管基金资产，基金销售服务费是托管费的一部分","基金销售服务费不能用于为基金份额持有人提供服务","基金销售服务费能用于为基金份额持有人提供服务","基金销售服务费可用于基金持续销售"],"answer":"CD","explain":"答案解析：A 选项错误，基金托管费和基金销售服务费是两种并列的基金费用，不存在包含关系。B 选项错误，C、D 选项正确，基金销售服务费是用于基金的持续销售和为基金份额持有人提供服务而收取的费用。"},{"id":"jun-bas2-45","subject":"basics","source":"6月押题 LC","type":"多选","q":"以下 ()是非过户交易。","options":["捐赠","转托管","继承","司法强制执行"],"answer":"ACD","explain":"答案解析：开放式基金非交易过户，是指不采用申购、赎回等交易方式，将一定数量的基金份额按照一定规则从某一投资者基金账户转移到另一投资者基金账户的行为，主要包括继承 (C 选项正确)、捐赠 (A 选项正确)、司法强制执行 (D 选项正确)和经注册登记机构认可的其他情况下的非交易过户。故本题选 ACD 选项。"},{"id":"jun-bas2-46","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列属于证券交易所特征的有 ()。","options":["交易的对象限于合乎一定标准的上市证券","通过公开竞价的方式决定交易价格","集中证券的供求双方具有较高的成交速度和成交率","为证券公司融资融券业务提供资金和证券的转融通服务"],"answer":"ABC","explain":"答案解析：证券交易所的特征包括：(1)有固定的交易场所和交易时间；(2)参加交易者为具备会员资格的证券经营机构，交易采取经纪制度，即一般投资者不能直接进入交易所买卖证券，只能委托会员作为经纪人间接进行交易；(3)交易的对象限于合乎一定标准的上市证券 (A 选项正确)；(4)通过公开竞价的方式决定交易价格(B 选项正确) ;(5)集中证券的供求双方，具有较高的成交速度和成交率 (C 选项正确)；实行\"公开、公平、公正\"原则，并对证券交易进行严格管理。D 选项错误，属于证券金融公司的特征。故本题选 ABC 项。"},{"id":"jun-bas2-47","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列属于我国国际债券品种的有 () 。","options":["政府债券","金融债券","公司债券","次级债券"],"answer":"ABC","explain":"答案解析：我国国际债券品种有：(1)政府债券 (A 选项正确)；(2)金融债券和公司债券 (B、C 选项正确)。故本题选 ABC 选项。"},{"id":"jun-bas2-48","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列可以跨市场转托管的债券有 () 。","options":["企业债","国债","证券公司次级债","公司债"],"answer":"AB","explain":"答案解析：跨市场交易的债券：目前，除了国债 (包括附息国债和地方债)和企业债可以跨市场转托管 (A、B 选项正确)，其他债券品种(包括公司债、证券公司次级债、中小企业私募债)都不能跨市场转托管 (C、D 选项错误)。故本题选 AB 选项。【知识】债券市场转托管的条件：(1)跨市场交易的债券。(2)转托管时间。由于托管机构之间存在着不同的运作模式，转托管的完成至少需要一天时间。(3)转托管的收费。从银行间转到交易所，参考中国证券登记结算有限责任公司官网，转托管费按转出国债面值金额的 0.005%计算，单笔 (单只)转托管费用最低为10元，最高为 10000 元。从交易所转到银行间，参考上海证券交易所债券交易收费标准为国债面值的 0.01%。(4)转托管的速度。目前最快的国债转托管，能实现T+1 日到账，其他大部分债券只能实现 T+2 日甚至 T+3 日到账。"},{"id":"jun-bas2-49","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于证券公司另类子公司说法，正确的是() 。","options":["另类子公司可以融资","另类子公司不得对外担保","另类子公司不得成为对所投资企业的债务承担连带责任的出资人","另类子公司不得从事投资以外的业务"],"answer":"BCD","explain":"答案解析：另类子公司不得融资 (A 选项错误)，不得对外提供担保和贷款 (B 选项正确)，不得成为对所投资企业的债务承担连带责任的出资人 (C 选项正确)。另类子公司不得向投资者募集资金开展基金业务，且不得下设任何机构。根据《证券公司另类投资子公司管理规范》.证券公司另类子公司从事《证券公司证券自营投资品种清单》所列品种以外的金融产品、股权等另类投资业务，不得从事投资业务之外的业务 (D 选项正确)。故本题选 BCD 选项。"},{"id":"jun-bas2-50","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于债券报价与结算的说法，正确的有 () 。","options":["净价是指不含应计利息的债券价格","债券买卖报价分为净价和全价两种","所报价格为每 100 元面值债券的价格","债券买卖结算分为净价结算和全价结算"],"answer":"ABC","explain":"答案解析：债券买卖报价分为净价和全价两种，结算为全价结算(B 选项正确、D 选项错误)。所报价格为每 100 元面值债券的价格 (C 选项正确)。净价是指不含应计利息的债券价格，单位为\"元/百元面值\"(A 选项正确)。故本题选 ABC 选项。"},{"id":"jun-bas2-51","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于我国企业债券各品种的说法，正确的有() 。","options":["可续期企业债券理论上可不断续期永续存在，具有期限超长、主动赎回、可充当资本金等诸多优势","项目收益债券的本息偿还资金完全或主要来源于项目建成后的运营收益","专项债券可以是普通企业债券，也可以是创新的项目收益债券、永续债券、债贷组合债券等","发行项目收益债券募集的资金，可以用于项目建设、运营或设备购置，可以置换项目资本金或偿还与项目有关的其他债务"],"answer":"ABC","explain":"答案解析：A 选项正确，可续期企业债券理论上可不断续期永续存在，具有期限超长、主动赎回、可充当资本金等诸多优势。B 选项正确，项目收益债券的本息偿还资金完全或主要来源于项目建成后的运营收益。C 选项正确，专项债券是指债券募集资金用于特定项目的债券。专项债券不是某一个债券品种，它可以是普通企业债券，也可以是创新的项目收益债券、永续债券、债贷组合债券等。D 选项错误，发行项目收益债券募集的资金，只能用于该项目建设、运营或设备购置，不得置换项目资本金或偿还与项目有关的其他债务。故本题选 ABC 选项。"},{"id":"jun-bas2-52","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于委托撤销的说法，正确的有 () 。","options":["证券营业部申报竞价成交后，买卖即告成立，成交部分不得撤销","委托未成交之前，客户有权变更委托","委托未成交之前，客户不得撤销委托","对客户撤销的委托，证券经纪商须及时将冻结的资金或证券解冻"],"answer":"ABD","explain":"答案解析：委托指令的撤销即撤单，撤单的条件和程序如下：(1)撤单的条件。在委托未成交之前，客户有权变更和撤销委托 (B 选项正确、C 选项错误)。证券营业部申报竞价成交后，买卖即告成立，成交部分不得撤销 (A 选项正确)。(2)撤单的程序。在委托未成交之前，客户变更或撤销委托，在采用证券经纪商场内交易员进行申报的情况下，证券经纪商营业部业务员须即刻通知场内交易员，经场内交易员操作确认后，立即将执行结果告知客户。在采用客户或证券经纪商营业部业务员直接申报的情况下，客户或证券经纪商营业部业务员可直接将撤单信息通过电脑终端输入证券交易所交易系统，办理撤单。对客户撤销的委托，证券经纪商须及时将冻结的资金或证券解冻 (D 选项正确)。故本题选 ABD 选项。"},{"id":"jun-bas2-53","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于美国金融市场的说法，正确的有 () 。","options":["根据国债的特点，美国国债有通货膨胀保值债券、浮动利率国库票据等分类","目前的纽约证券交易所交易制度模式主要包括三个特征，即专家制度、场内经纪商制度和补充流动性供商制度","1997年纳斯达克市场将电子通信引入自身的报价和交易系统中，并启用美国证券交易委员会的《交易指令处理规则》","有效联邦基金利率由联储理事会公开市场委员会负责计算和发布"],"answer":"AC","explain":"答案解析：A 选项正确，根据国债的特点，美国国债有通货膨胀保值债券、浮动利率国库票据等分类。B 选项错误，纽约证券交易所交易制度模式主要包括三个特征，即指定做市商制度、场内经纪商制度和补充流动性提供商制度。C 选项正确，1997年纳斯达克市场将电子通信引入自身的报价和交易系统中，并启用美国证券交易委员会《交易指令处理规则》。D 选项错误，为保证联邦基金利率正确反映银行间市场的供求状况，美联储根据国际证监会组织 (IOSCO)关于金融基准指标计算和发布的指导原则，具体由最贴近市场的纽约联邦储备银行 (并非联储理事会)负责根据联邦基金市场每日的交易情况，每日计算和发布成交额加权的有效联邦基金利率，并根据联邦公开市场委员会(FOMC)的议息会议决定，保证该利率在规定的范围内波动。故本题选 AC 选项。"},{"id":"jun-bas2-54","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于基金投资对象的说法，正确的有 () 。","options":["股票基金应有 80%以上的基金资产投资于股票","债券基金应有 90%以上的基金资产投资于债券","货币市场基金投资对象为期限较短的货币市场工具","混合基金是可同时投资于股票与债券的基金"],"answer":"ACD","explain":"答案解析：A 选项正确，80%以上的基金资产投资于股票的，为股票基金。B 选项错误，80%以上的基金资产投资于债券的，为债券基金。C 选项正确，货币市场基金是仅以货币市场工具为投资对象的一种基金，其投资对象期限较短，一般在 1 年以内.包括银行短期存款、政府短期债券、同业存单、公司短期债券等货币市场工具。D 选项正确，混合基金是指可以同时投资于股票与债券的基金，该类基金由于资产配置比例不同，分为偏股型基金、偏债型基金、股债平衡型基金、灵活配置型基金等。故本题选 ACD 选项。"},{"id":"jun-bas2-55","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于股票市场价格的说法，正确的有 () 。","options":["如果买方的意愿购买量超过此时卖方的意愿出售量，股票会上涨","如果买方的意愿购买量超过此时卖方的意愿出售量，股票会下跌","如果卖方的意愿出售量超过此时买方的意愿购买量，股票会上涨","如果卖方的意愿出售量超过此时买方的意愿购买量，股票会下跌"],"answer":"AD","explain":"答案解析：股票的市场价格由股票的价值决定，但同时受许多其他因素的影响。其中，供求关系是最直接的影响因素，其他因素都是通过作用于供求关系而影响股票价格的。在任何价位上，如果买方的意愿购买量超过此时卖方的意愿出售量，股价将会上涨 (A 选项正确)；反之，如果卖方的意愿出售量超过此时买方的意愿购买量，股价将会下跌 (D 选项正确)。故本题选 AD 选项。"},{"id":"jun-bas2-56","subject":"basics","source":"6月押题 LC","type":"多选","q":"下列关于法人股的说法，正确的有 () 。","options":["法人持股是法人经营自身财产的一种投资行为","法人股股票不记名","国有法人股属于国有股权","法人持股所形成的是一种所有权关系"],"answer":"ACD","explain":"答案解析：法人股是指企业法人或具有法人资格的事业单位和社会团体以其依法可支配的资产投入公司形成的股份。法人持股所形成的也是所有权关系，是法人经营自身财产的一种投资行为 (A、D 选项正确)。法人股股票以法人记名 (B 选项错误)。如果是具有法人资格的国有企业、事业单位及其他单位以其依法占用的法人资产向独立于自己的股份公司出资形成或依法定程序取得的股份. 则被称为\"国有法人股\"。国有法人股属于国有股权 (C 选项正确)。故本题选 ACD 选项。"},{"id":"jun-bas2-57","subject":"basics","source":"6月押题 LC","type":"多选","q":"委托指令根据委托订单的数量可分为 ()。","options":["整数委托","零数委托","比例委托","全额委托"],"answer":"AB","explain":"答案解析：根据委托订单的数量，委托指令可分为整数委托 (A 选项正确)和零数委托 (B选项正确)。故本题选 AB 选项。"},{"id":"jun-bas2-58","subject":"basics","source":"6月押题 LC","type":"多选","q":"商业银行发行金融债券应具备 ()条件。","options":["具有良好的公司治理机制","核心资本充足率不低于 8%","最近 3 年连续盈利","最近 3 年没有重大违法、违规行为"],"answer":"ACD","explain":"答案解析：商业银行发行金融债券应具备以下条件：(1)具有良好的公司治理机制 (A 选项正确)；(2)核心资本充足率不低于 4%(B 选项错误)；(3)最近三年连续盈利 (C选项正确)；(4)贷款损失准备计提充足；(5)风险监管指标符合监管机构的有关规定；(6)最近三年没有重大违法、违规行为 (D 选项正确) ;(7)中国人民银行要求的其他条件。故本题选 ACD 选项。"},{"id":"jun-bas2-59","subject":"basics","source":"6月押题 LC","type":"多选","q":"日经平均股价指数按其计算对象的采样数目不同，分为 ()。","options":["日经 500 种平均股价指数","日经 225 种平均股价指数","日经 300 种平均股价指数","日经 1000 种平均股价指数"],"answer":"AB","explain":"答案解析：日经平均股价指数按其计算对象的采样数目不同，分为日经 225 种平均股价指数(B 选项正确)、日经 500 种平均股价指数 (A 选项正确)。故本题选 AB 选项。"},{"id":"jun-bas2-60","subject":"basics","source":"6月押题 LC","type":"多选","q":"企业在短期融资券注册有效期内 ()的，应重新注册。","options":["更换审计机构","变更资产评估机构","变更注册金额","更换主承销商"],"answer":"CD","explain":"答案解析： 企业在注册有效期内需更换主承销商 (D 选项正确)或变更注册金额(C 选项正确)的，应重新注册。交易商协会不接受注册的，企业可于 6 个月后重新提交注册文件。故本题选 CD 选项。"},{"id":"jun-bas2-61","subject":"basics","source":"6月押题 LC","type":"多选","q":"流动性风险，是指金融市场参与者无法以合理成本及时获得充足资金，以()的资金需求的风险。","options":["进行套期保值","履行其他支付义务","满足正常业务开展","偿付到期债务"],"answer":"BCD","explain":"答案解析：流动性风险，是指金融市场参与者无法以合理成本及时获得充足资金，以偿付到期债务 (D 选项正确)、履行其他支付义务 (B 选项正确)和满足正常业务开展 (C选项正确)的资金需求的风险。故本题选 BCD 选项。"},{"id":"jun-bas2-62","subject":"basics","source":"6月押题 LC","type":"多选","q":"可以以自己的名义开立债券托管账户的机构有() 。","options":["商业银行所辖支行","证券公司","企业集团财务公司","基金管理公司及其管理的各类基金"],"answer":"BCD","explain":"答案解析：中华人民共和国境内的商业银行及授权分行 (A 选项错误)、信托投资公司、企业集团财务公司 (C 选项正确)、金融租赁公司、农村信用社、城市信用社、证券公司 (B 选项正确)、基金管理公司及其管理的各类基金 (D 选项正确)、保险公司、外资金融机构以及经金融监管当局批准可投资于债券资产的其他金融机构均可在中央国债登记结算有限责任公司 (即中央结算公司)、银行间市场清算所股份有限公司 (上海清算所)和中国证券登记结算有限责任公司 (即中国结算公司)按实名制原则以自己名义开立债券托管账户。故本题选 BCD 选项。"},{"id":"jun-bas2-63","subject":"basics","source":"6月押题 LC","type":"多选","q":"科创板上市公司可能强制退市的情形主要包括() 。","options":["公司存在欺诈发行、重大信息披露","公司重整、强制解散","涉及国家安全、公共安全重大违法","主营业务大部分停滞"],"answer":"ABCD","explain":"答案解析：针对科创板上市公司，上海证券交易所制定了专门的《上海证券交易所科创板股票上市规则》。根据该规则，科创板上市公司被强制退市的情形主要有：(1)重大违法强制退市，包括公司存在欺诈发行、重大信息披露违法和涉及国家安全、公共安全重大违法行为 (A、C 选项正确) 。(2)交易类强制退市.包括累计股票成交量低于一定指标，股票收盘价、市值、股东数量持续低于一定指标等。(3)财务类强制退市，即明显丧失持续经营能力，包括：主营业务大部分停滞 (D 选项正确)或者规模极低，经营资产大幅减少导致无法维持日常经营，营业收入或者利润主要来源于不具备商业实质的交易，营业收入或者利润主要来源于与主营业务无关的业务，其他明显丧失持续经营能力的情形。(4)规范类强制退市，包括公司财务重大报告差错与虚假记录、信息披露、定期报告发布、公司股本总额或股权分布发生变化、依法被强制解散、公司重整、破产和清算等方面触及相关合规性指标等 (B 选项正确)。故本题选 ABCD 选项。"},{"id":"jun-bas2-64","subject":"basics","source":"6月押题 LC","type":"多选","q":"金融期货交易与普通远期交易之间的区别在于() 。","options":["交易场所和交易组织形式不同","交易的监管程度不同","金融期货交易是标准化交易，远期交易的内容可协商确定","违约风险不同"],"answer":"ABCD","explain":"答案解析：作为一种标准化的远期交易，金融期货交易与普通远期交易之间也存在以下区别：(1)交易场所和交易组织形式不同 (A 选项正确)。(2)交易的监管程度不同 (B选项正确)。金融期货交易是标准化交易，远期交易的内容可协商确定 (C 选项正确)。(3)保证金制度和每日结算制度导致违约风险不同 (D 选项正确)。故本题选 ABCD 选项。"},{"id":"jun-bas2-65","subject":"basics","source":"6月押题 LC","type":"多选","q":"国际证监会组织公布的证券市场监管目标有 ()。","options":["保持证券市场的公平、效率和透明","降低系统性风险","保护投资者利益","促进证券市场价格"],"answer":"ABC","explain":"答案解析：国际证监会组织于 1998 年制定的《证券监管目标和原则》公布了证券监管的三个目标：一是保护投资者利益 (C 选项正确)；二是保证证券市场的公平、效率和透明 (A 选项正确)；三是降低系统性风险 (B 选项正确)。故本题选 ABC选项。"},{"id":"jun-bas2-66","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于影响国债销售价格的因素，下列说法中正确的有 ()。","options":["市场利率对国债销售价格起着显著的导向作用，市场利率趋于上升，就为承销商确定销售价格拓展了空间","若承销商通过投标获得较低成本的国债，有利于分销工作的顺利开展","如果国债的收益率过高，投资者就会倾向于在二级市场上购买已流通国债","在国债承销中，承销商可以获得金额一定比例的手续费收入"],"answer":"BD","explain":"答案解析：影响国债销售价格的因素：(1)市场利率。市场利率的高低及其变化对国债销售价格起着显著的导向作用，市场利率趋于上升，就限制了承销商确定销售价格的空间；市场利率趋于下降，就为承销商确定销售价格拓宽了空间 (A 选项错误)。(2)中标成本。国债销售的价格一般不应低于承销商与发行人的结算价格，反之，就有可能发生亏损。所以，通过投标获得较低成本的国债，有利于分销工作的顺利开展 (B 选项正确)。(3)流通市场中可比国债的收益率水平。如果国债承销价格定价过高，即收益率过低，投资者就会倾向于在二级市场上购买已流通的国债，而不是直接购买新发行的国债 (C 选项错误)。(4)手续费收入。在国债承销中，承销商可获得一定金额的手续费收入，因此，有些承销商为了争取客户，扩大市场份额，会采取降低销售价格的方式 (D 选项正确)。(5)其他因素。国债承销的价格还受其他一些因素的影响，如承销商的市场声誉、国债的期限、国债的票面利率等。"},{"id":"jun-bas2-67","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于我国证券公司，下列说法正确的有 () 。","options":["证券公司是证券市场投融资服务的提供者，是专业化的中介服务机构","证券公司是指依照《公司法》和《证券法》设立的经营证券业务的有限责任公司或股份有限公司","在我国，设立证券公司必须经国务院审查批准","证券公司是证券市场重要的机构投资者"],"answer":"ABD","explain":"答案解析：证券公司，是指依照《公司法》和《证券法》设立的经营证券业务的有限责任公司或股份有限公司 (B 选项正确) 。在我国，设立证券公司必须经国务院证券监督管理机构审查批准 (C 选项错误)。证券公司是证券市场的主要中介机构，在证券市场运行中发挥着重要作用。一方面，证券公司是证券市场投融资服务的提供者，为证券发行人和投资者提供专业化的中介服务 (A 选项正确)；另一方面，证券公司本身也是证券市场重要的机构投资者 (D 选项正确)。故本题选 ABD 选项。"},{"id":"jun-bas2-68","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于基金运作信息披露，下列说法正确的有 () 。","options":["开放式基金在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值","货币基金不必披露每个开放日的份额净值，但需要披露每万份基金收益和最近 7 日年化收益率","基金投资组合报告需要披露基金资产组合，按行业分类的股票投资组合，前10 名股票明细等","基金年度报告是基金各类信息披露文件中信息量最大的文件"],"answer":"ABCD","explain":"答案解析：A 选项正确，对开放式基金而言，在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值。B 选项正确，对普通货币基金而言，每日分配收益，份额净值保持 1 元不变，因此货币基金不像一般开放式基金那样披露每个开放日的份额净值，而是需要披露收益公告，包括每万份基金收益和最近 7 日年化收益率。C 选项正确，投资组合报告需要披露基金资产组合，按行业分类的股票投资组合，前 10 名股票明细，按券种分类的债券投资组合，前 5 名债券明细，投资贵金属、股指期货、国债期货等情况。D 选项正确，基金年度报告是基金的各类信息披露文件中信息量最大的文件，在会计年度结束后 3 个月内经过审计后予以公告。故本题选 ABCD 选项。"},{"id":"jun-bas2-69","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于基金投资理念，下列说法正确的有 () 。","options":["在招募说明书上阐明基金投资理念，是一种吸引投资者购买的自荐方式","在招募说明书上阐明基金投资理念，体现了国内基金投资和管理的日益规范和进步","投资理念并不隐含着对投资风险偏好的抉择","投资理念往往隐含着对投资风险偏好的抉择"],"answer":"ABD","explain":"答案解析：投资理念，从其本质上说就是指投资者对投资目的的认识和对投资方法的认知。投资理念包含两个层面：一是为什么要投资，即投资的目的是什么；二是怎样投资，即投资的方法是什么。投资理念的确定隐含着一系列投资抉择，包括对投资风险偏好的抉择、对投资期限的抉择、对投资策略的抉择等 (D 选项正确、C 选项错误)。在招募说明书上阐明投资理念，是一种吸引投资者购买的自荐方式，也体现了国内基金投资和管理的日益规范和进步 (A、B 选项正确)。故本题选ABD选项。"},{"id":"jun-bas2-70","subject":"basics","source":"6月押题 LC","type":"多选","q":"关于风险管理对价值创造的影响，下列说法正确的有 ()。","options":["风险定价、经济资本配置等风险管理行为对于提升企业现金流具有重要意义","现代风险管理理论认为，风险既是损失的可能，也是盈利的机会","通过衍生产品和对冲风险的交易可以降低企业现金流的波动","声誉风险管理、业务持续性管理、防止企业破产的各种风险管理措施都缩短了现金流期限"],"answer":"ABC","explain":"答案解析：A 选项正确，风险定价、经济资本配置等风险管理行为对于提升企业现金流具有重要的意义。B 选项正确，现代风险理念认为，风险是发展的机遇和资源，风险既是损失的可能，也是盈利的机会。C 选项正确，通过衍生产品和对冲风险的交易可以降低企业现金流的波动。D 选项错误，声誉风险管理、业务持续性管理以及防止企业破产的各种风险管理措施，延长了现金流期限 (并非缩短)，从而创造了价值。故本题选 ABC 选项。"},{"id":"jun-bas2-71","subject":"basics","source":"6月押题 LC","type":"多选","q":"根据衍生工具的产品形态分类，金融衍生工具可以划分为 ()。","options":["独立衍生工具","嵌入式衍生工具","交易所交易的衍生工具","OTC 交易的衍生工具"],"answer":"AB","explain":"答案解析：A、B 选项正确，金融衍生工具根据产品形态，金融衍生工具可分为独立衍生工具和嵌入式衍生工具。C、D 选项错误，金融衍生工具按交易场所可以分为交易所交易的衍生工具和场外交易市场 (OTC)交易的衍生工具。故本题选 AB 选项。"},{"id":"jun-bas2-72","subject":"basics","source":"6月押题 LC","type":"多选","q":"根据《证券法》， ()可以作为征集人代为出席该上市公司股东大会，并代为行使提案权、表决权等股东权利。","options":["上市公司监事会","上市公司执行董事","持有上市公司 1%以上有表决权股份的股东","投资者保护机构"],"answer":"CD","explain":"答案解析：新《证券法》设置了\"投资者保护\"专章，建立上市公司股东权利代为行使征集制度，明确上市公司董事会、独立董事、持有 1%以上有表决权股份的股东 (C 选项正确)或者投资者保护机构 (D 选项正确)可以作为征集人代为出席股东大会，并代为行使提案权、表决权等股东权利。故本题选 CD 选项。"},{"id":"jun-bas2-73","subject":"basics","source":"6月押题 LC","type":"多选","q":"个人投资者的特点包括 () 。","options":["投资行为具有随意性","投资资金规模化","投资的灵活性强","专业知识相对匮乏"],"answer":"ACD","explain":"答案解析：个人投资者的特点包括以下四个方面：(1)资金规模有限；(2)专业知识相对匮乏(D 选项正确)；(3)投资行为具有随意性、分散性和短期性 (A 选项正确) ;(4)投资的灵活性强 (C 选项正确)。B 选项错误，是机构投资者的特点。故本题选ACD 选项。"},{"id":"jun-bas2-74","subject":"basics","source":"6月押题 LC","type":"多选","q":"对投资者而言，美国存托凭证 ADR 的优点包括() 。","options":["以美元交易，且通过投资者熟悉的当地清算公司进行清算","上市交易的 ADR 须经美国证券交易委员会注册，有助于保障投资者权益","上市公司发放股利时，ADR 投资者能及时获得，且以当地货币支付","某些机构投资者受投资政策限制，不能投资非美国上市证券，ADR 可以规避相关限制"],"answer":"BD","explain":"答案解析：投资 ADR 给投资者带来的好处：(1)以美元交易，且通过投资者熟悉的美国清算公司进行清算 (A选项错误)。(2)上市交易的ADR须经美国证券交易委员会(SEC)注册，有助于保障投资者权益 (B 选项正确) 。(3)上市公司发放股利时，ADR投资者能及时获得，而且是以美元支付 (C 选项错误)。(4)某些机构投资者受投资政策限制，不能投资非美国上市证券，ADR 可以规避这些限制 (D 选项正确)。故本题选 BD 选项。"},{"id":"jun-bas2-75","subject":"basics","source":"6月押题 LC","type":"多选","q":"场外交易市场的特征有 () 。","options":["通常不对企业规模和盈利情况等进行要求","挂牌标准较高","交易制度通常采用做市商制度","信息披露要求比较低"],"answer":"ACD","explain":"答案解析：场外交易市场的特征：(1)挂牌标准相对较低，通常不对企业规模和盈利情况等进行要求 (A 选项正确、B 选项错误)。(2)信息披露要求较低，监管较为宽松 (D选项正确) 。(3)交易制度通常采用做市商制度 (C 选项正确)。故本题选ACD 选项。"},{"id":"jun-bas2-76","subject":"basics","source":"6月押题 LC","type":"多选","q":"参与证券投资的金融机构包括 ()。","options":["证券经营机构","保险经营机构","企业集团财务公司","银行业金融机构"],"answer":"ABCD","explain":"答案解析：金融机构类投资者，是指进行证券投资、从事金融资产交易的金融机构，包括证券经营机构 (A 选项正确)、银行业金融机构 (D 选项正确)、保险经营机构 (B选项正确)、基金公司以及其他金融机构。其他金融机构包括信托投资公司、企业集团财务公司和金融租赁公司等 (C 选项正确)。故本题选 ABCD 选项。"},{"id":"jun-bas2-77","subject":"basics","source":"6月押题 LC","type":"多选","q":"按照简易程序注册的基金产品有 () 。","options":["债券基金","混合基金","指数基金","货币基金"],"answer":"ABCD","explain":"答案解析：目前，基金注册程序分为简易程序和普通程序。原审核时间要求：对常规基金产品，如常规股票基金、混合基金 (B 选项正确)、债券基金 (A 选项正确)、指数基金 (C 选项正确)、货币基金 (D 选项正确)，QDII 基金、ETF 及其联接基金等，按简易程序注册，注册审查时间原则上不超过 20 个工作日；对其他产品，按照普通程序注册，注册审查时间不超过 6 个月。故本题选 ABCD 选项。"},{"id":"jun-bas2-78","subject":"basics","source":"6月押题 LC","type":"多选","q":"按股东享有权利的不同，股票可以分为 () 。","options":["记名股票","特别股票","无记名股票","普通股票"],"answer":"BD","explain":"答案解析：按股东享有权利的不同，股票可以分为普通股票 (D 选项正确)和特别股票 (B选项正确)。故本题选 BD 选项。"},{"id":"jun-bas2-79","subject":"basics","source":"6月押题 LC","type":"多选","q":"()属于我国金融衍生品市场的类别。","options":["商品类衍生品","利率类衍生品","货币类衍生品","信用类衍生品"],"answer":"BCD","explain":"答案解析：中国金融衍生品市场按资产类别划分主要包括利率类衍生品 (B 选项正确)、权益类衍生品、货币类衍生品 (C 选项正确)、信用类衍生品 (D 选项正确)。故本题选 BCD 选项。"},{"id":"jun-bas2-80","subject":"basics","source":"6月押题 LC","type":"判断","q":"做市商制度也被称为报价驱动制度，是指做市商向市场提供双向报价，投资者根据报价选择是否与做市商交易。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。做市商制度也称为报价驱动制度，是指做市商向市场提供双向报价，投资者根据报价选择是否与做市商交易。"},{"id":"jun-bas2-81","subject":"basics","source":"6月押题 LC","type":"判断","q":"租赁融资属于直接融资方式的一种。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。间接融资：指资金盈余者通过存款等形式，或者购买银行、信托和保险等金融机构发行的有价证券，将其暂时闲置资金先行提供给金融机构，再由这些金融机构以贷款、贴现或购买有价证券的方式把资金提供给短缺者，从而实现资金融通的过程。常见的间接融资方式包括银行信用融资、消费信用融资、租赁融资 (并非直接融资方式)等。【知识】直接融资：资金盈余单位通过直接与资金需求单位签订协议，或者在金融市场上购买资金需求者所发行的股票、债券等有价证券，将货币资金提供给需求单位使用。常见的直接融资方式有股票市场融资、债券市场融资、风险投资融资、商业信用融资、民间借贷等。"},{"id":"jun-bas2-82","subject":"basics","source":"6月押题 LC","type":"判断","q":"中国存托凭证是指由存托人签发、以境外证券为基础在中国境内发行、代表境外基础证券权益的证券。其参与主体主要包括发行人、存托人、托管人。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。中国存托凭证是指由存托人签发、以境外证券为基础在中国境内发行、代表境外基础证券权益的证券。其参与主体主要包括发行人、存托人、托管人、持有人。"},{"id":"jun-bas2-83","subject":"basics","source":"6月押题 LC","type":"判断","q":"证券投资咨询机构可以代理客户从事证券买卖。()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。证券投资咨询，是指从事证券投资咨询业务的机构及其投资咨询人员为证券投资人或者客户提供证券投资分析、预测或者建议等直接或者间接有偿咨询服务的活动。证券投资咨询机构不可以代理客户从事证券买卖。"},{"id":"jun-bas2-84","subject":"basics","source":"6月押题 LC","type":"判断","q":"证券交易的连续交易，并非意味着交易一定是连续的，而是指在营业时间内交易指令可以连续接收。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。在连续交易中，并非意味着交易一定是连续的，而是指在营业时间里订单匹配可以连续不断地进行。"},{"id":"jun-bas2-85","subject":"basics","source":"6月押题 LC","type":"判断","q":"证券公司债券业务面临的信用风险主要体现在信用债投资业务上，主要包括两类：一类是债券主体违约风险；另一类是逆回购、远期、借贷融出等交易对手方信用风险。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。证券公司债券业务面临的信用风险主要体现在信用债投资业务上，主要包括两类：一类是债券主体违约风险；另一类是逆回购、远期、借贷融出等交易对手方信用风险。"},{"id":"jun-bas2-86","subject":"basics","source":"6月押题 LC","type":"判断","q":"债券的折现率与债券价值呈反向关系。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。影响债券价值的基本因素和主要表现如下：(1)面值越大，债券价值越大 (同向)。(2)票面利率越大，债券价值越大 (同向)。(3)折现率越大，债券价值越小 (反向)。(4)到期时间。对于平息债券 (付息期无限小)，当折现率一直保持至到期日不变时，随着到期时间的缩短，债券价值逐渐接近其票面价值。(5)付息频率。折价发行的债券，加快付息频率，债券价值会下降；溢价发行的债券，加快付息频率，债券价值会上升；平价发行的债券，加快付息频率，债券价值会不变。"},{"id":"jun-bas2-87","subject":"basics","source":"6月押题 LC","type":"判断","q":"信用评级的程序中评级结果复评申请不计次数，复评结果为最终评级结果。()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。证券评级机构受理复评申请后，项目组根据评级对象提供的补充资料修改评级报告，并将修改后的评级报告、建议信用等级、补充资料等提交信用评审委员会，由信用评审委员会确定复评结果。复评申请仅限一次 (并非不计次数)，复评结果为最终评级结果。"},{"id":"jun-bas2-88","subject":"basics","source":"6月押题 LC","type":"判断","q":"销售服务费属于基金销售过程中发生的由基金投资者承担的费用。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。在基金运作过程中涉及的费用可以分为两大类：一类是基金销售过程中发生的由基金投资者承担的费用，主要包括申购费、赎回费及基金转换费等；另一类是基金管理过程中发生的费用，主要包括基金管理费、基金托管费、销售服务费、证券交易费、持有人大会费用、会计师费和律师费、信息披露费等，这些费用由基金资产承担。"},{"id":"jun-bas2-89","subject":"basics","source":"6月押题 LC","type":"判断","q":"我国证券交易所达成的多数证券交易均采取多边金额结算方式。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。目前，我国证券交易所达成的多数证券交易均采取多边净额结算方式 (并非多边金额结算方式)。"},{"id":"jun-bas2-90","subject":"basics","source":"6月押题 LC","type":"判断","q":"投资决策委员会负责决定私募基金的投资计划、投资策略、投资原则、投资目标、资产分配及投资组合的总体计划。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。目前，我国大部分基金公司的基金投资管理都实行投资决策委员会领导下的基金经理负责制。投资决策委员会负责决定公司所管理基金的投资计划、投资策略、投资原则、投资目标、资产配置以及投资权限等，具体的投资细节则由各基金经理自行掌握。"},{"id":"jun-bas2-91","subject":"basics","source":"6月押题 LC","type":"判断","q":"通常期限在 1 年以下 (含 1 年)的国债为贴现式国债；期限在 1 年以上的国债为附息式国债。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。按付息方式分类，国债可分为贴现国债和附息国债。(1)附息国债指国债券面上附有息票，是按照债券票面载明的利率及支付方式支付利息的债券。贴现国债指国债券面上不附有息票，发行时按规定的折扣率，以低于债券面值的价格发行，到期按面值支付本息的国债。(2)通常期限在 1 年以下 (含 1 年)的国债为贴现式国债；期限在 1 年以上的国债为附息式国债 (本题说法正确) 。"},{"id":"jun-bas2-92","subject":"basics","source":"6月押题 LC","type":"判断","q":"套期保值中在期货市场卖出或买进一定数量相同或相近的品种是为了规避价格风险。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。常见的风险对冲手段是套期保值，是以规避现货风险为目的的期货交易行为，其含义是与现货市场相关的经营者或交易者在现货市场上买进或卖出一定数量的现货品种的同时，在期货市场卖出或买进一定数量相同或相近的品种，以期在未来某一时间，通过同时将现货和期货市场上的头寸平仓后， 以一个市场的盈利弥补另一个市场的亏损，达到规避价格风险的目的。"},{"id":"jun-bas2-93","subject":"basics","source":"6月押题 LC","type":"判断","q":"私募证券股权基金和私募债券股权基金的区别不包括投资方向的不同。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。私募证券投资基金区别于私募股权投资基金，主要体现在四个方面：(1)投资方向不同。私募证券投资基金主要投资于二级市场的股票、债券、期货等上市交易品种；而私募股权基金主要投资于非上市公司股权或上市公司非公开交易股权。(2)投资周期不同。私募证券投资基金流动性强、单个投资周期短；而私募股权基金投资周期通常在 2~3 年，加上前期调研，整个投资周期会更长。(3)收益来源不同。私募证券投资基金收益来源基本为资本利得和分红；而私募股权基金的收益来源根据退出方式的不同而有所差异，风险收益更高。(4)附加服务。私募证券投资基金一般不参与企业经营，而私募股权基金投资为企业提供管理经验、再融资等增值服务。"},{"id":"jun-bas2-94","subject":"basics","source":"6月押题 LC","type":"判断","q":"使 ETF 二级市场价格与份额净值趋于一致的机制称套利机制。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。ETF 实行一级市场和二级市场并存的交易制度，这种双重交易机制使 ETF 的二级市场价格不会过度偏离基金份额净值，因为一级、二级市场的价差会产生套利机会，而套利交易会使二级市场价格回归到基金份额净值附近。"},{"id":"jun-bas2-95","subject":"basics","source":"6月押题 LC","type":"判断","q":"如果期望尾损失与 VAR 值相差越大，说明该组合损益分布的肥尾性越强，风险在相同的 VAR 水平上更高。()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。如果期望尾损失与 VaR 值的差值越大，说明该组合 (或证券)损益分布的肥尾性越强，风险在相同的 VaR 水平上更高。"},{"id":"jun-bas2-96","subject":"basics","source":"6月押题 LC","type":"判断","q":"利率作为货币政策中介目标存在的缺点是相关性弱。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。作为中介目标，利率的优点是可控性强、可测性强、相关性强。缺点是抗干扰性较差，容易受心理预期、金融市场投机活动等各种非货币政策因素的影响，从而降低其真实性。"},{"id":"jun-bas2-97","subject":"basics","source":"6月押题 LC","type":"判断","q":"开放式基金的认购，采取的是净额认购的方式。()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。开放式基金的认购采取金额认购的方式，即投资者在办理认购时，认购申请上不是直接填写需要认购多少份基金份额，而是填写需要认购多少金额的基金份额，基金注册登记人在基金认购结束后，再按基金份额的认购价格，将申请认购基金的金额换算成投资人应得的基金份额。"},{"id":"jun-bas2-98","subject":"basics","source":"6月押题 LC","type":"判断","q":"机构投资者包括政府机构类投资者、金融机构类投资者、保险经营机构投资者、合格境外投资者以及合格境内投资者。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。机构投资者主要包括政府机构类投资者、金融机构类投资者、合格境外投资者 (含 QFII、RQFII)、合格境内机构投资者 (QDII)、企业和事业法人类机构投资者以及基金类投资者 (不包括保险经营机构投资者)。"},{"id":"jun-bas2-99","subject":"basics","source":"6月押题 LC","type":"判断","q":"国际短期资金流动是指期限为三年以上的资金的跨国流动，包括国际直接投资、国际间接投资和国际信贷三种形式。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。国际短期资金流动是指期限为1年或1年以下的资金的跨国流动，包括贸易性资金的流动、套利性资金的流动、保值性资金的流动、投机性资金的流动。"},{"id":"jun-bas2-100","subject":"basics","source":"6月押题 LC","type":"判断","q":"股票的市场价格一般是指股票在二级市场上交易的价格。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。股票的市场价格一般是指股票在二级市场上交易的价格。"},{"id":"jun-bas2-101","subject":"basics","source":"6月押题 LC","type":"判断","q":"股利分配的形式主要有现金红利和股票红利两种。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。股利分配的形式主要有现金股利和股票股利两种。"},{"id":"jun-bas2-102","subject":"basics","source":"6月押题 LC","type":"判断","q":"股东大会作出普通决议必须经出席会议的股东所持表决权的三分之二以上通过。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。股东大会作出决议，必须经出席会议的股东所持表决权过半数通过。但是，股东会作出修改公司章程、增加或者减少注册资本的决议，以及公司合并、分立、解散或者变更公司形式的决议，必须经出席会议的股东所持表决权的 2/3 以上通过。"},{"id":"jun-bas2-103","subject":"basics","source":"6月押题 LC","type":"判断","q":"定向增发是股份公司向特定对象发行股票的增资方式，定向增发会直接影响公司原股东利益，需经股东会特别批准。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：题说法正确。向特定对象发行股票，也称为定向增发，是股份公司向特定对象发行股票的增资方式。特定对象包括公司控股股东、实际控制人及其控制的企业；与公司业务有关的企业；证券投资基金、证券公司、信托投资公司等金融机构；公司董事、员工等。公司可以对认购者的持股期限有所限制。这种增资方式会直接影响公司原股东利益，需经股东会特别批准。"},{"id":"jun-bas2-104","subject":"basics","source":"6月押题 LC","type":"判断","q":"当会员结算准备金余额小于零，且未能在第一节结束前补足的，交易所有权对其持仓进行强行平仓。()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。《中国金融期货交易所风险控制管理办法》规定下列五种情形下会强行平仓：(1)会员结算准备金余额小于零，且未能在第一节结束前补足的；(2)非期货公司会员、客户持仓超出持仓限额标准，且未能在第一节结束前平仓；(3)因违规、违约受到交易所强行平仓处理；(4)根据交易所的紧急措施应当予以强行平仓；(5)交易所规定应当予以强行平仓的其他情形。"},{"id":"jun-bas2-105","subject":"basics","source":"6月押题 LC","type":"判断","q":"从事套期保值等风险管理活动的，可以申请持仓限额豁免。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。对于进行套期保值交易和套利交易的持仓，则按照交易所的有关规定执行。从事套期保值等风险管理活动的，可以申请持仓限额豁免。当会员、客户持仓达到或者超过持仓限额时，不得同方向开仓交易。"},{"id":"jun-bas2-106","subject":"basics","source":"6月押题 LC","type":"判断","q":"从发起人角度看，资产证券化最基本的功能是融资。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。从发起人角度看，资产证券化最基本的功能是提高资产的流动性。"},{"id":"jun-bas2-107","subject":"basics","source":"6月押题 LC","type":"判断","q":"承销机构的发行人可以在发行环节直接或间接认购其发行的公司债券。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。发行人不得在发行环节直接或间接认购其发行的公司债券。发行人的董事、监事、高级管理人员、持股比例超过 5%的股东及其他关联方认购或交易、转让其发行的公司债券的，应当披露相关情况。"},{"id":"jun-bas2-108","subject":"basics","source":"6月押题 LC","type":"判断","q":"财政政策主要通过货币供给量、利率和信贷政策机制发生作用。 ()","options":["正确","错误"],"answer":"B","explain":"答案解析：本题说法错误。财政政策主要通过税收政策、公共支出政策以及国债发行等发挥作用。货币政策主要通过货币供给量、利率和信贷政策机制发生作用。"},{"id":"jun-bas2-109","subject":"basics","source":"6月押题 LC","type":"判断","q":"《巴塞尔协议》的颁布建立了资本充足率的最低标准。 ()","options":["正确","错误"],"answer":"A","explain":"答案解析：本题说法正确。巴塞尔委员会主要宗旨在于交换各国监管安排方面的信息，改善国际银行业务监管技术的有效性，建立资本充足率的最低标准，以及研究在其他领域确立标准的有效性。"},{"id":"jun-bas2-110","subject":"basics","source":"6月押题 LC","type":"案例","q":"【资料】假定某投资者以 940 元的价格购买了面额为 1000 元、票面利率为\n10%、剩余期限为 6 年的债券。请根据上述背景信息回答以下问题。\n\n【问题】该投资者的当期收益率为 () 。","options":["8%","10%","11%","12%"],"answer":"CD","explain":"答案解析：在投资学中，当期收益率被定义为债券的年利息收入与买入债券的实际价格的比率。其计算公式为： Y=C/P×100%; 式中：-当期收益率；C-每年利息收益；P-债券价格。本题中， C = 1 0 0 0 × 1 0 % = 1 0 0 元， P=940 元；当期收益率 Y=100/940×100%=11% (C 选项正确) 。2：下列关于债券收益率的说法，正确的有 ()。A、债券当期收益率是使债券未来现金流现值等于当前价格所用的贴现率B、债券的到期收益率是债券的年利息收入与买入债券的实际价格的比率C、债券持有期收益率是买入债券到卖出债券期间所获得的年平均收益D、在债券定价公式中，即期利率是用来现金流贴现的贴现率答案解析：A 选项错误，在投资学中，当期收益率被定义为债券的年利息收入与买入债券的实际价格的比率。B 选项错误，债券的到期收益率 (YTM)是使债券未来现金流现值等于当前价格所用的相同的贴现率，也就是金融学中所谓的内部报酬率(IRR)。C 选项正确，持有期收益率，是指买入债券到卖出债券期间所获得的年平均收益，它与到期收益率的区别仅仅在于末笔现金流是卖出价格而非债券到期偿还金额。D 选项正确，在债券定价公式中，即期利率就是用来进行现金流贴现的贴现率。故本题选 CD 选项。"}]},{"id":"t300-law","subject":"law","name":"9月300题 · 法律法规","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"t300-law-0","subject":"law","source":"9月300题 LC","type":"单选","q":"（）类公司文化建设水平在行业内最高。","options":["A","B","C","D"],"answer":"A","explain":"A 选项正确，A 类公司文化建设水平在行业内最高，在业务开展中能够践行\"合规、诚信、专业、稳健\"的核心价值观，文化建设能较好地与党建工作要求、人的全面发展、专业能力建设和历史文化传承有机结合，与公司治理、发展战略、发展方式和行为规范深度融合。故本题选A 选项。"},{"id":"t300-law-1","subject":"law","source":"9月300题 LC","type":"单选","q":"（）依法对交易商协会、同业拆借中心和中央结算公司进行监督管理。","options":["中国证监会","财政部","中国人民银行","国务院"],"answer":"C","explain":"C 选项正确，中国人民银行依法对交易商协会、同业拆借中心和中央结算公司进行监督管理。故本题选C 选项。"},{"id":"t300-law-2","subject":"law","source":"9月300题 LC","type":"单选","q":"《公司法》规定，股份有限公司将法定公积金转为股本时，留存的该项公积金不得少于转增前公司注册资本的（）。","options":["10%2","15%","20%","25%"],"answer":"D","explain":"D 选项正确，法定公积金转为增加注册资本时，所留存的该项公积金不得少于转增前公司注册资本的25%。故本题选D 选项。"},{"id":"t300-law-3","subject":"law","source":"9月300题 LC","type":"单选","q":"《股票质押回购交易业务协议》应当明确融入方融入资金可以用于（）。","options":["新股申购","通过竞价交易买入上市交易的股票","实体经济生产经营","投资于被列入国家相关部委发布的淘汰类产业目录"],"answer":"C","explain":"《业务协议》应明确约定融入方融入资金存放于其在证券公司指定银行开立的专用账户，并用于实体经济生产经营（C 选项正确）。不得直接或者间接用于下列用途：（1）投资于被列入国家相关部委发布的淘汰类产业目录，或者违反国家宏观调控政策、环境保护政策的项目（D 选项错误）：（2）进行新股申购（A 选项错误）：（3）通过竞价交易或者大宗交易方式买入上市交易的股票（B 选项错误）：（4）法律法规、中国证监会相关部门规章和规范性文件禁止的其他用途。故本题选C 选项。"},{"id":"t300-law-4","subject":"law","source":"9月300题 LC","type":"单选","q":"按照《证券公司风险控制指标计算标准规定》，证券公司自营权益类证券及其衍生品的合计额不得超过净资本的（）。3","options":["100%","500%","50%","80%"],"answer":"A","explain":"A 选项正确，根据《证券公司风险控制指标计算标准规定》，证券公司经营自营业务，其持仓规模必须符合规定：自营权益类证券及其衍生品的合计额不得超过净资本的 100%。故本题选A 选项。"},{"id":"t300-law-5","subject":"law","source":"9月300题 LC","type":"单选","q":"按照法律关系主体的数量进行划分，证券法律关系可分为（）。","options":["调整性法律关系与保护性法律关系","双边法律关系与多边法律关系","纵向法律关系与横向法律关系","民事法律关系与行政法律关系"],"answer":"B","explain":"A 选项错误，调整性法律关系与保护性法律关系是按照法律关系的职能不同进行的划分。B 选项正确，按照法律关系的主体数量，法律关系可分为双边法律关系与多边法律关系。C 选项错误，按照法律主体在法律关系中的地位不同，法律关系可分为纵向法律关系与横向法律关系。D 选项错误，按照法律关系所依据的法律部门，法律关系可分为宪法法律关系、民商事法律关系、行政法律关系、劳动法律关系、诉讼法律关系等不同部门的法律关系。故本题选B 选项。"},{"id":"t300-law-6","subject":"law","source":"9月300题 LC","type":"单选","q":"不具备（）资格的证券公司，其自有资金只能以对冲风险为目的，从事金融衍生品交易。","options":["证券自营业务","证券资产业务4","证券信用业务","证券做市交易"],"answer":"A","explain":"A 选项正确，不具备证券自营业务资格的证券公司只能以对冲风险为目的，从事金融衍生产品交易。故本题选A 选项。"},{"id":"t300-law-7","subject":"law","source":"9月300题 LC","type":"单选","q":"不具备（）资格的证券公司，其自有资金只能以套期保值为目的，参与股票期权交易。","options":["证券自营业务","证券资产业务","证券信用业务","证券做市业务"],"answer":"A","explain":"A 选项正确，不具备证券自营业务资格的证券公司，其自有资金只能以套期保值为目的，参与股票期权交易。故本题选A 选项。"},{"id":"t300-law-8","subject":"law","source":"9月300题 LC","type":"单选","q":"董监高人员离职（）内不能转卖股份。","options":["半年","一年","两年","三年"],"answer":"A","explain":"A 选项正确，公司董事、监事、高级管理人员离职后半年内，不得转让其所持有的本公司股份。故本题选A 选项。5"},{"id":"t300-law-9","subject":"law","source":"9月300题 LC","type":"单选","q":"对转融通担保证券账户内记录的证券，由（）以自己的名义，行使对证券发行人的权利。","options":["证券公司","证券金融公司","证券登记结算机构","商业银行"],"answer":"B","explain":"B 选项正确，对转融通担保证券账户内记录的证券，由证券金融公司以自己的名义，行使对证券发行人的权利。故本题选B 选项。"},{"id":"t300-law-10","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《发布证券研究报告暂行规定》和《发布证券研究报告执业规范》，下列不属于证券公司、证券投资咨询机构发布证券研究报告需载明事项的是（）。","options":["证券分析师姓名及登记编码","使用证券研究报告的收费环节说明","具备证券投资咨询业务资格的说明","证券研究报告采用的信息和资料来源"],"answer":"B","explain":"经营机构发布的证券研究报告，应当载明下列事项：（1）\"证券研究报告\"字样：（2）经营机构名称：（3）具备证券投资咨询业务资格的说明（C 选项不符合题意）：（4）证券分析师姓名及其登记编码（A 选项不符合题意）：（5）发布证券研究报告的时间：（6）证券研究报告采用的信息和资料来源（D 选项不符合题意）：（7）使用证券研究报告的风险提示。6故本题选B 选项。"},{"id":"t300-law-11","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《反洗钱法》规定，反洗钱不包括（）。","options":["合同违反","恐怖活动","贪污贿赂","金融诈骗"],"answer":"A","explain":"A 选项符合题意，合同违反属于一般的民事违约行为或行政违法行为，不属于《反洗钱法》列举的严重刑事犯罪范畴，因此，反洗钱工作不直接针对\"合同违反\"行为。反洗钱是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪（B 选项不符合题意）、走私犯罪、贪污贿赂犯罪（C 选项不符合题意）、破坏金融管理秩序犯罪、金融诈骗犯罪（D 选项不符合题意）和其他犯罪所得及其收益的来源和性质的洗钱活动，遏制相关违法犯罪活动，依照《反洗钱法》等法律法规采取相关措施的行为。故本题选A 选项。"},{"id":"t300-law-12","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《公司法》，下列关于可以用作有限责任公司出资的财产的说法，错误的是（）。","options":["货币","土地所有权","实物","知识产权"],"answer":"B","explain":"股东可以用货币出资（A 选项正确），也可以用实物（C 选项正确）、知识产权（D 选项正确）、土地使用权（B 选项错误，并非\"所有权\"）、股权、债权等可以用货币估价并可以依法转让的非货币财产作价出资：但是法律、行政法规规定不得作为出资的财产除外。故本题选B 选项。7"},{"id":"t300-law-13","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《公司法》，有限责任公司由1 个以上（）个以下股东出资设立。","options":["200","100","20","50"],"answer":"D","explain":"D 选项正确，有限责任公司由1 个以上 50 个以下股东出资设立。故本题选D 选项。"},{"id":"t300-law-14","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《公司法》的规定，有限责任公司的权力机构是（）。","options":["董事会","股东会","监事会","经理"],"answer":"B","explain":"B 选项正确，有限责任公司股东会是公司的权力机构，依法行使职权。故本题选B 选项。"},{"id":"t300-law-15","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《禁入规定》，证券市场禁入措施不包括（）。","options":["不得担任发行人的核心技术人员","不得在证券交易场所交易证券","不得从事证券业务、证券服务业务","不得担任证券发行人的董事、监事、高级管理人员"],"answer":"A","explain":"根据《禁入规定》第四条，执法单位可以采取的市场禁入种类包括：8（1）不得从事证券业务、证券服务业务（ C 选项不符合题意），不得担任证券发行人的董事、监事、高级管理人员（D 选项不符合题意）。（2）不得在证券交易场所交易证券（B 选项不符合题意）。故本题选A 选项。"},{"id":"t300-law-16","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《期货交易管理条例》，下列与期货相关的说法，错误的是（）。","options":["期权合约是指约定买方有权在将来某一时间以特定价格买入或者卖出约定标的物的标准化或非标准化合约","期货交易是指以期货合约或者标准化期权合约为交易标的的交易活动","期货交易场所可以制定非标准化的期权合约","期权合约可以约定将期货合约作为买卖标的物"],"answer":"C","explain":"A、D 选项正确，期权合约，是指约定买方有权在将来某一时间以特定价格买入或者卖出约定标的物（包括期货合约）的标准化或非标准化合约。B 选项正确，期货交易，是指以期货合约或者标准化期权合约为交易标的的交易活动。C 选项错误，非标准化期权合约属于\"场外衍生品交易\"的范畴。因此，期货交易场所不可以制定非标准化的期权合约。故本题选C 选项。"},{"id":"t300-law-17","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《融资融券交易风险揭示书必备条款》，融资融券交易不同于普通证券交易所特有的风险是（）。","options":["市场风险","系统风险","投资风险放大风险","政策风险"],"answer":"C","explain":"9融资融券业务交易风险揭示书的基本内容应包含：提示客户注意融资融券交易具有普通证券交易所具有的政策风险（D 选项错误）、市场风险（A 选项错误）、违约风险、系统风险（B 选项错误）等各种风险，以及其特有的投资风险放大等风险（C 选项正确）。故本题选C 选项。"},{"id":"t300-law-18","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《私募投资基金监督管理条例》，私募基金管理人应当遵循专业化管理原则。聘用具有相应从业经历的高级管理人员负责（）等工作。","options":["党建工作、风险控制、合规","投资管理、风险控制、合规","行政管理、监察审计、稽核","投资管理、监察审计、稽核"],"answer":"B","explain":"B 选项正确，私募基金管理人应当遵循专业化管理原则，聘用具有相应从业经历的高级管理人员负责投资管理、风险控制、合规等工作。A 选项错误，错在党建工作。C、D 选项错误，错在行政管理、监察审计、稽核。故本题选B 选项。"},{"id":"t300-law-19","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券发行上市保荐业务管理办法》，证券发行规模达到一定数量的，可以采用联合保荐，但参与联合保荐的保荐机构不得超过（）家。","options":["3","2","1","4"],"answer":"B","explain":"B 选项正确，证券发行规模达到一定数量的，可以采用联合保荐，但参与联合保荐的保荐机构10不得超过2 家。故本题选B 选项。"},{"id":"t300-law-20","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券法》，向特定对象发行证券累计超过（）人属于公开发行，但依法实施员工持股计划的员工人数不计算在内。","options":["100","1000","500","200"],"answer":"D","explain":"有下列情形之一的，为公开发行：（1）向不特定对象发行证券的：（2）向特定对象发行证券累计超过 200 人的，但依法实施员工持股计划的员工人数不计算在内（D 选项符合题意）：（3）法律、行政法规规定的其他发行行为。故本题选D 选项。"},{"id":"t300-law-21","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券法》，证券承销业务的种类不包括（）。","options":["自行销售","代销","全额包销","余额包销"],"answer":"A","explain":"A 选项符合题意，证券承销业务采取代销或者包销方式（B 选项不符合题意），其中包销分为全额包销和余额包销（C、D 选项不符合题意）。故本题选A 选项。11"},{"id":"t300-law-22","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券法》，证券的发行、交易活动，必须遵循的原则不包括（）。","options":["公开","公正","公平","公允"],"answer":"D","explain":"证券的发行、交易活动，必须遵循公开（A 选项不符合题意）、公平（C 选项不符合题意）、公正（B 选项不符合题意）\"三公\"原则。故本题选D 选项。"},{"id":"t300-law-23","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券法》代销协议应当载明的事项不包括（）。","options":["侵权责任","代销的付款方式及日期","代销的期限及起止日期","代销证券的种类、数量、金额及发行价格"],"answer":"A","explain":"注意题目问的是\"不包括\"。A 选项符合题意，侵权责任的认定和承担由《证券法》、《民法典》等法律直接规定，不属于代销协议中应当载明的事项。证券公司承销证券，应当同发行人签订代销或者包销协议，载明下列事项：（1）当事人的名称、住所及法定代表人姓名：（2）代销、包销证券的种类、数量、金额及发行价格（D 选项不符合题意）：（3）代销、包销的期限及起止日期（C 选项不符合题意）：（4）代销、包销的付款方式及日期（B 选项不符合题意）：（5）代销、包销的费用和结算办法：12（6）违约责任：（7）国务院证券监督管理机构规定的其他事项。故本题选A 选项。"},{"id":"t300-law-24","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券法》下列关于禁止内幕交易的相关说法，错误的是（）。","options":["证券交易内幕信息的知情人，在内幕信息公开前，不得买卖该公司的证券","非法获取内幕信息的人，在内幕信息公开前，不得买卖该公司的证券","证券交易内幕信息的知情人，在内幕信息公开前，不得买卖该公司的证券，但可以建议他人买卖该证券","禁止证券交易内幕信息的知情人和非法获取内幕信息的人利用内幕信息从事证券交易活动"],"answer":"C","explain":"证券交易内幕信息的知情人和非法获取内幕信息的人，在内幕信息公开前，不得买卖该公司的证券，或者泄露该信息，或者建议他人买卖该证券（C 选项错误）。故本题选C 选项。"},{"id":"t300-law-25","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司董事、监事、高级管理人员及从业人员管理规则》，下列人员中不属于证券从业人员的是（）。","options":["证券公司董事长刘某","证券公司行政管理部的前台岗滕某","证券公司投资咨询部门证券分析师张某","证券公司融资融券部门投资经理王某"],"answer":"B","explain":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》《证券公司董事、监事、高级管理人员及从业人员管理规则》，从业人员是指在证券基金经营机构从事证券基金业务和相关管理工作的人员，包括从事证券经纪、证券投资咨询、与证券交易及证券投资活动有关的财务顾问、证券承销与保荐、证券融资融券、证券自营、证券做市交易、证券资产管理等业务和相关管理工作的人员（C、D 选项不符合题意）。13证券公司董事长（A 选项不符合题意）、从事业务管理工作的其他董事和监事、高级管理人员、分支机构负责人均为本章所称从业人员。B 选项符合题意，其岗位职责与证券业务无直接关联，不属于证券从业人员。故本题选B 选项。"},{"id":"t300-law-26","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司分类监管规定》，证券公司分类评价（）进行一次。","options":["每年","每半年","每月","每季度"],"answer":"A","explain":"A 选项正确，证券公司分类评价每年进行一次，评价期为上一年度 5 月 1 日至本年度 4 月 30日。故本题选A 选项。"},{"id":"t300-law-27","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司风险处置条例》，下列关于行政重组的说法，错误的是（）。","options":["证券公司进行行政重组，可以采取注资、股权重组、债务重组、资产重组、合并或者其他方式","证券公司经停业整顿在规定期限内仍达不到正常经营条件，但能够清偿到期债务的，可以向证监会申请行政重组","行政重组期限一般不超过 12 个月。期满未完成的，可向国务院证券监督管理机构申请延长期限6 个月","在托管、接管过程中达到正常经营条件的，经证监会批准，可以恢复正常经营"],"answer":"B","explain":"B 选项错误，证券公司经停业整顿、托管、接管或者行政重组在规定期限内仍达不到正常经营条件，但能够清偿到期债务的，国务院证券监督管理机构依法撤销其证券业务许可（并非 \"向证监会申请行政重组\"）。14A、C 选项正确，证券公司进行行政重组，可以采取注资、股权重组、债务重组、资产重组、合并或者其他方式。行政重组期限一般不超过 12 个月。满 12 个月，行政重组未完成的，国务院证券监督管理机构可以决定延长行政重组期限，但延长行政重组期限最长不得超过 6 个月。D 选项正确，证券公司经停业整顿、托管、接管或者行政重组在规定期限内达到正常经营条件的，经国务院证券监督管理机构批准，可以恢复正常经营。故本题选B 选项。"},{"id":"t300-law-28","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司风险处置条例》，证券公司出现重大风险，在实施某些风险处置措施过程中达到规定条件的，可以由证监会对其进行行政重组。上述风险处置措施不包括（）。","options":["接管","停业整顿","托管","撤销证券业务许可"],"answer":"D","explain":"被停业整顿（B 选项不符合题意）、托管（C 选项不符合题意）、接管（A 选项不符合题意）的证券公司，具备规定条件的，也可以由国务院证券监督管理机构对其进行行政重组。D 选项符合题意，以上风险处置措施不包括撤销证券业务许可。故本题选D 选项。【温馨提示】证券公司出现重大风险，但具备下列条件的，可以由国务院证券监督管理机构对其进行行政重组：（1）财务信息真实、完整：（2）省级人民政府或者有关方面予以支持：（3）整改措施具体，有可行的重组计划。"},{"id":"t300-law-29","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司风险控制指标管理办法》，证券公司未按期完成整改、风险控制指标情况继续恶化，严重危及该证券公司的稳健运行的，（）可以撤销其有关业务许可。15","options":["证券业协会","中国证监会","中国证监会派出机构","证券交易所"],"answer":"B","explain":"证券公司风险控制指标无法达标，严重危害证券市场秩序、损害投资者利益的：中国证监会可以区别情形（B 选项正确），对其采取下列措施：（1）责令停业整顿：（2）指定其他机构托管、接管：（3）撤销经营证券业务许可：（4）撤销。故本题选B 选项。"},{"id":"t300-law-30","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司风险控制指标计算标准规定》，下列关于证券自营业务风险控制指标的说法，错误的是（）。","options":["持有一种权益类证券的成本不得超过净资本的30%","持有一种权益类证券的市值与其流通市值的比例不得超过5%","自营非权益类证券及其衍生品的合计额不得超过净资本的500%","自营权益类证券及其衍生品的合计额不得超过净资本的100%"],"answer":"B","explain":"证券公司经营自营业务，其持仓规模必须符合下列规定：（1）自营权益类证券及其衍生品的合计额不得超过净资本的100%（D 选项正确）。（2）自营非权益类证券及其衍生品的合计额不得超过净资本的500%（C 选项正确）。（3）持有一种权益类证券的成本不得超过净资本的30%（A 选项正确）。（4）持有一种权益类证券的市值与其总市值的比例不得超过5%（B 选项错误）。16（5）持有一种非权益类证券的规模不得超过其总规模的20%。故本题选B 选项。"},{"id":"t300-law-31","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，王某为甲证券公司合规负责人，下列做法正确的是（）。","options":["王某对本公司经营管理的合规性进行审核，监督工作由监事会完成","王某任职前取得高级管理人员的任职资格","王某任合规总监的同时，负责管理公司研究所的工作","王某直接向公司总经理张某负责"],"answer":"B","explain":"A、D 选项错误，合规负责人是高级管理人员，直接向董事会负责（并非总经理），对本公司及其工作人员的经营管理和执业行为的合规性进行审查、监督和检查。因此，王某自身就应当履行监督和检查职责，而不是交由监事会完成。B 选项正确，合规负责人属于公司的高级管理人员，因此王某在任职前必须依法取得高级管理人员的任职资格。C 选项错误，证券公司分管合规管理、风险管理、稽核审计部门的高级管理人员，不得兼任或者分管与合规管理、风险管理、稽核审计职责相冲突的职务或者部门。合规部门不得承担业务、财务、信息技术等与合规管理相冲突的职责。研究所属于业务部门，因此王某不能同时负责管理公司研究所的工作。故本题选B 选项。"},{"id":"t300-law-32","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，下列关于证券公司合规管理要求的说法，错误的是（）。","options":["贯穿决策、执行、监督、反馈等各个环节","覆盖所有业务","覆盖各部门，各分支机构、各关联公司","覆盖全体工作人员"],"answer":"C","explain":"17证券公司的合规管理应当覆盖所有业务（B 选项正确），各部门、各分支机构、各层级子公司（C 选项错误）和全体工作人员（D 选项正确），贯穿决策、执行、监督、反馈等各个环节（A选项正确）。故本题选C 选项。"},{"id":"t300-law-33","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，证券公司不采纳合规负责人的合规审查意见的，应当将有关事项提交（）审议决定。","options":["经理层","董事会","监事会","股东会"],"answer":"B","explain":"B 选项正确，规定公司不采纳合规负责人的合规审查意见的，应当将有关事项提交董事会审议决定。故本题选B 选项。"},{"id":"t300-law-34","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司全面风险管理规范》，证券公司（）对公司全面风险管理承担主要责任。","options":["首席风险官","董事会","经理层","风险管理部门"],"answer":"C","explain":"C 选项正确，证券公司经理层对全面风险管理承担主要责任。故本题选C 选项。【温馨提示】18风险管理组织架构：（1）证券公司董事会承担全面风险管理的最终责任。（2）证券公司经理层对全面风险管理承担主要责任。（3）证券公司监事会（或行使监事会职权的监事或董事会设置的由董事组成的审计委员会）承担全面风险管理的监督责任。（4）证券公司应当任命一名高级管理人员负责全面风险管理工作（统称首席风险官）。（5）证券公司应当指定或者设立专门部门履行风险管理职责，在首席风险官的领导下推动全面风险管理工作。（6）证券公司各部门、分支机构及子公司的负责人承担风险管理的直接责任。（7）证券公司每一名员工对风险管理有效性承担勤勉尽责、审慎防范、及时报告的责任。"},{"id":"t300-law-35","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司全面风险管理规范》，证券公司全面风险管理的责任主体不包括（）。","options":["董事会","经理层","全体员工","股东会"],"answer":"D","explain":"A 选项不符合题意，证券公司董事会承担全面风险管理的最终责任。B 选项不符合题意，证券公司经理层对全面风险管理承担主要责任。C 选项不符合题意，证券公司每一名员工对风险管理有效性承担勤勉尽责、审慎防范、及时报告的责任。D 选项符合题意，股东会是权力机构，不直接参与风险管理的日常运作。故本题选D 选项。"},{"id":"t300-law-36","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券公司声誉风险管理指引》，下列不属于声誉风险管理应遵循的原则是（）。","options":["从高层做起原则","预防第一原则19","审慎管理原则","快速响应原则"],"answer":"A","explain":"声誉风险管理应遵循全程全员原则、预防第一原则（ B 选项不符合题意）、审慎管理原则（C选项不符合题意）、快速响应原则（D 选项不符合题意）。故本题选A 选项。"},{"id":"t300-law-37","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司委托信息技术服务机构提供信息技术服务责任划分的说法，错误的是（）。","options":["证券公司借助信息技术手段从事证券基金业务活动的，可以委托信息技术服务机构提供产品或服务","委托信息技术服务机构提供产品或服务的，证券公司依法应当承担的责任可因委托而免除或减轻","证券公司应当清晰、准确、完整地掌握重要信息系统的技术架构、业务逻辑和操作流程等内容，确保重要信息系统运行始终处于自身控制范围","除法律法规及中国证监会另有规定外，证券公司不得将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施"],"answer":"B","explain":"B 选项错误，证券公司借助信息技术手段从事证券基金业务活动的，可以委托信息技术服务机构提供产品或服务，但证券公司依法应当承担的责任不因委托而免除或减轻。故本题选B 选项。"},{"id":"t300-law-38","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券期货经营机构及其工作人员廉洁从业规定》，某证券公司的下列做法，错误的是（）。","options":["建立健全廉洁从业内部控制制度，制定具体、有效的事前风险防范体系、事中管控措施和事后追责机制","对所从事的业务种类、环节及相关工作进行科学、系统的廉洁风险评估，识别廉洁从业风20险点，强化岗位制衡与内部监督机制并确保运作有效","制定工作人员廉洁从业规范，明确廉洁从业要求，加强从业人员廉洁培训和教育，培育廉洁从业文化","将工作人员廉洁从业纳入工作人员管理体系，对工作人员廉洁从业情况予以考察评估，离职情形除外"],"answer":"D","explain":"A 选项正确，证券经营机构应当制定具体、有效的事前风险防范体系、事中管控措施和事后追责机制。B 选项正确，证券经营机构应当对所从事的业务种类、环节（包括业务承揽、承做、销售、交易、结算、交割、投资、采购、商业合作、人员招聘，以及申请行政许可、接受监管执法和自律管理等）及相关工作进行科学、系统的廉洁风险评估，识别廉洁从业风险点，强化岗位制衡与内部监督机制并确保运作有效。C 选项正确，证券经营机构应当加强廉洁文化建设，每年开展覆盖全体工作人员的廉洁培训和教育，确保工作人员熟悉廉洁从业的相关规定，提高工作人员廉洁意识。D 选项错误，证券经营机构应当制定覆盖全体工作人员的廉洁从业规范，将工作人员廉洁从业情况纳入人力资源管理体系，并将廉洁从业情况考察和评估结果作为人员聘用、从业人员登记和后续管理、晋级、提拔、离职以及考核、薪酬管理、审计、稽核等事项的重要考量因素。故本题选D 选项。"},{"id":"t300-law-39","subject":"law","source":"9月300题 LC","type":"单选","q":"根据《证券期货经营机构及其工作人员廉洁从业规定》以及《证券经营机构及其工作人员廉洁从业实施细则》，某证券公司经纪业务从业人员王某的下列做法中，不属于违反证券经营机构工作人员廉洁从业要求的是（）。","options":["在下达资产管理产品营销任务时有意削减熟识营业部的考核指标","假期自驾出游期间给予交通协管人员好处以免除违章停车处罚","协助好友伪造资料以满足科创板投资者适应性管理的核查要求","指示下属营业部在不符合条件的情况下为其亲属申报股票质押式回购以获得更低的融资成本"],"answer":"B","explain":"21廉洁从业，是指证券期货经营机构及其工作人员在开展证券期货业务及相关活动中，严格遵守法律法规、中国证监会的规定和行业自律规则，遵守社会公德、商业道德、职业道德和行为规范，公平竞争，合规经营，忠实勤勉，诚实守信，不直接或者间接向他人输送不正当利益或者谋取不正当利益。A、C、D 选项不符合题意，均是在证券业务活动中的不廉洁行为。B 选项符合题意，属于私人生活的不廉洁行为。故本题选B 选项。"},{"id":"t300-law-40","subject":"law","source":"9月300题 LC","type":"多选","q":"按照《证券期货投资者适当性管理办法》，经营机构向个人投资者销售产品或者提供服务时，应当了解投资者的信息可以包括（）。","options":["基本信息","财务状况","诚信记录","投资经验"],"answer":"ABCD","explain":"根据《证券期货投资者适当性管理办法》的要求，经营机构向投资者销售产品或者提供服务时，应当了解投资者的下列信息：（1）自然人的姓名、住址、职业、年龄、联系方式，法人或者其他组织的名称、注册地址、办公地址、性质、资质及经营范围等基本信息（A 选项符合题意）：（2）收入来源和数额、资产、债务等财务状况（B 选项符合题意）：（3）投资相关的学习、工作经历及投资经验（D 选项符合题意）：（4）投资期限、品种、期望收益等投资目标：（5）风险偏好及可承受的损失：（6）诚信记录（C 选项符合题意）：22（7）实际控制投资者的自然人和交易的实际受益人：（8）法律法规、自律规则规定的投资者准入要求相关信息：（9）其他必要信息。故本题选ABCD 选项。"},{"id":"t300-law-41","subject":"law","source":"9月300题 LC","type":"多选","q":"不得担任财务顾问主办人的条件包括（）。","options":["最近24 个月内有违反诚信的不良记录","最近36 个月因执业行为违法违规受到处罚","最近24 个月因执业行为违反行业规范而受到行业自律组织的纪律处分","有大额贷款，到期未清偿"],"answer":"ABCD","explain":"财务顾问主办人应当具备下列条件：（1）具备中国证监会规定的投资银行业务经历：（2）具备从事相关业务的专业能力：（3）所任职机构同意推荐其担任本机构的财务顾问主办人：（4）未负有数额较大到期未清偿的债务（D 选项符合题意）：（5）最近24 个月无违反诚信的不良记录（A 选项符合题意）：（6）最近 24 个月未因执业行为违反行业规范而受到行业自律组织的纪律处分（C 选项符合题意）：（7）最近36 个月未因执业行为违法违规受到处罚（B 选项符合题意）：（8）中国证监会规定的其他条件。故本题选ABCD 选项。"},{"id":"t300-law-42","subject":"law","source":"9月300题 LC","type":"多选","q":"发生下列（）事项时发行人应聘请具有保荐业务资格的证券公司履行保荐职责。","options":["首次公开发行股票并上市","上市公司发行新股、可转换公司债券","公开发行存托凭证23","中国证监会认定的其他情形"],"answer":"ABCD","explain":"发行人申请从事下列发行事项，依法采取承销方式的，应当聘请具有保荐业务资格的证券公司（即保荐机构）履行保荐职责：（1）首次公开发行股票（A 选项正确）：（2）向不特定合格投资者公开发行股票并在北京证券交易所上市：（3）上市公司发行新股、可转换公司债券（B 选项正确）：（4）公开发行存托凭证（C 选项正确）：（5）中国证监会认定的其他情形（D 选项正确）。故本题选ABCD 选项。"},{"id":"t300-law-43","subject":"law","source":"9月300题 LC","type":"多选","q":"发生影响或者可能影响期货公司经营管理、财务状况或者客户资产安全的重大事件的，证券金融公司应当立即向中国证监会报告，说明（）。","options":["事件的起因","目前的状态","解决方案或措施","产生的利益损失"],"answer":"ABC","explain":"发生影响或者可能影响公司经营管理的重大事件的，证券金融公司应当立即向中国证监会报送临时报告，说明事件的起因（A 选项正确）、目前的状态（B 选项正确）、可能产生的后果和应对措施（C 选项正确）。故本题选ABC 选项。"},{"id":"t300-law-44","subject":"law","source":"9月300题 LC","type":"多选","q":"法律关系的特征主要有（）。","options":["以权利和义务为内容的一种社会关系","法律主体之间的一种社会关系24","以法律规范为基础形成的一种社会关系","社会组织之间的一种市场关系"],"answer":"ABC","explain":"法律关系的特征：（1）法律关系是一种以法律规范为基础形成的社会关系（C 选项正确）：（2）法律关系是以权利和义务为内容的社会关系（A 选项正确）：（3）法律关系是法律主体之间的社会关系（B 选项正确）。D 选项错误，法律关系的主体不仅包括\"社会组织\"，还包括自然人、国家等。法律关系是社会关系，其内容不仅限于 \"市场关系\"，因此，此选项将法律关系限定在\"社会组织\"之间的\"市场关系\"，大大缩小了其范围。故本题选ABC 选项。"},{"id":"t300-law-45","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《非上市公众公司监督管理办法》，下列关于信息披露义务人违反信息披露义务的说法，正确的有（）。","options":["信息披露义务人未按照规定披露信息，依照《证券法》有关规定进行处罚","信息披露义务人所披露的信息有虚假记载，依照《证券法》有关规定进行处罚","信息披露义务人所披露的信息对股价有重大影响，依照《证券法》有关规定进行处罚","信息披露义务人所披露的信息有误导性陈述，依照《证券法》有关规定进行处罚"],"answer":"ABD","explain":"A、B、D 选项正确，公司及其他信息披露义务人未按照规定披露信息，或者所披露的信息有虚假记载、误导性陈述或者重大遗漏的，依照《证券法》有关规定进行处罚。C 选项错误，对股价有重大影响，只要是合法合规披露，不会处罚。故本题选ABD 选项。"},{"id":"t300-law-46","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《公司法》，公司的组织形式包括（）。","options":["有限责任公司25","合伙公司","有限合伙公司","股份有限公司"],"answer":"AD","explain":"A、D 选项正确，我国《公司法》所称公司，是指依据《公司法》在中华人民共和国境内设立的有限责任公司和股份有限公司。故本题选AD 选项。"},{"id":"t300-law-47","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《公司法》，下列关于公司合并的说法，正确的有（）。","options":["公司合并可以采取吸收合并或者新设合并","三个以上公司合并设立一个新的公司为新设合并，合并各方保留","公司合并时，合并各方的债权、债务，应当由合并后存续的公司或者新设的公司承继","公司与其持股90%以上的公司合并，被合并的公司不需经股东会决议"],"answer":"ACD","explain":"A 选项正确，公司合并可以采取吸收合并或者新设合并。B 选项错误，两家以上（并非三个以上）公司合并设立一家新的公司为新设合并，合并各方解散（并非\"保留\"）。C 选项正确，公司合并时，合并各方的债权、债务，应当由合并后存续的公司或者新设的公司承继。D 选项正确，公司与其持股 90%以上的公司合并，被合并的公司不需经股东会决议，但应当通知其他股东，其他股东有权请求公司按照合理的价格收购其股权或者股份。故本题选ACD 选项。"},{"id":"t300-law-48","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《关于规范金融机构资产管理业务的指导意见》，下列关于资产管理业务运用人工智能技术的说法，正确的有（）。","options":["金融机构不得借助人工智能业务夸大宣传资产管理产品或者误导投资者26","非金融机构不得借助智能投资顾问超范围经营","金融机构运用人工智能技术开展投资顾问业务应当取得投资顾问资质","金融机构未出现违规但因管理不当造成投资者损失的，可不承担赔偿责任"],"answer":"ABC","explain":"A 选项正确，金融机构运用人工智能技术开展资产管理业务应当严格遵守意见有关投资者适当性、投资范围、信息披露、风险隔离等一般性规定，不得借助人工智能业务夸大宣传资产管理产品或者误导投资者。B、C 选项正确，运用人工智能技术开展投资顾问业务应当取得投资顾问资质，非金融机构不得借助智能投资顾问超范围经营或者变相开展资产管理业务。D 选项错误，金融机构因违法违规或者管理不当造成投资者损失的，应当依法承担损害赔偿责任。故本题选ABC 选项。"},{"id":"t300-law-49","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《关于加强对利用\"荐股软件\"从事证券投资咨询业务监管的暂行规定》，具备（）功能的软件产品、软件工具或者终端设备是\"荐股软件\"。","options":["提供具体证券投资品种选择建议","提供具体证券投资品种的买卖时机建议","提供涉及具体证券投资品种的投资分析意见，或者预测具体证券投资品种的价格走势","具备证券信息汇总或者证券投资品种历史数据统计功能"],"answer":"ABC","explain":"荐股软件是指具备下列一项或多项证券投资咨询服务功能的软件产品、软件工具或者终端设备：（1）提供涉及具体证券投资品种的投资分析意见，或者预测具体证券投资品种的价格走势（C选项正确）：（2）提供具体证券投资品种选择建议（A 选项正确）：（3）提供具体证券投资品种的买卖时机建议（B 选项正确）：（4）提供其他证券投资分析、预测或者建议。27D 选项错误，具备证券信息汇总或者证券投资品种历史数据统计功能，但不具备上述第一点至第四点所列功能的软件产品、软件工具或者终端设备，不属于\"荐股软件\"。故本题选ABC 选项。"},{"id":"t300-law-50","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《关于进一步加强证券基金经营机构债券交易监管的通知》，债券有关业务应当按照经纪、（）等业务类型分开办理。","options":["投资顾问","承销","资管","自营"],"answer":"ABCD","explain":"债券有关业务应按照经纪、自营（D 选项正确）、承销（B 选项正确）、资管（C 选项正确）、投资顾问（A 选项正确）等类型分开办理，并在人员、账户、资金、信息等方面严格分离，防范利益冲突：债券交易的投资决策、交易执行、风险控制、清算交收等关键岗位应专人负责，禁止岗位兼任或者混合操作。故本题选ABCD 选项。"},{"id":"t300-law-51","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《期货和衍生品法》，下列属于期货交易者分类因素的有（）。","options":["近亲属信息","工作单位地址","交易知识和经验","财产状况"],"answer":"CD","explain":"根据财产状况（D 选项符合题意）、金融资产状况、交易知识和经验（C 选项符合题意）、专业能力等因素，期货交易者可以分为普通交易者和专业交易者。故本题选CD 选项。28"},{"id":"t300-law-52","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《私募投资基金监督管理条例》，私募基金管理人不得采取以下行为（）。","options":["通过电话向不特定对象宣传推介","通过即时通信工具向不特定对象宣传推介","通过设有密码认证限制的销售平台向特定对象宣传推介","通过分析会向不特定对象分析推介"],"answer":"ABD","explain":"私募基金应非公开募集，不得通过报刊、电台、电视台、互联网等大众传播媒介，电话、短信、即时通信工具、电子邮件、传单，或者讲座、报告会、分析会等方式向不特定对象宣传推介（A、B、D 选项正确）：不得以虚假、片面、夸大等方式宣传推介：不得以私募基金托管人名义宣传推介：不得向投资者承诺投资本金不受损失或者承诺最低收益。私募基金管理人应当自行募集资金，不得委托他人募集资金，但国务院证券监督管理机构另有规定的除外。故本题选ABD 选项。"},{"id":"t300-law-53","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券、期货投资咨询管理暂行办法》，下列证券公司开展证券投资咨询业务中，不符合业务管理规定的有（）。","options":["投资咨询人员以化名在电台做投资咨询报告","投资咨询人员在网络媒体上开展投资咨询时注明自己所在证券公司和个人真实姓名","投资咨询人员向客户提供的证券投资咨询传真件注明机构名称、地址、联系电话和联系人姓名","投资咨询人员在报刊发表投资咨询文章，不需对投资风险作充分说明"],"answer":"AD","explain":"证券投资咨询人员在报刊、电台、电视台或者其他传播媒体上发表投资咨询文章、报告或者意见时，必须注明所在证券、期货投资咨询机构的名称和个人真实姓名，并对投资风险作充分说明（A、D 选项符合题意，B 选项不符合题意）。证券、期货投资咨询机构向投资人或者客户提供的证券、期货投资咨询传真件必须注明机构名29称、地址、联系电话和联系人姓名（C 选项不符合题意）。故本题选AD 选项。"},{"id":"t300-law-54","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券法》，下列关于上市公司收购和信息披露的法律责任的说法，正确的有（）。","options":["信息披露义务人未按照相关规定报送有关报告或者履行信息披露义务的，责令改正，给予警告，并处以五十万元以上五百万元以下的罚款","收购人未按照相关规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处以五十万元以上五百万元以下的罚款","收购人未按照相关规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，无罚款","信息披露义务人未按照相关规定报送有关报告或者履行信息披露义务的，对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以上一百万元以下的罚款"],"answer":"AB","explain":"A 选项正确、D 选项错误，根据《证券法》第一百九十七条的规定，信息披露义务人未按照《证券法》的规定报送有关报告或者履行信息披露义务的，责令改正，给予警告，并处以 50万元以上 500 万元以下的罚款：对直接负责的主管人员和其他直接责任人员给予警告，并处以20 万元以上200 万元以下罚款（并非\"一百万元以下\"）。B 选项正确、C 选项错误，根据《证券法》第一百九十六条的规定，收购人未按照《证券法》的规定履行上市公司收购的公告、发出收购要约义务的，责令改正，给予警告，并处以 50 万元以上500 万元以下的罚款（并非\"无罚款\"）。故本题选AB 选项。"},{"id":"t300-law-55","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券法》，下列关于证券公司从业人员执业行为的相关说法，正确的有（）。","options":["禁止从业人员为牟取佣金收入，诱使客户进行不必要的证券买卖","禁止从业人员在证券交易活动中作出虚假陈述或者信息误导","禁止从业人员不在规定时间内向客户提供交易的确认文件","禁止从业人员未经客户的委托，擅自为客户买卖证券"],"answer":"ABCD","explain":"30根据《证券法》，从业人员应当遵守的其他禁止性行为要求包括：（1）禁止利用未公开信息交易。（2）禁止在证券交易活动中作出虚假陈述或者信息误导（B 选项正确）。（3）禁止从事损害客户利益的行为：①违背客户的委托为其买卖证券：②不在规定时间内向客户提供交易的确认文件（C 选项正确）：③未经客户的委托，擅自为客户买卖证券（D 选项正确），或者假借客户的名义买卖证券：④为牟取佣金收入，诱使客户进行不必要的证券买卖（A 选项正确）：⑤其他违背客户真实意思表示，损害客户利益的行为。（4）禁止私下接受客户委托买卖证券。故本题选ABCD 选项。"},{"id":"t300-law-56","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券法》，下列关于证券销售期限，说法正确的有（）。","options":["证券的代销，包销期限最长不超过180 日","公开发行股票，代销，包销期限届满，发行人应当在规定的期限内将股票发行情况报国务院证券监督管理机构备案","证券的代销，包销期限最长不超过90 日","证券公司在代销，包销期内，对所代销，包销的证券应当保证先行出售给认购人，证券公司不得为本公司预留所代销的证券和预先购入并留存所包销的证券"],"answer":"BCD","explain":"A 选项错误、C 选项正确，证券的代销、包销期限最长不得超过 90 日。B 选项正确，公开发行股票，代销、包销期限届满，发行人应当在规定的期限内将股票发行情况报国务院证券监督管理机构备案。D 选项正确，证券公司在代销、包销期内，对所代销、包销的证券应当保证先行出售给认购人，证券公司不得为本公司预留所代销的证券和预先购入并留存所包销的证券。31故本题选BCD 选项。"},{"id":"t300-law-57","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券公司分类监管规定》，甲证券公司为 AA 级，乙证券公司为 BBB 级，丙证券公司为C 级，丁证券公司为 D 级，可以正常经营的证券公司的是（）。","options":["甲证券公司","乙证券公司","丙证券公司","丁证券公司"],"answer":"ABC","explain":"中国证监会根据证券公司评价计分的高低，将证券公司分为 A（AAA、AA、A）、B（BBB、BB、B）、C（CCC、CC、C）、D、E 五大类11 个级别。其中，C 级是正常经营状态的最低等级。A、B、C 选项正确，甲、乙、丙证券公司均在 C 级以上，因此，可以达到正常经营状态。D 选项错误，丁证券公司为D 级，不满足正常经营状态。故本题选ABC 选项。"},{"id":"t300-law-58","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券公司风险控制指标管理办法》，下列关于证券公司应持续符合的风险控制指标标准的说法，正确的有（）。","options":["流动性覆盖率不得低于100%","净稳定资金率不得低于100%","风险覆盖率不得低于80%","资本杠杆率不得低于8%"],"answer":"ABD","explain":"证券公司必须持续符合下列风险控制指标标准：（1）风险覆盖率不得低于100%（C 选项错误，并非 80%）：（2）资本杠杆率不得低于8%（D 选项正确）：（3）流动性覆盖率不得低于100%（A 选项正确）：32（4）净稳定资金率不得低于100%（B 选项正确）。故本题选ABD 选项。"},{"id":"t300-law-59","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券公司监督管理条例》，下列关于证券公司建立完善内部控制体系的说法，正确的有（）。","options":["证券公司融资融券业务应当建立逐日盯市制度","证券公司资产管理业务应当订立客户保本保底条款","证券公司经纪业务应当进行账户实名制管理","证券公司的自营业务必须以自己的名义进行"],"answer":"ACD","explain":"A 选项正确，证券公司从账户开立、保证金比例、担保品的收取、逐日盯市制度等方面，对融资融券业务作出了规定。B 选项错误，证券公司从账户备案、风险揭示、信息披露、禁止保本保底、对有关账户的交易行为实行实时监控等方面，对证券资产管理业务作出了规定。C 选项正确，经纪业务应建立健全账户实名制、客户信息保护、异常交易监测、大额及可疑交易报告、客户回访、客户投诉处理等制度和流程，及时发现、妥善处理风险事件。D 选项正确，证券自营业务，是指经中国证监会批准经营证券自营业务的证券公司用自有资金以自己名义开设的证券账户买卖依法公开发行的股票、债券、证券投资基金或者国务院证券监督管理机构认可的其他证券，以获取盈利的行为。故本题选ACD 选项。"},{"id":"t300-law-60","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券公司内部控制指引》，下列关于证券公司业务部门承担的内控职责的说法，正确的有（）。","options":["业务部门负责人对其业务范围内的具体作业程序和风险控制措施进行自我检查和评价","相关业务人员应对违反职责范围内的内部控制导致的风险和损失承担首要责任","业务部门仅接受证券公司上级管理部门的业务检查和指导","相关业务人员有义务向证券公司报告内部控制的缺陷并及时加以纠正"],"answer":"ABD","explain":"33业务部门和分支机构的负责人负责对其业务范围内的具体作业程序和风险控制措施进行自我检查和评价（A 选项正确），并接受证券公司上级管理部门和监督检查部门的业务检查和指导（C选项错误）。直接从事业务经营活动的业务部门和分支机构的相关人员有义务向证券公司报告内部控制的缺陷，并及时加以纠正（D 选项正确）。相关人员应对违反职责范围内的内部控制导致的风险和损失承担首要责任（B 选项正确）。故本题选ABD 选项。"},{"id":"t300-law-61","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券公司融资融券业务管理办法》，投资者对证券发行人的权利包括（）。","options":["请求分配投资收益等因持有证券而产生的权利","请求召开证券持有人会议","参加证券持有人会议","配售股份的认购"],"answer":"ABCD","explain":"证券发行人的权利，是指请求召开证券持有人会议（B 选项符合题意）、参加证券持有人会议（C 选项符合题意）、提案、表决、配售股份的认购（D 选项符合题意）、请求分配投资收益等因持有证券而产生的权利（A 选项符合题意）。故本题选ABCD 选项。"},{"id":"t300-law-62","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券公司信息隔离墙制度指引》，证券公司应当采取保密措施，防止敏感信息的不当流动和使用，下列措施正确的有（）。","options":["建立内幕信息知情人管理制度","加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施，设备的管理","与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密","对可能知悉敏感信息的工作人员的所有电子邮件、即时通信信息和其他通信信息进行监测"],"answer":"ABC","explain":"34证券公司应当采取保密措施，防止敏感信息的不当流动和使用，包括但不限于：（1）与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密（ C 选项正确）：（2）加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备的管理，保障敏感信息安全（B 选项正确）：（3）对可能知悉敏感信息的工作人员使用公司的信息系统或配发的设备形成的电子邮件、即时通信信息和其他通信信息进行监测（D 选项错误，并非\"所有电子邮件\"）：（4）建立内幕信息知情人管理制度（A 选项正确）。故本题选ABC 选项。"},{"id":"t300-law-63","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券公司信用风险管理指引》，证券公司应当建立常态化的信用风险压力测试机制，并根据（）在压力测试中充分考虑信用风险因素。","options":["市场变化情况","业务变化情况","风险水平情况","信息治理情况"],"answer":"ABC","explain":"证券公司应当根据全面风险管理要求，建立常态化的信用风险压力测试机制，并根据市场变化（A 选项正确）、业务变化（B 选项正确）和风险水平情况（C 选项正确），在压力测试中充分考虑信用风险因素。D 选项错误，信息治理是风险管理和内控的基础性工作，虽然良好的信息治理有助于压力测试数据的准确性，但它本身不是启动或调整压力测试的直接条件。故本题选ABC 选项。"},{"id":"t300-law-64","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券经纪人管理暂行规定》，证券经纪人不得有的行为是（）。","options":["替客户办理账户开立、注销、转移35","与客户约定分享投资收益","向客户传递由证券公司统一提供的证券类金融产品宣传推介材料及有关信息","为客户之间的融资提供中介、担保或者其他便利"],"answer":"ABD","explain":"证券经纪人不得有下列行为：（1）替客户办理账户开立、注销、转移，证券认购、交易或者资金存取、划转、查询等事宜（A 选项符合题意）：（2）与客户约定分享投资收益，对客户证券买卖的收益或者赔偿证券买卖的损失作出承诺（B选项符合题意）：（3）为客户之间的融资提供中介、担保或者其他便利（D 选项符合题意）：（4）向客户提供非由所服务证券公司统一提供的研究报告及与证券投资有关的信息、证券类金融产品宣传推介材料及有关信息（C 选项不符合题意，由证券公司统一提供属于合规行为）。故本题选ABD 选项。"},{"id":"t300-law-65","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券经纪业务管理办法》，证券公司从事证券经纪业务应当遵守（）的原则。","options":["中小股东利益优先","投资者利益优先","信息披露最大化","公平对待投资者"],"answer":"BD","explain":"证券公司从事证券经纪业务，应当诚实守信，切实维护投资者财产安全，保障投资者信息知情权、公平交易权等合法权益。证券公司应当遵守投资者利益优先和公平对待投资者的原则（ B、D 选项正确），防范公司与投资者之间、不同投资者之间的利益冲突。故本题选BD 选项。36"},{"id":"t300-law-66","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券经营机构及其工作人员廉洁从业实施细则》，下列属于证券经纪业务展业禁止性行为的有（）。","options":["以公允价格为利益关系人配售债券或者约定回购债券","委托不具备资质的人员或者机构招揽客户，并输送不正当利益","通过返还佣金或者其他利益、违规给予部分客户特殊优待等方式，输送或者谋取不正当利益","以所在机构名义或者以所在机构员工身份，销售未经公司核准销售的金融产品"],"answer":"BCD","explain":"根据《细则》，证券经营机构及其工作人员在证券经纪业务及其他销售产品或者提供服务过程中，不得通过以下方式输送或者谋取不正当利益：（1）直接或者变相向客户返还佣金、赠送礼品礼券或者提供其他非证券业务性质的服务，违规给予部分客户特殊优待（C 选项符合题意）：（2）委托不具备资质的人员或者机构招揽客户，并输送不正当利益（B 选项符合题意）：（3）以所在机构名义或者以所在机构员工身份，销售未经公司核准销售的金融产品（ D 选项符合题意）。故本题选BCD 选项。【温馨提示】根据《细则》，证券经营机构及其工作人员在证券经纪业务及其他销售产品或者提供服务过程中，不得通过以下方式输送或者谋取不正当利益：（1）协助客户通过提供虚假个人信息、伪造资料、代持等方式，向不满足适当性要求及合格投资者要求的客户销售产品或者提供服务：（2）直接或者变相向客户返还佣金、赠送礼品礼券或者提供其他非证券业务性质的服务，违规给予部分客户特殊优待：（3）安排向特定客户销售显著偏离公允价格的理财产品等交易：（4）违规向其他个人或者机构泄露客户资料、账户信息、交易情况等：（5）委托不具备资质的人员或者机构招揽客户，并输送不正当利益：（6）以所在机构名义或者以所在机构员工身份，销售未经公司核准销售的金融产品：37（7）误导、诱导客户进行不必要的交易：（8）私下接受客户委托从事证券投资：（9）向客户违规承诺投资收益或者承担投资损失：（10）其他输送或者谋取不正当利益的行为。"},{"id":"t300-law-67","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券期货经营机构私募资产管理计划运作管理规定》有关规定，下列证券公司的做法，错误的有（）。","options":["甲证券公司通过其管理的分级资产管理计划资产为该分级资产管理计划劣后级投资者提供融资","乙证券公司通过其管理的分级资产管理计划资产为该分级资产管理计划劣后级投资者的控股股东提供融资","丁证券公司未事先取得投资者同意，将其管理的资产管理计划资产投资于本公司控股股东发行的证券","丙证券公司未事先取得投资者同意，将其管理的资产管理计划资产投资于本公司发行的证券"],"answer":"ABCD","explain":"证券公司将资产管理计划资产投资于本机构、托管人及其控股股东、实际控制人或者其他关联方发行的证券或者承销期内承销的证券，应当建立健全内部审批机制和评估机制，并应当遵循投资者利益优先原则，事先取得投资者的同意，事后告知投资者和托管人，并采取切实有效措施，防范利益冲突，保护投资者合法权益（C、D 选项错误）。除上述情形外，证券公司不得将其管理的资产管理计划资产，直接或者通过投资其他资产管理计划等间接形式，为本机构、托管人及前述机构的控股股东、实际控制人或者其他关联方提供或者变相提供融资（A、B 选项错误）。故本题选ABCD 选项。"},{"id":"t300-law-68","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券期货投资者适当性管理办法》，符合以下（）条件的可以被认定为专业投资者。","options":["金融机构的高级管理人员","有2 年以上证券、基金、期货、黄金、外汇等投资经历38","最近1 年末净资产不低于2000 万元","最近1 年末金融资产不低于1000 万元"],"answer":"ABCD","explain":"同时符合下列条件的法人或者其他组织：（1）最近1 年末净资产不低于2000 万元（C 选项正确）：（2）最近1 年末金融资产不低于1000 万元（D 选项正确）：（3）具有2 年以上证券、基金、期货、黄金、外汇等投资经历（B 选项正确）。同时符合下列条件的自然人：（1）金融资产不低于500 万元，或者最近 3 年个人年均收入不低于50 万元：（2）具有 2 年以上证券、基金、期货、黄金、外汇等投资经历，或者具有 2 年以上金融产品设计、投资、风险管理及相关工作经历，或者属于第一类专业投资者中的规定的金融机构的高级管理人员（A 选项正确）、获得职业资格认证的从事金融相关业务的注册会计师和律师。故本题选ABCD 选项。"},{"id":"t300-law-69","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券投资顾问业务暂行规定》，证券公司及证券投资咨询机构从事证券投资顾问业务，应当遵守的基本原则包括（）。","options":["守法合规","独立审慎","诚实信用","忠实公司利益"],"answer":"AC","explain":"证券公司、证券投资咨询机构从事证券投资顾问业务，应当遵守的基本原则包括：（1）守法合规（A 选项符合题意）：（2）诚实信用（C 选项符合题意）：（3）忠实客户利益（D 选项不符合题意，并非公司利益）。39B 选项不符合题意，规定第十七条提到证券公司若研究能力不足，可向其他机构购买研究报告，独立审慎更多是关于业务操作而非基本原则。故本题选AC 选项。"},{"id":"t300-law-70","subject":"law","source":"9月300题 LC","type":"多选","q":"根据《证券行业执业声誉信息管理办法》，诚信信息中的违法失信信息包括（）。","options":["立案时间","违法失信类型","作出单位","违法失信名称"],"answer":"BCD","explain":"违法失信信息包括违法失信名称（D 选项符合题意）、作出单位（C 选项符合题意）、作出时间、违法失信类型（B 选项符合题意）等。A 选项不符合题意，\"立案时间\"不是诚信信息中的违法失信信息。故本题选BCD 选项。"},{"id":"t300-law-71","subject":"law","source":"9月300题 LC","type":"多选","q":"根据资产支持证券信息披露的相关规定，发生可能对资产支持证券投资价值有实质性影响的重大事件，管理人应当及时向资产支持证券合格投资者披露，披露中应当说明（）。","options":["该事件的起因","该事件目前的状态","该事件可能产生的法律后果","该事件发生后管理人对资产支持证券价格的预测"],"answer":"ABC","explain":"发生可能对资产支持证券投资价值或价格有实质性影响的重大事件，管理人应当及时将有关该重大事件的情况向资产支持证券合格投资者披露，说明事件的起因（A 选项正确）、目前的状态（B 选项正确）和可能产生的法律后果（C 选项正确），并向证券交易场所、中国证券投资基金业协会报告，同时抄送对管理人有辖区监管权的中国证监会派出机构。40D 选项错误，不得预测证券价格。故本题选ABC 选项。"},{"id":"t300-law-72","subject":"law","source":"9月300题 LC","type":"多选","q":"公开发行公司债券，应当符合的法定条件有（）。","options":["具备健全且运行良好的组织机构","最近3 年平均可分配利润足以支付公司债券 1 年的利息","债券利率不得超过国债利息的两倍","债券累计余额不得超过公司净资产的40%"],"answer":"AB","explain":"公开发行公司债券，应当符合下列条件：（1）具备健全且运行良好的组织机构（A 选项符合题意）：（2）最近3 年平均可分配利润足以支付公司债券 1 年的利息（B 选项符合题意）：（3）国务院规定的其他条件。故本题选AB 选项。"},{"id":"t300-law-73","subject":"law","source":"9月300题 LC","type":"多选","q":"公司对公开发行股票所募集资金，以下说法正确的是（）。","options":["必须按照招股说明书或者其他公开发行募集文件所列资金用途使用，不得擅自改变用途","改变资金用途，必须经股东会作出决议","改变资金用途，必须经董事会作出决议","擅自改变用途，未作纠正的不得公开发行新股"],"answer":"ABD","explain":"公司对公开发行股票所募集资金，必须按照招股说明书或者其他公开发行募集文件所列资金用途使用（A 选项正确）：改变资金用途，必须经股东会作出决议（B 选项正确、C 选项错误）。擅自改变用途、未作纠正的，或者未经股东会认可的，不得公开发行新股（D 选项正确）。故本题选ABD 选项。41"},{"id":"t300-law-74","subject":"law","source":"9月300题 LC","type":"多选","q":"公司公积金可用于的场景有（）。","options":["扩大公司生产经营","弥补公司亏损","转增公司股本","缴纳行政罚款"],"answer":"ABC","explain":"公司的公积金用于弥补公司的亏损（B 选项正确）、扩大公司生产经营（A 选项正确）或者转为增加公司注册资本（C 选项正确）。公积金弥补公司亏损，应当先使用任意公积金和法定公积金：仍不能弥补的，可以按照规定使用资本公积金。D 选项错误，行政罚款属于公司经营过程中的法定支出或损失，应当计入当期损益（营业外支出），不得使用公积金支付。公积金是所有者权益的组成部分，用于资本积累和风险缓冲，而非日常经营支出或罚款。故本题选ABC 选项。"},{"id":"t300-law-75","subject":"law","source":"9月300题 LC","type":"多选","q":"股份有限公司不得收购本公司股份。但是，有下列（）情形的，可以收购。","options":["减少公司注册资本","与持有本公司股份的其他公司合并","将股份用于员工持股计划或者股权激励","股东因对股东会作出的公司合并决议持异议的，要求公司收购其股份"],"answer":"ABCD","explain":"股份有限公司不得收购本公司股份。但是，有下列情形之一的除外：（1）减少公司注册资本（A 选项正确）：（2）与持有本公司股份的其他公司合并（B 选项正确）：（3）将股份用于员工持股计划或者股权激励（C 选项正确）：（4）股东因对股东会作出的公司合并、分立决议持异议，要求公司收购其股份（ D 选项正确）：42（5）将股份用于转换公司发行的可转换为股票的公司债券：（6）上市公司为维护公司价值及股东权益所必需。故本题选ABCD 选项。"},{"id":"t300-law-76","subject":"law","source":"9月300题 LC","type":"多选","q":"股份有限公司的设立方式有（）。","options":["发起设立","募集设立","协议设立","批准设立"],"answer":"AB","explain":"A、B 选项正确，股份有限公司的设立，可以采取发起设立或者募集设立的方式。故本题选AB 选项。"},{"id":"t300-law-77","subject":"law","source":"9月300题 LC","type":"多选","q":"关于操纵证券期货市场的刑事责任，下列说法正确的有（）。","options":["本罪的主体是一般主体，凡达到刑事责任年龄并具有刑事责任能力的自然人均可成为本罪主体","本罪的主观方面为故意","本罪侵害了国家证券、期货管理制度和投资者的合法权益","本罪的主体为一般主体，单位不能成为本罪的犯罪主体"],"answer":"ABC","explain":"操作证券、期货市场罪的主体为一般主体。凡达到刑事责任年龄并且具有刑事责任能力的自然人均可成为本罪主体（A 选项正确）：单位亦能构成本罪（D 选项错误）：该罪的主观方面由故意构成（B 选项正确）：该罪的客体是侵犯国家证券、期货管理制度和投资者合法权益（C 选项正确），该罪的客观方面表现为利用其资金、信息等优势或者滥用职权操纵市场、制造市场假象，影响证券、期货交易价格或者证券、期货交易量，情节严重的行为。43故本题选ABC 选项。"},{"id":"t300-law-78","subject":"law","source":"9月300题 LC","type":"多选","q":"关于股份有限公司的股票交易，依据《证券法》，以下属于内幕信息知情人的有（）。","options":["赵某，股份有限公司的董事","钱某，持有公司3％股份的股东","孙某，证监会工作人员，对公司股票的发行、交易进行管理","李某，股份有限公司会计，可获取少量内幕信息"],"answer":"ACD","explain":"证券交易内幕信息的知情人包括：（1）发行人及其董事、监事、高级管理人员（A 选项符合题意）：（2）持有公司 5%以上股份的股东及其董事、监事、高级管理人员，公司的实际控制人及其董事、监事、高级管理人员（B 选项不符合题意）：（3）由于所任公司职务或者因与公司业务往来可以获取公司有关内幕信息的人员（ D 选项符合题意）：（4）因法定职责对证券的发行、交易或者对上市公司及其收购、重大资产交易进行管理可以获取内幕信息的有关主管部门、监管机构的工作人员（C 选项符合题意）。故本题选ACD 选项。【温馨提示】证券交易内幕信息的知情人，还包括：（1）发行人控股或者实际控制的公司及其董事、监事、高级管理人员：（2）上市公司收购人或者重大资产交易方及其控股股东、实际控制人、董事、监事和高级管理人员：（3）因职务、工作可以获取内幕信息的证券交易场所、证券公司、证券登记结算机构、证券服务机构的有关人员：（4）因职责、工作可以获取内幕信息的证券监督管理机构工作人员：（5）国务院证券监督管理机构规定的可以获取内幕信息的其他人员。44"},{"id":"t300-law-79","subject":"law","source":"9月300题 LC","type":"多选","q":"关于合伙企业，下列说法正确的是（）。","options":["有限合伙人转变为普通合伙人，对其在有限合伙人期间合伙企业发生的债务承担无限连带责任","有限合伙人转变为普通合伙人，对其在有限合伙人期间合伙企业发生的债务承担有限责任","普通合伙人转变为有限合伙人，对其在普通合伙人期间合伙企业发生的债务承担无限连带责任","普通合伙人转变为有限合伙人，对其在普通合伙人期间合伙企业发生的债务承担有限责任"],"answer":"AC","explain":"A 选项正确、B 选项错误，有限合伙人转变为普通合伙人的，对其作为有限合伙人期间有限合伙企业发生的债务承担无限连带责任。C 选项正确、D 选项错误，普通合伙人转变为有限合伙人的，对其作为普通合伙人期间合伙企业发生的债务承担无限连带责任。故本题选AC 选项。"},{"id":"t300-law-80","subject":"law","source":"9月300题 LC","type":"判断","q":"不符合地方政府性债务管理有关规定或者新增地方政府性债务的基础资产应当被列入资产证券化业务基础资产负面清单。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。资产证券化基础资产负面清单包括：不符合地方政府性债务管理有关规定或者新增地方政府性债务的基础资产。【温馨提示】资产证券化基础资产负面清单还包括：45（1）被有权部门认定的失信被执行人、失信生产经营单位、其他失信单位作为重要现金流提供方的基础资产。重要现金流提供方、重要子公司存在上述失信情形的，视同重要现金流提供方存在相关情形。（2）产生现金流的能力具有较大不确定性的资产，如矿产资源开采收益权、土地出让收益权、电影票款以及不具有垄断性和排他性的入园凭证等。（3）因空置、在建等原因不能产生稳定现金流的不动产、不动产租金债权或者相关收益权。（4）不能直接产生现金流、仅依托处置资产才能产生现金流的基础资产，如提单、仓单、产权证书等具有物权属性的权利凭证。（5）法律界定及业务形态属于不同类型且缺乏相关性的资产组合，如基础资产中包含企业应收账款、高速公路收费权等两种或者两种以上不同类型资产。（6）违反相关法律法规或者政策规定的资产。（7）以上述资产作为底层资产或者现金流来源的基础资产。底层资产，是指根据穿透原则在专项计划中作为专项计划现金流最终偿付来源的资产。"},{"id":"t300-law-81","subject":"law","source":"9月300题 LC","type":"判断","q":"操作风险一般不包括战略风险和法律风险。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。操作风险是指由不完善或有问题的内部程序、人员、信息技术系统，以及外部事件造成损失的风险。一般包括法律风险，但不包括战略风险和声誉风险。"},{"id":"t300-law-82","subject":"law","source":"9月300题 LC","type":"判断","q":"除证券保荐人离职，否则不能更换证券保荐人。（）","options":["正确","错误"],"answer":"B","explain":"46本题说法错误。证券发行后，保荐机构不得更换保荐代表人，但因保荐代表人离职或者不符合保荐代表人要求的，应当更换保荐代表人。"},{"id":"t300-law-83","subject":"law","source":"9月300题 LC","type":"判断","q":"从业人员可以对证券价格涨跌做出确定性预判。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司及其从业人员向客户提供投资建议，不得对证券价格的涨跌或者市场走势作出确定性的判断。"},{"id":"t300-law-84","subject":"law","source":"9月300题 LC","type":"判断","q":"担任非公开募集基金的基金管理人要向中国基金业协会登记。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。担任非公开募集基金的基金管理人，应当按照中国基金业协会的规定向中国基金业协会申请登记手续，报送基本情况。"},{"id":"t300-law-85","subject":"law","source":"9月300题 LC","type":"判断","q":"当公司利益和客户利益产生冲突时，应当优先维护客户利益。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。47当经营机构及其工作人员的利益与投资者的利益发生冲突时，应当优先保障投资者的合法权益。"},{"id":"t300-law-86","subject":"law","source":"9月300题 LC","type":"判断","q":"非公开发行只能在证券交易所、国务院批准的其他全国性证券交易场所。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。非公开发行的证券，可以在证券交易所、国务院批准的其他全国性证券交易场所、按照国务院规定设立的区域性股权市场转让（并非只能）。"},{"id":"t300-law-87","subject":"law","source":"9月300题 LC","type":"判断","q":"刚性兑付的存在，使金融市场不是完全按照市场机制在运作。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。\"刚性兑付\"指的是在理财产品到期后，即使产品本身投资亏损，金融机构也会按合同约定的收益率或本金进行兑付的行为。这种安排从根本上违背了金融市场的核心运行逻辑。"},{"id":"t300-law-88","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《公司法》，有限责任公司必须设立股东会、董事会、监事会，这是企业法人治理结构的重要举措。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。我国《公司法》原则上要求有限责任公司需建立股东会、董事会和监事会。对于股东人数较少或者规模较小的有限责任公司，可适用《公司法》中的例外规定。即：48规模较小或者股东人数较少的有限责任公司，可以不设董事会，设 1 名董事，行使《公司法》规定的董事会的职权。该董事可以兼任公司经理。规模较小或者股东人数较少的有限责任公司，可以不设监事会，设 1 名监事，行使本法规定的监事会的职权：经全体股东一致同意，也可以不设监事。"},{"id":"t300-law-89","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《公司法》，子公司不具有法人资格，其民事责任由公司承担。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。子公司具有法人资格，依法独立承担民事责任。分公司不具有法人资格，其民事责任由公司承担。"},{"id":"t300-law-90","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《期货和衍生品法》，期货交易实行当日无负债结算制度。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。期货交易实行当日无负债结算制度。在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算：结算参与人应当根据期货结算机构的结算结果对交易者进行结算。"},{"id":"t300-law-91","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券法》，在收购要约确定的承诺期限内，收购人不得撤销其收购要约。（）","options":["正确","错误"],"answer":"A","explain":"49本题说法正确。在收购要约确定的承诺期限内，收购人不得撤销其收购要约。收购人需要变更收购要约的，应当及时公告。"},{"id":"t300-law-92","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券法》，证券公司可以将其自营账户借给他人使用。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。将自营账户借给他人使用，属于证券自营业务其他禁止的行为。【温馨提示】证券自营业务其他禁止的行为，包括：（1）假借他人名义或者个人名义进行自营业务：（2）违反规定委托他人代为买卖证券：（3）违反规定购买本证券公司控股股东或者与本证券公司有其他重大利害关系的发行人发行的证券：（4）将自营账户借给他人使用：（5）将自营业务与经纪业务混合操作：（6）法律、行政法规或中国证监会禁止的其他行为。"},{"id":"t300-law-93","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券公司及基金管理公司子公司资产证券化业务管理规定》，同一资产支持专项计划发行的资产支持证券可以划分为不同种类，同一种类的资产支持证券，享有同等权益，承担同等风险。（）","options":["正确","错误"],"answer":"A","explain":"50本题说法正确。同一专项计划发行的资产支持证券可以划分为不同种类。同一种类的资产支持证券，享有同等权益，承担同等风险。"},{"id":"t300-law-94","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券公司监督管理条例》，客户的交易结算资金、证券资产管理客户的委托资产属于客户，应当与证券公司、指定商业银行、资产托管机构的自有资产相互独立、分别管理。非因客户本身的债务或者法律规定的其他情形，任何单位或者个人不得对客户的交易结算资金、委托资产申请查封、冻结或者强制执行。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。根据《证券公司监督管理条例》第五十九条的规定，客户的交易结算资金、证券资产管理客户的委托资产属于客户，应当与证券公司、指定商业银行、资产托管机构的自有资产相互独立、分别管理。非因客户本身的债务或者法律规定的其他情形，任何单位或者个人不得对客户的交易结算资金、委托资产申请查封、冻结、扣划或者强制执行。"},{"id":"t300-law-95","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券公司监督管理条例》有关规定，净资产低于实收资本 50%的公司，不得成为持有证券公司5%以上股权的股东。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。净资产低于实收资本的 50%，或者或有负债达到净资产的 50%，不得成为持有证券公司 5%以上股权的股东、实际控制人。"},{"id":"t300-law-96","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券公司融资融券业务管理办法》，证券公司向客户融资、融券，应当向客户收取51一定比例的保证金，保证金除现金形式外还可以证券充抵。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司向客户融资、融券，应当向客户收取一定比例的保证金。保证金除现金形式外还可以证券充抵。"},{"id":"t300-law-97","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券基金经营机构债券投资交易业务内控指引》，参与债券投资交易的人员薪酬与激励合计超过人民币 100 万元的，超过部分应当按照等分原则递延发放，递延周期不少于 2 年。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司应加强债券交易人员执业资格、权限公示及薪酬递延管理。债券交易人员薪酬与激励合计超过人民币 100 万元的，超过部分应按照等分原则递延发放，周期不少于2 年。"},{"id":"t300-law-98","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券经营机构及其工作人员廉洁从业实施细则》自律管理要求，证券经营机构从业人员可以向正在洽谈的潜在客户提供有价证券、协助交易等购券便利。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。52根据《廉洁规定》及《细则》，证券经营机构及其工作人员在开展证券相关业务活动中，不得谋取不正当利益或者向公职人员、客户、正在洽谈的潜在客户及其他利益关系人输送不正当利益，不得干扰或者唆使、协助他人干扰证券监督管理或者自律管理工作。"},{"id":"t300-law-99","subject":"law","source":"9月300题 LC","type":"判断","q":"根据《证券投资基金法》，采用封闭式运作方式的基金，是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。封闭式基金是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金：开放式基金是指基金份额总额不固定，基金份额可以在基金合同约定的时间和场所申购或者赎回的基金。"},{"id":"t300-law-100","subject":"law","source":"9月300题 LC","type":"判断","q":"根据洗钱和恐怖融资客户风险等级划分的基本要求，对于首次建立业务关系的客户，无论其风险等级高低，证券公司在初次确定其风险等级后的三年内至少应进行一次复核。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。对于首次建立业务关系的客户，无论其风险等级高低，证券公司在初次确定其风险等级后的 3年内至少应进行一次复核。"},{"id":"t300-law-101","subject":"law","source":"9月300题 LC","type":"判断","q":"根据证券公司风险管理条例，证券公司违规挪用客户资金不能弥补，情节严重的，可以由国务院证券监督管理机构接管。（）","options":["正确53","错误"],"answer":"A","explain":"本题说法正确。证券公司有下列情形之一的，国务院证券监督管理机构可以将其证券经纪等涉及客户的业务进行托管：情节严重的，可以对该证券公司进行接管：（1）治理混乱、管理失控：（2）挪用客户资产并且不能自行弥补：（3）在证券交易结算中多次发生交收违约或者交收违约数额较大：（4）风险控制指标不符合规定，发生重大财务危机：（5）其他可能影响证券公司持续经营的情形。"},{"id":"t300-law-102","subject":"law","source":"9月300题 LC","type":"判断","q":"公开募集基金的基金管理人，享有参与分配清算后的剩余基金财产的权利。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。参与分配清算后的剩余基金财产的权利属于基金份额持有人（并非\"基金管理人\"）。【温馨提示】基金份额持有人的权利：（1）分享基金财产收益。（2）参与分配清算后的剩余基金财产。（3）依法转让或者申请赎回其持有的基金份额。（4）按照规定要求召开基金份额持有人大会或者召集基金份额持有人大会。（5）对基金份额持有人大会审议事项行使表决权。（6）对基金管理人、基金托管人、基金服务机构损害其合法权益的行为依法提起诉讼。54（7）公开募集基金的基金份额持有人有权查阅或者复制公开披露的基金信息资料：非公开募集基金的基金份额持有人有权对涉及自身利益的情况，查阅基金的财务会计账簿等财务资料。"},{"id":"t300-law-103","subject":"law","source":"9月300题 LC","type":"判断","q":"股票期权交易实行当日无负债结算制度。证券登记结算机构应当在次日及时将结算结果通知结算参与人。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。股票期权交易实行当日无负债结算制度。证券登记结算机构应当在当日及时将结算结果通知结算参与人（并非次日），结算参与人据此对投资者进行结算，并应当将结算结果按照与投资者约定的方式及时通知投资者。"},{"id":"t300-law-104","subject":"law","source":"9月300题 LC","type":"判断","q":"合规负责人应当对证券公司内部规章制度、重大决策、新产品和新业务方案等进行合规审查，并出具书面合规审查意见。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。合规负责人应当对证券公司内部规章制度、重大决策、新产品和新业务方案等进行合规审查，并出具书面合规审查意见。"},{"id":"t300-law-105","subject":"law","source":"9月300题 LC","type":"判断","q":"基金管理人、基金托管人因基金财产的管理、运用或者其他情形而取得的财产和收益，归入基金财产。（）","options":["正确","错误"],"answer":"A","explain":"55本题说法正确。基金管理人、基金托管人因基金财产的管理、运用或者其他情形而取得的财产和收益，归入基金财产。"},{"id":"t300-law-106","subject":"law","source":"9月300题 LC","type":"判断","q":"经营机构对普通投资者在信息告知、风险警示、收益保证、适当性匹配方面享有特殊保护。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。经营机构不得以任何方式承诺或者保证投资收益。"},{"id":"t300-law-107","subject":"law","source":"9月300题 LC","type":"判断","q":"经营机构向普通投资者销售高风险产品或者提供相关服务，应当履行特别的注意义务。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。经营机构向普通投资者销售高风险产品或者提供相关服务，应当履行特别的注意义务，包括制定专门的工作程序，追加了解相关信息，告知特别的风险点，给予普通投资者更多的考虑时间，或者增加回访频次等。"},{"id":"t300-law-108","subject":"law","source":"9月300题 LC","type":"判断","q":"可充抵保证金的证券在计算保证金金额时应当以证券市值或净值进行折算。（）","options":["正确","错误56"],"answer":"A","explain":"本题说法正确。可充抵保证金的证券，在计算保证金金额时应当以证券市值或净值按相应折算率进行折算。"},{"id":"t300-law-109","subject":"law","source":"9月300题 LC","type":"判断","q":"可以向正在进行沟通的客户输送不正当利益。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据《廉洁规定》及《细则》，证券经营机构及其工作人员在开展证券相关业务活动中，不得谋取不正当利益或者向公职人员、客户、正在洽谈的潜在客户及其他利益关系人输送不正当利益。"},{"id":"t300-law-110","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】有限责任公司，注册资本 1 亿元人民币，其中甲企业以现金出资 7000 万元：乙企\n业以土地使用权出资，该土地根据乙企业提供的取得时的会计凭证和相关材料确定价值 2000\n万元：丙企业以专利技术出资，该专利技术经专业机构评估确认价值 900 万元：丁企业以劳务\n出资 100 万元。四方达成约定公司董事会由 7 人组成，由股东会选举产生，公司监事会由 5 人\n组成，4 名股东代表监事由四家股东各推荐一人担任，1 名职工监事，由董事会任命。 \n请根据上述背景信息回答以下问题。\n\n【问题】甲、乙、丙、丁四家企业的出资方式合法的是（）。","options":["甲、乙、丁","甲、丙","甲、丙、丁57","甲、乙、丙、丁"],"answer":"B","explain":"甲、丙出资合法，乙、丁出资不合法。有限责任公司股东可以用货币出资（甲以现金出资，合法），也可以用实物、知识产权（丙以专利技术出资，合法）、土地使用权等可以用货币估价并可以依法转让的非货币财产作价出资：但是法律、行政法规规定不得作为出资的财产除外（不得以劳务出资，丁出资方式不合法）。对作为出资的非货币财产应当评估作价，核实财产，不得高估或者低估作价。法律、行政法规对评估作价有规定的，从其规定。乙的出资，未经过评估作价，出资方式不合法。综上所述，B 选项正确。故本题选B 选项。"},{"id":"t300-law-111","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】有限责任公司，注册资本 1 亿元人民币，其中甲企业以现金出资 7000 万元：乙企\n业以土地使用权出资，该土地根据乙企业提供的取得时的会计凭证和相关材料确定价值 2000\n万元：丙企业以专利技术出资，该专利技术经专业机构评估确认价值 900 万元：丁企业以劳务\n出资 100 万元。四方达成约定公司董事会由 7 人组成，由股东会选举产生，公司监事会由 5 人\n组成，4 名股东代表监事由四家股东各推荐一人担任，1 名职工监事，由董事会任命。 \n请根据上述背景信息回答以下问题。\n\n【问题】根据《公司法》，下列关于案例中四方股东就戊公司董事会和监事会事项作出约定的合法性判断，正确的有（）。","options":["监事会职工监事的产生方式符合《公司法》要求","董事会和监事会人数符合《公司法》要求","监事会中职工监事人数不符合《公司法》要求","全体董事由股东会选举产生的做法符合《公司法》要求"],"answer":"BCD","explain":"A 选项错误，监事会中的职工代表由公司职工通过职工代表大会、职工大会或者其他形式民主选举产生（并非\"由董事会任命\"）。B 选项正确，有限责任公司设监事会，其成员为 3 人以上（5 名，符合要求）。有限责任公司设董事会，其成员为3 人以上（7 人，符合要求）。C 选项正确，监事会成员应当包括股东代表和适当比例的公司职工代表，其中职工代表的比例"},{"id":"t300-law-112","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】王某在某证券营业部任职经纪人期间，向客户传递不是由证券公司统一提供的证\n券类金融产品宣传推介材料及有关信息：替客户办理证券认购、交易，并与客户约定按照一定\n比例分享证券交易产生的收益。不具有证券投资咨询执业资格，违规向客户推荐股票，被出具\n行政监管措施。 \n请根据上述背景信息回答以下问题。\n\n【问题】证券经纪人王某的禁止行为包括（）。","options":["替客户办理证券认购、交易或者资金存取、划转、查询等事宜","保守客户秘密","与客户约定分享投资收益","向客户传递非由证券公司统一提供的证券类金融产品宣传推介材料及有关信息"],"answer":"ACD","explain":"根据《证券经纪人管理暂行规定》，证券经纪人不得有下列行为：①替客户办理账户开立、注销、转移，证券认购、交易或者资金存取、划转、查询等事宜（ A选项符合题意）：②与客户约定分享投资收益（C 选项符合题意），对客户证券买卖的收益或者赔偿证券买卖的损失作出承诺：③向客户提供非由所服务证券公司统一提供的研究报告及与证券投资有关的信息、证券类金融产品宣传推介材料及有关信息（D 选项符合题意）。故本题选ACD 选项。59【温馨提示】证券经纪人不得有的行为，还包括：①提供、传播虚假或者误导客户的信息，或者诱使客户进行不必要的证券买卖：②采取贬低竞争对手、进入竞争对手营业场所劝导客户等不正当手段招揽客户：③泄露客户的商业秘密或者个人隐私：④为客户提供非法的服务场所或者交易设施，或者通过互联网络、新闻媒体从事客户招揽和客户服务等活动：⑤委托他人代其从事客户招揽和客户服务等活动：⑥损害客户合法权益或者扰乱市场秩序的其他行为。"},{"id":"t300-law-113","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】王某在某证券营业部任职经纪人期间，向客户传递不是由证券公司统一提供的证\n券类金融产品宣传推介材料及有关信息：替客户办理证券认购、交易，并与客户约定按照一定\n比例分享证券交易产生的收益。不具有证券投资咨询执业资格，违规向客户推荐股票，被出具\n行政监管措施。 \n请根据上述背景信息回答以下问题。\n\n【问题】证券公司及其从业人员违反下列《证券经纪业务管理办法》中的规定时，应依法应予处罚的，按照相关法律法规的规定进行处罚的情形有（）。","options":["严重损害投资者合法权益","严重损害证券行业形象","业务管控存在重大缺陷","严重危及市场正常秩序"],"answer":"ABCD","explain":"证券公司及其从业人员违反《证券经纪业务管理办法》规定，依法应予处罚的，按照相关法律法规的规定进行处罚。相关法律法规没有规定且存在以下情形之一的，给予警告，可以并处国务院规定的一定数额的罚款。①业务管控存在重大缺陷（C 选项正确）：②严重损害投资者合法权益（A 选项正确）：③严重危及市场正常秩序（D 选项正确）：60④严重损害证券行业形象（B 选项正确）：⑤造成恶劣社会影响。故本题选ABCD 选项。"},{"id":"t300-law-114","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】甲上市公司曾于 2 年前发行了公司债券，募集资金用途为用于新上一条生产线项\n目，债券发行后经债券持有人会议作出决议，取消原募集资金项目，立项新项目。目前甲公司\n拟再次发行公司债券，并已聘请了证券服务机构和人员，开始推进公开发行公司债券的进程。 \n请根据上述背景信息回答以下问题。\n\n【问题】根据《证券法》，下列关于甲公司本次发行公司债券应符合条件的说法，错误的是（）。","options":["甲公司本次发行公司债券应保证最近3 年平均可分配利润足以支付债券 1 年的利息","甲公司发行债券募集的资金，不得用于弥补亏损和非生产性支出","甲公司改变了上次公开发行公司债券所募资金的用途，本次不得再次公开发行公司债券","如果甲公司上次发行债券出现至今未支付利息的违约情况，本次不得再次公开发行公司债券"],"answer":"C","explain":"A 选项正确，公开发行公司债券应当符合的条件包括：最近 3 年平均可分配利润足以支付公司债券1 年的利息。B 选项正确，公开发行公司债券筹集的资金，不得用于弥补亏损和非生产性支出。C 选项错误，公开发行公司债券筹集的资金，必须按照公司债券募集办法所列资金用途使用：改变资金用途，必须经债券持有人会议作出决议。甲公司改变了上次公开发行公司债券所募资金的用途，但这一改变是经债券持有人会议作出决议后实施的，因此没有触发禁止再次公开发行公司债券的情形。D 选项正确，对已公开发行的公司债券或者其他债务有违约或者延迟支付本息的事实，仍处于继续状态的，不得再次公开发行公司债券。故本题选C 选项。"},{"id":"t300-law-115","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】甲上市公司曾于 2 年前发行了公司债券，募集资金用途为用于新上一条生产线项\n目，债券发行后经债券持有人会议作出决议，取消原募集资金项目，立项新项目。目前甲公司\n拟再次发行公司债券，并已聘请了证券服务机构和人员，开始推进公开发行公司债券的进程。 \n请根据上述背景信息回答以下问题。\n\n【问题】要求 2根据《证券法》，公司申请公开发行公司债券的程序，下列说法正确的有（）。","options":["甲公司不得在公告公开发行募集文件前发行公司债券","中国证监会负责公司债券注册","甲公司报送的公司债券发行申请文件，由为此出具有关文件的证券服务机构保证报送文件的真实、准确、完整","证券交易所负责审核公开发行公司债券申请"],"answer":"ABCD","explain":"A 选项正确，证券发行申请经注册后，发行人应当依照法律、行政法规的规定，在证券公开发行前公告公开发行募集文件。B 选项正确，国务院证券监督管理机构或者国务院授权的部门应当自受理证券发行申请文件之日起3 个月内，依照法定条件和法定程序作出予以注册或不予注册的决定。C 选项正确，为证券发行出具有关文件的证券服务机构和人员，必须严格履行法定职责，保证所出具文件的真实性、准确性和完整性。D 选项正确，按照国务院的规定，证券交易所等可以审核公开发行证券申请，判断发行人是否符合发行条件、信息披露要求，督促发行人完善信息披露内容。故本题选ABCD 选项。"},{"id":"t300-law-116","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】甲上市公司曾于 2 年前发行了公司债券，募集资金用途为用于新上一条生产线项\n目，债券发行后经债券持有人会议作出决议，取消原募集资金项目，立项新项目。目前甲公司\n拟再次发行公司债券，并已聘请了证券服务机构和人员，开始推进公开发行公司债券的进程。 \n请根据上述背景信息回答以下问题。\n\n【问题】证券公司设立集合资产管理计划进行投资，资产管理计划可以直接投资的资产有（）。","options":["所有境外金融产品","商业银行信贷资产","银行存款、同业存单，以及符合《关于规范金融机构资产管理业务的指导意见》规定的标准化债权类资产","上市公司股票、存托凭证，以及中国证监会认可的其他标准化股权类资产"],"answer":"CD","explain":"62证券公司可以依法设立资产管理计划在境内募集资金，投资于中国证监会认可的境外金融产品（A 选项错误，并非所有）。资产管理计划不得直接投资商业银行信贷资产（B 选项错误）。资产管理计划可以投资于以下资产：①银行存款、同业存单，以及符合《关于规范金融机构资产管理业务的指导意见》规定的标准化债权类资产（C 选项正确）：②上市公司股票、存托凭证，以及中国证监会认可的其他标准化股权类资产（D 选项正确）。故本题选CD 选项。【温馨提示】资产管理计划可以投资于以下资产：①银行存款、同业存单，以及符合《关于规范金融机构资产管理业务的指导意见》规定的标准化债权类资产，包括但不限于在证券交易所、银行间市场等国务院同意设立的交易场所交易的可以划分为均等份额、具有合理公允价值和完善流动性机制的债券、中央银行票据、资产支持证券、非金融企业债务融资工具等。②上市公司股票、存托凭证，以及中国证监会认可的其他标准化股权类资产。③在证券期货交易所等依法设立的交易场所集中交易清算的期货及期权合约等标准化期货和衍生品类资产。④公募基金，以及中国证监会认可的比照公募基金管理的资产管理产品。⑤第1 项至第 3 项规定以外的非标准化债权类资产、股权类资产、期货和衍生品类资产。⑥第4 项规定以外的其他受国务院金融监督管理机构监管的机构发行的资产管理产品。⑦中国证监会认可的其他资产。前款第1 项至第 4 项为标准化资产，第 5 项至第 6 项为非标准化资产。"},{"id":"t300-law-117","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】某证券公司推出一款高风险理财产品，部分投资者提出了购买申请，其中投资者\n王某为某商业银行高级管理人员，其提供了名下拥有金融资产 600 万元证明，书面告知经营机\n构选择成为普通投资者：投资人李某之前的风险等级为C3，其提供了最近3 年个人年均收入40\n\n【问题】下列关于王某情况的相关说法，正确的是（）。","options":["王某的情况符合专业投资者要求，即使其书面告知选择成为普通投资者，该证券公司应当将其作为专业投资者对待","王某的情况符合专业投资者要求，其书面告知选择成为普通投资者后，该证券公司应当对其履行相应的适当性义务","王某的情况符合专业投资者要求，其书面告知选择成为普通投资者后，该证券公司有权自主决定是否同意其转化为普通投资者","王某的情况不符合专业投资者要求，应认定为普通投资者，该证券公司应对其履行相应的适当性义务"],"answer":"B","explain":"A 选项错误、B 选项正确，第二类专业投资者可以书面告知经营机构选择成为普通投资者，经营机构应当对其履行相应的适当性义务。C 选项错误，第二类专业投资者在书面告知经营机构后即可成为普通投资者，无需证券公司同意转化。D 选项错误，金融资产不低于 500 万元并且属于金融机构的高级管理人员的，属于第二类专业投资者，王某符合专业投资者的要求。故本题选B 选项。"},{"id":"t300-law-118","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】某证券公司推出一款高风险理财产品，部分投资者提出了购买申请，其中投资者\n王某为某商业银行高级管理人员，其提供了名下拥有金融资产 600 万元证明，书面告知经营机\n构选择成为普通投资者：投资人李某之前的风险等级为C3，其提供了最近3 年个人年均收入40\n\n【问题】下列关于李某情况的相关说法，正确的是（）。64","options":["李某满足普通投资者申请转化为专业投资者条件并提出了转化书面申请，但该证券公司仍应履行必要的审核、提示工作并有权自主决定是否同意转化","李某的风险承受能力等级评估已完成，并且被定级了C3，不得再对其情况进行调整","李某满足普通投资者申请转化为专业投资者条件并提出了转化书面申请，该证券公司应当直接认定其为专业投资者","李某不满足普通投资者申请转化为专业投资者条件，无权提出转化申请"],"answer":"A","explain":"A 选项正确、C 选项错误，普通投资者申请转化为专业投资者亦需要遵守相应的程序。投资者须主动通过书面形式提出申请并确认自主承担可能产生的风险和后果，提供相关证明材料。经营机构应当通过追加了解信息、投资知识测试或模拟交易等方式对投资者情况及证明材料进行审慎评估，确认其是否符合相关要求，说明对不同类别投资者履行适当性义务的差别，警示投资者可能承担的投资风险，并告知审核结果及理由。经营机构有权自主决定是否同意投资者转化为专业投资者。B 选项错误，普通投资者风险承受能力等级评估是一个持续性的工作，经营机构应当定期或在得知投资者信息发生重要变化、可能影响投资者分类时及时对普通投资者风险承受能力等级进行重新评估。D 选项错误，最近3 年个人年均收入不低于30 万元，且具有1 年以上金融产品设计、投资、风险管理及相关工作经历的自然人投资者可以申请转化成为专业投资者，李某满足转化条件。故本题选A 选项。"},{"id":"t300-law-119","subject":"law","source":"9月300题 LC","type":"案例","q":"【资料】某证券公司推出一款高风险理财产品，部分投资者提出了购买申请，其中投资者\n王某为某商业银行高级管理人员，其提供了名下拥有金融资产 600 万元证明，书面告知经营机\n构选择成为普通投资者：投资人李某之前的风险等级为C3，其提供了最近3 年个人年均收入40\n\n【问题】下列关于投资者购买该高风险理财产品的说法，正确的有（）。","options":["李某成为专业投资者后可购买该产品","张某可以购买该理财产品","赵某经业务人员就产品风险等级高于其承受能力的情况进行特别书面风险警示，赵某仍坚持购买，可以向其销售相关产品65","王某在提交书面告知前可以购买该产品"],"answer":"ABD","explain":"A、D 选项正确，专业投资者可购买或接受所有风险等级的产品或服务（王某在提交书面告知前仍属于专业投资者）。B 选项正确，张某在证券公司风险评估中的风险级别为 C5，为该公司普通投资者中风险承受能力最高类别的投资者，可以购买高风险理财产品。C 选项错误，投资人赵某在证券公司风险评估中被划分为C1 级，为该公司风险承受能力最低类别的投资者，对风险承受能力最低类别的投资者，业务人员应当拒绝向其销售或提供高于其风险承受能力的产品或服务。故本题选ABD 选项。"}]},{"id":"t300-bas","subject":"basics","name":"9月300题 · 金融基础","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"t300-bas-0","subject":"basics","source":"9月300题 LC","type":"单选","q":"\"货币供应量↑→股价↑→托宾q↑→投资↑→总产出↑\"，描述的是货币政策（）。","options":["资产价格传导机制","汇率传导机制","信用传导机制","利率传导机制"],"answer":"A","explain":"资产价格传导机制：货币学派的托宾 q 理论与莫迪利安尼的生命周期理论提出的传导机制中，货币政策通过其他相关的资产价格以及真实财富效应作用于整个经济。（1）托宾q理论认为货币政策可以通过股票价值来影响经济活动，q值定义为企业的市场价值与资本重置成本之比。其传导机制可以表示为：货币供应量↑→股价↑→托宾 q↑→投资↑→总产出↑（A选项正确）。（2）财富效应。其传导机制可以表示为：货币供应量 ↑→股价↑→金融资产价值↑→财务困难的可能性↓→耐用消费品和住宅支出↑→总产出↑。故本题选A选项。"},{"id":"t300-bas-1","subject":"basics","source":"9月300题 LC","type":"单选","q":"\"债券通\"是开展我国内地与（）地区债券市场互联互通合作的全新计划，让中国境内与境外投资者通过在该地区建立的基础设施连接，在对方市场买卖债券。","options":["巴黎","纽约","香港","伦敦"],"answer":"C","explain":"2017 年，开通\"债券通\"。是开展中国内地与香港（C 选项正确）地区债券市场互联互通合作的2全新计划，让中国境内与境外投资者通过在香港地区建立的基础设施连接，在对方市场买卖债券。买卖两个市场交易流通债券的机制安排，包括北向通及南向通。故本题选C选项。"},{"id":"t300-bas-2","subject":"basics","source":"9月300题 LC","type":"单选","q":"（）拥有全球最发达的股票市场。","options":["中国","日本","英国","美国"],"answer":"D","explain":"美国（D 选项正确）是当今世界第一大经济体，其金融业也居全球霸主地位。拥有全球最发达的股票市场、最大债券市场、最大衍生品市场和全球第二大外汇市场。故本题选D选项。"},{"id":"t300-bas-3","subject":"basics","source":"9月300题 LC","type":"单选","q":"《证券公司融资融券业务内部控制指引》规定，证券公司应当建立以（）为核心的融资融券业务规模监控和调整机制。","options":["净收入","总资产","净资产","净资本"],"answer":"D","explain":"《证券公司融资融券业务内部控制指引》规定，证券公司应当建立以净资本（D 选项正确）为核心的融资融券业务规模监控和调整机制。证券公司应当建立融资融券业务的集中风险监控系统。故本题选D选项。"},{"id":"t300-bas-4","subject":"basics","source":"9月300题 LC","type":"单选","q":"《证券公司声誉风险管理指引》明确了声誉事件和重大声誉事件的定义，造成以下（）后3果的事件不属于重大声誉事件。","options":["证券行业声誉损害","市场大幅波动","引发部门风险","影响社会经济秩序"],"answer":"C","explain":"声誉事件是指引发证券公司声誉风险的相关行为或事件。重大声誉事件是指造成证券公司重大损失、证券行业声誉损害（A 选项不符合题意）、市场大幅波动（B 选项不符合题意）、引发系统性风险或影响社会经济秩序稳定（D选项不符合题意）的声誉事件。故本题选C选项。"},{"id":"t300-bas-5","subject":"basics","source":"9月300题 LC","type":"单选","q":"标志现代银行制度确立的机构是（）。","options":["美联储","英格兰银行","欧洲央行","中国人民银行"],"answer":"B","explain":"B 选项正确，1694 年，英国成立了世界上第一家股份制商业银行——英格兰银行，标志着英国现代银行制度的确立。故本题选B选项。"},{"id":"t300-bas-6","subject":"basics","source":"9月300题 LC","type":"单选","q":"不属于场内证券交易市场的是（）。","options":["深交所","全国中小企业股份转让系统","区域性股权市场","上交所4"],"answer":"C","explain":"中国股票市场分为场内市场和场外市场，场内市场包括沪深主板市场、科创板市场、创业板市场、北京证券交易所和全国中小企业股份转让系统（新三板），场外市场包括区域性股权市场（C选项符合题意）和柜台市场。故本题选C选项。"},{"id":"t300-bas-7","subject":"basics","source":"9月300题 LC","type":"单选","q":"不属于我国普通国债发行情况的是（）。","options":["发行方式趋于市场化","发行成本越来越高","期限趋于多样化","规模越来越大"],"answer":"B","explain":"我国发行普通国债的总体情况大致如下：（1）规模越来越大（D选项正确）：（2）期限趋于多样化（C选项正确）：（3）发行方式趋于市场化（A选项正确）。故本题选B选项。"},{"id":"t300-bas-8","subject":"basics","source":"9月300题 LC","type":"单选","q":"存托凭证主要在（）的环境下应运而生。","options":["资本本土化","资本市场国际化","投资多元化","机构多样化"],"answer":"B","explain":"B选项正确，存托凭证是为便利跨境投融资，在资本市场国际化背景下产生。5故本题选B选项。"},{"id":"t300-bas-9","subject":"basics","source":"9月300题 LC","type":"单选","q":"对基金机构的监管不包括对（）的监管。","options":["基金管理人","基金投资人","基金服务机构","基金托管人"],"answer":"B","explain":"基金监管机构通过依法行使审批或核准权，依法办理基金备案，对基金管理人（A 选项不符合题意）、基金托管人（D 选项不符合题意）以及其他从事基金活动的服务机构（C 选项不符合题意）进行监督管理，对违法行为进行查处，在基金的运作过程中起着重要的作用。故本题选B选项。"},{"id":"t300-bas-10","subject":"basics","source":"9月300题 LC","type":"单选","q":"负责证券投资基金行业的监管主体是（）。","options":["中国证券投资基金业协会","中国证券业协会","中国证监会","中国人民银行"],"answer":"C","explain":"基金监管机构通过依法行使审批或核准权，依法办理基金备案，对基金管理人、基金托管人以及其他从事基金活动的服务机构进行监督管理，对违法行为进行查处，在基金的运作过程中起着重要的作用。在我国，国务院证券监督管理机构，即中国证监会依法对证券投资基金活动实施监督管理（ C选项正确）。故本题选C选项。"},{"id":"t300-bas-11","subject":"basics","source":"9月300题 LC","type":"单选","q":"根据《证券法》，下列关于证券服务机构法律责任的说法，正确的是（）。6","options":["财务顾问机构为上市公司收购制作的文件有虚假记载给他人造成损失的，无论是否存在过错，应当承担民事赔偿责任","证券分析师为证券发行出具的文件有误导性陈述，因过错给他人造成损失的，应当承担连带赔偿责任","资产评估机构为上交所债券出具的评估报告有重大遗漏，无法证明自己没有过错的，自担连带全部赔偿责任","会计师事务所为证券上市出具的文件有虚假记载，给他人造成损失，但能够证明自己没有过错的，不承担民事赔偿责任"],"answer":"D","explain":"根据《证券法》，证券服务机构为证券的发行、上市、交易等证券业务活动制作、出具审计报告及其他鉴证报告、资产评估报告、财务顾问报告、资信评级报告或者法律意见书等文件，应当勤勉尽责，对所依据的文件资料内容的真实性、准确性、完整性进行核查和验证。其制作、出具的文件有虚假记载、误导性陈述或者重大遗漏，给他人造成损失的，应当与委托人承担连带赔偿责任，但是能够证明自己没有过错的除外（D选项正确、A选项错误）。B选项错误，证券分析师属于个人，并非证券服务机构。C 选项错误，司法实践中是按过错程度承担相应连带责任，故意全额连带，过失仅对自身过错部分担责，并非一律全额连带。故本题选D选项。"},{"id":"t300-bas-12","subject":"basics","source":"9月300题 LC","type":"单选","q":"根据风险定义，下列不涉及风险特征的是（）。","options":["不可预测性","不确定性","损失","波动性"],"answer":"C","explain":"目前，国内外金融理论界对风险的定义或界定主要有以下三类观点：7（1）风险是结果的不确定性，是一种变化（B选项不符合题意）：（2）风险是损失发生的可能性，或可能发生的损失（A选项不符合题意）：（3）风险是结果对期望的偏离，是（收益的）波动性（D选项不符合题意）。C选项符合题意，损失是风险可能导致的结果，而非风险的特征。故本题选C选项。"},{"id":"t300-bas-13","subject":"basics","source":"9月300题 LC","type":"单选","q":"根据风险管理理念，利用风险管理方式对于金融信用风险具有缓释作用的是（）。","options":["业务规模限额","对冲风险交易","风险定价","投资资产配置"],"answer":"B","explain":"信用风险缓释是指商业银行运用信用风险缓释技术，包括抵 /质押品、净额结算、保证与担保和信用衍生工具等方式转移或降低信用风险，其中前3种为传统信用风险缓释工具。B选项正确，对冲风险交易属于利用信用衍生工具进行信用风险缓释。故本题选B选项。"},{"id":"t300-bas-14","subject":"basics","source":"9月300题 LC","type":"单选","q":"根据风险管理组织架构的职责分工，证券公司指定或设立专门部门履行风险管理职责，在（）的直接领导下推动全面风险管理工作，监测、评估、报告公司整体风险水平，并为业务决策提供风险建议，协助、指导和检查各部门、分支机构及子公司的风险管理工作。","options":["监事会","总经理","首席风险官","董事会"],"answer":"C","explain":"证券公司应当指定或者设立专门部门履行风险管理职责，在首席风险官（C 选项正确）的领导8下推动全面风险管理工作，监测、评估、报告公司整体风险水平，并为业务决策提供风险管理建议，协助、指导和检查各部门、分支机构及子公司的风险管理工作。故本题选C选项。"},{"id":"t300-bas-15","subject":"basics","source":"9月300题 LC","type":"单选","q":"根据基金分类标准，80%以上资产投资于股票的基金为（）。","options":["债券基金","货币市场基金","股票基金","混合基金"],"answer":"C","explain":"A 选项不符合题意，债券基金是一种以债券为主要投资对象的证券投资基金。在我国，根据中国证监会对基金类别的分类标准，80%以上的基金资产投资于债券的，为债券基金。B 选项不符合题意，货币市场基金是仅以货币市场工具为投资对象的一种基金，其投资对象期限较短，一般在 1 年以内，包括银行短期存款、政府短期债券、同业存单、公司短期债券等货币市场工具。C 选项符合题意，股票基金是指以股票为主要投资对象的证券投资基金。在我国，根据中国证监会对基金类别的分类标准，80%以上的基金资产投资于股票的，为股票基金。D 选项不符合题意，混合基金是指可以同时投资于股票与债券的基金，该类基金由于资产配置比例不同，分为偏股型基金、偏债型基金、股债平衡型基金、灵活配置型基金等。故本题选C选项。"},{"id":"t300-bas-16","subject":"basics","source":"9月300题 LC","type":"单选","q":"根据商业银行的业务分类，下列属于商业银行资产业务的是（）。","options":["银行承兑汇票","吸收存款","资产托管","贷款业务"],"answer":"D","explain":"9D 选项符合题意，商业银行的资产业务主要包括现金资产、贷款业务、票据贴现、投资业务等。故本题选D选项。"},{"id":"t300-bas-17","subject":"basics","source":"9月300题 LC","type":"单选","q":"公司不以任何资产作担保而发行的债券是（）。","options":["信托公司债券","信用公司债券","保证公司债券","抵押公司债券"],"answer":"B","explain":"B 选项正确，信用公司债券是一种不以公司任何资产作担保而发行的债券，属于无担保证券范畴。故本题选B选项。"},{"id":"t300-bas-18","subject":"basics","source":"9月300题 LC","type":"单选","q":"股利收入由国有资产管理部门监督收缴，依法纳入国有资本经营预算，并根据国家有关规定安排使用的股票类型为（）。","options":["国有股","外资股","法人股","社会公众股"],"answer":"A","explain":"A 选项正确，国有股股利收入由国有资产管理部门监督收缴，依法纳入国有资本经营预算，并根据国家有关规定安排使用。国家股股权可以转让，但转让应符合国家的有关规定。故本题选A选项。"},{"id":"t300-bas-19","subject":"basics","source":"9月300题 LC","type":"单选","q":"股息当年结清、不能累积发放的优先股票称为（）。10","options":["股息率固定优先股票","可回购优先股票","非累积优先股票","累积优先股票"],"answer":"C","explain":"A选项错误，股息率优先股存续期内不作调整的，被称为固定股息率优先股。B 选项错误，可回购优先股是指允许发行公司按发行价加上一定比例的补偿收益回购优先股，公司通常在认为可以用较低股息率发行新的优先股时，就可用此方法回购已发行的优先股股票。C 选项正确，非累积优先股则是指公司不足以支付优先股的全部股息时，对所欠股息部分，优先股股东不能要求公司在以后年度补发。D 选项错误，累积优先股是指公司在某一时期所获盈利不足，导致当年可分配利润不足以支付优先股股息时，则将应付股息累积到次年或以后某一年盈利时，在普通股的股息发放之前，连同本年优先股股息一并发放。故本题选C选项。"},{"id":"t300-bas-20","subject":"basics","source":"9月300题 LC","type":"单选","q":"关于国别风险、战略风险以及系统性风险，下列说法错误的是（）。","options":["加强宏观审慎监管能够降低系统性风险","完善的内部控制和审计可以降低国别风险","系统性风险可以通过多样化分散和降低","战略风险管理包括制定以风险为导向的战略规划"],"answer":"C","explain":"A 选项正确，对系统性风险的管理主要通过加强宏观审慎监管，加强系统重要性机构的监管。宏观审慎监管的主要目的是增强金融体系的稳定性，降低系统性风险，平滑金融体系的顺周期波动和跨市场风险传染，并防范单个金融机构\"大而不能倒\"的风险。B 选项正确，完善的内部控制和审计是国别风险管理体系的基本要素之一。完善的内部控制和审计可以降低国别风险。11C 选项错误，在证券投资中，多样化投资的风险分散策略成为投资者消除非系统性风险的基本策略，而系统性风险无法通过多样化投资分散。D 选项正确，证券公司战略风险的基本做法之一为采取恰当的战略风险管理方法，如制定以风险为导向的战略规划、合理运用经济资本配置工具等。故本题选C选项。"},{"id":"t300-bas-21","subject":"basics","source":"9月300题 LC","type":"单选","q":"关于证券公司债券发行方式的说法，正确的是（）。","options":["只能公开发行","可以申请一次注册，分期发行","只能一次注册，一次发行","只能非公开发行"],"answer":"B","explain":"公司债券可以公开发行，也可以非公开发行。公开发行公司债券，可以申请一次注册，分期发行（B选项正确）。故本题选B选项。"},{"id":"t300-bas-22","subject":"basics","source":"9月300题 LC","type":"单选","q":"国债期货属于（）。","options":["汇率期货","外汇期货","利率期货","股权类期货"],"answer":"C","explain":"C选项正确，以国债期货为主的债券期货是各主要交易所最重要的利率期货品种。故本题选C选项。"},{"id":"t300-bas-23","subject":"basics","source":"9月300题 LC","type":"单选","q":"沪深300指数的成分股数量为（）只。12","options":["300","400","500","600"],"answer":"A","explain":"A 选项正确，沪深 300 指数由沪深 A 股中规模大、流动性好、最具代表性的 300 只股票组成，以综合反映沪深A股市场整体表现。故本题选A选项。"},{"id":"t300-bas-24","subject":"basics","source":"9月300题 LC","type":"单选","q":"基础设施公募REITs采用的运作模式为（）。","options":["开放式","封闭式","每日申赎","场外私募"],"answer":"B","explain":"B 选项正确，基础设施基金采取封闭式运作，不开通申购赎回，只能在二级市场交易，存在流动性不足的风险。故本题选B选项。"},{"id":"t300-bas-25","subject":"basics","source":"9月300题 LC","type":"单选","q":"基金监管对于维护证券市场的良好秩序、提高证券市场效率和（）均具有重大意义。","options":["优化基金投资者结构","保护基金份额持有人利益","保护个人基金投资者的利益","促进基金市场规模稳定健康扩大"],"answer":"B","explain":"13基金监管对于维护证券市场的良好秩序、提高证券市场效率、保护基金份额持有人利益（B 选项正确）均具有重大意义。故本题选B选项。"},{"id":"t300-bas-26","subject":"basics","source":"9月300题 LC","type":"单选","q":"基金投资者可以通过办理（）业务，实现其变更办理基金业务销售网点的需要。","options":["非交易过户","份额转托管","份额冻结","份额转换"],"answer":"B","explain":"B 选项正确，投资人可通过办理转托管业务，实现其变更办理基金业务销售渠道（或网点）的需要。故本题选B选项。【温馨提示】（1）开放式基金非交易过户：是指不采用申购、赎回等交易方式，将一定数量的基金份额按照一定规则从某一投资者基金账户转移到另一投资者基金账户的行为，主要包括继承、捐赠、司法强制执行和经注册登记机构认可的其他情况下的非交易过户。（2）开放式基金份额的冻结：基金注册登记机构只受理相关有权机关本身提出的基金份额冻结与解冻业务申请。有权机关提出的份额冻结和解冻应按照国家相关法律、法规和规章进行，注册登记机构对于其冻结和解冻的后果不承担责任。基金份额冻结与解冻业务由注册登记机构直接受理，并须提供要求的相关资料。注册登记机构对申请材料检验合格的，对份额冻结与解冻业务进行办理。（3）开放式基金份额转换：是指投资者将其所持有的某一只基金份额转换为另一只基金份额的行为，基金转换业务所涉及的基金，必须是由同一基金管理人管理的、在同一注册登记人处注册登记的基金。"},{"id":"t300-bas-27","subject":"basics","source":"9月300题 LC","type":"单选","q":"假定 A 公司在未来每期支付的每股股息为 8 元，必要收益率为 10%，而当时股票价格为 65元，每股股票净现值为（）元。14","options":["15","20","25","30"],"answer":"A","explain":"（1）使用零增长股利模型计算股票内在价值：股票的内在价值 =未来每期支付的每期股息/必要收益率=8/10%=80元。（2）净现值=内在价值成本=80-65=15元（A 选项正确）。故本题选A选项。"},{"id":"t300-bas-28","subject":"basics","source":"9月300题 LC","type":"单选","q":"金融市场参与者无法以合理成本及时获得充足资金，以偿付到期债务，履行其他支付义务和满足正常业务开展的资金需求的风险是（）。","options":["流动性风险","违约风险","信用风险","声誉风险"],"answer":"A","explain":"A 选项正确，流动性风险，是指金融市场参与者无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求的风险，通常被分为融资流动性风险和资产流动性风险。故本题选A选项。"},{"id":"t300-bas-29","subject":"basics","source":"9月300题 LC","type":"单选","q":"金融市场的首要功能是（）。","options":["资金融通","风险管理","信息生产15","公司控制"],"answer":"A","explain":"A 选项正确，金融市场的首要功能是资金融通。金融市场通过金融资产交易实现货币资金在供给者和需求者之间的转移，促进有形资本形成。故本题选A选项。"},{"id":"t300-bas-30","subject":"basics","source":"9月300题 LC","type":"单选","q":"金融衍生工具的价值与基础产品或基础变量紧密联系、规则变动，这体现的是金融衍生工具的（）基本特征。","options":["联动性","杠杆性","跨期性","不确定性"],"answer":"A","explain":"A 选项正确，联动性是指金融衍生工具的价值与基础产品或基础变量紧密联系、规则变动的特性。B 选项错误，杠杆性是指金融衍生工具交易一般只需要支付少量的保证金或权利金就可签订远期大额合约或互换不同的金融工具。C 选项错误，跨期性是指金融衍生工具是交易双方通过对利率、汇率、股价等因素变动趋势的预测，约定在未来某一时间按照一定条件进行交易或选择是否交易的合约。D 选项错误，不确定性或高风险性是指金融衍生工具的交易后果取决于交易者对基础工具（变量）未来价格（数值）的预测和判断的准确程度。基础工具价格的变幻莫测决定了金融衍生工具交易盈亏的不稳定性，这是金融衍生工具高风险性的重要诱因。故本题选A选项。"},{"id":"t300-bas-31","subject":"basics","source":"9月300题 LC","type":"单选","q":"金融衍生品不具备的特征是（）。","options":["跨期性16","杠杆性","收益确定性","联动性"],"answer":"C","explain":"A、B、D 选项不符合题意，金融衍生工具的基本特征：跨期性、杠杆性、联动性、不确定性或高风险性。故本题选C选项。"},{"id":"t300-bas-32","subject":"basics","source":"9月300题 LC","type":"单选","q":"可以发行股票的公司组织形式是（）。","options":["有限责任公司","有限责任公司或股份有限公司","股份有限公司","独资公司"],"answer":"C","explain":"企业的组织形式可分为独资制、合伙制和公司制。现代公司主要采取股份有限公司和有限责任公司两种形式，其中，只有股份有限公司才能发行股票（C选项正确）。A、B、D选项错误，有限责任公司、独资公司不可以发行股票。故本题选C选项。"},{"id":"t300-bas-33","subject":"basics","source":"9月300题 LC","type":"单选","q":"可转换债券的最短存续期限为（）。","options":["6个月","1年","3年","6年"],"answer":"B","explain":"17B选项正确，可转换公司债券期限最短1年，最长 6年。故本题选B选项。"},{"id":"t300-bas-34","subject":"basics","source":"9月300题 LC","type":"单选","q":"某可转换债券面额为 1000 元，转换价格为 25 元/股，标的股票的内在价值 30 元/股，市场价格为32元/股，则转换比例为（）。","options":["42","31","33","40"],"answer":"D","explain":"转换比例=可转换债券面值/转换价格，将本题数据代入为：1000/25=40（D选项正确）。故本题选D选项。"},{"id":"t300-bas-35","subject":"basics","source":"9月300题 LC","type":"单选","q":"目前，我国境内多家证券公司在境外设立、收购了经营机构，积极为境内企业跨境投融资活动提供了金融服务，提高了自身国际化经营水平和核心能力，但国内证券公司开展国际化业务主要还是集中在（）市场。","options":["中国香港","美国纽约","英国伦敦","新加坡"],"answer":"A","explain":"目前来看，内地证券公司开展国际化业务的主战场仍是中国香港市场（ A 选项正确）。截至2023年6月，我国内地有36家证券经营机构在海外设立子公司，其中有35家机构在香港设立子公司，均持有香港证监会的证券经纪、承销保荐等牌照，具备担任内资企业境外上市主办行、机构投资者境外主经纪和托管商的相关资质。18故本题选A选项。"},{"id":"t300-bas-36","subject":"basics","source":"9月300题 LC","type":"单选","q":"能够促进储蓄-投资转化的市场是（）。","options":["金融市场","劳动力市场","技术市场","房地产市场"],"answer":"A","explain":"金融市场的重要性：促进储蓄-投资转化（A 选项正确）。金融市场或金融体系首先使 \"意愿的储蓄\"脱离了实物窖藏的方式，使社会可用的投资品总量增长，同时，又将\"货币形态\"的储蓄提供给需要追加投资的部门，使它们能够支付得起对投资品的需要，最后促成厂商\"非正常存货投资\"的减少，最终实现全社会储蓄与投资的一种事前的或计划的均衡，增进了社会福利。故本题选A选项。【温馨提示】金融市场的重要性，还包括：（1）优化资源配置。金融市场通过竞争性的价格决定（利率），将货币资金配置到生产效率最高的经济主体或部门，使这些部门能够获得更多生产要素（土地、资本、技术、劳动力），从而提高了全社会的产出，使资源的利用效率得到提高。（2）反映经济状态。金融市场是经济运行状态的 \"晴雨表\"，繁荣的金融市场往往对应着实体经济的兴旺发达，而金融市场的萧条通常也意味着实体经济部门的不景气。因此，金融市场为测度经济运行的景气状态提供了非常方便而且直观的途径或手段。（3）宏观调控。政府通过对金融市场直接或间接的干预，影响金融市场变量，调控社会信贷可得性，进而影响公众的储蓄、消费、投资行为，调整本国与外国的经济往来，影响商业周期，最终实现对产出、就业、物价以及国际收支的有效控制，并对社会财富分配、社会公平和社会福利施加影响。"},{"id":"t300-bas-37","subject":"basics","source":"9月300题 LC","type":"单选","q":"企业可以通过（）实现对其他企业的控股或参股。19","options":["资产管理计划","发行债券","股票投资","收益权转让"],"answer":"C","explain":"企业可以通过股票投资（C 选项正确）实现对其他企业的控股或参股，也可以将暂时闲置的资金通过自营或委托专业机构进行证券投资以获取收益。故本题选C选项。"},{"id":"t300-bas-38","subject":"basics","source":"9月300题 LC","type":"单选","q":"全面风险管理第一道防线是（）。","options":["业务条线部门","风险管理部","内部审计","董事会"],"answer":"A","explain":"风险管理的\"三道防线\"：（1）业务条线部门是第一道风险防线（ A 选项正确），是风险的承担者，应负责持续识别、评估和报告风险敞口。（2）风险管理部门和合规部门是第二道风险防线。风险管理部门负责监督和评估业务部门承担风险的业务活动：合规部门负责定期监控机构对于法律、公司治理规则、监管规定、行为规范和政策的执行情况。风险管理和合规部门均应独立于业务条线部门。（3）内部审计是第三道风险防线。内部审计部门对机构风险治理框架的质量和有效性进行独立的审计。故本题选A选项。"},{"id":"t300-bas-39","subject":"basics","source":"9月300题 LC","type":"单选","q":"商业银行等金融机构通过发行金融债券进行直接融资，该金融债券的特点之一是（）。20","options":["一般可记名、可挂失","该金融债券利率一般低于同期储蓄利率","该金融债券反映的是银行等金融机构与金融债券持有者之间的债权债务关系","一般不可用于抵押及转让"],"answer":"C","explain":"金融债券作为债券的一种特殊类型，它具有以下特点：（1）金融债券表示的是银行等金融机构与金融债券持有者之间的债权债务关系：（2）金融债券一般不记名、不挂失，但可以抵押和转让（A、D选项不符合题意）：（3）金融债券的利息不计复利，不能提前支取，延期兑付亦不计逾期利息：（4）金融债券的利率固定，一般都高于同期储蓄利率（B选项不符合题意）：（5）我国发行金融债券所筹集的资金一般都专款专用。故本题选C选项。"},{"id":"t300-bas-40","subject":"basics","source":"9月300题 LC","type":"多选","q":"2024年4 月4日国务院发布了新\"国九条\"，其主要内容包括（）。","options":["大力推动中长期资金入市，持续壮大长期投资力量","严格上市公司持续监管","进一步全面深化改革开放，更好地服务高质量发展","加强交易监管，增强资本市场内在稳定性"],"answer":"ABCD","explain":"新\"国九条\"主要内容及配套制度有：（1）总体要求。（2）严把发行上市准入关。（3）严格上市公司持续监管（B选项正确）。21（4）加大退市监管力度。（5）加强证券基金机构监管，推动行业回归本源、做优做强，推动证券基金机构高质量发展。（6）加强交易监管，增强资本市场内在稳定性（D选项正确）。（7）大力推动中长期资金入市，持续壮大长期投资力量（A选项正确）。（8）进一步全面深化改革开放，更好地服务高质量发展（C选项正确）。（9）推动形成促进资本市场高质量发展的合力。故本题选ABCD选项。"},{"id":"t300-bas-41","subject":"basics","source":"9月300题 LC","type":"多选","q":"按股东享有权利的不同，股票可以分为（）。","options":["记名股票","特别股票","无记名股票","普通股票"],"answer":"BD","explain":"按股东享有权利的不同，股票可以分为普通股票（D选项正确）和特别股票（B选项正确）。故本题选BD选项。"},{"id":"t300-bas-42","subject":"basics","source":"9月300题 LC","type":"多选","q":"按照付息方式不同，国债可分为（）。","options":["长期国债","附息国债","贴现国债","特种债券"],"answer":"BC","explain":"B、C选项正确，附息国债和贴现国债是按照国债利息的支付方式不同而划分的。故本题选BC选项。22"},{"id":"t300-bas-43","subject":"basics","source":"9月300题 LC","type":"多选","q":"按照所交易产品品种的不同，可以将资本市场分为（）。","options":["债券市场","股票市场","基金市场","衍生品证券市场"],"answer":"ABCD","explain":"按照交易产品品种的不同，可以将资本市场划分为股票市场（B 选项正确）、债券市场（A 选项正确）、衍生品证券市场（D选项正确）和基金市场（C选项正确）。故本题选ABCD选项。【温馨提示】（1）按照市场功能的不同，可以将资本市场划分为发行市场和交易市场：（2）按照资本市场的组织形式和交易活动是否集中统一，可以将资本市场划分为场内交易市场和场外交易市场：（3）按照所服务和覆盖的上市公司类型的不同，可以将资本市场划分为全球性市场、全国性市场、区域性市场等类型：（4）按照发行和募集方式的不同，可以将资本市场划分为公募市场和私募市场。"},{"id":"t300-bas-44","subject":"basics","source":"9月300题 LC","type":"多选","q":"保荐制度的重点有（）。","options":["明确保荐机构和保荐代表人的责任","形成持续信用监管和\"冷淡对待\"的监管措施","证券登记管理制度","建立责任追究机制"],"answer":"AD","explain":"保荐制度的重点是明确保荐机构和保荐代表人的责任，并建立责任追究机制（ A、D 选项正确）。保荐人的保荐责任期包括发行上市全过程以及上市后的一段时期。故本题选AD选项。23"},{"id":"t300-bas-45","subject":"basics","source":"9月300题 LC","type":"多选","q":"在基金信息披露中，禁止登载自然人、法人或者其他组织的（）文字。","options":["祝贺性","恭维性","描述性","推荐性"],"answer":"ABD","explain":"禁止登载任何自然人、法人或者其他组织的祝贺性、恭维性或推荐性的文字。故本题选ABD选项。"},{"id":"t300-bas-46","subject":"basics","source":"9月300题 LC","type":"多选","q":"常见股份变动形式有（）。","options":["配股","定向增发","股票分割","资本公积转增股本"],"answer":"ABCD","explain":"常见股份变动形式有：（1）增发和定向增发（B选项正确）。（2）配股（A选项正确）。（3）资本公积金转增股本（D选项正确）。（4）股份回购。（5）可转换债券转换为股票。（6）股票分割和合并（C选项正确）。故本题选ABCD选项。"},{"id":"t300-bas-47","subject":"basics","source":"9月300题 LC","type":"多选","q":"承销是发行人将股票销售业务委托给专门的证券经营机构（承销商）销售。承销方式有（）。24","options":["自销","包销","代销","直销"],"answer":"BC","explain":"B、C选项正确，证券承销业务可以采取包销或者代销方式。故本题选BC选项。"},{"id":"t300-bas-48","subject":"basics","source":"9月300题 LC","type":"多选","q":"从事基金服务业务的机构，按照中国证监会的有关规定应进行注册或者备案，这些机构包括（）。","options":["从事公募基金的销售机构","从事公募基金的信息技术系统服务的机构","从事公募基金份额登记的机构","从事公募基金的投资顾问的机构"],"answer":"ABCD","explain":"基金管理人、基金托管人既是基金的当事人，又是基金的主要服务机构。除基金管理人与基金托管人外，基金市场上还有许多面向基金提供各类服务的其他服务机构。这些机构主要包括基金销售机构（A 选项正确）、基金销售支付机构、基金份额登记机构（ C选项正确）、基金估值核算机构、基金投资顾问机构（D 选项正确）、基金评价机构、律师事务所、会计师事务所、信息技术系统服务机构（B 选项正确）等。从事基金服务业务的机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。故本题选ABCD选项。"},{"id":"t300-bas-49","subject":"basics","source":"9月300题 LC","type":"多选","q":"地方政府一般债券的发行主体可以有（）。","options":["地级市政府","省政府25","自治区政府","直辖市政府"],"answer":"BCD","explain":"地方政府一般债券是指省（B 选项正确）、自治区（C 选项正确）、直辖市政府（含经省级政府批准自办债券发行的计划单列市政府）（D 选项正确）为没有收益的公益性项目发行的、约定一定期限内主要以一般公共预算收入还本付息的政府债券。故本题选BCD选项。"},{"id":"t300-bas-50","subject":"basics","source":"9月300题 LC","type":"多选","q":"法人结算模式要求证券公司以法人名义在证券登记结算机构开立的账户有（）。","options":["资金交收账户","证券交收账户","资金结算账户","证券结算账户"],"answer":"AB","explain":"（1）每日交易结束后，证券公司要为客户办理证券和资金的清算与交收。目前，我国证券市场采用的是法人结算模式。（2）法人结算是指由证券公司以法人名义在证券登记结算机构开立证券交收账户和资金交收账户（A、B 选项正确，C、D 选项错误），其接受客户委托代理的证券交易的清算交收均通过此账户办理。证券公司与其客户之间的资金清算交收由证券公司自行负责完成。证券公司作为结算参与人与客户之间的清算交收，是整个结算过程不可缺少的环节。故本题选AB选项。"},{"id":"t300-bas-51","subject":"basics","source":"9月300题 LC","type":"多选","q":"风险管理的流程主要包括（）。","options":["风险的传导","风险的衡量","风险的监测、预警与报告26","风险的识别"],"answer":"BCD","explain":"一般情况下，风险管理的流程主要包括：风险的识别（D 选项正确）、风险的衡量（B 选项正确）、风险的监测、预警与报告（C选项正确）以及风险的应对。故本题选BCD选项。"},{"id":"t300-bas-52","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据《公司法》，普通股股东行使剩余财产分配权，必须在公司解散清算时，公司财产经法定清偿后，方可对剩余财产按照股东持有的股份比例进行分配，其中，公司财产的法定清偿包括（）。","options":["支付清算费用","职工的工资、社会保险费用和法定补偿金","缴纳所欠税款","清偿公司债务"],"answer":"ABCD","explain":"我国《公司法》规定，公司财产在分别支付清算费用（A 选项正确）、职工的工资、社会保险费用和法定补偿金（B 选项正确），缴纳所欠税款（C 选项正确），清偿公司债务（D 选项正确）后的剩余财产，按照股东持有的股份比例分配。公司财产在未按照规定清偿前，不得分配给股东。故本题选ABCD选项。"},{"id":"t300-bas-53","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据《上市公司证券发行注册管理办法》，上市公司再融资的方式有（）。","options":["向原股东配售股份","向不特定对象募集股份","首次公开发行股票","发行可转换公司债券"],"answer":"ABD","explain":"27（1）上市公司首次融资的途径。根据《公司法》，上市公司是指其股票在证券交易所上市交易的股份有限公司。上市公司首次融资主要是指首次公开发行股票（IPO）（C选项错误）。（2）上市公司再融资的方式有向原股东配售股份（A 选项正确）、向不特定对象募集股份（B选项正确）、向特定对象发行股票、发行可转换公司债券（D选项正确）。故本题选ABD选项。"},{"id":"t300-bas-54","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据《证券法》，下列属于国务院证券监督管理机构有权采取的措施有（）。","options":["进入涉嫌违法行为发生场所调查取证","通知出境入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境","询问当事人和与被调查事件有关的单位和个人，要求其对与被调查事件有关的事项作出说明","对证券公司之间、证券公司与客户之间发生的证券业务纠纷进行调解"],"answer":"ABC","explain":"国务院证券监督管理机构根据《证券法》依法履行职责，有权采取下列措施：（1）进入涉嫌违法行为发生场所调查取证（A选项正确）。（2）询问当事人和与被调查事件有关的单位和个人，要求其对与被调查事件有关的事项作出说明或者要求其按照指定的方式报送与被调查事件有关的文件和资料（C选项正确）。（3）通知出境入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境（B选项正确）。D选项错误，是中国证券业协会的职责。故本题选ABC选项。【温馨提示】国务院证券监督管理机构根据《证券法》依法履行职责，有权采取的措施还包括：（1）对证券发行人、证券公司、证券服务机构、证券交易场所、证券登记结算机构进行现场检查。28（2）查阅、复制与被调查事件有关的财产权登记、通讯记录等文件和资料。（3）查阅、复制当事人和与被调查事件有关的单位和个人的证券交易记录、登记过户记录、财务会计资料及其他相关文件和资料：对可能被转移、隐匿或者毁损的文件和资料，可以予以封存、扣押。（4）查询当事人和与被调查事件有关的单位和个人的资金账户、证券账户、银行账户以及其他具有支付、托管、结算等功能的账户信息，可以对有关文件和资料进行复制。对有证据证明已经或者可能转移或者隐匿违法资金、证券等涉案财产或者隐匿、伪造、毁损重要证据的，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以冻结或者查封，期限为 6 个月：因特殊原因需要延长的，每次延长期限不得超过 3 个月，冻结、查封期限最长不得超过2年。（5）在调查操纵证券市场、内幕交易等重大证券违法行为时，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以限制被调查事件当事人的证券买卖，但限制的期限不得超过3个月：案情复杂的，可以延长 3 个月。"},{"id":"t300-bas-55","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据《证券投资基金法》的规定，基金财产不得用于下列（）投资或者活动。","options":["承销证券","向他人贷款","从事承担无限责任的投资","买卖基金管理人发行的股票"],"answer":"ABC","explain":"基金禁止投资的活动范围包括：（1）承销证券（A选项符合题意）：（2）向他人贷款或者提供担保（B选项符合题意）：（3）从事承担无限责任的投资（C选项符合题意）：（4）买卖其他基金份额，但国务院另有规定的除外：（5）向基金管理人、基金托管人出资：（6）从事内幕交易、操纵证券交易价格及其他不正当的证券交易活动：29（7）依照法律、行政法规有关规定，由国务院证券监督管理机构规定禁止的其他活动。D 选项不符合题意，现行法律并非完全禁止，而是履行关联交易审批、信息披露后可以买卖，不属于法定绝对禁止行为。故本题选ABC选项。"},{"id":"t300-bas-56","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据 2024 年 5 月中国证监会发布的《证券市场程序化交易管理规定（试行）》，下列说法正确的有（）。","options":["明确对程序化交易相关的技术系统、交易信息系统接入等监管要求","明确报告要求，程序化交易投资者在履行报告义务后方可进行程序化交易","明确甄别高频交易，并从报告信息、收费等方面提出差异化监管要求","明确交易监控和风险防控要求，证券交易所对异常交易行为进行重点监控"],"answer":"ABCD","explain":"一是明确程序化交易的定义和总体要求。二是明确报告要求，程序化交易投资者应按规定报告账户基本信息、资金信息、交易信息、软件信息等信息，并落实\"先报告、后交易\"要求，在履行报告义务后方可进行程序化交易（B 选项正确）。三是明确交易监测和风险防控要求，证券交易所对程序化交易实行实时监控，对异常交易行为进行重点监控（D 选项正确）。同时，进一步压实证券公司客户管理职责，明确机构投资者合规风控要求。四是加强信息系统管理，明确对程序化交易相关的技术系统、交易单元、主机托管、交易信息系统接入等监管要求（A选项正确）。五是加强高频交易监管，明确高频交易的定义，并从报告信息、收费、交易监控等方面提出差异化监管要求（C选项正确）。六是明确监督管理安排，程序化交易相关机构和个人违反有关规定的，证券交易所、行业协会根据规定采取管理措施，证监会及其派出机构可依法采取监管措施或进行处罚。七是明确北向程序化交易按照内外资一致的原则，纳入报告管理，执行交易监控标准。故本题选ABCD选项。30"},{"id":"t300-bas-57","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据发行主体的不同，债券可以分为（）。","options":["政府债券","金融债券","公募债券","公司债券"],"answer":"ABD","explain":"根据发行主体的不同，债券可以分为政府债券（A 选项正确）、金融债券（B 选项正确）和公司债券（D选项正确）等主要类型。故本题选ABD选项。"},{"id":"t300-bas-58","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据上海和深圳证券交易所现行竞价方式有（）。","options":["连续竞价","固定竞价","撮合竞价","集合竞价"],"answer":"AD","explain":"目前，我国证券交易所采用两种竞价方式：集合竞价方式和连续竞价方式（ A、D 选项正确）。故本题选AD选项。"},{"id":"t300-bas-59","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据衍生工具的产品形态分类，金融衍生工具可以划分为（）。","options":["OTC交易的衍生工具","交易所交易的衍生工具","独立衍生工具","嵌入式衍生工具"],"answer":"CD","explain":"31根据产品形态，金融衍生工具可分为独立衍生工具（C 选项正确）和嵌入式衍生工具（D 选项正确）。金融衍生工具按交易场所可以分为交易所交易的衍生工具（ B 选项错误）和场外交易市场（OTC）（A选项错误）交易的衍生工具。故本题选CD选项。"},{"id":"t300-bas-60","subject":"basics","source":"9月300题 LC","type":"多选","q":"根据债券发行条款中是否规定约定期限向债券持有人支付利息，债券可分为（）。","options":["附息债券","零息债券","保值债券","息票累积债券"],"answer":"ABD","explain":"根据债券发行条款中是否规定在约定期限向债券持有人支付利息，债券可分为零息债券（B 选项正确）、附息债券（A选项正确）、息票累积债券（D选项正确）三类。故本题选ABD选项。【温馨提示】保值债券是 1989 年银行实行保值贴补率政策后，财政部发行的一种带有保值贴补的国债。1989年首次发行，金额为125亿元，期限3年，其年利率随中国人民银行规定的3年定期储蓄存款利率浮动，加保值贴补率，再外加1个百分点。1993年，面对日益高涨的通货膨胀率，国家决定对若干特定种类的国库券恢复保值。"},{"id":"t300-bas-61","subject":"basics","source":"9月300题 LC","type":"多选","q":"公募基金按投资标的可分为（）。","options":["股票基金","债券基金","货币基金","混合基金"],"answer":"ABCD","explain":"32A、B、C、D 选项正确，按投资标的划分，公募基金可分为股票基金、债券基金、混合基金、货币市场基金等。故本题选ABCD选项。"},{"id":"t300-bas-62","subject":"basics","source":"9月300题 LC","type":"多选","q":"股票发行监管制度主要有（）。","options":["注册制","保荐制","审批制","核准制"],"answer":"ACD","explain":"A、C、D 选项正确，股票发行监管制度主要有三种：审批制、核准制和注册制，每一种发行监管制度都对应一定的市场发展状况。故本题选ACD选项。"},{"id":"t300-bas-63","subject":"basics","source":"9月300题 LC","type":"多选","q":"关于股票的价值，下面说法中正确的有（）。","options":["股票的票面价值又被称为面值，即在股票票面上标明的金额","股票的内在价值即理论价值，也就是股票未来收益的现值","股票的清算价值是公司清算时每一股份所代表的实际价值","股票的账面价值又被称为股票净值或每股净资产"],"answer":"ABCD","explain":"A选项正确，股票的票面价值又称面值，即在股票票面上标明的金额。B选项正确，股票的内在价值即理论价值，即股票未来收益的现值。C选项正确，股票的清算价值是公司清算时每一股份所代表的实际价值。D选项正确，股票的账面价值又称股票净值或每股净资产。故本题选ABCD选项。33"},{"id":"t300-bas-64","subject":"basics","source":"9月300题 LC","type":"多选","q":"关于基金信息披露，下列说法正确的有（）。","options":["基金管理人和托管人应当按照法规规定的各项时间要求进行基金运作信息的披露","开放式基金在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值","基金募集信息披露只是指首次募集信息披露","货币基金需要披露收益公告，包括每万份基金收益和最近7日年化收益率"],"answer":"ABD","explain":"按照基金运作的全周期，基金信息披露大致可分为基金募集信息披露、运作信息披露和临时信息披露三大类：（1）基金募集信息披露可以分为首次募集信息披露和存续期募集信息披露（C选项错误）。（2）基金运作信息披露主要指在基金合同生效后至基金合同终止前，基金信息披露义务人依法定期披露基金的上市交易、投资运作及经营业绩等信息。基金管理人和基金托管人应当按照法规规定的各项时间要求进行基金运作信息的披露（A 选项正确），时间一般是可以事先预见的。对开放式基金而言，在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值（ B选项正确）。对普通货币基金而言，每日分配收益，份额净值保持 1 元不变，因此货币基金不像一般开放式基金那样披露每个开放日的份额净值，而是需要披露收益公告，包括每万份基金收益和最近 7日年化收益率（D选项正确）。（3）基金临时信息披露。故本题选ABD选项。"},{"id":"t300-bas-65","subject":"basics","source":"9月300题 LC","type":"多选","q":"关于基金自身投资活动中产生的税收，下列说法正确的有（）。","options":["证券投资基金管理人运用基金买卖股票、债券转让收入免征增值税","基金买卖股票实行单向征收印花税，向卖出方征收","对证券投资基金取得的债券利息收入，发行债券的企业和银行在向基金支付上述收入时代扣代缴20%个人所得税","对证券投资基金从证券市场中取得的收入，暂不征收企业所得税34"],"answer":"ABCD","explain":"A选项正确，证券投资基金管理人运用基金买卖股票、债券转让收入免征增值税。B 选项正确，基金卖出股票按照 0.05%的税率征收交易印花税，买入交易不征收印花税，即对印花税实行单向征收。C 选项正确，对基金取得的债券利息收入，发行债券的企业和银行在向基金支付上述收入时代扣代缴20%的个人所得税。D 选项正确，对证券投资基金从证券市场中取得的收入，包括买卖股票、债券的差价收入，股权的股息、红利收入，债券的利息收入及其他收入，暂不征收企业所得税。故本题选ABCD选项。"},{"id":"t300-bas-66","subject":"basics","source":"9月300题 LC","type":"多选","q":"关于利率期货套期保值，下列说法正确的有（）。","options":["对未来利率变动方向的预判会影响套期保值的操作走向","债券的久期将直接影响套期保值时所需要的期货合约数量","债券到期期限与久期之间的关系也作为利率套期保值的考量内容","债券现货持仓中可能存在基差风险会影响套期保值效果"],"answer":"ABCD","explain":"A 选项正确，套期保值分为多头套期保值、空头套期保值，操作方向完全基于对未来利率走势判断。预期利率上升做空头套保，预期利率下降做多头套保，预判直接决定操作走向。B 选项正确，利率期货套期保值合约数量计算公式核心包含现货债券久期、期货标的久期，久期是计算所需合约份数的关键变量，直接影响期货合约数量。C 选项正确，久期和债券到期期限高度相关，不同剩余期限债券久期差异大，会改变对冲比例与对冲效果，因此二者关系是套保重要考量因素。D 选项正确，基差风险是指现货价格与期货价格走势不完全一致导致的风险。即使进行了对冲，若基差发生不利变动，仍可能无法完全锁定成本或收益，从而影响套期保值的最终效果。故本题选ABCD选项。35"},{"id":"t300-bas-67","subject":"basics","source":"9月300题 LC","type":"多选","q":"关于上市公司直接融资，下列说法正确的有（）。","options":["向原股东配售股份简称配股","向特定对象发行股票也称为定向增发","公司发行股票所筹得的资本属于借入资本","首次公开发行股票简称IPO"],"answer":"ABD","explain":"A选项正确，向原股东配售股份，简称\"配股\"。B 选项正确，向特定对象发行股票，也称为定向增发，是股份公司向特定对象发行股票的增资方式。C 选项错误，公司发行股票所筹得的资金属于自有资本，而通过发行债券所筹集的资金属于借入资本。D选项正确，首次公开发行股票（简称IPO）。故本题选ABD选项。"},{"id":"t300-bas-68","subject":"basics","source":"9月300题 LC","type":"多选","q":"关于收益互换说法正确的是（）。","options":["证券向客户支付固定利息","客户向证券支付固定利息","证券向客户支付挂钩股票收益","客户向证券支付挂钩股票收益"],"answer":"BC","explain":"收益互换指交易双方约定在未来某一期限内根据标的（通常为股票、股票指数、大宗商品等）的收益表现与固定利率进行现金流交换的协议。比如，中国证券业协会于 2012 年底启动的股票收益互换，一方是证券公司，另外一方为其客户（投资者），通常是由客户向证券公司支付固定利息（B 选项正确），证券公司向客户支付挂钩的股票收益（C选项正确），以此进行互换。故本题选BC选项。36"},{"id":"t300-bas-69","subject":"basics","source":"9月300题 LC","type":"多选","q":"关于外国债券的说法，正确的有（）。","options":["必须经官方主管机构批准","受发行人所在国有关法规的管制和约束","受发行地所在国的税法管制","由发行地所在国的金融机构、证券公司承销"],"answer":"ACD","explain":"A、C 选项正确，B 选项错误，外国债券的发行受发行地所在国有关法规的管制和约束，并且必须经官方主管机构批准。D选项正确，外国债券一般由发行地所在国的证券公司、金融机构承销。故本题选ACD选项。【温馨提示】外国债券是指某一国家借款人在本国以外的某一国家发行以该国货币为面值的债券。它的特点是债券发行人属于一个国家，债券的面值货币和发行市场属于另一个国家。"},{"id":"t300-bas-70","subject":"basics","source":"9月300题 LC","type":"多选","q":"国际证监会组织公布的证券市场监管目标有（）。","options":["保持证券市场的公平、效率和透明","降低系统性风险","保护投资者利益","促进证券市场价格"],"answer":"ABC","explain":"国际证监会组织于1998年制定的《证券监管目标和原则》公布了证券监管的三个目标：一是保护投资者利益（C选项正确）：二是保证证券市场的公平、效率和透明（A选项正确）：三是降低系统性风险（B选项正确）。故本题选ABC选项。37"},{"id":"t300-bas-71","subject":"basics","source":"9月300题 LC","type":"多选","q":"合格境外投资者可以投资于（）。","options":["在全国中小企业股转系统转让的股票","债券回购","金融期货合约","商品期货合约"],"answer":"ABCD","explain":"合格境外投资者可以投资于下列金融工具：（1）在证券交易所交易或转让的股票、存托凭证、债券、债券回购、资产支持证券（ B 选项正确）：（2）在全国中小企业股份转让系统转让的股票等证券（A选项正确）：（3）中国人民银行允许合格境外投资者投资的在银行间债券市场交易的产品以及债券类、利率类、外汇类衍生品：（4）公募证券投资基金：（5）在中国金融期货交易所上市交易的金融期货合约（C选项正确）：（6）中国证监会批准设立的期货交易场所上市交易的商品期货合约（D选项正确）：（7）在国务院或中国证监会批准设立的交易场所上市交易的期权：（8）国家外汇管理局允许合格境外投资者交易基于套期保值目的的外汇衍生品：（9）中国证监会允许的其他金融工具。故本题选ABCD选项。"},{"id":"t300-bas-72","subject":"basics","source":"9月300题 LC","type":"多选","q":"宏观经济发展水平和状况是影响股票价格的重要因素，宏观经济影响股票价格的特点有（）。","options":["作用机制复杂","波及范围广","干扰程度深","可能导致股价波动幅度大38"],"answer":"ABCD","explain":"宏观经济发展水平和状况是影响股票价格的重要因素。宏观经济对股票价格影响的特点是波及范围广（B 选项正确）、干扰程度深（C 选项正确）、作用机制复杂（A选项正确）并可能导致股价波动幅度较大（D选项正确）。故本题选ABCD选项。"},{"id":"t300-bas-73","subject":"basics","source":"9月300题 LC","type":"多选","q":"基础设施公募REITs的基础资产范围包含（）。","options":["收费公路","仓储物流","保障性租赁住房","商品住宅"],"answer":"ABC","explain":"基础设施公募 REITs 在证券交易所上市交易，其底层资产涵盖仓储物流（B 选项正确）、交通设施（如收费公路、机场港口）（ A 选项正确）、市政设施（如水电气热）、消费基础设施（如商场、农贸市场）以及符合国家战略的其他领域（如清洁能源、保障性租赁住房等）（ C选项正确）。D选项错误，法规明确严禁商品住宅作为基础设施REITs底层资产。故本题选ABC选项。"},{"id":"t300-bas-74","subject":"basics","source":"9月300题 LC","type":"多选","q":"基金的运作包括（）。","options":["基金份额的登记和交易","基金资产托管","基金资产的估值与会计核算","基金的募集"],"answer":"ABCD","explain":"39基金运作包括基金募集（D 选项正确）、基金投资管理、基金资产托管（B 选项正确）、基金份额的登记与交易（A 选项正确）、基金资产的估值与会计核算（C 选项正确）、基金信息披露以及其他相关环节。在基金运作中，基金管理人居主导与核心位置。故本题选ABCD选项。"},{"id":"t300-bas-75","subject":"basics","source":"9月300题 LC","type":"多选","q":"基金份额净值的估值（）。","options":["信息披露无要求","计算必须准确","结果是公允的","可以根据参与方需求进行调整"],"answer":"BC","explain":"A 选项错误，B、C 选项正确，只有基金份额净值的估值结果是公允的，并进行及时的信息披露，各参与方才能在公平、公开的环境中进行投资活动。D 选项错误，估值需遵循统一的会计准则和监管规定，不能根据参与方需求随意调整，否则会损害持有人利益、破坏市场公平。故本题选BC选项。"},{"id":"t300-bas-76","subject":"basics","source":"9月300题 LC","type":"多选","q":"基金市场的参与主体，包括（）。","options":["基金服务机构","基金的自律组织","基金的监管机构","基金当事人"],"answer":"ABCD","explain":"基金市场上存在许多不同的参与主体，依据所承担的责任与作用的不同，可以将基金市场的参与主体分为基金当事人（D选项正确）、基金服务机构（A选项正确）、基金的监管机构（C选项正确）和自律组织（B选项正确）三大类。40故本题选ABCD选项。"},{"id":"t300-bas-77","subject":"basics","source":"9月300题 LC","type":"多选","q":"基金投资管理的流程包括（）。","options":["研究部门提供研究报告","投资决策委员会决定基金总体投资计划","基金经理拟订投资组合具体方案","交易部依据基金经理的投资指令执行交易"],"answer":"ABCD","explain":"一般而言，基金投资管理的流程包括以下环节：（1）研究部门提供研究报告（A选项正确）。（2）投资决策委员会决定基金总体投资计划（B选项正确）。（3）基金经理拟订投资组合具体方案（C选项正确）。（4）交易部门依据基金经理的投资指令执行交易（D选项正确）。故本题选ABCD选项。"},{"id":"t300-bas-78","subject":"basics","source":"9月300题 LC","type":"多选","q":"基金信息披露禁止（）。","options":["传播虚假基金信息","定期披露基金估值信息","恶意进行信息误导","登载其他人推荐性文字"],"answer":"ACD","explain":"为了防止信息误导给投资者造成损失，保护公众投资者的合法权益，维护证券市场的正常秩序，法律法规对于借公开披露基金信息之名编制、传播虚假基金信息（A 选项正确），恶意进行信息误导（C选项正确），诋毁同行或竞争对手等行为作出了禁止性规定。在信息真实性方面，禁止虚假记载、误导性陈述，禁止重大信息遗漏：在宣传规范性方面，禁止业绩预测、收益承诺以及不当宣传用语：在竞争行为方面，禁止诋毁同业机构、登载祝贺性41及恭维性文字（D选项正确）。B选项错误，定期披露估值属于正常合规披露。故本题选ACD选项。"},{"id":"t300-bas-79","subject":"basics","source":"9月300题 LC","type":"多选","q":"金融风险的特征有（）。","options":["可管理性","扩散性","加速性","隐蔽性"],"answer":"ABCD","explain":"金融风险的特征包括：（1）隐蔽性（D选项正确）：（2）扩散性（B选项正确）：（3）加速性（C选项正确）：（4）不确定性：（5）可管理性（A选项正确）：（6）周期性。故本题选ABCD选项。"},{"id":"t300-bas-80","subject":"basics","source":"9月300题 LC","type":"判断","q":"《巴塞尔协议》的颁布建立了资本充足率的最低标准。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。42巴塞尔委员会主要宗旨在于交换各国监管安排方面的信息，改善国际银行业务监管技术的有效性，建立资本充足率的最低标准，以及研究在其他领域确立标准的有效性。"},{"id":"t300-bas-81","subject":"basics","source":"9月300题 LC","type":"判断","q":"《巴塞尔协议Ⅲ》将交易对手信用风险定义为交易对手在履行金融结算后的违约风险。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。《巴塞尔协议Ⅲ》将交易对手信用风险定义为交易对手在现金流结算前（并非结算后）的违约风险。"},{"id":"t300-bas-82","subject":"basics","source":"9月300题 LC","type":"判断","q":"《证券期货投资者适当性管理办法》是投资者保护领域的基础性制度，其核心理念是卖者无责，买者自负。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。2016 年 12 月 12 日，中国证监会发布《证券期货投资者适当性管理办法》（2017 年 7 月 1 日正式实施，2022 年 8 月 12 日修正，以下简称《管理办法》）。这是中国资本市场首部专门规范适当性管理的部门规章，标志着我国金融市场有了关于适当性管理的基础性法律规范，投资者适当性管理制度体系基本确立。《管理办法》构建了一整套适当性管理的制度框架，其核心理念就是 \"将适当的产品销售给适当的投资者\"。"},{"id":"t300-bas-83","subject":"basics","source":"9月300题 LC","type":"判断","q":"VaR 值可以反映在一定置信水平下，给定的时间范围内，由于特定的交易事件而导致的流动性成本。一般来说，VaR值越小，表明证券公司面临的流动性风险越大。（）","options":["正确43","错误"],"answer":"B","explain":"本题说法错误。VaR 是指在正常的市场条件和给定的置信水平下，某一投资组合在给定的持有期间内可能发生的最大损失。"},{"id":"t300-bas-84","subject":"basics","source":"9月300题 LC","type":"判断","q":"按照委托时效可以把委托分为：当日委托，定时委托，限价委托，当周委托，无限期委托，开市委托，收市委托。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。根据委托时效限制，可分为当日委托、当周委托、无期限委托、开市委托和收市委托等。"},{"id":"t300-bas-85","subject":"basics","source":"9月300题 LC","type":"判断","q":"采用注册制的股票发行方式，证券交易所、中介机构和中国证监会分担实质审核职责。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。发行人申请发行股票时，必须依法将公开的各种资料完全准确地向证券监管机构申报。证券监管机构或者国务院授权的部门依照法定条件负责证券发行申请的注册。证券交易所等可以审核公开发行证券申请，判断发行人是否符合发行条件、信息披露要求，督促发行人完善信息披露内容，发行人的质量由证券交易所和证券中介机构来判断和决定。新《证券法》（2020年3月1日起施行）施行前，审核环节由中国证监会下设的发审委负责，核准环节和监督环节由中国证监会负责。44新《证券法》施行后，作为发行监管体制的重大改革，审核环节下放到证券交易所，由证券交易所进行实质审核，中国证监会履行监督职能，真正实现了监审分离。"},{"id":"t300-bas-86","subject":"basics","source":"9月300题 LC","type":"判断","q":"操作风险是指由不完善或有问题的内部流程、人员和系统以及外部事件所造成的风险。该定义包括法律风险、战略风险和声誉风险。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。操作风险是指由不完善或有问题的内部流程、人员和系统以及外部事件所造成损失的风险。该定义包括法律风险，但不包括战略风险和声誉风险。"},{"id":"t300-bas-87","subject":"basics","source":"9月300题 LC","type":"判断","q":"场外市场是整个证券市场的核心。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。场内市场即证券交易所市场。证券交易所是证券买卖双方公开交易的场所，是一个高度组织化、集中进行证券交易的市场，是整个证券市场的核心。"},{"id":"t300-bas-88","subject":"basics","source":"9月300题 LC","type":"判断","q":"储蓄国债（凭证式、电子式）可以上市自由流通交易。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。45储蓄国债（凭证式）和储蓄国债（电子式）都在商业银行柜台发行，不能上市流通，但都是信用级别最高的债券，以国家信用作保证，而且免缴利息税。"},{"id":"t300-bas-89","subject":"basics","source":"9月300题 LC","type":"判断","q":"从事基金份额登记管理相关业务，接受业务主管单位中国证监会的自律组织，必须符合基金业务自律规范，自觉遵守。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。中国证监会及其派出机构实施监督管理，中国证券投资基金业协会实施自律管理。"},{"id":"t300-bas-90","subject":"basics","source":"9月300题 LC","type":"判断","q":"短期融资券的期限一般不短于1年。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。短期融资券，是指具有法人资格的非金融企业在银行间债券市场发行的，约定在 1 年内还本付息的债务融资工具。其期限最长不超过1年，常见期限包括3个月、6个月、9个月、1年等。"},{"id":"t300-bas-91","subject":"basics","source":"9月300题 LC","type":"判断","q":"对于金融期货交易，结算所实行逐日盯市制度，以 T+1 为结算周期，对所有账户的交易头寸按照不同到期日的下一个交易日分别进行结算，从而能够及时调整保证金账户，控制市场风险。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。46结算所实行无负债的每日结算制度，又称\"逐日盯市制度\"（结算周期是 T 日，并非 T+1）。逐日盯市制度以一个交易日为最长的结算周期，对所有账户的交易头寸按不同到期日分别计算，并要求所有的交易盈亏都能及时结算，从而能及时调整保证金账户，控制市场风险。"},{"id":"t300-bas-92","subject":"basics","source":"9月300题 LC","type":"判断","q":"多层次资本市场的各层次之间并不是单独平行、彼此隔离的。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。多层次资本市场的各层次之间并不是单独平行、彼此隔离的，而是既互相区分、又相互交错并不断演进的结构。"},{"id":"t300-bas-93","subject":"basics","source":"9月300题 LC","type":"判断","q":"发展机构投资者有利于推动直接融资市场发展、扩大直接融资比重。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。机构投资者在金融市场中的作用：发展机构投资者有利于推动直接融资市场发展、扩大直接融资比重。【温馨提示】机构投资者在金融市场中的作用，还包括：（1）发展机构投资者有利于促进不同金融市场之间的有机结合与协调发展，健全金融市场运行机制。（2）机构投资者有助于分散金融风险，促进金融体系的稳定运行。（3）机构投资者有助于实现社会保障体系与宏观经济的良性互动发展。"},{"id":"t300-bas-94","subject":"basics","source":"9月300题 LC","type":"判断","q":"风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化。（）47","options":["正确","错误"],"answer":"A","explain":"本题说法正确。风险偏好是战略性的，通常以定性描述为主：风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化。"},{"id":"t300-bas-95","subject":"basics","source":"9月300题 LC","type":"判断","q":"刚性兑付的存在，使金融市场不是完全按照市场机制在运作。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。中国金融业快速扩张并没有改变中国金融体系发育不足的现实，归根结底在于刚性兑付的存在使金融市场不是完全按照市场机制在运作，起不到分散和化解微观风险的作用，很多微观风险实际上是由政府承担。"},{"id":"t300-bas-96","subject":"basics","source":"9月300题 LC","type":"判断","q":"港股通交易以人民币报价，投资者以港币交收。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。港股通交易以港币报价，投资者以人民币交收。"},{"id":"t300-bas-97","subject":"basics","source":"9月300题 LC","type":"判断","q":"根据《证券交易所管理办法》，证券交易所的职能包括依法审核公开发行证券申请，审核、安排证券上市交易，决定证券终止上市和重新上市，对会员进行监管等。（）","options":["正确48","错误"],"answer":"A","explain":"本题说法正确。证券交易所的职能包括：依法审核公开发行证券申请：审核、安排证券上市交易，决定证券终止上市和重新上市：对会员进行监管等。【温馨提示】证券交易所的职能包括：（1）提供证券交易的场所、设施和服务：（2）制定和修改证券交易所的业务规则：（3）依法审核公开发行证券申请：（4）审核、安排证券上市交易，决定证券终止上市和重新上市：（5）提供非公开发行证券转让服务：（6）组织和监督证券交易：（7）对会员进行监管：（8）对证券上市交易公司及相关信息披露义务人进行监管：（9）对证券服务机构为证券上市、交易等提供服务的行为进行监管：（10）管理和公布市场信息：（11）开展投资者教育和保护：（12）法律、行政法规规定的以及中国证监会许可、授权或者委托的其他职能。"},{"id":"t300-bas-98","subject":"basics","source":"9月300题 LC","type":"判断","q":"根据发行条件的不同，金融债券可分为普通金融债券、特种金融债券和累进利息金融债券。（）","options":["正确","错误"],"answer":"B","explain":"49本题说法错误。根据发行条件不同，金融债券可分为普通金融债券和累进利息金融债券。"},{"id":"t300-bas-99","subject":"basics","source":"9月300题 LC","type":"判断","q":"公募REITs每年可供分配利润分配比例不低于 90%。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。基础设施公募 REITs 采取封闭式运作，收益分配比例不低于合并后基金年度可供分配金额的90%。"},{"id":"t300-bas-100","subject":"basics","source":"9月300题 LC","type":"判断","q":"股东可以用知识产权作价出资。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。股东可以用货币出资，也可以用实物、知识产权、土地使用权、股权、债权等可以用货币估价并可以依法转让的非货币财产作价出资。但是，法律、行政法规规定不得作为出资的财产除外。"},{"id":"t300-bas-101","subject":"basics","source":"9月300题 LC","type":"判断","q":"股份公司年度股东会每年召开一次，应当于上一会计年度结束后的 4个月内举行。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。年度股东会每年召开一次，应当于上一会计年度结束后的6个月内（并非 4个月内）举行。50"},{"id":"t300-bas-102","subject":"basics","source":"9月300题 LC","type":"判断","q":"股票的清算价值是公司清算时每一股份所代表的实际价值，其往往与账面价值不一样。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。股票的清算价值是公司清算时每一股份所代表的实际价值。从理论上说，股票的清算价值应与账面价值一致，实际上并非如此。只有当清算时公司资产实际出售价款与财务报表上的账面价值一致时，每一股份的清算价值才与账面价值一致。但在公司清算时，其资产往往只能压低价格出售，再加上必要的清算费用，所以大多数公司的实际清算价值低于其账面价值。"},{"id":"t300-bas-103","subject":"basics","source":"9月300题 LC","type":"判断","q":"股票价格指数的编制步骤依次为一是选择样本股：二是选定某基期，并以一定方法计算基期平均股价或市值：三是指数化，简单计算计算期平均股价或市值。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。股票价格指数的编制步骤：第一步，选择样本股。第二步，选定某基期，并以一定方法计算基期平均股价或市值。第三步，计算计算期平均股价或市值，并作必要的修正。第四步，指数化。"},{"id":"t300-bas-104","subject":"basics","source":"9月300题 LC","type":"判断","q":"国债（包括附息国债）、企业债、公司债、证券公司次级债、中小企业私募债均可以跨市场转托管。其中，国债转托管速度最快，目前已实现 T+1 日到账，其他债券品种只能实现51T+2或T+3日到账。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。目前，除了国债（包括附息国债和地方债）和企业债可以跨市场转托管，其他债券品种（包括公司债、证券公司次级债、中小企业私募债）都不能跨市场转托管。目前，最快的国债转托管能实现 T+1 日到账，其他大部分债券只能实现 T+2 日甚至 T+3 日到账。"},{"id":"t300-bas-105","subject":"basics","source":"9月300题 LC","type":"判断","q":"沪港通是指上海证券交易所与香港联合交易所有限公司建立技术连接，使内地投资者可以通过本地证券公司购买规定范围的香港联合交易所的上市债券，也可以通过香港证券公司买卖规定范围内的上海证券交易所的上市债券。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。沪港通交易标的是股票，不是债券。【温馨提示】沪港通，即沪港股票市场交易互联互通机制，是指内地和香港投资者委托上海证券交易所会员或者香港联合交易所参与者，通过上海证券交易所或者香港联合交易所在对方所在地设立的证券交易服务公司，买卖规定范围内的对方交易所上市的股票。"},{"id":"t300-bas-106","subject":"basics","source":"9月300题 LC","type":"判断","q":"货币供应量↑→实际利率↑→汇率↓→净出口↑→总产出↑。（）","options":["正确","错误"],"answer":"B","explain":"52本题说法错误。汇率传导机制：货币供应量↑→实际利率↓（并非↑）→汇率↓→净出口↑→总产出↑。【温馨提示】扩张性货币政策会引起实际利率水平下降，本币存款相对于外汇资产的预期收益率降低，资本总是从利率相对较低的国家流向利率相对较高的国家，这将导致本币贬值。本币贬值会促进本国商品出口，抑制外国商品进口，从而使净出口增加，最终导致总需求和总产出增加。"},{"id":"t300-bas-107","subject":"basics","source":"9月300题 LC","type":"判断","q":"基金产品相比市场上其他理财产品具有较高透明度，所以我国基金信息披露制度具有非强制性。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。在我国，基金的信息披露具有强制性，《证券投资基金法》和《公开募集证券投资基金信息披露管理办法》及一系列配套法规对基金信息披露的原则、内容、禁止行为等各方面作出了明确、严格的规定。"},{"id":"t300-bas-108","subject":"basics","source":"9月300题 LC","type":"判断","q":"基金经营活动中，买卖债券、股票等实现的差价收益为利息收入。（）","options":["正确","错误"],"answer":"B","explain":"本题说法错误。投资收益是指基金经营活动中因买卖股票、债券、资产支持证券、基金等实现的差价收益，具体可分为股票投资收益、债券投资收益、资产支持证券投资收益、基金投资收益、衍生工具收益、股利收益等。53"},{"id":"t300-bas-109","subject":"basics","source":"9月300题 LC","type":"判断","q":"基金类投资者包括证券投资基金、社保基金、企业年金、职业年金和社会公益基金。（）","options":["正确","错误"],"answer":"A","explain":"本题说法正确。基金类投资者包括证券投资基金、社保基金、企业年金、职业年金和社会公益基金。"},{"id":"t300-bas-110","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】宏观经济和证券市场运行情况、行业前景以及公司经营状况是影响投资者对未来\n股价预期从而影响当年买卖决策并最终导致当前股价变化的最主要原因。在证券分析中，通常\n把这三类因素统称为基本因素，对这些因素的分析就是基本分析或基本面分析。投资者老王拟\n通过基本面分析对上市公司HM股价的影响因素进行研究。 \n请根据上述背景信息回答下列问题。\n\n【问题】下列股票价格的说法中，错误的是（）。","options":["股票的期值就是股票未来收益的当前价值，即人们为了得到股票的未来收益愿意付出的代价","引起股票价格变动的直接原因是供求关系的变化","股票的市场价格一般是指股票在二级市场上交易的价格","股票价格是指股票在证券市场上的买卖价格"],"answer":"A","explain":"A 选项错误，股票的现值（并非\"期值\"）就是股票未来收益的当前价值，即人们为了得到股票的未来收益愿意付出的代价。股票的未来股息收入、资本利得收入是股票的未来收益，也称为期值。"},{"id":"t300-bas-111","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】宏观经济和证券市场运行情况、行业前景以及公司经营状况是影响投资者对未来\n股价预期从而影响当年买卖决策并最终导致当前股价变化的最主要原因。在证券分析中，通常\n把这三类因素统称为基本因素，对这些因素的分析就是基本分析或基本面分析。投资者老王拟\n通过基本面分析对上市公司HM股价的影响因素进行研究。 \n请根据上述背景信息回答下列问题。\n\n【问题】下列影响股价变动的宏观经济与政策因素有（）。","options":["货币政策","经济增长","财政政策","汇率变化"],"answer":"ABCD","explain":"影响股价变动的宏观经济与政策因素包括：①经济增长（B选项正确）：②经济周期循环：③货币政策（A选项正确）：④财政政策（C选项正确）：⑤市场利率：⑥通货膨胀：⑦汇率变化（D选项正确）：⑧国际收支状况。故本题选ABCD选项。"},{"id":"t300-bas-112","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】某证券公司投行人员正接触一家经营良好的公司甲，他们准备推荐该公司公开发\n行股票和上市，并对该公司的申请文件和信息制度展开全方位的尽职调查和辅导。 \n请根据上述背景信息回答以下问题。\n\n【问题】该证券公司这单投行业务属于股票发行制度的（）。55","options":["注册制度","承销制度","保荐制度","发审委制度"],"answer":"C","explain":"A选项错误，注册制是证券发行审核的制度模式。B选项错误，承销指证券公司包销或代销证券、负责销售发行证券，侧重发行后的销售环节。C 选项正确，券商对拟上市企业进行尽职调查、上市辅导、推荐上市，属于保荐业务，对应股票发行里的保荐制度。D选项错误，发审委指发行审核委员会对发行申请进行审核表决，属于监管审核环节。故本题选C选项。"},{"id":"t300-bas-113","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】某证券公司投行人员正接触一家经营良好的公司甲，他们准备推荐该公司公开发\n行股票和上市，并对该公司的申请文件和信息制度展开全方位的尽职调查和辅导。 \n请根据上述背景信息回答以下问题。\n\n【问题】该证券公司投行人员尽职调查后认为，公司甲符合首次公开发行新股的基本条件。这些条件包括（）。","options":["公司甲如果改变募集资金用途，必须经董事会作出决议","最近三年财务会计报告被出具无保留意见审计报告","具有持续盈利能力","具备健全且运营良好的组织机构"],"answer":"BD","explain":"公司首次公开发行新股，应当符合下列条件：（1）具备健全且运行良好的组织机构（D选项正确）：（2）具有持续经营能力（C选项错误）："},{"id":"t300-bas-114","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】证券金融公司履行《转融通业务监督管理试行办法》规定的职责，为证券公司融\n资融券业务提供资金和证券的转融通服务等，其不以盈利为目的，但是因为开展转融通业务，\n有稳定的营业收入和利润。某证券公司于 202x 年 5 月 4 日按照规定取得融资融券和转融通业\n务资格，与证券金融公司于6月1日签订转融通业务合同。6月20日证券金融公司决定向该证\n券公司交付首笔转融通资金，并于 6 月 25 日实际交付完成该笔资金。证券金融公司按照规定\n向该证券公司收取一定的保证金，保证金由货币资金和证券冲抵。 \n不考虑其他相关影响因素，请根据上述背景信息回答下列问题。\n\n【问题】关于证券金融公司可用于开展转融通业务的资金来源，下列说法正确的有（）。","options":["自有资金","通过证券交易所的业务平台融入的资金","通过证券金融公司的业务平台融入的资金","自有证券"],"answer":"ABC","explain":"证券金融公司开展转融通业务的资金和证券来源：①自有资金和证券（A选项正确、D选项错误，题目问的是资金来源）：②通过证券交易所的业务平台融入的资金和证券（B选项正确）：③通过证券金融公司的业务平台融入的资金或者依法筹集的其他资金和证券（C选项正确）：57④证券金融公司可以发行公司债券，也可以向股东或者其他特定投资者借入次级债。故本题选ABC选项。"},{"id":"t300-bas-115","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】证券金融公司履行《转融通业务监督管理试行办法》规定的职责，为证券公司融\n资融券业务提供资金和证券的转融通服务等，其不以盈利为目的，但是因为开展转融通业务，\n有稳定的营业收入和利润。某证券公司于 202x 年 5 月 4 日按照规定取得融资融券和转融通业\n务资格，与证券金融公司于6月1日签订转融通业务合同。6月20日证券金融公司决定向该证\n券公司交付首笔转融通资金，并于 6 月 25 日实际交付完成该笔资金。证券金融公司按照规定\n向该证券公司收取一定的保证金，保证金由货币资金和证券冲抵。 \n不考虑其他相关影响因素，请根据上述背景信息回答下列问题。\n\n【问题】不考虑特殊情况下转融通期限的顺延或者缩短的情形，该证券公司获得的首笔转融通资金的期限截止日不得超过当年的（）。","options":["11月4日","12月1日","12月20日","12月25日"],"answer":"D","explain":"证券金融公司向证券公司转融通的期限不得超过 6 个月。转融通的期限，自资金或者证券实际交付之日起算。本题 6 月 20 日证券金融公司决定向该证券公司交付首笔转融通资金，并于 6 月 25 日实际交付完成该笔资金。所以首笔转融通资金的期限截止日不得超过当年的 12 月 25 日（D 选项正确）。故本题选D选项。"},{"id":"t300-bas-116","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】证券金融公司履行《转融通业务监督管理试行办法》规定的职责，为证券公司融\n资融券业务提供资金和证券的转融通服务等，其不以盈利为目的，但是因为开展转融通业务，\n有稳定的营业收入和利润。某证券公司于 202x 年 5 月 4 日按照规定取得融资融券和转融通业\n务资格，与证券金融公司于6月1日签订转融通业务合同。6月20日证券金融公司决定向该证\n券公司交付首笔转融通资金，并于 6 月 25 日实际交付完成该笔资金。证券金融公司按照规定\n向该证券公司收取一定的保证金，保证金由货币资金和证券冲抵。 \n不考虑其他相关影响因素，请根据上述背景信息回答下列问题。\n\n【问题】根据相关规定，该证券公司交存的货币资金占应收取保证金的比例最低为（）。","options":["10%","12%","15%","20%"],"answer":"C","explain":""},{"id":"t300-bas-117","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】甲公司为一家高科技企业，从事新材料研发和制造，其原材料大部分进口，产成\n品主要销往海外市场。为了更好地服务实体经济，A 股份制商业银行与甲公司签订了全面合作\n和服务协议，依据协议，甲公司将闲余资金全部存放在 A 银行。A 银行根据甲公司的经营需要\n向其提供贷款、票据贴现、银行承兑汇票、保函、信用证等业务服务：另外根据甲公司委托，\nA 银行代理甲公司有关款项的收付，并根据甲公司的投资需要，向其提供财务顾问、资产托管\n服务。 \n暂不考虑银行提供服务（业务）时的具体要求，请根据上述背景信息回答以下问题。\n\n【问题】根据商业银行的业务分类，下列属于商业银行资产业务的是（）。","options":["银行承兑汇票","吸收存款","资产托管","贷款业务"],"answer":"D","explain":"商业银行的主要业务包括负债业务、资产业务和表外业务。①商业银行负债业务的内容包括以下三项：A.自有资金：主要包括股本金、储备资金以及未分配利润。B.存款负债（B选项错误）。C.借款负债。②商业银行的资产业务主要包括现金资产、贷款业务、票据贴现、投资业务等（D 选项正确）。③表外业务主要分为担保承诺类、代理投融资服务类、中介服务类、其他类等。59A.担保承诺类业务：包括担保类、承诺类等按照约定承担偿还责任的业务。担保类业务：包括但不限于银行承兑汇票（A 选项错误）、保函、信用证、信用风险仍在银行的销售与购买协议等。承诺类业务：包括但不限于贷款承诺等。B.代理投融资服务类业务。C.中介服务类业务：包括但不限于代理收付、财务顾问、资产托管（C 选项错误）、各类保管业务等。D.其他类是指上述业务种类之外的其他表外业务。故本题选D选项。"},{"id":"t300-bas-118","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】甲公司为一家高科技企业，从事新材料研发和制造，其原材料大部分进口，产成\n品主要销往海外市场。为了更好地服务实体经济，A 股份制商业银行与甲公司签订了全面合作\n和服务协议，依据协议，甲公司将闲余资金全部存放在 A 银行。A 银行根据甲公司的经营需要\n向其提供贷款、票据贴现、银行承兑汇票、保函、信用证等业务服务：另外根据甲公司委托，\nA 银行代理甲公司有关款项的收付，并根据甲公司的投资需要，向其提供财务顾问、资产托管\n服务。 \n暂不考虑银行提供服务（业务）时的具体要求，请根据上述背景信息回答以下问题。\n\n【问题】根据商业银行的业务分类，下列属于商业银行表外业务中中介服务类业务的有（）。","options":["财务顾问","代理收付","资产托管","贷款业务"],"answer":"ABC","explain":"商业银行的表外业务主要分为担保承诺类、代理投融资服务类、中介服务类、其他类等。中介服务类业务指商业银行根据客户委托，提供中介服务、收取手续费的业务，包括但不限于代理收付（B选项正确）、财务顾问（A选项正确）、资产托管（C选项正确）、各类保管业务等。D选项错误，贷款业务是商业银行的资产业务。故本题选ABC选项。【温馨提示】商业银行的表外业务主要分为担保承诺类、代理投融资服务类、中介服务类、其他类等：①担保承诺类业务，包括担保类、承诺类等按照约定承担偿还责任的业务。A.担保类业务是指商业银行对第三方承担偿还责任的业务，包括但不限于银行承兑汇票、保函、信用证、信用风险仍在银行的销售与购买协议等。60B.承诺类业务是指商业银行在未来某一日期按照事先约定的条件向客户提供约定的信用业务，包括但不限于贷款承诺等。②代理投融资服务类业务，指商业银行根据客户委托，为客户提供投融资服务但不承担代偿责任、不承诺投资回报的表外业务，包括但不限于委托贷款、委托投资、代客非保本理财、代客交易、代理发行和承销债券等。③中介服务类业务指商业银行根据客户委托，提供中介服务、收取手续费的业务，包括但不限于代理收付、财务顾问、资产托管、各类保管业务等。④其他类是指上述业务种类之外的其他表外业务。"},{"id":"t300-bas-119","subject":"basics","source":"9月300题 LC","type":"案例","q":"【资料】甲公司为一家高科技企业，从事新材料研发和制造，其原材料大部分进口，产成\n品主要销往海外市场。为了更好地服务实体经济，A 股份制商业银行与甲公司签订了全面合作\n和服务协议，依据协议，甲公司将闲余资金全部存放在 A 银行。A 银行根据甲公司的经营需要\n向其提供贷款、票据贴现、银行承兑汇票、保函、信用证等业务服务：另外根据甲公司委托，\nA 银行代理甲公司有关款项的收付，并根据甲公司的投资需要，向其提供财务顾问、资产托管\n服务。 \n暂不考虑银行提供服务（业务）时的具体要求，请根据上述背景信息回答以下问题。\n\n【问题】根据商业银行的业务分类，下列属于商业银行表外业务中担保承诺类业务的是（）。","options":["信用证","投资业务","保函","银行承兑汇票"],"answer":"ACD","explain":"担保承诺类业务，包括担保类、承诺类等按照约定承担偿还责任的业务。①担保类业务是指商业银行对第三方承担偿还责任的业务，包括但不限于银行承兑汇票（D 选项正确）、保函（C 选项正确）、信用证（A 选项正确）、信用风险仍在银行的销售与购买协议等。②承诺类业务是指商业银行在未来某一日期按照事先约定的条件向客户提供约定的信用业务，包括但不限于贷款承诺等。B选项错误，投资业务属于商业银行的资产业务。故本题选ACD选项。"}]},{"id":"real-law","subject":"law","name":"6月真题汇编 · 法律法规","stats":{"单选":38,"多选":38,"判断":30,"案例":9},"questions":[{"id":"real-law-0","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《公司法》，下列关于可以用作有限责任公司出资的财产的说法，错误的是（）。","options":["货币","土地所有权","实物","知识产权"],"answer":"C","explain":"公开发行股票，代销、包销期限届满，发行人应当在规定的期限内将股票发行情况报国务院证券监督管理机构备案。"},{"id":"real-law-1","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"公开发行股票，代销、包销期限届满，发行人应当在规定的期限内将股票发行情况报（）备案。","options":["证券业协会","法院","国务院证券监督管理机构","中国人民银行"],"answer":"D","explain":"法定公积金转为增加注册资本时，所留存的该项公积金不得少于转增前公司注册资本的25%。"},{"id":"real-law-2","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"《公司法》规定，股份有限公司将法定公积金转为股本时，留存的该项公积金不得少于转增前公司注册资本的（）。","options":["10%","15%","20%","25%"],"answer":"D","explain":"监事会主席召集和主持监事会会议；监事会主席不能履行职务或者不履行职务的，由过半数的监事共同推举1名监事召集和主持监事会会议。"},{"id":"real-law-3","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"公司监事会主席不能履行职务或者不履行职务的，由（）以上监事共同推举1名监事召集和主持监事会会议。","options":["1/3","2/3","全体","半数"],"answer":"B","explain":"选项B正确：有限责任公司股东会由全体股东组成。股东会是公司的权力机构，依法行使职权。选项A错误：董事会是公司的执行机构选项C错误：监事会是公司的监督机构选项D错误：经理是公司的日常经营管理机构"},{"id":"real-law-4","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《公司法》的规定，有限责任公司的权力机构是（）。","options":["董事会","股东会","监事会","经理"],"answer":"BD","explain":"选项B错误：证券公司应当按规定并结合自身状况与业务发展需要，决定分支机构是否提供现场交易服务、是否部署与现场交易服务相关的信息系统。选项D错误：证券公司应当明确委托指令接收、排序、处理的相关要求，公平对待投资者。选项A正确：证券公司应当将投资者的证券和资金与自有财产分别管理，并采取措施保障投资者证券和资金的安全、完整。中国结算、投保基金公司根据中国证监会的规定监控投资者证券和资金安全保管情况。选项C正确：证券公司应当根据投资者委托管理投资者证券和资金，按照有关规定托管投资者证券，选择符合要求的商业银行存管投资者资金。证券公司应当将投资者的证券和资金与自有财产分别管理，并采取措施保障投资者证券和资金的安全、完整。"},{"id":"real-law-5","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"期货交易实行（）结算制度。","options":["次日负债","当日负债","当日无负债2026年6月证券从业《证券市场基本法律法规》完整版真题汇编（考生回忆）第1题单项选择题（每题0.5分，共40题，共20分）"],"answer":"A","explain":"选项A正确，选项BCD错误：法的规范性是法的基本特征。正是基于法的规范性，使法对人们的行为或社会关系具有指引、评价、预测、教育及强制的作用。这既是法区别于其他社会规范的重要标志，也是法作为人类文明进步成果的重要体现。"},{"id":"real-law-6","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列哪一项属于法的基本特征（）。","options":["规范性","强制性","国家意志性","权利与义务性"],"answer":"B","explain":"私募基金管理人应当遵循专业化管理原则，聘用具有相应从业经历的高级管理人员负责投资管理、风险控制、合规等工作。"},{"id":"real-law-7","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《私募投资基金监督管理条例》，私募基金管理人应当遵循专业化管理原则。聘用具有相应从业经历的高级管理人员负责（）等工作。","options":["党建工作、风险控制、合规","投资管理、风险控制、合规","行政管理、监察审计、稽核","投资管理、监察审计、稽核"],"answer":"B","explain":"选项B正确：证券公司在开展业务创新时，在可行性研究的基础上，应当及时与中国证监会沟通，履行创新业务的报备（报批）程序。选项A错误：中国证券业协会实行行业自律，不负责审批或备案创新业务选项C错误：中国银保监会主要负责银行和保险行业的监管，现为国家金融监督管理总局。"},{"id":"real-law-8","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"证券公司在开展业务创新时，在可行性研究的基础上，应当及时与（）沟通，履行创新业务的报备（报批）程序。","options":["中国证券业协会","中国证监会","中国银保监会","中国证券登记结算有限责任公司"],"answer":"D","explain":"根据《证券法》第一百九十八条的规定，证券公司违反《证券法》第八十八条的规定未履行或者未按照规定履行投资者适当性管理义务的，责令改正，给予警告，并处以10万元以上100万元以下的罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处以20万元以下的罚款。"},{"id":"real-law-9","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券法》，下列关于违反投资者保护规则的法律责任的说法，正确的是（）。","options":["证券公司未按照规定履行投资者适当性管理义务的，对合规总监和合规部门责任人员给予警告，并处以二十万元以下的罚款","证券公司未按照规定履行投资者适当性管理义务的，对法定代表人给予警告，并处以二十万元以下的罚款","证券公司未按照规定履行投资者适当性管理义务的，对分支机构负责人和其他直接责任人员给予警告，并处以二十万元以下的罚款","证券公司未按照规定履行投资者适当性管理义务的，对直接负责的主管人员和其他直接责任人员给予警告，并处以二十万元以下的罚款"],"answer":"C","explain":"证券公司应当至少每半年经主要负责人、首席风险官签署确认后（C正确），向公司全体董事报告一次公司净资本等风险控制指标的具体情况和达标情况（BD错误）；证券公司应当至少每半年经董事会签署确认，向公司全体股东报告一次公司净资本等风险控制指标的具体情况和达标情况，并至少获得主要股东的签收确认证明文件（A错误）。"},{"id":"real-law-10","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券公司风险控制指标管理办法》，下列关于证券公司编制风险控制指标监管报表相关要求的说法，正确的是（）。","options":["公司净资本等风险控制指标的具体情况和达标情况，应获得全体股东的签收确认证明文件","证券公司应当至少每年向公司全体董事报告一次公司净资本等风险控制指标的具体情况和达标情况","公司净资本等风险控制指标的具体情况和达标情况报告由主要负责人、首席风险官签署确认","证券公司应当至少每年向公司经营层报告一次公司净资本等风险控制指标的具体情况和达标情况"],"answer":"C","explain":"选项C错误：证券公司应当在选择信息技术服务机构之前，制定更换服务提供方的流程及预案，确保在特定情况下可更换服务提供方。选项A正确：证券公司委托信息技术服务机构提供服务，应当按照《证券基金经营机构信息技术管理办法》第十四条的规定对信息技术服务机构及相关信息系统进行内部审查，并向中国证监会及其派出机构报送审查意见及相关资料。选项BD正确：证券公司应当与信息技术服务机构签订服务协议和保密协议，明确各方权利、义务和责任，约定质量考核标准、持续监控机制、异常处理机制、服务变更或者终止的处置流程以及现场服务人员保密要求等内容，并持续监督信息技术服务机构及相关人员落实服务协议和保密协议的情况。"},{"id":"real-law-11","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于证券公司各类业务的内部控制要求的说法，错误的是（）。","options":["受托投资管理业务应封闭运作、专户管理","内核部门为投资银行业务内部控制的第一道防线","经纪业务应建立由相对独立人员对重点客户进行定期回访的制度","投资咨询业务应确保执业人员不存在兼职和挂靠"],"answer":"D","explain":"选项D错误：违反《证券法》第九条的规定，擅自公开或者变相公开发行证券的，责令停止发行，退还所募资金并加算银行同期存款利息，处以非法所募资金金额5%以上50%以下的罚款。选项ABC正确：公开发行证券，必须符合法律、行政法规规定的条件，并依法报经国务院证券监督管理机构或者国务院授权的部门注册。未经依法注册，任何单位和个人不得公开发行证券。证券发行注册制的具体范围、实施步骤，由国务院规定。非公开发行证券的，不得采用广告、公开劝诱和变相公开方式。"},{"id":"real-law-12","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券法》，下列关于证券发行的说法，错误的是（）。","options":["非公开发行证券，不得采用广告、公开劝诱和变相公开方式","公开发行证券，必须符合法律、行政法规规定的条件，并依法报经国务院证券监督管理机构或者国务院授权的部门注册","未经依法注册，任何单位和个人不得公开发行证券","擅自公开或者变相公开发行证券的，责令停止发行，退还所募资金并加算银行同期贷款利息，处以法定数额罚款"],"answer":"C","explain":"根据《关于证券公司证券自营业务投资范围及有关事项的规定》，证券公司从事证券自营业务，可以买卖此规定附件《证券公司证券自营投资品种清单》所列证券，主要包括：(1)已经和依法可以在境内证券交易所上市交易和转让的证券。这是证券自营业务主要的投资对象，主要包括股票、债券、证券投资基金等。(2)已经在全国中小企业股份转让系统挂牌转让的证券。（A正确）(3)已经和依法可以在符合规定的区域性股权交易市场挂牌转让的私募债券（D正确），已经在符合规定的区域性股权交易市场挂牌转让的股票。（B正确）(4)已经和依法可以在境内银行间市场交易的证券，主要包括政府债券、国际开发机构人民币债券、央行票据、金融债券、短期融资券、公司债券、中期票据、企业债券。(5)经国家金融监管部门或者其授权机构依法批准或备案发行并在境内金融机构柜台交易的证券（C错误）。"},{"id":"real-law-13","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"具备证券自营业务资格的证券公司开展自营业务，下列关于其投资范围的说法，错误的是（）。","options":["可投全国中小企业股份转让系统挂牌转让的证券","可投依法在区域性股权交易市场挂牌转让的股票","经国家金融监管部门或其授权机构依法批准或者发行并在境外金融机构柜台交易的证券","可投依法在区域性股权交易市场挂牌转让的私募债券"],"answer":"D","explain":"证券行业文化建设包括三大层次十大方面的关键要素。一是行为层，包括平衡各方利益、建立长效激励、加强声誉约束（D正确）、落实责任担当四个要素。二是组织层，包括融合发展战略（C）、强化文化认同（B）、激发组织活力（A）三要素。三是观念层，包括秉承守正创新、崇尚专业精神、坚持可持续发展三要素。"},{"id":"real-law-14","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券行业文化建设十要素》的相关内容，下列选项属于行为层要素的是（）。","options":["激发组织活力","强化文化认同","融合发展战略","加强声誉约束"],"answer":"D","explain":"证券公司从事证券经纪业务，应当依法履行以下职责：(1)规范开展营销活动；（A属于）(2)充分了解投资者，履行适当性管理义务；(3)落实账户实名制要求；（B属于）(4)履行反洗钱义务；（C属于）(5)对投资者账户开立与使用、资金划转与证券交易等行为进行管理和监控；(6)保障投资者交易的安全、连续；（收益无法保证，D不属于）(7)开展投资者教育；(8)防范违法违规证券交易活动；(9)维护正常市场秩序；(10)中国证监会、证券交易场所、中国结算等规定的其他职责。"},{"id":"real-law-15","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券经纪业务管理办法》，下列不属于证券公司从事证券经纪业务依法应当履行的职责的是（）。","options":["规范开展营销活动","落实账户实名制要求","履行反洗钱义务","保障投资者交易的收益"],"answer":"D","explain":"选项D正确：根据《证券投资基金法》第三十六条的规定，基金托管人依法应当履行下列职责：(1)安全保管基金财产；(2)按照规定开设基金财产的资金账户和证券账户；(3)对所托管的不同基金财产分别设置账户，确保基金财产的完整与独立；(4)保存基金托管业务活动的记录、账册、报表和其他相关资料；(5)按照基金合同的约定，根据基金管理人的投资指令，及时办理清算、交割事宜；(6)办理与基金托管业务活动有关的信息披露事项；(7)对基金财务会计报告、中期和年度基金报告出具意见；(8)复核、审查基金管理人计算的基金资产净值和基金份额申购、赎回价格；(9)按照规定召集基金份额持有人大会；(10)按照规定监督基金管理人的投资运作。选项A错误：基金管理人的职责包括依法募集资金，办理基金份额的发售和登记事宜，办理基金备案手续，对所管理的不同基金财产分别管理、分别记账，进行证券投资等。"},{"id":"real-law-16","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"基金财产保管职责应由（）承担。","options":["基金管理人","基金注册登记机构","基金销售机构","基金托管人"],"answer":"D","explain":"选项D错误：合规负责人是高级管理人员，直接向董事会负责，对本公司及其工作人员的经营管理和执业行为的合规性进行审查、监督和检查。选项A正确：保障合规负责人的知情权。要求公司在召开董事会、经营决策会等重要会议以及合规负责人要求参加或者列席的会议前通知合规负责人，合规负责人有权根据履职需要参加或列席有关会议，查阅、复制有关文件、资料。选项B正确：合规负责人工作称职的，其年度薪酬收入总额在公司高级管理人员年度薪酬收入总额中的排名应当不低于中位数。选项C正确：强化合规负责人对合规管理人员的考核权。要求合规部门及其合规管理人员由合规负责人考核，证券公司对合规部门及其合规管理人员进行考核时，不得采取其他部门评价、以业务部门的经营业务为依据等方式影响合规部门及其合规管理人员的独立性。"},{"id":"real-law-17","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，下列关于证券公司合规负责","options":["合规负责人有权要求根据履职需要列席董事会","合规负责人工作称职的，其年度薪酬收入总额在公司高级管理人员年度薪酬收入总额中的排名不应当低于中位数","证券公司对合规部门考核时，不得将考核结果与业务部门的经营业务直接挂钩","合规负责人直接向经营层负责，由经营层考核"],"answer":"D","explain":"选项D错误：公司及其他信息披露义务人未按照规定披露信息，或者所披露的信息有虚假记载、误导性陈述或者重大遗漏的，依照《证券法》有关规定进行处罚。选项A正确：证券公司及其工作人员未按《公众公司办法》规定履行持续督导责任，情节严重的，中国证监会可以采取责令改正、监管谈话、出具警示函等监管措施。选项B正确：公司向不符合《公众公司办法》规定条件的投资者发行股票的，中国证监会可以责令改正。选项C正确：公司未依照《公众公司办法》规定，擅自转让或者发行股票的，依照《证券法》有关规定进行处罚。"},{"id":"real-law-18","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于违反全国股转系统业务有关规定的法律责任的说法，错误的是（）。","options":["证券公司及其工作人员未按照《非上市公司公司监督管理办法》规定履行持续督导责任，情节严重的，中国证监会可以采取责令改正、监管谈话、出具警示函等监管措施","公司向不符合《非上市公司公司监督管理办法》规定条件的投资者发行股票的，中国证监会可以责令改正","公司未按照《非上市公司公司监督管理办法》规定，擅自转让或者发行股票的，按照《证券法》有关规定进行处罚","公司及其他信息披露义务人未按照规定披露信息，或者所披露的信息有虚假记载、误导性陈述或重大遗漏的，依照《上市公司收购管理办法》有关规定进行处罚"],"answer":"C","explain":"行业文化建设基本要求为：（一）坚持依法合规，筑牢发展基础（D）；（二）坚持诚实守信，恪守职业操守；（三）坚持专业精神，提升服务能力；（四）坚持稳健经营，促进健康发展；（五）坚持廉洁自律，弘扬清风正气（A）；（六）牢记社会责任，展现良好形象（B）。题目问的是“不属于”。故本题选C。"},{"id":"real-law-19","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列各项中，不属于证券行业文化建设基本要求的是（）。","options":["坚持廉洁自律，弘扬清风正气","牢记社会责任，展现良好形象","坚持盈利导向，回馈股东信任","坚持依法合规，筑牢发展基础"],"answer":"A","explain":"证券公司经营证券经纪业务的，其净资本不得低于人民币2000万元；经营证券承销与保荐、证券自营、证券资产管理、其他证券业务等业务之一的，其净资本不得低于人民币5000万元；经营证券经纪业务，同时经营证券承销与保荐、证券自营、证券资产管理、其他证券业务等业务之一的，其净资本不得低于人民币1亿元；经营证券承销与保荐、证券自营、证券资产管理、其他证券业务中两项及两项以上的，其净资本不得低于人民币2亿元。甲证券公司经营证券经纪业务一项，净资本要求为2000万元。乙证券公司经营证券承销与保荐一项，净资本要求为5000万元。丙证券公司经营证券经纪业务同时经营证券承销与保荐业务，净资本要求为1亿元。丁证券公司经营证券承销与保荐、证券自营两项，净资本要求为2亿元。因此甲证券公司净资本要求最低，A选项正确。"},{"id":"real-law-20","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"甲证券公司经营证券经纪业务一项业务，乙证券公司经营证券承销与保荐一项业务，丙证券公司经营证券经纪业务，同时经营证券承销与保荐业务，丁证券公司经营证券承销与保荐、证券自营两项业务，下列关于证券公司从事相关证券业务净资本标准的说法，正确的是（）。","options":["甲证券公司净资本要求最低","丙证券公司净资本要求最高","甲证券公司的净资本要求比乙证券公司的高","丙证券公司的净资本要求比丁证券公司高"],"answer":"C","explain":"选项C正确：机构及其工作人员应当自觉遵守以下勤勉尽责要求(1)恪守职业操守，忠实勤勉，履行对投资者及其他利益相关方的责任和义务；(2)持续学习，不断提升专业能力，保证服务质量；(3)专业审慎，尽到合理专业的注意义务，履职尽责；(4)对自己的专业能力有充分认识，不承诺力不能及或不能如期完成的业务，不推诿应承担的责任；(5)实事求是，独立、审慎、客观、公正开展业务，不受其他单位和个人的非法干预和影响；(6)按规定做好相关工作底稿档案的记录、归集和保存管理。选项AB错误：\"不发表不当言论，贬损、诋毁其他同行，损害同行声誉和利益\"\"尊重同行，公平竞争，禁止商业贿赂，自觉维护市场竞争秩序，坚决反对不正当竞争的行为\"属于\"公平竞争要求\"，而非\"勤勉尽责要求\"。选项D错误：\"不利用虚假和误导性信息进行宣传，不编造传播虚假和误导性信息\"属于\"言行一致要求\"，而非\"勤勉尽责要求\"。"},{"id":"real-law-21","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券行业诚信准则》，下列选项中，属于证券公司及其工作人员应当遵守的勤勉尽责要求的是（）。","options":["不发表不当言论，贬损、诋毁其他同行，损害同行声誉和利益","尊重同行，公平竞争，禁止商业贿赂，自觉维护市场竞争秩序，坚决反对不正当竞争的行为","对自己的专业能力有充分认识，不承诺力不能及或不能如期完成的业务，不推诿应承担的责任","不利用虚假和误导性信息进行宣传，不编造传播虚假和误导性信息"],"answer":"A","explain":"证券公司从事股票期权经纪业务试点，应当符合下列基本条件：（1）具有证券经纪业务资格。（2）股票期权经纪业务制度健全，拟负责股票期权经纪业务的高级管理人员具备股票期权业务知识和相应的专业能力，配备3名具备相应专业能力的业务人员（D正确）。（3）具有满足从事股票期权经纪业务相关要求的营业场所、经营设备、技术系统等软硬件设施；业务设施和技术系统符合相关技术规范且运行状况良好，股票期权经纪业务技术系统已通过相关证券交易所、中国证券登记结算有限责任公司组织的测试。（4）公司及其董事、监事、高级管理人员最近1年内未因重大违法违规行为受到行政处罚或刑事处罚（A错误）。证券公司从事股票期权经纪业务试点，应于实际开展业务后5个工作日内报公司住所地中国证监会派出机构备案，并提交备案材料。证券公司应当指定专门部门、专人开展股票期权经纪业务（B正确），拟开展股票期权经纪业务的分支机构应当至少有1名具备相应专业能力的业务人员（C正确）。"},{"id":"real-law-22","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于证券公司开展股票期权经纪业务应符合条件的说法，错误的是（）。","options":["公司最近6个月内未因重大违规行为受到行政处罚","应当指定专门部门、专人开展股票期权经纪业务","分支机构开展股票期权经纪业务应至少有1名具备相应专业能力的业务人员","公司开展股票期权经纪业务应配备3名具备相应专业能力的业务人员人和合规管理人员的独立性原则的说法，错误的是（）。"],"answer":"C","explain":"选项C错误：证券公司经停业整顿、托管、接管或者行政重组在规定期限内仍达不到正常经营条件，但能够清偿到期债务的，国务院证券监督管理机构依法撤销其证券业务许可。选项ABD说法正确。"},{"id":"real-law-23","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券公司风险处置条例》，下列关于行政重组的说法，错误的是（）。","options":["证券公司进行行政重组，可以采取注资、股权重组、债务重组、资产重组、合并或者其他方式","行政重组期限一般不超过12个月。期满未完成的，国务院证券监督管理机构可以决定延长期限，但最长不得超过6个月","证券公司经停业整顿在规定期限内仍达不到正常经营条件，但能够清偿到期债务的，可以向证监会申请行政重组","证券公司经行政重组在规定期限内达到正常经营条件的，经证监会批准，可以恢复正常经营"],"answer":"A","explain":"证券公司分类评价首先设定正常经营的证券公司基准分为100分。"},{"id":"real-law-24","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券公司分类评价规定》，证券公司分类监管评价设定正常经营的证券公司基准分为（）","options":["100分","120分","80分","90分"],"answer":"C","explain":"选项C正确：流动性风险，是指证券公司无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求的风险。选项A错误：声誉风险是指由于证券经营机构行为或外部事件及其工作人员违反廉洁规定、职业道德、业务规范、行规行约等相关行为，导致投资者、发行人、监管机构、自律组织、社会公众、媒体等对证券公司形成负面评价，从而损害其品牌价值，不利其正常经营，甚至影响到市场稳定和社会稳定的风险。选项B错误：信用风险指因融资方、交易对手或发行人等违约导致损失的风险。选项D错误：操作风险是指由不完善或有问题的内部程序、人员、信息技术系统，以及"},{"id":"real-law-25","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"证券公司无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求的风险是（）。","options":["声誉风险","信用风险","流动性风险","操作风险"],"answer":"B","explain":"行为层包括平衡各方利益、建立长效激励、加强声誉约束、落实责任担当四个要素。平衡各方利益，是指在经营管理的各个环节，充分识别和考虑所有利益相关者的利益，有效管理各类利益冲突。平衡利益是证券公司实现稳健经营的基础（B错误）。长效激励是落实文化建设的重要途径（C正确）。声誉约束是文化建设的有力保障（A正确）。落实责任担当是文化建设的重要抓手（D正确）。"},{"id":"real-law-26","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券行业文化建设十要素》，下列关于证券行业文化建设的说法，错误的是（）","options":["声誉约束是文化建设的有力保障","利益最大化是证券公司实现稳健经营的基础","长效激励是落实文化建设的重要途径","落实责任担当是文化建设的重要抓手"],"answer":"D","explain":"选项D正确：操纵证券、期货市场罪，是指有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量：(1)单独或者合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买卖；(2)与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易；(3)在自己实际控制的账户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的；(4)不以成交为目的，频繁或者大量申报买入、卖出证券、期货合约并撤销申报；(5)利用虚假或者不确定的重大信息，诱导投资者进行证券、期货交易；(6)对证券、证券发行人、期货交易标的公开作出评价、预测或者投资建议，同时进行反向证券交易或者相关期货交易；(7)以其他方法操纵证券、期货市场的。选项A错误：利用未公开信息交易罪是指金融机构从业人员等利用因职务便利获取的内幕信息以外的其他未公开信息，从事相关交易或明示、暗示他人从事相关交易的行为，与题干中自买自卖的行为不符。选项B错误：骗投资者买卖证券罪是指特定主体故意提供虚假信息或者伪造、变造、销毁交易记录，诱骗投资者买卖证券，造成严重后果的行为，题干中甲并未实施提供虚假信息诱骗他人的行为。选项C错误：内幕交易罪是指内幕信息的知情人或非法获取内幕信息的人，在涉及证券的发行、交易或者其他对证券的价格有重大影响的信息公开前，买卖该证券或泄露该信息等行为。"},{"id":"real-law-27","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"甲在不同证券公司以不同身份开设了十余个账户，并且以自己为交易对象，自买自卖相关股票，严重影响上述股票的价格，获得巨大非法收益。则甲的行为构成（）罪。","options":["利用未公开信息交易","诱骗消费者购买证券","内幕交易","操纵证券市场"],"answer":"B","explain":"选项B正确：具备证券自营业务资格的证券公司可以从事金融衍生产品交易，不具备证券自营业务资格的证券公司只能以对冲风险为目的，从事金融衍生产品交易。选项A错误：经纪业务资格是指证券公司接受客户委托，代理客户买卖证券的业务资格，与以对冲风险为目的从事金融衍生产品交易无关。选项C错误：资产管理业务资格是指证券公司作为资产管理人，依法为客户提供证券及其他金融产品的投资管理服务的业务资格选项D错误：承销业务资格是指证券公司代理证券发行人发行证券的业务资格"},{"id":"real-law-28","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"不具备（）的证券公司只能以对冲风险为目的，从事金融衍生产品交易。","options":["经纪业务资格","证券自营业务资格","资产管理业务资格","承销业务资格"],"answer":"C","explain":"选项C错误：证券基金经营机构应当履行主动管理职责，自主作出投资决策，不得委托提供港股投资顾问服务的中国香港机构直接执行投资指令。证券基金经营机构作为基金管理人依法应当承担的责任不因委托而免除。选项ABD说法正确。"},{"id":"real-law-29","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券法》，下列关于证券交易行为的说法，错误的是（）。","options":["任何单位和个人不得违反规定，出借自己的证券账户或者借用他人的证券账户从事证券交易","禁止任何单位和个人编造、传播虚假信息或者误导性信息，扰乱证券市场","依法拓宽资金入市渠道，禁止资金违规流入股市","禁止投资者以任何方式利用财政资金、银行信贷资金、银行理财资金买卖证券"],"answer":"D","explain":"选项D错误：依法拓宽资金入市渠道，禁止资金违规流入股市。禁止投资者违规利用财政资金、银行信贷资金买卖证券。（未禁止利用银行理财资金买卖证券）选项ABC说法正确。答案：D解析：选项D正确：关键信息变更：投资者姓名或名称、有效身份证明文件类型及号码三项为关键信息。对于上述关键信息的变更，投资者应通过临柜、见证等方式办理。选项ABC为非关键信息。"},{"id":"real-law-30","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《中国证券登记结算有限责任公司证券账户管理规则》，下列信息变更属于客户关键信息变更的是（）","options":["投资者交易设备的变更","投资者联系方式的变更","投资者住所的变更","投资者姓名的变更"],"answer":"C","explain":"选项C正确：根据《证券投资基金法》第四十五条的规定，公开募集基金的运作方式可以采用封闭式、开放式或者其他方式。选项AB错误：采用封闭式运作方式的基金（以下简称'封闭式基金'），是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金。采用开放式运作方式的基金（以下简称'开放式基金'），是指基金份额总额不固定，基金份额可以在基金合同约定的时间和场所申购或者赎回的基金。选项D错误：投资者对封闭式基金份额的买卖，只能根据基金份额上市交易规则，委托证券公司在证券交易所完成交易。而开放式基金的基金份额的申购、赎回、登记，由基金管理人或者其委托的基金服务机构办理。"},{"id":"real-law-31","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于公募基金运作方式的说法，正确的是（）","options":["封闭式基金的基金合同期限不是固定的，开放式基金合同的期限是固定的","封闭式基金是指基金份额总额不固定，基金份额可以在基金合同约定的时间和场所申购或者赎回的基金","公募基金的运作方式可以采用封闭式、开放式或其他方式","投资者对开放式基金的买卖，只能根据基金份额上市交易规则，委托证券公司在证券交易所完成交易"],"answer":"D","explain":"管理人、托管人应当在每年4月30日之前向资产支持证券合格投资者披露上年度资产管理报告、年度托管报告。"},{"id":"real-law-32","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据资产支持证券信息披露的规定，管理人、托管人应当在每年（）之前向资产支持证券合格投资者披露上年度资产管理报告、年度托管报告。","options":["3月31日","1月31日","6月30日","4月30日"],"answer":"C","explain":"证券公司应确定可能影响公司声誉的风险来源，全面、系统、持续地收集和识别相关内外部信息，重点关注以下行为活动中可能引发声誉风险的驱动因素：(1)战略规划或调整、股权结构变动、内部组织机构调整或核心人员变动；（B包括）(2)业务投资活动及产品、服务的设计、提供或推介；(3)内部控制设计、执行及系统控制的重大缺陷或重大经营损失事件；（C不包括）(4)司法性事件及监管调查、处罚；(5)新闻媒体的不实报道或网络不实言论；(6)股东、关联方或其他利益相关方发生声誉事件传导至证券公司；（D包括）(7)客户投诉及其涉及证券公司的不当言论或行为；(8)工作人员出现不当言论或行为，违反廉洁规定、职业道德、业务规范、行规行约等相关行为；(9)他人仿冒公司名称、商标、网址等侵权或误导公众行为；（A包括）(10)其他可能引发公司声誉风险的重要因素。"},{"id":"real-law-33","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券公司声誉风险管理指引》，证券公司重点关注的可能引发声誉风险的驱动因素，不包括（）","options":["他人仿冒公司名称、商标、网址等侵权或误导公众行为","战略规划或调整、股权结构变动、内部组织机构调整或核心人员变动","内部控制设计、执行及系统控制的轻微缺陷或一般经营损失事件","股东、关联方或其他利益相关方发生声誉事件传导至证券公司"],"answer":"A","explain":"声誉风险管理应遵循全程全员原则、预防第一原则（D）、审慎管理原则（C）、快速响应原则（B）。题目问的是“不属于”。故本题选A。"},{"id":"real-law-34","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券公司声誉风险管理指引》，下列不属于声誉风险管理应遵循的原则的是（）","options":["从高层做起原则","快速响应原则","审慎管理原则","预防第一原则"],"answer":"A","explain":"选项A正确：中国人民银行依法对金融债券的发行进行监督管理。选项B错误：中国证券业协会是证券业的自律性组织，主要负责证券行业的自律管理。"},{"id":"real-law-35","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"某证券公司拟在银行间债券市场发行金融债券，对于其发行进行监督管理的是（）","options":["中国人民银行","证券业协会","国家发展改革委","交易商协会"],"answer":"B","explain":"选项B正确：证券代销，是指证券公司代发行人发售证券，在承销期结束时，将未售出的证券全部退还给发行人的承销方式。选项A错误：证券包销，是指证券公司将发行人的证券按照协议全部购入，或者在承销期结束时将售后剩余证券全部自行购入的承销方式。选项C错误：\"自行销售\"不是《证券法》规定的承销方式。选项D错误：\"余额包销\"属于包销的一种，是在承销期结束时将售后剩余证券全部自行购入，而非退还给发行人。"},{"id":"real-law-36","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券法》，证券公司在承销期结束时，将未售出的证券全部退还给发行人的承销方式是（）。","options":["全额包销","代销","自行销售","余额包销"],"answer":"C","explain":"根据《最高人民检察院、公安部关于公安机关管辖的刑事案件立案追诉标准的规定(二)》第三十五条规定，涉嫌下列情形之一的，应予立案追诉：(1)擅自运用客户资金或者其他委托、信托的财产数额在30万元以上的；（C正确，B错误）(2)虽未达到上述数额标准，但多次擅自运用客户资金或者其他委托、信托的财产，或者擅自运用多个客户资金或者其他委托、信托的财产的；（AD错误）(3)其他情节严重的情形。"},{"id":"real-law-37","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于背信运用受托财产罪的刑事追诉标准的说法，正确的是（）","options":["本罪即使行为人擅自运用多个客户资金，如果涉案金额达不到标准，也不满足刑事追诉的标准","本罪即使涉案金额达不到标准，若涉及国有资产，也满足刑事追诉的标准","本罪的刑事追诉标准跟具体涉案金额相关","本罪即使行为人多次擅自运用客户资金，如果涉案金额达不到标准，也不满足刑事追诉的标准"],"answer":"ABC","explain":"选项ABC正确，选项D错误：内部控制应当贯彻的原则包括健全、合理、制衡、独立。"},{"id":"real-law-38","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"证券公司内部控制原则是（）。","options":["健全","合理","制衡","审慎"],"answer":"ABCD","explain":"选项D正确：根据《证券法》第一百一十八条的规定，设立证券公司，应当具备相应条件，并经国务院证券监督管理机构批准。选项ABC正确：证券公司合并、分立、停业、解散、破产，应当经国务院证券监督管理机构核准。"},{"id":"real-law-39","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"以下需要证监会审核批准有（）。","options":["证券公司分立","证券公司破产","证券公司合并","证券公司设立"],"answer":"AC","explain":"选项A正确，选项B错误：有限合伙人转变为普通合伙人的，对其作为有限合伙人期间有限合伙企业发生的债务承担无限连带责任。选项C正确，选项D错误：普通合伙人转变为有限合伙人的，对其作为普通合伙人期间合伙企业发生的债务承担无限连带责任。"},{"id":"real-law-40","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"关于合伙企业，下列说法正确的是（）。","options":["有限合伙人转变为普通合伙人，其在有限合伙人期间承担无限连带责任","有限合伙人转变为普通合伙人，其在有限合伙人期间承担有限责任","普通合伙人转变为有限合伙人，其在普通合伙人期间承担无限连带责任","普通合伙人转变为有限合伙人，其普通合伙人期间承担有限责任"],"answer":"BCD","explain":"合伙企业有下列情形之一的，应当解散：（1）合伙期限届满，合伙人决定不再经营；（C正确）（2）合伙协议约定的解散事由出现；（3）全体合伙人决定解散；（A错误）（4）合伙人已不具备法定人数满30天；（B正确）（5）合伙协议约定的合伙目的已经实现或者无法实现；（6）依法被吊销营业执照（D正确）、责令关闭或者被撤销；"},{"id":"real-law-41","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"合伙企业有下列（）情形之一的，应当解散。","options":["2/3合伙人决定解散","合伙人已不具备法定人数满30天","合伙期限届满，合伙人决定不再经营","依法被吊销营业执照"],"answer":"ABC","explain":"选项ABC正确，选项D错误：《证券期货投资者适当性管理办法》要求经营机构在向投资者销售证券期货产品或者提供证券期货服务的过程中，应当遵守法律法规及其他有关规定，勤勉尽责，审慎履职，全面了解投资者情况，深入调查分析产品或者服务信息，科学有效评估，充分揭示风险，基于投资者的不同风险承受能力以及产品或者服务的不同风险等级等因素，提出明确的适当性匹配意见，将适当的产品或者服务销售或者提供给适合的投资者，并对违法违规行为承担法律责任。"},{"id":"real-law-42","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"证券公司经营证券经纪业务，需建立客户适当性管理，要求包含（）。","options":["了解客户风险承受能力","匹配对应风险等级产品","充分揭示投资风险","向高风险承受客户强制购买衍生品"],"answer":"ABC","explain":"选项ABC正确，选项D错误：证券交易内幕信息的知情人和非法获取内幕信息的人，在内幕信息公开前，不得买卖该公司的证券，或者泄露该信息，或者建议他人买卖该证券。内幕交易行为给投资者造成损失的，行为人应当依法承担赔偿责任。"},{"id":"real-law-43","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"内幕交易禁止行为包含（）。","options":["内幕信息公开前买卖标的证券","泄露内幕信息给他人","利用内幕信息建议他人交易","信息公开后正常交易"],"answer":"ACD","explain":"根据《证券经纪人管理暂行规定》，证券经纪人不得有下列行为：(1)替客户办理账户开立、注销、转移，证券认购、交易或者资金存取、划转、查询等事宜；(2)提供、传播虚假或者误导客户的信息，或者诱使客户进行不必要的证券买卖；（C正确）(3)与客户约定分享投资收益，对客户证券买卖的收益或者赔偿证券买卖的损失作出承诺；(4)采取贬低竞争对手、进入竞争对手营业场所劝导客户等不正当手段招揽客户；(5)泄露客户的商业秘密或者个人隐私；(6)为客户之间的融资提供中介、担保或者其他便利；（A正确）(7)为客户提供非法的服务场所或者交易设施，或者通过互联网络、新闻媒体从事客户招揽和客户服务等活动；(8)委托他人代其从事客户招揽和客户服务等活动；（B错误）(9)损害客户合法权益或者扰乱市场秩序的其他行为。选项D正确：证券经纪人可以向客户介绍证券投资的基本知识及开户、交易、资金存取等业务流程。"},{"id":"real-law-44","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券经纪人管理暂行规定》，下列关于证券经纪人执业行为的说法，正确的有（）。","options":["证券经纪人不得为客户之间的融资提供中介、担保或者其他便利","证券经纪人可以委托他人代理其从事客户招揽和客户服务等活动","证券经纪人不得提供、传播虚假或者误导客户的信息，或者诱使客户进行不必要的证券买卖","证券经纪人可以向客户介绍证券投资的基本知识及开户、交易、资金存取等业务流程"],"answer":"ABD","explain":"选项ABD正确：《证券期货投资者适当性管理办法》要求经营机构在向投资者销售证券期货产品或者提供证券期货服务的过程中，应当遵守法律法规及其他有关规定，勤勉尽责，审慎履职，全面了解投资者情况，深入调查分析产品或者服务信息，科学有效评估，充分揭示风险，基于投资者的不同风险承受能力以及产品或者服务的不同风险等级等因素，提出明确的适当性匹配意见，将适当的产品或者服务销售或者提供给适合的投资者，并对违法违规行为承担法律责任。选项C错误：差异性原则。经营机构应当对投资者进行分类管理，对普通投资者和专业投资者实施差别的适当性管理措施，履行不同的适当性义务。"},{"id":"real-law-45","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于证券经营机构及其工作人员落实投资者适当性管理的说法，正确的有（）。","options":["充分揭示风险","深入调查分析产品或者服务信息","实施相同的适当性管理措施","全面了解投资者情况"],"answer":"BD","explain":"根据《证券公司风险控制指标计算标准规定》，证券公司经营自营业务，其持仓规模必须符合下列规定:"},{"id":"real-law-46","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于证券公司经纪业务保障投资者交易的安全与连续的说法，错误的有（）。","options":["证券公司应当将投资者的证券和资金与自有财产分别管理，中国结算、投保基金公司监控投资者证券和资金安全保管情况","证券公司为保障投资者信息安全和交易连续性，分支机构均应当提供现场交易服务","证券公司应当根据投资者委托，托管投资者证券和资金，保证投资者资产安全","证券公司应当明确委托指令接收、排序、处理的相关要求，优先保证专业投资者"],"answer":"ABCD","explain":"(一)业务协同证券公司应当根据业务种类、区域布局、市场环境和自身并表管理能力，科学进行经营决策，不断提升证券公司并表管理体系综合服务能力和核心竞争力，促进高质量发展。(二)同业竞争证券公司应当统筹规划附属经营机构定位，确保各附属机构有明确的经营目标和市场定位，避免证券公司并表管理体系内部业务混同操作（D正确）。(三)风险隔离证券公司应当在并表管理体系内建立并持续完善内部隔离墙及利益冲突体系，通过审慎隔离业务、人员和信息等措施，有效防范金融风险在并表管理体系内部无序传递和跨区域、跨市场、跨境传染（A正确）。(四)数据获取证券公司可基于并表管理的合理需要，依法依规在并表管理体系范围内采集和运用并表管理所需数据（B正确）。(五)内部交易管理并表管理体系内部交易包括但不限于证券公司与其附属机构、附属机构之间的金融市场交易及衍生交易、资金拆借(借款、融资融券、回购等)、贷款、担保、交叉持股、资产转让等。证券公司应当对并表管理体系内部交易进行并表管理，充分关注潜在利益输送、虚增资本、转移收入、风险传染、监管套利和其他对证券公司并表管理体系稳健经营可能产生的负面影响（C正确）。"},{"id":"real-law-47","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于证券公司及相关从业人员从事私募资产管理业务的行为，属于禁止行为的有（）。","options":["以获取佣金为目的，使用资产管理计划财产进行不必要的交易","产品净值大幅度回撤后向持有产品的投资者解释说明","间接向投资者返还管理费","为规避监管的证券期货活动提供交易便利"],"answer":"ACD","explain":"选项ACD正确：证券公司应当构建网络和信息安全防护体系，综合采取网络隔离、用户认证、访问控制、策略管理、数据加密、网站防篡改、病毒木马防范、非法入侵检测和网络安全态势感知等安全保障措施，提升网络和信息安全防护能力，及时识别、阻断相关网络攻击，保护重要信息系统和相关基础设施，防范信息泄露与损毁。选项B错误：证券公司应当\"保护重要信息系统和相关基础设施\"，\"打通交易网段和办公网段\"会削弱网络隔离，增加安全风险。"},{"id":"real-law-48","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券期货业网络和信息安全管理办法》，证券公司构建网络和信息安全防护体系，可采取的安全保障措施有（）。","options":["病毒木马防范","打通交易网段和办公网段","用户认证","数据加密"],"answer":"ABCD","explain":"选项ABCD正确：证券公司在设立时的业务范围应当与其财务状况、内部控制制度、合规制度和人力资源状况相适应。"},{"id":"real-law-49","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"证券公司设立时，其业务范围应当与其（）相适应。","options":["内部控制制度","财务状况","合规制度","人力资源状况"],"answer":"ACD","explain":"有《公司法》第一百七十八条规定的情形或者下列情形之一的，不得担任证券交易所的负责人：一是因违法行为或者违纪行为被解除职务的证券交易场所、证券登记结算机构的负责人或者证券公司的董事、监事、高级管理人员，自被解除职务之日起未逾5年；二是因违法行为或者违纪行为被吊销执业证书或者被取消资格的律师、注册会计师或者其他证券服务机构的专业人员，自被吊销执业证书或者被取消资格之日起未逾5年。因违法行为或者违纪行为被开除的证券交易场所、证券公司、证券登记结算机构、证券服务机构的从业人员和被开除的国家机关工作人员，不得招聘为证券交易所的从业人员。ACD三项未逾5年，不得担任证券交易所的负责人，B项已逾5年，不受限制。"},{"id":"real-law-50","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于期货交易所负责人任命的说法，错误的有（）。","options":["2014年8月因违纪行为被撤销资格的律师李某，2018年3月可任命为某期货交易所负责人","2012年5月因违法行为被解除职务的证券公司董事王某，2018年4月可任命为某期货交易所负责人","2015年4月因违纪行为被解除职务的交易所负责人张某，2018年10月可任命为某期货交易所负责人","2016年3月因违法行为被撤销资格的注册会计师赵某，2018年9月可任命为某期货交易所负责人"],"answer":"ABC","explain":""},{"id":"real-law-51","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《期货和衍生品法》，下列关于我国期货结算与交割的说法，正确的有（）。","options":["期货交易实行当日无负债结算制度","结算参与人收取的权利金，在期货保证金存管机构专户存放","在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算","期货结算机构有权对任意交易者的标准仓单等合约标的物权利凭证进行处置"],"answer":"ABC","explain":"选项AC正确：期货交易实行当日无负债结算制度。在期货交易场所规定的时间，期货结算机构应当在当日按照结算价对结算参与人进行结算。选项B正确：期货结算机构、结算参与人收取的保证金、权利金等，应当与其自有资金分开，按照国务院期货监督管理机构的规定，在期货保证金存管机构专户存放，分别管理，禁止违规挪用。选项D错误：结算参与人在交割过程中违约的，期货结算机构有权对结算参与人的标准仓单等合约标的物权利凭证进行处置。答案：A,B,C解析：选项ABC正确：禁止任何人以下列手段操纵证券市场，影响或者意图影响证券交易价格或者证券交易量：(1)单独或者通过合谋，集中资金优势、持股优势或者利用信息优势联合或者连续买卖；(2)与他人串通，以事先约定的时间、价格和方式相互进行证券交易；(3)在自己实际控制的账户之间进行证券交易；(4)不以成交为目的，频繁或者大量申报并撤销申报；(5)利用虚假或者不确定的重大信息，诱导投资者进行证券交易；(6)对证券、发行人公开作出评价、预测或者投资建议，并进行反向证券交易；(7)利用在其他相关市场的活动操纵证券市场；(8)操纵证券市场的其他手段。选项D错误：\"出借自己的证券账户或者借用他人的证券账户从事证券交易\"属于\"其他禁止的交易行为\"，而非\"操纵证券市场行为\"。"},{"id":"real-law-52","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券法》，下列属于操纵证券市场行为的有（）。","options":["不以成交为目的，频繁或者大量申报并撤销申报","利用虚假或者不确定的重大信息，诱导投资者进行证券交易","对证券、发行人公开作出评价、预测或者投资建议，并进行反向证券交易","出借自己的证券账户或者借用他人的证券账户从事证券交易"],"answer":"ABCD","explain":"选项ABCD正确：证券投资顾问不得从事下列活动：(1)以任何方式向客户承诺或者保证投资收益；(2)对服务能力和过往业绩进行虚假、不实、误导性的营销宣传；(3)向他人泄露客户的投资决策计划信息；(4)以个人名义向客户收取证券投资顾问服务费用；(5)通过广播、电视、网络、报刊等公众媒体作出买入、卖出或者持有具体证券的投资建议。"},{"id":"real-law-53","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"证券投资顾问应当遵循诚实信用原则，勤勉、审慎地为客户提供证券投资顾问服务。证","options":["以任何方式向客户承诺或保证投资收益","以个人名义向客户收取证券投资顾问服务费用","通过网络等公众媒体作出买入具体证券的投资建议","向他人泄露客户的投资决策计划信息"],"answer":"ACD","explain":""},{"id":"real-law-54","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"关于操纵证券期货市场的刑事责任，下列说法正确的有（）。","options":["本罪的主观方面为故意","本罪的主体为一般主体，单位不能成为本罪的犯罪主体","本罪的主体是一般主体，凡达到刑事责任年龄并具有刑事责任能力的自然人均可成为本罪主体","本罪侵害了国家证券、期货管理制度和投资者的合法权益"],"answer":"ABD","explain":"证券交易所应当从其收取的交易费用和会员费、席位费中提取一定比例的金额设立风险基金（B正确）。风险基金由证券交易所理事会管理（C错误）。风险基金提取的具体比例和使用办法，由国务院证券监督管理机构会同国务院财政部门规定。（A正确）证券交易所应当将收存的风险基金存入开户银行专门账户，不得擅自使用。（D正确）"},{"id":"real-law-55","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券法》，下列关于证券交易所风险基金的说法，正确的有（）。","options":["风险基金提取的具体比例和使用办法，由国务院证券监督管理机构会同国务院财政部门规定","证券交易所应当从其收取的交易费用和会员费、席位费中提取一定比例的金额设立风险基金","证券交易所的风险基金由证券交易所监事会管理","证券交易所应当将收存的风险基金存入开户银行专门账户，不得擅自使用"],"answer":"CD","explain":"选项C正确：基金财产独立于基金管理人、基金托管人的固有财产。基金管理人、基金托管人不得将基金财产归入其固有财产。选项D正确：基金财产的债务由基金财产本身承担，基金份额持有人以其出资为限对基金财产的债务承担责任。但基金合同依照《证券投资基金法》另有约定的，从其约定。非因基金财产本身承担的债务，不得对基金财产强制执行。非因投资人本身的债务或者法律规定的其他情形，不得查封、冻结、扣划或者强制执行基金销售结算资金、基金份额。选项A错误：基金财产的债权，不得与基金管理人、基金托管人固有财产的债务相抵销；不同基金财产的债权债务，不得相互抵销。选项B错误：基金管理人、基金托管人因依法解散、被依法撤销或者被依法宣告破产等原因进行清算的，基金财产不属于其清算财产。"},{"id":"real-law-56","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券投资基金法》，下列关于基金财产独立性要求的说法，正确的有（）。","options":["基金财产的债权，可以与基金管理人、基金托管人固有财产的债务相抵销","基金管理人、基金托管人因依法解散、被依法撤销或者被依法宣告破产等原因进行清算的，基金财产属于其清算财产","基金管理人、基金托管人不得将基金财产归入其固有财产","非因基金财产本身承担的债务，不得对基金财产强制执行"],"answer":"AC","explain":"选项A正确，选项B错误：股份有限公司的设立，可以采取发起设立或者募集设立的方式。发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。募集设立，是指由发起人认购设立公司时应发行股份的一部分，其余股份向社会公开募集或者向特定对象募集而设立公司。选项C正确：设立股份有限公司，应当由发起人共同制定公司章程。选项D错误：以募集设立方式设立股份有限公司的，发起人认购的股份不得少于公司章程规定的公司设立时应发行股份总数的35%。"},{"id":"real-law-57","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《公司法》有关规定，下列关于股份有限公司设立的说法，正确的有（）。","options":["股份有限公司的设立可以采取发起设立或者募集设立的方式","股份有限公司初始设立时可以向战略投资者募集股份，但不可以向社会公开募集","设立股份有限公司，应当由发起人共同制定公司章程","发起人认购股份有限公司设立时的股份最低不应低于股份总数的50%"],"answer":"ABCD","explain":"选项A正确：禁止任何单位和个人编造、传播虚假信息或者误导性信息，扰乱证券市场。选项BCD正确：禁止证券交易场所、证券公司、证券登记结算机构、证券服务机构及其从业人员，证券业协会、证券监督管理机构及其工作人员，在证券交易活动中作出虚假陈述或者信息误导。各种传播媒介传播证券市场信息必须真实、客观，禁止误导。传播媒介及其从事证券市场信息报道的工作人员不得从事与其工作职责发生利益冲突的证券买卖。编造、传播虚假信息或者误导性信息，扰乱证券市场，给投资者造成损失的，应当依法承担赔偿责任。"},{"id":"real-law-58","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券法》，下列关于禁止虚假陈述、信息误导行为的说法，正确的有（）。","options":["禁止证券交易场所、证券公司、证券登记结算机构、证券服务机构及其从业人员，在证券交易活动中作出虚假陈述或者信息误导","禁止任何单位和个人编造、传播虚假信息或者误导性信息，扰乱证券市场","各种传播媒介传播证券市场信息必须真实、客观，禁止误导","禁止证券业协会、证券监督管理机构及其工作人员，在证券交易活动中作出虚假陈述或者信息误导"],"answer":"AD","explain":"选项A不属于：\"组织制定公司规章制度\"是经营管理主要负责人（而非全体工作人员）的职责。选项D不属于：建立与合规负责人的直接沟通机制是董事会职责。选项BC属于：全体工作人员的合规管理职责包括：（1）主动了解、掌握和遵守相关法律、法规和准则；（2）积极参加公司安排的合规培训和合规宣导活动；（3）根据公司要求，签署并信守相关合规承诺；（4）在执业过程中充分关注执业行为的合法合规性；（5）在业务开展过程中主动识别和防范业务合规风险；（6）发现违法违规行为或者合规风险隐患时，应当主动按照公司规定及时报告；（7）出现合规风险事项时，积极配合公司调查，并接受公司问责，落实整改要求。"},{"id":"real-law-59","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"以下不属于全体工作人员合规管理职责的有（）。","options":["组织制定公司规章制度","在业务开展过程中主动识别和防范业务合规风险","根据公司要求，签署并信守相关合规承诺","建立与合规负责人的直接沟通机制券投资顾问不得从事的活动有（）。"],"answer":"ABCD","explain":"选项ABCD正确：廉洁从业，是指证券期货经营机构及其工作人员在开展证券期"},{"id":"real-law-60","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券期货经营机构及其工作人员廉洁从业规定》，下列关于廉洁从业的说法，正确的有（）。","options":["公平竞争，合规经营，忠实勤勉，诚实守信","严格遵守法律法规、中国证监会的规定和行业自律规则","不直接或者间接向他人输送不正当利益或者谋取不正当利益","遵守社会公德、商业道德、职业道德和行为规范"],"answer":"ABD","explain":"选项ABD正确：声誉风险是指由于证券经营机构行为或外部事件及其工作人员违反廉洁规定、职业道德、业务规范、行规行约等相关行为，导致投资者、发行人、监管机构、自律组织、社会公众、媒体等对证券公司形成负面评价，从而损害其品牌价值，不利其正常经营，甚至影响到市场稳定和社会稳定的风险。选项C错误：客户违约导致仲裁机构作出不利于客户的裁决，并未导致相关方对证券公司形成负面评价。"},{"id":"real-law-61","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券公司声誉风险管理指引》，下列关于声誉风险的说法，正确的有（）。","options":["由于证券公司外部事件，导致社会公众对证券公司形成负面评价的风险是声誉风险","由于证券公司行为，导致监管机构对证券公司形成负面评价的风险是声誉风险","由于客户违约，导致仲裁机构作出不利于客户裁决的风险是声誉风险","由于证券公司工作人员违反职业道德，导致媒体对证券公司形成负面评价的风险是声誉风险"],"answer":"ABC","explain":"选项ABC正确，选项D错误：根据《证券公司监督管理条例》第六十九条的规定，证券公司以及有关单位和个人披露、报送或者提供的资料、信息应当真实、准确、完整，不得有虚假记载、误导性陈述或者重大遗漏。"},{"id":"real-law-62","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券公司监督管理条例》，证券公司以及有关单位和个人披露、报送或者提供的资料、信息应当（），不得有虚假记载、误导性陈述或者重大遗漏。","options":["准确","真实","完整","全面"],"answer":"ACD","explain":"选项AC正确，选项B错误：证券公司应当清晰、准确、完整地掌握重要信息系统的技术架构、业务逻辑和操作流程等内容，确保重要信息系统运行始终处于自身控制范围。除法律法规及中国证监会另有规定外，不得将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施。选项D正确：证券公司借助信息技术手段从事证券基金业务活动的，可以委托信息技术服务机构提供产品或服务，但证券公司依法应当承担的责任不因委托而免除或减轻。"},{"id":"real-law-63","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司委托信息技术服务机构提供产品或服务的说法，正确的有（）","options":["证券公司应当清晰、准确、完整地掌握重要信息系统的技术架构、业务逻辑和操作流程等内容","除法律法规及中国证监会另有规定外，可以将重要信息系统的运维、日常安全管理交由信息技术服务机构独立实施","证券公司应确保重要信息系统运行始终处于自身控制范围","证券公司可以委托信息技术服务机构提供产品或服务，但其依法应当承担的责任不因委托而免除或减轻"],"answer":"CD","explain":"选项CD正确，选项B错误：公司董事、监事、高级管理人员应当向公司申报所持有的本公司的股份及其变动情况，在就任时确定的任职期间每年转让的股份不得超过其所持有本公司股份总数的25%；所持本公司股份自公司股票上市交易之日起1年内不得转让。上述人员离职后半年内，不得转让其所持有的本公司股份。公司章程可以对公司董事、监事、高级管理人员转让其所持有的本公司股份作出其他限制性规定。选项A错误：公司公开发行股份前已发行的股份，自公司股票在证券交易所上市交易之日起一年内不得转让。法律、行政法规或者国务院证券监督管理机构对上市公司的股东、实际控制人转让其所持有的本公司股份另有规定的，从其规定。"},{"id":"real-law-64","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《公司法》，下列关于股份有限公司股份转让限制的说法，正确的有（）","options":["公司公开发行股份前已发行股份，自公司股票在证券交易所上市交易之日起三年内不得转让","公司董事、监事、高级管理人员离职后一年内，不得转让其所持有的本公司股份","公司董事、监事、高级管理人员所持本公司股份，自公司股票上市交易之日起一年内不得转让","公司董事、监事、高级管理人员在任职期间每年转让的股份，不得超过其所持有本公司股份总数的百分之二十五"],"answer":"AB","explain":"根据《证券投资基金法》第二十条、第一百二十三条的规定，基金管理人、基金托管人及其董事、监事、高级管理人员和其他从业人员不公平地对待其管理的不同基金财产的，责令改正，没收违法所得，并处违法所得1倍以上5倍以下罚款；没有违法所得或者违法所得不足100万元的，并处10万元以上100万元以下罚款；基金管理人、基金托管人有上述行为的，还应当对其直接负责的主管人员和其他直接责任人员给予警告，暂停或者撤销基金从业资格，并处3万元以上30万元以下罚款。"},{"id":"real-law-65","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券投资基金法》，下列关于基金管理人、基金托管人及其董事、监事、高级管理人员和其他从业人员不公平地对待其管理的不同基金财产的法律责任，正确的有（）。","options":["责令改正，没收违法所得，并处违法所得一倍以上五倍以下罚款","没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款","没有违法所得或者违法所得不足一百万元的，并处五十万元以上一百万元以下罚款","责令改正，没收违法所得，并处违法所得一倍以上三倍以下罚款"],"answer":"ABCD","explain":"选项A正确：证券公司从事融资融券业务，必须遵守法律法规，不得违反规定向客户出借资金或者证券，以防范和控制业务风险。"},{"id":"real-law-66","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于证券公司及其境内分支机构经营业务的说法，正确的有（）","options":["证券公司从事证券融资融券业务，不得违反规定向客户出借资金或者证券","证券公司经营证券资产管理业务的，应当符合《中华人民共和国证券投资基金法》等法律法规的规定","未取得经营证券业务许可证，证券公司不得经营证券业务","证券公司必须将其证券自营业务和证券资产管理业务分开办理，不得混合操作"],"answer":"ACD","explain":"选项ACD正确：依法发行的证券，《公司法》和其他法律对其转让期限有限制性规定的，在限定的期限内不得转让。上市公司持有5%以上股份的股东、实际控制人、董事、监事、高级管理人员，以及其他持有发行人首次公开发行前发行的股份或者上市公司向特定对象发行的股份的股东，转让其持有的本公司股份的，不得违反法律、行政法规和国务院证券监督管理机构关于持有期限、卖出时间、卖出数量、卖出方式、信息披露等规定，并应当遵守证券交易所的业务规则。选项B错误：非公开发行的证券，可以在证券交易所、国务院批准的其他全国性证券交易场所、按照国务院规定设立的区域性股权市场转让。"},{"id":"real-law-67","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券法》，下列关于证券转让的说法，正确的有（）","options":["上市公司董事、监事、高级管理人员转让其持有的本公司股份的，应当遵守证券交易所的业务规则","非公开发行的证券，不可以在证券交易所、国务院批准的其他全国性证券交易场所转让","上市公司持有百分之五以上股份的股东转让其持有的本公司股份的，不得违反法律、行政法规的规定","依法发行的证券，《公司法》对其转让期限有限制性规定的，在限定的期限内不得转让"],"answer":"BC","explain":"根据《证券期货投资者适当性管理办法》的要求，经营机构向投资者销售产品或者提供服务时，应当了解投资者的下列信息："},{"id":"real-law-68","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券期货投资者适当性管理办法》，下列关于经营机构向投资者销售产品或提供服务应了解的投资者信息，不属于规范要求的有（）","options":["法律法规、自律规则规定的投资者准入要求相关信息","收入来源和数额、资产、债务及家庭人均存款等财务状况","投资相关的学习、工作经历、投资经验、婚姻及子女状况","实际控制投资者的自然人和交易的实际受益人"],"answer":"ABC","explain":"选项A正确：证券公司从事私募资产管理业务，应当遵循自愿、公平、诚实信用和客户利益至上原则。选项B正确：证券公司从事私募资产管理业务，应当依法经中国证监会批准。选项C正确：证券公司应当遵守审慎经营规则，制定科学合理的投资策略和风险管理制度，有效防范和控制风险，确保业务开展与资本实力、管理能力及风险控制水平相适应。选项D错误：证券公司从事私募资产管理业务，应当实行集中运营管理，建立健全内部控制和合规管理制度，采取有效措施，将私募资产管理业务与公司其他业务分开管理。而非\"集中协同管理\"。"},{"id":"real-law-69","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"证券公司私募资产管理业务应当遵守的基本要求包括（）。","options":["应当遵循客户利益至上原则","证券公司从事私募资产管理业务，应当依法经中国证监会批准","应当遵守审慎经营规则","应当实行统一管理将私募资产管理业务与公司其他业务集中协同管理"],"answer":"ACD","explain":"选项A正确：证券公司从事私募资产管理业务，应当实行集中运营管理，建立健全内部控制和合规管理制度，采取有效措施，将私募资产管理业务与公司其他业务分开管理。"},{"id":"real-law-70","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于证券公司开展资产管理业务的做法，正确的有（）","options":["对私募资产管理业务实行集中运营管理，并将私募资产管理业务与公司其他业务分开管理","向客户做出保证其取得最低收益的承诺","与客户签订资产管理合同，约定收取管理费用","向客户说明，投资所产生的收益由客户享有，损失由客户承担"],"answer":"BCD","explain":"机构及其工作人员应当自觉遵守以下言行一致要求：（1）开展业务活动时，表达的信息应当真实、准确、完整（B正确），不对自身专业能力、执业经验及过往业绩进行夸张、虚假和误导性宣传（未禁止正常介绍，A错误）；（2）不利用虚假和误导性信息进行宣传（C正确），不编造传播虚假和误导性信息（D正确）。"},{"id":"real-law-71","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券行业诚信准则》，下列关于证券公司及其工作人员言行一致要求的说法，正确的有（）","options":["开展业务活动时，不得对自身专业能力、执业经验进行介绍","开展业务活动时，表达的信息应当真实、准确、完整","不利用虚假和误导性信息进行宣传","不编造传播虚假和误导性信息"],"answer":"ABD","explain":"证券的发行、交易活动，必须遵循公开、公平、公正'三公'原则。"},{"id":"real-law-72","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《证券法》，证券的发行、交易活动，必须遵循的原则包括（）。","options":["公平","公正","等价有偿","公开"],"answer":"BD","explain":"选项BD正确：股份有限公司的设立，可以采取发起设立或者募集设立的方式。发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。募集设立，是指由发起人认购设立公司时应发行股份的一部分，其余股份向社会公开募集或者向特定对象募集而设立公司。选项AC为干扰项。"},{"id":"real-law-73","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据《公司法》，股份有限公司可以采取的设立方式包含（）。","options":["认缴设立","募集设立","出资设立","发起设立"],"answer":"ACD","explain":"选项ACD正确：融资融券业务涉及的法律法规和准则包括：《证券法》《证券公司监督管理条例》《证券公司融资融券业务管理办法》《证券公司融资融券业务内部控制指引》《上海证券交易所融资融券交易实施细则》《深圳证券交易所融资融券交易实施细则》《北京证券交易所融资融券交易细则》等。"},{"id":"real-law-74","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"证券公司融资融券业务涉及的法律法规和准则包括（）。","options":["《证券公司融资融券业务管理办法》","《股票质押式回购交易及登记结算业务办法》","《证券法》","《证券公司监督管理条例》"],"answer":"ABCD","explain":"选项ABC正确：选项D正确：根据《最高人民检察院、公安部关于公安机关管辖的刑事案件立案追诉标准的规定(二)》第四十四条规定，以非法占有为目的，使用诈骗方法非法集资，数额在10万元以上的，应予立案追诉。"},{"id":"real-law-75","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于集资诈骗罪的说法，正确的有（）。","options":["集资诈骗罪的客体为国家金融管理秩序及公私财产所有权","集资诈骗罪的主观方面是故意，且以非法占有为目的","集资诈骗罪的犯罪主体为一般主体，包括自然人和单位","以非法占有为目的，使用诈骗方法非法集资，数额在10万元以上的，应予立案追诉1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对"],"answer":"A","explain":"普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护。"},{"id":"real-law-76","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"普通投资者应至少在信息告知、风险警示、适当性匹配三个方面享有特别保护。（）","options":["正确","错误"],"answer":"B","explain":"证券投资咨询人员必须具备下列条件：（1）具有中华人民共和国国籍；（2）具有完全民事行为能力；（3）品行良好、正直诚实，具有良好的职业道德；"},{"id":"real-law-77","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券投资咨询人员只需专科学历即可执业登记。（）","options":["正确","错误"],"answer":"A","explain":"采用封闭式运作方式的基金(以下简称“封闭式基金”)，是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金。"},{"id":"real-law-78","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《证券投资基金法》，采用封闭式运作方式的基金，是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金。（）","options":["正确","错误"],"answer":"A","explain":"根据《证券公司监督管理条例》第五十九条的规定，客户的交易结算资金、证券资产管理客户的委托资产属于客户，应当与证券公司、指定商业银行、资产托管机构的自有资产相互独立、分别管理。非因客户本身的债务或者法律规定的其他情形，任何单位或者个人不得对客户的交易结算资金、委托资产申请查封、冻结、扣划或者强制执行。"},{"id":"real-law-79","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《证券公司监督管理条例》，客户的交易结算资金、证券资产管理客户的委托资产属于客户，应当与证券公司、指定商业银行、资产托管机构的自有资产相互独立、分别管理。非因客户本身的债务或者法律规定的其他情形，任何单位或者个人不得对客户的交易结算资金、委托资产申请查封、冻结或者强制执行。（）","options":["正确","错误"],"answer":"B","explain":"根据《廉洁规定》及《细则》，证券经营机构及其工作人员在开展证券相关业务活动中，应当严格遵守《廉洁规定》及其他相关规定，不得谋取不正当利益或者向公职人员、客户、正在洽谈的潜在客户及其他利益关系人输送不正当利益，不得干扰或者唆使、协助他人干扰证券监督管理或者自律管理工作。"},{"id":"real-law-80","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券经营机构及其工作人员在开展证券相关业务活动中，可以向正在进行沟通的客户输送不正当利益。（）","options":["正确","错误"],"answer":"A","explain":"上市公司、公司债券上市交易的公司、股票在国务院批准的其他全国性证券交易场所交易的公司，应当按照国务院证券监督管理机构和证券交易场所规定的内容和格式编制定期报告，并按照以下规定报送和公告：（1）在每一会计年度结束之日起4个月内，报送并公告年度报告，其中的年度财务会计报告应当经符合《证券法》规定的会计师事务所审计；（2）在每一会计年度的上半年结束之日起2个月内，报送并公告中期报告。"},{"id":"real-law-81","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"上市公司年度报告需在每一会计年度结束之日起4个月内披露，中期报告需在每一会计.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对年度上半年结束之日起2个月内披露。（）","options":["正确","错误"],"answer":"A","explain":"资产证券化基础资产负面清单：（1）不符合地方政府性债务管理有关规定或者新增地方政府性债务的基础资产。（2）被有权部门认定的失信被执行人、失信生产经营单位、其他失信单位作为重要现金流提供方的基础资产。重要现金流提供方、重要子公司存在上述失信情形的，视同重要现金流提供方存在相关情形。（3）产生现金流的能力具有较大不确定性的资产，如矿产资源开采收益权、土地出让收益权、电影票款以及不具有垄断性和排他性的入园凭证等。（4）因空置、在建等原因不能产生稳定现金流的不动产、不动产租金债权或者相关收益权。（5）不能直接产生现金流、仅依托处置资产才能产生现金流的基础资产，如提单、仓单、产权证书等具有物权属性的权利凭证。（6）法律界定及业务形态属于不同类型且缺乏相关性的资产组合，如基础资产中包含企业应收账款、高速公路收费权等两种或者两种以上不同类型资产。（7）违反相关法律法规或者政策规定的资产。"},{"id":"real-law-82","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"不符合地方政府性债务管理有关规定或者新增地方政府性债务的基础资产应当被列入资产证券化业务基础资产负面清单。（）","options":["正确","错误"],"answer":"B","explain":"非公开发行的证券，可以在证券交易所、国务院批准的其他全国性证券交易场所、按照国务院规定设立的区域性股权市场转让。"},{"id":"real-law-83","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"非公开发行只能在证券交易所、国务院批准的其他全国性证券交易场所。（）","options":["正确","错误"],"answer":"A","explain":"同一专项计划发行的资产支持证券可以划分为不同种类。同一种类的资产支持证券，享有同等权益，承担同等风险。"},{"id":"real-law-84","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《证券公司及基金管理公司子公司资产证券化业务管理规定》，同一资产支持专项计划发行的资产支持证券可以划分为不同种类，同一种类的资产支持证券，享有同等权益，承担同等风险。（）","options":["正确","错误"],"answer":"A","explain":"股东人数未超过200人的公司申请股票公开转让并挂牌，中国证监会豁免注册，由全国股转公司作出同意公开转让并挂牌的审核决定或终止审核决定。"},{"id":"real-law-85","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"股东人数未超过200人的公司申请股票公开转让并挂牌，中国证监会豁免注册，由全国股转公司作出同意审核决定或终止审核决定。（）","options":["正确","错误"],"answer":"A","explain":"全国股转系统是经国务院批准，依据证券法设立的全国性证券交易场所，主要为创新型、创业型、成长型中小微企业发展服务。"},{"id":"real-law-86","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"全国股转系统是经国务院批准，依法设立的全国性证券交易场所。（）","options":["正确","错误"],"answer":"A","explain":"证券公司从业人员是从事证券相关业务的管理人员和专业人员，合规总监，投资顾问，投资经理以及稽核人员均负责证券相关业务以及相关内控、合规、审计等管理事项，均属于从业人员。"},{"id":"real-law-87","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《证券公司董事、监事、高级管理人员及从业人员管理规则》，某证券公司合规总监张某、上海分公司投资顾问王某、资产管理部投资经理李某以及稽核审计部稽核专员赵某均属于从业人员。（）","options":["正确","错误"],"answer":"B","explain":"证券公司依托第三方开展客户尽职调查的，应当采取以下措施：一是确认第三方接受反洗钱和反恐怖融资监管，并按照反洗钱法律、行政法规等相关要求，采取了客户尽职调查及交易记录保存措施；二是立即从第三方获取客户尽职调查的必要信息；三是在需要时立即从第三方获取客户身份证明文件和其他相关资料的复印件或影印件。证券公司应当承担第三方未履行客户尽职调查义务的责任。"},{"id":"real-law-88","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"符合一定条件时，证券公司可信赖销售金融产品的金融机构所提供的客户身份识别结果，不再重复进行已完成的客户身份识别程序，不需承担未履行客户身份识别义务的责任。（）","options":["正确","错误"],"answer":"B","explain":"债券交易人员薪酬与激励合计超过人民币100万元的，超过部分应按照等分原则递延发放，周期不少于2年。"},{"id":"real-law-89","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券公司应当加强对债券投资交易人员的薪酬递延管理，参与债券投资交易的人员薪酬与激励合计超过100万元人民币的，超过部分应当递延发放，具体递延周期及比例由证券公司自行确定。（）","options":["正确","错误"],"answer":"A","explain":"按照合伙协议的约定或者经全体合伙人决定，可以委托一个或者数个合伙人对外代表合伙企业，执行合伙事务。"},{"id":"real-law-90","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"按照合伙协议的约定，可以委托一个或者数个合伙人对外代表合伙企业，执行合伙事.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对务。（）","options":["正确","错误"],"answer":"A","explain":"证券公司从事介绍业务的工作人员不得进行期货交易。"},{"id":"real-law-91","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券公司从事中间介绍业务的工作人员不得进行期货交易。（）","options":["正确","错误"],"answer":"A","explain":"证券公司有下列情形之一的，国务院证券监督管理机构可以将其证券经纪等涉及客户的业务进行托管；情节严重的，可以对该证券公司进行接管：(1)治理混乱、管理失控；"},{"id":"real-law-92","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《证券公司风险处置条例》，证券公司挪用客户资产并且不能自行弥补，情节严重的，国务院证券监督管理机构可以对该证券公司进行接管。（）","options":["正确","错误"],"answer":"B","explain":"从业人员执业行为规范包括\"在法律法规规定及公司授权范围内开展业务，遵循客户利益优先和公平对待客户原则，有效防范利益冲突。"},{"id":"real-law-93","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券公司从业人员应当在法律法规规定及公司授权范围内开展业务，遵循公司利益优先及公平对待客户原则，防范利益冲突。（）","options":["正确","错误"],"answer":"B","explain":"证券期货经营机构不得在表内从事私募资产管理业务，不得以任何方式向投资者承诺本金不受损失或者承诺最低收益。"},{"id":"real-law-94","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券公司开展私募资产管理业务时，可以向投资者承诺保证投资本金安全，但不得向投资者承诺最低收益。（）","options":["正确","错误"],"answer":"A","explain":"制衡：证券公司部门和岗位的设置应当权责分明、相互牵制；前台业务运作与后台管理支持适当分离。"},{"id":"real-law-95","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券公司部门和岗位的设置应当权责分明、相互牵制，前台业务运作与后台管理支持适当分离。（）","options":["正确","错误"],"answer":"A","explain":"禁止证券交易场所、证券公司、证券登记结算机构、证券服务机构及其从业人员，证券业协会、证券监督管理机构及其工作人员，在证券交易活动中作出虚假陈述或者信息误导。"},{"id":"real-law-96","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"禁止证券公司从业人员在证券交易活动中作出虚假陈述或者信息误导行为。（）","options":["正确","错误"],"answer":"A","explain":"证券经营机构应当根据有关规定制定合理完善的公司营销制度，明确可列入营销费用的具体事项、内容、标准、额度等，并对公司营销制度和标准定期予以评估，对营销费用支出严格审查，对违反公司营销制度和标准的行为予以严厉问责。"},{"id":"real-law-97","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券经营机构应当制定合理完善的公司营销制度，明确可列入营销费用的具体事项、内容、标准、额度等。（）","options":["正确","错误"],"answer":"B","explain":"公司可以设立分公司。分公司不具有法人资格，其民事责任由公司承担。"},{"id":"real-law-98","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"公司可以设立分公司，分公司具有法人资格，依法独立承担民事责任。（）","options":["正确","错误"],"answer":"B","explain":"私募基金管理人应当履行下列职责：(1)依法募集资金，办理私募基金备案；(2)对所管理的不同私募基金财产分别管理、分别记账，进行投资；(3)按照基金合同约定管理私募基金并进行投资，建立有效的风险控制制度；(4)按照基金合同约定确定私募基金收益分配方案，向投资者分配收益；(5)按照基金合同约定向投资者提供与私募基金管理业务活动相关的信息；(6)保存私募基金财产管理业务活动的记录、账册、报表和其他有关资料；(7)国务院证券监督管理机构规定和基金合同约定的其他职责。"},{"id":"real-law-99","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"私募基金管理人对所管理的不同私募基金财产应当统一管理，合并记账。（）","options":["正确","错误"],"answer":"A","explain":"证券公司通过短信、邮件等非自主运营渠道发送投资者敏感个人信息的，应当将投资者账号信息、身份证号码等敏感个人信息进行脱敏处理。"},{"id":"real-law-100","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券公司通过短信、邮件等非自主运营渠道发送投资者敏感个人信息的，应当将投资者账号信息、身份证号码等敏感个人信息进行脱敏处理。（）.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对","options":["正确","错误"],"answer":"A","explain":"将科创板股票的涨跌幅限制放宽至20%。为尽快形成合理价格，新股上市后的前"},{"id":"real-law-101","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"科创板新股上市后的前5个交易日不设涨跌幅限制，之后股票的涨跌幅限制为20%。（）","options":["正确","错误"],"answer":"A","explain":"证券公司应当在报送年度报告的同时报送年度信息技术管理专项报告，并说明报告期内信息技术治理、信息技术合规与风险管理、信息技术安全管理、信息技术审计等方面执行规定的情况。"},{"id":"real-law-102","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券公司应当在向中国证监会报送年度报告的同时报送年度信息技术管理专项报告。（）","options":["正确","错误"],"answer":"B","explain":"证券公司应当按适当性制度要求和《证券公司融资融券业务管理办法》规定，制定选择客户的具体标准，一般主要包括以下几方面：(1)从事证券交易的时间客户申请开立信用业务证券账户前，应当已经开设普通证券账户且从事证券交易的时间满半年以上【题干未满足从事证券交易的时间满半年以上】。(2)账户状态客户开户手续齐全、资料完备，资金账户与证券账户对应关系清晰，交易结算状态正常。(3)信誉状况要求客户信誉良好，无重大违约记录。(4)资产状况最近20个交易日日均证券类资产不低于50万元，具有符合要求的担保品及较强的还款能力。(5)投资风格具有较强的风险承受能力，符合适当性相关规定。(6)关联关系不属于本公司的股东(持有上市证券公司5%以下流通股份的股东除外)或关联人。"},{"id":"real-law-103","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《证券公司融资融券业务管理办法》，客户向证券公司申请开展融资融券业务的，应当已经在该证券公司开设普通证券账户满半年以上，并符合法律法规规定的资产状况、信誉状况，证券公司方可为其开立信用业务证券账户。（）","options":["正确","错误"],"answer":"A","explain":"在证券研究报告发布之前，制作发布证券研究报告的相关人员不得向证券研究报告相关销售服务人员、客户及其他无关人员泄露研究对象覆盖范围的调整、制作与发布研究报告的计划，证券研究报告的发布时间、观点和结论，以及涉及盈利预测、投资评级、目标价格等内容的调整计划。"},{"id":"real-law-104","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《发布证券研究报告执业规范》，在证券研究报告发布之前，制作发布证券研究报告的相关人员不得向证券研究报告相关销售服务人员、客户及其他无关人员泄露证券研究报告的发布时间、观点和结论，以及涉及盈利预测、投资评级、目标价格等内容的调整计划。（）","options":["正确","错误"],"answer":"B","explain":"证券公司设董事会的，内部董事人数不得超过董事人数的1/2。"},{"id":"real-law-105","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"张某为某证券公司营业部营销总监。在张某推介下，客户王某在营业部开立了账户并转入人民币1500万元准备购买某款私募基金产品。随后，张某以落实反洗钱政策为由向王某索要了账户密码，擅自使用王某账户进行证券交易盈利人民币100余万元，并为该证券公司带来了可观的佣金收入。该营业部客户经理李某知悉后心生羡慕，通过偷窥获知其客户赵某账户密码后频繁实施单笔小额交易，累计交易金额约20万元，并造成赵某账户亏损。不考虑各小题及各选项之间的影响，请根据上述背景信息回答以下111-112问题。下列关于追究证券公司及张某的法律责任的说法，正确的有（）。","options":["该证券公司可能触犯背信运用受托财产罪","张某可能触犯背信运用受托财产罪","因张某为客户王某实现盈利，可免予追究其法律责任","张某的行为侵犯了金融管理秩序和客户的合法权益"],"answer":"C","explain":"选项C正确：证券公司作为金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重的，构成背信运用受托财产罪。李某的行为使证券公司违背了对赵某的受托义务。选项A错误：证券公司及其从业人员违背受托义务，擅自运用客户资金给客户造成损失的，应当依法承担民事赔偿责任，因此李某及证券公司需要赔偿赵某的经济损失。选项B错误：背信运用受托财产罪的立案追诉标准包括：(1)擅自运用客户资金或者其他委托、信托的财产数额在30万元以上的；(2)虽未达到上述数额标准，但多次擅自运用客户资金或者其他委托、信托的财产，或者擅自运用多个客户资金或者其他委托、信托的财产的；(3)其他情节严重的情形。李某累计交易金额约20万元，未达到30万元的立案标准。但\"多次\"擅自运用客户资金或者其他委托、信托的财产的\"也应立案追诉。选项D错误：关于背信运用受托财产罪的规定，单位犯该罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员追究刑事责任。李某即使不是营业部主管人员，若作为其他直接责任人员，仍需依法承担刑事责任。"},{"id":"real-law-106","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"下列关于李某的行为及相关法律责任的说法，正确的是（）。","options":["李某及证券公司均无需赔偿赵某的经济损失","李某累计交易金额较小，故不可能达到刑事立案追诉标准","李某的行为使证券公司违背了对赵某的受托义务","李某并非营业部主管人员，无需承担刑事责任"],"answer":"C","explain":"选项C错误：证券公司借助信息技术手段从事证券基金业务活动的，应当在业务系统上线时，同步上线与业务活动复杂程度和风险状况相适应的风险管理系统或相关功能。选项A正确：证券公司借助信息技术手段从事证券基金业务活动前，应当开展内部审查，验证下列事项并建立存档记录：(1)业务系统的流程设计、功能设置、参数配置和技术实现应当遵循业务合规的原则，不得违反法律法规及中国证监会的规定；(2)风险管理系统功能完备、权限清晰，能够与业务系统同步上线运行；(3)具备完善的信息安全防护措施，能够保障经营数据和客户信息的安全、完整；(4)具备符合要求的信息系统备份及运维管理能力，能够保障相关系统安全、平稳运行。选项B正确：证券公司从事证券交易相关业务，应当按照监管规定及自律管理规则的要求，确保风险管理系统具备审查账户资金及证券是否充足、监控交易及资金划转是否异常等功能。选项D正确：证券公司使用电子合同从事证券基金业务活动的，应当将电子合同存储在指定的信息系统，并提供可供投资者及合同其他相关方查询、下载的公开渠道。"},{"id":"real-law-107","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"某证券公司为更好开展证券经纪业务，拟上线一条新业务系统，召集相关部门开会研讨，张某提出该系统主要涉及证券交易业务，相应风险管理系统应当具备审查账户资金及证券是否充足、监控交易及资金划转是否异常等功能；王某视为保证业务系统尽快上线，可以暂缓相关风险管理系统功能的升级，在业务系统上线后再尽快上线相关系统功能；赵某表示在系统上线开展业务活动前，应当对相关系统的流程设计、功能设置及参数配置等情况开展内部审查；李某提出该系统涉及电子合同的使用，应当注意将电子合同存储在指定的信息系统内，在履行完相应流程后，该系统进入开发测试环节，并在测试成功后投入使用。不考虑其他情况，请根据上述背景信息回答以下113-115问题。下列哪位关于该系统上线合规与风险管理要求的说法是错误的（）。","options":["赵某","张某","王某","李某"],"answer":"AC","explain":"选项A错误：除必须使用敏感数据的情形外，证券公司应当对测试环境涉及的敏感数据进行脱敏，对未脱敏数据须采取与生产环境同等的安全控制措施。选项C错误：证券公司为其子公司提供信息技术服务的，应当充分评估信息技术基础设施的支撑能力与冗余程度，并与子公司签订服务协议，明确合作双方的权利义务，以及建立日常协作、业务隔离和应急管理机制，防范基础设施共用产生的新增风险。选项B正确：证券公司应当遵循最少功能以及最小权限等原则分配信息系统管理、操作和访问权限，并履行审批流程。选项D正确：证券公司应当将经营及客户数据按照重要性和敏感性进行分类分级，并根据不同类别和级别作出差异化数据管理制度安排。"},{"id":"real-law-108","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"下列关于该证券公司系统测试、使用期间的做法，错误的有（）。","options":["为保证测试的及时性和准确性，该证券公司安全控制措施稍弱的开发测试环境使用未脱敏数据进行测试","在使用时，该证券公司按照最少功能以及最小权限等原则分配系统权限","由于系统需求相似，在完成内部立项演示流程后，该证券公司开始为其子公司提供信息技术服务","在使用时，公司将客户数据根据不同类别和级别做出了差异化数据管理安排"],"answer":"D","explain":"选项D错误，选项B正确：(1)信息技术管理部门为信息技术应急管理的牵头组织部门，组织开展信息技术应急预案的制订、演练、评估与改进工作，并负责信息系统的应急响应与恢复；(2)各业务部门负责评估本业务条线信息技术突发事件相关风险，开展"},{"id":"real-law-109","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"为确保业务系统的正常使用，下列关于该证券公司加强应急管理的做法，错误的是（）。","options":["确保备份系统与生产系统具备同等的处理能力","规定信息技术管理部门为应急管理的牵头部门，组织开展信息技术应急预案的制定、演练、评估与改进工作","在公司网站公示信息技术突发事件发生时客户可采取的替代交易方式","明确由信息技术部负责评估各业务条线信息技术突发事件相关风险，确定并实施重要业务恢复目标和恢复策略"],"answer":"ABCD","explain":"选项AB正确：证券公司应当依法依规通过公司治理程序将所有子公司（被证券公司控制）纳入全面风险管理体系，对其风险管理工作实行垂直管理并逐步加强一体化管控，从公司治理、风险偏好与风险指标管理、新业务管理、重大事项管理、风险报告、考核评价等方面强化对子公司的风险管理，要求并确保子公司在整体风险偏好和风险管理制度框架下，建立健全自身的风险管理组织架构、制度流程、信息技术系统和风控指标体系，保障全面风险管理的一致性和有效性。选项C正确：证券公司应当从新业务管理、重大事项管理等方面强化对子公司的风险管理，对子公司的各项风险管理制度、各项新业务进行审批或出具专业意见，落实垂直一体化管控要求。选项D正确：在深化子公司风险管理垂直一体化管控模式中，证券公司应当将子公司的各类风险计量模型、金融产品及金融工具的估值模型纳入统一的风险管理体系或进行集中审批管控，以有效防范风险外溢和传染，确保整体风险可控。"},{"id":"real-law-110","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"2025年3月，证券业协会发布《证券公司全面风险管理规范（修订稿）》（以下简称“新规”），本次修订突出强监管、防风险、促高质量发展的主线要求。进一步提升规则的前瞻性引导与预防性规范功能。某证券公司是一家全牌照综合类券商，以经纪、资管、投行、自营四大业务为核心，积极发展私募投资基金、另类投资等业务。公司经理层高度重视全面风险管理工作，此次新规发布后，该公司风险管理部门在首席风险官的带领下，对照新规要求对公司现行全面风险管理体系进行了一次专项自查，确立了如下需要重点改进完善的工作方向：构建“穿透式+全景式”风控体系，深化子公司风险管理垂直一体化管控模式；细化同一业务、同一客户管理流程，提升对专项、复杂领域的风险管控：强化风险偏好及指标体系管理要求：压实一线风控责任，完善评价考核机制，加强风险考核的独立性要求；搭建全覆盖、穿透式的风险管理系统和贯穿整个生命周期的数据治理体系；融入中国特色金融文","options":["在证券公司整体风险管理制度框架体系下制定并持续完善子公司层面的风险管理制度体系","将子公司纳入整体风险偏好及风险指标体系，在子公司推行基本一致的风险偏好","对子公司的各项风险管理制度、各项新业务进行审批或出具专业意见","将子公司的各类风险计量模型、金融产品及金融工具的估值模型纳入统一管理"],"answer":"B","explain":"选项B错误：证券公司应当坚守业务本源、稳慎开展业务创新，建立针对新业务、新产品的风险管理制度和流程，明确需满足的条件和公司内部审批路径，充分了解新业务、新产品模式，识别各类潜在风险，关注信息技术、舆情负面评价、ESG(环境、社会和治理)等风险因素，评估公司是否有相应的人员、系统及资本开展该项业务。选项A正确：证券公司应当建立健全同一客户风险管理机制，明确同一客户的定义、认定标准、业务覆盖范围以及各组织机构的职责分工，建立同一客户风险管理相关风险限额、制度及流程，并覆盖证券公司各业务部门、分支机构及各级子公司。选项C正确：证券公司应构建和完善针对资产管理业务、场外衍生品业务等表外业务、场外业务的风险管理机制，充分识别表外业务、场外业务风险的复杂性、隐蔽性，严格落实客户准入及适当性管理要求。选项D正确：证券公司应当根据同一业务的定义和分类标准对公司及各级子公司的各项业务进行分类，建立并完善与业务复杂程度和风险指标体系相适应的同一业务风险管理信息技术系统或相关系统功能，对同一业务逐步实行基本一致的风险控制措施，对风险信息汇总管理并实施同一业务层面的风险监测、分析和预警。"},{"id":"real-law-111","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"根据《证券公司全面风险管理规范》相关规定，下列关于该证券公司细化同一业务同一客户管理流程、提升对专项复杂领域风险管控的做法错误的是（）。","options":["明确同一客户的定义、认定标准、业务覆盖范围，建立同一客户风险管理相关风险限额、制度及流程","严格比照已有业务风险管理制度和流程对新业务进行管控，并在业务开展过程中逐步了解其业务模式，识别各类潜在风险","充分识别表外业务、场外业务风险的复杂性、隐蔽性，严格落实客户准入及适当性管理要求","对同一业务逐步实行基本一致的风险控制措施，对风险信息汇总管理并实施同一业务层面的风险监测、分析和预警"],"answer":"B","explain":"选项B错误：证券研究报告应当由证券公司、证券投资咨询机构统一发布，并应当通过公司指定的渠道或合规的平台向客户发布。鼓励客户通过微信群或自媒体转发研报可能造成研报内容被不当传播。选项ACD做法无误。"},{"id":"real-law-112","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"某证券公司的业务范围涵盖证券经纪业务、证券承销与保荐业务、证券投资咨询业务等。李某、王某、徐某为该公司研究所分析师、蒋某为该公司研究所新员工（在中国证券业协会注册为“一般证券业务”）、刘某为该公司研报销售部门销售经理、金某为该公司投资银行部门业务人员。请结合前述背景信息回答以下118-120问题。根据《发布证券研究报告暂行规定》等相关规定，该公司的下列做法错误的是（）。","options":["制定投资价值研究报告专项内部制度","鼓励客户通过微信群或自媒体转发研报，以扩大影响","对发布证券研究报告行为及相关人员实行集中统一管理","建立证券研究报告发布审阅机制，明确审阅流程"],"answer":"D","explain":"选项D正确：证券分析师引用信息和数据来源时，应对引用信息和数据来源进行"},{"id":"real-law-113","subject":"law","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"根据《发布证券研究报告暂行规定》等相关规定，下列做法正确的是（）","options":["蒋某以分析师名义对外发布证券研究报告","徐某署名发布的某证券研究报告存在分析结论的合理依据不够充分的情况","李某将未经公司审核的证券研究报告草稿提供给刘某","王某撰写证券研究报告过程中注明相关数据来源"],"answer":"ABCD","explain":"选项A做法错误：经营机构发布证券研究报告，应当加强研究对象覆盖范围管理。将上市公司纳入研究对象覆盖范围并作出证券估值或投资评级，或者将该上市公司移出研究对象覆盖范围的，应当由研究部门或者研究子公司独立作出决定并履行内部审核程序。选项B做法错误：经营机构应当建立拟发布的证券研究报告市场影响评估机制，在证券研究报告制作和合规审查环节，对证券研究报告重要敏感信息可能对市场产生的影响进行审慎评估，不得基于个别数据夸大或臆测行业或市场整体风险。对于可能产生重要影响的结论和信息，应当提高审核人员层级，加大审核力度。选项C做法错误：证券分析师使用微信群等互联网工具提供服务应向公司备案，且发布内容需经公司审核。选项D做法错误：证券分析师在进行事实性信息的核实时，不得向发行人及投资银行业务部门人员提供包括估值、盈利预测等投资分析内容的章节，相关需要核实的事实性内容应提交给公司或发行人，抄送合规审查人员，由股票发行与承销部门人员转给投资银行业务部门人员进行核实。"}]},{"id":"real-bas","subject":"basics","name":"6月真题汇编 · 金融基础","stats":{"单选":38,"多选":36,"判断":30,"案例":6},"questions":[{"id":"real-bas-0","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于证券公司的说法，错误的是()。","options":["证券公司，是指依照《公司法》和《证券法》设立的经营证券业务的有限责任公司或股份有限公司","证券公司是证券市场投融资服务的提供者，为证券发行人和投资者提供专业化的中介服务","证券公司本身也是证券市场重要的机构投资者","世界各国对证券公司的划分和称呼不尽相同，英国、德国等一些国家和我国一样，将专营证券业务的金融机构称为证券公司"],"answer":"D","explain":""},{"id":"real-bas-1","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"中证中小投资者服务中心有限公司的主要职责不包括()。","options":["诉讼与支持诉讼","持股权","纠纷调解","进入涉嫌违法行为发生场所调查取证"],"answer":"C","explain":"当期收益率度量的是债券年利息收益占购买价格的百分比（B错误），反映每单位投资能够获得的债券年利息收益，但不反映每单位投资的资本损益（D错误）。当期收益率的优点在于简便易算，可以用于期限和发行人均较为接近的债券之间进行比较。其缺点是：零息债券无法计算当期收益（A错误）；不同期限附息债券之间，不能仅仅因为当期收益高低而评判优劣（C正确）。"},{"id":"real-bas-2","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于债券当期收益率的说法，正确的是()。","options":["优点在于简单易算，零息债券也可以方便计算当期收益","当期收益率度量的是债券总利息收益占购买价格的百分比","缺点在于不同期限附息债券之间不能仅以当期收益率作为评判优劣的指标","能反映每单位投资能够获得的债券年利息收益，也能反映每单位投资的资本损益"],"answer":"D","explain":"选项A：私募基金的投资额度通常较大，且在合同约定的范围内具有较大的灵活性，属于其特点。选项B：私募基金的投资方式在存续期内通常具有不可逆性，投资者在封闭期内不能随意赎回，属于其特点。选项C：私募基金在投资策略和标的选择上受到的监管限制较少，具有相对较强的自主性，属于其特点。选项D：分散投资是公募证券投资基金的典型特点，受限于严格的投资比例规定；而私募基金投资限制较少，可以集中投资，不强制要求分散投资，故不属于其典型特点。故本题答案选D。"},{"id":"real-bas-3","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"不属于私募投资基金特点的是（）。","options":["投资额度有较大的灵活性","组合投资方式具有不可逆性","投资具有相对较强的自主性","分散投资"],"answer":"A","explain":"资产支持证券不能直接提高投资者收益（A错误），只是盘活资产、盘活流动性、优化发起人资产结构、依托资产池发行，BCD均是其特点。"},{"id":"real-bas-4","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"资产支持证券的特点不包括（）。","options":["提高投资者的收益水平","将流动性较低的资产转化为具有较高流动性的可交易证券","可以改变发起人的资产结构，改善资产质量","可以资产池为基础2026年6月证券从业《金融市场基础知识》完整版真题汇编（学员回忆）第1题单选题（每题0.5分，共40题，共20分）"],"answer":"ABCD","explain":"一般而言，基金投资管理的流程包括以下环节："},{"id":"real-bas-5","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于金融市场风险敏感性分析的说法，错误的是（）。","options":["敏感性分析将风险因子的变化视为外生的","敏感性分析是全面的风险衡量方法","敏感性分析关注的是投资价值的变化","敏感性分析将投资风险暴露与风险因子联系起来"],"answer":"B","explain":"国外主要股票市场的股票价格指数包括：道•琼斯工业股价平均数、标准普尔500指数、纳斯达克指数、金融时报证券交易所指数（也被译为“富时指数”）、日经平均股价指数（ACD都包括）。沪深300指数是属于我国主要的股票价格指数，答案选B。"},{"id":"real-bas-6","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列不属于国外股票价格指数的是（）。","options":["富时指数","沪深300指数","道・琼斯工业股价平均数","标准普尔500指数"],"answer":"D","explain":"委托指令应当包括下列内容：证券账户号码、证券代码、买卖方向、委托数量、委托价格、交易所及其会员要求的其他内容（包括ABC）。故本题答案选D。"},{"id":"real-bas-7","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列不属于证券委托指令内容的是（）。","options":["买卖方向","证券代码","委托数量","资产管理号码"],"answer":"C","explain":"利率互换不交换本金，仅按名义本金计算利息差额互换，C选项正确。"},{"id":"real-bas-8","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"在金融衍生工具中，利率互换交易是根据（）计算利息。","options":["实际金额","资金成本","名义本金","本金数额"],"answer":"C","explain":"金融债券作为债券的一种特殊类型，它具有以下特点:（1）金融债券表示的是银行等金融机构与金融债券持有者之间的债权债务关系;（2）金融债券一般不记名、不挂失，但可以抵押和转让（AD选项不符合题意）;（3）金融债券的利息不计复利，不能提前支取，延期兑付亦不计逾期利息;（4）金融债券的利率固定，一般都高于同期储蓄利率（B选项不符合题意）;（5）我国发行金融债券所筹集的资金一般都专款专用，如中国建设银行曾发行的投资债券，其主要用途就是为国家大中型建设项目筹措资金。故本题选C选项。"},{"id":"real-bas-9","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"商业银行等金融机构通过发行金融债券进行直接融资，该金融债券的特点之一是（）。","options":["一般可记名、可挂失","该金融债券利率一般低于同期储蓄利率","该金融债券反应的是银行等金融机构与金融债券持有者之间的债权债务关系","一般不可用于抵押及转让"],"answer":"B","explain":"A正确，可使用内部模型法等高级方法计量；B错误，风险资本不是净资本与负债的比率，该定义表述错误；C正确，用于覆盖业务非预期损失；D正确，属于核心风控指标。"},{"id":"real-bas-10","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于证券公司风险资本的说法，错误的是（）。","options":["证券公司可采用内部模型法等风险计量高级方法计算风险资本准备","风险资本是证券公司持有的符合规定的净资本与负债之间的比率","风险资本准备是证券公司在开展业务过程中，因市场风险等可能引起的非预期损失所需要的资本","风险资本是证券公司重要的风险控制指标"],"answer":"D","explain":"证券交易所实行“公平、公开、公正”的原则，交易价格由交易双方公开竞价确定，实行“价格优先、时间优先”的竞价成交原则。"},{"id":"real-bas-11","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"证券交易所交易遵循的原则是（）。","options":["时间优先原则和数量优先原则","价格优先原则和数量优先原则","客户优先原则和时间优先原则","价格优先原则和时间优先原则"],"answer":"D","explain":"影响国债销售价格的因素："},{"id":"real-bas-12","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列不属于国债销售价格影响因素的是（）。","options":["承销商承销国债的中标成本","流通市场中可比国债的收益率水平","市场利率"],"answer":"B","explain":"券商以经纪、投行、自营、资管等业务为主，信贷类业务少；商业银行主营放贷，信用风险集中。二者业务结构不同，决定券商信用风险占比更低，B选项正确。"},{"id":"real-bas-13","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"证券公司承担的信用风险在其整体风险承担中的占比要低于商业银行，这主要是由其（）结构特点决定的。","options":["权益","业务","负债","盈利"],"answer":"D","explain":"股票退市制度是资本市场重要的基础性制度，有利于健全资本市场功能（C正确），降低市场经营成本，增强市场主体活力，提高市场竞争能力（B正确）；有利于实现优胜劣汰，惩戒重大违法行为，引导理性投资，保护投资者特别是中小投资者合法权益。股票退市包括主动退市和强制退市（A正确）。D错误，因重大违法类情形被强制退市的公司，不得申请重新上市。"},{"id":"real-bas-14","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于股票退市制度的说法，错误的是（）。","options":["股票退市包括主动退市和强制退市","股票退市制度有利于增强市场主体活力，提高市场竞争力","股票退市制度有利于健全资本市场功能","科创板上市公司股票被终止上市的，均可申请重新上市"],"answer":"D","explain":"选项A正确：股票基金的风险较高，但预期收益也较高。选项B正确：股票基金的投资目标侧重于追求资本利得和长期资本增值，比较适合长期"},{"id":"real-bas-15","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于股票型基金的说法，错误的是（）。","options":["股票型基金的风险较高，但预期收益也高","股票型基金的投资目标侧重于追求资本利得和长期资本增值","股票型基金是指以股票为主要投资对象的投资基金","股票型基金90%以上的基金资产投资于股票"],"answer":"C","explain":"上市公司增发，可以全部或者部分向原股东优先配售（B错误、C正确），优先配售比例应当在发行公告中披露（AD错误）。"},{"id":"real-bas-16","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于上市公司增发的说法，正确的是（）。","options":["优先配售比例无需在发行公告中披露","原股东不享有优先配售权","可以部分或全部向原股东优先配售","优先配售比例仅需在发行结果中披露"],"answer":"D","explain":"投资人可通过办理转托管业务（D选项正确），实现其变更办理基金业务销售渠道（或网点）的需要。选项A：份额转换是指投资者将其所持有的某一只基金份额转换为另一只基金份额的行为，不能实现变更销售网点的需要，故A选项错误。选项B：份额冻结是指基金注册登记机构受理有权机关提出的基金份额冻结业务申请，冻结期间不能进行一般交易，不能实现变更销售网点的需要，故B选项错误。选项C：份额分割通常指基金份额拆分，与变更销售网点无关，故C选项错误。"},{"id":"real-bas-17","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"基金投资者可以通过办理（）业务，实现其变更办理基金业务销售网点的需要。","options":["份额转换","份额冻结","份额分割","份额转托管"],"answer":"B","explain":"存托凭证是为便利跨境投融资，在资本市场国际化背景下产生。"},{"id":"real-bas-18","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"存托凭证主要在（）的环境下应运而生。","options":["资产本土化","资本市场国际化","投资多元化","机构多样化"],"answer":"D","explain":"证券承销，是指证券公司代理证券发行人发行证券的行为，D选项正确。"},{"id":"real-bas-19","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"证券承销是指证券公司代理（）发行证券的行为。","options":["投资银行","商业银行","金融机构","证券发行人"],"answer":"A","explain":"A错误，优先股的股息一般来自可分配税后利润，而债券的利息来自税前利润。B正确，优先股的法律属性属于股票，和债券不同。CD正确，定期还本付息属于公司必须履行的强制义务，不能按时还本付息会构成违约，而优先股股息支付相对灵活，优先股没有到期的概念，发行人没有偿还本金的压力，因此优先股的股息收益不确定性大于债券。"},{"id":"real-bas-20","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列项目当中不属于我国发行的普通国债的是（）。","options":["储蓄国债（电子式）","长期建设国债","记账式国债","储蓄国债（凭证式）"],"answer":"B","explain":"金融市场是要素市场的一种（A错误，不属于产品市场）。金融市场是创造和交易金融资产的市场（CD错误），是以金融资产为交易对象而形成的供求关系和交易机制的总和。金融市场参与者不仅在有形的固定场所进行金融资产交易，还通过各种线上手段进行联系，形成庞大的无形金融市场网络（B正确）。现代金融市场往往是无形的市场。"},{"id":"real-bas-21","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于金融市场的说法，正确的是（）。","options":["金融市场既是要素市场，也是产品市场","金融市场既包括有形的固定交易场所，还包括通过各种线上手段形成的庞大的无形市场","金融市场只是交易金融资产的市场","金融市场并不是创造金融资产的市场"],"answer":"D","explain":"随着中国经济从高速增长阶段转向高质量发展阶段，可以考虑从以下四个方面入手，增强金融服务实体经济的能力，促进实体经济和金融良性循环和健康发展：第一，守住不发生系统性金融风险的底线，管控好宏观层面的金融高杠杆率和流动性风险、微观层面的金融机构信用风险，以及跨市场、跨业态、跨区域的影子银行和违法犯"},{"id":"real-bas-22","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"在我国经济高质量发展阶段，增强金融服务实体经济能力的举措不包括（）。","options":["有序资金“脱虚向实”","补齐各类金融市场短板","鼓励以交易技术和风险管理能力为主要目的的金融创新","提升间接融资比重"],"answer":"C","explain":"净额结算使交易商可以使用有限的资本支撑起较大的交易规模，使整个市场信用风险敞口的增长慢于整个市场的市值增长。"},{"id":"real-bas-23","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"在交易对手信用风险管理方面，净额结算使得交易员可以使用有限的资本支撑起较大的交易规模，使整个市场()。","options":["流动性敞口","资本敞口","信用风险敞口","净额资金敞口"],"answer":"C","explain":"基金管理人、基金托管人既是基金的当事人，又是基金的主要服务机构。除基金管理人与基金托管人外，基金市场上还有许多面向基金提供各类服务的其他服务机构。这些机构主要包括基金销售机构（B）、基金销售支付机构、基金份额登记机构（D）、基金估值核算机构、基金投资顾问机构、基金评价机构（A）、律师事务所、会计师事务所、信息技术系统服务机构等。C选项属于监管机构。"},{"id":"real-bas-24","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列不属于金融服务机构的是()。","options":["基金评价机构","基金销售机构","基金监管机构","基金份额登记机构"],"answer":"B","explain":"投资者保护机构（如中证中小投资者服务中心）可受50名以上投资者委托，作为诉讼代表人，按明示退出、默示加入原则，为受害投资者提起民事损害赔偿诉讼，B选项正确。A选项，证券投资基金公司是从事证券投资基金业务的金融机构，不具备作为证券民事赔偿诉讼代表人的法定资格。C选项，证券交易所是为证券集中交易提供场所和设施的自律管理法人，主要履行一线监管职责，不作为民事诉讼代表人。D选项，财政部是国务院组成部门，主管国家财政收支等宏观经济事务，不参与证券民事损害赔偿诉讼的代表工作。"},{"id":"real-bas-25","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列可以作为诉讼代表人，按照“明示退出、默示加入”的原则依法为受害投资者提起民事损害赔偿诉讼的是（）。","options":["证券投资基金公司","投资者保护机构","证券交易所","财政部"],"answer":"C","explain":"合法性是指只有国家法律允许进行证券交易的自然人和法人才能开立证券账户。对国家法律法规不准许开户的对象，中国结算公司及其开户代理机构不得予以开户，C正确。选项A：真实性是指投资者开立证券账户时所提供的资料必须真实有效，不得有虚假隐匿，不符合题意。选项B：规范性不属于开立证券账户的法定基本原则，不符合题意。"},{"id":"real-bas-26","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"在证券账户管理基本原则中，（）是指只有国家法律允许进行证券交易的自然人和法人才能开立证券账户。","options":["真实性","规范性","合法性"],"answer":"C","explain":"北交所上市公司向特定对象发行股票，应当符合下列规定：具备健全且运行良好的组织机构（D正确）；具有独立、稳定经营能力，不存在对持续经营有重大不利影响的情形（B正确）；最近一年财务会计报告无虚假记载，未被出具否定意见或无法表示意见的审计报告；最近一年财务会计报告被出具保留意见的审计报告，保留意见所涉及事项对上市公司的重大不利影响已经消除(本次发行涉及重大资产重组的除外)；合法规范经营，依法履行信息披露义务（A正确）。C错误，现任董事、监事、高级管理人员最近一年内受到北交所公开谴责的，不得发行，不是半年。"},{"id":"real-bas-27","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于北交所上市公司向特定对象发行股票的条件，错误的是（）。","options":["合法规范经营，如实履行信息披露义务","具有独立、稳定经营能力，不存在对持续经营有重大不利影响的情形","上市时除董事高管人员最近半年内未受到北交所公开谴责","具备健全且运行良好的组织机构"],"answer":"D","explain":"私募基金募集说明不能过于晦涩难懂，要适配普通合格投资者理解，而非只贴合从业人员，D错误。ABC均为私募基金合规正确要求。"},{"id":"real-bas-28","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于私募基金的说法，错误的是（）。","options":["有明确的对投资者的细化、识别和评估的方法","信息披露要真实、准确、完整地披露投资者作出投资决策所需要的主要信息","完善私募基金投资者适当性管理制度","募集说明书语言专业复杂，符合从业人员的理解能力"],"answer":"C","explain":"我国的基金管理费、基金托管费及基金销售服务费均是按照前一日基金资产净值的一定比例逐日计提，按月支付，C选项正确。"},{"id":"real-bas-29","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"我国的基金管理费、基金托管费及基金销售服务费均是按照前一日（）的一定比例逐日计提，按月支付","options":["基金赎回额","基金申购额","基金资产净值","基金总份额"],"answer":"A","explain":"A项，佣金是客户在委托买卖证券成交后按成交金额一定比例支付的费用，是证券经纪商为客户提供证券代理买卖服务收取的费用。B选项，印花税是根据国家税法规定，在A股和B股成交后对买卖双方客户按照规定的税率分别征收的税金。C选项，过户费是委托买卖的股票、基金成交后，买卖双方为变更证券登记所支付的费用。D选项，监管费即证券交易监管费，是向中国证监会交纳的费用，不属于证券公司收取的代理买卖服务费用。"},{"id":"real-bas-30","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"证券公司接受客户委托买卖证券收取的服务费用是（）。","options":["佣金","印花税","过户费","监管费"],"answer":"B","explain":"机构投资者，是与个人投资者相对应的一类投资者，指用自有资金或者从分散的公众手中筹集的资金，以获得证券投资收益为主要经营目的的专业团体机构或企业，B错误。A正确，众多的证券市场投资者保证了证券发行和交易的连续性，是推动证券市场价格形成和流动性的根本动力。C正确，证券市场投资者是证券市场的资金供给者，D正确，各类投资者的目的各不相同，有些偏重长期投资，以获取高于银行利息的收益或意在参与股份公司的经营管理；有些则偏重短线投机，赚取市场差价。"},{"id":"real-bas-31","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于证券市场投资者的说法，错误的是（）。","options":["众多的证券市场投资者保证了证券发行和交易的连续性，是推动证券市场价格形成和流动性的根本动力","机构投资者，是指仅以取得利息或股息为目的，购买并持有有价证券，承担证券投资风险并行使证券权利","证券市场投资者是证券市场的资金供给者","机构证券市场投资者的目的各不相同，有些侧重于长期投资，有些则热衷于短线交易"],"answer":"A","explain":"首次公开发行，是指拟上市公司首次面向不特定的社会公众投资者公开发行股票募集资金并上市的行为，A正确。B正确，通过首次公开发行，发行人不仅募集到所需资金，而且成为上市公众公司。C正确，通过首次公开发行，发行人完成了股份有限公司的设立或转制。D正确，发行人申请首次公开发行股票并上市，应符合发行条件、上市条件、信息披露"},{"id":"real-bas-32","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"下列关于首次公开发行的说法，错误的是（）。","options":["首次公开发行是指拟上市公司首次面向特定投资者公开发行股票并实现公开上市的行为","通过首次公开发行，发行人成为了上市公众公司","通过首次公开发行，发行人完成了股份有限公司的设立或转制","发行人申请首次公开发行股票并上市，应符合相关板块定位"],"answer":"A","explain":"银行间债券市场，是指依托于中国外汇交易中心暨全国银行间同业拆借中心和中央国债登记结算有限责任公司的，包括商业银行、农村信用联社、保险公司、证券公司等金融机构以及一些非金融机构合格投资人通过北京金融资产交易所进行债券买卖和回购的市场（BCD正确）。A属于干扰项。"},{"id":"real-bas-33","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"银行间债券市场的参与主体不包括（）。","options":["交易所","农村信用社联社","商业银行","证券公司"],"answer":"C","explain":"基金监管机构通过依法行使审批或核准权，依法办理基金备案，对基金管理人、基金托管人以及其他从事基金活动的服务机构进行监督管理，对违法行为进行查处，在基金的运作过程中起着重要的作用。在我国，国务院证券监督管理机构，即中国证监会依法对证券投资基金活动实施监督管理，C选项正确。A选项，中国证券投资基金业协会是我国证券投资基金行业的自律性组织。B选项，中国证券业协会是证券行业的自律性组织，主要负责证券行业的自律管理。D选项，中国人民银行是我国的中央银行，主要负责制定和执行货币政策、维护金融稳定。"},{"id":"real-bas-34","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"负责证券投资基金行业的监管主体是（）。","options":["中国证券投资基金业协会","中国证券业协会","中国证监会","中国人民银行"],"answer":"D","explain":"根据《证券法》，证券服务机构为证券的发行、上市、交易等证券业务活动制作、出具审计报告及其他鉴证报告、资产评估报告、财务顾问报告、资信评级报告或者法律意见书等文件，应当勤勉尽责，对所依据的文件资料内容的真实性、准确性、完整性进行核查和验证。其制作、出具的文件有虚假记载、误导性陈述或者重大遗漏，给他人造成损失的，应当与委托人承担连带赔偿责任，但是能够证明自己没有过错的除外。A错误，并非无论是否存在过错都承担责任。B错误，承担连带赔偿责任的主体是证券服务机构。C错误，资产评估机构无法证明自己没有过错的，应当与委托人承担连带赔偿责任，而非自担连带全部赔偿责任。D正确，会计师事务所出具的文件有虚假记载给他人造成损失，但能够证明自己没有过错的，符合免责条款规定，不承担民事赔偿责任。"},{"id":"real-bas-35","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"根据《证券法》，下列关于证券服务机构法律责任的说法，正确的是（）。","options":["财务顾问机构为上市公司收购制作的文件有虚假记载给他人造成损失的，无论是否存在过错，应当承担民事赔偿责任","证券分析师为证券发行出具的文件有误导性陈述，因过错给他人造成损失的，应当承担连带赔偿责任","资产评估机构为上交所债券出具的评估报告有重大遗漏，无法证明自己没有过错的，自担连带全部赔偿责任","会计师事务所为证券上市出具的文件有虚假记载，给他人造成损失，但能够证明自己没有过错的，不承担民事赔偿责任"],"answer":"A","explain":"压力测试应当涵盖证券公司面临的主要风险，包括经营风险、市场风险、信用风险、操作风险、声誉风险、法律合规风险、流动性风险等风险类型（包括BCD）。A属于干扰项。"},{"id":"real-bas-36","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"压力测试能为商业银行带来的主要风险不包括（）。","options":["会计风险","市场风险","信用风险","操作风险"],"answer":"A","explain":"我国银行间债券市场中长期债券信用评级统一划分为：三等九级。"},{"id":"real-bas-37","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"单选","q":"我国银行间债券市场的信用评级，按照风险等级将中长期债券信用评级划分为（）。","options":["三等九级","三等九档","四等六级","四等六档"],"answer":"AD","explain":"目前，我国证券交易所采用两种竞价方式：集合竞价方式和连续竞价方式（AD选项正确）。B属于干扰项，教材都没有这种说法。C选项，撮合是交易系统处理买卖申报的过程，而非独立的竞价方式名称。"},{"id":"real-bas-38","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据上海和深圳证券交易所现行竞价方式有（）。","options":["连续竞价","固定竞价","撮合竞价","集合竞价"],"answer":"BD","explain":""},{"id":"real-bas-39","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列属于以转移或防范信用风险为核心的金融衍生工具有（）。","options":["保证金互换","信用联结票据","利率互换","信用互换"],"answer":"ABC","explain":"信用衍生工具是指以基础产品所蕴含的信用风险或违约风险为基础变量的金融衍生工具，用于转移或防范信用风险，是20世纪90年代以来发展最为迅速的一类衍生产品，主要包括信用互换、信用联结票据以及信用风险缓释合约、信用风险缓释凭证等信用风险缓释工具，BD选项正确。A选项，保证金互换不属于以转移或防范信用风险为核心的信用衍生工具。C选项，利率互换属于利率衍生工具，是指以利率或利率的载体为基础工具的金融衍生工具。答案：A,B,C解析：根据我国财政部《地方政府一般债券发行管理暂行办法》，地方政府一般债券是指省、自治区、直辖市政府(含经省级政府批准自办债券发行的计划单列市政府)为没有收益的公益性项目发行的、约定一定期限内主要以一般公共预算收入还本付息的政府债券，ABC选项正确，D选项错误，县级市政府不属于地方政府一般债券的发行主体。"},{"id":"real-bas-40","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"地方政府一般债券的发行主体可以有（）。","options":["省政府","自治区政府","直辖市政府","县级市政府"],"answer":"AC","explain":"常见的直接融资方式有股票市场融资、债券市场融资、风险投资融资、商业信用融资、民间借贷等，AC选项正确，BD属于干扰项。"},{"id":"real-bas-41","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"企业（公司）直接融资活动主要有（）方式。","options":["股票融资","制度融资","债券融资","权证融资"],"answer":"BCD","explain":"个人投资者投资基金税收："},{"id":"real-bas-42","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列对于个人投资者投资基金分红涉及的税收的说法，正确的有（）。","options":["个人投资者从基金分配中获得的收入，由基金代扣代缴20%的个人所得税","个人投资者买卖基金份额免征印花税","个人投资者申购和赎回基金份额取得的差价收入，暂不征收个人所得税","个人投资者买卖基金份额暂免征收印花税"],"answer":"ABCD","explain":"《证券市场程序化交易管理规定(试行)》围绕强监管、防风险、促高质量发展的主线，坚持“趋利避害、突出公平、有效监管、规范发展”的总体思路，对证券市场程序化交易(市场通常称为量化交易)监管作出全方位、系统性规定，是强化市场交易行为监管的重要举措。一是明确程序化交易的定义和总体要求。程序化交易，是指通过计算机程序自动生成或者下达交易指令在证券交易所进行证券交易的行为，相关活动应遵循公平原则，不得影响证券交易所系统安全或者扰乱正常交易秩序。二是明确报告要求，程序化交易投资者应按规定报告账户基本信息、资金信息、交易信息、软件信息等信息，并落实“先报告、后交易”要求，在履行报告义务后方可进行程序化交易（B正确）。三是明确交易监测和风险防控要求，证券交易所对程序化交易实行实时监控（C正确），对异常交易行为进行重点监控（D正确）。同时，进一步压实证券公司客户管理职责，明确机构投资者合规风控要求。四是加强信息系统管理，明确对程序化交易相关的技术系统、交易单元、主机托管、交易信息系统接入等监管要求（A正确）。五是加强高频交易监管，明确高频交易的定义，并从报告信息、收费、交易监控等方面提出差异化监管要求。六是明确监督管理安排，程序化交易相关机构和个人违反有关规定的，证券交易所、行业协会根据规定采取管理措施，证监会及其派出机构可依法采取监管措施或进行处罚。七是明确北向程序化交易按照内外资一致的原则，纳入报告管理，执行交易监控标准。"},{"id":"real-bas-43","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据2024年5月中国证监会发布的《证券市场程序化交易管理规定（试行）》，下列说法正确的有（）。","options":["明确对程序化交易相关的技术系统、交易信息系统接入等监管要求","明确报告要求，程序化交易投资者在履行报告义务后方可进行程序化交易","明确甄别高频交易，并从报告信息、收费等方面提出差异化监管要求","明确交易监控和风险防控要求，证券交易所对异常交易行为进行重点监控"],"answer":"ABD","explain":"上海证券交易所在《上海证券交易所科创板企业发行上市申报及推荐暂行规定》"},{"id":"real-bas-44","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据科创板的定位，下列属于其服务范围的领域或行业有（）。","options":["新一代信息技术领域","生物医药领域","主要从事金融业务的行业","新能源领域"],"answer":"AD","explain":"可交换债券与可转换债券具有类似的特征，也有以下明显的区别："},{"id":"real-bas-45","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"可转换债券和可交换债券的区别有（）。","options":["可交换债由公司股东发行，可转债由公司本身发行","可转债由公司股东发行，可交换债由公司本身发行","可交换债转股时股票总股本扩大，可转债转股时股票总股本不扩大","可转债转股时股票总股本扩大，可交换债转股时股票总股本不扩大"],"answer":"ABCD","explain":"常见的直接融资方式有股票市场融资、债券市场融资、风险投资融资、商业信用融资、民间借贷等。证券市场融资属于典型的直接融资。综上，答案选ABCD。"},{"id":"real-bas-46","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列属于直接融资的是（）。","options":["债券市场融资","股票市场融资","风险投资融资","民间借贷"],"answer":"ABCD","explain":"债券与股票的区别如下："},{"id":"real-bas-47","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"维护金融安全是一项系统性工作，要从深化金融改革及（）等多方面推进。","options":["完善金融体系","为虚拟经济发展创造优于实体经济的良好环境","加强金融监管","采取措施处置风险点"],"answer":"ABCD","explain":"考点：考查政府债券的特征。政府债券的特征有：安全性高、流通性强、收益稳定、免税待遇。综上，本题答案选ABCD。"},{"id":"real-bas-48","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列属于政府债券的特征的有（）。","options":["安全性高","免税待遇","收益稳定","流通性强"],"answer":"BCD","explain":"BCD正确，A错误：投资者如果预期证券价格即将下跌，可以借入证券卖出，而后通过以更低价格买入证券获利。"},{"id":"real-bas-49","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于融资融券交易的说法中，正确的有（）。","options":["投资者如果预期股价即将上涨，可以借入证券卖出，而后通过以更低价格买入还券获利","投资者向证券公司提交的保证金可以是现金，或者可充抵保证金的证券","融券交易是指投资者向证券公司缴纳一定的保证金，融入一定数量的证券并卖出的交易行为","融资交易具有杠杆特性，将进一步放大风险"],"answer":"ACD","explain":"与个人投资者相比，机构投资者具有以下特点:"},{"id":"real-bas-50","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"与个人投资者相比，以下属于证券市场机构投资者特点的有（）。","options":["投资管理专业化","投资结构单一化","投资行为规范化","投资资金规模化"],"answer":"ABCD","explain":"选项A正确：套期保值分为多头套期保值、空头套期保值，操作方向完全基于对未来利率走势判断：预期利率上升做空头套保，预期利率下降做多头套保，预判直接决定操作走向。选项B正确：利率期货套期保值合约数量计算公式核心包含现货债券久期、期货标的久期，久期是计算所需合约份数的关键变量，直接影响期货合约数量。选项C正确：久期和债券到期期限高度相关，不同剩余期限债券久期差异大，会改变对冲比例与对冲效果，因此二者关系是套保重要考量因素。选项D正确：基差=现货价格-期货价格，利率套保无法完全消除价格波动，基差波动带来基差风险，会削弱、影响最终套期保值效果。"},{"id":"real-bas-51","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"关于利率期货套期保值，下列说法正确的有（）。","options":["对未来利率变动方向的预判会影响套期保值的操作走向","债券的久期将直接影响套期保值时所需要期货合约数量","债券到期期限与久期之间的关系也作为利率套期保值的考量内容","债券现货持仓中可能存在基差风险会影响套期保值效果"],"answer":"BC","explain":"按付息方式分类。附息国债和贴现国债是按照国债利息的支付方式不同而划分的，BC选项正确。A是按照国债的偿还期限分类的，D是指政府为了实施某种特殊政策而发行的国债，属于按资金用途或发行目的分类。"},{"id":"real-bas-52","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"按照付息方式不同，国债可分为（）。","options":["长期国债","附息国债","贴现国债","特种债券"],"answer":"ABCD","explain":"在基金市场上存在许多不同的参与主体，依据所承担的责任与作用的不同，可以将基金市场的参与主体分为基金当事人、基金服务机构、基金的监管机构和自律组织三大类。综上，ABCD都要选上。"},{"id":"real-bas-53","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"基金市场的参与主体有（）。","options":["基金的自律组织","基金的监管机构","基金服务机构","基金当事人"],"answer":"ACD","explain":"股票发行监管制度主要有三种：审批制、核准制和注册制，每一种发行监管制度都对应一定的市场发展状况。综上，答案选ACD，B选项，保荐制是我国股票发行核准制发展过程中的一个阶段（核准制包括通道制和保荐制两个阶段）。"},{"id":"real-bas-54","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于证券服务机构的说法，正确的有（）。","options":["《证券法》规定从事证券投资咨询服务业务，应当经中国证券业协会核准","从事信息技术系统服务的证券服务机构应当按照中国证监会《证券服务机构从事证券服务业务备案管理规定》办理备案","根据相关法规的规定，证券服务机构业务包括财务顾问、律师等相关证券服务业务","证券服务机构是指依法设立的从事证券服务业务的法人机构，包括会计师事务所、律师事务所等证券服务机构"],"answer":"AD","explain":"保荐制度的重点是明确保荐机构和保荐代表人的责任，并建立责任追究机制（AD选项正确）。保荐人的保荐责任期包括发行上市全过程以及上市后的一段时期。B错误，形成持续信用监管和冷淡对待的监管措施不属于保荐制度的重点内容。C错误：保荐制度的主要内容包括建立保荐机构资格核准和保荐代表人的登记管理制度，而非证券登记管理制度。"},{"id":"real-bas-55","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"保荐制度的重点有（）。","options":["明确保荐机构和保荐代表人的责任","形成持续信用监管和“冷淡对待”的监管措施","证券登记管理制度","建立责任追究机制"],"answer":"ACD","explain":"外国债券是指某一国家借款人在本国以外的某一国家发行以该国货币为面值的债券。它的特点是债券发行人属于一个国家，债券的面值货币和发行市场属于另一个国家。外国债券一般由发行地所在国的证券公司、金融机构承销（D正确），而欧洲债券由一家或几家大银行牵头，组织十几家或几十家国际性银行在一个国家或几个国家同时"},{"id":"real-bas-56","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"关于外国债券的说法，正确的有（）。","options":["必须经官方主管机构批准","受发行人所在国有关法规的管制和约束","受发行地所在国的税法管制","由发行地所在国的金融机构、证券公司承销"],"answer":"ACD","explain":"政府机构类投资者的特点是通常很少考虑盈利，参与证券投资的目的主要是为了调剂资金余缺、实施宏观调控、实行特定产业政策等。故本题选ACD选项，B错误，政府机构类投资者通常很少考虑盈利，不以获取超额投资收益为主要目的。"},{"id":"real-bas-57","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"政府机构类投资者参与证券投资的目的主要包括（）。","options":["实施宏观调控","获取超额投资收益","调剂资金余缺","实行特定产业政策"],"answer":"ACD","explain":"A财产清算处置股票，权属变更；B正常流动性买卖属于普通交易，非特殊原因；C争夺控股权买入，特殊目的权属变动；D履约行权买入，属于特殊原因。"},{"id":"real-bas-58","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列可导致股票权属发生变化的特殊原因包括（）。","options":["由于财产清算等原因股票持有人实施股票","股票持有人因为流动性原因卖出或清偿股票","为了夺取或保持公司控制权而买入股票","履行某种承诺（如期限到期行权）而买进股票"],"answer":"ABD","explain":"私募基金募集应当履行下列程序："},{"id":"real-bas-59","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"私募基金募集应当履行的程序，主要包括（）等。","options":["投资者适当性匹配","投资冷静期","投资冷漠反馈","特定对象确定"],"answer":"ABCD","explain":"新“国九条”主要内容及配套制度有：（一）总体要求（二）严把发行上市准入关（三）严格上市公司持续监管（四）加大退市监管力度（五）加强证券基金机构监管，推动行业回归本源、做优做强（六）加强交易监管，增强资本市场内在稳定性（七）大力推动中长期资金入市，持续壮大长期投资力量（八）进一步全面深化改革开放，更好服务高质量发展（九）推动形成促进资本市场高质量发展的合力综上，本题答案选ABCD。"},{"id":"real-bas-60","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"2024年4月4日国务院发布了新“国九条”，其主要内容包括（）。","options":["大力推动中长期资金入市，持续壮大长期投资力量","严格上市公司持续监管","进一步全面深化改革开放，更好服务高质量发展","加强交易监管，增强资本市场内在稳定性"],"answer":"ABCD","explain":"委托指令的撤销即撤单，撤单的条件和程序如下：第一，撤单的条件。在委托未成交之前，客户有权变更和撤销委托（BC正确）。证券营业部申报竞价成交后，买卖即告成立，成交部分不得撤销（D正确）。第二，撤单的程序。在委托未成交之前，客户变更或撤销委托，在采用证券经纪商场内交易员进行申报的情况下，证券经纪商营业部业务员须即刻通知场内交易员，经场内交易员操作确认后，立即将执行结果告知客户。在采用客户或证券经纪商营业部业务员直接申报的情况下，客户或证券经纪商营业部业务员可直接将撤单信息通过电脑终端输人"},{"id":"real-bas-61","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于委托撤单的说法，正确的有（）。","options":["对客户撤销的委托，证券经纪商须及时将冻结的资金或证券解冻","委托未成交之前，客户有权变更委托","委托未成交之前，客户有权撤销委托","证券竞价交易中竞价成交后，买卖即告成立，成交部分不得撤单"],"answer":"ABCD","explain":"基金市场上还有许多面向基金提供各类服务的其他服务机构。这些机构主要包括基金销售机构、基金销售支付机构、基金份额登记机构、基金估值核算机构、基金投资顾问机构、基金评价机构、律师事务所、会计师事务所、信息技术系统服务机构等。从事基金服务业务的机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。综上，ABCD都要选上。"},{"id":"real-bas-62","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据中国证监会的规定进行注册备案的基金服务机构有（）。","options":["从事基金销售的机构","从事公开基金评价的服务机构","从事公开基金投资顾问业务的机构","从事基金销售支付的机构"],"answer":"ABD","explain":"选项AB正确，对开放式基金而言，在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值。对货币基金而言，货币基金每日分配收益，份额净值保持1元不变，因此货币基金不像一般开放式基金那样披露每个开放日的份额净值，而是需要披露收益公告，包括每万份基金收益和最近7日年化收益率。选项C错误，选项D正确，基金运作信息披露主要指在基金合同生效后至基金合同终止前，基金信息披露义务人依法定期披露基金的上市交易、投资运作及经营业绩等信息。基金管理人和基金托管人应当按照法规规定的各项时间要求进行基金运作信息的披露，时间一般是可以事先预见的。"},{"id":"real-bas-63","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"关于基金信息披露，下列说法正确的有（）。","options":["货币基金需要披露收益公告，包括每万份基金收益和最近7日年化收益率","开放式基金在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值","基金募集信息披露只是指首次募集信息披露","基金管理人和托管人应当按照法律法规的各项时间要求进行基金运作信息的披露"],"answer":"ACD","explain":"A禁止传播虚假信息；B定期披露估值属于正常合规披露；C禁止恶意信息误导；D禁止刊登他人推荐性文字。综上，答案选ACD。"},{"id":"real-bas-64","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"基金信息披露禁止（）。","options":["传播虚假基金信息","定期披露基金估值信息","恶意进行信息误导","登载其他人推荐性文字"],"answer":"ABCD","explain":"境内符合条件的股份公司可以通过主办券商申请在全国中小企业股份转让系统挂牌，公开转让股份，进行股权融资、债权融资、资产重组等，但不包括公开发行股份。综上，本题答案选ABCD。"},{"id":"real-bas-65","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"依据《国务院关于全国中小企业股份转让系统有关问题的决定》，境内符合条件的股份公司均可通过主办券商申请在全国股份转让系统挂牌，（）。","options":["公开转让股份","进行债权融资","进行股权融资","进行资产重组"],"answer":"AD","explain":"普通股股东的股息取决于公司当年盈利状况和分配政策，而优先股的股息收益一般是固定的，AD选项正确，BC属于干扰项。"},{"id":"real-bas-66","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"普通股的红利是不固定的，它取决于股份公司的（）。","options":["盈利水平","股票市价","股票面额","分配政策"],"answer":"BCD","explain":"中华人民共和国境内的商业银行及授权分行（A错误）、信托投资公司、企业集团财务公司、金融租赁公司、农村信用社、城市信用社、证券公司、基金管理公司及其管理的各类基金、保险公司、外资金融机构以及经金融监管当局批准可投资于债券资产的其他金融机构均可在中央国债登记结算有限责任公司（即中央结算公司）、银行间市场清算所股份有限公司（上海清算所）和中国证券登记结算有限责任公司（中国结算公司）按实名制原则以自己名义开立债券托管账户。故本题选BCD选项。"},{"id":"real-bas-67","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"可以以自己的名义开立债券托管账户的机构有（）。","options":["商业银行理财部支行","企业集团财务公司","证券公司","基金管理公司"],"answer":"ABD","explain":"A正确，技术分析依托市场行为研判价格走势；B正确，基本面分析聚焦内在价值，对比市价做投资判断；C错误，三类分析各有优劣，不存在量化分析已经超越领先一说。D正确，量化分析运用各类定量模型开展分析。"},{"id":"real-bas-68","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"某大型农场为了防止农用化肥尿素市场价格变动对企业经营带来的风险，于是与某大型尿素供应商签订了以固定价格购货的长期合同。但后来考虑到合同可能存在对手违约风险，于是将规避风险的方式改为在期货市场上利用尿素期货进行套期保值操作，以上描述中，企业的行为旨在规避的风险包括（）。","options":["操作风险","市场风险","流动性风险","信用风险"],"answer":"ACD","explain":"A、D正确，做市商双向报出买卖价格；B错误，投资者之间不能直接交易，只能和做市商成交；C正确，做市商用自有资金、自有证券和投资者交易。"},{"id":"real-bas-69","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于做市商交易制度的说法，正确的有（）。","options":["证券交易的买卖价由做市商给出","投资者之间可以直接成交","做市商以其自有资金或证券与投资者交易","证券交易的买卖价由做市商报出"],"answer":"BC","explain":"A错误，估值信息有严格披露要求；B正确，净值计算必须精准；C正确，估值结果秉持公允原则；D错误，严禁随意按需求调整估值。"},{"id":"real-bas-70","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"基金份额净值的估值（）。","options":["信息放置无要求","计算必须准确","结果是公允的","可以根据参与方需求进行调整"],"answer":"BCD","explain":"A错误：私募投资范围有合规限制，并非无任何限制；B正确：面向特定合格投资者，禁止公开推介；C正确：严格遵守法定人数上限；D正确：只能非公开方式募集。"},{"id":"real-bas-71","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"下列关于私募基金的说法，正确的有（）","options":["私募基金的投资范围不受任何限制","私募基金是向特定合格投资者发售证券投资基金份额，私募基金不得进行公开推介","私募基金投资者人数受到限制，不能超过法定的投资者人数上限","私募基金只能采取非公开募集方式募集资金"],"answer":"ABD","explain":"国务院证券监督管理机构根据《证券法》依法履行职责，有权采取下列措施:(1)对证券发行人、证券公司、证券服务机构、证券交易场所、证券登记结算机构进行现场检查。D正确(2)进入涉嫌违法行为发生场所调查取证。B正确(3)询问当事人和与被调查事件有关的单位和个人（C错误，不是所有人），要求其对与被调查事件有关的事项作出说明或者要求其按照指定的方式报送与被调查事件有关的文件和资料。(4)查阅、复制与被调查事件有关的财产权登记、通讯记录等文件和资料。A正确(5)查阅、复制当事人和与被调查事件有关的单位和个人的证券交易记录、登记过户记录、财务会计资料及其他相关文件和资料:对可能被转移、隐匿或者毁损的文件和资料，可以予以封存、扣押。(6)查询当事人和与被调查事件有关的单位和个人的资金账户、证券账户、银行账户以及其他具有支付、托管、结算等功能的账户信息，可以对有关文件和资料进行复制对有证据证明己经或者可能转移或者隐匿违法资金、证券等涉案财产或者隐匿、伪造、毁损重要证据的，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以冻结或者查封，期限为6个月:因特殊原因需要延长的，次延长期限不得超过3个月，冻结、查封期限最长不得超过2年(7)在调杏操纵证券市场、内幕交易等重大证券违法行为时，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以限制被调查事件当事人的证券买卖，但限制的期限不得超过3个月:案情复杂的，可以延长3个月。(8)通知出境入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境。"},{"id":"real-bas-72","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"私募投资基金管理机构按照《私募办法》履行职责，有权采取的措施包括（）。","options":["查阅、复制与被调查事件有关的财产权登记、通讯记录等文件和资料","进入涉嫌违法行为发生场所调查取证","询问被调查事件当事人、涉嫌违法从业的所有人","对证券发行人、证券公司、证券服务机构、证券交易所、证券登记结算机构进行现场检查"],"answer":"ABCD","explain":"A限额管理：控制授信规模，缓释信用风险；B风险对冲：转移抵消信用损失风险；C风险定价：高风险高定价，提前补偿风险；D资产配置：分散投资，降低单一主体信用违约冲。"},{"id":"real-bas-73","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"多选","q":"根据风险管理理念，利用风险管理方式对于金融信用风险具有缓释作用的是（）。","options":["业务规模限额","对冲风险交易","风险定价","投资资产配置1.错2.对"],"answer":"A","explain":"股票的清算价值是公司清算时每一股份所代表的实际价值。从理论上说，股票的清算价值应与账面价值一致，实际上并非如此。"},{"id":"real-bas-74","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"股票的清算价值是公司清算时每一股份所代表的实际价值，其往往与账面价值不一样。.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对","options":["正确","错误"],"answer":"A","explain":"题干说法正确，融资流动性风险主要是从单个机构的角度分析金融机构在面临现金需求时其融资能力随时间推移而引起的不确定波动，是指在不影响其日常经营和财务状况的条件下，金融机构难以有效满足其预期和非预期的、当前和未来的现金流和担保需求的风险。"},{"id":"real-bas-75","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"融资流动性风险主要是从单个机构的角度分析金融机构在面临现金需求时其融资能力随时间推移而引起的不确定波动，是指在不影响其日常经营和财务状况的条件下，金融机构难以有效满足其预期和非预期的、当前和未来的现金流和担保需求的风险。","options":["正确","错误"],"answer":"B","explain":"中国证监会及其派出机构实施监督管理，中国证券投资基金业协会实施自律管理。"},{"id":"real-bas-76","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"从事基金份额登记管理相关业务，接受业务主管单位中国证监会的自律组织，必须符合基金业务自律规范，自觉遵守。（）","options":["正确","错误"],"answer":"B","explain":"题干说法错误，基金管理人根据规定或约定解聘运营管理机构的，且该运营管理机构为资产支持证券管理人聘请的资产服务机构，资产支持证券管理人应当同步解除与该机构的资产服务协议。"},{"id":"real-bas-77","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"基金管理人根据规定解聘运营管理机构时，如该运营管理机构为对应的资产支持证券管理人，则不得单方面解除与该机构的资产服务协议，而是待其资产服务协议到期再行解除。（）","options":["正确","错误"],"answer":"A","explain":"风险偏好是战略性的，通常以定性描述为主；风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化。"},{"id":"real-bas-78","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"风险容忍度是风险偏好的具体体现，是对风险偏好的进一步量化和细化。","options":["正确","错误"],"answer":"A","explain":"一般性货币政策工具是指中央银行普遍或常规运用的货币政策工具，其实施对象是整体经济和金融活动，主要包括存款准备金制度、再贴现政策和公开市场业务三大工具。"},{"id":"real-bas-79","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"实施一般性货币政策的三大工具分别是存款准备金制度、再贴现政策和公开市场业务。","options":["正确","错误"],"answer":"B","explain":"年度股东会每年召开一次，应当于上一会计年度结束后的6个月内举行。"},{"id":"real-bas-80","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"股份公司年度股东会每年召开一次，应当于上一会计年度结束后的4个月内举行。","options":["正确","错误"],"answer":"A","explain":"商品期货是指标的物为实物商品的期货合约。商品期货历史悠久，种类繁多，主要包括农产品期货、金属期货和能源化工期货等。"},{"id":"real-bas-81","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"商品期货是以实物商品为标的物的期货合约，其交易标的包括农产品、金属和能源化工等类别。","options":["正确","错误"],"answer":"A","explain":"证券交易所的职能包括：(1)提供证券交易的场所、设施和服务；(2)制定和修改证券交易所的业务规则；(3)依法审核公开发行证券申请；(4)审核、安排证券上市交易，决定证券终止上市和重新上市；(5)提供非公开发行证券转让服务；(6)组织和监督证券交易；(7)对会员进行监管；(8)对证券上市交易公司及相关信息披露义务人进行监管；"},{"id":"real-bas-82","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"根据《证券交易所管理办法》，证券交易所的职能包括依法审核公开发行证券申请，审核、安排证券上市交易。","options":["正确","错误"],"answer":"A","explain":"证券发行人，是指为筹措资金而发行债券、股票等证券的发行主体。证券发行人主要包括政府及其机构、企业(公司)和金融机构。"},{"id":"real-bas-83","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券发行人主要包括政府及其机构、企业（公司）和金融机构。","options":["正确","错误"],"answer":"B","explain":"结算所实行无负债的每日结算制度，又称“逐日盯市制度”，就是以每种期货合约在交易日收盘前规定时间内的平均成交价作为当日结算价，与每笔交易成交时的价格作对照，计算每个结算所会员账户的浮动盈亏，进行随市清算。由于逐日盯市制度以一个交易日为最长的结算周期，对所有账户的交易头寸按不同到期日分别计算，并要求所有的交易盈亏都能及时结算，从而能及时调整保证金账户，控制市场风险。"},{"id":"real-bas-84","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"对于金融期货交易，结算所实行逐日盯市制度，以T+1为结算周期，对所有账户的交易头寸按照不同到期日的下一个交易日分别进行结算，控制市场风险。.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错","options":["正确","错误"],"answer":"B","explain":"2023年12月1日，中国证券业协会颁布《证券公司操作风险管理指引》，明确操作风险是指由不完善或有问题的内部流程、人员和系统以及外部事件所造成损失的风险。该定义包括法律风险，但不包括战略风险和声誉风险。"},{"id":"real-bas-85","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"操作风险是指由不完善或有问题的内部流程、人员和系统以及外部事件所造成的风险，该定义包括法律风险、战略风险和声誉风险。","options":["正确","错误"],"answer":"B","explain":"《巴塞尔协议Ⅲ》将交易对手信用风险定义为交易对手在现金流结算前的违约风险。"},{"id":"real-bas-86","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"《巴塞尔协议Ⅲ》将交易对手信用风险定义为交易对手在履行金融结算后的违约风险。","options":["正确","错误"],"answer":"B","explain":"《存款保险条例》核心理念并非“存款无虞，监管自负”，存款保险制度遵循存款保险、风险共担、有限赔付。"},{"id":"real-bas-87","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"【超纲题】《存款保险条例》是存款保险保护领域的基础性制度，其核心理念是“存款无虞，监管自负”。","options":["正确","错误"],"answer":"B","explain":"股票价格指数的编制步骤：第一步，选择样本股。选择一定数量有代表性的上市公司股票作为编制股价指数的样本股。样本股可以是全部上市股票，也可以是其中有代表性的一部分。样本股的选择主要考虑两条标准：一是样本股的市价总值要占在交易所上市的全部股票市价总值的大部分；二是样本股票价格变动趋势必须能反映股票市场价格变动的总趋势。第二步，选定某基期，并以一定方法计算基期平均股价或市值。通常选择某一有代表性或股价相对稳定的日期为基期，并按选定的某一种方法计算这一天的样本股平均价格或总市值。第三步，计算计算期平均股价或市值，并作必要的修正。收集样本股在计算期的价格，并按选定的方法计算平均价格或市值。有代表性的价格是样本股收盘平均价。第四步，指数化。如果计算股价指数，就需要将计算期的平均股价或市值转化为指数值，即将基期平均股价或市值定为某一常数(通常为"},{"id":"real-bas-88","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"股票价格指数的编制步骤依次为一是选择样本股；二是选定某基期，并以一定方法计算基期平均股价或市值；三是指数化，简单计算计算期平均股价或市值。（）","options":["正确","错误"],"answer":"A","explain":"一般债券采用记账式固定利率付息形式，地方政府一般债券实行自发自还，债券"},{"id":"real-bas-89","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"一般债券采用记账式固定利率付息形式，实行自发自还。（）","options":["正确","错误"],"answer":"B","explain":"存款保险依靠投保机构缴纳保费形成保险基金，出险赔付优先动用存款保险基金，大幅减少财政直接支出，缓解财政压力，更容易平衡财政负担与金融稳定。"},{"id":"real-bas-90","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"对于存款保险制度在防范财政负担方面所具有的重要作用，再加上金融市场对市场变化的敏感性，金融市场极易引发恐慌，会使得财政压力方面很难找到一个平衡点。","options":["正确","错误"],"answer":"A","explain":"各市场层次有转板、升降层、挂牌上市衔接机制，互通流动，并非孤立平行。"},{"id":"real-bas-91","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"多层次资本市场的各层次之间并不是​单独平行、彼此隔离​的。（）","options":["正确","错误"],"answer":"B","explain":"远期合约非标准化，场外私下交易；期货才是标准化、场内交易所交易。"},{"id":"real-bas-92","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"远期合约通常是标准化合约，并在交易所内交易。（）","options":["正确","错误"],"answer":"B","explain":"募集期买入叫认购，基金成立生效后买入叫申购，题干说反了。"},{"id":"real-bas-93","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"在开放式基金设立募集期内，投资者申请购买基金份额的行为称为申购；在基金合同生效后，投资者申请购买基金份额的行为叫认购。（）","options":["正确","错误"],"answer":"B","explain":"资本现金流贴现只是估值方法之一，不等于整体金融贴现，概念范围不等同。"},{"id":"real-bas-94","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"金融估值的资本现金流贴现就是金融贴现。（）","options":["正确","错误"],"answer":"A","explain":"巴塞尔协议核心就是确立商业银行资本充足率最低监管标准，严控银行风险。"},{"id":"real-bas-95","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"《巴塞尔协议》建立了资本充足率的最低标准。.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对1.错2.对","options":["正确","错误"],"answer":"A","explain":"Gamma是Delta的变化率，衡量标的资产价格变动对Delta数值的影响程度。"},{"id":"real-bas-96","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"在证券交易中，Gamma反映的是标的证券价格变化对delta值的影响程度。","options":["正确","错误"],"answer":"A","explain":"信用风险量化核心围绕违约展开，违约概率、违约损失率、风险暴露三大核心指标，直接决定预期损失与非预期损失。"},{"id":"real-bas-97","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"在信用风险分析中，对信用风险的描述和量化仍然是以违约为中心，主要包括违约概率、违约损失率和违约时的风险暴露，这些要素决定了信用产品的预期损失和非预期损失。","options":["正确","错误"],"answer":"A","explain":"1972年芝加哥商业交易所推出外汇期货，是最早诞生的金融期货品种，主要用来对冲汇率波动风险。"},{"id":"real-bas-98","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"外汇期货是金融期货中最先产生的品种，主要用于规避外汇风险，其交易自1972年在芝加哥商业交易所所属的国际货币市场率先推出并得到迅速发展。","options":["正确","错误"],"answer":"A","explain":"资本市场主流两大交易模式，竞价交易（集中撮合）、做市商制度，市场普遍采用。"},{"id":"real-bas-99","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"证券或期货市场通常采用做市商制度或者竞价交易制度。","options":["正确","错误"],"answer":"B","explain":"基金收益可以远超债券，股票型基金收益远高于债券；风险也不一定低于债券，偏股基金风险明显高于债券。"},{"id":"real-bas-100","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"基金主要投资于有价证券，投资选择灵活多样，但由于基金投资标的分散化程度较高，从而使基金的收益不可能高于债券，投资风险也低于债券。","options":["正确","错误"],"answer":"B","explain":"沪港通交易标的是股票，不是债券；内地投资者买港股、香港投资者买沪市A股，并非买卖债券。"},{"id":"real-bas-101","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"沪港通是指上海证券交易所与香港联合交易所有限公司建立技术连接，使内地投资者可以通过本地证券公司购买规定范围的香港联合交易所的上市债券，也可以通过香港证券公司买卖规定范围内的上海证券交易所的上市债券。","options":["正确","错误"],"answer":"A","explain":""},{"id":"real-bas-102","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"判断","q":"有的金融机构风险控制需要将风险控制类指标的考核体系中的权重提高，使得风险管理与业务发展的有机统一，其对一般高管人员影响实行薪酬延期，以增强对风险结果的敏感性。","options":["正确","错误"],"answer":"A","explain":"提高风控指标考核权重、对高管实行薪酬延期支付，能够约束短期逐利行为，强化风险责任意识，实现风控与业务协同发展。答案：对解析：金融期货具备价格发现功能，期货价格可预判未来现货价格，市场主体依托价格信号合理安排经营与生产规划。"},{"id":"real-bas-103","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"假定法定准备金比率（r）=0.10，现金（C）=2,800亿元，存款（D）=8,000亿元，超额准备金（ER）=400亿元，请根据上述背景信息回答111-113问题。下列说法中，正确的有（）","options":["基础货币是4000亿元","法定准备金是800亿元","超额准备金率是0.05","现金比率是0.35"],"answer":"D","explain":"货币乘数=（1+0.35）/（"},{"id":"real-bas-104","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"上述情形中，货币乘数是（）","options":["3.00","2.00","2.22","2.70"],"answer":"C","explain":"货币乘数=（1+0.35）/（"},{"id":"real-bas-105","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"若中央银行将存款的法定准备金率调整为0.08，基础货币和存款比率不变，新的货币供给是()。","options":["12558亿元","10800亿元","11250亿元","9302亿元"],"answer":"C","explain":"C选项正确，券商对拟上市企业进行尽职调查、上市辅导、推荐上市，属于保荐业务，对应股票发行里的保荐制度。A注册制：是审核上市的制度B承销：是发售股票环节D发审委：是审核会议机制"},{"id":"real-bas-106","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"某证券公司投行人员正接触一家经营良好的公司甲，他们准备推荐该公司公开发行股票和上市，并对该公司的申请文件和信息制度展开全方位的尽职调查和辅导。请根据上述背景信息回答以下114-115问题。该证券公司这单投行业务属于股票发行制度的（）。","options":["注册制度","承销制度","保荐制度","发审委制度"],"answer":"BD","explain":"A错误：变更募资用途需股东大会决议，非董事会；B正确：近三年财报无保留意见是IPO硬性条件；C错误：需具备持续经营的能力，不是持续盈利；D正确：必须有健全且运行良好的组织机构。"},{"id":"real-bas-107","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"该证券公司投行人员尽职调查后认为，公司甲符合首次公开发行新股的基本条件。这些条件包括（）","options":["公司甲如果改变募集资金用途，必须经董事会作出决议","最近三年财务会计报告被出具无保留意见审计报告","具有持续盈利能力","具备健全且运营良好的组织机构"],"answer":"ABC","explain":"中介服务类业务指商业银行根据客户委托，提供中介服务、收取手续费的业务，包括但不限于代理收付、财务顾问、资产托管、各类保管业务等，ABC选项正确。D选项，贷款业务是银行将其所吸收的资金贷放给客户赚取收益的活动，属于商业银行的资产业务，不属于表外业务。"},{"id":"real-bas-108","subject":"basics","source":"2026.06 真题汇编（考生回忆）","type":"案例","q":"根据材料回答116-118甲公司为一高科技企业，从事新材料研发和制造，其原材料大部分进口，产成品主要销往海外市场。为了更好地服务实体经济，A股份制商业银行与甲公司签订了全面合作和服务协议。根据商业银行的业务分类，下列属于商业银行表外业务中中介服务类业务的有（）。","options":["财务顾问","代理收付","资产托管","贷款业务"],"answer":"D","explain":"A银行承兑汇票：表外业务；B吸收存款：负债业务；C资产托管：中间业务；D贷款业务：资产业务。"}]},{"id":"n-law2","subject":"law","name":"11月300题 · 法规卷二","stats":{"单选":40,"多选":37,"判断":30,"案例":10},"questions":[{"id":"n-law2-0","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"《证券公司全面风险管理规范》要求证券公司建立健全与公司自身发展战略相适应前全面风险管理体系，该体系应覆盖的内容不包括 ()。","options":["各风险类型","各个部门、分支机构及子公司","各业务条线","各收益来源"],"answer":"D","explain":"《证券公司全面风险管理规范》要求证券公司建立健全与公司自身发展战略相适应全面风险管理体系，包括建立与业务复杂程度和风险指标体系相适应的风险管理信息技术系统，覆盖各风险类型、业务条线、各个部门、分支机构及子公司，对风险进行计算、汇总、预警和监控，故本题选择“各收益来源”。押题加"},{"id":"n-law2-1","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"按照规定，证券投资者保护基金的资金不可用于()。","options":["购买中央银行票据","购买中央级金融机构发行金融债券","购买国债","新股中购"],"answer":"D","explain":"证券投资保护基金的资金运用限于银行存款、购买国债 (C排除，题干为“不可用于”)、中央银行债券(包括中央银行票据，A排除)和中央级金融机构发行金融债券(B 排除)以及国务院批准的其他资金运用形式，不可用于新股申购，D项符合题意。故本题选D项。"},{"id":"n-law2-2","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"传统资产证券化中，属于企业债权资产的是()。","options":["设备租赁","企业信货","商业地产抵押信贷","住房抵押货款"],"answer":"A","explain":"传统的证券化资产包括:(1)银行的债权资产，如住房抵押贷款、商业地产抵押贷款、信用卡货款、汽车货款、企业货款等，B、C、D选项不符合题意:(2)企业的债权资产，如应收账款、设备租赁等，A选项符合题意。故本题选A选项。"},{"id":"n-law2-3","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"风险管理的第一步是()。","options":["风险估测","选择风险管理技术","风险识别","风险评价"],"answer":"C","explain":"风险管理的流程主要包括:风险的识别，风险的衡量，风险的应对，风险的监测、预警与报告，故本题选择“风险识别”。(一)风险的识别包括感知风险和分析风险。感知风险是通过系统化的方法发现经济主体所面临风险种类和性质:分析风险是深入理解各种风险的成因和变化规律。(二)风险的衡量，是计量风险发生的概率及潜在损失大小，评估风险严重程度，为确定风险管理对策提供依据。风险衡量方法有敏感性分析法、波动性分析法和压力测试等。(三)风险的应对，主要包括风险偏好管理、风险限额、风险定价与拨备、风险缓释以及应急计划等。(四)风险监测、预警与报告。风险监测是风险管理的重要一环，是风险偏好、风险限额，以及日常风险管理得以有效实施的重要保障。"},{"id":"n-law2-4","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据()划分，金融期权可以分为看涨期权和看跌期权。","options":["选择权性质","合约所规定的履约时间不同","基础资产性质","基础资产的来源"],"answer":"A","explain":"按照选择权的性质划分，金融期权可以分为认购期权(看涨期权)和认沽期权(看跌期权)。"},{"id":"n-law2-5","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司资本补充指引》，下列不属于证券公司资本管理应当遵循的原则是()。","options":["资本水平应当与业务发展相匹配","资本水平应该能够充分覆盖全部风险","资本水平应当与风险偏好相适应","资本水平应当与外部环境相适应"],"answer":"B","explain":"依据中国证券业协会规定，证券公司资本管理应当遵循以下原则:(1)资本水平应当与业务发展相匹配，(2)资本水平应当与风险偏好、风险管理水平和外部环境相适应，能够充分覆盖主要风险。故本题选择“应该能够充分覆盖全部风险”，应该是“主要风险”。"},{"id":"n-law2-6","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据导致金融市场风险因素的不同，市场风险不包括()。","options":["房价风险","利率风险","商品风险","外汇风险"],"answer":"A","explain":"市场风险是证券投资类机构面临的最基本的风险之一，是指因市场价格变量波动而给经济主体带来损益的风险。根据导致市场风险因素的不同，市场风险分为利率风险、外汇风险、股票价格风险和商品风险四种类型。(1)利率风险是指利率不利变动给金融机构财务状况带来风险。(2) 外汇风险又被称为汇率风险，是指在不同货币的相互兑换或折算中，因汇率在一定时间内发生不可预期的变化，从而使有关经济主体蒙受损失的风险。(3)商品风险是指因商品价格波动而带来损失风险。(4)股票价格风险是指由于某些因素的影响，使股票价格出现不利于投资者的波动，致使投资者在投资期内不能获得预期收益，甚至遭受损失一种可能性。"},{"id":"n-law2-7","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"沪伦通交易昀证券为()。","options":["存托凭证","上市股票","交易所规定上市股票","债券"],"answer":"A","explain":"沪伦通，是指上交所与伦交所的互联互通机制。初期从存托凭证起步(A正确)，沪伦通存托凭证业务包括东西两个业务方向。东向业务，是指符合条件的伦交所上市公司在上交所主板上市中国存托凭证；西向业务，是指符合条件的上交所A股上市公司在伦交所主板发行上市全球存托凭证。故本题选A项。"},{"id":"n-law2-8","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"沪深300股指期货合约交易代码为()。","options":["ETF","SZ","SH","IF"],"answer":"D","explain":"为规范中国金融期货交易所沪深 300股指期货合约交易行为，沪深300 股指期货合约交易代码为IF，常见的代码还包括:IC 是沪深500股指期货代码，IH是上证50指数期货代码。"},{"id":"n-law2-9","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"机构投资者与个人投资者差异明显，下列各项中属于机构投资者特点的是()。","options":["投资灵活性强","投资规模有限","投资结构组合化","投资行为具有随意性"],"answer":"C","explain":"与个人投资者相比，机构投资者具有以下特点:1、投资资金规模化。2、投资管理专业化。"},{"id":"n-law2-10","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"基础设施 REITs 购人项目(含首次发行与新购入项目)完成之日起2年内，净回收资金使用率原则上应不低于()，3年内应全部使用完毕。","options":["0.5","0.6","0.75","0.8"],"answer":"C","explain":"基础设施 REITs 购人项目(含首次发行与新购入项目)完成之日起2年内，净回收资金使用率原则上应不低于 75%，3年内应全部使用完毕。"},{"id":"n-law2-11","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"基础设施公募 REITS 要求收益分配比例不低于合并后基金年度可供分配金额()。","options":["0.9","0.8","0.6","0.7"],"answer":"A","explain":"基础设施公募 REITS 采取封闭式运作，收益分配比例不低于合并后基金年度可供分配金额90% (A正确，排除B、C、D项)。故本题选A项。"},{"id":"n-law2-12","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"既有损失机会又有获利可能的风险是()。","options":["系统性风险","投机风险","非系统性风险","纯粹风险"],"answer":"B","explain":"获取按照风险后果不同，风险可分为纯粹风险与投机风险。投机风险是相对于纯粹风险而言，是指既有损失机会又有获利可能的风险，例如单只股票价格波动对持有人造成的收益或损失。"},{"id":"n-law2-13","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"净稳定资金率这一指标用来衡量的是()。","options":["市场风险","操作风险","流动性风险","信用风险"],"answer":"C","explain":"流动性风险主要衡量指标:"},{"id":"n-law2-14","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"流动性风险通常被分为()。","options":["融资流动性风险和投资流动性风险","融资流动性风险和资产流动性风险","资产流动性风险和投资流动性风险","资产流动性风险和现金流动性风险"],"answer":"B","explain":"流动性风险，是指金融市场参与者无法以合理成本及时获得充足资金，以偿付到期债务、履行其他支付义务和满足正常业务开展的资金需求风险，通常被分为融资流动性风险和资产流动性风险。(1)融资流动性风险是指在不影响其日常经营和财务状况的条件下，金融机构难以有效满足其预期和非预期、当前和未来现金流和担保需求的风险。(2)资产流动性风险又被称为市场流动性风险，是指资产价值不受损害而进行变现的能力。"},{"id":"n-law2-15","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"某可转换公司债券面额为1000元，转换价格为25元/股，标股票内在价值30元/股，市场价格为32元/股，则转换比例为()。","options":["40","42","31","33"],"answer":"A","explain":"转换比例，是指一定面额可转换债券可转换成普通股票股数。用公式表示为:转换比例=可转换债券面值/转换价格。"},{"id":"n-law2-16","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"期货合约是由()统一制定的。","options":["中国证监会","期货交易所","中国期货业协会","证券交易所"],"answer":"B","explain":"期货合约是期货交易所统一制定的、规定在将来某一特定的时间和地点交割一定数量和质量标的物的标准化合约。"},{"id":"n-law2-17","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"企业可以通过()来实现对其他企业的控股或参股。","options":["资产管理计划","股票投资","收益权转让","发行债券"],"answer":"B","explain":"企业可以通过股票投资实现对其他企业控股或参股(B正确，排除 A、C、D项)，也可以将暂时闲置的资金通过自营或委托专业机构进行证券投资以获取收益。故本题选B项。"},{"id":"n-law2-18","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"任何金融衍生工具都存在因指数价格的不利变动而带来资产损失的可能性，这是()。","options":["结算风险","法律风险","市场风险","信用风险"],"answer":"C","explain":""},{"id":"n-law2-19","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"上海证券交易所托管制度是和()联系在一起。","options":["随处通买原则","哪买哪卖原则","自动托管制度","全面指定交易制度"],"answer":"D","explain":"上海证券交易所实行的托管制度与金面指定交易制度联系在一起。投资者必须指定一家证券公司作为其买卖证券受托人。"},{"id":"n-law2-20","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"首次公开发行股票并在主板上市，发行人应符合最近()内主营业务和董事、高管人员没有发生重大不利变化，实际控制人没有发生变更。","options":["1年","3年","2年","5年"],"answer":"B","explain":"首次公开发行股票并在主板上市，发行人应符合最近3年内主营业务和董事、高管人员没有发生重大不利变化，实际控制人没有发生变更。"},{"id":"n-law2-21","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"我国股权分置改革试点工作开始启动于()。","options":["1年","3年","2年"],"answer":"C","explain":""},{"id":"n-law2-22","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"我国沪、深交易所对 ST、ST*股票的涨跌幅限制为()。","options":["0.1","0.05","0.07","0.03"],"answer":"A","explain":"在中国 A股市场中，ST(特别处理)和*ST(退市风险警示)股票涨跌幅限制通常为10%。"},{"id":"n-law2-23","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"系统性风险又称为()。","options":["不可分散风险","政策风险","特殊风险","自有风险"],"answer":"A","explain":"系统性风险又称为不可分散风险，系统性风险主要由国家政治和经济的重大变革以及不可预知的自然灾害等因素引发，是指全局性的、影响整个金融市场的风险。经营风险、操作风险以及信用风险都是可以通过一些措施，来减少其发生的可能性，或者减少带来的损失，属于系统性风险。"},{"id":"n-law2-24","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列不属于商品期货是()。","options":["农产品期货","金属期货","能源化工期货","利率期货"],"answer":"D","explain":"商品期货，是指标物为实物商品期货合约。商品期货历史悠久，种类繁多，主要包括农产品期货、金属期货和能源化工期货等。“利率期货”属于金融期货。除此之外，金融期货还包括货币期货、股票指数期货和股票期货。"},{"id":"n-law2-25","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列各项关于证券公司各类风险界定说法，正确是()。","options":["声誉风险是指由证券公司经营管理及其他行为或外部事件导致证券公司股东、员工、客户、第三方合作机构及监管机构对证券公司前公开负面评价的风险","系统性风险通常具有外生性、关联性、复杂性、突发性、传染性等特征","巴塞尔委员会认为，战略风险是由于不利的经营决策，或决策执行不当，而对收益或资本造成影响风险","法律风险属于市场风险的范畴"],"answer":"A","explain":"(1)系统性风险通常具有内生性、关联性、复杂性、突发性、传染性等特征。(2)声誉风险是指由证券公司经营管理及其他行为或外部事件导致证券公司股东、员工、客户、第三方合作机构及监管机构等对证券公司的公开负面评价风险。(3) 美国货币监理署认为，战略风险是由于不利的经营决策，或决策执行不当，而对收益或资本造成影响的风险。(4) 市场风险，是指因市场价格变量波动而给经济主体带来损益的风险。(5) 操作风险是指由不完善或有问题的内部流程、人员和系统以及外部事件所造成损失前风险。该定义包括法律风险，但不包括战略风险和声誉风险。"},{"id":"n-law2-26","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列各项中，不属于间接融资特点的是()","options":["融资相对集中性","部分融资方式具有不可逆性","融资主动权主要掌握在金融中介机构手中","融资信誉的差异性相对较小"],"answer":"B","explain":"间接融资特点包括“融资相对集中性”、“融资主动权主要掌握在金融中介机构手中”、“融资信誉的差异性相对较小”。部分融资方式的不可逆性是直接融资特点。"},{"id":"n-law2-27","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于风险限额管理的说法，错误的是()。","options":["风险限额监测是为了检查公司经营活动是否服从于限额，是否存在突破限额的现象","证券公司应当建立定期盯市制度，准确计算、监测关键风险指标情况","风险限额的设定首先需要全面风险计量，以确定各类敞口的预期损失和非预期损失","对超限额的处置，应当由风险管理部门负责组织落实，对超限额处置实际效果要定期进行返回检验"],"answer":"B","explain":"风险限额管理包括风险限额设定、风险限额监测、超限额处置等环节。(1) 风险限额设定，分成四个阶段:第一，全面风险计量，确定各类敞口的预期损失和非预期损失。第二，利用会计信息系统，对各业务敞口收益和成本进行量化分析，制订方案。第三，运用资产组合分析模型，对各业务敞口确定经济资本增量和存量。第四，综合考虑监管部门的政策要求以及公司战略管理层风险偏好，最终确定各业务敞口的风险限额。(2) 风险限额监测，为了检查公司的经营活动是否服从于限额，是否存在突破限额的现象。证券公司应当建立逐日盯市等机制，准确计算、动态监控关键风险指标情况，故“定期町市制度”表述错误，应该是“逐日盯市”。(3) 超限额处置，应由风险管理部门负责组织落实，对超限额处置的实际效果要定期进行返回检验。"},{"id":"n-law2-28","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于公募基金信息披露的说法，错误是()","options":["公募基金的一个突出特点是透明度较高","在我国，公募基金信息披露具有自愿性","公募基金披露信息要具有真实性、准确性和完整性","披露信息是了解、识别公募基金的重要信息来源渠道"],"answer":"B","explain":"在我国，基金的信息披露具有强制性。"},{"id":"n-law2-29","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于金融市场说法，错误是()。","options":["鉴于交易所市场和场外市场的交易双方都进行直接的交易，交易对手风险不存在明显差","狭义的有价证券指资本证券，广义的有价证券包括商品证券、货币证券和资本证券","按辐射地域，可以将金融市场分为国际金融市场和国内金融市场","中国外汇交易中心一般归为场外市场"],"answer":"A","explain":"交易所市场存在中央对手方(CCP)机制，可以有效降低交易对手风险。而场外市场交易通常是一对一的直接交易，交易对手风险明显高于交易所市场。因此，选项A的说法错误."},{"id":"n-law2-30","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于欺诈发行上市股票责令回购的说法，错误是()。","options":["发行人应当在收到责令回购决定书后5个交易日内披露有关信息","证监会可以责令负有责任的控股股东、实际控制人买回股票","证监会可以依法责令发行人回购欺诈发行股票","发行人应当在责令回购决定书要求的期限内制定股票回购方案"],"answer":"A","explain":"欺诈发行责令回购规定中，发行人应当在收到责令回购决定书后的2个交易日内披露有关信息，而非5个交易日。"},{"id":"n-law2-31","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于债券登记的说法，错误是()","options":["债券登记时确定或变更债券持有人及其权利的法律行为，是保障投资者合法权益的重要措","债券登记是指债券登记结算机构为债券发行人建立和维护债券持有人名册行为","债券登记量等于已经发行但尚未到期的债券总量","债券登记是证券要素和证券权利记录和确认"],"answer":"C","explain":"债券登记是指债券登记结算机构为债券发行人建立和维护债券持有人册的行为，也就是证券要素和证券权利记录和确认。债券登记时确定或变更债券持有人及其权利的法律行为，是保障投资者合法权益的重要措施。"},{"id":"n-law2-32","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于证券公司操作风险旳说法，错误是()。","options":["证券公司可利用资产损失率、案件发生率、失败交易数量等指标对操作风险进行监测及早期预警","情景分析是证券公司评估操作风险可能造成损失数据来源之一","根据损失事件类型可将操作风险划分为八种表现形式","保险是证券公司转嫁操作风险的主要手段"],"answer":"C","explain":"(1) 操作风险的分类方法:①根据定义将其划分为由人员、系统、流程和外部事件所引发的四类风险:②根据损失事件类型将其划分为七种表现形式:内部欺诈，外部欺诈，就业制度和工作场所安全，客户、产品和业务活动，实物资产的损坏，营业中断和信息技术系统瘫痪，执行、交割和流程管理。故“八种表现形式”表述错误。(2) 关键风险指标:资产损失率、案件发生率、失败交易数量、员工流动率、客户投诉次数、错误和遗漏频率以及严重程度等。(3)操作风险损失数据收集主要基于以下四个方面；①内部损失数据:②外部损失数据；③情景分析；④业务环境和内部控制因素；(4)保险是证券公司转嫁操作风险主要手段。"},{"id":"n-law2-33","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列情形符合面向专业投资者公开发行公司债券要求是()。","options":["发行人最近三年平均可分配利润足以支付公司债券一年利息","违反《证券法》规定，改变公开发行公司债券所募资金用途","发行人对已公开发行公司债券有违约事实，仍处于继续状态","发行人对己公开发行的公司债券有延迟支付本息事实，仍处于继续状态"],"answer":"A","explain":"根据《证券法》第十七条规定，存在下列情形之一的，不得再次公开行公司债券:"},{"id":"n-law2-34","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列属于风险管理本质特征是()；风险管理的基本目标是()。","options":["事后管理；损失前目标","损失管理:损失后目标","事前管理:以最小成本获得最大安全保障","盈利管理:以较小成本获得较大安全保障"],"answer":"C","explain":"风险管理不等于损失管理，其本质特征是事前管理。损失前目标和损失后目标是风险管理具体目标。以最小成本获得最大安全保障是风险管理的基本目标。"},{"id":"n-law2-35","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列有关债券说法，错误是()。","options":["信用公司债券是一种不以公司任何资产作担保而发行的债券，属于无担保债券范畴","金融债券大多数可以免除担保","一般来说，政府债券无须提供担保","大多数公司发行债券不需要提供担保"],"answer":"D","explain":"信用公司债券是一种不以公司任何资产作担保而发行的债券，属于无担保证券范畴。一般来说，政府债券无须提供担保，因为政府掌握国家资源，可以征税，所以政府债券安全性最高。金融债券大多数也可免除担保，因为金融机构作为信用机构，本身就有较高的信用。公司债券不同，公司的信用状况一般比政府和金融机构差，所以，大多数公司发行债券被要求提供某种形式的担保。"},{"id":"n-law2-36","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券公司承担的信用风险在其整体风险承担中的占比()商业银行。","options":["高于","低于","类似于","等同于"],"answer":"B","explain":"证券公司面临信用风险的相关业务和资本市场有很强的关联性。业务结构特点决定了证券公司承担的信用风险在其整体风险承担中的占比要低于商业银行。故本题选择“低于”。"},{"id":"n-law2-37","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券公司承担全面风险管理的最终职责的是()。","options":["股东(大)会","首席风险官","经理层","董事会"],"answer":"D","explain":"证券公司应当明确董事会、监事会、经理层、各部门、分支机构及子公司履行全面风险管理的职责分工，建立多层次、相互衔接、有效制衡的运行机制。(1)证券公司董事会承担全面风险管理的最终责任，履行的职责包括推进风险文化建设，审议基本制度，审议批准公司的风险偏好等:故本题选择“董事会”。(2)证券公司经理层对全面风险管理承担主要责任，应当履行的职责包括:制定风险管理制度，并适时调整等；(3)证券公司应当指定或者设文专门部门履行风险管理职责，在首席风险官的领导下推动全面风险管理工作，监测、评估、报告公司整体风险水平等；(4) 证券公司应当将子公司的风险管理纳入统一体系，对其风险管理工作实行垂直管理。"},{"id":"n-law2-38","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券竞价交易必须遵循的原则是()。","options":["价格优先原则和时间优先原则","客户优先原则和时间优先原则","时间优先原则和数量优先原则","价格优先原则和数量优先原则"],"answer":"A","explain":"证券交易所内证券竞价交易按“价格优先、时间优先”(A项正确)的原则撮合成交:证券公司自营业务和客户指令冲突时，遵循“客户优先”原则，“数量优先”属于干拢项，排除B、C、D项。故本题选A项。"},{"id":"n-law2-39","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券托管是指投资者将持有的证券委托给()保管。","options":["证券公司","中国证监会","证券营业部","中国结算"],"answer":"A","explain":"证券托管是指投资者将持有证券委托给证券公司(A正确)保管，并由证券公司代为处理有关证券权益事务的行为。故本题选A项。信XSs！"},{"id":"n-law2-40","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"按股东享有权利的不同，股票可以分为 ()。","options":["特别股票","记名股票","普通股票","无记名股票"],"answer":"AC","explain":"按股东享有权利的不同，股票可分为普通股票和特别股票。1、普通股票。普通股票秉持“一股一权”规则之下收益权与表决权无差别、等比例配置的股票。2、特别股票。特别股票是指设有特别权利或特别限制的股票。"},{"id":"n-law2-41","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"按照所交易产品品种的不同，可以将资本市场分为()等。","options":["私募市场","股票市场","债券市场","衍生品证券市场"],"answer":"BCD","explain":"按交易产品品种分类，资本市场可分为股票市场、债券市场、基金市场、衍生品证券市场等。私募市场是按发行方式(公开/非公开)分类。"},{"id":"n-law2-42","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"常用风险调整后收益指标有()。","options":["夏晋比率","索提诺比率","信息比率","多因子"],"answer":"ABC","explain":"常用的风险调整后收益指标有夏普比率、索提诺比率、信息比率等，多因子属于业绩归因方法，而非“风险调整后收益指标”。"},{"id":"n-law2-43","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"出于不同的用途，债券收益率的计算方式种类繁多。下列说法错误的有()。","options":["到期收益率是使债券未来现金流现值等于当前价格所用的相同的贴现率","当期收益率是零息债券到期收益率简称","持有期收益率是指买入债券到卖出债券期间所获得年平均收益率","即期利率为债券的年利息收入与买入债券的实际价格的比率"],"answer":"BD","explain":"当期收益率是债券的年利息收入与买入债券的实际价格的比率(通常用于附息债券)，而零息债券的到期收益率是特殊的。即期利率是零息债券到期收益率。因此选项B和D对概念解释错误。"},{"id":"n-law2-44","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"当会员或客户的金融期货持仓达到交易所规定的数量时，必须向交易所申报有关()等情况，以便交易所审查大户是否有过度投机和操纵市场行为。","options":["开户情况","交易情况","资金来源","交易成本"],"answer":"ABC","explain":"大户报告制度是交易所建立限仓制度后，当会员或客户持仓量达到交易所规定的数量时，必须向交易所申报有关开户、交易、资金来源、交易动机等情况，以便交易所审查大户是否有过度投机和操纵市场行为，并判断大良交易风险状况风险控制制度。"},{"id":"n-law2-45","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》，普通股股东行使剩余财产分配权，必须在公司解散清算时，公司财产经法定清偿后，方可对剩余财产按照股东持有股份比例进行分配。其中，公司财产法定清偿包括()。","options":["职工的工资、社会保险费用和法定补偿金","清偿公司债务","缴纳所欠税款","支付清算费用"],"answer":"ABCD","explain":"我国《公司法》规定，公司财产在分别支付清算费用(D正确)、职工的工资、社会保险费用和法定补偿金(A正确)，缴纳所欠税款(C正确)，清偿公司债务(B正确)后剩余财产，按照股东持有的股份比例分配。公司财产在未按照规定清偿前，不得分配给股东。故本题选 ABCD 项。"},{"id":"n-law2-46","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据我国股票发行监管制度的演变，下列有关说法，正确的有()。","options":["发行监管制度中，核准制包括指标管理和通道制两个阶段","1993年，证券市场建立了全国统一的股票发行审核制度，并先后经历了行政主导的审批制和市场化方向的核准制两个阶段","发行监管制度中，审批制包括额度管理和保荐制两个阶段","2020年3月1日，新《证券法》正式实施，核准制开始向全面注册制转变"],"answer":"BD","explain":"审批制包括额度管理和指标管理两个阶段，而核准制包括通道制和保荐制两个阶段(A 错误，应为“通道制和保荐制”，而非“指标管理和通道制”今C错误，应为“额度管理和指标管理”，而非“额度管理和保荐制”)；2020年3月7日，新《证券法》正式施行，核准制开始向全面注册制转变，注册制改革是完善资本市场基础制度的重要体现(D正确):1993年，证券市场建立了全国统一的股票发行重核制度，并先后经历了行政主导审批制和市场化方向的核准制两个阶段(B 正确)。散本题选BD项。"},{"id":"n-law2-47","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"公募证券投资基金的募集，今-一般要经过步骤包括()。","options":["基金注册","基金合同发布","基金份额的发售","基金募集申请"],"answer":"ACD","explain":"基金的募集一般要经过申请、注册、发售、基金合同生效四个步骤。"},{"id":"n-law2-48","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"股权类期权包括()。","options":["单只股票期权","股票组合期权","认股权证期权","股价指数期权"],"answer":"ABD","explain":"与股权类期货类似，股权类期权也包括三种类型:单只股票期权、股票组合期权和股价指数期权。"},{"id":"n-law2-49","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于多层次资本市场的意义，下列说法正确的有()。","options":["有利于创新宏观调控机制，防范和化解经济金融风险","有利于促进产业整合，缓解产能过剩","有利于促进科技创新，促进新兴产业发展和经济转型","有利于促进储蓄转化为投资，提升服务实体经济能"],"answer":"ABCD","explain":"信构建多层次资本市场意义包括:促进储蓄转化为投资、促进科技创新和产业整合、防范经济金融风险等。"},{"id":"n-law2-50","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于公司型基金表述，正确有()。","options":["基金是独立法人机构","基金不是独立法人机构","投资者是基金公司股东","投资者不享有股东权益"],"answer":"AC","explain":"按基金的组织形式划分，可分为契约型基金和公司型基金。契约型基金依据基金管理人、基金托管人之间所签署的基金合同设立，基金投资者购买基金份额后成为基金持有人，依法享受权利并承担义务。目前，我国的基金全部是契约型基金。公司型基金依据基金公司章程设立，是在法律上具有独立法人地位股份投资公司。基金投资者是公司的股东，凭其持有的股份依法享有投资收益。公司型基金在组织形式上与股份有限公司类似，由股东选举董事会，由董事会选聘基金管理公司，基金管理公司负责管理基金的投资业务。契约型基金与公司型基金的区别:(1)资金性质不同，契约型基金的资金是通过发行基金份额筹集的信托财产；公司型基金的资产是通过发行普通股票筹集的公司法人资本。(2)投资者的地位不同。契约型基金的投资者购买基金份额后成为基金契约当事人之一，投资者既是基金的委托人，即基于对基金管理人的信任，将自己的资金委托给基金管理人管理和营运，又是基金的受益人，即享有基金的受益权。公司型基金的投资者购买基金公司股票后成为该公司的股东。(3)基金的营运依据不同。契约型基金依据基金合同营运基金，公司型基金依据投资公司章程营运基金。"},{"id":"n-law2-51","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于金融期权的说法，正确的有()。","options":["金融期权门主要特征在于它仅仅是买卖权利前交换多。","期权买方在支付了期权费后，承担着履行该期权合约义务","期权卖方在收取期权费后，承担着在规定时间内履行该期权合约义务","当期权买方选择行使权利时，卖方必须无条件地履行合约规定义务"],"answer":"ACD","explain":""},{"id":"n-law2-52","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于债券估值定价分类，一般包括()。","options":["含权债券定价","累息债券定价","零息债券定价","附息债券定价"],"answer":"BCD","explain":"债券估值模型包括零息债券定价、附息债券定价和累息债券定价。"},{"id":"n-law2-53","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"国别风险主要包括()。","options":["主权风险","货币风险","政治风险","转移风险"],"answer":"ABCD","explain":"押题加微国别风险存在于授信、国际资本市场业务、设立境外机构等经营活动中。国别风险主要包括转移风险 (D正确)、主权风险(A正确)、货币风险(B正确)、政治风险 (C正确)。故本题选 ABCD。"},{"id":"n-law2-54","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"货币政策的信用传导机制通过()完成。","options":["银行信货渠道","企业资产负债表渠道","生命周期","财富效应"],"answer":"AB","explain":"伯南克提出了银行借货渠道和资产负债渠道两种信用传导机制，并得出货币政策传递过程中即使利率没发生变化，也会通过信用途径来影响国民经济总量的结论。"},{"id":"n-law2-55","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"基金的专业管理体现在基金管理人 ()。","options":["有大量专业投资研究人员","有强大的信息网络","能够对市场进行深入分析","能够发挥资金规模优势"],"answer":"ABC","explain":"证券投资基金是指通过公开发售基金份额募集资金，由基金托管人托管，由基金管理人管理和运用资金，为基金份领特有人附利益，以资产组合方式进行证券投资附一种利益共享，风险共担的集合投资方式。基金管理人一般拥有专业的投资研究人员和强大的信息网络，能够"},{"id":"n-law2-56","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"基金资产估值是指通过对基金所拥有的()按一定的原则和方法进行估算，进而确定基金资产公允价值的过程。","options":["经营利润","资金流量","全部资产","所有负债"],"answer":"CD","explain":"基金资产估值，是指通过对基金所拥有的全部资产(C正确:A错误，而非“利润”，而是“全部资产”；B错误，而非“资金流量”，而是“全部资产”)及所有负债(D正确)按一定的原则和方法进行估算，进而确定基金资产公允价值过程。故本题选 CD项。"},{"id":"n-law2-57","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"金融理论界对风险的定义主要有()。","options":["风险是结果的不确定性，是一种变化","风险是结果对期望的偏离，是(收益的)波动性","风险是损失发生可能性，或可能发生损失","风险等同于危险"],"answer":"ABC","explain":"目前，国内外金融理论界对风险的定义或界定主要有以下三类观点:(1)风险是结果的不确定性，是一种变化 (A正确)；(2)风险是损失发生可能性，或可能发生损失(C 正确)；(3) 风险是结果对期望的偏离，是(收益)波动性(B 正确)。风险不仅包括损失的可能性，也包括对盈利可能性的覆盖，故D项错误，故本题选 ABC 项。"},{"id":"n-law2-58","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"金融期货与金融期权区别表现在()。","options":["基础资产不同","套期保值的作用与效果不同","履约保证不同","盈亏特点不同"],"answer":"ABCD","explain":"金融期权与金融期货区别:"},{"id":"n-law2-59","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"金融自由化的主要内容包括 ()。","options":["逐步实现利率自由化","鼓励银行综合化发展","放松外汇管制","放宽对资本流动的限制"],"answer":"ABCD","explain":"金融自由化的主要内容包括:(1)取消对存款利率的最高限额，逐步实现利率自由化；(2)打破金融机构经营范围的地域和业务种类限制，允许各金融机构业务交叉、互相自由渗透，鼓励银行综合化发展:(3)放松外汇管制:(4) 开放各类金融市场放宽对资本流动的限制。"},{"id":"n-law2-60","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"投资者在参与沪深300股指期货交易时，所使用的交易编码应根据投资目的不同分为()。","options":["套期保值用途","套利用途","套汇用途","投机用途"],"answer":"ABD","explain":"交易编码是客户、从事自营业务前交易会员进行期货交易的专用代码。投资者可以根据不同投资目的，分别申请套期保值、套利和投机用途的客户号。"},{"id":"n-law2-61","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列各项中，可以充当金融衍生工具基础的变量的有6》。","options":["通货膨胀率","信用等级","温室气体排放","银行定期存单"],"answer":"ABC","explain":"密包金融衍生工具基础变量种类繁多，主要是各类资产价格、价格指数、利率、汇率、费率、通货膨胀率以及信用等级等:近些年来，某些自然现象(如气温、降雪量、霜冻、飓风)，甚至人类行为(如选举、温室气体排放)也逐渐成为金融衍生工具的基础变量。与之不同的是现货金融产品(如债券、股票、银行定期存款单等)。"},{"id":"n-law2-62","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列各项中，属于利用金融市场进行风险管理的行为有()。","options":["持有未到期外汇应付账款进口商卖出了对应外汇的期货合约","持有债券的保险基金购入了信货违约互换合约","持有股票的证券投资基金出售了股指期货合约","担心火灾的厂商购买了保险合约"],"answer":"ABCD","explain":"风险管理策略，是指金融机构面临风险时可以选择采用的应对方法，主要包括风险规避、风险控制、风险分散、风险对冲、风险转移、风险补偿与准备金。"},{"id":"n-law2-63","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于风险管理流程的说法，正确的有()。","options":["风险的应对主要包括风险偏好管理、风险计量、风险定价与报备、风险缓释以及应急计划","风险监测是风险管理的重要一环，是风险偏好、风险限额，以及日常风险管理得以有效实施的重要保障","证券公司应当建立逐日盯市的机制，准确计算、动态监控关键风险指标情况，判断和预测各类风险指标的变化，及时预警超越各类、各级风险限额情形","证券机构应当建立健全风险报告体系定期对公司所面临的风险状况进行检测，编制风险报告，确保各类风险信息顺畅并及时的在公司内部传递"],"answer":"BCD","explain":"①风险的应对主要是证券公司根据风险识别、计量、监控及预警等情况，针对不同类别、不同发生概率及不同损失程度的风险所采取应对措施，主要包括风险偏好管理、风险限额、风险定价与拨备、风险缓释，以及应急计划等，故“风险计量”表述错误。②风险监测是风险管理重要一环，是风险偏好、风险限额，以及日常风险管理得以有效实施的重要保障。③证券公司应当建立逐日盯市等机制，准确计算、动态监控关键风险指标情况，判断和预测各类风险指标的变化，及时预警超越各类、各级风险限额的情形。④证券机构应该建立健全风险报告体系，定期对公司所面临的风险状况进行检测，编制风险报告，确保各类风险信息顺畅并及时地在公司内部传递。"},{"id":"n-law2-64","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于风险管理相关的活动中，属于风险控制过程中事中控制措施的有()。","options":["风险定价","流程控制","工具控制","实时监测和报告"],"answer":"BCD","explain":"事前控制主要是确定风险管理政策，包括确定风险容忍度、风险限额、风险定价和制订应急预案等:事中是指在风险资产的实际运作过程中采用流程、工具进行动态、实时监测和报告；事后控制是在风险影响因素发生变化或风险发生后采取的对应措施，包括风险转移和重新调整风险限额。"},{"id":"n-law2-65","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于国债销售价格影响因素说法，正确的有()。","options":["通过投标获得较低成本国债，有利于分销工作顺利展开","如果国债承销价格定价过低，投资者就会倾向于在二级市场上购买已流通的国债，从而阻碍国债分销工作顺利进行","降低销售价格，承销商的分销过程会缩短，资金的回收速度会加快，从而提高收益","影响国债销售价格的因素包括市场利率、流通市场中可比国债收益率水平、承销商所期望的资金回收速度等"],"answer":"ACD","explain":"包如果国债承销价格定价过高，投资者就会倾向于在二级市场上购买己流通的国债，从而阻碍国债分销工作顺利进行。"},{"id":"n-law2-66","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于基金投资对象说法，正确的有()。","options":["股票基金应有80%以上的基金资产投资于股票","债券基金应有 90%以上前基金资产投资于债券","货币市场基金投资对象为期限较短的货币市场工具","混合基金是可同时投资于股票与债券基金"],"answer":"ACD","explain":"按基金的投资标的划分，可分为股票基金、债券基金、混合基金、货币市场基金等。股票基金是指以股票为主要投资对象的证券投资基金。在我国，根据中国证监会对基金类别的分类标准，80%以上的基金资产投资于股票的，为股票基金。债券基金是一种以债券为主要投资对象证券投资基金。在我国，根据中国证监会对基金类别的分类标准，80%以上的基金资产投资于债券，为债券基金。混合基金是指同时投资于股票与债券的基金，该类基金由于资产配置比例不同，风险收益差异较大。货币市场基金是仅以货币市场工具为投资对象一种基金，其投资对象期限较短，一般在1年以内，包括银行短期存款、国库券、公司短期债券、银行承兑票据及商业票据等货币市场工具。货币市场基金没有申购、赎回费率。"},{"id":"n-law2-67","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于金融机构和风险的说法，正确有()。","options":["风险管理是金融机构核心竞争力","金融机构必定会承担风险","风险管理以为公司创造价值为目标","内部控制是一种传统风险管理方法"],"answer":"ABCD","explain":"(1) 金融机构企业本质和基本使命就在于承担和管理风险，并实现风险换收益。金融机构尽管可以从单个项目上规避风险，但是不可能规避或不承担任何风险。(2) 风险管理是金融机构的核心竞争力。以内部控制为主要内容的传统风险管理己经发展到包含风险对冲、限额、定价以及风险业绩调整等更加全面的现代风险管理阶段，进而风险管理也进入金融机构战略管理的层面，超越了保驾护航的范畴，成为核心竞争力。(3)风险管理助力金融业务持续、稳定、健康发展。风险管理的目标是创造价值，而不是减少损失或降低风险。"},{"id":"n-law2-68","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于我国中证中小投资者服务中心有限责任公司具体职责的说法，正确的有()。","options":["组织和监督投资者证券交易","调查、监测投资者意愿和诉求，开展战略研究与规划","提供调解、损失计算等纠纷解决服务","面向投资者开展公益性宣传和教育"],"answer":"BCD","explain":"组织和监督证券交易属于证券交易所的主要职能。"},{"id":"n-law2-69","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于信用违约互换的说法，正确的有()。","options":["信用违约互换从本质上看可视为一种针对债务工具违约的保险单","在信用违约互换交易中，买方在合约期限内或在信用事件发生前定期向信用风险保护的卖方就某个参照实体信用事件支付费用，以换取信用事件发生后赔付","在信用违约互换交易中，合约买方一般需要真正持有作为参考信用工具","信用违约互换具有较高杠杆性"],"answer":"ABD","explain":""},{"id":"n-law2-70","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于信用衍生工具前说法，正确的有()。","options":["主要包括信用违约互换、信用联结票据等","是以基础产品所蕴含信用风险或违约风险为基础变量的金融衍生工具","用于转移或防范系统性风险","是20 世纪 90 年代以来发展最为迅速的一类衍生产品"],"answer":"ABD","explain":"信用衍生工具是指以基础产品所蕴含的信用风险或违约风险为基础变量的金融衍生工具，用于转移或防范信用风险，是20世纪 90年代以来发展最为迅速的一类衍生产品，主要包括信用互换、信用联结票据以及信用风险缓释合约、信用风险缓释凭证等信用风险缓释工具。"},{"id":"n-law2-71","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于涨跌幅限制下委托有效的说法，正确的有()。","options":["高于涨幅限制价格委托","低于涨幅限制价格委托","高于跌幅限制价格委托","低于跌幅限制价格委托"],"answer":"BC","explain":"证券交易所可根据需要对每日股票价格涨跌幅度予以适当的限制，高于涨幅限制价格的委托和低于跌幅限制价格委托无效。"},{"id":"n-law2-72","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于直接融资与间接融资的说法，正确的有()。","options":["直接融资与间接融资区别在于融资过程中资金需求者与资金的供求者是否直接形成债权债务关系","在许多情况下，从融资所采用的金融工具上就能准确判断出融资是属于直接融资还是间接","一般习惯上认为凡是债权债务关系中的一方是金融机构的融资就是间接融资","直接融资是间接融资基础"],"answer":"ACD","explain":"B 项错误，在许多情况下，单纯从活动中所使用的金融工具出发尚不能准确地判断融资的性质究竟属于直接融资还是间接融资。一般认为，直接融资活动从时间上早于间接融资，直接融资是间接融资的基础，D正确。"},{"id":"n-law2-73","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列可以跨市场转托管的债券有()。","options":["公司债","证券公司次级债","企业债","国债"],"answer":"ABCD","explain":"转托管，是指同一投资人开立的两个托管账户之间的托管债券的转移，即其持有的债券从一个托管账户转移到属于该投资者的另一个托管账户进行托管。目前，除了国债(包括附息国债和地方债)和企业债 (C、D正确)可以跨市场转托管外，其他债券品种(包括公司债、证券公司次级债、中小企业私募债)都不能跨市场转托管(A、B错误)。故本题选CD项。A. 信用违约互换B.信用远期协议C. 信用关联票据D. 总收益互换信用衍生品主要包括:信用违约互换(CDS)、总收益互换、信用远期协议、信用关联票据等。因此四个选项均正确。"},{"id":"n-law2-74","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"现代信用风险分析的构成要素包括()。","options":["违约概率","违约损失率","违约时的风险暴露","违约时间"],"answer":"BC","explain":"(1) 信用风险的构成要素分析以违约为中心。在信用风险分析中，违约依然是最为重要的信用事件，对信用风险的描述和量化仍然是以违约为中心，主要包括违约概率(PD)、违约损失率(LGD)和违约时的风险暴露 (EAD)等。(2)这些要素决定了信用产品的预期损失和非预期损失。对这些信用风险要素量化是以损失概率分布进行科学描述风险基础。现代风险计量方法的中心工作就是以各种模型准确量化这些风险要素。A. 制定、修改证券交易所业务规则B.制定和修改证券交易所章程C. 审议和通过证券交易所财务决算D. 审定对会员接纳制定、修改证券交易所业务规则属于证券交易所的职能，审定对会员的接纳是理事会的职权。"},{"id":"n-law2-75","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"证券公司开展融资融券业务，应当在证券登记结算机构以自己名义分别开立()。","options":["信用交易资金交收账户","客户信用交易担保证券账户","信用交易证券交收账户","融券专用证券账户"],"answer":"ABCD","explain":"证券公司开展融资融券业务，应在登记结算机构开立融券专用证券账户、客户信用交易担保证券账户、信用交易证券交收账户和信用交易资金交收账户。因此四个选项均正确。"},{"id":"n-law2-76","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"证券公司压力测试可采用的方法有()。","options":["敏感性分析","历史情景法","假设情景法","历史情景法和假设情景法相结合"],"answer":"ABCD","explain":""},{"id":"n-law2-77","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"QDTI是境外合格投资者。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。合格境内机构投资者(QDII)制度，是指经一国金融管理当局审批通过、获准直接投资境外股票或者债券市场的国内机构投资者，在一定规定下通过基金形式募集一定额度的人民币资金，通过严格监管的专门账户投资国外证券市场，其汇回的资本利得、股息红利等经审核后可转为本币的一种市场开放机制。"},{"id":"n-law2-78","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"按照现行规定，基金经理在研究部门的支持下，结合自身对证券市场和上市公司的分析判断，拟订投资组合和投资方案，向交易部门下达投资指令，基金经理不得直接向交易员下达投资指令或者直接进行交易。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。根据投资决策委员会决议，基金经理在研究部门支持下，结合自身对证券市场和上市公司的分析判断，拟订投资组合和投资方案，向交易部下达投资指令，按规定，基金经理不得直接向交易员下达投资指令或者直接进行交易。"},{"id":"n-law2-79","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"采用注册制股票发行方式，证券交易所、中介机构和中国证监会分担实质审核职责。","options":["正确","错误"],"answer":"B","explain":"本题表述错误。注册制的核心是以信息披露为中心，证券交易所和中介机构负责对信息披露的合规性进行审核，审核部门不对企业的投资价值作出判断，即不再进行实质审核。"},{"id":"n-law2-80","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"短期融资券，是指具有法人资格的非金融企业在银行间债券市场发行的，约定在1年内还本付息的债务融资工具。企业在注册有效期内需更换主承销商或变更注册金额的，应重新注册。交易商协会不接受注册的，企业可于3个月后重新提交注册文件。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。企业在注册有效期内需更换主承销商或变更注册金额，应重新注册。交易商协会不接受注册的，企业可于6个月后重新提交注册文件。"},{"id":"n-law2-81","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"短期融资券的期限一般不短于1年。()()","options":["正确","错误"],"answer":"B","explain":"本题表还错误。短期融资券期限一般不长于1年。"},{"id":"n-law2-82","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"凤险管理不等于损失管理，其本质特征是事后管理。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。风险管理不等于损失管理，其本质特征是事前管理。"},{"id":"n-law2-83","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"股票退市制度包括主动退市和强制退市。上市公司的股票终止上市后，其终止上市情形已消除，达到证券交易所规定重新上市条件的，可以向证券交易所申请重新上市。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。退市分为主动退市和强制退市，并且终止上市后若消除终止上市情形并达到重新上市条件，可以申请重新上市。"},{"id":"n-law2-84","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"股票质押式业务面临的信用风险是指股权质押业务的融资主体不能按时履约风险。证券公司股权质押业务一般资金主要来源于券商自营、银行信托、集合资管计划等，因融入方质押股价大幅下调触发平仓线或触发违约情形无法及时还款付息，股票质押业务可能遭遇强行平仓，进而引发连锁风险。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。股票质押业务面临的信用风险是指股权质押业务融资主体不能按时履约的风险。对于证券公司的股权质押业务，一般资金主要来源于券商自营、银行信托、集合资管计划等。因融入方质押股价大幅下调触发平仓线或触发违约情形无法及时还款付息，股票质押业务可能遭遇强行平仓，进而引发连锁风险。故术题选A。"},{"id":"n-law2-85","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"国家发改委明确规定项目发起人(原始权益人)应为持有消费基础设施、开展相关业务的独立法人主体，可以从事商品住宅开发业务。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。国家发改委明确规定项目发起人(原始权益人)应为持有消费基础设施、开展相关业务独立法人主体，不得从事商品住宅开发业务。"},{"id":"n-law2-86","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"国债的竞争性招标方式包括单一价格、修正的多重价格招标方式 (即混合式)，招标标的仅为利率。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。国债竞争性招标方式包括单一价格、修正的多重价格招标方式(即混合式)，招标标的为利率或价格(而非题干中的“仅为利率”)。"},{"id":"n-law2-87","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"基金类投资者包括证券投资基金、社保基金、企业年金、职业年金和社会公益基金。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。基金类投资者(机构投资者的一种》包括证券投资基金、社保基金、企业年金、职业年金、社会公益基金等。"},{"id":"n-law2-88","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"价格发现是衍生工具市场初始功能，是衍生工具市场发展一个立足点，这是基于期货市场特征决定。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。衍生品市场最基础、初始、首要功能不是价格发现，而是风险管理(套期保值)。"},{"id":"n-law2-89","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"结构化金融产品通常会内嵌一个或一个以上的衍生品，其挂钩基础资产具有不同风险特征，嵌入式衍生产品的种类、结构各异，导致结构化产品的收益与风险出现非常大的差异，监管机构要求金融机构在销售时格外审慎。()()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。结构化金融产品通常会内嵌一个或一个以上的衍生品，其挂钩基础资产具有不同风险特征，嵌入式衍生产品的种类、结构各异，导致结构化产品的收益与风险出现非常大差异，监管机构要求金融机构在销售时格外审慎。"},{"id":"n-law2-90","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"金融互换交易是指两个或两个以上当事人按共同商定的条件，在约定时间内定期交换资产的金融交易。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。金融互换是指两个或两个以上的当事人按共同商定的条件，在约定的时间内定期交换现金流(而非“资产”)的金融交易。"},{"id":"n-law2-91","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"金融债券一般不记名、不挂失，但可以抵押和转让。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。金融债券作为债券的一种特殊类型，它具有以下特点:(1)金融债券表示是债权债务关系；(2)金融债券一般不记名、不挂失，但可以抵押和转让；(3)我国金融债券发行对象主要为个人，利息收入可免征个人收入所得税和个人收入调节税；(4)金融债券的利息不计复利，不能提前支取，延期兑付亦不计逾期利息；(5)金融债券的利率固定，一般都高于同期储蓄利率:(6)我国发行过金融债券所筹集的资金一般都专款专用，如建设银行曾发行的投资债券，其主要用途就是为国家大中型建设项目筹措资金。"},{"id":"n-law2-92","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"企业市场化并购重组，促进产业整合，是解决产能过剩问题重要手段。()()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。，大力推进企业市场化并购重组，促进产业整合，是解决产能过剩问题的重要手段。微信※"},{"id":"n-law2-93","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"市场风险限额指标包括 VaR 限额、产品或组合敞口限额、敏感度限额、止损限额等。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。市场风险限额指标包括VaR限额、产品或组合敞口限额、敏感度限额、止损限额等。"},{"id":"n-law2-94","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"投资决策委员会负责决定私募基金的投资计划、投资策略、投资原则、投资目标、资产分配及投资组合总体计划。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。目前，我国大部分基金公司的基金投资管理都实行投资决策委员会领导下的基金经理负责制。投资决策委员会负责决定公司所管理基金的投资计划、投资策略、投资原则、投资目标、资产配置以及投资权限等，具体的投资细节则由各基金经理自行掌握。(注:这里的基金指公募基金，不是私募基金)"},{"id":"n-law2-95","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"我国普通国债发展趋势是发行方式趋于市场化，规模越来越大，期限趋于多样化。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。获取我国普通国做发展商趋势是发行方式趋于市场化，规模越来越大，期限趋于多样化。"},{"id":"n-law2-96","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"现代风险管理的基本理念包括:“任何金融产品都是风险和收益的组合，风险是与收益相匹配，投资是以风险换收益”","options":["正确","错误"],"answer":"A","explain":"本题表述正确。限额管理体现了现代风险管理是一种全面的风险管理，限额管理体现了任何金融产品是风险和收益的组合，投资是以风险换收益。"},{"id":"n-law2-97","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"运用利率政策和信货政策对证券市场进行干预属于行政手段。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。经济手段是通过运用利率政策、公开市场业务、信货政策、税收政策等经济手段，对证券市场进行干预，这种手段相对比较灵活，但调节过程可能较慢，存在时滯。"},{"id":"n-law2-98","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"在我国金融中介体系中，信托机构属于投资中介体系。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。目前，我国己经形成了多层次的金融中介机构体系，拥有以中央银行为主导、国有商业银行为主体，包括股份制商业银行、城市商业银行、农村商业银行、跨国银行、农村信用社在内时多层次银行机构体系；拥有以证券公司、期货公司和证券投资基金为主，以各类投资咨询中介、信托机构为辅的多元化投资中介体系，拥有人寿保险公司、财产保险公司、再保险公司以及提供多种多样保险服务保险中介体系。"},{"id":"n-law2-99","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"在信用风险分析中，违约依然是最为重要的信用事件，对信用风险的描述和量化仍然以违约为中心，主要包括违约概率违约损失率和违约时的风险暴露等。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。在信用风险分析中，违约依然是最为重要信用事件，对信用风险描述和量化仍然是以违约为中心，主要包括违约概率、违约损失率、违约时的风险暴露等。"},{"id":"n-law2-100","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"在中国境内申请发行人民币债券的国际开发机构应向证监会等窗口单位递交债券发行申请。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。在中国境内申请发行人民币债券的国际开发机构应向财政部等窗口单位递交债券发行申请，由窗口单位会同中国人民银行、国家发改委、中国证监会等部门审核后，报国务院同意。"},{"id":"n-law2-101","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"正常情况下，利率债的信用风险很小。","options":["正确","错误"],"answer":"A","explain":"本题表还正确。利率债，是指直接以政府信用为基础或是以政府提供偿债支持为基础而发行的债券。由于有政府信用背书，正常情况下利率债的信用风险很小。"},{"id":"n-law2-102","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券服务机构包括会计师事务所、律师事务所以及从事证券投资咨询、资产评估、资信评级、财务顾问、信息技术系统服务的证券服务机构。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。证券服务机构，是指依法设立的从事证券服务业务的法人机构，包括会计师事务所、律师事务所以及从事证券投资咨询、资产评估、资信评级、财务顾问、信息技术系统服务证券服务机构。"},{"id":"n-law2-103","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司、基金管理公司子公司通过设立特殊目的载体(SPV)开展资产证券化业务。","options":["正确","错误"],"answer":"A","explain":"本题表还正确。证券公司、基金管理公司子公司通过设立特殊目的载体开展资产证券化业务。"},{"id":"n-law2-104","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司风控人员可以兼任其风险管理品种相关前台业务工作()。()","options":["正确","错误"],"answer":"B","explain":"本题表还错误。证券公司风控人员不得兼任与风险管理职责相冲突的职务。"},{"id":"n-law2-105","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司向证券金融公司交存保证金，采取设立交收的方式。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。证券公司采取设立信托的方式向证券金融公司交存保证金。"},{"id":"n-law2-106","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"中小非金融企业集合票据由多家中小企业构成联合发行人作为债券发行主体集合发行，各发行企业作为独立负债主体，在各自的发行额度内承担按期还本付息义务，并按照相应比例承担发行费用。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。集合票据由多家中小企业构成的联合发行人作为债券发行主体集合发行，各发行企业作为独立负债主体，在各自的发行额度内承担按期还本付息的义务，并按照相应比例承担发行费用。集合发行能够解决单个企业独立发行规模小、流动性不足的问题。"},{"id":"n-law2-107","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】近日，中国证监会根据《证券法》的有关规定成立调查组，对某私募证券投资基金涉\n嫌操纵市场一案进行立案调查。调查组查询了当事人和与被调查案子有关的单位和个人的资\n金账户、证券账户、银行账户以及其他具有支付、托管、结算等账户信息。随着调查组对该\n私募证券投资基金涉嫌操纵市场一案调查的深入，发现该私募证券投资基金通过控制其发行\n的6个私募基金产品账户、2个资产管理计划账户、8个理财专户账户及借入并控制10个\n自然人账户操纵市场，手段隐蔽、资金量巨大，并存在转移违法资金、毁损财务会计资料和\n伪造开户资料等行为，案情重大、复杂。\n请根据上述背景信息回答以下问题。\n\n【问题】调查组在调查过程中，不得对有关文件和资料进行()。","options":["扣押","销毁","封存","复制"],"answer":"B","explain":"(1)查阅、复制当事人和与被调查事件有关的单位和个人的证券交易记录、登记过户记录、财务会计资料及其他相关文件和资料:对可能被转移、隐匿或者毁损的文件和资料，可以予以封存、扣押。(2)查询当事人和与被调查事件有关的单位和个人的资金账户、证券账户、银行账户以及其他具有支付、托管、结算等功能的账户信息，可以对有关文件和资料进行复制。"},{"id":"n-law2-108","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】近日，中国证监会根据《证券法》的有关规定成立调查组，对某私募证券投资基金涉\n嫌操纵市场一案进行立案调查。调查组查询了当事人和与被调查案子有关的单位和个人的资\n金账户、证券账户、银行账户以及其他具有支付、托管、结算等账户信息。随着调查组对该\n私募证券投资基金涉嫌操纵市场一案调查的深入，发现该私募证券投资基金通过控制其发行\n的6个私募基金产品账户、2个资产管理计划账户、8个理财专户账户及借入并控制10个\n自然人账户操纵市场，手段隐蔽、资金量巨大，并存在转移违法资金、毁损财务会计资料和\n伪造开户资料等行为，案情重大、复杂。\n请根据上述背景信息回答以下问题。\n\n【问题】对此案件，国务院证券监督管理机构可以依法采取的措施包括 ()。","options":["经国务院证券监督管理机构主要负责人或者其授权其他负责人批准，可以冻结或者查封有关账户、涉案财产","通知出入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境","经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以限制被调查事件当事人的证券买卖","经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，责令该私募证券投资基金清算其管理的产品、理财账户"],"answer":"ABC","explain":"国务院证券监督管理机构根据《证券法》依法履行职责，有权采取下列措施；(1)进入涉嫌违法行为发生场所调查取证。(2)对有证据证明已经或者可能转移或者隐匿违法资金、证券等涉案财产或者隐匿、伪造、毁损重要证据的，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以冻结或者查封，期限为6个月；因特殊原因需要延长的，每次延长期限不得超过3个月，冻结、查封期限最长不得超过2年。(3)在调查操纵证券市场、内慕交易等重大证券违法行为时，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以限制被调查事件当事人的证券买卖，但限制的期限不得超过3个月；案情复杂的，可以延长3个月。(4) 通知出境入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位主管人员和其他直接责任人员出境。"},{"id":"n-law2-109","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】2022年4月20日全国人大常委会审议通过了《期货和衍生品法》，自2022年8月1\n日起实施。《期货和衍生品法》补齐了我国期货和衍生品领域法律“短板”。\n请回答以下问题。\n\n【问题】下列关于《期货和衍生品法》立法特点说法，错误的是()。","options":["以境内为主，兼顾境外","以期货为主，兼顾其他衍生品","以场外为主，兼顾场内","以标准化为主，秉顾非标产品"],"answer":"C","explain":"《期货和衍生品法》在立法上特点主要体现在四个方面。(1)以期货为主，兼顾其他衍生品。衍生品家族主要有四大成员，分别是期货、期权、远期和互换。(2)以场内为主，兼顾场外。场内交易通常指所有前供求方集中在交易所进行竞价交易雨交易方式。(3)以境内为主，兼顾境外。期货和衍生品基于原生品即现货市场发展，在产业链供应链全球化的今天，期货和衍生品“走出去”是必然选择。(4) 以标准化产品为主，兼顾非标产品。《期货和衍生品法》明确了期货交易、衍生品交易的定义，对期货、期权、远期、互换等衍生产品给予了明确的法律界定。"},{"id":"n-law2-110","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】2022年4月20日全国人大常委会审议通过了《期货和衍生品法》，自2022年8月1\n日起实施。《期货和衍生品法》补齐了我国期货和衍生品领域法律“短板”。\n请回答以下问题。\n\n【问题】《期货和衍生品法》首次明确了交易报告库的法律地位及主要职责，我国己建成的交易报告库包括()。","options":["中国期货市场监控中心交易报告库","深圳交易所交易报告库","上海交易所交易报告库","中证报价场外业务交易报告库"],"answer":"AD","explain":"《期货和衍生品法》首次明确了交易报告库的法律地位及主要职责，规定 “应当建立衍生品交易报告库，对衍生品交易标的、规模、对手方等信息进行集中收集、保存、分析和管理，并按照规定及时向市场披露有关信息”。我国证券期货行业自 2014 年开始建设交易报告库。目前，共建成中证报价场外业务报告库、中国期货市场监控中心交易报告库两家交易报告库，并相继被金融稳定理事会认证为正式交易报告库(TR)，表明我国交易报告库建设已初步达到国际标准。由于是《期货和衍生品法》，约束期货及衍生品，而BC 选项是证券交易报告库，故可排除。"},{"id":"n-law2-111","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公募基金公司正处于筹建过程中，近期，公募基金公司设立筹建工作组，拟对公司\n基金资产估值、费用及其计提方式、利润分配相关控制措施与流程进行梳理，在考虑相关业\n务规则的基础上，制定相关业务管理制度，并逐步予以完善，从而确保基金依法合规有字运\n作。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于该公司基金资产估值要求说法，正确的是()。","options":["封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但仅需每周披露一次基金份额净值","基金采用的估值方法需要在法定募集文件中公开披露，若基金变更了估值方法，必须及时进行披露","开放式基金于每个交易日估值，并不晚于下一交易日公告份额净值","对于投资标的交易活跃的资产，可分离至侧袋账户进行处置清算，以确保投资者得到公平"],"answer":"ABC","explain":"基金资产估值需考虑因素:估值频率、交易价格的公允性、估值方法的一致性及公开性。1.基金资产估值时频率，基金一般都按照固定的时间间隔对基金资产进行估值，通常相关法规会规定一个最小的估值频率。我国的开放式基金于每个交易日估值，并不晚于下一交易日公告份额净值:封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但每周披露一次基金份额净值。2. 估值方法一致性是指基金在进行资产估值时均应采用同样的估值方法，遵守同样的估值规则。估值方法公开性是指基金采用的估值方法需要在法定募集文件中公开披露。若基金变更了估值方法，必须及时进行披露。3. 公允性。当基金投资标的为交易活跃证券时，对其资产进行估值较为容易。在这种情况下，市场交易价格是可获得并被接受，也是公允的，因此，也是可信的，直接采用市场交易价格就可以对标的资产估值。"},{"id":"n-law2-112","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公募基金公司正处于筹建过程中，近期，公募基金公司设立筹建工作组，拟对公司\n基金资产估值、费用及其计提方式、利润分配相关控制措施与流程进行梳理，在考虑相关业\n务规则的基础上，制定相关业务管理制度，并逐步予以完善，从而确保基金依法合规有字运\n作。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于该公司基金费用及计提方式的说法，正确有()。","options":["基金管理费、基金托管费及基金销售服务费均是按照前一日基金资产净值的一定比例逐日计提，按年支付","申购费(认购费)、赎回费及基金转换费由基金投资者承担，不参与基金会计核算","基金管理费、托管费、持有人大会费、信息披露费由基金资产承担，直接从基金资产中列","与侧袋账户有关的费用需从侧袋账户中列支，但应待特定资产变现后方可列支，并收取管理费及业绩报酬"],"answer":"BC","explain":"(1)基金管理费是指基金管理人管理基金资产而向基金收取的费用。我国基金管理费、基金托管费及基金销售服务费均是按照前一日基金资产净值的一定比例逐日计提，按月支付。(2)在基金运作过程中涉及的费用可以分为两大类；①一类是基金销售过程中发生由基金投资者承担费用，主要包括申购费(认购费)、赎回费及基金转换费等；②另一类是基金管理过程中发生的费用，主要包括基金管理费、基金托管费、持有人大会费用、信息披露费等，这些费用由基金资产承担。上述两大类费用的性质是不同的。第一类费用并不参与基金的会计核算，而第二类费用则需要直接从基金资产中列支，其种类及计提标准需在基金合同及基金招募说明书中明确规定。(3)“并收取管理费及业绩报酬”表述错误，应该是“并不收取管理费及业绩报酬”。"},{"id":"n-law2-113","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公募基金公司正处于筹建过程中，近期，公募基金公司设立筹建工作组，拟对公司\n基金资产估值、费用及其计提方式、利润分配相关控制措施与流程进行梳理，在考虑相关业\n务规则的基础上，制定相关业务管理制度，并逐步予以完善，从而确保基金依法合规有字运\n作。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于该公司基金利润分配的说法，正确的有()。","options":["开放式基金要求基金利润分配后基金份额净值不得低于面值","基金利润主要来自基金收入减去基金费用后的净额、公允价值变动损益","封闭式基金的收益分配每年不得少于一次，可采取现金分红和红利再投资两种方式","当日赎回的货币市场基金份额自赎回当日起不享有基金的分配权益"],"answer":"AB","explain":"(1) 根据有关规定，封闭式基金的收益分配每年不得少于一次，封闭式基金年度收益分配比例不得低于基金年度可供分配利润的 90%。基金分配后，基金份额净值不得低于面值。封闭式基金只能采用现金方式分红。(2)根据有关规定，一般开放式基金利润分配默认方式应当采用现金分红。开放式基金的基金份额持有人可以事先选择分红再投资。基金份额持有人事先未作出选择的，基金管理人应当支付现金。(3) 对于每日按照面值进行报价的货币市场基金，可以在基金合同中将收益分配的方式约定为红利再投资，并应当每日进行收益分配。(4)基金利润是指基金在一定会计期间的经营成果。基金利润主要来自基金收入减去基金费用后的净额、公允价值变动损益等。基金收入主要包括利息收入、投资收益以及其他收入。(5) 货币市场基金在每日进行利润分配时，当日申购的基金份额自下一工作日起享有基金的分配权益，当日赎回的基金份额自下一工作日起不享有基金的分配权益。"},{"id":"n-law2-114","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】根据《国务院关于开展优先股试点的指导意见》，2019年初，某上市公司非公开发行\n首期优先股3亿股，募集资金12亿元，期限 3+N年，股息率为4.80%。2020年，该上市公\n司召开股东大会，对非公开发行第二期优先股2亿股的议案进行表决。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于优先股的说法，正确的有()。","options":["优先股的股息，须在派发普通股股息之前派发","优先股股东对公司经营影响力要大于普通股股东","优先股既像债券，又像股票","在破产清算时，优先股股东对公司剩余财产权利先于普通股，但在债权人之后"],"answer":"ACD","explain":"优先股既像债券，又像股票，其“优先”主要体现在:一是通常具有固定股息(类似债券)，并须在派发普通股股息之前派发；二是在破产清算时，优先股股东对公司剩余财产权利先于普通股股东，但在债权人之后"},{"id":"n-law2-115","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】根据《国务院关于开展优先股试点的指导意见》，2019年初，某上市公司非公开发行\n首期优先股3亿股，募集资金12亿元，期限 3+N年，股息率为4.80%。2020年，该上市公\n司召开股东大会，对非公开发行第二期优先股2亿股的议案进行表决。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于第二期优先股议案表决的说法，正确的是()。","options":["首期优先股股东出席享有表决权，且与参加会议普通股股东一起表决","该议案须经出席会议的普通股股东所持表决权的三分之二以上通过之外，还须经出席会议的首期优先股股东所持表决权三分之二以上通过","该议案只需经出席会议的首期优先股股东所持表决权三分之二以上通过","首期优先股股东不出席股东大会会议，所持股份没有表决权"],"answer":"B","explain":"(1) 优先股股东其他一些股东权利是受限的。一般对公司日常经营管理事务没有表决权，对公司经营的影响力要小于普通股股东。(2)优先股股东在以下两种情况下具有表决权:1. 固有的表决权，是公司对与优先股股东利益切身相关重大事项进行表决时，优先股股东享有表决权，而且与普通股分类表决，以下五种事项除须经出席会议普通股股东所持表决权三分之二以上通过之外，还须经出席会议的优先股股东所持表决权的三分之二以上通过；修改公司章程中与优先股相关的内容:一次或累计减少公司注册资本超过百分之十；公司合并、分立、解散或变更公司形式:发行优先股；公司章程规定的其他情形。2. 恢复的表决权，是由于公司长期未按约定分配股息，优先股股东恢复到与普通股股东同样的表决权，可以参与公司经营决策，与普通股一同参加投票。公司累计3个会计年度或连续2个会计年度未按约定支付优先股股息，优先股股东可以享有公司章程规定的表决权。但当公司全额支付所欠优先股股息时，将不再享有这类表决权。"},{"id":"n-law2-116","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】根据《国务院关于开展优先股试点的指导意见》，2019年初，某上市公司非公开发行\n首期优先股3亿股，募集资金12亿元，期限 3+N年，股息率为4.80%。2020年，该上市公\n司召开股东大会，对非公开发行第二期优先股2亿股的议案进行表决。\n请根据上述背景信息回答以下问题。\n\n【问题】因经营亏损，该上市公司 2020年、2021 年连续两个会计年度未能按照约定支付优先股股息，优先股股东可以享有公司章程规定的表决权，下列关于该类表决权说法，正确的有()。","options":["在公司全额支付所欠优先股股息时，优先股股东将不再享有该类表决权","被称为优先股“恢复的表决权”","该类表决权一经享有一直存在","特有该类表决权前优先股股东心奇以参与公司经营决策，与普逼股具有同样的表决权，一同参加投票"],"answer":"ABD","explain":"(1) 优先股股东其他一些股东权利是受限的。一般对公司日常经营管理事务没有表决权，对公司经营的影响力要小于普通股股东。(2) 优先股股东在以下两种情况下具有表决权；1. 固有的表决权，是公司对与优先股股东利益切身相关的重大事项进行表决时，优先股股东享有表决权，而且与普通股分类表决，以下五种事项除须经出席会议的普通股股东所持表决权的三分之二以上通过之外，还须经出席会议的优先股股东所持表决权的三分之二以上通过；修改公司章程中与优先股相关的内容:一次或累计减少公司注册资本超过百分之十:公司合并、分立、解散或变更公司形式:发行优先股:公司章程规定的其他情形。2.恢复的表决权，是由于公司长期未按约定分配股息，优先股股东恢复到与普通股股东同样的表决权，可以参与公司经营决策，与普通股一同参加投票。公司累计3个会计年度或连续2个会计年度未按约定支付优先股股息，优先股股东可以享有公司章程规定的表决权。但当公司全额支付所欠优先股股息时，将不再享有这类表决权。"}]},{"id":"n-law3","subject":"law","name":"11月300题 · 法规卷三","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"n-law3-0","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于股票合并的说法，错误的是是()。","options":["股票合并是将若干股票合并为1股","股票合并常见于低价股","股票合并又称并股","股票合并会影响每位股东所持股东权益占公司全部股东权益比重"],"answer":"D","explain":""},{"id":"n-law3-1","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"沪股通通过()设立的证券交易服务公司进行交易。","options":["上海证券交易所或香港联合交易所","香港联合交易所","上海证券交易所","上海证券交易所和香港联合交易所"],"answer":"B","explain":"沪股通，是指投资者委托香港经纪商，经由香港联合交易所在上海设立的证券交易服务公司，向上海证券交易所进行申报(买卖盘传递)，买卖沪港通规定范围内的上海证券交易所上市的股票故本题选择 “香港联合交易所”。"},{"id":"n-law3-2","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券公司为客户提供证券代理买卖业务收取的费用是()。","options":["佣金","投顾费","过户费","印花税"],"answer":"A","explain":"客户在委托买卖证券时，需支付多项费用和税收，如用金、过户费、印花税等。(1) 佣金是客户在委托买卖证券成交后按成交金额一定比例支付费用，是证券经纪商为客户提供证券代理买卖服务收取费用，故本题选择“佣金”。(2) 过户费是委托买卖股票、基金成交后，买卖双方为变更证券登记所支付费用。(3)印花税是根据国家税法规定，在A股和B股成交后对买卖双方客户按照规定的税率分别征收税金。"},{"id":"n-law3-3","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券账户管理规则》相关规定，()对证券账户实施统一管理。","options":["中国人民银行","中国证券登记结算有限责任公司","中国证监会","证券公司"],"answer":"B","explain":"中国证券登记结算有限责任公司为同一投资者维护一套证券账户信息。"},{"id":"n-law3-4","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于普通股股东享有的优先认股权昀说法，错误是()。","options":["优先认股权是指当股份公司为增加公司资本而决定增加发行新的股票时，原普通股股东享有的按其持股比例，以低于市价的某一特定价格优先认购一定数量新发行股票权利","享有优先认股权的股东，仅有两种选择:行使此权利来认购新发行普通股或放弃此权利","赋予股东优先认股权，能保护原普通股股东的利益和持股价值","赋予股东优先认股权，能保证普通股股东在股份公司中保持原有的持股比例"],"answer":"B","explain":""},{"id":"n-law3-5","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于股份公司支付红利的说法，错误的是()。","options":["股份公司在缴纳所得税后，其利润可按照普通股股东持有股份比例分配红利","股份公司只能用留存收益支付红利","红利支付不能减少其注册资本","公司在无力偿债时不能支付红利"],"answer":"A","explain":"资产收益权和剩余资产分配权直接体现了普通股股东对股份公司的剩余索取权，也直接体现了其在经济利益上的要求。资产收益权是股东按照其持有的股份比例分取股利的权利。普通股票股东行使资产收益权有一定的限制条件。(1)法律上的限制。一般原则是:股份公司只能用留存收益支付红利；红利的支付不能减少其注册资本:公司在无力偿债时不能支付红利。我国有关法律规定，公司缴纳所得税后的利润，在支付普通股票的红利之前，应按如下顺序分配:弥补亏损，提取法定公积金，提取任意公积金。可见，普通股票股东能否分到红利以及分得多少，取决于公司税后利润多少以及公司未来发展的需要。(2)其他方面的限制。如公司对现金的需要，股东所处地位，公司的经营环境，公司进入资本市场获得资金的能力等。"},{"id":"n-law3-6","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于网下发行的说法，错误的是()。","options":["公开发行股票数量在4亿股(含)以下的，有效报价投资者的数量不少于 10家","首次公开发行股票，网下投资者须具备丰富的投资经验和良好的定价能力，应当接受中国证券业协会的自律管理，遵守中国证券业协会自律规则","首次公开发行股票采用询价方式的，公开发行后总股本在4亿股(含)以下的，网下初始发行比例不低于本次公开发行股票数量60%","公开发行股票数量在4亿股以上的，有效报价投资者数量不少于 15家"],"answer":"D","explain":"(1) 首次公开发行股票，网下投资者须具备丰富前投资经验和良好定价能力，应当接受中国证券业协会自律管理，遵守中国证券业协会自律规则。(2)公开发行股票数量在4亿股《含)以下，有效报价投资者的数量不少于10家；公开发行股票数量在4亿股以上的，有效报价投资者的数量不少于 20家，故本题选择“数量不少于15家”，应该是“20家”。(3) 首次公开发行股票采用询价方式，公开发行后总股本在4亿股(含)以下的，网下初始发行比例不低于本次公开发行股票数量的 60%:公开发行后总股本超过4亿股的，网下初始发行比例不低于本次公开发行股票数量的70%。"},{"id":"n-law3-7","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于首次公开发行股票并在主板上市规定说法，错误是()。","options":["发行人最近三年内主营业务和董事、高级管理人员没有发生重大变化，实际控制人没有发生变更","发行人依法设立且持续经营时间在三年以上股份公司，但经国务院批准的除外；有限责任公司按原账面净资产值折股整体变更为股份有限公司的，持续经营时间可以从有限责任公司成立之日起计算","最近三个会计年度经营活动产生的现金流量净额累计超过人民币5000万元或者最近三个会计年度营业收入累计超过人民币3亿元","最近三个会计年度净利润均为正数且累计超过人民币5000 万元，净利润以扣除非经常性损益前后较低者为计算依据"],"answer":"D","explain":"首次公开发行股票并在主板上市的规定首次公开发行股票并上市应满足以下条件:(1) 发行人依法设立且持续经营时间在三年以上的股份有限公司，但经国务院批准的除外。有限责任公司按原账面净资产值折股整体变更为股份有限公司的，持续经营时间可以从有限责任公司成立之日起计算。(2) 发行人最近三年内主营业务和董事、高级管理人员没有发生重大变化，实际控制人没有发生变更。(3) 最近三个会计年度净利润均为正数县累计超过人民币 3000万元，净利润以扣除非经常性损益前后较低者为计算依据，故“净利润均为正数且累计超过人民币5000万元”表述错误，应该是“3000”。(4) 最近三个会计年度经营活动产生现金流量净额累计超过人民币5000万元或者最近三个会计年度营业收入累计超过人民币3亿元。"},{"id":"n-law3-8","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于委托受理的说法，错误是()。","options":["证券经纪商对客户审查可以维护交易的合法性，提高成交的准确率，避免造成不必要","在不采用信用交易的情况下，客户必须用自己账户上的资金买入证券，或者卖出自己账户上实际存在证券","证券经纪商要根据证券交易所的交易规则，对客户的证件和委托单在合法性和同一性方面进行审查","时间优先是指当证券公司自营买卖申报与客户委托买卖申报在时间上相冲突时，应让客户委托买卖优先申报"],"answer":"D","explain":"(1) 委托受理的手续和过程包括委托受理、委托执行和委托撤销。在委托受理，证券经纪商在收到客户委托后，应对委托人身份、委托内容、委托卖出的实际证券数量及委托买入实际资金余额进行审查。经审查符合要求后，才能接受委托。(2) 证券经纪商要根据证券交易所的交易规则，对客户的证件和委托单在合法性和同一性方面进行审查。这些审查是为了维护交易的合法性，提高成交的准确率，避免造成不必要纠纷。(3)查验资金及证券。在不采用信用交易情况下，客户必须用自己账户上的资金买入证券，或者卖出自己账户上实际存在的证券券。(4)时间优先是指证券经纪商应按受托时间先后次序为委托人申报，故“时间优先”表述错误，应该是“客户优先”。【客户优先是指当证券公司自营买卖申报与客户委托买卖申报在时间上相冲突时，应让客户委托买卖优先申报。】"},{"id":"n-law3-9","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券公司提供基于互联网或移动通讯网络的网上证券交易系统，向客户提供用于下达证券交易指令、获取成交结果服务方式是()。","options":["自助终端委托","传真委托","人工电话委托","网上委托"],"answer":"D","explain":"本题考查的是证券委托的形式。证券委托可以分为柜台委托和非柜台委托。柜台委托是指委托人亲自或由其代理人到证券营业部交易柜台，根据委托程序和必需的证件采用书面方式表达委托意向，由本人填写委托单并签章的形式。非柜台委托主要有人工电话委托或传真委托、自助和电话自动委托、网上委托等形式。网上委托是指证券营业商通过互联网，向委托人提供用于下达证券交易指令、获取成交结果一种服务方式。"},{"id":"n-law3-10","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于国家股、法人股、社会公众股和外资股的说法，错误是()。","options":["法人股指企业法人或具有法人资格事业单位和社会团体所持有股份","社会公众股指社会公众依法以其拥有财产投入公司时形成可上市流通股份","外资股指股份公司向外国和我国香港、澳门、台湾地区投资者发行的股票，含红筹股","国家股是国有股权一个组成部分，股利收入依法纳入国有资产经营预算"],"answer":"C","explain":"在我国，按投资主体的性质不同，将股票分为:(1)国家股:(2)法人股；(3)社会公众股；(4)外资股。(1)国家股是国有股权的一个组成部分，股利收入依法纳入国有资产经营预算。(2) 法人股指企业法人或具有法人资格事业单位和社会团体所持有股份。(3)社会公众股指社会公众依法以其拥有财产投入公司时形成的可上市流通的股份。(4)外资股是指股份公司向外国和我国香港、澳门、台湾地区投资者发行股票。这是我国股份公司吸收外资的一种方式。外资股按上市地域，可以分为境内上市外资股(即B股，股份有限公司向境外投资者募集资金并在我国境内上市的股份)和境外上市外资股。红筹股不属于外资股，指在中国境外注册、在香港上市，但主要业务在中国内地或大部分股东权益来自中国内地公司的股票。"},{"id":"n-law3-11","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"人民币普通股票账户又称为()，目前在我国此账户不可用于买卖()。","options":["B股账户:债券","A股账户；B股","基金账户:人民币普通股票","人民币特种股票账户；证券投资基金"],"answer":"B","explain":"(1)人民币普通股票账户简称“A股账户”，A股账户是我国目前用途最广、数量最多所一种通用型证券账户，既可用于买卖人民币普通股票，也可用于买卖债券和证券投资基金。(2)B股的正式名称是人民币特种股票。它是以人民币标明面值，以外币认购和买卖，在中国境内证券交易所上市交易前外资股。B股公司的注册地和上市地都在境内，我国此账户不可用于买卖。故本题选择“A股账户；B股”。"},{"id":"n-law3-12","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"当股票市场投机过度或出现严重违法行为时，()会采取一定的措施以平抑股价的波动。","options":["财政部","证券监督管理机构","中国人民银行","证券业协会"],"answer":"B","explain":"当健票和场技机这慢碳告頭严业出洗行为时、证旁监合管里材村也会天软一定前据道以平拍"},{"id":"n-law3-13","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"对股份公司而言，发行优先股票可以避免经营决策权改变和分散是因为()。","options":["优先股股东剩余资产分配优先","优先股股东表决权受限","优先股股东股息分派优先","优先股的股息率固定"],"answer":"B","explain":"一般来讲，优先股股东对公司日常经营管理事务没有表决权，仅在与之利益密切相关的特定事项上享有表决权，优先股股东对公司经营的影响力要小于普通股股东。"},{"id":"n-law3-14","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"在()情况下，优先股票的股息收益可能会大大低于普通股票。","options":["公司破产清算","公司经营有方、盈利丰厚","公司经营不善、效率低下","公司进入成熟期"],"answer":"B","explain":"优先股是一种特殊股票。"},{"id":"n-law3-15","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"优先股是一种特殊股票，它对发行人来讲具有一定的意义。下列有关说法错误的是()。","options":["发行优先股作用在于可以筹集长期稳定的公司资本","发行优先股可以优化发行人财务结构，增大其财务杠杆系数","优先股股东一般不参与公司经营决策，表决权受到限制，这样可以避免公司经营决策权改变和分散","优先股股息率固定，发行优先股可以减轻发行人利润分配的负担"],"answer":"B","explain":"(1)优先股是一种特殊股票，对发行人的意义:①可以筹集长期稳定的公司股本；②因其股息率固定，可以减轻利润分配的负担；③优先股股东一般不参与公司经营决策，表决权受到限制，可以避免公司经营决策权改变和分散。故本题选择“优化发行人财务结构，增大其财务杠杆系数”。(2) 对投资者意义:①由于优先股优先于普通股分配公司利润和剩余财产，因而投资风险相对较小，不失为一种较安全的投资对象。②优先股因收入稳定，二级市场价格波动小，风险较低，适宜中长线投资，在国外，大部分优先股为保险公司、养老基金等稳健型机构投资者所持有。"},{"id":"n-law3-16","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"融资融券中，担保物()。","options":["既可以是股票，也可以是现金","可以是不动产或股票","可以是现金或不动产","只能是股票"],"answer":"A","explain":"融资交易是指投资者向证券公司缴纳一定的保证金，融(借)入一定数量资金买入股票交易行为。融券交易是指投资者向证券公司缴纳一定的保证金，融入一定数量的证券并卖出的交易行为。投资者向证券公司提交的保证金可以是现金或者可充抵保证金的证券。"},{"id":"n-law3-17","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"关于深圳证券交易所市场旳证券转托管程厚，下列说法错误是()。","options":["转出证券营业部按照深交所有关规定，在非交易时间内可以申报转托管","转托管可以撤单","在同一证券公司的不同席位之间，当日买入证券可以转托管","在不同证券公司的席位之间，当日买入证券不可以转托管"],"answer":"A","explain":"转出证券营业部按照深交所有关规定，在交易时间内可以申报转托管，而不是非交易时间。深圳证券交易所交易证券的托管制度可概括为:自动托管，随处通买，哪买哪卖，转托不限。深圳证券市场投资者的证券托管是自动实现的，投资者在哪家证券营业部买入证券，这些证券就自动托管在哪家证券营业部。投资者可以以同一证券账户在单个或多个会员不同证券营业部买入证券。投资者买入的证券可以通过原买入证券的交易单元委托卖出，也可以向原买入证券的交易单元发出转托管指令，转托管完成后，在转入的交易单元委托卖出。"},{"id":"n-law3-18","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于地方政府专项债券的说法错误的是()。","options":["各地 7年和 10 年期地方政府专项债券合计发行规模不得超过专项债券全年发行规模的 30%","各地可以在专项债券承销商中择优选择主承销商，主承销商为专项债券提供发行定价、登记托管、上市交易等咨询服务","专项债券由各地按照市场化原则自发自还，遵循公开、公平、公正原则，发行和偿还主体为地方政府","专项债券应当在中央国债登记结算有限责任公司办理总登记托管，在国家规定的证券登记结算机构办理分登记托管"],"answer":"A","explain":"(1) 专项债券期限为1年、2年、3年、5年、7年和10年，由各地综合考虑项目建设、运营、回收周期和债券市场状况等合理确定。但7年和 10年期债券的合计发行规模不得超过专项债券全年发行规模旳50%。(2) 专项债券由各地按照市场化原则自发自还，遵循公开、公平、公正的原则，发行和偿还主体为地方政府。(3)各地可以在专项债券承销商中择优选择主承销商，主承销商为专项债券提供发行定价、登记托管、上市交易等咨询服务。(4) 专项债券应当在中央国债登记结算有限责任公司办理总登记托管，在国家规定的证券登记结算机构办理分登记托管。"},{"id":"n-law3-19","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"不动产抵押公司债券属于 ()。","options":["信用债券","担保债券","质押债券","抵押债券"],"answer":"D","explain":"不动产抵押公司债券是以公司的不动产(如房屋、土地等)作抵押而发行的债券，是抵押证券的一种。公司以这种财产的房契或地契作抵押，如果发生了公司不能偿还债务的情况，抵押的财产将被出售，所得款项用来偿还债务。另外，用作抵押的财产价值不一定与发生债务额相等，当某抵押品价值很大时，可以分为若干次抵押，这样就有第一抵押债券、第二抵押债券等之分。在处理抵押品偿债时，要按顺序依次偿还优先一级的抵押债券。"},{"id":"n-law3-20","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"分离交易的可转换公司债券是指债券与()可以分离交易。","options":["可回售权","认购权","认股权","可赎回权"],"answer":"C","explain":"分离交易可转换公司债券是认股权证和公司债券组合产品，该种产品中的公司债券和认股权证可在上市后分别交易，即发行时是组合在一起的，上市后自动拆分成公司债券和认股权证。"},{"id":"n-law3-21","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"国际开发机构在中国境内申请发行人民币债券，应由()负责对人民币债券发行和偿还有关的人民币账户和人民币跨境支付进行管理。","options":["国家发改委","财政部","国家外汇管理局","中国人民银行"],"answer":"D","explain":"(1)国际开发机构人民币债券是指国际开发机构依法在中国境内发行的、约定在一定期限内还本付息的、以人民币计价的债券。(2) 在中国境内申请发行人民币债券的国际开发机构应向财政部等窗口单位递交债券发行申请，由窗口单位会同央行、发改委、证监会等部门审核后，报国务院同意。(3) 发改委会同财政部，对人民币债券的发行规模及所筹资金用途进行审核。央行对发行利率进行管理。(4) 中国人民银行负责对与人民币债券发行和偿还有关的人民币账户和人民币跨境支付进行管理。故本题选择 “银行”。"},{"id":"n-law3-22","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"外国债券的发行一般由()前金融机构、证券公司承销。","options":["发行地所在国","投资者所在国","发行者所在国","国际性"],"answer":"A","explain":"外国货券是指某一国家借款人在本国以外某一国家发行以该国货币为面值的债券。它的特点是债券发行人属于一个国家，债券的面值货币和发行市场属于另一个国家。外国债券是一种传统的国际债券。外国债券一般由发行地所在国的证券公司、金融机构承销，而欧洲债券由一家或几家大银行牵头，组织术几家或几十家国际性银行在一个国家或几个国家同时承销。"},{"id":"n-law3-23","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"与国内债券相比，国际债券不具有的特殊特点是()。","options":["存在汇率风险","发行规模大","存在信用风险","资金来源广"],"answer":"C","explain":"国际债券是一种跨国发行的债券，涉及两个或两个以上的国家。同国内债券相比，具有一定的特殊性:(1)资金来源广、发行规模大。(2)存在汇率风险。发行国内债券，筹集和还本付息的资金都是本国货币，所以不存在汇率风险。发行国际债券，筹集到资金是外国货币，汇率一旦发生波动，发行人和投资者都有可能蒙受意外损失或获取意外收益，所以，汇率风险是国际债券重要风险。(3)有国家主权保障。(4)以自由兑换货币作为计量货币。国际债券在国际市场上发行，因此，其计价货币往往是国际通用货币，一般以美元、英镑、吹元、日元和瑞士法郎为主。"},{"id":"n-law3-24","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于商业银行混合资本债券发行的说法，正确的是()。","options":["只能定向发行","只能公开发行","必须进行增信","必须进行信用评级"],"answer":"D","explain":"3获取混合资本债券可以公开发行，也可以定向发行。但无论是公开发行还是定向发行，均应进行信用评级，故本题选择“必须进行信用评级”。"},{"id":"n-law3-25","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"与其他非金融机构债券相比，金融债券的资信通常()。","options":["基本等同","更高","不好比较","更低"],"answer":"B","explain":"金融债券是指银行及非银行金融机构依照法定程序发行并约定在一定期限内还本付息有价证券。在我国，金融债券是指“依法在中华人民共和国境内设立金融机构法人在全国银行间债券市场发行前、按约定还本付息有价证券”。其中，该办法所指的金融机构法人包括政策性银行、商业银行、企业集团财务公司及其他金融机构。金融债券能够较有效地解决银行等金融机构的资金来源不足和期限不匹配矛盾。由于银行等金融机构在一国经济中占有较特殊的地位，政府对它们的运营又有严格的监管，因此，金融债券的资信通常高于其他非金融机构债券，违约风险相对较小，具有较高的安全性。所以，金融债券的利率通常低于一般的企业债券，但高于风险更小的国债和银行储蓄存款利率。"},{"id":"n-law3-26","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"可转换公司债券在发行结束()个月后，方可转换为公司股票。","options":["1","3","6","12"],"answer":"C","explain":"可转换债券的要素:1.有效期限和转换期限；2.票面利率或股息率；3.转换比例或转换价格；"},{"id":"n-law3-27","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"企业债券发行主体不包括()","options":["股份有限公司","上市公司","仍尚未改制为现代公司制度企业法人","有限责任公司"],"answer":"B","explain":"(1) 企业债券是指企业依照法定程序发行、约定在一定期限内还本付息的有价证券。(2)企业债券发行主体可以是股份有限公司和有限责任公司，也可以是尚未改制为公司制的企业法人，但不包括上市公司。"},{"id":"n-law3-28","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"由财政部面向全社会各类投资者、通过无纸化方式发行的、以电子记账方式记录债权并可以上市和流通转让的债券是()。","options":["储蓄国债","凭证式国债","特别国债","记账式国债"],"answer":"D","explain":"记账式国债是从 1994年开始发行的一个上市券种。它是由财政部面向全社会各类投资者、通过无纸化方式发行、以电子记账方式记录债权并可以上市和流通转让的债券。特点是:可以记名、挂失:以无券形式发行，可以防止证券的遗失、被窃与伪造，安全性好；可上市转让，流通性好；期限有长有短，但更适合短期国债的发行；通过证券交易所电脑网络发行，可以降低证券发行成本；上市后价格随行就市，具有一定的风险。信XS"},{"id":"n-law3-29","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"以下关于保险公司次级债务的说法，正确前是()。","options":["利息清偿顺序先于股权资本","本金清偿顺序列于保单之前","期限在10年以上(含10年)製染5","利息清偿顺序列于保单之前"],"answer":"A","explain":"2013年3月15日，原中国保监会修订了《保险公司次级定期债务管理暂行办法》。根据该办法，保险公司次级债是指 “保险公司为了弥补临时性或者阶段性资本不足，经批准募集、期限在5年以上(含5年)，且本金和利息的清偿顺序列于保单责任和其他负债之后，先于保险公司股权资本保险公司债务”。"},{"id":"n-law3-30","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"双方约定在未来某一时刻按照现在确定的价格买卖标的证券的行为称为()。","options":["远期交易","现券交易","回购交易","即期交易"],"answer":"A","explain":"债券交易分为:现券交易、回购交易、远期交易和期货交易。(1) 现券交易，也被称为债券的即期交易，是指证券买卖双方在成交后就办理交收手续，买入者付出资金并得到证券，卖出者交付证券并得到资金，也就是所谓二级市场的债券交易。(2) 回购交易，是指债券买卖双方(资金融入方和资金融出方)在成交的同时，约定于未来某一时间以某一约定价格双方再进行反向交易行为。(3)远期交易是双方约定在未来某一时刻(或时间段内)按照现在确定的价格买卖标债券行为。(4)期货交易是在交易所进行标准化的远期交易，即交易双方在集中性的市场以公开竞价方式所进行的期货合约交易。"},{"id":"n-law3-31","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"银行间债券市场的参与主体不包括()","options":["交易所","农村信用联社","商业银行","让券公司"],"answer":"A","explain":"银行间债券市场，是指依托于中国外汇交易中心暨全国银行间同业拆借中心和中央国债登记结算有限责任公司，包括商业银行、农村信用联社、保险公司、证券公司等金融机构以及一些非金融机构合格投资人通过北京金融资产交易所进行债券买卖和回购市场。"},{"id":"n-law3-32","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于债券报价与结算的说法，错误的是()。","options":["全价=净价+应计利息","债券的结算为净价结算","净价指的是不含应计利息的债券价格，单位为“元/百元面值”","债券的买卖报价分为净价和全价两种"],"answer":"B","explain":""},{"id":"n-law3-33","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列不属于债券利息主要支付方式的是()。","options":["先本后息","折扣利息","息票方式","本息合一"],"answer":"A","explain":"债券兑付是偿还本金，债券付息是支付利息。一般情况下，债券有五种兑付方式:到期兑付、提前兑付、债券替换、分期兑付和转换为普通股兑付。债券利息支付方式主要有三种:息票方式(剪息票方式)、折扣利息、本息合一方式。"},{"id":"n-law3-34","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"当通货膨胀率升高时，债券的实际收益率()。","options":["上升","不变","不确定","下降"],"answer":"D","explain":"预期通货膨胀率上升，相当于降低了债券的实际利率，引起债券相对预期回报率的下降。"},{"id":"n-law3-35","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"债券的发行条款规定了债券现金流，下列不影响债券现金流的条款是()。","options":["报价方式","债券币种","嵌入式期权条款","计付息间隔"],"answer":"A","explain":"(1)债券估值基本原理就是现金流贴现。债券投资者持有债券，会获得利息和本金偿付。把现金流入用适当的贴现率进行贴现并求和，便可得到债券的理论价格。(2)影响债券现金流确定的因素有:①债券的面值和票面利率。②计付息间隔。③债券嵌入式期权条款。④债券税收待遇。⑤其他因素。债券利率类型(浮动利率、固定利率)，债券的币种(单一货币、双币债券)等因素都会影响债券的现金流。(3)影响债券贴现率确定因素:债券必要回报率=真实无风险收益率+预期通货膨胀率+风险溢价。风险溢价根据各种债券的风险大小而定，是投资者因承担投资风险而获得的补偿。债券投资的主要风险因素包括违约风险(信用风险)、流动性风险、汇率风险等。"},{"id":"n-law3-36","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"政府发行证券昀品种一般仅限于()。","options":["债券","优先股","金融债券","股票"],"answer":"A","explain":""},{"id":"n-law3-37","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于债券交易说法，错误是()。","options":["债券交易的竞价原则包括价格优先、时间优先、客户委托优先","时间优先是要求在相同的价格申报时，应该与最早提出该价格的一方成交","客户委托优先主要是证券公司在自营买卖和代理买卖之间，首先进行自营买卖","价格优先是证券公司按照交易最有利于投资委托人利益的价格买进或卖出债券"],"answer":"C","explain":"在证券交易所内，债券成交就是要使买卖双方在价格和数量上达成一致。这一程序必须遵循竞价原则。这种竞价原则的主要内容是“三先”，即价格优先、时间优先、客户委托优先。(1)价格优先就是证券公司按照交易最有利于投资委托人利益的价格买进或卖出债券:(2)时间优先就是要求在相同的价格申报时，产该与最早提出该价格的一方成交；(3)客户委托优先主要是要求证券公司在自营买卖和代理买卖之间，首先进行代理买卖。故本题选择“首先进行自营买卖”，应该是“首先进行代理买卖”。"},{"id":"n-law3-38","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于银行间债券市场的描述，错误是()。","options":["偿还期在1年以内(含1年)债券为短期债券","偿还期在1年以上(不含1年)债券为中期债券","银行间债券市场中长期债券信用评级等级划分为三等九级，每个信用等级可用“+”、“-”号进行微调表示略高或略低于本等级","银行间债券市场短期债券信用评级等级划分为四等六级，每个信用等级均不进行微调"],"answer":"B","explain":"(1) 我国短期企业债券的偿还期限在1年以内，偿还期限在1年以上5年以下为中期企业债券，偿还期限在5年以上为长期企业债券。(2)银行间债券市场中长期债券信用评级划分为三等九级，符号表示为:AAA、AA、A、BBB、BB、B、cCC、CC、C等级。中长期债券信用评级前每一个信用等级可用“+”、“_”符号进行微调，表示略高或略低于本等级。(3) 短期债券信用等级划分为四等六级。符号表示为:A-1、A-2、A-3、B、C、D，每一个信用等级均不进行微调。"},{"id":"n-law3-39","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于债券市场转托管说法，错误是()。","options":["企业债可以跨市场转托管","转托管是指同一投资人开立的两个托管账户之间的托管债券的转移","公司债可以跨市场转托管","转托管是其持有的债券从一个托管账户转到属于该投资者另一个托管账户进行托管"],"answer":"C","explain":"(1) 转托管，是指同一投资人开立两个托管账户之间的托管债券的转移，即其持有的债券从一个托管账户转移到属于该投资者的另一个托管账户进行托管。(2)跨市场交易的债券。目前，除了国债(包括附息国债和地方债)和企业债可以跨市场转托管，其他债券品种(包括公司债、证券公司次级债、中小企业私募债)都不能跨市场转托管。(3)转托管时间。由于托管机构之间存在看不同的运作模式，转托管时完成全少需要一天。"},{"id":"n-law3-40","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"影响投资者对社会经济发展前景的预期因素包括()。","options":["重要法规颁布","社会经济发展规划的制订","重大经济政策的出台","企业的年度预算方案昀调整"],"answer":"ABC","explain":"政治因素对股票价格的影响很大，往往很难预料，主要有:(1)战争。战争是最有影响的政治因素。战争会破坏社会生产力，使经济停滞、生产凋敝、收入减少、利润下降。(2)政权更迭、领袖更替等政治事件。这些事件的爆发都会影响社会安定，进而影响投资者的心理状态和投资行为，引起股票市场的涨跌变化。(3) 政府重大经济政策的出台、社会经济发展规划的制订、重要法规的颁布等。这些会影响投资者对社会经济发展前景的预期，从而也会引起股票价格变动。(4)因发生不可预料和不可抵抗的自然灾害或不幸事件，给社会经济和上市公司带来重大财产损失而又得不到相应赔偿，股价会下跌。"},{"id":"n-law3-41","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"投资者投资优先股好处在于()。","options":["优先股股息固定，有债券特性，优先股股东可以要求无法支付股息公司进入破产程序，保护自己的权益","优先股优先于普通股分配公司利润和剩余财产，因而投资风险相对较小，为一种较安全的投资对象","优先股股息固定，投资者投资优先股收入稳定，可以作中长线投资","优先股因收入稳定，二级市场价格波动小，风险较低，优先股的股息收益一般会高于普通股投资收益"],"answer":"BC","explain":"本题考查优先股。优先股通常具有以下四个特征:(1)持有优先股并不总是有利的。比如。在公司经营有方、盈利丰厚情况下，优先股的股息收益可能会大大低于普通股(D 错误)。(2)由于优先股优先于普通股分配公司利润和剩余财产，投资风险相对较小，不失为一种较安全的投资对象。优先股因收入稳定，二级市场价格波动小，风险较低，适宜中长线投资。(BC 正确)。(3)优先股的清偿顺序先于普通股，而次于债权人。也就是说，一旦公司破产清算，剩余财产先分给债权人，再分给优先股股东，最后分给普通股股东。但与公司债权人不同，优先股股东不可以要求无法支付股息公司进入破产程序，不能向人民法院提出企业重整、和解或者破严清算甲请(A错误)。故本题选BC。"},{"id":"n-law3-42","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"深圳证券交易所交易证券托管制度可概括为()。","options":["自动托管","随处通买","哪买哪卖","转托不限"],"answer":"ABCD","explain":"深圳证券交易所的证券托管制度可概括为:自动托管，随处通买，哪买哪卖，转托不限。"},{"id":"n-law3-43","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于地方政府债券概念说法，错误有()。","options":["根据本地区经济发展和资金需求状况发行","由中央财政承担还本付息责任","向银行、证券公司等金融机构发行筹集资金","是一种债务凭证"],"answer":"BC","explain":"(1)地方政府债券简称地方债券或地方公债或地方债，是地方政府根据本地区经济发展和资金需求状况，以承担还本付息责任为前提，向社会筹集资金的债务凭证。(2)地方政府债券筹集资金一般用于弥补地方财政资金的不足，或者地方兴建大型项目。(3)地方政府债券按资金用途和偿还资金来源分类，通常可以分为一般债券(普通债券)和专项债券(收益债券)。前者是指地方政府为缓解资金紧张或解决临时经费不足而发行的债券，后者是指为筹集资金建设某项具体工程而发行的债券。近年我国允许试点省(市)自行发债。"},{"id":"n-law3-44","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"企业债券募集资金可用于()。","options":["固定资产投资项目","弥补亏损","收购产权(股权)","补充营运资金"],"answer":"ACD","explain":""},{"id":"n-law3-45","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于金融债券发行的操作要求的说法，正确的有()。","options":["金融债券可在全国银行间债券市场公开发行或定向发行，可以采取一次足额发行或限额内分期发行的方式","商业银行、财务公司、金融租赁公司发行金融债券没有强制性担保要求","发行人应在中国人民银行核准金融债券发行之日起60个工作日内开始发行金融债券，并在规定期限内完成发行","发行人未能在规定期限内完成发行，原金融债券发行核准文件自动失效，发行人不得继续发行本期金融债券"],"answer":"ACD","explain":"金融债券发行的操作要求:(1) 发行方式。金融债券可在全国银行间债券市场公开发行或定向发行，可以采取一次足额发行或限额内分期发行方式。(2)担保要求。①商业银行发行金融债券没有强制性担保要求；②财务公司发行金融债券需要由财务公司的母公司或其他有担保能力的成员单位提供相应担保，经原中国银监会批准免于担保除外:③对于商业银行设立金融租赁公司，资质良好但成立不满3年的，应由具有担保能力的担保人提供担保。(3) 其他相关事项。①发行人应在中国人民银行核准金融债券发行之日起60个工作日内开始发行金融债券，并在规定期限内完成发行。②发行人未能在规定期限内完成发行的，原金融债券发行核准文件自动失效，发行人不得继续发行本期金融债券。"},{"id":"n-law3-46","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"我国在国际债券市场上已发行的债券品种有()。","options":["政府债券","特种国债","金融债券","可转换公司债券"],"answer":"ACD","explain":"我国发行国际债券始于20 世纪80年代初期。主要的债券品种有:政府债券、金融债券、可转换公司债券。"},{"id":"n-law3-47","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"商业银行发行金融债券应具备()条件。","options":["具有良好公司治理机制","核心资本充足率不低于8%","最近3年连续盈利","最近3年没有重大违法、违规行为"],"answer":"ACD","explain":"商业银行发行混合资本债券应具备条件与其发行金融债券完全相同。商业银行发行金融债券应具备以下条件:(1) 具有良好的公司治理机制:核心资本充足率不低于 4%:最近3年连续盈利；(2)贷款损失准备计提充足；(3) 风险监管指标符合监管机构的有关规定；(4) 最近3年没有重大违法、违规行为；(5) 中国人民银行要求的其他条件。"},{"id":"n-law3-48","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于银行间债券市场的说法，正确的有()。","options":["银行间债券市场参与者包括商业银行、农村信用联社、保险公司.证券公司等金融制机构以及一些非金融机构合格投资人","交易所债券市场已经成为我国债券市场的主体部分","银行间债券市场也已成为中央银行公开市场操作平台","与国际市场相比，市场流动性己经很高"],"answer":"AC","explain":"(1) 银行间债券市场包括商业银行、农村信用联社、保险公司、证券公司等金融机构以及一些非金融机构合格投资人通过北京金融资产交易所进行债券买卖和回购的市场。(2)银行间债券市场目前已成为我国债券市场的主体部分，也己成为中央银行公开市场操作平台。(3)发展现状表现在以下几个方面:市场规模快速扩大，直接融资比例不断上升；与国际市场相比较，市场流动性仍然较低等。"},{"id":"n-law3-49","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"债券投资主要风险因素包括()。","options":["违约风险","流动性风险","操作风险","汇率风险"],"answer":"ABD","explain":"(1)债券估值基本原理就是现金流贴现。债券投资者持有债券，会获得利息和本金偿付。把现金流入用适当的贴现率进行贴现并求和，便可得到债券的理论价格。(2)影响债券现金流确定的因素有:①债券的面值和票面利率。②计付息间隔。③债券嵌入式期权条款。④债券税收待遇。⑤其他因素。债券的利率类型(浮动利率、固定利率)，债券的币种(单一货币、双币债券)等因素都会影响债券的现金流。(3)影响债券贴现率确定因素:债券必要回报率=真实无风险收益率+预期通货膨胀率+风险溢价。风险溢价根据各种债券的风险大小而定，是投资者因承担投资风险而获得昀补偿。债券投资的主要风险因素包括违约风险(信用风险)、流动性风险、汇率风险等。"},{"id":"n-law3-50","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列属于债券交割方式的有()。","options":["当日交割","普通日交割","约定日交割","实物交割"],"answer":"ABC","explain":""},{"id":"n-law3-51","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"属于中小非金融企业集合票据特点的有()。","options":["分别负债","发行期限灵活","集合发行","引入信用增进机制"],"answer":"ABCD","explain":"(1) 中小非金融企业集合票据是指2个(含)以上、10个(含)以下具有法人资格的企业，在银行间债券市场以统一产品设计、统一券种冠名、统一信用增进、统一发行注册方式共同发行的，约定在一定期限还本付息的债务融资工具。(2) 中小非金融企业集合票据特点:(1)分别负债、集合发行。(2)发行期限灵活。(3)引入信用增进机制。"},{"id":"n-law3-52","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"资产证券化是以()为支持，发行可交易证券的一种融资形式。","options":["特定资产组合","特定股票组合","特定基金组合","特定现金流"],"answer":"AD","explain":"资产证券化是以特定资产组合或特定现金流为支持，发行可交易证券的一种融资形式。传统的证券发行是以企业为基础，而资产证券化是以特定的资产池为基础发行证券。兴起原因:"},{"id":"n-law3-53","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"存在下列情形之一的，发行人、主承销商、证券服务机构应当及时书面报告证券交易所或者中国证监会，证券交易所或者中国证监会应当中止相应发行上市审核程序或者发行注册程序()。","options":["发行人因涉嫌违法违规被行政机关调查","发行人主承销商，以及律师事务所、会计师事务所、资信评级机构等证券服务机构签字人员被中国证监会依法采取限制从事证券服务业务等监管措施或者证券市场禁入措施","发行人或主承销商主动要求中止发行上市审核程序或者发行注册程序，理由正当且经证券交易所或者中国证监会批准","证券交易所实施一定期限内不接受其出具相关文件的纪律处分，尚未解除"],"answer":"ABCD","explain":"存在下列情形之一，发行人、主承销商、证券服务机构应当及时书面报告证券交易所或者中国证监会，证券交易所或者中国证监会应当中止相应发行上市审核程序或者发行注册程序:①发行人因涉嫌违法违规被行政机关调查，或者被司法机关侦查，尚未结案，对其公开发行公司债券行政许可影响重大；②发行人前主承销商，以及律师事务所、会计师事务所、资信评级机构等证券服务机构被中国证监会依法采取限制业务活动、责令停业整顿、指定其他机构托管、接管等监管措施，或者被证券交易所实施一定期限内不接受其出具的相关文件纪律处分，尚未解除；③发行人主承销商，以及律师事务所、会计师事务所、资信评级机构等证券服务机构签字人员被中国证监会依法采取限制从事证券服务业务等监管措施或者证券市场禁入的措施，或者被证券交易所实施一定期限内不接受其出具的相关文件的纪律处分，尚未解除:④发行人或主承销商主动要求中止发行上市审核程序或者发行注册程序，理由正当且经证券交易所或者中国证监会批准；⑤中国证监会或证券交易所规定其他情形。"},{"id":"n-law3-54","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于开放式基金申购、赎回概念的说法，正确的有()。","options":["基金的申购是指投资者在开放式基金合同生效后，申请购买基金份额行为","基金的赎回是指基金份额持有人要求基金管理人购回其所持有的开放式基金份额行为","开放式基金赎回不能通过基金管理人直销中心办理了0","开放式基金的申购可以通过基金销售机构前代销网点办理"],"answer":"ABD","explain":"投资者在开放式基金合同生效后，申请购买基金份额行为通常被称为基金的申购。开放式基金赎回，是指基金份额持有人要求基金管理人购回其所持有的开放式基金份额行为。开放式基金申购和赎回与认购一样，可以通过基金管理人的直销中心与基金销售机构代销网点办理。"},{"id":"n-law3-55","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"我国基金监管目标有()。","options":["规范基金活动","进行投资者教育","降低系统风险","保证市场公平、效率和透明"],"answer":"ACD","explain":"(1) 基金监管是指监管部门运用法律的、经济的以及必要的行政手段，对基金市场参与者行为的监督与管理。(2) 基金监管对于维护证券市场的良好秩序、提高证券市场效率和保护基金份额持有人利益均具有重大意义。(3) 基金监管目标是指基金监管所要达到的目的和效果，是基金监管活动出发点和价值归宿。(4) 我国基金监管目标是:保护投资人及相关当事人合法权益:规范基金活动，保证市场的公平、效率和透明，降低系统风险:促进证券投资基金和资本市场的健康发展。"},{"id":"n-law3-56","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于不同类型基金利润分配原则的说法，正确的有()。","options":["封闭式基金采用现金方式分红或红利再投资","根据有关规定，一般开放式基金利润分配默认的方式应当采用现金分红","对于每日按照面值进行报价的货币市场基金，可以在基金合同中将收益分配方式约定为红利再投资，并应当每日进行收益分配","开放式基金的基金份额持有人可以事先选择分红再投资"],"answer":"BCD","explain":"(1) 根据有关规定，封闭式基金的收益分配每年不得少于一次，封闭式基金年度收益分配比例不得低于基金年度可供分配利润 90%。基金分配后，基金份额净值不得低于面值。封闭式基金只能采用现金方式分红。(2)根据有关规定，一般开放式基金利润分配默认方式应当采用现金分红。开放式基金的的基金份额持有人可以事先选择分红再投资。基金份额持有人事先未作出选择的，基金管理人应当支付现金。(3) 对于每日按照面值进行报价的货币市场基金，可以在基金合同中将收益分配的方式约定为红利再投资，并应当每日进行收益分配。"},{"id":"n-law3-57","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于基金运作信息披露，下列说法正确有()。","options":["开放式基金在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值","货币基金不必披露每个开放日的份额净值，但需要披露每万份基金收益和最近7日年化收","基金投资组合报告需要披露基金资产组合，按行业分类的股票投资组合，前10名股票明","基金年度报告是基金各类信息披露文件中信息量最大文件"],"answer":"ABCD","explain":"本题考查基金运作信息披露的相关内容。(1) 基金年度报告是基金的各类信息披露文件中信息量最大的文件(D正确)，在会计年度结束后3个月内经过审计后予以公告。(2) 投资组合报告需要披露基金资产组合，按行业分类股票投资组合，前10名股票明细，按券种分类的债券投资组合，前5名债券明细，投资贵金属、股指期货、国债期货等情况(C正确)。(3) 开放式基金会披露每个开放日的份额净值和份额累计净值(A 正确)。(4) 对货币基金而言，货币基金每日分配收盖，份额净值保持1元不变，因此货币基金不像一般开放式基金那样披露每个开放日舸份额净值，而是需要披露收益公告，包括每万份基金收益和最近7日年化收益率(B正确)。故本题选 ABCD。"},{"id":"n-law3-58","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于基金资产估值，下列说法正确的有()。","options":["基金份额净值是评价基金投资业绩基础指标之一","基金资产总值是基金全部资产的价值总和","我国基金资产估值责任人是基金管理人","基金托管人对基金管理人雨估值及净值计算结果负有复核义务"],"answer":"ABCD","explain":""},{"id":"n-law3-59","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于开放式基金份额的转换、非交易过户、转托管与冻结说法，正确的有()。","options":["投资人可以通过办理转托管业务，实现其变更办理基金业务销售渠道需要","基金份额冻结与解冻业务由基金管理人直接受理","基金非交易过户主要包括继承、捐赠、司法强制执行等情况","基金份额的转换常常需要收取转换费用，因此综合费用没有优势"],"answer":"AC","explain":"(1) 基金份额冻结与解冻业务由注册登记机构直接受理，并须提供要求相关资料。(2)投资人可通过办理转托管业务，实现其变更办理基金业务销售渠道(或网点)的需要。(3) 基金份额转换常常还会收取一定的转换费用。由于基金份额转换不需要先赎回己持有基金再购买另一基金，综合费用仍有优势。(4) 开放式基金非交易过户，是指不采用申购、赎回等交易方式，将一定数量的基金份额按照一定规则从某一投资者基金账户转移到另一投资者基金账户行为，主要包括继承、捐赠、司法强制执行和经注册登记机构认可的其他情况下的非交易过户。"},{"id":"n-law3-60","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于我国基金发展的说法，正确的有()。","options":["在早期探索阶段，我国基金业发展带有探索性、自发性和不规范性特征","我国开放式基金的出现先于封闭式基金","在创新发展阶段，我国基金产品创新层出不穷，包括LOF 基金、ETF 基金、分级基金、QDII 基金等","目前香港成立的基金可以向内地销售，内地成立的基金也可以进入香港市场"],"answer":"ACD","explain":"证券投资基金在我国的发展可分为四个阶段。"},{"id":"n-law3-61","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"从证券投资基金的运作关系来看，基金的主要当事人包括()。","options":["监管机构","基金投资者","基金管理人","基金托管人"],"answer":"BCD","explain":"包:基金信息披露是指基金信息披露义务人按照法律、行政法规和中国证监会规定披露基金信息，并凭所披露信息的真实性、准确性和完整性的活动。基金信息披露义务人包括基金管理人、基金托管人、召集基金份额持有人大会基金份额持有人等法律行政法规和中国证监会规定的自然人、法人和其他组织。监管机构则对基金市场上的各类参与主体实施全面监管。"},{"id":"n-law3-62","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于金融期权的说法，正确有()。","options":["金融期权的主要特征在于它仅仅是买卖权利的交换","期权的买方在支付了期权费后，承担着履行该期权合约义务","期权卖方在收取期权费后，承担着在规定时间内履行该期权合约义务","当期权的买方选择行使权利时，卖方必须无条件地履行合约规定的义务"],"answer":"ACD","explain":""},{"id":"n-law3-63","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"金融自由化主要内容包括()。","options":["逐步实现利率自由化","鼓励银行综合化发展","放松外汇管制","放宽对资本流动的限制"],"answer":"ABCD","explain":"金融自由化主要内容包括:(1)取消对存款利率最高限额，逐步实现利率自由化；(2)打破金融机构经营范围的地域和业务种类限制，允许各金融机构业务交叉、互相自由渗透，鼓励银行综合化发展；(3)放松外汇管制；(4)开放各类金融市场放宽对资本流动的限制。"},{"id":"n-law3-64","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于信用衍生工具的说法，正确的有()。","options":["主要包括信用违约互换、信用联结票据等","是以基础产品所蕴含的信用风险或违约风险为基础变量的金融衍生工具","用于转移或防范系统性风险","是20世纪90 年代以来发展最为迅速的一类衍生产品"],"answer":"ABD","explain":"信用衍生工具是指以基础产品所蕴含的信用风险或违约风险为基础变量的金融衍生工具，用于转移或防范信用风险，是20世纪90年代以来发展最为迅速的一类衍生产品，主要包括信用互换、信用联结票据以及信用风险缓释合约、信用风险缓释凭证等信用风险缓释工具。"},{"id":"n-law3-65","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列各项中，可以充当金融衍生工具基础的变量有()。","options":["通货膨胀率","信用等级","温室气体排放","银行定期存单"],"answer":"ABC","explain":"金融衍生工具基础变量种类繁多，主要是各类资产价格、价格指数、利率、汇率、费率、通货膨胀率以及信用等级等；近些年来，某些自然现象(如气温、降雪量、霜冻、飓风)，甚至人类行为(如选举、温室气体排放)也逐渐成为金融衍生工具前基础变量。与之不同的是现货金融产品(如债券、股票、银行定期存款单等)。"},{"id":"n-law3-66","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"投资者在参与沪深300股指期货交易时，所使用的交易编码应根据投资目的不同分为()。","options":["套期保值用途","套利用途","套汇用途","投机用途"],"answer":"ABD","explain":"交易编码是客户、从事自营业务的交易会员进行期货交易专用代码。投资者可以根据不同投资目的，分别申请套期保值、套利和投机用途的客户号。"},{"id":"n-law3-67","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列各项中，属于利用金融市场进行风险管理的行为有()。","options":["持有未到期外汇应付账款的进口商卖出了对应外汇的期货合约","持有债券的保险基金购入了信货违约互换合约","持有股票证券投资基金出售了股指期货合约","担心火灾厂商购买了保险合约"],"answer":"ABCD","explain":"风险管理策略，是指金融机构面临风险时可以选择采用的应对方法，主要包括风险规避、风险控制、风险分散、风险对冲、风险转移、风险补偿与准备金。"},{"id":"n-law3-68","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于风险管理流程说法，正确的有()。","options":["风险的应对主要包括风险偏好管理、风险计量、风险定价与报备、风险缓释以及应急计划","风险监测是风险管理重要一环，是风险偏好，风险限额，以及日常风险管理得以有效实施重要保障","证券公司应当建立逐日盯市的机制，准确计算、动态监控关键风险指标情况，判断和预测各类风险指标的变化，及时预警超越各类、各级风险限额情形","证券机构应当建立健全风险报告体系定期对公司所面临的风险状况进行检测，编制风险报告，确保各类风险信息顺畅并及时的在公司内部传递"],"answer":"BCD","explain":"①风险的应对主要是证券公司根据风险识别、计量、监控及预警等情况，针对不同类别、不同发生概率及不同损失程度的风险所采取的应对措施，主要包括风险偏好管理、风险限额、风险定价与拨备、风险缓释，以及应急计划等，故“风险计量”表述错误。②风险监测是风险管理的重要一环，是风险偏好、风险限额，以及日常风险管理得以有效实施的重要保障。③证券公司应当建立逐日盯市等机制，准确计算、动态监控关键风险指标情况，判断和预测各类风险指标的变化，及时预警超越各类、各级风险限额的情形。④证券机构应该建立健全风险报告体系，定期对公司所面临风险状况进行检测，编制风险报告，确保各类风险信息顺畅并及时地在公司内部传递。"},{"id":"n-law3-69","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于金融机构和风险的说法，正确的有()。","options":["风险管理是金融机构核心竞争力","金融机构必定会承担风险","风险管理以为公司创造价值为目标","内部控制是一种传统风险管理方法"],"answer":"ABCD","explain":"(1)金融机构约企业本质和基本使命就在于承担和管理风险，并实现风险换收益。金融机构尽管可以从单个项目上规避风险，但是不可能规避或不承担任何风险。(2)风险管理是金融机构的核心竞争力。以内部控制为主要内容的传统风险管理已经发展到包含风险的对冲、限额、定价以及风险业绩调整等更加全面的现代风险管理阶段，进而风险管理也进入金融机构战略管理的层面，超越了保驾护航的范畴，成为核心竞争力。(3)风险管理助力金融业务持续、稳定、健康发展。风险管理的目标是创造价值，而不是减少损失或降低风险。A. 主权风险"},{"id":"n-law3-70","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"国别风险主要包括()","options":["主权风险","货币风险","政治风险","转移风险"],"answer":"ABCD","explain":"本题考查国别风险。国别风险存在于授信、国际资本市场业务、设立境外机构等经营活动中。国别风险主要包括转移风险(D正确)、主权风险(A正确)、货币风险(B正确)、政治风险(C正确)。故本题选 ABCD。"},{"id":"n-law3-71","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于风险管理相关的活动中，属于风险控制过程中事中控制措施的有()。","options":["风险定价","流程控制","工具控制","实时监测和报告"],"answer":"BCD","explain":"事前控制主要是确定风险管理政策，包括确定风险容忍度、风险限额、风险定价和制订应急预案等:事中是指在风险资产实际运作过程中采用流程、工具进行动态、实时监测和报告；事后控制是在风险影响因素发生变化或风险发生后采取的对应措施，包括风险转移和重新调整风险限额。"},{"id":"n-law3-72","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"现代信用风险分析的构成要素包括()。","options":["违约概率","违约损失率","违约时风险暴露","违约时间"],"answer":"ABC","explain":"(1)信用风险的构成要素分析以违约为中心。在信用风险分析中，违约依然是最为重要信用事件，对信用风险的描述和量化仍然是以违约为中心，主要包括违约概率(PD)、违约损失率(LGD)和违约时的风险暴露 (EAD)等。(2)这些要素决定了信用产品的预期损失和非预期损失。对这些信用风险要素量化是以损失的概率分布进行科学描述风险的基础。现代风险计量方法的中心工作就是以各种模型准确量化这些风险要素。"},{"id":"n-law3-73","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"证券公司压力测试可采用的方法有()。","options":["敏感性分析","历史情景法","假设情景法","历史情景法和假设情景法相结合"],"answer":"ABCD","explain":""},{"id":"n-law3-74","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于金融期权说法，正确的有()。","options":["当期权买方选择行使权利时，卖方同样也有选择的权利","金融期权的主要特征在于它仅仅是买卖权利交换","期权交易买方可以选择行使他所拥有的权利","金融期权是以金融工具或金融变量为基础工具期权交易形式"],"answer":"BCD","explain":"本题考查金融期权。金融期权是指以金融工具或金融变量为基础工具的期权交易形式(D正确)。当期权买方选择行使权利时，卖方必须无条件地履行合约规定的义务，而没有选择的权利(A错误，应为“没有选择的权利”，而非“有选择权”)。金融期权的主要特征在于它仅仅是买卖权利的交换 (B 正确)，期权的买方可以选择行使他所拥有的权利 (C 正确)；期权卖方在收取期权费后就承担着在规定时间内履行该期权合约的义务。故本题选 BCD项。"},{"id":"n-law3-75","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据债券发行条款中是否规定约定期限向债券持有人支付利息，债券可分为()。","options":["附息债券","零息债券","保值债券","息票累积债券"],"answer":"ABD","explain":"根据债券发行条款中是否规定在约定期限向债券持有人支付利息，债券可分为零息债券、附息债券、息票累积债券三类。"},{"id":"n-law3-76","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"中国存托凭证是指由存托人签发、以境外证券为基础在中国境内发行、代表境外基础证券权益的证券。参与主体有()。","options":["发行人","存托人","托管人","持有人"],"answer":"ABCD","explain":"中国存托凭证是指由存托人签发、以境外证券为基础在中国境内发行、代表境外基础证券权益的证券。发行主体包括:(1) 发行人爹在境外发行基础证券。(2)存托人:存托人持有基础证券，在境内签发相应的存托凭证:按照存托协议约定，根据存托凭证持有人意愿行使境外基础证券相应权利，办理存托凭证分红、派息等业务。(3)持有人:存托凭证持有人依法享有存托凭证代表的境外基础证券权益，并按照存托协议约定，通过存托人行使其权利。(4)托管人，是指受存托人委托，按照托管协议托管存托凭证所代表的基础证券金融机"},{"id":"n-law3-77","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于区域性股权市场，下列说法错误的是()。","options":["可以为全国的企业私募证券或股权的融资、转让提供服务","由所在地的中国证监会派出机构按规定实施监管，并承担相应风险处置责任","采用公开方式发行证券","采取集中竞价、做市商等集中交易方式进行证券转让"],"answer":"ABCD","explain":"区域性股权市场不得为在省级行政区域外的企业私募证券或股权的融资、转让提供服务(A错误)；区域性股权市场由所在地省级人民政府按规定实施监管，并承担相应风险处置责任(B错误):在区域性股权市场发行或转让证券的不得采用广告、公开劝诱等公开或变相公开方式发行证券，不得以任何形式非法集资，不得采取集中竞价、做市商等集中交易方式进行证券转让。(CD 错误)。"},{"id":"n-law3-78","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"注册制与核准制的实质区别表现在()。","options":["坚持开门搞审核","大幅优化发行上市条件","切实把好信息露质量关","审核部门要准确对企业的投资价值作出判断"],"answer":"ABC","explain":"注册制与核准制的实质区别:一是大幅优化发行上市条件。改革后，仅保留了企业公开发行股票必要资格条件、合规条件，将核准制下实质性门槛尽可能转化为信息披露要求，审核部门不再对企业投资价值作出判断。二是切实把好信息披露质量关。实行注册制，绝不意味着放松质量要求，审核把关更加严格。审核工作主要通过问询来进行，督促发行人真实、准确、完整披露信息。同时，综合运用多要素校验、现场督导、现场检查、投诉举报核查、监管执法等多种方式，压实发行人的信息披露第一责任、中介机构“看门人”责任。三是坚持开门审核。审核注册的标准、程序内容、过程、结果全部向社会公开，公权力运行全程透明、严格制衡，接受社会监督与核准制有根本的区别。"},{"id":"n-law3-79","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"2017年，证监会发布了 《关于进一步加强证券基金经营机构债券交易监管的通知》，对证券公司自营、资管所涉及的债券买卖、回购等业务的()等进行了详细规范。","options":["国别风险","操作风险","信用风险","市场风险"],"answer":"BCD","explain":"2017 年，中国证监会根据“一行三会” 《关于规范债券市场参与者债券交易业务通知》配套发布了 《关于进一步加强证券基金经营机构债券交易监管的通知》，对证券公司自营、资管所涉及债券买 卖、回购等业务前市场风险、信用风险、操作风险等进行了详细规范。"},{"id":"n-law3-80","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"大宗商品类金融衍生工具，是指标的资产为大宗商品或者商品价格指数及相关指数远期、期货、期权以及互换。常见的标的有农产品、金属、原油和其他石化产品、天然气、电力、海运费和天气指数等。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。大宗商品类金融衍生工具，是指标的资产为大宗商品或者商品价格指数及相关指数的远期、期货、期权以及互换。常见的标的有农产品、金属、原油和其他石化产品、天然气、电力、海运费和天气指数等。"},{"id":"n-law3-81","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"由于结构化金融衍生产品挂钩基础资产具有不同的风险特征，嵌入式衍生产品的种类、结构各异，导致结构化产品的收益与风险出现非常大的差异。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。由于结构化金融衍生产品挂钩基础资产具有不同风险特征，嵌入式衍生产品种类、结构各异，导致结构化产品收益与风险出现非常大的差异。同时，由于这类产品结构复杂，难以为普通投资者所掌握，通常监管机构和行业自律组织均要求金融机构在销售时格外审慎，防止错误地销售给不具备风险承受能力的客户。"},{"id":"n-law3-82","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"金融期货合约的基础工具是各种金融工具，如外汇、债券、股票、股价指数等。换言之，金融期货是以金融工具为基础工具期货交易。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。金融期货合约的基础工具是各种金融工具(或金融变量)，如外汇、债券、股票、股价指数等。换言之，金融期货是以金融工具(或金融变量)为基础工具的期货交易。"},{"id":"n-law3-83","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"内部审计是第三道风险防线。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。业务条线部门是第一道风险防线，风险管理部门和合规部门是第二道风险防线，内部审计是第三道风险防线。"},{"id":"n-law3-84","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"风险限额管理包括风险限额设定、风险限额监测、超限额处置等坏节。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。风险限额管理包括风险限额设定、风险限额监测、超限额处置等环节。"},{"id":"n-law3-85","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"金融机构的本质是承担和经营风险的企业。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。金融机构的本质是承担和经营风险的企业。"},{"id":"n-law3-86","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"融资流动性风险主要是从单个机构的角度分析金融机构在面临现金需求时其融资能力随时间推移而引起的不确定波动，是指在不影响其日常经营和财务状况的条件下，金融机构难以有效满足其预期和非预期的、当前和未来现金流和担保需求风险。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。融资流动性风险主要是从单个机构的角度分析金融机构在面临现金需求时其融资能力随时间推移而引起的不确定波动，是指在不影响其日常经营和财务状况的条件下，金融机构难以有效满足其预期和非预期的、当前和未来现金流和担保需求风险。"},{"id":"n-law3-87","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"战略风险是指证券公司在追求短期商业目的和长期发展目标的过程中，因不适当的发展规划和战略决策给证券公司造成损失或不利影响的风险。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。战略风险是指证券公司在追求短期商业目和长期发展目标的过程中，因不适当的发展规划和战略决策给证券公司造成损失或不利影响的风险。"},{"id":"n-law3-88","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"敏感性是一个变量对另外一个变量发生的变化的反应程度。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。敏感性是一个变量对另外一个变量发生的变化反应程度，也就是经济学分析中的弹性。"},{"id":"n-law3-89","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司制定或者设立专门部门履行风险管理职责，在合规部门负责人的领导下推动全面风险管理工作，监测、评估、报告公司整体风险水平；并为业务决策提供风险管理建议，协助、指导和检查各部门、分支机构及子公司的风险管理工作。()","options":["正确","错误押题加"],"answer":"B","explain":"本题表还错误。证券公司制定或者设立专门部门履行风险管理职责，风险管理部门在首席风险官领导下推动全面风险管理工作，监测、评估、报告公司整体风险水平，并为业务决策提供风险管理建议，协助、指导和检查各部门、分支机构及子公司的风险管理工作。本题说法错误。"},{"id":"n-law3-90","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司进行压力测试应遵循的原则包括全面性原则、实践性原则、审慎性原则、前瞻性原则。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。证券公司进行压力测试应遵循的原则包括全面性原则、实践性原则、审慎性原则、前瞻性原"},{"id":"n-law3-91","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"目前，我国银行间外汇市场交易方式分为竞价和询价两种，竞价交易占主导地位。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。目前，我国银行间外汇市场交易方式分为竞价和询价两种，询价交易占主导地位。"},{"id":"n-law3-92","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"商业银行次级债券本金和利息的清偿顺序是列手商业银行其他负债之后、先于商业银行股权资本。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。商业银行次级债券是指商业银行发行、本金和利息清偿顺序列于商业银行其他负债之后、先于商业银行股权资本债券。"},{"id":"n-law3-93","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"间接融资具有分散性，分散性指间接融资在无数个企业相互之间、政府与企业和个人之间、个人与个人之间，或企业与个人之间进行的，因此，融资活动分散于各种场合。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。分散性是直接融资特点，而不是“间接融资”。直接融资的分散性指融资发生在无数个企业相互之间、政府与企业和个人之间、个人与个人之间，或企业与个人之间进行的，因此，融资活动分散于各种场合。"},{"id":"n-law3-94","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"实行客户交易结算资金第三方存管制度后，证券投资者存取资金的方式是通过证券公司直接办理。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。3S在客户交易结算资金第三方存管制度框架下，证券公司与客户之间的资金清算交收，需要由证券公司与指定商业银行配合完成。"},{"id":"n-law3-95","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"中小非金融企业发行集合票据，应依据《银行间债券市场非金融企业债务融资工具注册规则》在交易商协会注册，一次注册，多次发行。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。中小非金融企业发行集合票据，应依据《银行间债券市场非金融企业债务融资工具注册规则》在交易商协会注册，一次注册，一次发行。"},{"id":"n-law3-96","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"银行间同业拆借市场、商业票据市场、短期国库券市场、大额可转让存单市场、股票市场等属于货币市场金融工具。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。货币市场，是指所交易金融资产到期期限在一年以内的金融市场，例如银行间同业拆借市场、商业票据市场、短期国库券市场、大额可转让存单市场等。这些金融资产具有比较强“货币性”，主要解决市场参与者短期性的资金周转和余额调剂问题，因此，这些市场被称为货币市场。"},{"id":"n-law3-97","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"资本公积金转增股本以后，股东权益总量和每位股东占公司的股份比例和发行在外股份总数均发生变化。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。资本公积金转增股本以后，股东权益总量和每位股东占公司的股份比例均未发生变化，唯一的变动是发行在外的股份总数增加了。"},{"id":"n-law3-98","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"中国基金业协会作为行业自律性组织，对基金公司实施行业自律管理，其职责之一是制定基金从业人员资格标准和行为准则，并监督实施。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。制定基金从业人员的资格标准和行为准则，并监督实施是证监会职责之一，而不是“基金业协会”。"},{"id":"n-law3-99","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"养老目标基金是指追求养老资产的长期稳健增值为目的，鼓励投资人长期持有，采用成熟的资产配置策略，合理控制投资组合波动风险的私募基金。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。养老目标基金是指以追求养老资产的长期稳健增值为目的，鼓励投资人长期持有，采用成熟的资产配置策略，合理控制投资组合波动风险的公开募集证券投资基金。养老目标基金应当采用基金中基金形式或中国证监会认可的其他形式运作。"},{"id":"n-law3-100","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"影响股票投资价值的内部因素主要包括公司净资产、盈利水平、股利政策、股份分割、增资和减资以及并购重组等。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。影响股票投资价值的内部因素主要包括:公司净资产、盈利水平、股利政策、股份分割、增资和减资以及并购重组等。影响股票投资价值的外部因素主要包括:宏观经济因素、行业因素及市场因素。"},{"id":"n-law3-101","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"债券清算应该按照全额交收原则办理债券和价款交割。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。债券清算按照净额交收原则办理债券和价款交割。"},{"id":"n-law3-102","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"新《证券法》设置了 “投资者保护”专章，建立上市公司股东权利代为行使征集制度，明确上市公司董事会、独立董事、持有 3%以上有表决权股份的股东或者投资保护机构可以作为征集人代为出席股东大会，并代为行使提案权、表决权等股东权利。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。新《证券法》设置了 “投资者保护”专章，建立上市公司股东权利代为行使征集制度，明确上市公司董事会、独立董事、持有1%以上有表决权股份的股东或者投资者保护机构可以作为征集人代为出席股东大会，并代为行使提案权、表决权等股东权利。"},{"id":"n-law3-103","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"合格境外机构投资者境内股票投资，应当遵守中国证监会规定的持股比例限制和国家其他有关规定，其中所有增外投资者对单会上市公司A股的特股比例总和不超过该上市公司股份总数10%。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。合格境外机构投资者的境内股票投资，应当遵守中国证监会规定的持股比例限制和国家其他有关规定:单个境外投资者通过合格境外机构投资者持有一家上市公司股票的，持股比例不得超过该公司股份总数的10%:所有境外投资者对单个上市公司A股的持股比例总和，不超过该上市公司股份总数的30%。"},{"id":"n-law3-104","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"我国交易所市场对附息债券的计息规定是全年天数统一按365天计算；利息累计天数规则是按实际天数计算，算头算尾。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。我国交易所市场对附息债券的计息规定是全年天数统一按 365天计算；利息累计天数规则是按实际天数计算，算头不算尾，闰年2月29日不计息。"},{"id":"n-law3-105","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"目前，沪、深证券交易所封闭式基金交易不收取印花税。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。获取按照沪、深证券交易所公布的收费标准，我国基金交易佣金不得高于成交金额0.5%(深圳证券交易所特别规定该佣金水平不得低于代收的证券交易监管费和证券交易经手费，上海证券交易所无此规定)，起点5元，由述券公司向投资者收取。目前，封闭式基金交易不收取印花税。"},{"id":"n-law3-106","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"关于国债销售价格的因素，市场利率趋于下降，限制了承销商确定销售价格空间。","options":["正确","错误"],"answer":"B","explain":"本题表述错误。市场利率的高低及其变化对国债销售价格起看显著的导向作用，市场利率趋于上升，就限制了承销商确定销售价格的空间；市场利率趋于下降，就为承销商确定销售价格拓宽了空间。"},{"id":"n-law3-107","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"我国保险行业是一个快速发展行业，随着经济的发展和人民生活水平的提高，人们越来越重视保险，保险行业的需求也越来越大。目前，我国保险行业已经成为世界上最大保险市场之一。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。我国保险行业是一个快速发展的行业，随着经济的发展和人民生活水平的提高，人们越来越重视保险，保险行业需求也越来越大。目前，我国保险行业已经成为世界上最大的保险市场之一。"},{"id":"n-law3-108","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"债券竞价的原则是价格优先，时间优先和机构优先。","options":["正确","错误"],"answer":"B","explain":"本题表述错误。包:债券竞价原则遵循价格优先、时间优先、客户委托优先。"},{"id":"n-law3-109","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"根据《证券公司分类监管规定》，证券公司可将分类结果用于广告、宣传、营销等商业目。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。根据《证券公司分类监管规定》第三十二条相关表述，证券公司分类结果主要供中国证监会及其派出机构使用，证券公司不得将分类结果用于广告、宜传、营销等商业目的。"},{"id":"n-law3-110","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】基金管理人主要负责办理与基金财产管理业务活动有关的信息披露事项，具体涉及基\n金募集、投资运作、净值披露等各环节。根据此背景回答下列问题。\n\n【问题】基金公开披露的信息中，禁止登载自然人、法人或其他组织的()文字。","options":["祝贺性","恭维性","推荐性","褒扬性"],"answer":"ABC","explain":"基金公开披露的信息中，禁止登载任何自然人、法人或者其他组织的祝贺性、恭维性或推荐性的文字。"},{"id":"n-law3-111","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】基金管理人主要负责办理与基金财产管理业务活动有关的信息披露事项，具体涉及基\n金募集、投资运作、净值披露等各环节。根据此背景回答下列问题。\n\n【问题】以下属于触发披露基金临时报告重大事件是()。","options":["基金扩募","延长基金合同","转换基金运作模式","更换基金管理人和基金托管人"],"answer":"ABCD","explain":"以上均属于重大事项，需要进行临时信息的披露。"},{"id":"n-law3-112","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】基金管理人主要负责办理与基金财产管理业务活动有关的信息披露事项，具体涉及基\n金募集、投资运作、净值披露等各环节。根据此背景回答下列问题。\n\n【问题】基金管理人应当在基金合同生效()在指定报刊和指定网站上登载基金合同生效公告。","options":["次日","5日内","2日内","2个工作日内"],"answer":"A","explain":"基金管理人应当在基金合同生效的次日在指定报刊和指定网站上登载基金合同生效公告。"},{"id":"n-law3-113","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】金融中介机构是指传统银行、证券(期货)、保险等商业银行金融机构或政策性金融\n机构之外，为企业和居民提供服务各类非银行金融机构，它们被称为“新型金融业态”。\n据悉，上海、北京等国内先进城市十分重视金融中介服务机构的发展，并将金融中介服务定\n位为新型金融业态:同类城市中，大连、宁波等地的金融服务中介机构也呈现良好发展态势。\n根据此背景回答下列问题。\n诊\n\n【问题】下列关于金融中介机构体系说法，正确的有()。","options":["按照所从事业务性质及其在金融活动中所起的作用，金融中介机构可分为融资类金融中介机构、投资类金融中介机构、保障类金融中介机构和服务类金融中介机构","在联合国统计署按中心产品分类中，“金融中介、保险及辅助服务”类是17大类中","在联合国统计署按经济活动类型所分 “金融中介”这类活动中，证券交易所的活动属于“辅助金融中介的活动”","“保险公司和养老基金”是国民经济核算体系 SNA 对金融业进行的机构分类之一"],"answer":"ACD","explain":"联合国统计署按中心产品分类，共分九大类。其中有“金融中介、保险及辅助服务类”，大体包括:①金融中介服务:②投资银行服务:③保险和养老基金服务:④再保险服务:⑤金融中介辅助服务:⑥保险和养老基金辅助服务等。"},{"id":"n-law3-114","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】金融中介机构是指传统银行、证券(期货)、保险等商业银行金融机构或政策性金融\n机构之外，为企业和居民提供服务各类非银行金融机构，它们被称为“新型金融业态”。\n据悉，上海、北京等国内先进城市十分重视金融中介服务机构的发展，并将金融中介服务定\n位为新型金融业态:同类城市中，大连、宁波等地的金融服务中介机构也呈现良好发展态势。\n根据此背景回答下列问题。\n诊\n\n【问题】下列关于各类金融中介机构业务昀说法，正确的有()。","options":["证券公司的主要业务包括证券经纪业务、证券投资咨询业务、证券承销与保荐业务、证券自营业务、融资融券业务等","机动车商业保险和责任保险均属于财产保险公司基础类业务","健康保险、变额年金、意外伤害保险均属于人身保险公司的基础类业务","银行承兑汇票和保函均属于商业银行担保承诺类业务.3获"],"answer":"ABD","explain":"变额年金属于人身保险公司的拓展类业务。"},{"id":"n-law3-115","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】金融中介机构是指传统银行、证券(期货)、保险等商业银行金融机构或政策性金融\n机构之外，为企业和居民提供服务各类非银行金融机构，它们被称为“新型金融业态”。\n据悉，上海、北京等国内先进城市十分重视金融中介服务机构的发展，并将金融中介服务定\n位为新型金融业态:同类城市中，大连、宁波等地的金融服务中介机构也呈现良好发展态势。\n根据此背景回答下列问题。\n诊\n\n【问题】银行金融中介机构和非银行金融中介机构是按照()标准做的划分。","options":["按业务特征及货币创造、交换媒介和支付手段的能力","按照是否承担国家政策性金融业务","按照所从事业务性质","按照在金融活动中所起的作用"],"answer":"A","explain":"按业务特征及货币创造、交换媒介和支付手段的能力划分，可划分为银行金融中介机构和非银行金融中介机构。"},{"id":"n-law3-116","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】1994年下半年起，新加坡巴林期货有限公司的总经理兼首席交易员里森在日本东京市\n场上做了一种特别繁琐，期望值很高，风险也极大的衍生金融商品交易一日本日经指数期货，\n55\n\n\n结果日经指数从 1995年1月一路下滑，使里森所持的多头头寸遭受重创，为了反败为胜，\n他以赌徒心态来押宝日经225指数上涨，继续从伦敦调入户资买入大量期货合约，最终惨败。\n1995年2月26日，英国银行业的泰斗，在世界 1000 家大银行中按核心资本排名第 489位，\n有着233年历史巴林银行因进行巨额金融期货投机交易，造成9.16亿英镑巨额亏损，\n被追宣布破产。3月5日，以1英镑的象征性价格卖给荷兰 ING集团。根据此背景回答下列\n问题。\n\n【问题】该案例中，巴林银行的风险是由()引起前。","options":["操作风险","流动性风险","信用风险","市场风险"],"answer":"A","explain":"操作风险是指由不完善或有问题的内部流程、人员和系统以及外部事件所造成损 失的风险。里森以赌徒心态来押宝日经225指数上涨，继续从伦敦调入巨资买入大量期货合约，最终惨败，由此表明巴林银行的风险是由操作风险引起的。"},{"id":"n-law3-117","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】1994年下半年起，新加坡巴林期货有限公司的总经理兼首席交易员里森在日本东京市\n场上做了一种特别繁琐，期望值很高，风险也极大的衍生金融商品交易一日本日经指数期货，\n55\n\n\n结果日经指数从 1995年1月一路下滑，使里森所持的多头头寸遭受重创，为了反败为胜，\n他以赌徒心态来押宝日经225指数上涨，继续从伦敦调入户资买入大量期货合约，最终惨败。\n1995年2月26日，英国银行业的泰斗，在世界 1000 家大银行中按核心资本排名第 489位，\n有着233年历史巴林银行因进行巨额金融期货投机交易，造成9.16亿英镑巨额亏损，\n被追宣布破产。3月5日，以1英镑的象征性价格卖给荷兰 ING集团。根据此背景回答下列\n问题。\n\n【问题】可能引起操作风险的原因是()。","options":["工作人员误操作","不完善内部流程","信息技术系统缺陷","外部事件"],"answer":"ABCD","explain":"操作风险的分类方法:①根据定义将其划分为由人员、系统、流程和外部事件所引发四类风险；②根据损失事件类型将其划分为七种表现形式:内部欺诈，外部欺诈，就业制度和工作场所安全，客户、产品和业务活动，实物资产的损坏，营业中断和信息技术系统瘫痪，执行、交割和流程管理。"},{"id":"n-law3-118","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】1994年下半年起，新加坡巴林期货有限公司的总经理兼首席交易员里森在日本东京市\n场上做了一种特别繁琐，期望值很高，风险也极大的衍生金融商品交易一日本日经指数期货，\n55\n\n\n结果日经指数从 1995年1月一路下滑，使里森所持的多头头寸遭受重创，为了反败为胜，\n他以赌徒心态来押宝日经225指数上涨，继续从伦敦调入户资买入大量期货合约，最终惨败。\n1995年2月26日，英国银行业的泰斗，在世界 1000 家大银行中按核心资本排名第 489位，\n有着233年历史巴林银行因进行巨额金融期货投机交易，造成9.16亿英镑巨额亏损，\n被追宣布破产。3月5日，以1英镑的象征性价格卖给荷兰 ING集团。根据此背景回答下列\n问题。\n\n【问题】以下选项中，属于操作风险管理方法前有()。","options":["内部控制","数据治理和管理","业务持续计划","保险"],"answer":"ABCD","explain":"操作风险管理方法:内部控制、保险、业务外包、IT技术应用、数据治理和管理、业务持续计划。"},{"id":"n-law3-119","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】1994年下半年起，新加坡巴林期货有限公司的总经理兼首席交易员里森在日本东京市\n场上做了一种特别繁琐，期望值很高，风险也极大的衍生金融商品交易一日本日经指数期货，\n55\n\n\n结果日经指数从 1995年1月一路下滑，使里森所持的多头头寸遭受重创，为了反败为胜，\n他以赌徒心态来押宝日经225指数上涨，继续从伦敦调入户资买入大量期货合约，最终惨败。\n1995年2月26日，英国银行业的泰斗，在世界 1000 家大银行中按核心资本排名第 489位，\n有着233年历史巴林银行因进行巨额金融期货投机交易，造成9.16亿英镑巨额亏损，\n被追宣布破产。3月5日，以1英镑的象征性价格卖给荷兰 ING集团。根据此背景回答下列\n问题。\n\n【问题】操作风险限额指标包括()。","options":["监管处罚率","操作风险损失率","净稳定资金比率","核心负债依存度"],"answer":"AB","explain":"操作风险限额指标包括:操作风险损失率、监管处罚率、千人重大操作风险事发率、千人发案率、案件风险率、操作风险事件败诉率、信息系统主要业务时段可用率、操作风险经济资本率等。CD 属于流动性风险限额指标，故排除。本题选 AB。"}]},{"id":"n-bas3","subject":"basics","name":"11月300题 · 金融卷三","stats":{"单选":40,"多选":40,"判断":30,"案例":10},"questions":[{"id":"n-bas3-0","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"2013年5月，甲合伙人变更为乙公司(普通合伙人)和丙公司(有限合伙人)，同时，顾某和丁某退休。后因甲迟迟不归还800 万元借款及利息，潘某提起诉讼。下列说法中错误是()。","options":["顾某作为甲公司普通合伙人，对该项债务承担无限责任","丁某作为原有限合伙人己经退休，不再承担该项债务责任","乙公司作为甲公司的新普通合伙人，应当对该项债务承担无限责任","丙公司作为甲公司新有限合伙人，对入伙前的该项债务以其认缴出资额为限承担责任"],"answer":"B","explain":"普通合伙企业所有出资人均须对合伙企业的债务承担无限连带责任:而有限合伙企业中有限合伙人对企业债务承担有限责任，普通合伙人对合伙企业债务承担无限责任或无限连带责任。"},{"id":"n-bas3-1","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"按照《证券公司风险控制指标计算标准规定》，证券公司自营权益类证券及其衍生品","options":["100%合计额不传超过净资术街()A","500%","50%","80%"],"answer":"A","explain":"自营权益类证券及其衍生品合计额不得超过净资本100%。"},{"id":"n-bas3-2","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《公司法》，下列关于有限责任公司董事会职权的说法，错误的是()。","options":["制定公司的基本管理制度","决定公司内部管理机构的设置","对发行公司债券作出决议","召集股东会会议，并向股东会报告工作"],"answer":"C","explain":"A选项正确:“制定公司的基本管理制度”属于董事会职权。B选项正确:“决定公司内部管理机构设置”属于董事会职权。C选项错误:“对发行公司债券作出决议”是股东会法定职权，而非董事会。董事会只能“制定公司增加或者减少注册资本以及发行公司债券的方案”，决策权在股东会。D 选项正确:“召集股东会会议，并向股东会报告工作”是董事会的基础职权。故本题答案选C。"},{"id":"n-bas3-3","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《融资融券交易风险揭示书必备条款》，融资融券交易不同于普通证券交易所特有风险是()。信XS","options":["市场风险","系统风险","政策风险","投资风险放大风险"],"answer":"D","explain":"根据融资融券交易特有风险的规定(结合《融资融券交易风险揭示书必备条款》内容):融资融券交易与普通证券交易相比，除了普通交易共有的市场风险、系统风险、政策风险等之外，其特有的、最核心的风险是杠杆交易带来的投资风险放大风险。这是因为融资融券引入了“借入资金或证券”机制，放大了投资收益和亏损波动。"},{"id":"n-bas3-4","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《刑法》，下列关于欺诈发行证券罪的说法，错误是()。","options":["一般只对其直接负责的主管人员和其他直接责任人员处以罚金","并处或者单处非法募集资金金额 20%以上1倍以下罚金","对其直接负责的主管人员和其他负责人员处以5年以下有期徒刑或者拘役","单位犯罪的，对单位判处罚金"],"answer":"A","explain":"根据《刑法》的有关规定:①控股股东、实际控制人组织、指使实施欺诈发行证券，处5年以下有期徒刑或者拘役，并处或者单处非法募集资金金额 20%以上1倍以下罚金:数额特别巨大、后果特别严重或者有其他特别严重情节的，处5年以上有期徒刑，并处非法募集资金金额20%以上1倍以下罚金。②单位犯欺诈发行证券罪的，对单位判处非法募集资金金额20%以上1倍以下罚金，并对其直接负责的主管人员和其他直接责任人员，依照《刑法》第一百六十条第一款的规定处罚。【补充说明】《刑法》第一百六十条规定，在发行文件中隐瞒重要事实或者编造重大虚假内容，数额巨大、后果严重或者有其他严重情节，处5年以下有期徒刑或者拘役，并处或者单处罚金:数额特别巨大、后果特别严重或者有其他特别严重情节的，处5年以上有期徒刑，并处罚金。故本题“只对其直接负责主管人员和其他直接责任人员处以罚金”说法错误，对单位、控股股东、实际控制人组织均要处以罚金。"},{"id":"n-bas3-5","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券法》，下列关于证券发行，，交易活动当事人说法，错误的是()。","options":["应当遵守诚实信用的原则","应当遵守自愿原则","具有平等的法律地位","应当遵守无偿原则"],"answer":"D","explain":"证券发行、交易活动的当事人具有平等的法律地位，应当遵守自愿、有偿、诚实信用的原则。"},{"id":"n-bas3-6","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券法》，下列关于证券交易场所的说法，错误是()。","options":["非公开发行的证券，可以在按照国务院规定设立的区域性股权市场转让","非公开发行的证券，可以在证券交易所、国务院批准的其他全国性证券交易场所转让","公开发行的证券，应当在依法设立的证券交易所上市交易或者在国务院批准的其他全国性证券交易场所交易","公开发行的证券，应当在依法设立的证券交易所上市交易或者在国务院批准的其他地方性证券交易场所交易"],"answer":"D","explain":"根据证券交易场所的规定:A选项正确:“非公开发行证券，可以在按照国务院规定设立的区域性股权市场转让。”B选项正确:“非公开发行证券，可以在证券交易所、国务院批准的其他全国性证券交易场所转让。”C选项正确:“公开发行的证券，应当在依法设立的证券交易所上市交易或者在国务院批准的其他全国性证券交易场所交易。”D选项错误:公开发行的证券，其交易场所是“证券交易所”或“全国性证券交易场所”，而非“地方性证券交易场所”。区域性股权市场是地方性的，主要服务非公开发行的证券。"},{"id":"n-bas3-7","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券法》，下列属于证券公司及其从业人员从事的损害客户利益行为是()。","options":["根据客户的委托为其买卖证券","为牟取佣金收入，诱使客户进行不必要附证券买卖","在规定的时间内向客户提供交易的确认文件","根据客户的真实意思标识，维护客户利益"],"answer":"B","explain":"禁止证券公司及其从业人员从事下列损害客户利益的行为:(1) 违背客户的委托为其买卖证券；(2)不在规定时间内向客户提供交易的确认文件；(3) 未经客户的委托，擅自为客户买卖证券，或者假借客户的名义买卖证券；(4)为牟取佣金收入，诱使客户进行不必要的证券买卖；(5) 其他违背客户真实意思表示，损害客户利益行为。违反上述规定给客户造成损失前，应当依法承担赔偿责任。"},{"id":"n-bas3-8","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券法》及《证券、期货投资咨询管理暂行办法》，下列做法中，不属于证券投资咨询人员禁止性行为是()。","options":["向客户承诺保障本金安全及最低收益","采用差别佣金方式收取服务费用","与客户约定分担投资损失","代理客户买卖股票"],"answer":"B","explain":"证券、期货投资咨询机构及其投资咨询人员，不得从事下列活动:(一)代理投资人从事证券、期货买卖；(二)向投资人承诺证券、期货投资收益；(三)与投资人约定分享投资收益或者分担投资损失:(四)为自己买卖股票及具有股票性质、功能的证券以及期货；(五)利用咨询服务与他人合谋操纵市场或者进行内幕交易；(六)法律、法规、规章所禁止旳其他证券、期货欺诈行为。不包括B选项，故本题选B。。"},{"id":"n-bas3-9","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司和证券投资基金管理公司合规管理办法》，下列关于证券公司合规负责人和合规管理人员独立性原则的说法，错误是()。","options":["合规负责人有权要求根据履职需要列席董事会","合规负责人工作称职的，其年度新酬收入总额在公司高级管理人员年度新酬收入总额中的排名不应当低于中位数","证券公司对合规部门考核时，不得将考核结果与业务部门经营业务直接挂钩","合规负责人直接向经营层负责，由经营层考核"],"answer":"D","explain":"根据合规负责人独立性原则的规定:A选项正确:教材明确:“合规负责人有权要求根据履职需要列席董事会。”B选项正确:教材明确:“合规负责人工作称职的，其年度薪酬收入总额在公司高级管理人员年度薪酬收入总额中的排名不应当低于中位数。”C选项正确:教材明确:“证券公司对合规部门考核时，不得将考核结果与业务部门的经营业务直接挂钩。”D选项错误:教材明确:“合规负责人是高级管理人员，直接向董事会负责。”其他人员不得干预合规负责人依法履行职责。"},{"id":"n-bas3-10","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司监督管理条例》，下列关于证券公司信息披露要求，正确的是()。","options":["证券公司向社会公开披露的信息中无须包含或有负债情况","证券公司向社会公开披露的信息中无须包含参股及控股情况","证券公司向社会公开披露的信息中应当包括经营管理状况","证券公司向社会公开披露的信息中无须包含其高级管理人员薪酬信息"],"answer":"C","explain":"根据《证券公司监督管理条例》第六十六条的规定，证券公司应当依法向社会公开披露其基本情况、参股及控股情况、负债及或有负债情况、经营管理状况、财务收支状况、高级管理人员薪酬和其他有关信息。具体办法由国务院证券监督管理机构制定。"},{"id":"n-bas3-11","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司流动性风险管理指引》，证券公司应至少()对流动性风险限额进行一次评估，必要时进行调整。","options":["每月","每半年","每年","每季度"],"answer":"C","explain":"证券公司应至少每年对流动性风险限额进行一次评估，必要时进行调整。"},{"id":"n-bas3-12","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司全面风险管理规范》，下列关于证券公司风险评估、监测、应对和报告的做法，正确的是()。","options":["建立逐日盯市等机制，准确计算、静态监控关键风险指标情况","仅采取定量的方法，对识别风险进行分析计量并进行等级评价或量化排序","根据风险评估和预警结果，选择与公司风险偏好相适应的应对策略，并始终保持不变","与子公司之间建立畅通的风险信息沟通机制"],"answer":"D","explain":"风险评估监测应该是动态的；分析方法应采用定性和定量相结合；应对策略应根据风险评估结果和风险偏好制定，并适时调整。与子公司建立畅通的风险信息沟通机制是全面风险管理的基本要求。"},{"id":"n-bas3-13","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据《证券行业文化建设十要素》，下列关于证券行业文化建设的说法，错误是()。","options":["声誉约束是文化建设的有力保障","利益最大化是证券公司实现稳健经营的基础","长效激励是落实文化建设的重要途径","落实责任担当是文化建设的重要抓手"],"answer":"B","explain":"根据行业文化建设描述，强调“稳健审慎”、“依法合规”等，而非“利益最大化”。证券行业文化建设强调稳健经营，而非追求短期利益最大化。"},{"id":"n-bas3-14","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"根据资产支持证券信息披露的规定，管理人、托管人应当在每年()之前向资产支持证券合格投资者披露上年度资产管理报告、年度托管报告。","options":["3月31日","1月31日","6月30日","4月30日"],"answer":"D","explain":"管理人、托管人应当在每年4月30日之前向资产支持证券合格投资者披露上年度资产管理报告、年度托管报告。"},{"id":"n-bas3-15","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"股份有限公司修改公司章程，必须经出席股东大会会议的股东所持表决权()以上通","options":["三分之二","二分之一","三分之一","四分之三"],"answer":"A","explain":"(1) 公司合并或分立，应当由公司的股东(大)会作出决议。有限责任公司，必须经代表2/3以上表决权的股东通过。股份有限公司，必须经出席会议的股东所持表决权2/3以上通过。(2)股份有限公司修改公司章程，必须经出席股东大会会议股东所持表决权2/3以上通过。"},{"id":"n-bas3-16","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"设立股份有限公司，公司章程须经()通过。","options":["全体发起人、认股人所持表决权2/3以上","发起人","出席创立大会的认股人所持有表决权2/3以上","全体认股人所持表决权过半数"],"answer":"B","explain":"密包过本题考查旳是股份有限公司设立条件。股份有限公司，应当具备下列条件:(1) 发起人符合法定人数。(2)股份有限公司注册资本为在公司登记机关登记己发行股份的股本总额。(3)股份发行、筹办事项符合法律规定。(4)设立股份有限公司，应当由发起人共同制定公司章程。(5) 有公司名称，建立符合股份有限公司要求的组织机构。(6) 有公司住所。"},{"id":"n-bas3-17","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"王某是证券公司营业部信息技术负责人，下列关于其从事工作说法，正确是()。","options":["王某可以兼任营业部合规员","王某可以兼任营业部行政管理工作","王某可以从事客户营销开拓工作","王某可以从事客户账户开户工作"],"answer":"B","explain":"根据《关于加强证券经纪业务管理的规定》，从事技术、风险监控、合规管理的人员不得从事销售、客户账户及客户资金存管等业务活动。故“王某可以兼任营业部合规员、从事客户营销开拓工作、客户账户开户工作”表述错误，均不可以。"},{"id":"n-bas3-18","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列不属于股份有限公司公司章程应载明事项的是()。","options":["股东姓名或名称","公司的通知和公告办法","公司解散事由与清算办法","公司注册资本、公司利润分配办法"],"answer":"A","explain":"股份有限公司章程应当载明下列事项:公司名称和住所:公司经营范围；公司设立方式:公可注册资本、已发行的股份数和设立时发行的股份数，面额股的每股金额；每一类别股的股份数及其权利和义务(发行类别股)；发起人姓名或者名称、认购的股份数、出资方式；董事会组成、职权和议事规则；公司法定代表人的产生、变更办法；监事会组成、职权和议事规则；公司利润分配办法；公司的解散事由与清算办法；公司的通知和公告办法；股东会认为需要规定的其他事项。A选项属于有限责任公司章程应载明事项，故本题选A。"},{"id":"n-bas3-19","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于公司章程说法，错误是()。","options":["公司的经营范围由公司章程规定，并依法登记","公司章程只对公司和股东具有约束力","公司可以修改公司章程，改变经营范围，但是应当办理变更登记","设立公司必须依法制定公司章程"],"answer":"B","explain":"(1)公司章程对公司、股东、董事、监事、高级管理人员具有约束力。(2)公司的经营范围由公司章程规定，并依法登记。公司可以修改公司章程，改变经营范围，但是应当办理变更登记。(3)公司的经营范围中属于法律、行政法规规定须经批准的项目，应当依法经过批准。"},{"id":"n-bas3-20","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于基金财产债权债务独立性的意义说法，错误是()。","options":["有利于维护基金财产独立性","有利于保护基金管理人的合法权益","有利于保障基金财产安全","有利于基金财产稳定运作，提高基金的运作效率"],"answer":"B","explain":"获取基金财产债权债务独立性，是基金财产独立性必然要求，也是基金财产独立性内涵的应有之义。对证券投资基金活动具有重要的意义，主要体现在:"},{"id":"n-bas3-21","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于净资本计算标准的说法，正确的是()。","options":["净资本=核心净资本+附属净资本","净资本=可用稳定资金/所需稳定资金✕100%","净资本=净资产/各项风险资本准备之和✕100%","净资本=核心净资本/表内外资产总和×100%"],"answer":"A","explain":"净资本=核心净资本+附属净资本(A 正确)；净稳定资金率=可用稳定资金/所需稳定资金✕100%(B错误，应为“净稳定资金率”，而非“净资本”):资本杠杆率=核心净资本/表内外资产总和✕100%(D错误，应为“资本杠杆率”，而非“净资本”):风险覆盖率=净资本/各项风险资本准备之和✕100%(C错误，应为“风险覆盖率”，而非“净资本”)。故本题选 A。"},{"id":"n-bas3-22","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于跨墙人员行为规范及监督管理的说法，错误的是()。","options":["合规部门负责记录跨墙情况，向跨墙人员提示跨墙行为规范","跨墙人员在跨墙期间可以获取与跨墙业务无关的内幕信息","跨墙人员在跨墙期间不应当泄露跨墙后知悉内幕信息","合规部门会同提出跨墙申请的业务部门和跨墙人员所属部门对跨墙人员行为进行监控"],"answer":"B","explain":"跨墙人员在跨墙期间不应泄露或不当使用跨墙后知悉前内幕信息，不应获取与跨墙业务无关的内幕信息。"},{"id":"n-bas3-23","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于上市公司信息披露的说法，错误的是()。","options":["发行人的董事、监事和高级管理人员应当保证发行人及时、公平地披露信息，所披露的信息真实、准确、完整","上市公司监事应当对公司定期报告签署书面确认意见","发行人监事会应当对董事会编制的证券发行文件和定期报告进行审核并提出书面审核意","发行人的董事、高级管理人员应当对证券发行文件和定期报告签署书面确认意见"],"answer":"B","explain":""},{"id":"n-bas3-24","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于证券承销的说法，错误的是()。","options":["证券包销是指证券公司将发行人的证券按照协议全部购入，或者在承销期结束时将售后剩余证券全部自行购入的承销方式","证券代销是指证券公司代发行人发售证券，在承销期结束时，将未售出的证券全部退还给发行人承销方式","证券公司承销证券，应当同发行人签订代销协议","证券公司承销证券，应当先行出售给认购人，而不是为本公司预留"],"answer":"C","explain":"(1) 证券代销，是指证券公司代发行人发售证券，在承销期结束时，将未售出证券全部退还给发行人承销方式(B正确)(2)证券包销，是指证券公司将发行人的证券按照协议全部购入，或者在承销期结束时将售后剩余证券全部自行购入承销方式(A正确)。(3)证券公司承销证券，应当同发行人签订代销或者包销协议(C错误，不一定是代销协议，还可能是包销协议)。(4)证券公司在代销、包销期内，对所代销、包销证券应当保证先行出售给认购人，证券公司不得为本公司预留所代销的证券和预先购入并留存所包销的证券(D 正确)。故本题选C。"},{"id":"n-bas3-25","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于证券公司合规经营基本原则与应遵守的基本要求的说法，错误是()。","options":["证券公司应动态监控客户交易活动","证券公司应划分客户类别和产品服务等级，将适当产品服务提供给适合的客户","证券公司的合规管理需覆盖总部各部门及分支机构，不需覆盖各层级子公司","证券公司的合规管理应贯穿决策、执行、监督、反馈等各环节"],"answer":"C","explain":"证券公司的合规应当覆盖所有业务，各部门、各分支机构、各层级子公司和全体工作人员，贯穿决策、执行、监督、反馈等各个环节。"},{"id":"n-bas3-26","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于证券公司开展股票期权经纪业务应符合条件的说法，错误的是()。","options":["公司最近6个月内未因重大违规行为受到行政处罚","应当指定专门部门、专人开展股票期权经纪业务","分支机构开展股票期权经纪业务应至少有1名具备相应专业能力的业务人员","公司开展股票期权经纪业务应配备3名具备相应专业能力的业务人员"],"answer":"A","explain":"从事股票期权经纪业务试点条件之一是:“公司及其董事、监事、高级管理人员最近1年内来用哑大道让造规行别受到行技姓河安刊事处啊，“继项A中份“9个月”时间长发请设。"},{"id":"n-bas3-27","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于证券公司信息系统安全管理要求说法，错误的是()。","options":["证券公司应定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要","证券公司应当经中国证监会备案后方可为其子公司提供信息技术服务","证券公司应当建立健全信息系统安全监测机制，应当指定专人跟踪监测发现异常情形","证券公司应当建立独立于生产环境的专用开发测试环境，避免风险传导"],"answer":"B","explain":"(1) 证券公司应当结合公司发展战略、市场交易规模等因素定期对重要信息系统开展压力测试和评估分析，确保其容量满足业务开展需要。(2)证券公司可以在安全、合规前提下为子公司提供机房、通信网络及其他信息技术基础设施，并协助开展相关运维工作。不需要经中国证监会备案，B选项错误。(3)证券公司应当建立健全信息系统安全监测机制，设定监测指标并持续监测重要信息系统的运行状况。证券公司应当指定专人跟踪监测发现的异常情形，及时处置并定期开展评估分析。(4)证券公司应当建立独立于生产环境专用开发测试环境，避免风险传导。故本题选B。"},{"id":"n-bas3-28","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列主体可以作为合伙企业普通合伙人前是()。","options":["自然人","国有企业","上市公司","国有独资公司"],"answer":"A","explain":"为保护固有资产和上市公司股东的利益，国有独资公司、国有企业、上市公司不得成为普通合伙人。"},{"id":"n-bas3-29","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"向投资者销售或者提供“荐股软件”，并直接或者间接获取经济利益，属于从事()，应当经中国证监会许可，取得相关业务资格。","options":["证券经纪业务","证券投资咨询业务","证券公司中间介绍业务","代销金融产品业务"],"answer":"B","explain":"(1)“荐股软件”，是指具备下列一项或多项证券投资咨询服务功能的软件产品、软件工具或者终端设备:①提供涉及具体证券投资品种投资分析意见，或者预测具体证券投资品种的价格走势；②提供具体证券投资品种选择建议:③提供具体证券投资品种的买卖时机建议；④提供其他证券投资分析、预测或者建议。(2)向投资者销售或者提供“荐股软件”，并直接或者间接获取经济利益，属于从事证券投资咨询业务，应当经中国证监会许可，符合证券投资咨询业务条件。故本题应该选择“证券投资咨询业务”。"},{"id":"n-bas3-30","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"信息技术系统服务机构未向国务院证券监督管理机构提供相关技术系统资料，或者提供的信息技术系统资料虚假、有重大遗漏的，处()。","options":["1万元以上10万元以下罚款","1万元以上30万元以下罚款","3万元以上10万元以下罚款","3万元以上30万元以下罚款"],"answer":"C","explain":"信息技术系统服务机构未按照规定向国务院证券监督管理机构提供相关信息技术系统资料，或者提供的信息技术系统资料虚假、有重大遗漏的，责令改正，处3万元以上10万元以下罚款。对直接负责的主管人员和其他直接责任人员给予警告，并处1万元以上3万元以下罚"},{"id":"n-bas3-31","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"在证券投资基金当事人中，负责运用基金资产进行证券投资机构是()。","options":["基金托管人","基金发起人","基金持有人","基金管理人"],"answer":"D","explain":"基金管理人是指按照法律、法规的规定和基金合同的约定，为基金份额持有人利益，对基金财产进行管理及运作机构。"},{"id":"n-bas3-32","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券发行、交易活动的当事人具有平等的法律地位，应当遵守()前原则。","options":["自愿、有偿、诚实信用","义务、无偿、各负其责","义务、有偿、诚实信用","自愿、有偿、各负其责"],"answer":"A","explain":"证券发行、交易活动的当事人具有平等的法律地位，应当遵守自愿、有偿、诚实信用的原则。"},{"id":"n-bas3-33","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券公司发现客户的交易与洗钱相关，应当向规定的机构提交可疑交易报告，该机构是()。","options":["证券公司注册地证监局","客户开户银行","相关侦査机关","中国反洗钱监测分析中心"],"answer":"D","explain":"证券公司发现或者有合理理由怀疑客户、客户的资金或者其他资产、客户的交易或者试图进行的交易与洗钱、恐怖融资等犯罪活动相关的，不论所涉资金金额或者资产价值大小，应当向中国反洗钱监测分析中心提交可疑交易报告。"},{"id":"n-bas3-34","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券公司开展柜台交易业务中，需要向投资者收取履约保证金的，保证金应存入在()金融机构开立的专门账户。","options":["证券公司与投资者双方约定的","证券公司指定","投资者指定","中国投资者保护基金有限责任公司指定"],"answer":"A","explain":"证券公司与投资者约定抵押、质押等财产担保的，应当依法办理担保设定手续:向投资者收取展约保证金的，应当在双方约定的金融机构开立专门账户存放，不得违约动用。"},{"id":"n-bas3-35","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券公司另类子公司的合规负责人应由()考核和管理。","options":["证券公司合规负责人","另类子公司董事会","证券公司经营管理层","另类子公司经营管理层"],"answer":"A","explain":"证券公司应当选派人员作为另类子公司高级管理人员负责合规及风险管理工作，并由证券公司合规及风险管理负责人考核和管理，且不得兼任与其合规或风险管理职责相冲突的职务。故本题选 A。"},{"id":"n-bas3-36","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券公司停业、解散或破产的，应当经()批准，并按照有关规定安置客户，处理未了结的业务。","options":["证券交易所","证券业协会","国务院证券监督管理机构","证券登记结算机构"],"answer":"C","explain":"证券公司停业、解散或者破产，国务院证券监督管理机构应当对停业、解散、破产申请进行审查，并在自受理之日起30个工作肆作出批准或不予批准的书面决定。证券公司应按照有关规定安置客户、处理未了结业务。"},{"id":"n-bas3-37","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券公司应当()负责与客户进行沟通，处理客户投诉等事宜。","options":["设立专职部门或岗位","由营业部营销人员","设立营业部员工轮岗机制","由公司合规部"],"answer":"A","explain":"证券公司应当设专职部门或者岗位(A正确，BCD错误)，负责与客户进行沟通，处理客户的投诉等事宜。故本题选 A。"},{"id":"n-bas3-38","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券公司应当按照()原则，建立健全风险管理与内部控制制度，防范和控制风险。","options":["自主经营","审慎经营","独立经营","诚信经营"],"answer":"B","explain":"证券公司应当按照审慎经营的原则，建立健全风险管理与内部控制制度，防范和控制风险。"},{"id":"n-bas3-39","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"证券公司中应对违反职责范围内的内部控制要求所导致风险和损失承担首要责任的是()。","options":["合规部门","经理层","董事会","直接从事业务经营活动的相关人员"],"answer":"D","explain":"(1)直接从事业务经营活动业务部门和分支机构的相关人员应对违反职责范围内内部控制导致风险和损失承担首要责任(D正确，排除 ABC 项)；(2)业务部门负责人对其业务范围内的具体作业程序和风险控制措施进行自我检查和评价；(3)相关业务人员应对违反职责范围内的内部控制导致的风险和损失承担首要责任；(4) 相关业务人员有义务向证券公司报告内部控制的缺陷并及时加以纠正；(5) 相关业务人员要接受证券公司上级管理部门和监督检查部门的业务检查和指导。故本题选D项。"},{"id":"n-bas3-40","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"财务顾问及其财务顾问主办人出现下列()情形之一的，中国证监会对其采取监管谈话，出具警示函，责令改正等监管措施。","options":["内部控制机制和管理制度、尽职调查制度以及相关业务规则存在重大缺陷或者未得到有效","未按照相关规定发表专业意见","未依法履行持续督导义务前","在相关并购重组信息未依法公开前，建议他人买卖该公司证券"],"answer":"ABC","explain":"财务顾问及其财务顾问主办人出现下列情形之一的，中国还监会对其采取监管谈话，出具警示函，责令改正等监管措施:9951"},{"id":"n-bas3-41","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《反洗钱法》，下列属于反洗钱罪上游犯罪的有()。","options":["毒品犯罪","单位犯罪","破坏金融管理秩序犯罪","贪污贿赂犯罪"],"answer":"ACD","explain":"反洗钱，是指为了预防通过各种方式掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪等犯罪所得及其收益的来源和性质的洗钱活动，依照本法规定采取相关措施的行为。"},{"id":"n-bas3-42","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《公司法》有关规定，下列关于股份有限公司设立的说法，正确有()。","options":["股份有限公司的设立可以采取发起设立或者募集设立方式","股份有限公司初始设立时可以向战略投资者募集股份，但不可以向社会公开募集","设立股份有限公司，应当由发起人共同制定公司章程","发起人认购股份有限公司设立时的股份最低不应低手股份总数的 50%"],"answer":"AC","explain":"A 选项正确:股份有限公司的设立，可以采取发起设立或者募集设立的方式。B选项错误:募集设立时，公司可以向社会公开募集股份。因此“不可以向社会公开募集”说法错误。C选项正确:设立股份有限公司、应当由发起人共同制定公司章程。D选项错误:以募集设立方式设立股份有限公司，发起人认购的股份不得少于公司股份总数35%。而非“50%”。"},{"id":"n-bas3-43","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《关于规范金融机构资产管理业务的指导意见》，下列关于资产管理业务运用人工智能技术的说法，正确的有()。","options":["金融机构不得借助人工智能业务夸大宜传资产管理产品或者误导投资者","非金融机构不得借助智能投资顾问超范围经营","金融机构运用人工智能技术开展投资顾问业务应当取得投资顾问资质","金融机构未出现违规但因管理不当造成投资者损失的，可不承担赔偿责任"],"answer":"ABC","explain":"运用人工智能技术开展投资顾问业务应当取得投资顾问资质，非金融机构不得借助智能投资顾问超范围经营或者变相开展资产管理业务。B、C正确。金融机构运用人工智能技术开展资产管理业务应当严格遵守意见有关投资者适当性、投资范围、信息披露、风险隔离等一般性规定，不得借助人工智能业务夸大宣传资产管理产品或者误导投资者。A正确。金融机构因违法违规或者管理不当造成投资者损失的，应当依法承担损害赔偿责任。D错误。故本题答案选 ABC。"},{"id":"n-bas3-44","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《区域性股权市场自律管理与服务规范(试行)》，下列关于证券公司开展区域性股权市场业务说法，正确的有()。","options":["证券公司及其从业人员应当配合中国证券业协会对落实该规范及相关自律要求情况的监督","证券公司及其从业人员违反该规范，中国证券业协会将视情节轻重采取相关自律惩戒措施","证拳公司及其从业人员存在违反法律、法规行为的。将移交中国证监会及其派出机构或其他有权机关依法查处","证券公司及其从业人员应当勤勉尽责，严格遵守执业规范和职业道德，按规定和约定履行"],"answer":"ABCD","explain":"证券公司参与区域性股权市场的自律管理要求如下:(1) 证券公司作为运营机构股东或者在区域性股权市场开展相关业务，应当遵守证券行业监管和自律规则以及区域性股权市场相关管理规定。(2) 区域性股权市场运营机构、证券公司及其从业人员应当配合中国证券业协会对落实《规范》及相关自律要求情况监督检查(A正确)。(3)区域性股权市场运营机构、证券公司及其从业人员违反《规范》，中国证券业协会将视情节轻重采取相关自律惩戒措施(B正确)；存在违反法律、法规行为的，将移交中国证监会及其派出机构或其他有权机关依法查处(C正确)。(4) 证券公司及其从业人员应当勤勉尽责，严格遵守执业规范和职业道德，按规定和约定履行义务(D正确)。故本题选 ABCD项。"},{"id":"n-bas3-45","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《上市公司并购重组财务顾问业务管理办法》，下列关于财务顾问主办人执业行为规范说法，正确的有()。","options":["财务顾问应当建立健全内部检查制度，确保财务顾问主办人切实履行持续督导责任，按时向中国证监会派出机构提交持续督导工作的情况报告","财务顾问及其财务顾问主办人应当严格履行保密责任，在保密前提下可以买卖相关上市公司的证券","财务顾问的法定代表人或者其授权代表人、部门负责人、内部核查机构负责人、财务顾问主办人和项目协办人应当在财务顾问专业意见上签名，并加盖财务顾问单位公章","财务顾问应当按照中国证监会的要求，配合提供上市公司并购重组相关内幕信息知情人买卖、持有相关上市公司证券的文件"],"answer":"ACD","explain":"(1) 财务顾问应当建立健全内部检查制度，确保财务顾问主办人切实履行持续督导责任，按时向中国证监会派出机构提交持续督导工作的情况报告(A正确)；(2)财务顾问及其财务顾问主办人应当严格履行保密责任，不得利用职务之便买卖相关上市公司的证券或者牟取其他不当利益(B错误，应为“不得买卖”，而非“可以买卖”)；(3)财务顾问应当按照中国证监会的要求，配合提供上市公司并购重组相关内幕信息知情人买卖、持有相关上市公司证券前文件(D 正确)；(4) 财务顾问的法定代表人或者其授权代表人、部门负责人、内部核查机构负责人、财务顾问主办人和项目协办人应当在财务顾问专业意见上签名，并加盖财务顾问单位公章 (C正确)。故本题选 ACD。"},{"id":"n-bas3-46","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《私募投资基金监督管理暂行办法》，下列关于私募基金募集完毕办理备案手续时需报送的信息，正确的有()。","options":["委托托管机构托管基金财产的，应当报送托管协议","基金合同、公司章程或者合伙协议以及基金业协会规定的其他信息","主要投资方向及根据主要投资方向注明的基金类别","资金募集过程中己向投资者提供基金招募说明书的，可以不报送基金招募说明书"],"answer":"ABC","explain":"根据《证券投资基金法》《私募投资基金监督管理暂行办法》《私募投资基金募集行为管理办法》等法律、部门规章和行业自律规则的规定，非公开募集基金募集完毕后规定时间内，基金管理人应当向中国基金业协会备案，报送以下基本信息:主要投资方向及根据主要投资方向注明基金类别(C正确)；基金合同、公司章程或者合伙协议以及中国基金业协会规定的其他信息(B正确)。此外，资金募集过程中向投资者提供基金招募说明书的，应当报送基金招募说明书(D错误)。以公司、合伙企业等形式设立的私募基金，还应当报送工商登记和营业执照正副本复印件:采取委托管理方式的，应当报送委托管理协议。委托托管机构托管基金财产的，还应当报送托管协议(A正确)。故本题选 ABC。"},{"id":"n-bas3-47","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》，设立证券公司需要符合的条件有()。","options":["有合格前经营场所、业务设施和信息技术系统","有完善风险管理和内部控制制度","董事、监事、高级管理人员、从业人员符合《证券法》规定条件","有符合《证券法》规定的公司注册资本"],"answer":"ABCD","explain":"根据《证券法》第一百一十八条的规定，设立证券公司，应当具备下列条件，并经国务院证券监督管理机构批准:(1)有符合法律、行政法规规定的公司章程；(2)主要股东及公司的实际控制人具有良好的财务状况和诚信记录，最近三年无重大违法违规记录；(3)有符合本法规定的公司注册资本(D正确)；(4)董事、监事、高级管理人员、从业人员符合本法规定的条件(C正确)；(5)有完善的风险管理与内部控制制度 (B正确)；(6)有合格经营场所、业务设施和信息技术系统(A 正确)；(7)法律、行政法规和经国务院批准的国务院证券监督管理机构规定的其他条件。在上述规定的基础上，《证券公司监督管理条例》对有关内容进一步细化，作了更为具体的规定。故本题选 ABCD。"},{"id":"n-bas3-48","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》，下列关于某公司股票代销的说法，正确的有()。","options":["代销期限届满，向投资者出售的股票数量占拟公开发行股票数量50%，为发行失败","代销期限届满，向投资者出售的股票数量占拟公开发行股票数量80%，为发行失败","股票发行失败，发行人应当按照发行价并加算银行同期存款利息返还股票认购人","股票发行失败，发行人应当按照发行价并加算银行同期货款利息返还股票认购人"],"answer":"AC","explain":"根据《证券法》，股票发行采用代销方式，代销期限届满，向投资者出售的股票数量未达到拟公开发行股票数量百分之七十的，为发行失败。发行人应当按照发行价并加算银行同期存款利息返还股票认购人。选项A50%低于 70%，属于发行失败:选项B前80%高于70%，属于发行成功。选项D应为存款利息。"},{"id":"n-bas3-49","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》，下列属于证券交易内幕信息有()。","options":["甲上市公司发生重大债务和未能清偿到期重大债务的违约情况，投资者尚未得知该情况","乙上市公司的实际控制人及其控制其他企业从事与公司相同或者相似业务情况发生较大变化，投资者尚未得知该信息","丙上市公司分配股利、增资的计划及公司股权结构的重要变化，投资者尚未得知该信息","证券交易活动中，涉及发行人经营、财务或者对该发行人证券的市场价格有重大影响尚未公开信息"],"answer":"ABCD","explain":"根据“内幕信息”定义与范围:A选项正确:教材明确将“公司发生重大债务和未能清偿到期重大债务的违约情况”列为内幕信息(重大事件)。B选项正确:教材明确将“持有公司5%以上股份的股东或者实际控制人，其持有股份或者控制公司情况发生较大变化”列为内幕信息。C选项正确:教材明确将“公司分配股利、增资计划，公司股权结构重要变化”列为内幕信息。D 选项正确:这是教材对内幕信息最基础定义:“证券交易活动中，涉及发行人经营、财务或者对该发行人证券的市场价格有重大影响的尚未公开的信息。”"},{"id":"n-bas3-50","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》规定，擅自改变公开发行证券所募集资金的用途的，应当承担法律责任的行为主体包括()。","options":["发行人","直接负责的主管人员","上市公司股东大会","上市公司董事会"],"answer":"AB","explain":"(1)根据《证券法》第一百八十五条规定，发行人违反本法相关规定擅自改变公开发行证券所募集资金的用途，责令改正，处以50万元以上500 万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处以 10万元以上100万元以下的罚款。(2) 发行人的控股股东、实际控制人从事或者组织、指使从事前款违法行为的，给予警告，并处以 50 万元以上500 万元以下的罚款:对直接负责主管人员和其他直接责任人员，处以10万元以上100万元以下的罚款。"},{"id":"n-bas3-51","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司风险控制指标管理办法》，下列关于证券公司编制风险控制指标监管报表相关要求的说法，错误的有()。","options":["证券公司的净资本等风险控制指标达到预警标准，应在该情形发生之日起1个工作日内向中国证监会及其派出机构报告","证券公司应当在每月结束之日起7个工作日肉，向中国证监会及其派出机构报送月度风险控制指标监管报表","净资本指标与上月相比发生10%以上不利变化时，证券公司应当在5个工作日内向公司全体董事报告","净资本指标不符合规定标准时，10个工作日内向公司全体股东报告"],"answer":"AC","explain":"净资本指标与上月相比发生20%以上不利变化或不符合规定标准时，证券公司应当在5个工作日内向公司全体董事报告，10个工作日内向公司全体股东报告(C错误，D正确)。证券公司应当在每月结束之日起7个工作日内，向中国证监会及其派出机构报送月度风险控制指标监管报表(B正确)。证券公司的净资本等风险控制指标达到预警标准或者不符合规定标准的，应当分别在该情形发生之日起 3个、1个工作日内，向中国证监会及其派出机构报告，说明基本情况、问题成因以及解决问题的具体措施和期限(A错误)。故本题选AC。"},{"id":"n-bas3-52","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司柜台交易业务规范》、《证券公司柜台市场管理办法(试行)》等规定，下列说法正确的有()。","options":["中国证券业协会委托中证资本市场发展监测中心有限责任公司建立机构间私募产品报价与服务系统，由该报价系统对证券公司柜台交易活动进行自律管理和监控","证券公司应于每季度结束后7个工作日内按照要求向中国证券业协会报送当期的柜台交易","证券公司应当通过与机构间私募产品报价与服务系统联网方式实现业务信息的互联互通，信息范围包括但不限于自身产品基本情况、交易信息和登记结算信息等","证券公司进行柜台交易，应当报中国证券业协会备案，其柜台交易管理制度和实施方案应当通过中国证券业协会组织的专业评价"],"answer":"CD","explain":"(1) 中国证券业协会对证券公司柜台交易活动进行自律管理和日常监控。同时，中国证券业协会委托中证机构间报价系统股份有限公司建立机构间私募产品报价与服务系统，为柜台市场提供互联互通服务。(2) 证券公司进行柜台交易，应当报中国证券业协会备案，其柜台交易管理制度和实施方案应当通过中国证券业协会组织的专业评价。(3) 证券公司应于每月结束后5个工作日内按要求向中国证券业协会报送柜台交易月度报表；每年结束后规定时间报送柜台市场业务年度报告，内容包括但不限于:柜台市场业务总体情况、交易、登记结算、投资者适当性管理、风险及合规管理等。(4) 证券公司应当通过与报价系统联网的方式实现业务信息的互联互通，信息范围包括但不限于私募产品基本情况、交易信息和登记结算信息等。"},{"id":"n-bas3-53","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司监督管理条例》，以下说法正确的有()。","options":["从事证券经纪业务证券公司应当将客户的交易结算资金存放在指定商业银行","指定商业银行应当保证客户能够随时查询客户交易结算资金的余额变动情况","客户交易结算资金的存取，应当通过指定商业银行办理","从事证券资产管理业务证券公司应当将客户的委托资产交由指定商业银行等资产托管机构托管"],"answer":"ABCD","explain":"根据《证券公司监督管理条例》的规定，证券公司从事证券经纪业务，其客户的交易结算资金应当存放在指定商业银行(A项正确)；客户交易结算资金的存取应当通过指定商业银行办理(C项正确)，指定商业银行应当保证客户能够随时查询客户交易结算资金的余额及变动情况(B项正确):证券公司从事证券资产管理业务，应当将客户的委托资产交指定商业银行或者国务院证券监督管理机构认可的其他资产托管机构托管(D 项正确)。故本题选ABCD。"},{"id":"n-bas3-54","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司监督管理条例》，证券公司从事证券自营业务违反规定的，可以采取的处罚措施包括()。","options":["没收违法所得","给予警告","拘役","贡令改正"],"answer":"ABD","explain":"证券公司违反规定从事证券自营业务，责令改正，给予警告，没收违法所得，并处以罚款；情节严重的，可以撤销相关业务许可或责令关闭。拘役属于刑事处罚措施，不在此列。"},{"id":"n-bas3-55","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司内部控制指引》，下列关于证券公司业务部门承担的内控职责的说法，正确有()。","options":["业务部门负责人对其业务范围内的具体作业程序和风险控制措施进行自我检查和评价","相关业务人员应对违反职责范围内的内部控制导致前风险和损失承担首要责任","相关业务人员有义务向证券公司报告内部控制缺陷并及时加以纠正","业务部门仅接受证券公司上级管理部门的业务检查和指导"],"answer":"ABC","explain":"(1)业务部门负责人对其业务范围内的具体作业程序和风险控制措施进行自我检查和评价。(2) 相关业务人员应对违反职责范围内内部控制导致风险和损失承担首要责任。(3) 相关业务人员有义务向证券公司报告内部控制缺陷并及时加以纠正。(4) 相关业务人员要接受证券公司上级管理部门和监督检查部门的业务检查和指导。【补充说明】①董事会负责督促、检查和评价证券公司各项内部控制制度的建立与执行情况，对内部控制的有效性负最终责任；②直接从事业务经营活动的业务部门和分支机构的相关人员应对违反职责范围内的内部控制导致风险和损失承担首要责任。"},{"id":"n-bas3-56","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司声誉风险管理指引》，下列可能引发证券公司声誉风险行为活动有()。","options":["客户投诉及其涉及证券公司的不当言论或行为","新闻媒体的不实报道或网络不实言论","司法性事件及监管调查、处罚","客户资信状况变化"],"answer":"ABC","explain":"证券公司应确定可能影响公司声誉风险来源，全面、系统、持续地收集和识别相关内外部信息，重点关注以下行为活动中可能引发声誉风险驱动因素:1.战略规划或调整、股权结构变动、内部组织机构调整或核心人员变动；2.业务投资活动及产品、服务的设计、提供或推介；3.内部控制设计、执行及系统控制的重大缺陷或重大经营损失事件；4.司法性事件及监管调查、处罚(C 正确)；5.新闻媒体的不实报道或网络不实言论(B正确)；6.股东、关联方或其他利益相关方发生声誉事件传导至证券公司；7.客户投诉及其涉及证券公司的不当言论或行为(A正确)；8.工作人员出现不当言论或行为，违反廉洁规定、职业道德、业务规范、行规行约等相关行为；9.他人仿冒公司名称、商标、网址等侵权或误导公众行为；"},{"id":"n-bas3-57","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券期货业网络和信息安全管理办法》，证券公司构建网络和信息安全防护体系，可采取的安全保障措施有()。","options":["病毒木马防范","打通交易网段和办公网段","用户认证","数据加密"],"answer":"ACD","explain":"根据“安全保障措施”的规定:A选项正确:教材明确包括“病毒木马防范”等安全技术措施。B选项错误:教材明确要求“严格隔离交易网段和办公网段”，而非“打通”。C选项正确:教材明确包括“用户认证”等访问控制措施。D 选项正确:教材明确包括“数据加密”等技术措施。"},{"id":"n-bas3-58","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券投资基金法》，从事公开募集基金的()等基金服务业务机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。","options":["销售、销售支付","份额登记、估值","投资顾问、评价","信息技术系统服务"],"answer":"ABCD","explain":"包根据《证券投资基金法》第九十七条及第一百三十六条的规定，从事公开募集基金的销售、销售支付、份额登记、估值、投资顾问、评价、信息技术系统服务等基金服务业务的机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。"},{"id":"n-bas3-59","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据《证券投资基金法》，下列关于基金财产独立性要求的说法，正确的有()。","options":["基金财产的债权，可以与基金管理人、基金托管人固有财产的债务相抵销","基金管理人、基金托管人因依法解散、被依法撤销或者被依法宣告破产等原因进行清算的，基金财产属于其清算财产","基金管理人、基金托管人不得将基金财产归入其固有财产","非因基金财产本身承担的债务，不得对基金财产强制执行"],"answer":"CD","explain":"A 选项错误:基金财产的债权，不得与基金管理人、基金托管人固有财产的债务相抵销。B选项错误:基金管理人、基金托管人因依法解散、被依法撤销或者被依法宣告破产等原因进行清算的，基金财产不属于其清算财产。C选项正确:基金管理人、基金托管人不得将基金财产归入其固有财产。D选项正确:非因基金财产本身承担的债务，不得对基金财产强制执"},{"id":"n-bas3-60","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"股份有限公司董事不得从事的行为有()。","options":["将公司资金以其个人名义开立账户存储","持有本公司的股份","不经股东大会同意与本公司订立合同或者进行交易","接受他人与公司交易的佣金并将一部分归为己有"],"answer":"ACD","explain":"董事、高级管理人员不得有下列行为:(1) 挪用公司资金；(2)将公司资金以其个人名义或者以其他个人名义开立账户存储；(3)违反公司章程的规定，未经股东会、股东大会或者董事会同意，将公司资金借贷给他人或者以公司财产为他人提供担保；(4)违反公司章程的规定或者未经股东会、股东大会同意，与本公司订立合同或者进行交(5) 未经股东会或者股东大会同意，利用职务便利为自己或者他人谋取属于公司商业机会，自营或者为他人经营与所任职公司同类的业务；(6) 接受他人与公司交易佣金归为己有；(7)擅自披露公司秘密；(8)违反对公司思实义务的其他行为。董事、高级管理人员违反经营义务所得收入应当归公司所有。"},{"id":"n-bas3-61","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"合规负责人是高级管理人员，直接向董事会负责，对本公司及其工作人员经营管理和职业行为的合规性进行()。","options":["审査","检査","监督","审计"],"answer":"ABC","explain":"合规负责人是高级管理人员，直接向董事会负责，对本公司及其工作人员的经营管理和执业行为的合规性进行审查、监督和检查。"},{"id":"n-bas3-62","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"可作为融资买入或融券卖出的标证券，一般是在交易所上市交易并经交易所认可的证券，包括()。","options":["股票","债券","基金","信托产品"],"answer":"ABC","explain":"在交易所上市交易的并经交易所认可的可作为融资买入或融券卖出的证券统称为标的证券，标的证券涵盖四大类证券，主要包括股票、证券投资基金、债券和其他证券。"},{"id":"n-bas3-63","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列对证券业从业人员执业行为准则的描述中，正确的是()。","options":["从业人员在执业过程中应当维护客户和其他相关方的合法利益，诚实守信，勤勉尽责，维护行业声誉","从业人员应依照相应的业务规范和执业标准为客户提供专业服务，了解客户需求、财务状况及风险承受能力，为客户推荐合适的产品或服务，尽量回避讨论所推荐产品或服务存在的相关风险","从业人员应具备从事相关业务活动所需的专业知识和技能，取得相应从业资格","从业人员应保守国家秘密、所在机构的商业秘密、客户的商业秘密及个人隐私"],"answer":"ACD","explain":"《证券法》《证券业从业人员执业行为准则》对证券业从业人员执业行为作出了具体规定:(1) 从业人员应自觉遵守法律、行政法规，接受并配合中国证监会监督与管理，接受并配合证券业协会的自律管理，遵守交易场所有关规则、所在机构的规章制度以及行业公认职业道德和行为准则。(2)从业人员在执业过程中应当维护客户和其他相关方的合法利益，诚实守信，勤勉尽责，维护行业声誉。(3)从业人员应依照相应的业务规范和执业标准为客户提供专业服务，了解客户需求、财务状况及风险承受能力，为客户推荐合适的产品或服务，充分揭示其推荐产品或服务涉及的责任、义务及相关风险，包括但不限于法律风险、政策风险、市场风险等。(4)从业人员应当品行良好，具备从事证券业务所需的专业能力。(5) 从业人员应保守国家秘密、所在机构的商业秘密、客户的商业秘密及个人隐私，对客户服务结束或者离开所在机构后，仍应按照有关规定或合同约定承担上述保密义务。"},{"id":"n-bas3-64","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于法的规范性体现的说法，正确的有()。","options":["体现了人们在违反法定义务后应承担的责任","体现了人们依法应履行的义务","体现了人们在国家意志和权威下的道德观念","体现了人们依法享有的权利"],"answer":"ABD","explain":"法的规范性体现在:(1)规定了人们可以为一定行为或不为一定行为或者人们可以请求他人为或不为一定行为，体现了人们依法享有的权利；(2) 规定了人们应当为一定行为或不得为一定行为，体现了人们依法应履行的义务；(3)规定了人们在应当为而不为或不应当为而为的情况下所产生后果，体现了人们在违反法定义务后应承担的责任。"},{"id":"n-bas3-65","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于合伙企业与公司的区别的说法，错误的有()。","options":["合伙企业财产属于合伙人共有，公司财产独立于股东","合伙人对合伙企业承担无限责任，股东对公司承担有限责任","分公司具有法人独立地位，合伙企业不具有独立的法人地位","合伙企业与公司没有本质的不同"],"answer":"BCD","explain":"合伙企业与公司的区别主要有:一是法律地位不同。公司具有独立的法人主体资格，是企业法人；合伙企业不是法人，是非法人企业。二是财产独立性不同。公司财产独立于股东；合伙企业财产与合伙人仅相对独立，合伙企业的财产属于合伙人共有。三是承担的贡任不同，股东对公司贡任以出资为限，承担有限责任；而合伙企业中，普通合伙人对合伙企业承担无限责任，此外，与公司相比，合伙企业具有高度的人合性，因此合伙企业的加入，退出，运营管理等方面，与公司均有较大不同。"},{"id":"n-bas3-66","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于另类投资业务总体要求说法，正确有()。","options":["另类子公司可以下设实业投资子公司","另类子公司开展业务应当坚持专业化投资原则","证券公司应当对子公司统一实施管控","证券公司应当加强对另类子公司资本约束"],"answer":"BCD","explain":"(1)《管理规范》第二条规定了另类子公司业务范围，即“证券公司另类子公司从事《证券公司证券自营投资品种清单》所列品种以外的金融产品、股权等另类投资业务，应当符合法律法规、监管要求和规范规定。另类子公司不得从事投资业务之外的业务。”(2)证券公司应当清晰划分证券公司与另类子公司及另类子公司与其他子公司之间业务范围，避免利益冲突和利益输送。"},{"id":"n-bas3-67","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于有限合伙企业执行合伙事务的说法，正确的有()。","options":["有限合伙企业由普通合伙人执行合伙事务","有限合伙人不执行合伙事务","有限合伙人不得对外代表有限合伙企业","执行事务合伙人可以要求在合伙协议中明确执行事务报酬及报酬提取方式"],"answer":"ABCD","explain":"有限合伙企业由普通合伙人执行合伙事务。执行事务合伙人可以要求在合伙协议中确定执行事务报酬及报酬提取方式。有限合伙人不执行合伙事务，不得对外代表有限合伙企业。"},{"id":"n-bas3-68","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于证券公司合规管理的说法，错误有()。","options":["经过合规负责人审核的材料，其他相关高级管理人员不需再对其中的内容负责","证券公司首次开展行业己有可借鉴先例的业务不需要进行本公司内新产品新业务评估与决","合规负责人直接向总经理办公会负责","合规负责人发现公司存在合规风险隐患，应依照公司章程及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改"],"answer":"ABC","explain":"(1) 合规负责人是高级管理人员，直接向董事会负责，对本公司及其工作人员经营管理和执业行为的合规性进行审查、监督和检查。证券公司首次开展行业已有可借鉴先例业务仍需要进行本公司内新产品新业务评估与决策。(2) 经过合规负责人审核材料，其他相关高级管理人员应当对申请材料或报告中基本事实和业务数据的真实性、准确性及完整性负责。(3)合规负责人发现公司存在违法违规行为或合规风险隐患，应依照公司章程及时向董事会、经营管理主要负责人报告，提出处理意见，并督促整改:合规负责人应当同时督促公司及时向中国证监会相关派出机构报告。"},{"id":"n-bas3-69","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于证券公司经纪业务保障投资者交易安全与连续的说法，错误的有()。","options":["证券公司应当将投资者的证券和资金与自有财产分别管理，中国结算、投保基金公司监控投资者证券和资金安全保管情况","证券公司为保障投资者信息安全和交易连续性，分支机构均应当提供现场交易服务","证券公司应当根据投资者委托，托管投资者证券和资金，保证投资者资产安全","证券公司应当明确委托指令接收、排序、处理的相关要求，优先保证专业投资者"],"answer":"BD","explain":"根据“证券公司经纪业务保障投资者交易安全与连续”啲规定:A选项正确:教材要求“证券公司应当将投资者的证券和资金与自有财产分别管理”，且“中国结算、投保基金公司监控投资者证券和资金安全保管情况”。B选项错误:教材并未要求“所有”分支机构均提供现场交易服务。C选项正确:教材要求“证券公司应当根据投资者委托，托管投资者证券和资金，保证投资者资产安全”。D选项错误:教材要求“证券公司应当明确委托指令接收、排序、处理的相关要求，优先保障投资者交易的执行及公平对待投资者”，而非优先保证专业投资者。"},{"id":"n-bas3-70","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于资产管理合同须明确约定的或有事项的说法，正确的有()。","options":["延期清算","管理人变更","巨额申赎","延期支付"],"answer":"ABD","explain":"资产管理合同应当对巨额退出、延期支付、延期清算、管理人变更或者托管人变更等或有事项，作出明确约定。"},{"id":"n-bas3-71","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列属于风险控制指标体系前有()。","options":["净资本","净稳定资金率","资本杠杆率","流动性覆盖率"],"answer":"ABCD","explain":"证券公司风险控制指标体系以净资本和流动性为核心，主要包括净资本、风险覆盖率、资本杠杆率、流动性覆盖率、净稳定资金率等。"},{"id":"n-bas3-72","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列属于内幕交易行为有()。","options":["内幕人员利用内幕信息买卖证券","内幕人员利用内幕信息建议他人买卖证券获取","内幕人员向他人透露内幕信息，使他人利用内幕信息进行交易","非内幕人员非法获取内幕信息，并据此买卖证券"],"answer":"ABCD","explain":"证券交易内幕信息知情人和非法获取内幕信息的人，在内幕信息公开前，不得买卖该公司旳证券，或者泄露该信息，或者建议他人买卖该证券。内幕交易行为给投资者造成损失昀，应当依法承担赔偿责任。"},{"id":"n-bas3-73","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列属于全体工作人员的合规管理职责有()。","options":["主动了解、掌握和遵守相关法律、法规和准则","根据公司要求，签署并信守相关合规承诺","在执业过程中充分关注执业行为的合法合规性","在业务开展过程中主动识别和防范业务合规风险"],"answer":"ABCD","explain":"证券公司全体工作人员应当对自身经营活动范围内所有业务事项和执业行为的合规性负责，履行下列合规管理职责:(1)主动了解、掌握和遵守相关法律、法规和准则；(2)积极参加公司安排的合规培训和合规宣导活动；(3) 根据公司要求，签署并信守相关合规承诺；(4) 在执业过程中充分关注执业行为的合法合规性；(5) 在业务开展过程中主动识别和防范业务合规风险。故本题全选。"},{"id":"n-bas3-74","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列属于受法律规范调整的社会关系前有()。","options":["代理关系","继承关系","朋友关系","恋爱关系"],"answer":"AB","explain":"法律规范是法律关系产生前提和基础，任何一种法律关系均以特定的法律规范为依据。没有相应的法律规范，就不会产生相应的法律关系。但并不是所有的社会关系均受到法律规范的调整，有些社会关系，如恋爱关系、朋友关系或社会团体内部成员之间的关系，一般不存在相应的法律规定，不受法律规范调整，因此不产生法律关系，也不存在合法或非法评价。代理关系、继承关系均受《民法典》等法律调整。故本题答案选 AB。"},{"id":"n-bas3-75","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列证券公司从事证券业务净资本不得低于人民币2亿元的情形有()。","options":["证券公司经营经纪业务","证券公司经营证券经纪业务和证券自营业务","证券公司经营证券资产管理业务和证券承销与保荐业务","证券公司经营证券自营和证券资产管理业务"],"answer":"CD","explain":"证券公司经营证券承销与保荐、证券自营、证券资产管理、其他证券业务中两项及两项以上，其净资本不得低于人民币2亿元。"},{"id":"n-bas3-76","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列资产管理产品销售推介行为中，正确的有()。","options":["资管产品名称中不得出现“保本”字样","资产管理合同中不得出现保本保收益内涵的表述","销售材料中不得出现保本保收益内涵表述","资管产品严禁向投资者承诺本金不受损失或承诺最低收益"],"answer":"ABCD","explain":"证券经营机构在销售中不得存在如下行为:(1)资产管理合同及销售材料中存在包含保本保收益内涵的表述，如零风险、收益有保障、本金无忧等。(2) 资产管理计划名称中含有“保本”字样。(3)与投资者私下签订回购协议或承诺函等文件，直接或间接承诺保本保收益；向投资者口头或者通过短信、微信等各种方式承诺保本保收益。(4) 向非合格投资者销售资产管理计划，明知投资者实质不符合合格投资者标准，仍予以销售确认，或者通过拆分转让资产管理计划份额或其收益权、为投资者直接或间接提供短期借货等方式，变相突破合格投资者标准。(5) 单一资产管理计划投资者人数超过200人，或者同一资产管理人为单一融资项目设立多个资产管理计划，变相突破投资者人数限制。(6) 通过报刊、电台、电视、互联网等公众传播媒体，讲座、报告会、分析会等方式，布告、传单、短信、微信、博客和电子邮件等载体，向不特定对象宣传具体产品，但证券期货经营机构和销售机构通过设置特定对象确定程序的官网、客户端等互联网媒介向己注册特定对象进行宣传推介的除外。(7)向投资者宣传资产管理计划预期收益率。(8) 夸大或者片面宣传产品，夸大或者片面宣传资产管理计划管理人及其管理的产品、投资经理等的过往业绩，未充分揭示产品风险，投资者认购资产管理计划时未签订风险揭示书和资产管理合同。"},{"id":"n-bas3-77","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"证券公司或其分支机构违反 《证券公司融资融券业务管理办法》，下列关于中国证监会或其派出机构可采取的措施，正确的有()。","options":["出具警示函","判处罚金","责令公开说明","监管谈话"],"answer":"ACD","explain":"证券公司或其分支机构违反《证券公司融资融券业务管理办法》，中国证监会或者其派出机构可采取责令改正、监管谈话、出具警示函、责令公开说明、责令参加培训、责令定期报告、暂不受理与行政许可有关的文件、暂停部分或者全部业务、撤销业务许可等相关监管措施。"},{"id":"n-bas3-78","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"证券公司融资融券业务涉及的法律法规和准则包括()。","options":["《证券公司融资融券业务管理办法》","《股票质押式回购交易及登记结算业务办法》","《证券法》","《证券公司监督管理条例》"],"answer":"ACD","explain":"融资融券业务的基础法律法规包括《证券法》、《证券公司监督管理条例》，其专门业务管理办法包括《证券公司融资融券业务管理办法》等。《股票质押式回购交易及登记结算业务办法》是场外质押融资的规范，不直接规范融资融券业务。"},{"id":"n-bas3-79","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"证券公司应当按照规定向社会公众披露本公司的年度财务报告及其他信息，其中，证券公司应当披露的董事、监事、高级管理人员薪酬管理信息至少包括 ()。","options":["薪酬管理的基本制度及决策程序","年度薪酬总额和在董事、监事、高级管理人员之间的分布情况","薪酬延期支付情况","非现金薪酬情况"],"answer":"ABCD","explain":"证券公司还应当披露董事、监事、高级管理人员薪酬管理信息，至少包括如下方面:(1)新酬管理的基本制度及决策程序；(2) 年度薪酬总额和在董事、监事、高级管理人员之间的分布情况；(3)薪酬延期支付和非现金新酬情况。"},{"id":"n-bas3-80","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"按照合伙协议的约定，可以委托一个或者数个合伙人对外代表合伙企业，执行合伙事务。","options":["正确","错误"],"answer":"A","explain":"本题表述正确。按照合伙协议的约定或者经全体合伙人决定，可以委托一个或者数个合伙人对外代表合伙企业，执行合伙事务。"},{"id":"n-bas3-81","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"当经营机构利益与投资者利益发生冲突时，应当优先保障投资者的合法利益。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。投资者适当性管理及相关法规都强调，当机构利益与投资者利益发生冲突时，应当优先保障投资者合法权益。"},{"id":"n-bas3-82","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"非法设立期货公司，或者未经核准从事相关期货业务的，予以取缔，没收违法所得，并处以违法所得1倍以上10倍以下的罚款:没有违法所得或者违法所得不足100万元的，处以 100 万元以上1000 万以下的罚款。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。根据《期货和衍生品法》第一百三十二条的规定，非法设立期货公司，或者未经核准从事相关期货业务附，予以取缩，没收违法所得、并处以违法所得1倍以上10倍以下哟罚款:没有违法所得或者违法所得不足100万元，处以100万元以上1000万以下的罚款。"},{"id":"n-bas3-83","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"根据《公司法》，上市公司董事和高级管理人员在任职期间每年转让股份不得超过其所持本公司股份总数的 15%。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。上市公司董事、监事和高级管理人员在任职期间，每年通过集中竞价、大宗交易协议转让等方式转让的股份不得超过其所持本公司股份总数25%。"},{"id":"n-bas3-84","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"根据 《关于加强对利用“荐股软件”从事证券投资咨询业务监管的暂行规定》，向投资者销售或者提供“荐股软件”，并直接或者间接获取经济利益的，属于从事证券投资咨询业务，应当经中国证券业协会许可，取得证券投资咨询业务资格。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。向投资者销售或者提供“荐股软件”，并直接或者间接获取经济利益的，属于从事证券投资咨询业务，应当经中国证监会许可(并非“证券业协会许可”)，符合证券投资咨询业务条"},{"id":"n-bas3-85","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"根据《证券公司风险处置条例》，证券公司挪用客户资产并且不能自行弥补，情节严重的，国务院证券监督管理机构可以对该证券公司进行接管。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。证券公司挪用客户资产并且不能自行弥补，严重危害证券市场稳定运行，或者经国务院证券监督管理机构责令改正，逾期未改正的，国务院证券监督管理机构可以对该证券公司进行接管。题干缺少了“严重危害证券市场稳定运行”这一重要前提条件。"},{"id":"n-bas3-86","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"根据《证券基金经营机构信息技术管理办法》，证券公司应当将经营及客户数据按照时效性和完整性进行分类分级，并根据不同类别和级别作出差异化数据管理制度安排。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。证券公司应当将经营及客户数据按照重要性和敏感性进行分类分级，并根据不同类别和级别作出差异化数据管理制度安排。"},{"id":"n-bas3-87","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"根据《证券期货经营机构私募资产管理计划运作管理规定》，证券期货经营机构在任何情况下，均不得将资产管理计划资产投资于本机构、托管人的控股股东、实际控制人或者其他关联方发行的证券。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。证券公司将资产管理计划资产投资于本机构、托管人及其控股股东、实际控制人或者其他关联方发行前证券或者承销期内承销的证券，应当建立健全内部审批机制和评估机制，并应当遵循投资者利益优先原则，事先取得投资者同意，事后告知投资者和托管人，并采取切实有效措施，防范利益冲突，保护投资者合法权益。除上述情形外，证券公司不得将其管理资产管理计划资产，直接或者通过投资其他资产管理计划等间接形式，为本机构、托管人及前述机构的控股股东、实际控制人或者其他关联方提供或者变相提供融资。"},{"id":"n-bas3-88","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"根据《证券期货投资者适当性管理办法》，证券公司应将投资者区分为普通投资者和专业投资者，并对普通投资者在信息告知、风险警示、投资收益、适当性匹配等方面给予特别保护。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。根据 “投资者分类”的明确规定，普通投资者在信息告知、风险警示、适当性匹配等方面享有特别保护，但不包含“投资收益”。保本保收益是明确的禁止性行为。因此，题干中的“投资收益”一词错误。"},{"id":"n-bas3-89","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"加强声誉约束是证券文化建设十个方面行为层关键要素之一。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。证券行业文化建设包括三个层次十个方面的关键要素。一是行为层，包括平衡各方利益、建立长效激励、加强声誉约束、落实责任担当四个要素。二是组织层，包括融合发展战略、强化文化认同、激发组织活力三个要素。三是观念层，包括秉承守正创新、崇尚专业精神、坚持可持续发展三个要素。"},{"id":"n-bas3-90","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"经营机构在销售产品或提供服务过程中，应当全面了解投资者，向投资者就不确定事项提供确定性的判断。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。经营机构不得向投资者就不确定事项提供确定性的判断，或者告知投资者有可能使其误认为具有确定性的意见。"},{"id":"n-bas3-91","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"目前，我国证券公司的营销渠道包括通过证券公司内部营销人员进行直接营销和委托证券经纪人开展证券经纪业务营销活动。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。目前，我国证券公司的营销渠道包括通过证券公司内部营销人员进行直接营销和委托证券经纪人开展证券经纪业务营销活动。"},{"id":"n-bas3-92","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"全国股转系统是经国务院批准，依法设立的全国性证券交易场所。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。13获取证券交易所、国务院批准其他全国性证券交易场所为证券集中交易提供场所和设施……证券交易所、国务院批准的其他全国性证券交易场所的设立、变更和解散，由国务院决定。全国中小企业股份转让系统(全国股转系统)是经国务院批准设立的全国性证券交易场所。"},{"id":"n-bas3-93","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"上市公司收购中，在收购要约确定前承诺期限内，收购人不得撤销其收购要约。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。收购要约约定的收购期限不得少于 30日，并不得超过 60日。在收购要约确定的承诺期限内，收购人不得撤销其收购要约。"},{"id":"n-bas3-94","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"私募基金管理人应当建立健全关联交易管理制度，不得以私募基金财产与关联方进行不正当交易或者利益输送，不得通过多层嵌套或者其他方式进行隐瞒。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。私募基金管理人应当建立健全关联交易管理制度，不得以私募基金财产与关联方进行不正当交易或者利益输送，不得通过多层嵌套或者其他方式进行隐瞒。"},{"id":"n-bas3-95","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"投资者对开放式基金份额的买卖，只能根据基金份额上市交易规则，委托证券公司在证券交易所完成交易，且交易双方均是基金的投资者。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。获取投资者对封闭式基金份额买卖，只能根据基金份额上市交易规则，委托证券公司在证券交易所完成交易，且交易双方均是基金的投资者。"},{"id":"n-bas3-96","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"违规披露、不披露重要信息行政责任认定的依据是中国证监会颁布的《信息披露违法行为行政责任认定规则》:违规披露《不披露重要信息刑事责任认定的依据是《中华人民共和国证券法》。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。中国证监会《信息披露违法行为行政责任认定规则》关于违规披露、不披露重要信息行政贡任认定作出了相关规定。违规披露、不披露重要信息刑事责任认定的依据是《刑法》。"},{"id":"n-bas3-97","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"为加强融资融券业务集中统一管理，证券公司分管融资融券业务的高级管理人员应该兼管风险监控部门。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。"},{"id":"n-bas3-98","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券代销，是指证券公司将发行人证券按照协议全部购入，或者在承销期结束时将售后剩余证券全部自行购入承销方式。","options":["正确","错误"],"answer":"B","explain":"本题表述错误。(1) 证券代销，是指证券公司代发行人发售证券，在承销期结束时，将未售出的证券全部退还给发行人的承销方式。(2)证券包销，是指证券公司将发行人证券按照协议全部购入，或者在承销期结束时将售后剩余证券全部自行购入的承销方式。"},{"id":"n-bas3-99","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司从事证券经纪业务，客户资金不足而接受其买入委托，或者客户证券不足而接受其卖出委托的，对直接负责的主管人员和其他直接责任人员给予警告，并处以3万元以上30万元以下的罚款。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。根据《证券公司监督管理条例》第七十八条的规定，证券公司从事证券经纪业务，客户资金不足而接受其买入委托，或者客户证券不足而接受其卖出委托的，对直接负责的主管人员和其他直接责任人员给予警告，并处以3万元以上30万元以下的罚款。"},{"id":"n-bas3-100","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司从事中间介绍业务工作人员不得进行期货交易。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。；密包过证券公司从事介绍业务工作人员不得进行期货交易。"},{"id":"n-bas3-101","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司基于个人同意处理个人信息，个人有权撤回其同意，证券公司应当提供便捷的撤回同意的方式。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。证券公司基于个人同意处理个人信息的，个人有权撤回其同意。个人信息处理者应当提供便捷的撤回同意的方式。"},{"id":"n-bas3-102","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司可以从事股票期权经纪业务、自营业务、做市业务、与股票期权备兑开仓以及行权相关的证券现货经纪业务。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。证券公司可以从事股票期权经纪业务、自营业务、做市业务，期货公司可以从事股票期权经纪业务、与股票期权备兑开仓以及行权相关的证券现货经纪业务。"},{"id":"n-bas3-103","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司入股区性股权市场运营机构，可以不必采取措施与区域性股权市场运营机构保持业务独立。()","options":["正确","错误"],"answer":"B","explain":"本题表还错误。证券公司入股区域性股权市场运营机构，应当采取必要措施与区域性股权市场运营机构保持业务独立，不得利用股东身份牟取不正当利益。"},{"id":"n-bas3-104","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司应当在向中国证监会报送年度报告的同时报送年度信息技术管理专项报告。","options":["正确","错误"],"answer":"A","explain":"本题表述正确。证券公司应在向证监会报送年度报告的同时报送年度信息技术管理专项报告。"},{"id":"n-bas3-105","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司应当制定合规管理的基本制度，经股东(大)会审议通过后实施。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。证券公司应当制定合规管理的基本制度，经董事会审议通过后实施，而非“股东(大)会”。"},{"id":"n-bas3-106","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司转发香港机构发布的港股研究报告，应当对该香港机构进行审查，确保其经香港证券及期货事务监察委员会批准取得就证券提供意见牌照，并具有发布证券研究报告业务经验。()加微信","options":["正确","错误"],"answer":"A","explain":"本题表述正确。证券公司转发香港机构发布的港股研究报告，应当对该香港机构进行审查，确保其经香港证券及期货事务监察委员会批准取得就证券提供意见牌照，并具有发布证券研究报告业务经验。"},{"id":"n-bas3-107","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券基金经营机构分支机构负责人，指的是证券基金经营机构在境内设立从事业务经营活动的子公司、分公司以及证券营业部的负责人。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。分支机构负责人，是指证券基金经营机构在境内设立的从事业务经营活动的分公司、证券营业部，以及中国证监会规定的下属其他非法人机构的负责人。"},{"id":"n-bas3-108","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券经纪业务被责令停业整顿，证券公司应当注销客户的账户。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。证券经纪业务被责令停业整顿的，证券公司在规定的期限内可以将其证券经纪业务委托给国务院证券监督管理机构认可的证券公司管理，或者将客户转移到其他证券公司。而非注销客户的账户。微信)"},{"id":"n-bas3-109","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券行业执业声誉信息包括基本信息》诚信信息和其它执业声誉信息。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。执业声誉信息包括基本信息、诚信信息和其他执业声誉信息。"},{"id":"n-bas3-110","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】A 证券公司成立于2008年10月，经营证券自营、证券经纪及证券投资咨询等业务。\n2018年3月，李某通过该证券公司考核进入公司实习，经过试用期的锻炼并且取得了证券\n从业资格证，转正正式成为一名证券从业人员。\n根据该案例，回答以下问题。\n\n【问题】假如该证券公司工作人员李某于 2021年7月20日辞职，与该公司解除劳动关系。以下说法正确的是()。","options":["证券公司应当在2021年7月25日前为其办理注销登记","李某应联系中国证券业协会，协会在 2021年7月25日前为其办理注销登记","李某再也不能从事证券工作","李某执业资格依旧存在，若入职其他公司可直接开展业务"],"answer":"A","explain":"从业人员离职前，证券公司应当自劳动关系(或委托代理关系)解除之日起5个工作日内办理注销登记。"},{"id":"n-bas3-111","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】A 证券公司成立于2008年10月，经营证券自营、证券经纪及证券投资咨询等业务。\n2018年3月，李某通过该证券公司考核进入公司实习，经过试用期的锻炼并且取得了证券\n从业资格证，转正正式成为一名证券从业人员。\n根据该案例，回答以下问题。\n\n【问题】若李某在该证券公司任职期间，故意提供虚假信息，伪造交易记录，诱骗投资者买卖证券合约，情节特别严重。则根据《刑法》，应当()","options":["处5年以下有期徒刑或者拘役","处5年以上10年以下有期徒刑或拘役","处2万元以上20万元以下罚金","处1万元以上10万元以下罚金"],"answer":"BC","explain":"根据《刑法》第一百八十一条规定，证券交易所、期货交易所、证券公司、期货经纪公司从业人员，证券业协会、期货业协会或者证券期货监督管理部门的工作人员，故意提供虚假信息或者伪造、变造、销毁交易记录，诱骗投资者买卖证券、期货合约，造成严重后果的，处5年以下有期徒刑或者拘役，并处或者单处1万元以上10万元以下罚金；情节特别恶分，处5年以上10年以下有期徒刑，并处2万元以上20万元以下罚金。"},{"id":"n-bas3-112","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公司系一家有限责任公司。甲系该公司股东，甲事实上合计持有该公司50%股权，\n其中，30%股权由其本人持有(登记在其本人名下)，20%股权由乙代为持有(登记为乙持\n有)。未经甲同意，乙将其代持的20%股权转让给了丙，并收取了转让款。甲本人持有的30%\n股权尚未缴足出资，在出资期限庙满前，甲将该等股权转让给了丁。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于乙和丙之间的股权转让的相关说法，错误是()。","options":["内根据协议取得了 20%股份的所有权","甲可以主张乙方无权处分，法院应当判决该转让协议无效","乙作为名义股东，具有公司股东资格","乙侵犯了甲的权利，应当赔偿损失"],"answer":"B","explain":"根据《证券从业《法律法规》官方教材》“第一章证券市场基本法律法规”“(2)股权代持情况下的股权转让”案例及分析:A选项正确:教材案例原文明确:“自然人甲、乙作为登记名义股东，未经实际出资人丙同意，转让丙名下13%股份给丁，并收取了转让款。在此案中，该股权转让行为不因丙与甲乙之间存在股权代持协议而无效。丁根据协议取得13%股份的所有权。”本案中，乙作为名义股东将股权转让给丙，同样适用此原则，丙根据协议取得了20%股份的所有权。B选项错误:教材明确:“在股权代持情况下，实际出资人与名义股东之间系合同关系，实际出资人未经显名确认并记载于股东名册的，尚不具有公司股东资格。因此，名义出资人对外转让股权属于有权处分而非无权处分。”因此，甲主张“无权处分”是错误的。此外，根据《公司法》司法解释规定，人民法院不应当仅以此为由判决转让协议无效。甲只能请求乙承担赔偿责任。C选项正确:教材明确:“实际出资人未经显名确认并记载于股东名册的，尚不具有公司股东资格。”因此，乙作为名义股东(登记股东)，具有公司股东资格。D选项正确:教材案例原文明确:“而甲、乙侵犯了丙的权利，应赔偿因侵权行为给丙造成损失。”教材明确:“名义股东处分股权造成实际出资人损失，实际出资人请求名义股东承担赔偿责任，人民法院应予支持。”因此，乙侵犯了甲的应得利益，应当赔偿损失。因此，错误的选项是B。"},{"id":"n-bas3-113","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公司系一家有限责任公司。甲系该公司股东，甲事实上合计持有该公司50%股权，\n其中，30%股权由其本人持有(登记在其本人名下)，20%股权由乙代为持有(登记为乙持\n有)。未经甲同意，乙将其代持的20%股权转让给了丙，并收取了转让款。甲本人持有的30%\n股权尚未缴足出资，在出资期限庙满前，甲将该等股权转让给了丁。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于甲和丁之间的股权转让的相关说法，正确的有()。","options":["甲应当按期缴纳尚未缴足出资","丁未按期交付出资前，由公司登记机关责令改正，并可处以罚款","丁应当按期缴纳尚未缴足出资","丁未按期足额缴纳出资，甲应当缴纳其未缴纳部分出资"],"answer":"CD","explain":"根据《证券从业《法律法规》官方教材》“第一章证券市场基本法律法规”“(五)有限责任公司股权转让相关规定”中“4.瑕疵股权转让效力”规定:A选项错误:根据教材规定:“股东转让已认缴出资但未届出资期限的股权，由受让人承担缴纳该出资义务。”本案中，甲将其未缴足出资(未届出资期限)30%股权转让给了丁。根据上述规定，缴纳出资的义务转移给了受让人丁，甲不再有按期缴纳义务。因此A选项错误。B选项错误:根据教材规定，丁未按期交付出资的，应当由公司向丁发出书面催缴书，而非“由公司登记机关责令改正并处罚款”。公司登记机关行政处罚是针对公司设立时的违法行为(如虚假出资、抽逃出资)或公司本身的违规行为，而非针对受让人未履行出资义务的民事行为。因此B选项错误。C选项正确:教材明确:“股东转让已认缴出资但未届出资期限股权，由受让人承担缴纳该出资义务。”因此，丁(受让人)作为新的股东，应当按期缴纳尚未缴足的出资。D选项正确:教材明确:“受让人未按期足额缴纳出资，转让人对受让人未按期缴纳出资承担补充责任。”因此，如果丁未按期足额缴纳出资，原股东甲(转让人)需要对其未缴纳部分承担补充责任。教材中使用的术语是“补充责任”，与题干表述“甲应当缴纳其未缴纳部分出资”意思一致(即甲承担补充缴纳义务)。因此，正确的选项是 C、"},{"id":"n-bas3-114","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】2025年3月，赵某、钱某、孙某三人共同设立了甲有限责任公司。甲公司章程规定，\n赵某以货币出资200万元，钱某以专利权作价出资 200万元，孙某以股权作价出资100万元，\n各股东所认缴出资应在公司成立之日起5年内缴足；股东对外转让股权应书面通知其他股东，\n其他股东自接到通知之日起 30日内未答复视为放弃优先购买权。2025年8月，公司发现钱\n某用于出资的专利权实际价值仅 120 万元，远低于公司章程约定的作价金额。2025年10月，\n孙某未经书面通知其他股东，与王某签订了股权转让协议，拟转让其所持股权。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于钱某出资行为说法，正确的是()。","options":["钱某的专利权出资比例超过公司注册资本 30%，违反法律规定","赵某、孙某无需对钱某出资差额承担连带责任","钱某的出资因作价不实导致其出资无效，应重新履行出资义务","钱某应就专利权作价与实际价值的差额向甲公司补足出资"],"answer":"D","explain":"根据《公司法》，作为出资的非货币财产的实际价额显著低于公司章程所定价额的，应当由交付该出资的股东补足其差额(选项D正确)。专利权出资比例可以是20%以上，非货币出资最高可达70%(选项A错误》。公司设立时其他股东(赵某、孙某)承担连带责任(选项B错误)。钱某的出资行为有效，但需要补足差额(选项C错误)。"},{"id":"n-bas3-115","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】2025年3月，赵某、钱某、孙某三人共同设立了甲有限责任公司。甲公司章程规定，\n赵某以货币出资200万元，钱某以专利权作价出资 200万元，孙某以股权作价出资100万元，\n各股东所认缴出资应在公司成立之日起5年内缴足；股东对外转让股权应书面通知其他股东，\n其他股东自接到通知之日起 30日内未答复视为放弃优先购买权。2025年8月，公司发现钱\n某用于出资的专利权实际价值仅 120 万元，远低于公司章程约定的作价金额。2025年10月，\n孙某未经书面通知其他股东，与王某签订了股权转让协议，拟转让其所持股权。\n请根据上述背景信息回答以下问题。\n\n【问题】下列关于孙某股权转让行为说法，正确的是()。","options":["孙某的股权转让行为因违反法律强制性规定而自始无效","孙某股权转让行为侵犯了其他股东优先购买权","孙某应当向其他股东转让股权，无权向第三方转让股权","孙某的股权转让行为需经股东会事后追认方可生效"],"answer":"B","explain":"根据《公司法》，股东向股东以外的人转让股权，应当书面通知其他股东，其他股东在同等条件下享有优先购买权。孙某未履行书面通知义务，直接与王某签订协议，侵犯了赵某、钱某的优先购买权(选项B正确)。"},{"id":"n-bas3-116","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】2025年3月，赵某、钱某、孙某三人共同设立了甲有限责任公司。甲公司章程规定，\n赵某以货币出资200万元，钱某以专利权作价出资 200万元，孙某以股权作价出资100万元，\n各股东所认缴出资应在公司成立之日起5年内缴足；股东对外转让股权应书面通知其他股东，\n其他股东自接到通知之日起 30日内未答复视为放弃优先购买权。2025年8月，公司发现钱\n某用于出资的专利权实际价值仅 120 万元，远低于公司章程约定的作价金额。2025年10月，\n孙某未经书面通知其他股东，与王某签订了股权转让协议，拟转让其所持股权。\n请根据上述背景信息回答以下问题。\n\n【问题】根据《公司法》有关规定，下列说法正确的有()。","options":["赵某、钱某、孙某出资形式均为法律允许财产形式","甲公司章程规定股东实缴出资期限符合法律规定要求","孙某转让其股权，还应当书面通知甲公司","赵某、钱某、孙某之间可以相互转让其全部或者部分股权"],"answer":"ABCD","explain":"根据《公司法》，货币、实物、知识产权(专利权)、股权等可以用货币估价并可以依法转全体股东认缴出资额由股东按照公司章程让的非货币财产均可作价出资(选项A正确入。的规定自公司成立之日起五年内缴足(选项B正确)。股东转让股权，应当书面通知公司(选项C正确)。股东之间可以相互转让其全部或者部分股权(选项D正确)。"},{"id":"n-bas3-117","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】客户王某在甲证券公司基营业部开立有经纪业务账户，因其账户证券交易存在异常被\n证券公司使用的反洗钱系统预警。其营业部的业务人员和合规人员共同分析识别后，结合客\n户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人的公司违规\n经营外汇业务相关，甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报告，同时\n向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的洗钱风\n险等级调至最高，对客户采取了冻结账户等措施。\n根据该案例，回答以下问题。\n\n【问题】根据人民银行反洗钱相关规定，下列属于可疑交易后续控制措施的有()。","options":["中止业务关系","限制客户交易","拒绝提供服务","提升客户风险等级"],"answer":"BCD","explain":"证券公司在报送可疑交易报告后，应当根据中国人民银行的相关规定采取相应的后续风险控制措施，包括对可疑交易所涉客户及交易开展持续监控、提升客户风险等级、限制客户交易、拒绝提供服务、终止业务关系、向相关金融监管部门报告、向相关侦查机关报案等。"},{"id":"n-bas3-118","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】客户王某在甲证券公司基营业部开立有经纪业务账户，因其账户证券交易存在异常被\n证券公司使用的反洗钱系统预警。其营业部的业务人员和合规人员共同分析识别后，结合客\n户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人的公司违规\n经营外汇业务相关，甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报告，同时\n向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的洗钱风\n险等级调至最高，对客户采取了冻结账户等措施。\n根据该案例，回答以下问题。\n\n【问题】根据《金融机构大额交易和可疑交易报告管理办法》，下列关于证券公司向其所在地中国人民银行或者其分支机构报告形式昀说法，正确的有()。","options":["口头形式","书面形式","电子形式","现场汇报"],"answer":"BC","explain":"证券公司应当在向中国反洗钱监测分析中心提交可疑交易报告同时，以电子形式或书面形式向所在地中国人民银行或者其分支机构报告，并配合反洗钱调查。"},{"id":"n-bas3-119","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】客户王某在甲证券公司基营业部开立有经纪业务账户，因其账户证券交易存在异常被\n证券公司使用的反洗钱系统预警。其营业部的业务人员和合规人员共同分析识别后，结合客\n户尽职调查的结果，怀疑客户王某用于进行证券交易的资金与其担任法定代表人的公司违规\n经营外汇业务相关，甲证券公司立即向中国反洗钱监测分析中心提交了可疑交易报告，同时\n向其营业部所在地的中国人民银行某中心支行提交了重点可疑交易报告，并将客户的洗钱风\n险等级调至最高，对客户采取了冻结账户等措施。\n根据该案例，回答以下问题。\n\n【问题】根据可疑交易报告的相关规定，证券公司正确的做法是()。","options":["明显涉嫌洗钱活动的，向人民银行反洗钱监测分析中心提交可疑交易报告的同时，还要向所在地中国人民银行或其分支机构报告","交易监测标准仅包括客户交易金额、频率、流向等异常情形，不包括客户身份、行为等异常情形","发现客户交易与洗钱等犯罪活动相关，对满足特定金额的，应向人民银行反洗钱监测分析中心提交可疑交易报告","制定本公司的交易监测标准，但对其有效性不能完全负责"],"answer":"A","explain":"证券公司应当制定本公司的交易监测标准，并对其有效性负责。交易监测标准包括但不限于客户身份、行为、交易前资金来源、金额、频率、流向、性质等存在异常的情形。证券公司发现或者有合理理由怀疑客户、客户的资金或者其他资产、客户的交易或者试图进行的交易与洗钱、恐怖融资等犯罪活动相关的，不论所涉资金金额或者资产价值大小，应当向中国反洗钱监测分析中心提交可疑交易报告。"}]},{"id":"n-law1","subject":"law","name":"11月300题 · 法规卷一","stats":{"单选":39,"多选":40,"判断":28,"案例":10},"questions":[{"id":"n-law1-0","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据相关规定，证券经纪人不得()。","options":["替客户办理账户开立、注销、转移，证券认购、交易或者资金存取、划转、查询等事宜","向客户介绍证券投资的基本知识及开户、交易、资金存取等业务流程","向客户传递由证券公司统一提供的研究报告及与证券投资有关信息","向客户传递由证券公司统一提供证券类金融产品宣传推介材料及有关信息"],"answer":"A","explain":"证券经纪人不得有下列行为；替客户办理账户开立、注销、转移，证券认购、交易或者资金存取、划转、查询等事宜(A选项符合题意)。故本题选A选项。【乐橙网提示】证券经纪人不得有的行为还有:(1) 提供、传播虚假或者误导客户的信息，或者诱使客户进行不必要的证券买卖；(2) 与客户约定分享投资收益，对客户证券买卖收益或者赔偿证券买卖的损失作出承诺；(3)采取贬低竞争对手、进入竞争对手营业场所劝导客户等不正当手段招揽客户；(4) 泄露客户的商业秘密或者个人隐私；(5) 为客户之间融资提供中介、担保或者其他便利；(6) 为客户提供非法的服务场所或者交易设施，或者通过互联网络、新闻媒体从事客户招揽和客户服务等活动；(7) 委托他人代其从事客户招揽和客户服务等活动；(8)损害客户合法权益或者扰乱市场秩序其他行为。"},{"id":"n-law1-1","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"上市公司在一年内担保金额超过公司资产总额()前，应当由股东会作出决议，并经出席会议的股东所持表决权2/3以上通过。","options":["10%","50%","20%","30%"],"answer":"D","explain":"D 选项正确，上市公司在1年内向他人提供担保的金额超过公司资产总额30%的，应当由股东会作出决议，并经出席会议的股东所持表决权 2/3以上通过。故本题选D选项。"},{"id":"n-law1-2","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券公司应当至少每半年经主要负责人、()签署确认后，向公司全体董事报告一次公司净资本等风险控制指标的具体情况和达标情况。","options":["首席风险官","监事长","合规总监","独立董事"],"answer":"A","explain":"证券公司应当至少每半年经主要负责人、首席风险官签署确认后(A 选项正确)，向公司全体董事报告一次公司净资本等风险控制指标的具体情况和达标情况。故本题选A选项。"},{"id":"n-law1-3","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"设立管理公开募集基金的基金管理公司，注册资本不低于法定要求，且资本金()。","options":["必须为实缴货币资本","可以是非货币资本","可以认缴出资","可以固定资产出资"],"answer":"A","explain":"A 选项正确，根据 《证券投资基金法》第十三条的规定，设立管理公开募集基金的基金管理公司，注册资本不低于人民币1亿元，且必须为实缴货币资本。故本题选A选项。"},{"id":"n-law1-4","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于投资者适当性管理工作的说法，错误的是()。","options":["需要了解的客户信息包括基本信息、财务状况、投资经验，不包括投资目标、投资知识","“了解你客户”是投资者适当性管理工作前核心内容之一","证券经营机构向投资者销售产品或者提供服务应了解投资者信息","客户的信息包括客户的诚信记录"],"answer":"A","explain":"A 选项错误，“了解你的客户“是投资者适当性管理工作的核心内容之一，需要了解客户信息范围均包括:基本信息、财务状况、投资目标、投资知识、投资经验。故本题选A选项。"},{"id":"n-law1-5","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"甲证券公司代销乙基金公司一款混合型证券投资基金。王某是甲证券公司经纪业务事业部负责代销金融产品上架工作的主管。根据《证券公司代销金融产品管理规定》，王某可以接受乙公司提供()。","options":["宴请及观光游览服务","基金宣传推介资料","乙公司机构客户基金优惠申购费率","高档礼品"],"answer":"B","explain":"B 选项正确，证券公司从事代销金融产品活动的人员不得接受委托人给予的财物或其他利益。故本题选B选项。"},{"id":"n-law1-6","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于公司法律地位说法，错误的是()。","options":["分公司具有法人资格，可以独立承担民事责任","公司可以设立分公司和子公司","子公司具有法人资格，依法承担民事责任","分公司不具有法人资格，其民事责任由公司承担"],"answer":"A","explain":"A 选项错误、D选项正确，分公司不具有法人资格，其民事责任由公司承担。B 选项正确，公司可以设立分公司和子公司。C选项正确，子公司具有法人资格，依法独立承担民事责任。故本题选 A选项。"},{"id":"n-law1-7","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券经营机构及其工作人员廉洁从业实施细则》，证券公司应向证券业协会履行廉洁从业报告义务的事项的内容，说法错误的是〈)。","options":["证券公司发现其工作人员违反廉洁从业相关规定，且进行内部追责，应向证券业协会报送","证券经营机构应自相关决定作出之日或者收到、知悉相关决定之日起5个工作日内，通过证券行业执业声誉信息库向中国证券业协会报送","证券经营机构或者其工作人员因违反廉洁从业相关规定被纪检监察部门、司法机关等部门采取纪律处分、行政处罚、刑事处罚等措施的，应向中国证券业协会报送","证券公司应当于每年4月30日前向证券业协会报送上年度廉洁从业管理情况报告"],"answer":"D","explain":"证券期货经营机构应当于每年4月30日前，向中国证监会有关派出机构(D选项错误，并非”证券业协会”)报送上年度廉洁从业管理情况报告。有下列情形之一的，证券经营机构应当按照 《证券行业执业声誉信息管理办法》的规定，自相关决定作出之日或者收到、知悉相关决定之日起5个工作日内，通过证券行业执业声誉信息库向中国证券业协会报送(B选项正确):(1) 证券经营机构工作人员因违反廉洁从业相关规定被内部追责，且符合《证券行业执业声誉信息管理办法》第九条第三款第六项报送规定的(A 选项正确)；(2) 证券经营机构或者其工作人员因违反廉洁从业相关规定被纪检监察部门、司法机关等部门采取纪律处分、行政处罚、刑事处罚等措施的 (C 选项正确)。故本题选D选项。"},{"id":"n-law1-8","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"合规负责人是证券公司高级管理人员，直接向()负责。","options":["总经理办公会","董事会","监事","股东会"],"answer":"B","explain":"13获取19951B选项正确，合规负责人是高级管理人员，直接向董事会负责，对本公司及其工作人员的经营管理和执业行为的合规性进行审查、监督和检查。故本题选B选项。"},{"id":"n-law1-9","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"甲有限合伙企业成立于20✕6年3月，顾某为普通合伙人，丁某为有限合伙人。20x7年3月，潘某与甲公司签订《借款协议》约定，甲公司从潘某处借款800万元。20x8年5月，甲的合伙人变更为乙公司(普通合伙人)和丙公司(有限合伙人)，同时，顾某和丁某退休。后因甲迟迟不归还800万元借款及利息，潘某提起诉讼。下列说法错误是()。","options":["顾某作为甲公司普通合伙人，对该项债务承担无限责任","T某作为原有限合伙人已经退休，不再承担该项债务责任","乙公司作为甲公司的新普通合伙人，应当对该项债务承担无限责任","丙公司作为甲公司的新有限合伙人，对入伙前的该项债务以其认缴的出资额为限承担责任"],"answer":"B","explain":"A 选项正确，普通合伙人对合伙企业债务承担无限连带责任，有限合伙人以其认缴的出资额为限对合伙企业债务承担责任。合伙企业不能清偿到期债务的，可以要求普通合伙人清偿。顾某作为甲公司普通合伙人，对该项债务承担无限责任。B选项错误，根据《合伙企业法》第八十八条规定，丁某作为原有限合伙人，对基于其退伙前的原因发生的有限合伙企业债务，以其退伙时从甲公司取回的财产承担责任。C选项正确，新合伙人对入伙前合伙企业的债务承担无限连带责任。普通合伙人对合伙企业存续期间的债务仍应承担无限连带责任。乙公司应当对该项债务承担无限责任。D 选项正确，有限合伙人对入伙前的公司债务以其认缴出资额为限承担责任。丙公司作为甲公司的新有限合伙人，对入伙前的该项债务以其认缴的出资额为限承担责任。故本题选B选项。网站不是www.ytks8.cn的都是假题，请退款。"},{"id":"n-law1-10","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于反洗钱工作保密要求的说法，错误是()。","options":["应对配合中国人民银行行政调查获取的反洗钱工作信息予以保密","证券公司应对依法履行反洗钱职责或者义务获得客户身份资料和交易信息予以保密","对依法监测、分析、报告可疑交易的有关情况可向单位提供，但不得向个人提供","应对采取临时冻结措施的有关情况予以保密"],"answer":"C","explain":"证券公司应对下列信息予以保密，非依法律规定不得向任何单位及个人透露和提供:(1)依法履行反洗钱职责或者义务获得客户身份资料和交易信息(B选项正确)；(2) 对依法监测、分析、报告可疑交易和开展名单监控的有关情况 (C 选项错误)；(3) 对配合中国人民银行反洗钱行政调查(A选项正确)、采取临时冻结措施有关情况(D选项正确)；(4) 对与采取涉恐冻结措施有关的工作信息予以保密。故本题选C选项。"},{"id":"n-law1-11","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《公司法》，如有限责任公司设监事会，下列关于其成员说法，错误是()。","options":["总经理可以兼任监事","监事任期每届三年","应当有股东代表","应当有公司职工代表"],"answer":"A","explain":"A 选项错误，总经理属于高级管理人员。董事、高级管理人员不得兼任监事。B选项正确，监事的任期每届为3年。监事任期届满，连选可以连任。C、D选项正确，监事会成员应当包括股东代表和适当比例的公司职工代表，其中职工代表的比例不得低于 1/3，具体比例由公司章程规定。故本题选A选项。"},{"id":"n-law1-12","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"王某是甲证券公司经营管理的主要负责人，根据证券监管法律法规，下列说法错误的是()。","options":["为防止董事会越权干涉，王某不应将本公司的资金运作情况向董事会报告","王某根据《公司法》、公司章程的规定行使职权，向董事会负责","王某可以在中国证券业协会担任理事","王某作为甲证券公司主要负责人，必须保证向董事会、监事会报告真实、准确、完整"],"answer":"A","explain":"A 选项错误，证券公司经营管理的主要负责人应当根据董事会或者监事会(或行使监事会职权的监事或董事会设置由董事组成审计委员会)前要求，向董事会或者监事会(或行使监事会职权监事或董事会设置的由董事组成审计委员会)报告公司重大合同的签订、执行情况，资金运用情况和盈亏情况。经营管理的主要负责人必须保证报告真实、准确、完故本题选A选项。"},{"id":"n-law1-13","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"经营机构发布证券研究报告，应当遵循独立、客观、公平、审慎原则，关于独立性原则，以下说法错误是()。","options":["经营机构应当从组织设置、人员职责上，将证券研究报告制作发布业务与销售服务业务分开管理","除相关销售服务人员外，其他人员不得在证券研究报告发布前影响证券研究报告的发布时","制作发布证券研究报告的相关人员，应当独立于证券研究报告相关销售服务人员","经营机构应当采取有效措施，保证制作发布证券研究报告不受上市公司及基金管理公司等利益相关者的干涉和影响"],"answer":"B","explain":"经营机构应当维护证券研究报告制作发布的独立性，从组织设置、人员职责上，将证券研究报告制作发布业务与销售服务业务分开管理 (A 选项正确)；制作发布证券研究报告相关人员，应当独立于证券研究报告相关销售服务人员(C选项正确)；证券研究报告相关销售服务人员不得在证券研究报告发布前干涉和影响证券研究报告的制作过程、研究观点和发布时间(B 选项错误)。经营机构应当采取有效措施，保证制作发布证券研究报告不受利益相关者的干涉和影响 (D选项正确)。故本题选B选项。"},{"id":"n-law1-14","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券法》，下列关于证券登记结算机构业务规则的说法，错误的是()。","options":["投资者委托证券公司进行证券交易，应当通过证券公司申请在证券登记结算机构开立证券","在证券交易所和国务院批准的其他全国性证券交易场所交易证券的登记结算，应当采取全国集中统一的运营方式","证券登记结算机构作为中央对手方提供证券结算服务，是结算参与人共同的清算交收对手，进行全额结算，为证券交易提供集中履行保障","在证券交易所或者国务院批准的其他全国性证券交易场所交易的证券，应当全部存管在证券登记结算机构"],"answer":"C","explain":"证券登记结算机构为证券交易提供集中登记、存管与结算服务，不以营利为目，依法登记，取得法人资格。设立须经国务院证券监督管理机构批准。业务规则:①投资者委托证券公司进行证券交易，应当通过证券公司申请在证券登记结算机构开立证券账户。结算机构应按规定为投资者以其开立证券账户(A选项正确)；②在证券交易所或者国务院批准的其他全国性证券交易场所交易的证券，应当全部存管在证券结算机构。结算机构不得挪用客户证券(D选项正确)；多③在证券交易所和国务院批准的其他全国性证券交易场所交易的证券的登记结算，应当采取全国集中统一的运营方式(B 选项正确)；证券登记结算机构作为中央对手方提供证券结算服务，是结算参与人共同清算交收对手，进行净额结算，为证券交易提供集中履约保障(C选项错误，并非”全额结算”)。故本题选C选项。"},{"id":"n-law1-15","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"按照《证券监督管理条例》的要求，以下()公司应当建立独立董事制度。","options":["经营证券经纪业务、证券资产管理业务和证券承销与保荐业务甲公司","经营融资融券业务、自营业务和研究咨询业务的乙公司","经营证券经纪业务、自营业务和证券投资顾问业务的丙公司","经营证券承销与保荐业务、研究咨询业务和自营业务的丁公司"],"answer":"A","explain":"A 选项正确，经营证券经纪业务、证券资产管理业务、融资融券业务和证券承销与保荐业务中两种以上业务的证券公司，应当建立独立董事制度。故本题选 A选项。"},{"id":"n-law1-16","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"关于证券公司股东出资的规定，以下说法正确的是()。","options":["证券公司股东只能用货币出资","证券公司的债权人可以将其债权转为证券公司股权","证券公司股东的出资可以聘请不具有证券业务资格的会计师事务所验资","证券公司股东货币财产出资总额不得超过证券公司注册资本30%"],"answer":"B","explain":"A 选项错误，证券公司的股东应当用货币或者证券公司经营必需的非货币财产出资。C 选项错误，聘任会计师事务所必须聘请具有证券相关业务资格会计师事务所。D 选项错误，证券公司股东非货币财产出资总额不得超过证券公司注册资本30%。B选项正确，在证券公司经营过程中，证券公司的债权人将其债权转为证券公司股权的，不受前述规定限制。故本题选B选项。"},{"id":"n-law1-17","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券法》相关规定，下列关于证券发行的相关说法，错误的是()。","options":["未经依法注册，任何单位和个人不得公开发行证券","擅自公开或者变相公开发行证券够，责令停止发行，退还所募资金并加算银行同期货款利息，处以统一固定数额罚款","非公开发行证券，不得采用广告、公开劝诱和变相公开方式","公开发行证券，必须符合法律、行政法规规定的条件，并依法报经国务院证券监督管理机构或者国务院授权部门注册"],"answer":"B","explain":"B 选项错误，擅自公开或者变相公开发行证券的，责令停止发行，退还所募资金并加算银行同期存款利息，处以非法所募资金金额 5%以上 50%以下的罚款(并非”处以统一固定数额罚款”)。故本题选B选项。"},{"id":"n-law1-18","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列非货币资产中，股东不可以用货币估价并作价出资是()。","options":["劳务","知识产权","土地使用权","股权、债权"],"answer":"A","explain":"股东可以用货币出资，也可以用实物、知识产权(B选项不符合题意)、土地使用权(C选项不符合题意)、股权、债权(D选项不符合题意)等可以用货币估价并可以依法转让非货币财产作价出资；但是法律、行政法规规定不得作为出资的财产除外。A 选项符合题意，劳务具有人身依附性，无法独立于提供者而依法转让，且其价值难以进行客观、稳定的货币估价。因此，劳务不能作为股东出资方式。故本题选A选项。"},{"id":"n-law1-19","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于期货公司业务许可说法，错误的是()。","options":["国务院期货监督管理机构向期货公司按照其商品期货、金融期货业务种类颁发许可证","期货公司申请金融期货经纪业务资格，应当不存在因涉嫌违法违规正在被有权机关立案调查情形","期货公司从事资产管理业务的，应当依法登记备案","取得业务许可后，期货公司变更业务范围无需再经国务院期货监督管理机构批准"],"answer":"D","explain":"期货公司办理下列事项，应当经国务院期货监督管理机构核准:(1) 合并、分立、停业、解散或者申请破产；(2)变更主要股东或公司的实际控制人；(3)变更注册资本且调整股权结构；(4)变更业务范围(D 选项错误)；(5)国务院期货监督管理机构规定其他重大事项。A选项正确，期货公司经国务院期货监督管理机构核准可以从事下列业务:期货经纪、期货交易咨询、期货做市交易、其他期货业务。B 选项正确，期货公司申请金融期货经纪业务资格，应当不存在因涉嫌违法违规正在被有权机关立案调查的情形。C 选项正确，期货公司从事资产管理业务前，应当符合 《证券投资基金法》等法律、行政法规的规定。故本题选D选项。"},{"id":"n-law1-20","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"以下关于证券公司内部控制制度机制建设的基本要求说法错误是()。","options":["证券公司业务授权应当采用书面形式","应当提高工作效率，比如资金清算人员由技术部人员兼任，以及时解决资金收支时发生技术难题","应当建立完备的业务台账系统，并通过业务台账系统和会计核算系统交叉印证，防止出现账外经营、账目不清等问题","重要合同和票据应有连号控制、作废控制等专门措施"],"answer":"B","explain":"B选项错误，资金清算人员不得由电脑部门人员和交易部门人员兼任。故本题选B选项。"},{"id":"n-law1-21","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"除监管部门另有规定的情形外，通过证券交易所证券交易，投资者持有上市公司己发行的有表决权股份达到5%时，下列关于书面报告和公告的说法，错误是()。","options":["公告后2日内，该投资者在任何情形均不得再行买卖该上市公司股票","投资者持有一个上市公司己发行的股份达到 5%时，应当在该事实发生之日起3日内，进行书面报告","报告期限内，该投资者不得再行买卖该上市公司的股票","投资者应当向国务院证券监督管理机构、证券交易所作出书面报告"],"answer":"A","explain":"通过证券交易所的证券交易，投资者持有或者通过协议、其他安排与他人共同持有一家上市公司己发行的有表决权股份达到 5%时，应当在该事实发生之日起3日内，向国务院证券监督管理机构、证券交易所作出书面报告，通知该上市公司，并予公告。在上述期限内不得再行买卖该上市公司的股票，但国务院证券监督管理机构规定的情形除外(A 选项错误)。故本题选 A选项。"},{"id":"n-law1-22","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司信用风险管理指引》，下列关于信用风险监控、报告机制要求的说法，错误是()。","options":["证券公司应建立健全存续期业务后续管理和跟踪机制，并明确业务覆盖范围和管理方式","证券公司应明确信用风险报告种类、路线、内容、格式和频率","证券公司应根据监管部门或其派出机构等的要求报送与信用风险有关的报告","证券公司应通过设置并监测各类信用风险指标，静态监控信用风险状况、管理水平及效果"],"answer":"D","explain":"D 选项错误，证券公司应通过设置并监测各类信用风险指标，动态、持续地监控信用风险状况、管理水平及效果(而非”静态监控”)。故本题选D选项。"},{"id":"n-law1-23","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，下列关于证券公司人员信息公示说法，正确的是()。","options":["证券公司应当对其高级管理人员、部门负责人和分支机构负责人人员名单在官方网站进行公示，并自发生变化之日起20个工作日内进行更新","证券公司应当对其高级管理人员、部门负责人和分支机构负责人的人员名单在中国证券业协会网站进行公示，并自发生变化之日起 20 个工作日内进行更新","证券公司应当对其董事、监事、高级管理人员、部门负责人和分支机构负责人人员名单在中国证券业协会网站进行公示，并自发生变化之日起10个工作日内进行更新","证券公司应当对其董事、监事、高级管理人员和分支机构负责人的人员名单在官方网站进行公示，并自发生变化之日起20个工作日内进行更新"],"answer":"C","explain":"证券基金经营机构应当对其董事、监事、高级管理人员和分支机构负责人(不包含部门负责人)前人员名单在官方网站进行公示，并自发生变化之日起 20 个工作日内进行更新(A、B、C选项错误，D选项正确)。证券基金经营机构高级管理人员职责分工发生调整，或者分支机构负责人改任本公司其他分支机构负责人的，应当在5个工作日内向中国证监会相关派出机构报告。故本题选D选项。理，办理信息披露事务等事宜。C. 董事会秘书D.董事长C选项正确，上市公司设董事会秘书，负责公司股东会和董事会会议的筹备、文件保管以及公司股东资料的管理，办理信息披露事务等事宜。故本题选C选项。"},{"id":"n-law1-24","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《合格境内机构投资者境外证券投资管理试行办法》，合格境内机构投资者开展境外证券投资业务，应当由()负责资产托管业务。","options":["境外证券公司","境内证券公司","境外商业银行","境内商业银行"],"answer":"D","explain":"D选项正确，合格境内投资者开展境外证券投资业务，应当由境内商业银行负责资产托管业务，可以委托境外证券服务机构代理买卖证券。故本题选D选项。"},{"id":"n-law1-25","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"关于非公开募集基金的投资范围，以下说法错误是()。","options":["非公开募集基金可以买卖股权","非公开募集基金可以买卖股指期货","非公开募集基金可以买卖基金份额","非公开募集基金可以买卖基金合同约定以外投资标"],"answer":"D","explain":"获取D 选项错误，非公开募集基金财产投资包括买卖股票、股权、债券、期货、期权、基金份额及投资合同约定的其他投资标(并非”基金合同约定以外”)。故本题选D选项。"},{"id":"n-law1-26","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列做法不违反证券投资咨询业务监管规定的是()。","options":["引用有关信息、资料时未注明出处和著作权人","证券投资咨询人员同时在两个或者两个以上的证券、期货投资咨询机构服务","就同一问题向不同客户提供投资分析、预测或者建议一致","未以行业公认的谨慎、诚实和勤勉尽责的态度，为投资人或者客户提供证券投资咨询服务"],"answer":"C","explain":"A 选项不符合题意，不得断章取义地引用或者篡改有关信息、资料；引用有关信息、资料时，应当注明出处和著作权人。B选项不符合题意，证券投资咨询人员不能同时在两个或者两个以上的证券、期货投资咨询机构服务。D 选项不符合题意，证券投资咨询人员应当以行业公认谨慎、诚实和勤勉尽责的态度，为投资人或者客户提供证券投资咨询服务。故本题选C选项。"},{"id":"n-law1-27","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券公司工作人员对以任何方式知悉的敏感信息负有严格的保密义务，不得利用敏感信息为自己或他人谋取不当利益。证券公司采取以下保密措施错误前是()。","options":["建立内幕信息知情人管理制度","与公司工作人员签署保密文件","对可能知悉敏感信息工作人员使用公司的信息系统或配发的设备形成的电子邮件、即时通信信息和其他通信信息进行监测","证券公司聘用外部服务商，无权要求其对在服务中获知敏感信息进行保密"],"answer":"D","explain":"D 选项错误，证券公司聘用外部服务商的，应当与服务商约定其对在服务中获知敏感信息负有保密义务。故本题选D选项。"},{"id":"n-law1-28","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券法》，下列关于证券公司开展资产管理业务说法，错误是()。","options":["证券公司经营证券资产管理业务前，应当符合《基金法》等法律、行政法规的规定","证券公司发行资产管理产品，应当遵守国务院依照《证券法》的原则制定的相关规定","除证券公司外，任何单位和个人不得从事资产管理业务","证券公司必须将其证券经纪业务、证券承销业务、证券自营业务、证券做市业务和证券资产管理业务分开办理，不得混合操作"],"answer":"C","explain":"C 选项错误，证券公司可以委托具备证券资产管理业务资格、特定客户资产管理业务资格或者合格境内机构投资者资格其他证券公司或者基金管理公司进行证券投资管理。故本题选C选项。"},{"id":"n-law1-29","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"甲有限责任公司由张某和孙某出资设立，张某担任公司执行董事兼任经理。在经营期间，张某利用职务之便恶性转移甲资产，导致甲公司无力偿还欠乙公司的施工款。下列说法不符合《公司法》规定的是()。","options":["张某和孙某对甲公司所欠款项承担有限责任","乙公司可以向人民法院起诉，要求股东张某依法承担连带责任","张某应对甲公司的损失承担赔偿责任","因张某的不当行为给孙某造成损失，张某应依法承担赔偿责任"],"answer":"A","explain":"A选项符合题意，董事、监事、高级管理人员执行职务时违反法律、行政法规或者公司章程的规定，给公司造成损失，应当承担赔偿责任。故本题选A选项。A. 违反法律、行政法规或者中国证监会有关规定，情节严重，可以对有关责任人员采取3"},{"id":"n-law1-30","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《禁入规定》，下列说法不正确所有 (J5398512栋)至5年证券市场禁入措施","options":["违反法律、行政法规或者中国证监会有关规定，情节严重，可以对有关责任人员采取3","行为恶劣、严重拢乱证券市场秩序、严重损害投资者利益或者在重大违法活动中起主要作用等情节较为严重的，可以对有关责任人员采取5至10年的证券市场禁入措施","严重违反法律、行政法规或者中国证监会有关规定，构成犯罪的，可以对有关责任人员采取终身证券市场禁入措施","组织、策划、领导或者实施重大违反法律、行政法规或者中国证监会有关规定的活动的，可以对有关责任人员采取终身证券市场禁入措施"],"answer":"B","explain":"违反法律、行政法规或者中国证监会有关规定，情节严重的，可以对有关责任人员采取3年以上5年以下的证券市场禁入措施(A选项正确)。行为恶劣、严重扰乱证券市场秩序、严重损害投资者利益或者在重大违法活动中起主要作用等情节较为严重，可以对有关责任人员采取6年以上10年以下证券市场禁入措施(B选项错误)。有下列情形之一的，可以对有关责任人员终身采取证券市场禁入措施:(1)严重违反法律、行政法规或者中国证监会有关规定，被人民法院生效司法裁判认定构成犯罪的(C选项正确)；(2) 组织、策划、领导或者实施重大违反法律、行政法规或者中国证监会有关规定的活动的(D选项正确)。故本题选B选项。【乐橙网提示】可以对有关责任人员终身采取证券市场禁入措施的情形还包括:(1)从业人员等负有法定职责人员，故意不履行法律、行政法规或者中国证监会规定义务，并造成特别恶劣社会影响，或者致使投资者利益受到特别严重损害，或者导致其他特别严重后果；(2)在报送或者公开披露材料中，隐瞒、编造或者篡改重要事实、重要财务数据或者其他重要信息，或者组织、指使从事前述行为或者隐瞒相关事项导致发生上述情形，严重拢乱证券市场秩序，或者造成特别恶劣社会影响，或者致使投资者利益受到特别严重损害旳；(3)违反法律、行政法规或者中国证监会有美规定，从事欺诈发行、内幕交易、操纵证券市场等违法行为，严重扰乱证券市场秩序并造成特别恶劣社会影响，或者获取违法所得等不当利益数额特别巨大，或者致使投资者利益受到特别严重损害；(4)违反法律、行政法规或者史国证监会有关规定，情节严重，应当采取证券市场禁入措施，且存在故意出具虚假重要证据，隐瞒、毁损重要证据等阻碍、抗拒执法单位及其工作人员依法行使监督检查、调查职权行为旳；(5)因违反法律、行政法规或者中国证监会有关规定，5年内曾经被执法单位给予行政处罚2次以上，或者5年内曾经被采取本规定第四条第一款第一项规定的证券市场禁入措施的；(6)其他违反法律、行政法规或者中国证监会有关规定，情节特别严重的。"},{"id":"n-law1-31","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司年度报告内容与格式准则》，证券公司应当编制年度报告，并在每个会计年度结束之日起()个月内向证监会报送。","options":["2","3","4","5"],"answer":"C","explain":"证券公司应当自每一会计年度结束之日起4个月内(C选项正确)，向国务院证券监督管理机构报送年度报告；自每月结束之日起7个工作日内，报送月度报告。故本题选C选项。"},{"id":"n-law1-32","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券基金经营机构信息技术管理办法》，下列关于证券公司信息技术合规与风险管理的说法，错误的是()。","options":["证券公司应当建立相应审查、监测和检查机制，确保合规与风险管理覆盖信息技术运用各个环节","证券公司应当识别借助信息技术手段从事证券基金业务活动各类风险，建立持续有效风险监测机制","证券公司应当将信息技术运用情况纳入合规与风险管理体系，为合规管理部门和风险管理部门配备与业务活动规模、复杂程度相适应的信息技术资源","证券公司借助信息技术手段从事证券基金业务活动的，应当在业务系统上线之后，上线与业务活动复杂程度和风险状况相适应的风险管理系统或相关功能"],"answer":"D","explain":"D 选项错误，证券公司借助信息技术手段从事证券基金业务活动的，应当在业务系统上线时(并非”上线之后”)，同步上线与业务活动复杂程度和风险状况相适应的风险管理系统或相关功能，对风险进行识别、监控、预警和干预。故本题选D选项。"},{"id":"n-law1-33","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券公司提交虚假证明文件骗取业务许可，应给予()处罚。","options":["中止业务","没收相关业务收入并处罚款","撒销相关许可并处罚款","撤销相关许可"],"answer":"C","explain":"C 选项正确，提交虚假证明文件或者采取其他欺诈手段骗取证券公司设立许可、业务许可或者重大事项变更核准的，撤销相关许可，并处以 100 万元以上 1000 万元以下的罚款。故本题选C选项。"},{"id":"n-law1-34","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"证券金融公司应当每年按照税后利润的()提取风险准备金。","options":["5%","10%","15%","20%"],"answer":"B","explain":"获取B选项正确，证券金融公司应当每年按照税后利润的 10%提取风险准备金。中国证监会可以根据防范证券金融公司风险的需要，对提取比例进行调整。故本题选B选项。"},{"id":"n-law1-35","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券期货投资者适当性管理办法》，下列属于证券经营机构在销售产品、提供服务中禁止性行为的是()","options":["“投资者基本信息表”由合法授权人填写","向投资者披露有助于投资者作出投资分析判断的信息","《投资者风险承受能力评估问卷》由经营机构业务人员辅导代填","向普通投资者主动推介符合其投资目标的产品"],"answer":"C","explain":"C选项符合题意，《投资者基本信息表》《投资者风险承受能力评估问卷》应当由投资者本人或合法授权人填写，经营机构业务人员不得以任何方式诱导、误导或欺骗投资者，从而影响填写结果。故本题选C选项。"},{"id":"n-law1-36","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"股份有限公司以超过股票票面金额发行价格发行股份所得溢价款应当列为公司()。","options":["资本公积金","任意公积金","股本溢价","法定公积金"],"answer":"A","explain":"A 选项正确，公司以超过股票票面金额发行价格发行股份所得溢价款、发行无面额股所得股款未计入注册资本的金额以及国务院财政部门规定列入资本公积金的其他项目，应当列为公司资本公积金。故本题选A选项。【乐橙网提示】公司分配当年税后利润时，应当提取利润白10%列入公司法定公积金。公司从税后利润中提取法定公积金后，经股东会决议，还可以从税后利润中提取任意公积金。股本溢价是资本公积金下明细科目(资本公积金包含股本溢价、其他资本公积等)，题目问的是整体归属，而非具体明细，法规题目要遵从法律原文表述。"},{"id":"n-law1-37","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"根据《证券公司证券自营业务指引》，关于自营业务资金出入的相关规定，下列行为正确是()。","options":["以个人名义从自营账户调出资金","以公司名义从自营账户提取现金","以个人名义调入资金","以公司名义调入资金"],"answer":"D","explain":"自营业务资金的出入必须以公司名义进行(D选项正确)，禁止以个人名义从自营账户中调入调出资金(A、C选项错误)，禁止从自营账户中提取现金 (B选项错误)。故本题选D选项。"},{"id":"n-law1-38","subject":"law","source":"2026.11 LC 300题","type":"单选","q":"下列关于公司分立的说法，错误的是()。","options":["公司分立，其财产作相应的分割","公司分立，应当重新编制资产负债表及财产清单","公司应当自作出分立决议之日起10日内通知债权人，并于30日内在报纸上或者国家企业信用信息公示系统公告","公司分立前债务由分立前的公司承担"],"answer":"D","explain":"A选项正确，公司分立，其财产作相应的分割。B选项正确，公司分立，应当编制资产负债表及财产清单。C 选项正确，公司应当自作出分立决议之自起10日内通知债权人，并于30日内在报纸上或者国家企业信用信息公示系统公告爽D选项错误，公司分立前的债务由分立后的公司承担连带责任。但是，公司在分立前与债权人就债务清偿达成的书面协议另有约定的除外。故本题选D选项。"},{"id":"n-law1-39","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于证券公司合规经营的说法，错误的有()。","options":["证券公司不得为客户违规从事证券发行、交易活动提供便利","证券公司的合规管理仅需覆盖总部各部门及分支机构，不需覆盖各层级子公司","证券公司应保证关联交易公允性","证券公司的合规管理仅体现在执行、监督环节"],"answer":"BD","explain":"证券公司开展各项业务，应当遵循合规经营、勤勉尽责，坚持客户利益至上原则，并遵守下列基本要求:(1) 持续督促客户规范证券发行行为，动态监控客户交易活动，及时报告、依法处置重大异常行为，不得为客户违规从事证券发行、交易活动提供便利 (A选项正确)；(2)依法履行关联交易审议程序和信息披露义务，保证关联交易公允性(C 选项正确)，防止不正当关联交易和利益输送。证券公司的合规管理应当覆盖所有业务，各部门、各分支机构、各层级子公司(统称“下属单位”)和全体工作人员(B选项错误)，贯穿决策、执行、监督、反馈等各个环节(D选项错误)。故本题选 BD选项。【乐橙网提示】证券公司合规经营应遵守基本要求还包括获取(1) 充分了解客户的基本信息、财务状况、投资经验、投资目标、风险偏好、诚信记录等信息并及时更新。(2) 合理划分客户类别和产品、服务风险等级，确保将适当的产品、服务提供给适合客户，不得欺诈客户。(3) 严格规范工作人员执业行为，督促工作人员勤勉尽责，防范其利用职务便利从事违法违规、超越权限或者其他损害客户合法权益行为。(4) 有效管理内幕信息和未公开信息，防范公司及其工作人员利用该信息买卖证券、建议他人买卖证券，或者泄露该信息。(5)及时识别、妥善处理公司与客户之间、不同客户之间、公司不同业务之间利益冲突，切实维护客户利益，公平对待客户。(6) 审慎评估公司经营管理行为对证券市场的影响，采取有效措施，防止扰乱市场秩序。"},{"id":"n-law1-40","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券基金经营机构董事、监事、高级管理人员及从业人员监督管理办法》，下列关于履职限制的做法，错误有()。","options":["甲证券公司上海分公司负责人张某，兼职担任上海某投资管理有限公司法定代表人","乙证券公司大连某证券营业部负责人王某，在任职期间从事其他经营性活动的行为","丙证券公司总经理李某在任职期间担任了深圳市某集团有限公司等4家公司董事","丁证券公司副总经理赵某在公司参股私募基金公司担任董事"],"answer":"ABC","explain":"A、B、C选项错误，证券基金经营机构的高级管理人员(李某)、部门负责人和分支机构负责人(张某和王某)，不得在证券基金经营机构参股或者控股的公司以外的营利性机构兼职。D 选项正确，证券基金经营机构的高级管理人员(赵某)在证券基金经营机构参股的公司仅可兼任董事、监事，且数量不得超过2家。故本题选 ABC 选项。"},{"id":"n-law1-41","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列不属于资产证券化基础资产清单有()。","options":["不动产租金债权","提单","仓単","产权证书"],"answer":"BCD","explain":"密包过资产证券化基础资产负面清单包括:(1) 因空置、在建等原因不能产生稳定现金流的不动产、不动产租金债权或者相关收益权(A 选项不符合题意)；(2)不能直接产生现金流、仅依托处置资产才能产生现金流的基础资产，如提单(B选项符合题意)、仓单 (C选项符合题意)、产权证书(D选项符合题意)等具有物权属性的权利凭证。故本题选 BCD 选项。"},{"id":"n-law1-42","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"法律关系特征主要有()。","options":["以权利和义务为内容的一种社会关系","法律主体之间一种社会关系","以法律规范为基础形成一种社会关系","社会组织之间的一种市场关系"],"answer":"ABC","explain":"法律关系的特征:(1) 法律关系是一种以法律规范为基础形成的社会关系 (C 选项正确)；(2)法律关系是以权利和义务为内容社会关系(A选项正确)；(3)法律关系是法律主体之间的社会关系(B选项正确)。D 选项错误，法律关系主体不仅包括”社会组织”，还包括自然人、国家等。法律关系是社会关系，其内容不仅限于“市场关系”，因此，此选项将法律关系限定在”社会组织”之间的“市场关系”，大大缩小了其范围。故本题选 ABC 选项。"},{"id":"n-law1-43","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"证券公司融资融券业务决策机构主要负责()。","options":["保证金收取和交易执行等业务操作押题加","确定对单一客户和单一证券授信额度","决定与融资融券业务有关部门设置","确定融资融券期限和利率费率"],"answer":"BD","explain":"业务决策机构由有关高级管理人员及部门负责人组成，负责制定融资融券业务操作流程，选择可从事融资融券业务的分支机构，确定对单一客户和单一证券的授信额度(B 选项正确)、融资融券的期限和利率(费率)(D选项正确)、保证金比例和最低维持担保比例、可充抵保证金的证券种类及折算率、客户可融资买入和融券卖出的证券种类。分支机构在公司总部的集中监控下，按照公司的统一规定和决定，具体负责客户征信、签约、开户、保证金收取和交易执行等业务操作(A选项错误)。董事会负责制定融资融券业务的基本管理制度，决定与融资融券业务有关的部门设置(C选项错误)及各部门职责，确定融资融券业务的总规模。故本题选BD选项。"},{"id":"n-law1-44","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"关于证券期货经营机构向普通投资者提供服务时，应当进行更充分前风险警示，下列说法正确的有()。","options":["为普通投资者提供风险揭示材料","向普通投资者销售高风险产品时履行特别的注意义务","向普通投资者提供服务时无需履行特别注意义务","向普通投资者在营业网点进行风险警示，可以全程录音录像"],"answer":"AB","explain":"经营机构及其从业人员在向普通投资者提供服务时应当进行更为充分的风险警示，包括为普通投资者提供风险揭示材料(A选项正确)；向普通投资者销售高风险产品(B选项正确)或提供相关服务时履行特别注意义务(C选项错误，并非无需)；在营业网点向普通投资者进行告知、警示的，应当全过程录音录像等(D选项错误，并非可以而是应当)。故本题选 AB 选项。"},{"id":"n-law1-45","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《关于证券业从业人员登记管理有关事项通知》，下列关于证券业从业人员登记类别昀说法，正确的有()。","options":["从业人员登记类别包括一般证券业务、证券经纪人等","从业人员登记类别包括证券投资咨询(投资顾问)、证券投资咨询(分析师)、保荐代表","应当根据从业人员实际从事业务类别和相应要求进行登记，同一人员只能登记为一个类","登记信息包括基本信息、专业能力水平评价情况、从业经历及相关情况、诚信情况及其他执业声誉情况等"],"answer":"ABCD","explain":"A、B选项正确，登记类别包括一般证券业务、证券经纪人、证券投资咨询(证券投资顾问)、证券投资咨询(证券分析师)、保荐代表人等。C 选项正确，证券公司应当根据人员实际岗位、从事的业务类别和相应要求进行登记，同一人员只能登记为一个类别。D 选项正确，登记信息包括基本信息、专业能力水平评价情况、从业经历及相关情况、诚信情况及其他执业声誉情况等。故本题选 ABCD 选项。"},{"id":"n-law1-46","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列有限责任公司法人财产权的说法中，错误的有()。","options":["股东以其个人资产为限对公司承担责任，公司以其注册资本对公司债务承担责任","股东以其出资额为限对公司承担责任，公司以其全部财产对公司债务承担责任","股东以其出资额为限对公司承担责任，公司以其注册资本对公司的债务承担责任","股东以其个人资产为限对公司承担责任，公司以其全部财产对公司债务承担责任"],"answer":"ACD","explain":"B选项正确，有限责任公司，股东以其认缴的出资额为限对公司承担责任。公司以其全部财产对公司的债务承担责任。股份有限公司的股东以其认购的股份为限对公司承担责任。A 选项错误，错在”个人资产”、“注册资本”；C选项错误，错在”注册资本”；D选项错误，错在”个人资产”。故本题选 ACD选项。"},{"id":"n-law1-47","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于基金管理人、托管人相关责任说法，正确有()。","options":["基金管理人、托管人应缴纳的罚款、罚金以其固有财产承担","基金托管人以受托资金承担罚款、罚金","依法收缴的罚款、罚金和没收违法所得，全部上缴国库","依法收缴的罚款、罚金和没收的违法所得，全部归基金财产所有"],"answer":"AC","explain":"A选项正确、B选项错误，基金管理人、基金托管人、基金服务机构依照法律规定，应当承担的民事赔偿责任和缴纳的罚款、罚金，由基金管理人、基金托管人、基金服务机构以其固有财产承担。C 选项正确、D选项错误，依照《证券法》收缴的罚款和没收的违法所得，全部上缴国库。故本题选 AC选项。"},{"id":"n-law1-48","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于风险管理的说法，正确的有()。","options":["证券公司应当保障首席风险官的独立性","风险管理部门具备3年以上的证券、金融等有关领域工作经历的人员占公司总部员工比例应不低于2%","公司应当设立专门部门履行风险管理职责","合规部门中具备3年以上证券、金融、法律、会计、信息技术等有关领域工作经历合规管理人员数量不得低于公司总部人数的1.5%且不得少于5人。"],"answer":"ABCD","explain":"A 选项正确，证券公司应当保障首席风险官能够充分行使履行职责所必需知情权及独立性。B选项正确，风险管理部门具备3年以上的证券、金融、会计、信息技术等有关领域工作经历的人员占公司总部员工比例应不低于 2%。C选项正确，证券公司应当指定或者设立专门部门履行风险管理职责，在首席风险官领导下推动全面风险管理工作。D 选项正确，合规部门中具备3年以上证券、金融、法律、会计、信息技术等有关领域工作经历的合规管理人员数量不得低于公司总部人数1.5%，且不得少于5人。故本题选 ABCD 选项。"},{"id":"n-law1-49","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司代销金融产品管理规定》，下列关于证券公司从事代销金融产品活动说法，正确的有()。","options":["金融产品营销人员应充分了解所负责推介金融产品的信息，证券公司无需对其进行培训","证券公司从事代销金融产品活动的人员不得接受委托人给予财物或其他利益","证券公司从事代销金融产品活动的人员，应遵守代销金融产品管理规定，无须遵守证券从业人员管理规定","金融产品营销人员应充分了解代销活动有关的公司内部管理规定和监管要求"],"answer":"BD","explain":"根据《证券公司代销金融产品管理规定》，证券公司从事代销金融产品活动的人员，应当符合规定的条件，并遵守证券从业人员的管理规定。证券公司应当对金融产品营销人员进行必要培训，保证其充分了解所负责推介金融产品信息及与代销活动有关的公司内部管理规定和监管要求(D选项正确)；证券公司从事代销金融产品活动的人员不得接受委托人给予的财物或其他利益(B选项正确)。A 选项错误，证券公司需对营销人员进行培训；C选项错误。应遵守各项法律法规、从业人员管理规定。故本题选 BD选项。"},{"id":"n-law1-50","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于股份有限公司设立方式的说法，正确的有()。","options":["股份有限公司的设立，可以采取发起设立方式","发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司","募集设立，是指全部股份向社会公开募集或者向特定对象募集而设立公司","股份有限公司的设立，可以采取募集设立方式"],"answer":"ABD","explain":"A、D选项正确，发起设立适用于有限责任公司和股份有限公司，募集设立只适用于股份有限公司。B选项正确，发起设立，是指由发起人认购设立公司时应发行的全部股份而设立公司。C选项错误，募集设立，是指由发起人认购公司应发行股份的一部分，其余股份向社会公开募集或者向特定对象募集而设立公司。故本题选 ABD 选项。"},{"id":"n-law1-51","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于证券公司另类投资子公司业务规则说法，正确的有()。","options":["另类子公司不得下设任何机构","证券公司担任拟上市企业 IPO辅导机构，在签署有关协议或实质开展业务孰早时点后，另类子公司不得对该企业进行投资，但科创板跟投的除外","另类子公司不得融资","另类子公司持有境内证券交易所上市交易证券，应当将其持有与母公司自营持有同一只证券的市值分别计算市值，判断是否符合监管对风控指标的规范"],"answer":"ABC","explain":"A选项正确，让券公司应当突出主业，充分考虑自身发展需要、财务实力和管理能力，审慎设立另类子公司。另类子公司不得再下设任何机构。C选项正确，另类子公司不得融资，不得对外提供担保和贷款，不得成为对所投资企业债务承担连带责任出资人。B 选项正确，证券公司担任拟上市企业首次公开发行股票的辅导机构、财务顾问、保荐机构、主承销商或担任拟挂牌企业股票挂牌并公开转让的主办券商，应当按照签订有关协议或者实质开展相关业务两个时点孰早原则，在该时点后另类子公司不得对该企业进行投资。中国证监会、证券交易所及中国证券业协会另有规定的除外(科创板推出“跟投”制度是强制性要求，是禁止性规定例外)。D 选项错误，另类子公司持有境内证券交易场所上市交易和转让证券，应当将另类子公司与母公司自营持有同一只证券市值合并计算，合并计算后的市值应当符合《证券公司风险控制指标管理办法》规定。故本题选 ABC 选项。"},{"id":"n-law1-52","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》，下列关于承销团说法，错误有()。","options":["向特定对象发行证券票面总值超过人民币5000万元的，应当由承销团承销","向不特定对象发行证券票面总值超过人民币5000万元，应当由承销团承销","向不特定对象发行证券的，可以不聘请承销团承销","向不特定对象发行证券的，应当聘请承销团承销"],"answer":"ABD","explain":"A、B选项错误，新证券法取消了“向不特定对象发行证券票面总值超过人民币5000万元，应当由承销团承销“前规定。D 选项错误，向不特定对象发行证券聘请承销团承销的，承销团应当由主承销和参与承销前证券公司组成，可以不聘请。故本题选 ABD选项。"},{"id":"n-law1-53","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司业务范围审批暂行规定》，证券公司从事下列业务，无须取得证券自营业务资格有()。","options":["证券公司将自有资金投资于依法公开发行国债、投资级公司债、货币市场基金、央行票据等证监会认可的风险较低、流动性较强的证券，且投资规模不超过其净资本的80%","证券公司委托基金管理公司进行证券投资管理，且投资规模不超过其净资本80%","证券公司依法履行承销义务而买卖证券","在规定的投资规模内，证券公司投资于依法发行公司债券"],"answer":"AC","explain":"证券公司进行现金管理，将自有资金投资于依法公开发行国债、投资级公司债、货币市场基金、央行票据等证监会认可的风险较低、流动性较强的证券，以及证券公司经证监会批准设立的集合资产管理计划、专项资产管理计划，且投资规模不超过其净资本80%的，或者因依法履行承销义务而买卖证券，无须取得证券自营业务资格，但应当比照执行证券自营业务规则。"},{"id":"n-law1-54","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列行为中，属于损害客户利益有()。","options":["违背客户的委托为其买卖证券","不在规定时间内向客户提供交易确认文件","为牟取佣金收入，诱使客户进行不必要的证券买卖","未经客户的委托，擅自为客户买卖证券，或者假借客户的名义买卖证券"],"answer":"ABCD","explain":"禁止证券公司及其从业人员从事下列损害客户利益的行为:(1) 违背客户的委托为其买卖证券(A 选项符合题意)；(2)不在规定时间内向客户提供交易的确认文件(B 选项符合题意)；(3) 未经客户的委托，擅自为客户买卖证券，或者假借客户的名义买卖证券(D 选项符合题意)；(4) 为牟取佣金收入，诱使客户进行不必要的证券买卖(C 选项符合题意)；(5) 其他违背客户真实意思表示，损害客户利益的行为。违反上述规定给客户造成损失的，应当依法承担赔偿责任。故本题选 ABCD 选项。"},{"id":"n-law1-55","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于证券公司对敏感信息采取保密措施所说法，正确前有()。","options":["与证券公司工作人员签署保密文件，要求工作人员对工作中获取前敏感信息严格保密","对可能知悉敏感信息的工作人员使用的公司及冷人各类信息系统或设备形成的电子邮件、即时通信信息和其他通讯信息进行监测","建立内幕信息知情人管理制度","加强对涉及敏感信息信息系统《通信及办公自动化等信息设施、设备管理，保障敏感奧过押题加信息安全"],"answer":"ACD","explain":"(1) 与公司工作人员签署保密文件，要求工作人员对工作中获取的敏感信息严格保密(A选项正确)；(2) 加强对涉及敏感信息的信息系统、通信及办公自动化等信息设施、设备管理，保障敏感信息安全 (D选项正确)；(3)对可能知悉敏感信息工作人员使用公司(并不包括个人)的信息系统或配发设备形成的电子邮件、即时通信信息和其他通信信息进行监测(B选项错误)；(4) 建立内幕信息知情人管理制度(C选项正确)。故本题选 ACD选项。"},{"id":"n-law1-56","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列行为中，构成操纵证券、期货市场行为是()。","options":["甲与乙合谋利用资金优势连续买卖，操纵证券交易价格","甲与乙相互串通，以事先约定的时间、价格和方式相互进行证券交易，影响证券交易价格","甲以自己为交易对象，进行不转移所有权自买自卖，影响证券交易价格","甲是证券公司工作人员，利用因职务便利获取的内幕信息，从事与该信息相关昀证券活动"],"answer":"ABC","explain":"操纵证券、期货市场罪，是指有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量:(1) 单独或合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买卖(A选项正确)；(2)与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易(B选项正确)；(3) 在自己实际控制够账户之问进行证券交易、或者以自己为交易对象，自买自卖期货合约的(C选项正确)；D 选项错误，利用因职务便利获取的内幕信息从事相关的证券活动属于内幕交易行为(并非“操纵证券、期货市场”)。故本题选 ABC 选项。【乐橙网提示】操纵证券、期货市场罪，是指有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量:(1) 单独或者合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买(2) 与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易；(3)在自己实际控制账户之间进行证券交易，或者以自己为交易对象，自买自卖期货合(4) 不以成交为目的，频繁或者大量申报买入、卖出证券、期货合约并撤销申报；(5)利用虚假或者不确定的重大信息，诱导投资者进行证券、期货交易；(6) 对证券、证券发行人、期货交易标的公开作出评价、预测或者投资建议，同时进行反向证券交易或者相关期货交易；(7) 以其他方法操纵证券、期货市场。"},{"id":"n-law1-57","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"资产托管机构办理资产管理资产托管业务，托管人应当履行()职责。","options":["安全保管资产管理计划资产","对所托管的不同财产分别设置账户，确保资产管理计划财产的完整与独立","按照资产管理合同约定，根据管理人的投资指令，及时办理清算、交割事宜","复核资产管理计划资产净值和份额净值"],"answer":"ABCD","explain":"托管人应当履行职责包括:(1)安全保管资产管理计划财产(A选项正确)获取(2) 对所托管的不同财产分别设置账户，确保资产管理计划财产的完整与独立 (B选项正确)；(3) 按照资产管理合同约定，根据管理入的投资指令，及时办理清算、交割事宜(C选项正确)；(4) 复核资产管理计划资产净值和份额净值等(D选项正确)。故本题选 ABCD 选项。"},{"id":"n-law1-58","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于股份有限公司的股份发行的说法，错误有()。","options":["股份的发行，实行公平、公开、公正原则","股票发行价格低于票面金额","同股同权是指所有发行的股票，发行条件和价格应当相同","股份有限公司股份采取股票形式"],"answer":"ABC","explain":"A、C选项错误，股份的发行，实行公平、公正的原则，同种类的每一股份应当具有同等权利。同次发行同类别股份，每股发行条件和价格应当相同(并非”所有发行”)；认购人所认购的股份，每股应当支付相同价额。B 选项错误，面额股股票发行价格可以按票面金额，也可以超过票面金额，但不得低于票面金额。D 选项正确，股份有限公司的股份采取股票的形式，股票是公司签发的证明股东所持股份的凭证。故本题选 ABC 选项。"},{"id":"n-law1-59","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"客户申请开展融资融券业务要在证券公司开立实名()。","options":["客户信用交易担保证券账户","信用证券账户","客户信用交易担保资金账户","信用资金台账"],"answer":"BD","explain":"A、C选项错误，证券公司经营融资融券业务，应当以自己名义，在证券登记结算机构分别开立融券专用证券账户、客户信用交易担保证券账户、信用交易证券交收账户和信用交易资金交收账户；以自己的名义在商业银行分别开立融资专用资金账户和客户信用交易担保资金账户。B、D选项正确，客户通过证券公司开展融资融券业务，应当在证券公司开立实名信用资金台账和信用证券账户，在指定的商业银行开立实名信用资金账户。故本题选 BD选项。"},{"id":"n-law1-60","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于违反证券发行规定的法律责任说法，正确的有()。","options":["未经依法注册，擅自公开或者变相公开发行证券，责令停止发行，退还所募资金并加算银行同期存款利息，并处罚款","发行人在其公告的证券发行文件中隐瞒重要事实或者编造重大虚假内容，尚未发行证券，可以不追究责任","发行人的控股股东、实际控制人组织、指使发行人在其公告的证券发行文件中隐瞒重要事实或者编造重大虚假内容，只对发行人进行没收违法所得处罚","证券公司承销或者销售擅自公开发行的证券的，责令停止承销或者销售，没收违法所得，并处罚款"],"answer":"AD","explain":"A选项正确，擅自公开或者变相公开发行证券，责令停止发行，退还所募资金并加算银行同期存款利息，处以非法所募资金金额5%以上50%以下的罚款。B 选项错误，发行人在其公告的证券发行文件中隐瞒重要事实或者编造重大虚假内容，尚未发行证券，处以200万元以上2000万元以下罚款(并非不追究责任)。C 选项错误，发行人的控股股东、实际控制人组织、指使从事前款违法行为，没收违法所得，并处以违法所得 10%以上1倍以下罚款，对直接负责主管人员和其他直接责任人员，处以100万元以上1000万元以下的罚款(并非只追究发行人责任)。D 选项正确，证券公司承销或者销售擅自公开发行或者变相公开发行的证券的，责令停止承销或者销售，没收违法所得，并处以违法所得1倍以上10倍以下的罚款。故本题选 AD 选项。"},{"id":"n-law1-61","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》，下列关于证券交易说法，正确的有()。","options":["证券交易当事人依法买卖的证券，必须是依法发行并交付的证券","公开发行的证券，可以在按照国务院规定设立的区域性股权市场转让","证券在证券交易所上市交易，应当采用公开集中交易方式或者国务院证券监督管理机构批准其他方式","依法发行的证券，《公司法》和其他法律对其转让期限有限制性规定，在限定期限内不得转让"],"answer":"ACD","explain":"A 选项正确，证券交易当事人依法买卖的证券，必须是依法发行并交付的证券。非依法发行的证券，不得买卖。B选项错误，公开发行的证券，应当在依法设立的证券交易所上市交易或者在国务院批准其他全国性证券交易场所交易。C 选项正确，证券在证券交易所上市交易，应当采用公开的集中交易方式或者国务院证券监督管理机构批准的其他方式。D 选项正确，依法发行证券，《公司法》和其他法律对其转让期限有限制性规定的，在限定的期限内不得转让。故本题选 ACD选项。"},{"id":"n-law1-62","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"证券公司营业部存在柜台人员违规为他人打印客户的对账单导致客户资料泄露，以及为客户之间的融资提供便利等情形，违反了 《关于加强证券经纪业务管理的规定》及其他监管规定。中国证监会及其派出机构可以()。","options":["出具警示函","进行监管谈话","开除直接责任人","依法进行行政处罚"],"answer":"ABD","explain":"中国证监会《证券经纪业务管理办法》的有关规定:证券从业人员违反本办法规定的，依法采取出具警示函(A选项正确)、责令改正、监管谈话(B选项正确)等行政监管措施(D选项正确)。构成犯罪，移送司法机关处理。C 选项错误，“开除直接责任人”这一行为的主体是证券公司，并非监管机构。故本题选 ABD选项。"},{"id":"n-law1-63","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司全面风险管理规范》，下列关于证券公司应当将子公司的风险管理纳入统一体系的说法，正确的有()。","options":["证券公司对子公司风险管理工作实行垂直管理","证券公司应当任命一名高级管理人员负责公司的全面风险管理工作","证券公司各部门、分支机构及子公司负责人承担风险管理直接责任","子公司在整体风险偏好和风险管理制度框架下，建立自身的风险管理组织架构、制度流程、信息技术系统和风控指标体系，保障全面风险管理的一致性和有效性"],"answer":"ABCD","explain":"B 选项正确，证券公司应当任命一名高级管理人员负责全面风险管理工作。C 选项正确，证券公司各部门、分支机构及子公司的负责人承担本单位风险管理的直接责任。A、D 选项正确，证券公司应当依法依规通过公司治理程序将所有子公司(被证券公司控制)纳入全面风险管理体系，对其风险管理工作实行垂直管理并逐步加强一体化管控，从公司治理、风险偏好与风险指标管理、新业务管理、重大事项管理，风险报告、考核评价等方面强化对子公司的风险管理，要求并确保子公司在整体风险偏好和风险管理制度框架下，建立健全自身的风险管理组织架构、制度流程、信息技术系统和风控指标体系，保障全面风险管理旳的一致性和有效性。故本题选 ABCD选项。"},{"id":"n-law1-64","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"有下列情形之一，对股东会决议投反对票的股东可以请求公司按照合理的价格收购其股份()。","options":["公司连续3年不向股东分配利润，而公司该3年连续盈利，并且符合法律规定的分配利润","公司转让主要财产","公司章程规定的营业期限届满或者章程规定的其他解散事由出现，股东会通过决议修改章程使公司存续","公司减少注册资本"],"answer":"BC","explain":"有下列情形之一的，对股东会该项决议投反对票股东可以请求公司按照合理的价格收购其股份，公开发行股份的公司除外:(1)公司连续5年不向股东分配利润，而公司该5年连续盈利，并且符合本法规定的分配利润条件(A 选项错误)；(2)公司转让主要财产(B选项正确)；(3)公司章程规定的营业期限届满或者章程规定的其他解散事由出现，股东会通过决议修改章程使公司存续(C选项正确)。D 选项错误，不属于情形之一。故本题选 BC 选项。"},{"id":"n-law1-65","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"自营业务中涉及()方面的重大决策，应当经过集体决策并采取书面形式，由相关人员签字确认后存档。","options":["自营规模","风险限额","资产配置","业务授权"],"answer":"ABCD","explain":"自营业务中涉及自营规模(A选项正确)、风险限额(B选项正确)、资产配置(C选项正确)、业务授权(D 选项正确)等方面的重大决策，应当经过集体决策并采取书面形式，由相关人员签字确认后存档。故本题选 ABCD 选项。"},{"id":"n-law1-66","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"以下关于证券公司风险管理条线履职保障的说法，正确的是()。","options":["公司董事可以随意干涉首席风险官的工作","公司应当指定或者设立专门部门履行风险管理职责","首席风险官不得兼任或者分管与其职责相冲突职务","证券公司应当将子公司纳入全面风险管理体系，对其风险管理工作实行垂直管理"],"answer":"BCD","explain":"A 选项错误，证券公司应当保障首席风险官能够充分行使履行职责所必需的知情权及独立性。B 选项正确，证券公司应当指定或者设立专门部门履行风险管理职责，在首席风险官的领导下推动全面风险管理工作。C选项正确，证券公司应当任命一名高级管理人员负责全面风险管理工作(以下统称”首席风险官”)，首席风险官不得兼任或者分管与其职责相冲突职务或者部门。D 选项正确，证券公司应当依法依规通过公司治理程序将所有子公司(被证券公司控制)纳入全面风险管理体系，对其风险管理工作实行垂直管理并逐步加强一体化管控，从公司治理、风险偏好与风险指标管理、新业务管理、重大事项管理、风险报告、考核评价等方面强化对子公司的风险管理，要求并确保子公司在整体风险偏好和风险管理制度框架下，建立健全自身的风险管理组织架构、制度流程、信息技术系统和风控指标体系，保障全面风险管理一致性和有效性。故本题选 BCD选项。"},{"id":"n-law1-67","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司柜台交易业务规范》《证券公司柜台市场管理办法(试行)》，下列说法正确的有()。","options":["证券公司应当通过与机构间私募产品报价与服务系统联网的方式实现业务信息互联互通，信息范围包括但不限于私募产品基本情况、交易信息和登记结算信息等","中国证监会对证券公司柜台交易活动进行自律管理和日常监控","证券公司进行柜台交易，应当报中国证券业协会备案，其柜台交易管理制度和实施方案应当通过中国证券业协会组织的专业评价","证券公司应于每季度结束后7个工作日内，按照要求向证券交易所报送当期的柜台交易报"],"answer":"AC","explain":"A 选项正确，证券公司应当通过与报价系统联网的方式实现业务信息互联互通，信息范围包括但不限于私募产品基本情况、交易信息和登记结算信息等。B 选项错误，中国证券业协会对证券公司柜台交易活动进行自律管理和日常监控。同时，中国证券业协会委托中证机构间报价系统股份有限公司建立机构间私募产品报价与服务系统，为柜台市场提供互联互通服务。C选项正确，证券公司进行柜台交易，应当报中国证券业协会备案，其柜台交易管理制度和实施方案应当通过中国证券业协会组织的专业评价。D 选项错误，证券公司应于每月结束后5个工作日内按要求向中国证券业协会报送柜台交易月度报表；每年结束后在规定时间报送柜台市场业务年度报告，内容包括但不限于；柜台市场业务总体情况、交易、登记结算、投资者适当性管理、风险及合规管理等。故本题选 AC 选项。"},{"id":"n-law1-68","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于从事证券投资咨询业务人员的资格要求的说法，正确的有()。","options":["不能同时注册成为证券分析师和证券投资顾问","必须加入一家有从业资格的证券投资咨询机构","可以在2个证券投资咨询机构同时执业","必须符合证券投资咨询从业条件"],"answer":"ABD","explain":"题加微1从事证券投资咨询业务的人员，感当符合证券投资咨询从业条件(D 选项正确)并加入一家有从业资格证券投资咨询机构后(B选项正确)，方可从事证券投资咨询业务。同一人员不得同时登记为证券分析师和证券投资顾问(A选项正确)，证券投资咨询机构人员只能与一家证券经营机构签订劳动合同，不得以任何形式同时在两家或两家以上证券经营机构执业(C选项错误)。故本题选 ABD选项。"},{"id":"n-law1-69","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"符合下列()情形的，为公开发行。","options":["向不特定对象发行证券","向特定对象发行证券累计超过","法律、行政法规规定的其他发行行为","向特定对象发行证券累计超过200人的，但依法实施员工持股计划的员工人数不计算在内"],"answer":"ACD","explain":"有下列情形之一的，为公开发行:(1) 向不特定对象发行证券的(A 选项符合题意)。(2)向特定对象发行证券累计超过200人的，但依法实施员工持股计划的员工人数不计算在内(B选项不符合题意、D选项符合题意)。(3)法律、行政法规规定的其他发行行为 (C 选项符合题意)。故本题选ACD选项。"},{"id":"n-law1-70","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"在融资融券交易中，()可作为客户对证券公司债务担保物。","options":["客户缴纳保证金","客户融券卖出所得全部资金","客户在证券公司开户账户内的全部证券","客户的银行存款"],"answer":"AB","explain":"证券公司应当将收取的保证金(A选项正确)以及客户融资买入全部证券(C选项错误，并非开户账户内)和融券卖出所得全部价款(B选项正确)，分别存放在客户信用交易担保证券账户和客户信用交易担保资金账户，作为对该客户融资融券所生债权的担保物。D 选项错误，银行存款与证券公司的融资融券业务无直接法律关系，不属于对证券公司债务的担保物。故本题选 AB选项。"},{"id":"n-law1-71","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于证券公司债券交易建立有效监督制衡机制的说法，正确的是()。","options":["债券交易的投资决策、交易执行、风险控制、清算交收等关键岗位应专人负责，禁止岗位兼任或者混合操作","将各类债券交易纳入公司全面风险管理体系，健全应急处置机制","对自营、资管账户及提供投资顾问服务的账户之间的交易实施有效监控，防范利益输送、冲突和风险传导","债券交易相关部门下设二级部门应当有专职合规人员"],"answer":"ABC","explain":"A 选项正确，债券交易的投资决策、交易执行、风险控制、清算交收等关键岗位应专人负责，禁止岗位兼任或者混合操作；B 选项正确，证券公司应具备专门风险控制系统对各类债券交易实施集中监控。将各类债券交易纳入公司全面风险管理体系，健全应急处置机制；C选项正确，对自营、资管账户及提供投资顾问服务账户之间的交易实施有效监控，防范利益输送、冲突和风险传导；D 选项错误，证券公司合规管理应覆盖各类债券交易部门、大员和业务环节。公司应有专职合规人员负责债券交易合规管理，债券交易相关部门下设二级部门应当有兼职合规人员。故本题选 ABC选项。"},{"id":"n-law1-72","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于合伙人行为的说法，正确的有()。","options":["合伙人违反《合伙企业法》或者合伙协议的约定，从事与合伙企业相竞争的业务或者与本合伙企业进行交易，该收益归合伙企业所有","合伙人执行合伙事务，利用职务上的便利，将应当归属合伙企业的利益据为己有，应当将该利益退还合伙企业","合伙人应当根据合伙协议约定来执行合伙事务","不具有事务执行权合伙人不得擅自执行合伙事务"],"answer":"ABCD","explain":"A 选项正确，合伙人违反法律或约定，从事与合伙企业相竞争的业务或者与本合伙企业进行交易的，该收益归合伙企业所有。B选项正确，合伙人执行合伙事务，或者合伙企业从业人员利用职务上的便利，将应当归合伙企业的利益据为己有的，或者采取其他手段侵占合伙企业财产的，应当将该利益和财产退还合伙企业；给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任。C选项正确，合伙人对执行合伙事务享有同等的权利。按照合伙协议的约定或者经全体合伙人决定，可以委托一个或者数个合伙人对外代表合伙企业，执行合伙事务。D 选项正确，不具有事务执行权的合伙人擅自执行合伙事务，给合伙企业或者其他合伙人造成损失的，依法承担赔偿责任。故本题选 ABCD选项。"},{"id":"n-law1-73","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于欺诈发行股票、债券的法律责任的说法正确的有()。","options":["单位犯该罪，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处有期徒刑或拘役","发行人不符合发行条件，发行人的控股股东指使以欺骗手段骗取发行核准的，依照针对发行人规定处罚","违反相关规定，应当承担民事赔偿责任和缴纳罚款、罚金的，其财产不足以同时支付时，先承担罚款、罚金责任","构成犯罪的情节必须达到数额巨大、后果严重或者有其他严重情节"],"answer":"AD","explain":"B选项错误，发行人在其公告的证券发行文件中隐瞒重要事实或者编造重大虚假内容，尚未发行证券，处以 200 万元以上 2000 万元以下的罚款；已经发行证券前，处以非法所募资金金额10%以上1倍以下的罚款。发行人的控股股东、实际控制人组织、指使从事前款违法行为的，没收违法所得，并处以违法所得10%以上1倍以下的罚款:没有违法所得或者违法所得不足2000万元的，处以200万元以上2000万元以下的罚款。C选项错误，违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金、违法所得，违法行为人财产不足以支付的，优先用于承担民事赔偿责任。故本题选 AD选项。"},{"id":"n-law1-74","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券法》，下列关于上市公司收购的说法，正确的有()。","options":["在及时公告并载明具体变更事项的情况下，收购人可以缩短收购期限","在及时公告并载明具体变更事项的情况下，收购人可以减少预定收购股份数额","在收购要约确定的承诺期限内，收购人不得撤销其收购要约","收购人需要变更收购要约的，应当及时公告，载明具体变更事项，且不得降低收购价格"],"answer":"CD","explain":"在收购要约确定的承诺期限内，收购人不得撤销其收购要约(C选项正确)。收购人需要变更收购要约的，应当及时公告，载明具体变更事项，且不得存在下列情形:(1) 降低收购价格(D选项正确)；(2) 减少预定收购股份数额(B 选项错误)；(3)缩短收购期限(A 选项错误)；(4) 国务院证券监督管理机构规定的其他情形。故本题选 CD选项。"},{"id":"n-law1-75","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券公司融资融券业务管理办法》，下列关于对证券发行人权利的行使，错误有()。","options":["对客户信用交易担保证券账户记录的证券，由证券公司以客户的名义，为客户的利益，行使对证券发行人权利","证券公司行使对证券发行人的权利，感当事先征求客户的意见，并按照其意见办理","证券公司行使对证券发行人的权利，在征求客户意见时客户未表达意见的，证券公司可在行使内部审批程序后行使对发行人权利","对客户信用交易担保证券账户记录的证券，由证券公司以证券登记结算机构的名义为客户的利益行使对证券发行人的权利"],"answer":"ACD","explain":"A、D选项错误，对客户信用交易担保证券账户记录的证券，由证券公司以自己名义，为客户的利益，行使对证券发行人权利。B选项正确，证券公司行使对证券发行人的权利，应当事先征求客户的意见，并按照其意见办理。C选项错误，客户未表达意见，证券公司不得行使对发行人的权利。故本题选 ACD选项。"},{"id":"n-law1-76","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列能成为背信运用受托财产罪主体有()。","options":["保险公司","证券交易所","证券公司","商业银行"],"answer":"ABCD","explain":"背信运用受托财产罪的概念:背信运用受托财产，是指商业银行(D选项正确)、证券交易所(B选项正确)、期货交易所、证券公司(C选项正确)、期货经纪公司、保险公司 (A选项正确)或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重行为。故本题选 ABCD 选项。"},{"id":"n-law1-77","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"下列关于有限合伙企业的说法，正确约有 (21S","options":["保险公司","上市公司不得作为普通合伙人A有限各饮企业全少应当有！个曾通合代大。","有限合伙人以其认缴出资额为限承担有限责任","有限合伙企业由2个以上150个以下合伙人设立"],"answer":"ABC","explain":"A选项正确、D选项错误，除法律另有规定外，有限合伙企业由2个以上50 个以下合伙人设立(并非”150个以下”)，其中至少应当有1个普通合伙人。B选项正确，国有独资公司、国有企业、上市公司以及公益性事业单位、社会团体不得成为普通合伙人。C选项正确，普通合伙人对合伙企业债务承担无限连带责任，有限合伙人以其认缴出资额为限对合伙企业债务承担责任。故本题选 ABC选项。"},{"id":"n-law1-78","subject":"law","source":"2026.11 LC 300题","type":"多选","q":"根据《证券期货经营机构私募资产管理业务管理办法》，资产管理计划完成备案前不得开展投资活动，可以现金管理为目的，投资于()。","options":["银行活期存款","地方政府债券","股票","公开发行的公司债券"],"answer":"AB","explain":"资产管理计划完成备案前，以现金管理为目的，投资于银行活期存款(A 选项正确)、国债、中央银行票据、政策性金融债、地方政府债券(B选项正确)、货币市场基金等中国证监会认可的投资品种。故本题选 AB选项。"},{"id":"n-law1-79","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"根据《证券公司声誉风险管理指引》，证券公司声眷风险管理应邀循全程全员原则、预防第一原则、审慎管理原则、快速响应原则。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。声誉风险管理应遵循全程全员原则、预防第一原则、审慎管理原则、快速响应原则。"},{"id":"n-law1-80","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券投资顾问不得通过广播、电视、网络、报刊等公众媒体，作出买入、卖出或者持有具体证券的投资建议。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券投资顾问不得通过广播、电视、网络、报刊等公众媒体，作出买入、卖出或者持有具体证券的投资建议。"},{"id":"n-law1-81","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司应当遵循最少功能以及最小权限等原则分配信息系统管理、操作和访问权限。","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司应当遵循最少功能以及最小权限等原则分配信息系统管理、操作和访问权限，并履行审批流程。合规管理和风险管理部门应当对权限管理制度和操作流程进行合规审查及风险控制。"},{"id":"n-law1-82","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"股份有限公司的股东会会议由董事长主持，董事长、副董事长不能履行职务或者不履行职务的，由半数以上董事共同推举华名董事主持。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。股东会会议由董事会召集，董事长主持；董事长不能履行职务或者不履行职务的，由副董事长主持；副董事长不能履行职务或者不履行职务的，由过半数的董事共同推举一名董事主持。"},{"id":"n-law1-83","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"上市公司并购重组活动涉及公开发行股票，应当按照有关规定聘请具有证券经纪资格的证券公司从事相关业务。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。上市公司并购重组活动涉及公开发行股票的，应当按照有关规定聘请具有保荐资格的证券公可从事相关业务。"},{"id":"n-law1-84","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"风险覆盖率不低于 100%，资本杠杆率不低于10%。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司必须持续符合下列风险控制指标标准:(1)风险覆盖率不得低于100%；(2) 资本杠杆率不得低于8%(并非不低于 10%)；(3) 流动性覆盖率不得低于100%/(4)净稳定资金率不得低于¥100%。"},{"id":"n-law1-85","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"全国股转系统设置创新层和基础层，全国股转公司对挂牌公司实行分层管理。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。全国股转系统设置创新层和基础层，全国股转公司对挂牌公司实行分层管理。挂牌公司的分层管理包括公司申请挂牌同时进入创新层，基础层挂牌公司进入创新层，以及创新层挂牌公司调整至基础层。"},{"id":"n-law1-86","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"基金管理人有权参与清算后前财产分配。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。基金份额持有人(并非“基金管理人\")有权参与分配清算后剩余基金财产。【乐橙网提示】关于基金份额持有人享有的权利如下:(1) 分享基金财产收益。(2)参与分配清算后的剩余基金财产。(3)依法转让或者申请赎回其持有的基金份额。(4)按照规定要求召开基金份额持有人大会或者召集基金份额持有人大会。(5) 对基金份额持有人大会审议事项行使表决权。(6) 对基金管理人、基金托管人、基金服务机构损害其合法权益行为依法提起诉讼。(7) 公开募集基金的基金份额持有人有权查阅或者复制公开披露的基金信息资料；非公开募集基金的基金份额持有人对涉及自身利益的情况，有权查阅基金的财务会计账簿等财务资料。除上述权利以外，基金份额持有人还享有基金合同约定的其他权利。"},{"id":"n-law1-87","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"相关人员在成为证券公司从业人员时，其原已持有的股票或者其他具有股权性质的证券，必须依法转让。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。证券公司的从业人员在任期或者法定限期内，不得直接或者以化名、借他人名义持有、买卖股票或者其他具有股权性质的证券，也不得收受他人赠送的股票或者其他具有股权性质的证相关人员在成为证券公司的从业人员时，其原已持有的股票或者其他具有股权性质的证券，必须依法转让。"},{"id":"n-law1-88","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"为资产支持证券原始权益人利益管理专项计划财产是管理人主要职责之一。()","options":["正确","错误"],"answer":"A","explain":"本题说法错误。3获取管理人应当履行职责:为资产支持证券投资者(而非原始权益人)利益管理专项计划资A. 正确B. 错误本题说法正确。上市证券公司开展新业务和经营创新业务，应当经中国证监会批准。上市证券公司在公告董事会、股东会对拟开展新业务或者经营创新业务的决议时，应当同时向投资者进行风险提示。这说明上市证券公司要实际开展相关业务尚需要监管机构核准，且存在达不到法律法规和监管要求而导致监管机构不予核准的情形。"},{"id":"n-law1-89","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券基金经营机构应当委托提供港股投资顾问服务的香港机构直接执行投资指令。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券基金经营机构应当履行主动管理职责，自主作出投资决策，不得委托提供港股投资顾问服务的中国香港机构直接执行投资指令，证券基金经营机构作为基金管理人依法应当承担的责任不因委托而免除。"},{"id":"n-law1-90","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"公司的公积金可用于弥补公司的亏损、扩大公司生产经营或者转为增加公司注册资本。资本公积金不得用于弥补公司亏损。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。公司的公积金用于弥补公司的亏损、扩大公司生产经营或者转为增加公司注册资本。公积金弥补公司亏损，应当先使用任意公积金和法定公积金:仍不能弥补的，可以按照规定使用资本公积金(并非完全禁止)。"},{"id":"n-law1-91","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司从事财务顾问业务，需报中国证监会备案，其他证券服务机构从事财务顾问业务，需经中国证监会核准。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。依据《证券法》规定，证券公司从事财务顾问业务，需经中国证监会核准，其他证券服务机构从事财务顾问业务，应当报中国证监会备案。"},{"id":"n-law1-92","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司各部门、分支机构及子公司负责人不必承担风险管理的直接责任。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司各部门、分支机构及子公司的负责人承担本单位风险管理的直接责任。"},{"id":"n-law1-93","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司与特定交易对手方在集中交易场所之外进行的交易，证券公司应当具备从事证券经纪业务资格。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券公司进行柜台交易，应当具备中国证监会批准的与所开展业务相适应的资格条件，即证券公司为投资者交易提供服务的，感经中国证监会批准可从事证券经纪业务；证券公司与特定交易对手方进行柜台交易的，泣经中国证监会批准可从事证券自营业务(并非经纪业务资格)。"},{"id":"n-law1-94","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"合伙企业依法被宣告破产，普通合伙人对合伙企业债务仍应承担无限连带责任。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。合伙企业注销后，原普通合伙人对合伙企业存续期间的债务仍应承担无限连带责任。合伙企业不能清偿到期债务的，债权人可以依法向人民法院提出破产清算申请，也可以要求普通合伙人清偿。合伙企业依法被宣告破产的，普通合伙人对合伙企业债务仍应承担无限连带责任。"},{"id":"n-law1-95","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"不具备证券承销业务资格证券公司只能以对冲风险为目前，从事金融衍生产品交易。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。不具备证券自营业务资格证券公司只能以对冲风险为目的，从事金融衍生产品交易。"},{"id":"n-law1-96","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"公司董事会认为必要的时候，证券公司应当进行合规事项专项检查。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。公司董事会、监事会(或行使监事会职权监事或董事会设置由董事组成的审计委员会)、高级管理人员、合规负责人或合规部门认为必要的时候，证券公司应当进行专项检查。【乐橙网提示】在发生下列情形时，证券公司应当进行专项检查:(1)公司发生违法违规行为或存在合规风险隐患昀；(2)公司董事会、监事会(或行使监事会职权监事或董事会设置由董事组成的审计委员会)、高级管理人员、合规负责人或合规部门认为必要的；(3)公司下属各单位及其工作人员配合监管和稽查办案不力的；(4)监管部门或自律组织要求昀；(5) 其他有必要进行专项检查的情形。证券公司相关违法违规行为频发，应当增加合规检查频次。"},{"id":"n-law1-97","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"期货交易场所不得直接或者间接参与期货交易。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。期货交易场所不得直接或者间接参与期货交易。未经国务院批准，期货交易场所不得从事信托投资、股票投资、非自用不动产投资等与其职责无关的业务。"},{"id":"n-law1-98","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"向投资者充分提示产品或服务的信用风险、市场风险、流动性风险等可能影响投资者权益的主要风险，具体产品或服务前特别风险除外。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。证券经营机构销售产品、提供服务，应当向投资者充分披露产品或服务信息以及有助于投资者作出投资分析判断的其他信息，并向投资者充分揭示产品或服务的信用风险，市场风险、流动性风险等可能影响投资者权益的主要风险以及具体产品或服务的特别风险，并由投资者签署确认。"},{"id":"n-law1-99","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"在融资融券业务当中，融资专用资金账户是客户在指定商业银行开立的用于记载客户交存的担保资金的明细数据的账户。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。融资专用资金账户:用于存放证券公司拟向客户融出资金及客户归还的资金。客户信用资金账户:客户在指定商业银行开立的用于记载客户交存担保资金明细数据的账户。"},{"id":"n-law1-100","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"收购人及其控股股东、实际控制人利用上市公司收购，给被收购公司及其股东造成损失的，应当依法承担赔偿责任。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。收购人及其控股股东、实际控制人利用上市公司收购，给被收购公司及其股东造成损失的，应当依法承担赔偿责任。"},{"id":"n-law1-101","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"中国证监会根据证券公司分类结果对不同类别证券公司实施相同监管政策。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。中国证监会根据证券公司分类结果对不同类别证券公司实施差异化的监管政策。"},{"id":"n-law1-102","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"投资者对封闭式基金份额的买卖，只能根据基金份额上市交易规则，委托证券公司在证券交易所完成交易。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。投资者对封闭式基金份额的买卖，只能根据基金份额上市交易规则，委托证券公司在证券交易所完成交易。"},{"id":"n-law1-103","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"证券公司中，B类公司风险管理能为在行业内较高，在市场变化中能较好地控制业务扩张前风险。()","options":["正确","错误"],"answer":"A","explain":"本题说法正确。A 类公司风险管理能力在行业内最高，能较好地控制新业务、新产品方面风险；B 类公司风险管理能力在行业内较高，在市场变化中能较好地控制业务扩张风险。"},{"id":"n-law1-104","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"取得执业证书的证券投资基金销售人员辞职或者不为原聘用机构所聘用的，原聘用机构应当在上述情况发生后 10 日由协会变更该人员执业注册登记。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。登记人员离职的，证券公司应当自劳动关系或者委托代理关系解除之日起5个工作日内为其办理注销登记(并非10日)。"},{"id":"n-law1-105","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"行政重组期限一般不超过 12个月。满12个月，行政重组未完成的，可向国务院证券监督管理机构申请延长期限 12个月。()","options":["正确","错误"],"answer":"B","explain":"本题说法错误。行政重组期限一般不超过12个月。满12个月，行政重组未完成的，国务院证券监督管理机构可以决定延长行政重组期限，但延长行政重组期限最长不得超过6个月(并非”12个月\")。"},{"id":"n-law1-106","subject":"law","source":"2026.11 LC 300题","type":"判断","q":"当客户变更重要身份信息、司法机关对客户进行调查、客户涉及权威媒体案件报道等可能导致风险状况发生实质性变化的事件发生时，证券公司应考虑终止与客户委托关系。","options":["正确","错误"],"answer":"B","explain":"本题说法错误。当客户变更重要身份信息、司法机关对客户进行调查、客户涉及权威媒体的案件报道等可能导致风险状况发生实质性变化的事件发生时，证券公司应考虑重新评定客户风险等级。"},{"id":"n-law1-107","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】2021年底，国内甲证券公司担任乙股份公司保荐机构，甲证券公司按照协议全部购\n入乙公司将要发行全部股票，然后分销给其他投资者。甲证券公司承担销售和价格的全部\n风险，甲证券公司本次承销活动非常顺利，在短时间内将所承销股票全部售出。此后，甲证\n券公司以自有资金在证券市场上对乙公司股票进行买卖，并赚取了买卖差价。\n请根据上述背景信息回答以下问题。\n\n【问题】甲证券公司在承销证券时，应对公开发行募集文件()进行核查。","options":["真实性","合理性","准确性","完整性"],"answer":"ACD","explain":"证券公司承销证券，应当对公开发行募集文件的真实性、准确性、完整性进行核查(B选项错误，A、C、D 选项正确)。发现有虚假记载、误导性陈还或者重大遗漏的，不得进行销售活动。已经销售，必须立即停止销售活动，并采取纠正措施。故本题选 ACD 选项。"},{"id":"n-law1-108","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】2021年底，国内甲证券公司担任乙股份公司保荐机构，甲证券公司按照协议全部购\n入乙公司将要发行全部股票，然后分销给其他投资者。甲证券公司承担销售和价格的全部\n风险，甲证券公司本次承销活动非常顺利，在短时间内将所承销股票全部售出。此后，甲证\n券公司以自有资金在证券市场上对乙公司股票进行买卖，并赚取了买卖差价。\n请根据上述背景信息回答以下问题。\n\n【问题】甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价，证券公司在承销证券要求包括()。","options":["注册资本不低于1亿元人民币","注册资本不低于5亿元人民币","净资本不低于2亿元人民币","净资本不低于 5000万元人民币"],"answer":"BC","explain":"经营证券承销与保荐、证券融资融券、证券做市交易、证券自营、其他证券业务中两项以上的，注册资本最低限额为人民币5亿元。经营证券承销与保荐、证券自营、证券资产管理、其他证券业务中两项及两项以上的，其净资本不得低于人民币2亿元。B、C选项符合题意，本题中甲证券公司以自有资金在证券市场上对乙公司的股票进行买卖，并赚取了买卖差价，属于证券自营业务，同时甲证券公司经营证券承销业务，属于经营证券承销和自营业务两种。故本题选 BC 选项。"},{"id":"n-law1-109","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】甲证券公司担任乙公司在科创板首次公开发行股票项目的辅导、保荐机构及主承销商，\n甲证券公司在上述信息公开之日，将乙公司列入限制名单。为向网下投资者提供投资价值研\n9\n究报告的需要，甲证券公司资本市场部人员向该公司研究部门和合规部门提出申请，请求研\n究部门指派分析师跨墙参与撰写该项目的投资价值研究报告。\n请根据上还背景信息回答以下问题。\n题加微\n\n【问题】信息隔离墙制度中敏感信息管理的核心原则是()。","options":["有效性原则","准确性原则","需知原则","制衡性原则"],"answer":"C","explain":"C选项正确，“需知原则”是信息隔离墙制度中敏感信息管理的核心原则，有需要方享有知情故本题选C选项。"},{"id":"n-law1-110","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】甲证券公司担任乙公司在科创板首次公开发行股票项目的辅导、保荐机构及主承销商，\n甲证券公司在上述信息公开之日，将乙公司列入限制名单。为向网下投资者提供投资价值研\n9\n究报告的需要，甲证券公司资本市场部人员向该公司研究部门和合规部门提出申请，请求研\n究部门指派分析师跨墙参与撰写该项目的投资价值研究报告。\n请根据上还背景信息回答以下问题。\n题加微\n\n【问题】下列关于敏感信息的表述，说法正确的是()。","options":["敏感信息包括内幕信息及其他未公开信息","证券公司应当按照需知原则管理敏感信息","证券交易活动中，涉及发行人的经营、财务或者对该发行人证券的市场价格有重大影响昀尚未公开的信息为小众信息","证券公司工作人员对以任何方式知悉的敏感信息负有严格的保密义务"],"answer":"ABD","explain":"A 选项正确，敏感信息包括内慕信息及其他未公开信息。B 选项正确，证券公司应当按照需知原则管理敏感信息。C 选项错误，证券交易活动中，涉及发行人的经营、财务或者对该发行人证券的市场价格有重大影啊的尚未公开的信息，为内幕信息。D 选项正确，证券公司工作人员对以任何方式知悉的敏感信息负有严格的保密义务，不得利用敏感信息为自己或他人谋取不当利益。故本题选 ABD选项。"},{"id":"n-law1-111","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】证券公司应当树立”全员合规、合规从管理层做起、合规创造价值、合规是公司生存基\n础”理念，倡导和推进合规文化建设，培育全体工作人员合规意识，提升合规管理人员职\n业荣誉感和专业化、职业化水平。\n\n【问题】证监会要求证券公司()应当按照《证券公司和证券投资基金管理公司合规管理办法》昀要求，督促下属各单位为合规管理人员履职提供有效保障。","options":["董事会","监事会","经营管理主要负责人","下属各单位负责人确定"],"answer":"C","explain":"C选项正确，证券公司经营管理主要负责人应当对公司合规运营承担责任，支持合规负责人及合规部门工作，督促下属各单位为合规管理人员履职提供有效保障。故本题选C选项。"},{"id":"n-law1-112","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】证券公司应当树立”全员合规、合规从管理层做起、合规创造价值、合规是公司生存基\n础”理念，倡导和推进合规文化建设，培育全体工作人员合规意识，提升合规管理人员职\n业荣誉感和专业化、职业化水平。\n\n【问题】证券公司的分支机构应当配备具备()年以上证券、金融、法律、会计、信息技术等有关领域工作经历，具备与履行合规管理职责相适应的专业知识和技能的合规管理人员。","options":["1","2","3","4"],"answer":"C","explain":"C 选项正确，证券公司业务部门、分支机构应当配备具备3年以上证券、金融、法律、会计、信息技术等有关领域工作经历，具备写展行合规管理职贵相适应哟专业知识和技能的合规管理人员。故本题选C选项。"},{"id":"n-law1-113","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】证券公司应当树立”全员合规、合规从管理层做起、合规创造价值、合规是公司生存基\n础”理念，倡导和推进合规文化建设，培育全体工作人员合规意识，提升合规管理人员职\n业荣誉感和专业化、职业化水平。\n\n【问题】证券公司应当配备专职合规管理人员前部门及机构包括()。","options":["自营部门","投资银行部门","工作人员人数在10人及以上的分支机构","证券公司异地总部"],"answer":"ABD","explain":"证券公司从事自营(A选项符合题意)、投资银行(B选项符合题意)、债券等合规风险管控难度较大的业务部门、工作人员人数在15人以上的分支机构(C选项不符合题意)以及证券公司异地总部(D选项符合题意)等，应当配备专职合规管理人员。故本题选 ABD选项。"},{"id":"n-law1-114","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】甲公募基金为混合型证券投资基金，采用契约型开放式的运作方式，该基金最低募\n集份额总额为2亿份，最低募集金额总额为人民币2亿元，基金募集期为10天，发售对象\n为符合法律法规规定的可投资于证券投资基金的个人投资者、机构投资者、合格境外机构投\n资者和人民币合格境外机构投资者以及法律法规或中国证监会允许购买证券投资基金的其他\n投资人。\n\n【问题】下列关于甲公募基金运作方式的说法，正确有()","options":["甲公募基金没有固定旳存续期限","甲公募基金基金份额总额不固定","甲公募基金基金份额持有人在基金合同期限内不得申购或赎回","甲公募基金的基金份额可以在基金合同约定的时间和场所申购或者赎回"],"answer":"ABD","explain":"A 选项正确，开放式基金的基金合同期限不是固定的。B、D选项正确，开放式基金，是指基金份额总额不固定，基金份额可以在基金合同约定时间和场所申购或者赎回基金。C 选项错误，封闭式基金，是指基金份额总额在基金合同期限内固定不变，基金份额持有人不得申购或赎回的基金。故本题选 ABD 选项。"},{"id":"n-law1-115","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】甲公募基金为混合型证券投资基金，采用契约型开放式的运作方式，该基金最低募\n集份额总额为2亿份，最低募集金额总额为人民币2亿元，基金募集期为10天，发售对象\n为符合法律法规规定的可投资于证券投资基金的个人投资者、机构投资者、合格境外机构投\n资者和人民币合格境外机构投资者以及法律法规或中国证监会允许购买证券投资基金的其他\n投资人。\n\n【问题】乙公司为管理甲公募基金的基金管理公司，乙公司应当具备条件包括()。","options":["有符合《公司法》和《证券投资基金法》规定章程","取得基金从业资格的人员达到法定人数","董事、监事、高级管理人员具备相应的任职条件","注册资本不低于 5000 万元人民币，且必须为实缴资本"],"answer":"ABC","explain":"设立管理公开募集基金的基金管理公司，应当具备的条件有:①有符合《证券投资基金法》和《公司法》规定章程(A选项符合题意)；②注册资本不低于人民币1亿元，且必须为实缴货币资本(D选项不符合题意)；③主要股东应当具有经营金融业务或者管理金融机构的良好业绩、良好财务状况和社会信誉，资产规模达到国务院规定标准，最近3年没有违法记录；④取得基金从业资格人员达到法定人数(B选项符合题意)；⑤董事、监事、高级管理人员具备相应任职条件‘C 选项符合题意)；⑥有符合要求的营业场所、安全防范设施和与基金管理业务有关的其他设施；⑦有良好的内部治理结构、完善的内部稽核监控制度、风险控制制度。故本题选 ABC 选项。"},{"id":"n-law1-116","subject":"law","source":"2026.11 LC 300题","type":"案例","q":"【资料】甲公募基金为混合型证券投资基金，采用契约型开放式的运作方式，该基金最低募\n集份额总额为2亿份，最低募集金额总额为人民币2亿元，基金募集期为10天，发售对象\n为符合法律法规规定的可投资于证券投资基金的个人投资者、机构投资者、合格境外机构投\n资者和人民币合格境外机构投资者以及法律法规或中国证监会允许购买证券投资基金的其他\n投资人。\n\n【问题】甲公募基金的合格境外机构投资者是指经中国证监会批准使用来自境外的资金进行境内证券期货投资()。","options":["境外基金管理公司","境外商业银行","境外政府投资机构","境外资产评估机构"],"answer":"ABC","explain":"根据《合格境外机构投资者和人民币合格境外机构投资者境内证券期货投资管理办法》，合格境外机构投资者，是指符合该办法的规定，经中国证监会批准使用来自境外的资金进行境内证券期货投资的境外基金管理公司(A 选项正确)、商业银行(B 选项正确)、保险公司、证券公司、期货公司、信托公司、政府投资机构(C选项正确)、主权基金、养老基金、慈善基金、捐赠基金、国际组织等。D 选项错误，其中不包含境外的资产评估机构。故本题选 ABC 选项。"}]},{"id":"n-bas1","subject":"basics","name":"11月300题 · 金融卷一","stats":{"单选":40,"多选":39,"判断":30,"案例":10},"questions":[{"id":"n-bas1-0","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"以下说法错误是()。","options":["上市公司配股，原股东可以放弃配置股权","上市公司转增股本，股东权益总量和每位股东占公司比例均未发生变化","股东对股东大会作出公司合并持异议，可要求公司收购其股份","上市公司增发股票，不可以面向少数机构或个人"],"answer":"D","explain":"(1)增发指公司因业务发展需要增加资本额而发行新股。上市公司可以向公众公开增发，也可以向少数特定机构或个人增发。增发之后，公司注册资本相应增加，故本题选择“不可以面向少数机构或个人”，应该是“可以增发”。(2)配股是上市公司向原股东配售股份的行为。原股东可以参与配股，也可以放弃配股权。(3) 资本公积金转增股本是在股东权益內部，把资本公积金转入股本账户，并按照投资者所持有公司股份份额比例的大小分到各个投资者账户中，以此增加每个投资者的投入资本。股东权益总量和每位股东占公司的比例均未发生变化，唯一的变动是发行在外的股份总数增加了。(4)股票合并又被称为并股，是将若干股股票合并为1股。股东对股东大会作出的公司合并持异议，可要求公司收购其股份。"},{"id":"n-bas1-1","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"稳定的现金股利政策对公司的现金流管理有较高要求，通常把那些经营业绩较好，具有稳定且较高现金股利支付的公司股票称为()。","options":["红筹股","蓝筹股","潜力股","优先股"],"answer":"B","explain":"(1)“蓝筹股”是指证券市场上那些经营业绩较好，具有稳定且较高的现金股利支付的公司股票，故本题选择“蓝筹股”。(2) 红筹股不属于外资股。红筹股是指在中国境外注册、在香港上市，但主要业务在中国内地或大部分股东权益来自中国内地公司的股票。现在，红筹股已经成为内地企业进国际资本市场筹资的一条重要渠道。(3)优先股就是一种最常见特别股票，持有人优先于普通股股东分配公司利润和剩余财产，但参与公司决策管理等权利受到限制。"},{"id":"n-bas1-2","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列有关沪港通与沪伦通区别的说法，正确的是()。","options":["沪港通与沪伦通实现产品跨境所采用模式是不同","只有在中国境内符合要求证券经营机构可根据相关规定申请开展跨境转换业务","沪港通与沪伦通业务均已开通，目前所有有意愿投资者均可直接参与沪港通与沪伦通的","沪伦通下，投资者跨境互相到对方市场直接买卖股票，沪港通则是将境外基础股票转换为存托凭证实现产品跨境"],"answer":"A","explain":"(1) 中英两地符合要求的证券经营机构可根据相关规定申请开展跨境转换业务；(2) 目前，上交所主板上市中国存托凭证(CDR)设有一定的投资者适当性门槛，因此并非所有有意愿投资者均可直接参与沪港通与沪伦通的交易；(3) 与沪港通是投资者跨境相互到对方市场直接买卖股票的模式不同，沪伦通是将境外基础股票转换为存托凭证实现产品跨境，故本题选择“沪港通与沪伦通实现产品跨境所采用模式是不同”。"},{"id":"n-bas1-3","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"有甲、乙、丙、丁四个投资者，均申报买进X股票，申报价格和申报时间分别为:甲的买进价为10.70元，时间是13:35；乙的买进价为10.40元，时间是13:40；丙买进价为10.75元，时间为13:55；丁的买进价为10.40元，时间是13:38；则四位投资者交易的优先顺序为()。","options":["丁、乙、甲、丙","内、甲、丁、乙","丁、乙、内、甲","丙、甲、乙、丁"],"answer":"B","explain":"证券交易所内的证券竞价交易按“价格优先、时间优先”的原则撮合成交。(1) 价格优先。成交时价格优先前原则为:较高价格买入申报优先于较低价格买入申报，较低价格卖出申报优先于较高价格卖出申报。(2)时间优先。成交时间优先的原则为:买卖方向、价格相同，先申报者优先于后申报者。先后顺序按证券交易所交易主机接受申报的时间确定。先比较申报价格，可知丙的申报价格最高，甲其次，乙、丁的申报价格相同且低于丙、甲，再比较乙丁的申报时间，丁先于乙申报，所以丁应优先于乙。"},{"id":"n-bas1-4","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于科创板股票交易机制说法，错误的是()。","options":["科创板股票竞价交易实行价格涨跌幅限制，涨跌幅比例为20%，其中科创板首次公开上市的股票，上市后前5个交易日不设涨跌幅","通过市价申报买卖的，单笔申报数量应当不小于 100股，且不超过10万股","通过限价申报买卖科创板股票的，单笔申报数量应当不小于200股，且不超过10万股","科创板股票自上市首日起可作为融资融券标的"],"answer":"B","explain":"个人投资者开通科创板股票交易权限的，应当符合下列条件:(1) 申请权限开通前20个交易日证券账户及资金账户内的资产均不低于人民币50万元(不包括该投资者通过融资融券融入资金和证券)；(2)参与证券交易24个月以上；(3) 上海证券交易所规定的其他条件。机构投资者参与科创板股票交易，应当符合法律法规及上海证券交易所业务规则的规定。通过限价申报买卖科创板股票，单笔申报数量应当不小于 200股，且不超过 10万股:通过市价申报买卖的，单笔申报数量应当不小于 200股，且不超过5万股。卖出时，余额不足200股的部分，应当一次性申报卖出。"},{"id":"n-bas1-5","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"普通股股东行使剩余资产分配权时需要的先决条件是()。","options":["必须是在公司正常经营时","必须是在公司解散清算时","晋通股股东必须持股一年以上","普通股股东要求分配公司资产权利是任意"],"answer":"B","explain":"普通股股东行使剩余资产分配权有一定昀先决条件。第一，普通股股东要求分配公司资产权利的时点必须是在公司解散清算之时。第二，我国《公司法》规定，公司财产在分别支付清算费用、职工工资、社会保险费用和法定补偿金，缴纳所欠税款，清偿公司债务后剩余财产，股份有限公司按照股东持有股份比例分配。公司财产在未依照前款规定清偿前，不得分配给股东。"},{"id":"n-bas1-6","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"深港通中深股通起始额度为每日()亿元人民币。","options":["必须是在公司正常经营时","必须是在公司解散清算时"],"answer":"B","explain":"(1) ①沪股通起始额度为每日130亿元人民币。2018年5月1日起，沪股通每日额度调整为520 亿元人民币。②沪港通下的港股通起始额度为每日105亿元人民币。2018年5月1日起，沪港通下港股通每日额度调整为420亿元人民币。(2) ①深股通起始额度每日130亿元人民币。2018年5月1日起，深股通每日额度调整为520亿元人民币。②深港通下港股通起始额度每日 105亿元人民币。2018年5月1日起，深港通下港股通每日额度调整为420亿元人民币。故本题选择“130”。"},{"id":"n-bas1-7","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"首次公开发行股票并在主板上市情形下，发行人应满足条件不包括()。","options":["最近三年内主营业务没有发生重大变化","最近三年内实际控制人没有发生变更","最近三年内监事没有发生重大变化","最近三年内董事没有发生重大变化"],"answer":"C","explain":"首次公开发行股票并在主板上市的规定首次公开发行股票并上市应满足以下条件:(1) 发行人依法设立且持续经营时间在三年以上的股份有限公司，但经国务院批准的除外。(2) 发行人最近三年内主营业务和董事、高级管理人员没有发生重大变化，实际控制人没有发生变更，故本题选择“监事没有发生重大变化”，不包括“监事”。(3) 最近三个会计年度净利润均为正数且累计超过人民币 3000万元，净利润以扣除非经常性损益前后较低者为计算依据。(4)国务院规定其他情形。"},{"id":"n-bas1-8","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于股票退市制度的说法，错误的是()。","options":["科创板上市公司股票被终止上市的，可申请重新上市","股票退市包括主动退市和强制退市","股票退市制度有利于健全资本市场功能","股票退市制度有利于增强市场主体活力，提高市场竞争力"],"answer":"A","explain":""},{"id":"n-bas1-9","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于证券委托的说法，错误是()。","options":["柜台委托必须由委托人亲自到证券营业部交易柜台填写委托单","非柜台委托包括人工电话委托或传真委托、自助和电话自动委托、网上委托等形式","投资者在证券交易所买卖证券，是通过委托证券经纪商来进行的","证券委托可以分为柜台委托和非柜台委托两大类"],"answer":"A","explain":"投资者在证券交易所买卖证券，是通过委托证券经纪商来进行，需要向证券经纪商下达委托指令。证券委托可以分为柜台委托和非柜台委托两大类。①非柜台委托主要有人工电话委托或传真委托、自助和电话自动委托、网上委托等形式。②柜台委托是指委托人亲自或由其代理人到证券营业部交易柜台，根据委托程序和必需的证件采用书面方式表达委托意向，由本人填写委托单并签章形式，故本题选择“柜台委托必须由委托人亲自”表述错误，应该是“亲自或由其代理人”。"},{"id":"n-bas1-10","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"如果是具有法人资格的国有企业，事业单位及其单位以其依法占用的法人资产向独立于自己的股份公司出资形成或依法定程序取得股份，可称为()。","options":["国有法人股","国家股","外资股","法人股"],"answer":"A","explain":"法人股是指企业法人或具有法人资格事业单位和社会团体以其依法可支配资产投入公司形成约股份，法入持股所形成哟也是所有权关家，是法人经营自身财产哟一种投资行为。法人股股票以法人记名。如果是具有法人资格的国有企业、事业单位及其他单位以其依法占用的法人资产向独立于自己的股份公司出资形成或依法定程序取得股份，则被称为“国有法人股”。国有法人股属于国有股权。"},{"id":"n-bas1-11","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"股利收入由国有资产管理部门监督收缴，依法纳入国有资产经营预算，并根据国家有关规定安排使用的股票类型为()。","options":["国有股","外资股","社会公众股","法人股"],"answer":"A","explain":"国家股是国有股权一个组成部分(国有股权另一组成部分是国有法人股)。国有资产管理部门是国有股权行政管理的专职机构。国有股权可由国家授权投资的机构持有，也可由国有资产管理部门持有或由国有资产管理部门代政府委托其他机构或部门持有。国有股股利收入由国有资产管理部门监督收缴，依法纳入国有资产经营预算，并根据国家有关规定安排使用。国家股股权可以转让，但转让应符合国家有关规定。"},{"id":"n-bas1-12","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"在我国，H股、N股、S股等为()白简称。","options":["境内上市外资股","社会公众股","红筹股","境外上市外资股"],"answer":"D","explain":""},{"id":"n-bas1-13","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"一般情况下，股份分割能够刺激公司股票上涨，其原因是()，","options":["所有的股份分割对公司股票都是利好","投资者持有的股份数量增加，预期将会获得更多的股利","股份分割后公司股东获得的实际股利多了","股份分割后公司的净资产比原来多了"],"answer":"B","explain":"股份分割，又被称为拆股或拆细，是将原有股份均等地拆成若干较小股份。股份分割一般在年度决算月份进行，通常会刺激股价上升。股份分割给投资者带来的不是现实的利益，因为股份分割前后投资者持有的公司净资产和以前一样，得到股利也相同，但是，投资者持有的股份数量增加了，给投资者带来了今后可多分股利和更高收益的预期，因此，股份分割往往比增加股利分配对股价上涨的刺激作用更大。"},{"id":"n-bas1-14","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"非累积优先股票的特点是股息分派以()为界，当年结清。","options":["每个经营周期","每个会计年度","每个产业周期","每个生产周期"],"answer":"B","explain":"根据公司因当年可分配利润不足而未向优先股股东足额派发股息，差额部分是否累积到下一会计年度，可分为累积优先股和非累积优先股。累积优先股是指公司在某一时期所获盈利不足，导致当年可分配利润不足以支付优先股股息时。则将应付股息累积到次年或以后某一年盈利时，在普通股的股息发放之前，连同本年优先股股息一并发放。非累积优先股则是指公可不足以支付优先股的全部股息时，对所欠股息部分，优先股股东不能要求公司在以后年度补发。故本题选B。"},{"id":"n-bas1-15","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"对股份有限公司而言，之所以发行优先股票可以减轻其利润的分派负担，是因为()。","options":["优先股股东无表决权","优先股股东股息分派优先","优先股股东剩余资产分配优先","优先股股息率固定"],"answer":"D","explain":"对股份公司而言，发行优先股的作用在于可以筹集长期稳定的公司股本，由因其股息率固定，可以减轻利润的分派负担。"},{"id":"n-bas1-16","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"在报价驱动中，做市商收入来源是()。","options":["买卖证券的差价","手续费、佣金收入","股息收入","投资收入"],"answer":"A","explain":"报价驱动机制是一种连续交易商市场，或称“做市商市场”。在这一市场中，买价和卖价都由做市商给出，做市商将根据市场的买卖力量和自身情况进行证券双向报价。投资者之间并不直接成交，而是从做市商手中买进证券或向做市商卖出证券。做市商的收入来源是买卖证券的差价。"},{"id":"n-bas1-17","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于证券托管制度说法，错误是()。","options":["全面指定交易制度下，投资者应当与指定交易的会员签订指定交易协议，明确双方的权利、义务和贡任","全面指定交易制度下，投资者可以以同、证券账户在单个或多个会员的不同证券营业部买入证券","上海证券交易所证券交易实行全面指定交易制度，境外投资者从事B股交易除外","深圳证券交易所交易证券托管制度可概括为自动托管、随处通买、哪买哪卖、转托不限"],"answer":"B","explain":"(1)上海证券交易所证券交易实行全面指定交易制度，境外投资者从事B股交易除外。(2)全面指定交易是指参与上海证券交易所证券买卖投资者必须事先指定一家会员作为其买卖证券的受托人，通过该会员参与本所市场证券买卖。投资者应当与指定交易会员签订指定交易协议，明确双方的权利、义务和责任。(3)深圳证券交易所交易证券托管制度可概括为:自动托管，随处通买，哪买哪卖，转托不限。(4) 深圳证券市场中，投资者可以以同一证券账户在单个或多个会员的不同证券营业部买入证券。故“全面指定交易制度下，投资者可以以同一证券账户”表述错误，全面指定交易制度指的是上海交易所。"},{"id":"n-bas1-18","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"商业银行次级定期债务前募集方式为商业银行向()定向募集。","options":["机关法人","社团法人","事业法人","企业法人"],"answer":"D","explain":"根据原中国银监会于2003年发布的《关于将次级定期债务计入附属资本通知》，次级债务是指由银行发行，固定期限不低于5年(含5年)5°除非银行倒闲或清算，不用于弥补银行日常经营损失，且该项债务的索偿权排在存款和其他负债之后的商业银行长期债务。次级定期债务募集方式为商业银行向目标债权人定向募集，目标债权人为企业法人。商业银行不得向目标债权人指派，不得在对外营销中使用“储蓄”字样。次级定期债务不得与其他债权相抵销:原则上不得转让。提前赎回。特殊情况，由商业银行报原中国银监会审批。商业银行应当对次级定期债务进行必要的披露。"},{"id":"n-bas1-19","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"非公开发行公司债券应当向合格投资者发行，不得采用广告、公开劝诱和变相公开方式，每次发行对象不得超过()人。","options":["50","社团法人","事业法人"],"answer":"C","explain":"非公开发行公司债券应当向合格投资者发行，不得采用广告、公开劝诱和变相公开方式，每次发行对象不得超过 200人，故本题选择“200”。"},{"id":"n-bas1-20","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"按内含选择权的不同，公司债券分类不包括 ()。","options":["可转换公司债券","附认股权证公司债券","信用公司债券","可交换公司债券"],"answer":"C","explain":"公司债券是指公司依照法定程序发行的、约定在一定期限还本付息的有价证券，反映发行债券的公司和债券投资者之间的债权债务关系。常见的分类包括:(1)按担保抵押情况分为信用公司债券、不动产抵押公司债券、保证公司债券；(2) 按付息方式的不同分为普通公司债券和收益公司债券；(3)按内含选择权的不同分为可转换公司债券、附认股权证的公司债券(包括分离交易可转换公司债券)、可交换公司债券；(4) 按是否记名可分为记名公司债券和不记名公司债券；(5) 按持有人是否参加公司利润分配可分为参加公司债券和非参加公司债券；(6) 按是否可提前赎回可分为可提前赎回公司债券和不可提前赎回公司债券；(7) 按发行方式可分为公募公司债券和私募公司债券等。"},{"id":"n-bas1-21","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于国际开发机构人民币债券说法中，错误的是()。","options":["在中国境内申请发行人民币债券的国际开发机构应向财政部等窗口单位递交债券发行申请，由窗口单位会同中国人民银行、国家发改委、中国证监会等部门审核后，报国务院同意","国家发改委会同财政部，根据国家产业政策、外资外债情况、宏观经济和国际收支状况，对人民币债券的发行规模及所筹资金用途进行审核","中国人民银行对人民币债券发行利率进行管理","国际开发机构人民币债券，是指国际开发机构依法在中国境外发行的、约定在一定期限内还本付息的、以人民币计价的债券"],"answer":"D","explain":"(1)国际开发机构人民币债券是指国际开发机构依法在中国境内发行的、约定在一定期限内还本付息的、以人民币计价的债券。(2)在中国境内申请发行人民币债券的国际开发机构应向财政部等窗口单位递交债券发行申，由窗口单位会同中国人民银行、国家发改委、中国证监会等部门审核后，报国务院同意。(3) 中国人民银行对人民币债券发行利率进行管理。(4)国家发改委会同财政部，根据国家产业政策、外资外债情况、宏观经济和国际收支状况，对人民币债券发行规模及所筹资金用途进行审核。"},{"id":"n-bas1-22","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"国际债券的发行对象主要是()。","options":["外国投资者","本国外币持有者","本国自然人投资者","本国金融机构"],"answer":"A","explain":"国际债券是指一国借款人在国际证券市场上以外国货币为面值、向外国投资者发行债券。故本题选择“外国投资者”。"},{"id":"n-bas1-23","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"国际债券在国际市场上发行，其计价货币往往是国际通用货币，一般不用()。","options":["美元","欧元","人民币","英镑"],"answer":"C","explain":"国际债券在国际市场发行，所以计价货币是国际通用货币。一般以美元、英镑、欧元、日元和瑞士法郎为主。"},{"id":"n-bas1-24","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"我国的混合资本债券的清偿顺序是()。","options":["位于股权资本之后","位于次级债务之前","位于一般债务之前","位于一般债务和次级债务之后"],"answer":"D","explain":"混合资本债券是指商业银行为补充附属资本发行的、清偿顺序位于股权资本之前但列在一般债务和次级债务之后、期限在15年以上、发行之日起10年内不可赎回的债券。故本题选择“位于一般债务和次级债务之后”。【补充考点】1.商业银行发行混合资本债券应具备的条件与其发行金融债券完全相同。商业银行发行金融债券应具备以下条件:(1)具有良好公司治理机制:核心资本充足率不低于4%:最近3年连续盈利；(2)贷款损失准备计提充足；(3)风险监管指标符合监管机构的有关规定；(4)最近3年没有重大违法、违规行为；(5)中国人民银行要求其他条"},{"id":"n-bas1-25","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"不能发行金融债券的主体是()。","options":["政策性银行","国有商业银行","证券公司","中国人民银行"],"answer":"D","explain":""},{"id":"n-bas1-26","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于可转换债券发行主体说法，正确是()。","options":["可转换债券的发行主体是上市公司的股东","可转换债券的发行主体是上市公司的关联公司","可转换债券的发行主体是上市公司的子公司","可转换债券的发行主体是上市公司本身"],"answer":"D","explain":"可交换债券与可转换债券具有类似的特征，也有以下明显的区别:(1) 发行主体不同。可交换债券发行主体是上市公司股东，而可转换债券发行主体是上市公司本身。(2)用于转股的股份来源不同。可交换债券的股份来源是发行人持有的其他公司己发行在外股份，而可转换债券的股份来源通常是发行人本身未来将发行的新股。(3)转股对公司股本的影响不同。可转换债券的转股会使标的股票总股本扩大，而可交换债券转股不会影响标的股票总股本的数量。"},{"id":"n-bas1-27","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"某可转换债券面额为1000元，转换价格为25元/股，标的股票的内在价值30元/股，市场价格为32元/股，则转换比例为()。","options":["40","42","33","31"],"answer":"A","explain":"转换比例是指一定面额可转换债券可转换成普通股票的股数。用公式表示为:转换比例=可转换债券面值/转换价格。转换价格是指可转换债券转换为每股普通股份所支付的价格。转换比例=1000/25=40。题干中的内在价值和市场价格属于干扰项。"},{"id":"n-bas1-28","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"为利用国外资金，加快我国的建设步伐，我国积极利用国际债券市场筹集资金，发行主要债券品种不包括 ()。","options":["政府债券","企业债券","金融债券","公司债券"],"answer":"B","explain":"获取在改革开放政策的指导下，为利用国外资金，加快我国的建设步伐，我国开始利用国际债券可够您業好金，主爱柠務品种，没师代参。没活能务用公司好务。從本過主择-金业馆"},{"id":"n-bas1-29","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列不属于目前我国国债期限种类是()。","options":["15年","7年","1年","6个月"],"answer":"A","explain":"我国国债期限种类包括3个月、6个月、1年、2年、3年、5年、7年、10年、30年和50年期，期限结构较为完善，故本题选择“15年”。其中，1年、3年、5年、7年、10年为关键期限国债，实现每月一次发行。"},{"id":"n-bas1-30","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于中小企业集合债券的说法，错误的是()。","options":["使用统一债券名称","由当地政府职能部门确定各个企业的发行额度","多个中小企业构成联合发行主体","由当地政府职能部门作为牵头人组织"],"answer":"B","explain":"中小企业集合债券是指同一区域内由当地政府国资部门等政府职能部门作为牵头人组织、以多个中小企业构成联合发行主体，若干个中小企业各自确定债券发行额度，釆用集合债券形式，使用统一的债券名称，形成一个总发行额度而发行的约定到期还本付息一种企业债券，故本题选择“由当地政府职能部门确定各个企业的发行额度”，应该是“中小企业各自确定债券发行额度”。"},{"id":"n-bas1-31","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于银行间债券市场与交易所债券市场的说法，错误是()。","options":["交易所债券市场实行“中央登记、一级托管”制度","银行间债券市场实行一级、二级综合托管账户模式","银行间债券市场均采用实时全额逐笔结算机制","交易所债券市场采用中央对手分净额结算机制"],"answer":"A","explain":""},{"id":"n-bas1-32","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列有关国债销售的说法，错误是()","options":["国债销售的价格一般不应低于承销商与发行人的结算价格，反之，承销商就有可能发生亏","市场利率趋于上升，就为承销商确定国债销售价格拓宽了空间","降低销售价格，承销商的分销过程会缩短，资金的回收速度会加快","如果国债承销价格定价过高，投资者就会倾向于在二级市场上购买己流通的国债，从而阻碍国债分销工作顺利进行"],"answer":"B","explain":"3获取影响国债销售价格因素:(1) 市场利率。市场利率的高低及其变化对国债销售价格起着显著的导向作用。市场利率趋于上开，就限制了承销商确定销售价格的空间:市场利率趋于下降，就为承销商确定销售价格拓宽了空间，故本题选择“市场利率趋于上升”。(2)承销商承销国债的中标成本。国债销售的价格一般不应低于承销商与发行人结算价格。反之，就有可能发生亏损。(3) 流通市场中可比国债的收益类水平。如果国债承销价格定价过高，即收益率过低，投资者就会倾向于在二级市场上购买已流通的国债，而不是直接购买新发行的国债。(4)国债承销的手续费收入。在国债承销中，承销商可获得其承销金额一定比例的手续费收入。由于该项手续费收入的存在，为了促进分销活动，承销商有可能压低销售价格。(5)承销商所期望的资金回收速度。降低销售价格，承销商的分销过程会缩短，资金回收速度会加快，承销商可以降低总成本，提高收益。(6) 其他国债分销过程中的成本。"},{"id":"n-bas1-33","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于债券报价的说法，错误是()。","options":["债券买卖交易中有公开报价、对话报价、双边报价和小额报价四种报价方式","双边报价是交易所债券市场开展双边报价业务的交易员进行现券买卖报价时，在任意债券买卖差价范围内连续报出该券种的买卖实价","对话报价是指参与者为达成交易而直接向交易对手方作出的、对手方确认即可成交的报价","公开报价是指参与者为表明自身交易意向而面向市场做出、不可直接确认成交的报价"],"answer":"B","explain":"(1) 对话报价是指参与者为达成交易而直接向交易对手方作出、对手方确认即可成交报价。(2)双边报价是银行间债券市场开展双边报价业务交易员进行现券买卖报价时，在中国人民银行核定债券买卖差价范围内连续报出该券种的买卖实价，并同时报出该券种的买卖数量、清算速度等交易要素。(3)公开报价是指参与者为表明自身交易意向而面向市场作出的、不可直接确认成交报(4)小额报价是在交易系统中，一次报价、规定交易数量范围和对手范围的现券单向撮合交易方式。"},{"id":"n-bas1-34","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"2011年3月31日，财政部发行的某期国债距到期日还有3年，面值100元，票面利率年息4.15%，每年付息1次，下次付息日在1年以后。1年期、2年期、3年期贴现率分别为4%、4.5%、5%。则该债券理论价格为()。","options":["98.75元","96.66元","97.76元","96.76元"],"answer":"C","explain":"该国债是固定利率债券，每年的利息(现金流金额)C=面值 M*票面利率=100＊4.15%=4.15元。债券理论价格 P=C/(1+y1)1+C/(1+y2)^2+.....+ (C+M)／ (1+yt)^t=4.15/ (1+4%)^1+4.15/(1+4.5%)2+(4.15+100)／(1+5%)^3=97.76元。P-债券理论价格；七-期数；C-现金流金额；y-贴现率(通常为年利率)，^-多少次方。"},{"id":"n-bas1-35","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于债券贴现率的说法，错误是()。","options":["真实无风险收益率理论上由社会资本平均回报率决定","预期通货膨胀率是对未来通货膨胀率的估计值","债券的贴现率是投资者对该债券要求的最低回报率，也被称为必要回报率","债券必要回报率=真实无风险收益率+预期通货膨胀率"],"answer":"D","explain":"(1)债券的贴现率是投资者对该债券要求的最低回报率，也被称为必要回报率；(2)真实无风险收益率理论上由社会资本平均回报率决定；(3) 预期通货膨胀率是对未来通货膨胀率的估计值，预期通货膨胀率上升，相当于降低了债券实际利率，引起债券相对预期回报率的下降。(4)必要回报率公式为:债券必要回报率=真实无风险收益率+预期通货膨胀率+风险溢价。本题选择 “债券必要回报率=真实无风险收益率+预期通货膨胀率”，少了“风险溢价”。"},{"id":"n-bas1-36","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"发行價券筹措商發金属于公司約()，发行股票筹资资金属于公司的()。","options":["负债、负债","负债、资本","资本、负债","资本、资本"],"answer":"B","explain":"发行债券获取的资金属于公司的负债，不是资本金，有偿还的义务。发行股票筹措的资金列入公司资本，是股份公司创立和增加资本的需要。"},{"id":"n-bas1-37","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"债券代表了一定财产价值，它是一种()。","options":["固定资本","实收资本","虚拟资本","流动资本"],"answer":"C","explain":"债券是一种虚拟资本。债券尽管有面值，代表了一定的财产价值，但它也只是一种虚拟资本，而非真实资本。"},{"id":"n-bas1-38","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"某公司发行的银行间债券市场中长期债信用评级为A，其含义是()。","options":["偿还债务的能力很差，不受不利经济环境的影响，违约风险很低","偿还债务的能力一般，受不利经济环境的影响较大，违约风险一般","偿还债务的能力极强，基本不受不利经济环境影响，违约风险极低","偿还债务能力较强，较易受不利经济环境影响，违约风险较低"],"answer":"D","explain":"银行间债券市场中长期债券信用评级，等级划分为三等九级，符号表示为:AAA、AA、A、BBB、BB、B、cCC、CC、C。"},{"id":"n-bas1-39","subject":"basics","source":"2026.11 LC 300题","type":"单选","q":"下列关于债券评级的说法，错误的是()。","options":["债券信用评级是为投资者购买债券和证券市场债券的流通转让活动提供信息服务","债券信用评级是对具有独立法人资格企业所发行某一特定债券、按期还本付息的可靠程度进行客观公正的评估，并表示其信用程度等级","国家财政发行的国库券和国家政策性银行发行的金融债券也参加债券信用评级","债券信用评级是以企业或经济主体发行的有价债券为对象进行的信用评级"],"answer":"C","explain":"①债券信用评级是以企业或经济主体发行的有价债券为对象进行的信用评级。②债券信用评级大多是企业债券信用评级，是对具有独立法人资格企业所发行某一特定债券、按期还本付息的可靠程度进行客观公正的评估，并表示其信用程度的等级。这种信用评级，是为投资者购买债券和证券市场债券的流通转让活动提供信息服务。③国家财政部门发行的国库券和国家政策性银行发行的金融债券，因为有政府的保证，所以不参加债券信用评级。地方政府或非国家银行金融机构发行的某些有价证券，则有必要进行评级。"},{"id":"n-bas1-40","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"宏观经济发展水平和状况是影响股票价格的重要因素，宏观经济影响股票价格特点有()。信XS","options":["波及范围广","干扰程度深","作用机制复杂","可能导致股价波动幅度大"],"answer":"ABCD","explain":"宏观经济发展水平和状况是影响股票价格的重要因素。宏观经济对股票价格影响的特点是波及范围广、干扰程度深、作用机制复杂并可能导致股价波动幅度较大。"},{"id":"n-bas1-41","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于优先股、普通股和可转债区别的说法，错误的有()。","options":["相对于普通股股东，优先股股东在公司利润分配上享有优先权","普通股没有到期的概念，绝大多数优先股需要到期还本付息","优先股的股息一般来自税前利润，而普通股股息来自可分配税后利润","与可转债相比，优先股没有固定期限，且未必含有转股条款"],"answer":"AD","explain":"优先股和债券的区别如下:第一，两者的根本区别在于其法律属性不同，优先股的法律属性还属于股票。根据我国现行的会计准则和国际做法，发行人优先股作为权益或者负债入账需要由公司和会计师视优先股的不同条款，对是否符合负债或权益的本质进行判断，所以不能说统一作为权益入账。第二，优先股没有到期的概念，发行人没有偿还本金的压力。第三，在公司出现亏损或者利润不足支付优先股股息时，优先股股东具有相应的保障机制。第四，优先股的股息一般来自可分配税后利润，而债券的利息来自税前利润。从风险角度来说，优先股的股息收益不确定性大于债券。A. 上市公司的一些重大事项未及时向社会公布B.在目己买不控制的天公开明账尸之目进行交易C. 证券交易中的欺诈行为D. 上市公司董事长发生变动未向社会披路公开原则又被称为信息公开原则，指证券交易是一种面向社会旳、公开交易活动，其核心要求是实现市场信息的公开化。公平原则是指参与交易的各方应当获得平等的机会。它要求证券交易活动中的所有参与者都有平等的法律地位，各自的合法权益都能得到公平保护。公正原则是指应当公正地对待证券交易的参与各方，以及公正地处理证券交易事务。"},{"id":"n-bas1-42","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于商业银行次级债务的说法，正确的有()。","options":["固定期限不低于5年(含5年)","发行须向中国银保监会提出申请","目标债权人可为自然人","索偿权排在存款和其他负债之后"],"answer":"ABD","explain":"(1)根据原中国银监会于2003年发布的《关于将次级定期债务计入附属资本通知》，次级债务是指由银行发行，固定期限不低于5年(含5年)，除非银行倒闲或清算，不用于弥补银行日常经营损失，且该项债务的索偿权排在存款和其他负债之后的商业银行长期债务。次级定期债务的募集方式为商业银行向目标债权人定向募集，目标债权人为企业法人。(2) 商业银行不得向目标债权人指派，不得在对外营销中使用“储蓄”字样。次级定期债务不得与其他债权相抵销:原则上不得转让、提前赎回。特殊情况，由商业银行报原中国银监会审批。商业银行应当对次级定期债务进行必要的披露。"},{"id":"n-bas1-43","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"证券公司发行债券，应当按照《公司法》或者公司章程相关规定，对重要事项作出决议，包括()。","options":["发行债券的金额","债券评级","债券期限","募集资金用途"],"answer":"ACD","explain":"发行公司债券，发行人应当按照《公司法》或者公司章程相关规定对以下事项作出决议:发行债券的金额:发行方式:债券期限:募集资金的用途:其他按照法律法规及公司章程规定需要明确的事项。"},{"id":"n-bas1-44","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"商业银行发行混合债券应该具备条件有()。","options":["核心资本充足率不低于 3%，最近3年连续盈利","具备良好的公司治理机制","货款损失准备计提充足","最近3年没有重大违法违规行为"],"answer":"BCD","explain":"商业银行发行混合资本债券应具备的条件与其发行金融债券完全相同。应具备以下条件:具有良好的公司治理机制:核心资本充足率不低于 4%:最近3年连续盈利:贷款损失准备计提充足:风险监管指标符合监管机构的有关规定:最近3年没有重大违法、违规行为:中国人民银行要求的其他条件。但商业银行发行混合资本债券应向中国人民银行报送的发行申请文件，除了包括其发行金融债券的内容之外，还应同时报送近3年按监管部门要求计算的资本充足率信息和其他债务本息偿付情况。"},{"id":"n-bas1-45","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"影响利率的期限结构形状因素有()。","options":["对未来利率变动方向预期","债券预期收益中可能存在流动性溢价","如果预期利率下降较多，其利率期限结构是向上倾斜白","市场效率低下或者资金从长期(或短期)市场向短期〈或长期)市场流动可能存在約隊碍"],"answer":"ABD","explain":"(1) 市场预期理论又被称为无偏预期理论，认为利率期限结构完全取决于对未来即期利率的市场预期。如果预期未来即期利率上升，则利率期限结构呈上升趋势；如果预期未来即期利率下降，则利率期限结构呈下降趋势。(2) 在任一时点上，都有以不三种因素影响期限结构的形状:对未来利率变动方向的预期、债券预期收益中可能存在的流动性溢价、市场效率低下或者资金从长期(或短期)市场向短期(或长期)市场流动可能存在的障碍。利率期限结构理论就是基于这三种因素分别建立起来的。"},{"id":"n-bas1-46","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列属于我国发行的国债品种的有()。","options":["普通国债","特别国债","长期建设国债","无期国债"],"answer":"ABC","explain":"我国政府除了有规律性地发行适度规模的普通型国债包括记账式国债、储蓄国债(凭证式)、储蓄国债(电子式)以外，还不定期地发行一定数量的其他类型国债。其他类型国债主要有国家重点建设债券、国家建设债券、财政债券、特种债券、保值债券、基本建设债券、特别国债、长期建设国债等。"},{"id":"n-bas1-47","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"企业资产证券化的基础资产可以有()。","options":["基础设施收费权","棚户区改造","小额贷款","租赁资产"],"answer":"ACD","explain":"3S相设因政府做务网性、现金流不能定装报浙货面游帮非条。其余三爱构为当前企业 A0S主流合规基础资产。"},{"id":"n-bas1-48","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"债券报价主要方式包括()。","options":["公开报价","对话报价","净额报价","双边报价"],"answer":"ABD","explain":"(1)债券买卖交易中有“公开报价”、“对话报价”、“双边报价”和“小额报价”四种报价方式，前两者属于询价交易方式的范畴，后两者可通过点击确认、单向撮合的方式成交。(2)债券交易的竞价方式:证券交易所的交易价格按竞价的方式进行。竞价方式包括口头报唱、板牌竞价以及计算机终端申报竞价三种。"},{"id":"n-bas1-49","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"债券与股票不同之处包括()。","options":["权利不同","目的不同","期限不同","收益不同"],"answer":"ABCD","explain":"债券和股票区别:(1) 权利不同。债券是债权凭证，债券持有者与债券发行人之间的经济关系是债权债务关系。股票是所有权凭证，股票所有者是发行股票公司的股东，股东一般拥有表决权，可以行使对公司的经营决策权和监督权。(2)目的不同。发行债券获取的资金属于公司的负债，有偿还义务。发行股票筹措的资金列入公司资本。(3) 主体不同。发行债券的经济主体很多，但能发行股票经济主体只有股份有限公司。(4)期限不同。债券一般有规定的偿还期，是一种有期证券。股票通常是无须偿还，是一种无期证券，或被称为永久证券(5)收益不同。债券通常有规定的票面利率，可获得固定的利息。股票的股息红利不固定，一般视公司经营情况而定。《(6)风险不同。股票风险较大，债券风险相对较小。"},{"id":"n-bas1-50","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"政府债券发行主体有()。","options":["中央政府","地方政府","中央国有大型企业","地方国有大型企业"],"answer":"AB","explain":"政府债券是指政府财政部门或其他代理机构为筹集资金，以政府名义发行的、承诺在一定时期支付利息和到期还本的债务凭证。中央政府发行的债券被称为中央政府债券或者国债，地方政府发行的债券被称为地方政府债券，有时二者被统称为公债。"},{"id":"n-bas1-51","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"资产证券化的参与主体包括()。","options":["发起人","承销商","服务商","受托人、保荐人"],"answer":"ABC","explain":"3获取资产证券化的参与主体包括:发起人、特殊目的机构。信用增级机构、信用评级机构、承销商、服务商、受托人。"},{"id":"n-bas1-52","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于资产支持证券说法，正确的有()。","options":["资产支持证券是以资产池为发行证券基础","欧美市场资产证券化发展较为成熟","信用卡贷款、汽车货款均能证券化","企业的债权资产不能进行证券化"],"answer":"ABC","explain":""},{"id":"n-bas1-53","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"中国证监会通过内部基金监管部门具体实施监管包括()。","options":["基金市场准入监管","日常持续监管","基金交易监管","基金信息披露监管"],"answer":"AB","explain":"中国证监会通过内部基金监管部门具体施行基金市场准入监管与日常持续监管。(1) 市场准入监管主要指对基金从业机构资格审核，通过严格的市场准入，从源头上控制整个行业运作风险，提高行业服务水平。(2) 日常持续监管一般是对基金从业机构日常经营活动、相关人员从业行为、基金运作各环节的监管。"},{"id":"n-bas1-54","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"关于基金投资风格，下列说法正确的有()。","options":["分析投资风格便于准确评价基金业绩","投资人了解和考察其资产的投资风格非常重要","通过对基金投资风格的分析，有助于投资者选择适合自己风险偏好的投资品种","投资风格并不影响风险与收益水平"],"answer":"ABC","explain":""},{"id":"n-bas1-55","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"关于对基金机构的监管，下列说法正确的有()。","options":["基金托管人可由依法设立的商业银行担任","非金融机构经中国证监会核准，可以成为基金托管人","从事公募基金服务业务机构应按照中国证监会的规定进行注册或备案","公募基金基金管理人只能由基金管理公司或中国证监会按照规定核准的其他机构担任"],"answer":"ACD","explain":"对基金机构的监管包括对基金管理人、基金托管人、基金销售机构等的监管。"},{"id":"n-bas1-56","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"应按照中国证监会的规定进行注册或者备案公募基金服务业务机构有()。","options":["从事基金销售的机构","从事基金销售支付机构","从事公募基金估值、投资顾问业务机构","从事公募基金评价的服务机构"],"answer":"ABCD","explain":"基金市场上还有许多面向基金提供各类服务的其他服务机构。这些机构主要包括基金销售机构、基金销售支付机构、基金份额登记机构、基金估值核算机构、基金投资顾问机构、基金评价机构、律师事务所、会计师事务所、信息技术系统服务机构等。从事基金服务业务机构，应当按照国务院证券监督管理机构的规定进行注册或者备案。"},{"id":"n-bas1-57","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"关于基金业绩评估时所须考虑的因素，下列说法正确的有()。","options":["投资目标和范围不同的基金，其投资策略和业绩比较基准都可能不同","市场上一些平均收益率高基金，一定与基金经理的能力相关","与小规模基金相比，规模较大基金的诸如研究费用的平均成本更低","同一基金在不同时间段内表现可能会有很大差距"],"answer":"ACD","explain":"系统的基金业绩评估需要从四个方面入手:计算绝对收益:计算风险调整后收益:计算相对收益:进行业绩归因。进行基金业绩评价不能仅看回报率，以下因素必须加以考虑。(1)投资目标与范围，投资目标与范围不同的基金，其投资策略、业绩比较基准都可能不(2) 基金风险水平，根据风险报酬理论，投资收益是由投资风险驱动，风险越大，所要求的报酬率就越高。(3) 基金规模，与小规模基金相比，规模较大的基金的平均成本更低。(4) 时期选择，同一基金在不同时间段内的表现可能有很大的差距。"},{"id":"n-bas1-58","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"基金自身投资活动产生税收有()。","options":["增值税","印花税","营业税","所得税"],"answer":"ABD","explain":"基金自身投资活动产生的税收:"},{"id":"n-bas1-59","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"关于基金资产估值责任的说法，正确的是()。","options":["我国基金资产估值责任人是基金管理人","我屬QDTT 基金资产估值的责任人为境外资产托管人","基金托管人对基金管理人估值结果负有复核责任","会计师事务所对基金管理人估值结果负有复核责任"],"answer":"AC","explain":"密包文根据《证券投资基金法》前规定，我国基金资产估值的责任人是基金管理人，但基金托管人对基金管理人估值及净值计算结果负有复核义务责任。故“责任人为境外资产托管人”以及“会计师事务所对基金管理人的估值结果负有复核责任”错误。"},{"id":"n-bas1-60","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于我国基金业发展的说法，正确的有()。","options":["在创新发展阶段，我国基金产品创新层出不穷，包括 LOF基金、ETF 基金、分级基金、QDII 基金等","在早期探索阶段，我国基金业发展带有探索性、自发性和不规范性特征","目前中国香港成立前基金可以向内地销售，内地成立的基金也可以进入中国香港市场","我国开放式基金出现先于封闭式基金"],"answer":"ABC","explain":"证券投资基金在我国的发展可分为四个阶段:(1)早期探索阶段(1990～1997年)。1992年11月，国内第一家公司型封闭式投资基金一淄博乡镇企业投资基金正式设立，并于1993年8月在上交所挂牌上市，成为我国首家在证券交易所上市交易的投资基金。这一阶段中国基金业发展带有很大探索性、自发性与不规范性。(2)规范发展阶段(1998～2003年)。1998年3月，两只封闭式基金一基金开元与基金金泰，是我国最早的证券投资基金。2001年9月，我国第一只开放式基金一华安创新诞生。(3)创新发展阶段(2004～2012年)。先后出现了上市开放式基金(LOF)、ETF基金，分级基金、QDII 基金等主要基金创新品种。(4)稳步发展阶段(2013年至今)。2015年7月，内地与香港开启基金互认，香港成立的基金可以向内地销售，内地成立的基金也可以进入香港市场。"},{"id":"n-bas1-61","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于投资基金的说法，正确的有()。","options":["公募基金可以向社会公众公开发售和宣传推广","私募基金可以采用公开方式发行","公募基金的基金募集对象不固定","监管机构会对私募基金投资者人数加以限制"],"answer":"ACD","explain":"(1)公募基金是指面向社会公众公开发售基金份额、募集资金而设立基金。公募基金可以向社会公众公开发售基金份额和宣传推广，基金募集对象不固定。基金份额投资金额要求较低，适合中小投资者参与。(2) 私募基金是向特定合格投资者发售基金份额、募集资金而设立的基金。私募基金不能进行公开发售和宣传推广，只能釆取非公开方式发行。私募基金的投资金额较高，风险较大，监管机构对投资者的资格和人数会加以限制。私募基金的投资范围较广，在基金运作和信息披露方面所受的限制和约束已逐步向公募基金看齐。"},{"id":"n-bas1-62","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于金融期权主要风险指标的说法，正确的有()。","options":["期权的 Rho 值反映到期时间变化对期权价值的影响程度","波动率与认购、认沽期权价值均正相关","市场无风险利率与认购期权为正相关关系","期权 Delta 值反映期权标证券价格变化对期权价格影响程度"],"answer":"BCD","explain":"金融期权价格至少受以下五个因素的影响:标证券价格、执行价格、标证券价格波动性、期权到期期限、无风险利率等。通常用以下指标反映金融期权的风险。Delta 值反映期权标证券价格变化对期权价格影响程度。标的证券价格与认购期权价值为正相关关系，与认沽期权价值为负相关关系。Rho 值反映无风险利率变化对期权价格影响程度。市场无风险利率与认购期权价值为正相关，与认沽期权为负相关。Theta 值反映到期时间变化对期权价值的影响程度。到期期限与认购、认沽期权价值均为正相关关系。Vega值反映合约标证券价格波动率变化对期权价值的影响程度。波动率与认购、认洁期权价值均为正相关关系。"},{"id":"n-bas1-63","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据衍生工具的产品形态分类，金融衍生工具可以划分为()。","options":["独立衍生工具","嵌入式衍生工具","交易所交易衍生工具","OTC 交易的衍生工具"],"answer":"AB","explain":"本题考查衍生工具分类。金融衍生工具可以按照产品形态、自身交易方式、基础工具种类以及交易场所的不同而有不同的分类。(1)按产品形态分类，可分为独立衍生工具和嵌入式衍生工具(A、B正确)。(2) 按照金融衍生工具自身交易的方式及特点，可以分为金融远期合约、金融期货、金融期权、金融互换和结构化金融衍生工具。(3) 按照基础工具种类分类，可以划分为股权类产品衍生工具、货币衍生工具、利率衍生工具、信用衍生工具以及其他衍生工具。(4) 按照交易场所分类，可以分为交易所交易衍生工具和场外交易市场(简称OTC)交易衍生工具(C、D错误，CD是按交易场所分类，而非题干所问 “产品形态分类”)。故本题选 AB 项。"},{"id":"n-bas1-64","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"关于金融衍生工具说法，错误有()。","options":["金融衍生产品的价格决定基础金融产品的价格","金融衍生工具是与基础金融产品相对应一个概念","金融衍生工具是指建立在基础金融产品或基础变量之上，其价格取决于后者价格(或数值)变动派生金融产品","温室气体排放不能成为金融衍生工具基础变量"],"answer":"AD","explain":""},{"id":"n-bas1-65","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据基础资产划分，常见的金融远期合约包括()。","options":["股权类资产远期合约","债权类资产远期合约","远期利率协议","远期汇率协议"],"answer":"ABCD","explain":"根据基础资产划分，常见的金融远期合约包括以下四个大类。(1)股权类资产的远期合约，包括单个股票的远期合约、一篮子股票远期合约和股票价格指数的远期合约三个子类。(2) 债权类资产的远期合约，包括定期存款单、短期债券、长期债券、商业票据等固定收益证券的远期合约。(3)远期利率协议，指交易双方约定在未来某一日交换协议期间内在一定名义本金基础上分别以合同利率和参考利率计算的利息的金融合约。(4)远期汇率协议，指按照约定的汇率，交易双方在约定的未来日期买卖约定数量某种外币的远期协议。"},{"id":"n-bas1-66","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于风险的相关说法，错误有()。","options":["巴塞尔委员会将操作风险事件划分为六种类型","交易对手风险一般不是由实际违约责任所引起，而是由市场察觉到的将会违约概率增加引起","与市场风险不同，操作风险一般为下侧风险，即只可能带来损失，不能带来收益几.本營风造一能是受其也日治彩物们产生制议生网险、與他可以进市附以那计量","远期汇率协议"],"answer":"ABD","explain":"操作风险是指由不完善或有问题的内部流程、人员和系统以及外部事件所造成损失风险。该定义包括法律风险，但不包括战略风险和声誉风险。巴塞尔委员会将操作风险事件划分为七种类型:(1)内部欺诈；(2)外部欺诈；(3)雇员活动和工作场所安全性风险:(4)客户、产品及业务活动中的操作性风险；(5)实物资产损坏:(6)营业中断或信息技术系统瘫痪；(7)执行、交割和流程管理中的操作性风险。交易对手风险是指交易对手未能履行合同约定义务完成交易而导致另一方发生损失可能性。声誉风险一般是受其他风险影响而产生次生风险，很难具体确认和计量，但是它对金融机构影响巨大而且深远。声誉风险是指由证券公司经营管理及其他行为或外部事件导致证券公司股东、员工、客户、第三方合作机构及监管机构等对证券公司的公开负面评价的风险。"},{"id":"n-bas1-67","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"根据风险管理的职责分工，下列关于证券公司董事会应当履行职责的说法，正确的有()。","options":["制定风险管理制度，并适时调整","推进风险文化建设","建立涵盖风险管理有效性的全员绩效考核体系","批准公司的风险偏好、风险容忍度以及重大风险限额"],"answer":"BD","explain":"证券公司董事会承担全面风险管理的最终责任，履行职责包括推进风险文化建设，审议批准公司全面风险管理的基本制度，审议批准公司的风险偏好、风险容忍度以及重大风险限额，审议公司定期风险评估报告，任免并考核首席风险官、确定其薪酬待遇、建立与首席风险官的直接沟通机制等。“制定风险管理制度，并适时调整”属于经理层的职能；“建立涵盖风险管理有效性的全员绩效考核体系”属于高级管理层职能"},{"id":"n-bas1-68","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"目前国内外关于风险的定义较多，其中主要包括 。。","options":["风险是结果的不确定性","风险是波动性或对期望值的偏离度","风险是未来损失可能性","风险不包括盈利可能性"],"answer":"ABC","explain":"目前，国内外金融理论界对风险定义或界定主要有以下三类观点:(1)风险是结果的不确定性，是一种变化。(2) 风险是损失发生可能性，或可能发生的损失，即风险是未来损失的可能性。(3) 风险是结果对期望旳偏离，是(收益旳)波动性。(4)第一种定义:风险被定义为不确定性，比较抽象，强调风险世界变化特性。第二种定义:最传统的风险定义版本。第三种定义:重要特性体现了风险不仅包括损失可能性，也包括对盈利可能性的覆盖，是现代风险计量和管理的基础。故“不包括盈利的可能性”表述错误。"},{"id":"n-bas1-69","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列属于流动性风险衡量指标有()。","options":["流动性覆盖率","净稳定资金率","稳定性覆盖率","稳定资金率"],"answer":"AB","explain":"流动性风险的衡量指标包括:(1) 流动性覆盖率，流动性覆盖率=优质流动性资产-未来30天现金流出量✕100%。(2)净稳定资金率，净稳定资金率=可用稳定资金一所需稳定资金✕100%。"},{"id":"n-bas1-70","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列属于非系统性风险有()。","options":["某公司产品研发导致股价下跌","市场加息引起股票指数下跌","因债务人违约导致公司股价波动","公司财务因火灾受损"],"answer":"ACD","explain":"系统性风险是指国家因多种外部或内部的不利因素经过长时间积累没有被发现或重视，在某段时间共振导致无法控制使金融系统参与者恐慌性出逃(抛售)，造成全市场投资风险加大。系统性风险包括政策风险，宏观风险，流动性风险，外部风险，灾害。其中政策和宏观的变化交互影响市场的流动性。非系统风险亦称“非市场风险”、“可分散风险”。与“系统性风险”相对。与股票市场、期货市场、外汇市场等相关金融投机市场波动无关风险。非系统风险是由特殊因素引起，如企业管理问题、上市公司劳资问题等，是某一企业或行业特有风险，只影响某些股票的收益。非系统风险可通过分散投资消除。"},{"id":"n-bas1-71","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于敏感性分析的说法，正确的有()。","options":["敏感性是经济学分析中的弹性","敏感性在数学上就是函数的一阶导数","敏感性分析是一个动态的分析过程","敏感性分析是市场风险分析中最常用方法之一"],"answer":"ABD","explain":"敏感性分析:(1)敏感性是一个变量对另外一个变量发生的变化的反应程度，也就是经济学分析中的弹性(A 正确)。(2)敏感性风险分析方法的特点在于将投资风险暴露与风险因子联系起来，关注的是投资价值的变化，而非市场风险因子的变化。因此，敏感性分析是一个静态的分析过程(C错误)。(3)在数学上，敏感性就是函数的一阶导数。某一金融产品对某一因子的风险敏感性是该金融产品的价值函数对于某一风险因子的一阶导数(B正确)。(4)敏感性分析是假设当风险因子变化达到一定程度时金融工具价值的变化，敏感性分析是市场风险分析中最常用方法之一(D正确)。故本题选 ABD。"},{"id":"n-bas1-72","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"证券融资交易类交易对手信用风险主要来自()。","options":["回购","逆回购","场外衍生品","证券借货"],"answer":"ABD","explain":"交易对手信用风险主要来自两类金融产品:一是场外衍生品，比如利率互换、汇率远期、信用违约互换:二是证券融资交易，比如回购和逆回购、证券借货，其中场外衍生品规模更大。"},{"id":"n-bas1-73","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"关于基金信息披露，下列说法正确有()。","options":["基金管理人和托管人应当按照法规规定各项时间要求进行基金运作信息披露","基金募集信息披露只是指首次募集信息披露","开放式基金在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值","货币基金需要披露收益公告，包括每万份基金收益和最近7日年化收益率"],"answer":"ACD","explain":"A正确，B错误，基金运作信息披露主要指在基金合同生效后至基金合同终止前，基金信息披露义务人依法定期披露基金的上市交易、投资运作及经营业绩等信息。基金管理人和基金托管人应当按照法规规定的各项时间要求进行基运作信息的披露，时间一般是可以事先预见的。CD 正确，对开放式基金而言，在开放申购和赎回后，会披露每个开放日的份额净值和份额累计净值。对货币基金而言，货币基金每日分配收益，份额净值保持1元不变，因此货币基金不像一般开放式基金那样披露每个开放日的份额净值而是需要披露收益公告，包括每万份基金收益和最近7日年化收益率。"},{"id":"n-bas1-74","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于证券委托的说法，正确的有()。","options":["客户买卖证券的要求主要体现在委托受理的手续和过程中","委托指令内容需要反映客户买卖证券具体要求","证券委托可以分为柜台委托和非柜台委托，","委托指令可根据委托订单的数量分为整数委托和零数委托"],"answer":"BCD","explain":"A项说法错误，在委托指令中，不管是采用填写委托单还是自助委托方式，都需要反映客户买卖证券具体要求，这些要求丰要体现在委托指令的内容中。"},{"id":"n-bas1-75","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"下列关于基金信息披露说法，正确的有()。","options":["与市场上其他理财产品相比，基金的一个突出特点就是透明度较高","基金的信息披露制度有利于防止利益冲突和利益输送","基金的信息披露不具有强制性","基金的信息披露必须保证所披露信息的真实性、准确性和完整性"],"answer":"ABD","explain":"选项A正确，与市场上其他理财产品相比，基金的一个突出特点就是透明度较高；选项阝正确，强制性的基金信息披制度，有利于培育和完善市场运行机制，有利于防止利益冲突与利益输送，增强市场参与各方对市场的理解和信心:选项C错误，在我国，基金的信息披露具有强制性；选项D正确，基金管理人、基金托管人和其他基金信息披露义务人应当依法披露基金信息，并保证所披露信息的真实性、准确性和完整性。"},{"id":"n-bas1-76","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"法人结算模式要求证券公司以法人名义在证券登记结算机构开立的账户有()。","options":["证券结算账户","资金结算账户","证券交收账户","资金交收账户"],"answer":"CD","explain":"法人结算是指由证券公司以法人名义在证券登记结算机构开立证券交收账户和资金交收账户，其接受客户委托代理的证券交易的清算交收均通过此账户办理。1995"},{"id":"n-bas1-77","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"私募基金管理人应当自私募基金募集完毕之日起20个工作日内，向登记备案机构报送材料，办理备案，下列属于报送材料有()","options":["基金合同","托管协议或者保障私募基金财产安全制度措施","私募基金财产证明文件","投资者的基本信息、认购金额、持有基金份额的数量及其受益所有人相关信息"],"answer":"ABCD","explain":"私募基金管理人应当自私募基金募集完毕之日起20个工作日内，向登记备案机构报送下列材料，办理备案:(1)基金合同:(2)托管协议或者保障私募基金财产安全制度措施:(3)私募基金财产证明文件；(4)投资者的基本信息、认购金额、持有基金份额的数量及其受益所有人相关信息；(5)国务院证券监督管理机构规定的其他材料。"},{"id":"n-bas1-78","subject":"basics","source":"2026.11 LC 300题","type":"多选","q":"金融市场根据发行流通的性质可以分为()。","options":["一级市场","私募市场","三级市场","公募市场"],"answer":"AC","explain":"金融市场按发行流通性质分为一级市场和二级市场。一级市场是新金融资产的发行市场，二级市场是已发行金融资产的流通市场。"},{"id":"n-bas1-79","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"交易所期权随时可以转让，保证金制度和结算制度以及结算机构的参与可以保证买方几乎不会承担违约风险，而场外期权交易以上两点都无法保证。所以，相比场内期权，场外期权交易具有较高流动性风险和信用风险。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。交易所期权随时可以转让，保证金制度和结算制度以及结算机构的参与可以保证买方几乎不会承担违约风险，而场外期权交易以上两点都无法保证。所以，相比场内期权，场外期权交易具有较高的流动性风险和信用风险。"},{"id":"n-bas1-80","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"在信用违约互换交易中，违约互换购买者将定期向违约互换出售者支付一定费用，而一旦出现信用类事件，违约互换购买者将有权利将债券以面值递送给违约互换出售者，从而有效规避信用风险。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。在信用违约互换交易中，违约互换购买者将定期向违约互换出售者支付一定费用(称为信用违约互换点差)，而一旦出现信用类事件(主要指债券主体无法偿付)，违约互换购买者将有权利将债券以面值递送给违约互换出售者，从而有效规避信用风险。信用违约互换是国外债券市场中最常见的信用衍生产品。"},{"id":"n-bas1-81","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"结构化金融衍生产品可分为收益保证型产品和非收益保证型产品两大类，其中收益保证型产品又细分为本金保障型产品和保证最低收益型产品。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。结构化金融衍生产品可分为收益保证型产品和非收益保证型产品两大类，其中前者又可进一北细分为本金保酸型产品和保证最低收治地产品。S55"},{"id":"n-bas1-82","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"金融期货交易与金融现货交易不同，它不能创造价值，不是投资工具，而是一种风险管理工具。风险厌恶者可以利用它进行套期保值、规避风险，风险喜好者则利用它承担更大风险。不论是风险厌恶者还是风险喜好者，金融期货前杠杆性都为他们提供了更高的风险管理效率。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。金融期货交易与金融现货交易不同，它不能创造价值，不是投资工具，而是一种风险管理工具。风险厌恶者可以利用它进行套期保值、规避风险，风险喜好者则利用它承担更大的风险。不论是风险厌恶者还是风险喜好者，金融期货杠杆性都为他们提供了更高风险管理效率。"},{"id":"n-bas1-83","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"风险是结果对期望的偏离。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。风险是结果对期望偏离，是(收益的)波动性。"},{"id":"n-bas1-84","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"在有效的金融市场上，只有承担风险才能相应获得收益。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。"},{"id":"n-bas1-85","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"金融风险具有周期性特征。()在有数约金熊市场上，只衬来坦风络才能档加教有惨摄513栋河，","options":["正确押题加微信X S","错误"],"answer":"A","explain":"本题表述正确。金融风险具有以下特征:隐蔽性、扩散性、加速性、不确定性、可管理性、周期性。其中，周期性是指金融风险受经济循环周期和货币政策变化影响，呈现规律、周期性的特点。"},{"id":"n-bas1-86","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"系统风险通常具有内生性、关联性、复杂性、突发性、传染性等特征。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。系统性风险是指由于金融体系的部分或全部功能受到破坏，从而引发金融服务的供应大规模中断，并可能对实体经济造成严重负面影响的风险。它是与单体金融机构风险相对应，通常具有内生性、关联性、复杂性、突发性、传染性等特征。"},{"id":"n-bas1-87","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"市场风险，是指因市场价格变量波动而给经济主体带来损益风险。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。市场风险，是指因市场价格变量波动而给经济主体带来损益的风险。"},{"id":"n-bas1-88","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"商品风险是指因商品价格波动而带来损失前风险。()","options":["正确押题加","错误"],"answer":"A","explain":"本题表述正确。商品风险是指因商品价格波动而带来损失风险。"},{"id":"n-bas1-89","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"信用风险的来源包括场外衍生品业务和非标准化债权资产投资。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。业务结构特点决定了证券公司承担的信用风险在其整体风险承担中的占比低于商业银行。按照证券类机构业务类型分类，信用风险主要来自但不限于以下几类业务:(1)股票质押式回购交易、约定购回式证券交易、融资融券等融资类业务；(2) 互换、场外期权、远期、信用衍生品等场外衍生品业务(本题说法正确)；(3)债券投资交易；(4)非标准化债权资产投资(本题说法正确)；(5)其他涉及信用风险的自有资金出资业务。交易对手信用风险主要来源于自营非权益类交易和融资类业务。"},{"id":"n-bas1-90","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"账面资本不包括未分配利润。()","options":["正确","错误"],"answer":"B","explain":"本题表还错误。账面资本金额为企业合并后资产负债表中资产减去负债后余额，包括实收资本、资本公积、盈余资本、未分配利润等。"},{"id":"n-bas1-91","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"收益公司债券是一种具有特殊性质的债券，与一般的债券相似，没有固定到期日，清偿时债权排列顺序排于股票之后。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。按不同标准，公司债券可以划分为很多种类，常见的分类包括:按担保抵押情况分为信用公司债券、不动产抵押公司债券、保证公司债券。信用公司债券是一种不以公司任何资产作担保而发行的债券，属于无担保证券范围；不动产抵押公司债券是以公司的不动产抵押而发行的债券，是抵押证券的一种。保证公司债券是公司发行由第三者作为还本付息担保人的债券，是担保证券的一种。收益公司债券是一种具有特殊性质的债券，与一般的债券相似，有固定到期日，清偿时债权排列顺序先于股票。"},{"id":"n-bas1-92","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"封闭式基金按规定需在基金合同和招募说明书中约定每年基金收益分配最多次数和每次基金收益分配約最低比例。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。得低于基金年度可供分配利润 90%，基金分配后，基金份额净值不得低于面值。封闭式基金只能采用现金方式分红，而题干是对开放式基金的描述，故错误。"},{"id":"n-bas1-93","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"无面额股票的发行或转让价格较灵活，但不便于股票分割。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。无面额股票有如下特点:(1)发行或转让价格较灵活。(2)便于股票分割。"},{"id":"n-bas1-94","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"在公司经营有方、盈利丰厚情况下，优先股股息收益可能会大大低于普通股。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。持有优先股并不总是有利，比如，在公司经营有方、盈利丰厚的情况下，优先股的股息收益可能会大大低于普通股。"},{"id":"n-bas1-95","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券公司长期次级债可按一定比例计入净资本，到期期限在3年、2年、1年以上的，原则上分别按 100%、70%、50%的比例计入净资本。()","options":["正确","错误"],"answer":"A","explain":"本题表还正确。.3获取证券公司长期次级债可按一定比例计入净资本，到期期限在3年、2年、1年以上的，原则上分别按100%、70%、50%的比例计入净资本。"},{"id":"n-bas1-96","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"中央银行发行商基础货币，是指社会流通中的现金，不包括银行体系中作为准备金前存款。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。中央银行发行的基础货币，包括社会流通中的现金和银行体系中作为准备金的存款。"},{"id":"n-bas1-97","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"基金资产估值引起的资产价值变动作为公允价值变动损益计入当期损益。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。公允价值变动损益是指基金持有的采用公允价值模式计量的交易性金融资产、交易性金融负债等公允价值变动形成的应计入当期损益的利得或损失，并于估值日对基金资产按公允价值估值时予以确认。"},{"id":"n-bas1-98","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"港股通交易以人民币报价，投资者以港币交收。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。3获取投者应当通过沪市人民币普通股票账户进行港股通交易。港股通交易以港币报价，投资者以人民币交收。"},{"id":"n-bas1-99","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"商业银行经营资金主要来源是存款分”()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。存款是银行负债业务中最重要业务，是商业银行经营资金的主要来源。吸收存款是商业银行赖以生存和发展基础，一般占负债总额的70%以上。"},{"id":"n-bas1-100","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"在金融交易中，花费一定的时间来定位交易对手一般视为显性成本。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。花费一定的时间来定位交易对手为隐性成本。"},{"id":"n-bas1-101","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"证券登记结算制度包括:证券实名制、货银对付的交收制度、分级结算制度和结算参与人制度、全额结算制度、结算证券和资金的专用性制度。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。证券登记结算制度包括:证券实名制、货银对付的交收制度、分级结算制度和结算参与人制皮、淨解法酥制度、结铁证券和实金们专用性制饭食"},{"id":"n-bas1-102","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"交易所债券市场实行“中央登记、一级托管“前制度:银行间债券市场实行一级、二级综合托管账户模式。()","options":["正确","错误"],"answer":"B","explain":"本题表还错误。交易所债券市场实行“中央登记、二级托管”的制度。"},{"id":"n-bas1-103","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"股票发行后股息率不再变动的优先股票，称为固定利息率优先股票。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。股息率优先股存续期内不作调整的，被称为固定股息率优先股:而根据约定的计算方法进行调整的，被称为浮动股息率优先股。"},{"id":"n-bas1-104","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"“风险是最终收益对期望值偏离”在这个描述中，强调风险特性是波动性。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。目前，国内外金融理论界对风险的定义或界定主要有以下学类观点:(1)风险是结果的不确定性，是一种变化。(2)风险是损失发生可能性，或可能发生的损失。(3)凤险是结果对期望的偏离，(收益肉》额动性。"},{"id":"n-bas1-105","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"现代风险管理的基本理念包括；《“任何金融产品都是风险和收益的组合，风险是与收益相匹配时，投资是以风险换收益”。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。限额管理体现了现代风险管理是一种全面的风险管理，限额管理体现了任何金融产品是风险和收益的组合，投资是以风险换收益。"},{"id":"n-bas1-106","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"在信用风险分析中，违约依然是最为重要的信用事件，对信用风险描述和量化仍然以违约为中心，主要包括违约概率违约损失率和违约时的风险暴露等。()","options":["正确","错误"],"answer":"A","explain":"本题表述正确。在信用风险分析中，违约依然是最为重要的信用事件，对信用风险的描述和量化仍然是以违约为中心，主要包括违约概率、违约损失率、违约时的风险暴露等。"},{"id":"n-bas1-107","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"国家发改委明确规定项目发起人(原始权益人)应为持有消费基础设施、开展相关业务的独立法人主体，可以从事商品住宅开发业务。()","options":["正确","错误"],"answer":"B","explain":"本题表述错误。国家发改委明确规定项目发起人(原始权益人》应为持有消费基础设施、开展相关业务独立法人主体，不得从事商品住宅开发业务。"},{"id":"n-bas1-108","subject":"basics","source":"2026.11 LC 300题","type":"判断","q":"QDII 是境外合格投资者。","options":["正确","错误"],"answer":"B","explain":"本题表述错误。合格境内机构投资者(QDII)制度，是指经一国金融管理当局审批通过、获准直接投资境外股票或者债券市场的国内机构投资者，在一定规定下通过基金形式募集一定额度前人民币资金，通过严格监管的专门账户投资国外证券市场，其汇回的资本利得、股息红利等经审核后可转为本币的一种市场开放机制。"},{"id":"n-bas1-109","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】2022年4月20日全国人大常委会审议通过了《期货和衍生品法》，自2022年8月1\n日起实施。《期货和衍生品法》补齐了我国期货和衍生品领域的法律“短板”。请回答以下\n问题。\n\n【问题】下列关于《期货和衍生品法》立法特点说法，错误是()。","options":["以境内为主，兼顾境外","以期货为主，兼顾其他衍生品","以场外为主，兼顾场内","以标准化为主，兼顾非标产品"],"answer":"C","explain":"《期货和衍生品法》在立法上的特点主要体现在四个方面。(1) 以期货为主，兼顾其他衍生品。衍生品家族主要有四大成员，分别是期货、期权、远期和互换。(2) 以场内为主，兼顾场外。场内交易通常指所有的供求方集中在交易所进行竞价交易交易方式。(3) 以境内为主，兼顾境外。期货和衍生品基于原生品即现货市场发展，在产业链供应链全球化前今天，期货和衍生品“走出去”是必然选择。(4) 以标准化产品为主，兼顾非标产品。《期货和衍生品法》明确了期货交易、衍生品交易的定义，对期货、期权、远期、互换等衍生产品给予了明确的法律界定。"},{"id":"n-bas1-110","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】2022年4月20日全国人大常委会审议通过了《期货和衍生品法》，自2022年8月1\n日起实施。《期货和衍生品法》补齐了我国期货和衍生品领域的法律“短板”。请回答以下\n问题。\n\n【问题】《期货和衍生品法》首次明确了交易报告库的法律地位及主要职责，我国己建成的交易报告库包括()。","options":["中国期货市场监控中心交易报告库","深圳交易所交易报告库","上海交易所交易报告库","中证报价场外业务交易报告库"],"answer":"AD","explain":"《期货和衍生品法》首次明确了交易报告库的法律地位及主要职责，规定“应当建立衍生品交易报告库，对衍生品交易标的、规模、对手方等信息进行集中收集、保存、分析和管理，并按照规定及时向市场披露有关信息”。我国证券期货行业自 2014 年开始建设交易报告库。目前，共建成中证报价场外业务报告库、中国期货市场监控中心交易报告库两家交易报告库，并相继被金融稳定理事会认证为正式交易报告库(TR)，表明我国交易报告库建设已初步达到国际标准。由于是《期货和衍生品法》，约束期货及衍生品，而 BC 选项是证券交易报告库，故可排除。"},{"id":"n-bas1-111","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】近日，中国证监会根据《证券法》的有关规定成立调查组，对某私募证券投资基金涉\n嫌操纵市场一案进行立案调查。调查组查询了当事人和与被调查案子有关的单位和个人的资\n金账户、证券账户、银行账户以及其他具有支付《托管、结算等账户信息。随着调查组对该\n私募证券投资基金涉嫌操纵市场一案调查深入，发现该私募证券投资基金通过控制其发行\n的6个私募基金产品账户、2个资产管理计划账户、8个理财专户账户及借入并控制10个\n自然人账户操纵市场，手段隐蔽、资金量巨大，并存在转移违法资金、毁损财务会计资料和\n伪造开户资料等行为，案情重大、复杂。请根据上述背景信息回答以下问题。\n\n【问题】调查组在调查过程中，不得对有关文件和资料进行()。","options":["扣押","销","封存","复制"],"answer":"B","explain":"(1)查阅、复制当事人和与被调查事件有关的单位和个人的证券交易记录、登记过户记录、财务会计资料及其他相关文件和资料:对可能被转移、隐匿或者毁损的文件和资料，可以予以封存、扣押。(2)查询当事人和与被调查事件有关的单位和个人的资金账户、证券账户、银行账户以及其他具有支付、托管、结算等功能的账户信息，可以对有关文件和资料进行复制。"},{"id":"n-bas1-112","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】近日，中国证监会根据《证券法》的有关规定成立调查组，对某私募证券投资基金涉\n嫌操纵市场一案进行立案调查。调查组查询了当事人和与被调查案子有关的单位和个人的资\n金账户、证券账户、银行账户以及其他具有支付《托管、结算等账户信息。随着调查组对该\n私募证券投资基金涉嫌操纵市场一案调查深入，发现该私募证券投资基金通过控制其发行\n的6个私募基金产品账户、2个资产管理计划账户、8个理财专户账户及借入并控制10个\n自然人账户操纵市场，手段隐蔽、资金量巨大，并存在转移违法资金、毁损财务会计资料和\n伪造开户资料等行为，案情重大、复杂。请根据上述背景信息回答以下问题。\n\n【问题】对此案件，国务院证券监督管理机构可以依法采取的措施包括 ()。","options":["经国务院证券监督管理机构主要负责人或者其授权其他负责人批准，可以冻结或者查封有关账户、涉案财产","通知出入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境","经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以限制被调查事件当事人的证券买卖","经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，责令该私募证券投资基金清算其管理的产品、理财账户"],"answer":"ABC","explain":"国务院证券监督管理机构根据《证券法》依法履行职责，有权采取下列措施:(1)进入涉嫌违法行为发生场所调查取证。(2)对有证据证明已经或者可能转移或者隐匿违法资金、证券等涉案财产或者隐匿、伪造、毁损重要证据的，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以冻结或者查封，期限为6个月；因特殊原因需要延长的，每次延长期限不得超过3个月，冻结、查封期限最长不得超过2年。(3)在调查操纵证券市场、内慕交易等重大证券违法行为时，经国务院证券监督管理机构主要负责人或者其授权的其他负责人批准，可以限制被调查事件当事人的证券买卖，但限制的期限不得超过3个月；案情复杂的，可以延长3个月。(4)通知出境入境管理机关依法阻止涉嫌违法人员、涉嫌违法单位的主管人员和其他直接责任人员出境。"},{"id":"n-bas1-113","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】根据《国务院关于开展优先股试点的指导意见》，2019年初，某上市公司非公开发行\n首期优先股3亿股，募集资金12亿元，期限3十N年，股息率为4.80%。2020年，该上市公\n司召开股东大会，对非公开发行第二期优先股2亿股的议案进行表决。请根据上述背景信息\n回答以下问题。\n\n【问题】下列关于优先股的说法，正确的有()。","options":["优先股的股息，须在派发普通股股息之前派发","优先股股东对公司经营的影响力要大于普通股股东","优先股既像债券，又像股票13获取","在破产清算时，优先股股东对公司剩余财产的权利先于普通股，但在债权人之后"],"answer":"ACD","explain":"微信XS优先股既像债券，又像股票，其“优先”主要体现在:一是通常具有固定的股息(类似债券)，并须在派发普通股股息之前派发:笨是在破产清算时，优先股股东对公司剩余财产权利先于普通股股东，但在债权人之后。"},{"id":"n-bas1-114","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】根据《国务院关于开展优先股试点的指导意见》，2019年初，某上市公司非公开发行\n首期优先股3亿股，募集资金12亿元，期限3十N年，股息率为4.80%。2020年，该上市公\n司召开股东大会，对非公开发行第二期优先股2亿股的议案进行表决。请根据上述背景信息\n回答以下问题。\n\n【问题】下列关于第二期优先股议案表决的说法，正确的是()。","options":["首期优先股股东出席享有表决权，且与参加会议普通股股东一起表决","该议案须经出席会议普通股股东所持表决权的三分之二以上通过之外，还须经出席会议的首期优先股股东所持表决权三分之二以上通过","该议案只需经出席会议的首期优先股股东所持表决权三分之二以上通过","首期优先股股东不出席股东大会会议，所持股份没有表决权"],"answer":"B","explain":"(1) 优先股股东其他一些股东权利是受限的。一般对公司日常经营管理事务没有表决权，对公司经营的影响力要小于普通股股东。(2)优先股股东在以下两种情况下具有表决权:1. 固有的表决权，是公司对与优先股股东利益切身相关重大事项进行表决时，优先股股东享有表决权，而且与普通股分类表决，以下五种事项除须经出席会议的普通股股东所持表决权的三分之二以上通过之外，还须经出席会议的优先股股东所持表决权的三分之二以上通过；修改公司章程中与优先股相关的内容；一次或累计减少公司注册资本超过百分之十；公司合并、分立、解散或变更公司形式:发行优先股:公司章程规定的其他情形。2. 恢复表决权，是由于公司长期未按约定分配股息，优先股股东恢复到与普通股股东同样的表决权，可以参与公司经营决策，与晋通股一同参加投票。公司累计3个会计年度或连续2个会计年度未按约定支付优先股股息前，优先股股东可以享有公司章程规定的表决权。但当公司全额支付所欠优先股股息时，将不再享有这类表决权。"},{"id":"n-bas1-115","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】根据《国务院关于开展优先股试点的指导意见》，2019年初，某上市公司非公开发行\n首期优先股3亿股，募集资金12亿元，期限3十N年，股息率为4.80%。2020年，该上市公\n司召开股东大会，对非公开发行第二期优先股2亿股的议案进行表决。请根据上述背景信息\n回答以下问题。\n\n【问题】因经营亏损，该上市公司2020 年、2021 年连续两个会计年度未能按照约定支付优先股股息，优先股股东可以享有公司章程规定的表决权，下列关于该类表决权说法，正确的有()。","options":["在公司全额支付所欠优先股股息时，优先股股东将不再享有该类表决权","被称为优先股“恢复表决权”","该类表决权一经享有一直存在","持有该类表决权优先股股东，可以参与公司经营决策，与普通股具有同样的表决权，一同参加投票"],"answer":"ABD","explain":"(1)优先股股东其他一些股东权利是受限。一般对公司日常经营管理事务没有表决权，对公司经营影响力要小于普通股股东。(2)优先股股东在以下两种情况下具有表决权:1.固有的表决权，是公司对与优先股股东利益切身相关的重大事项进行表决时，优先股股东享有表决权，而且与普通股分类表决，以下五种事项除须经出席会议普通股股东所持表决权前三分之二以上通过之外，还须经出席会议的优先股股东所持表决权三分之二以上通过:修改公司章程中与优先股相关的内容；一次或累计减少公司注册资本超过百分之十；公司合并、分立、解散或变更公司形式:发行优先股；公司章程规定的其他情形。2. 恢复的表决权，是由于公司长期未按约定分配股息，优先股股东恢复到与普通股股东同样的表决权，可以参与公司经营决策，与普通股一同参加投票。公司累计3个会计年度或连续2个会计年度未按约定支付优先股股息的，优先股股东可以享有公司章程规定的表决权。但当公司全额支付所欠优先股股息时，将不再享有这类表决权。"},{"id":"n-bas1-116","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公募基金公司正处于筹建过程中，近期，公募基金公司设立筹建工作组，拟对公司\n基金资产估值、费用及其计提方式、利润分配相关控制措施与流程进行梳理，在考虑相关业\n务规则的基础上，制定相关业务管理制度，并逐步予以完善，从而确保基金依法合规有席运\n作。请根据上述背景信息回答以下问题。\n\n【问题】下列关于该公司基金资产估值要求的说法，正确的是()。","options":["封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但仅需每周披露一次基金份额净值","基金采用的估值方法需要在法定募集文件中公开披露，若基金变更了估值方法，必须及时进行披露","开放式基金于每个交易日估值，并不晚于下一交易日公告份额净值","对于投资标的交易活跃资产，可分离至侧袋账户进行处置清算，以确保投资者得到公平"],"answer":"ABC","explain":"基金资产估值需考虑因素:估值频率、交易价格公允性、估值方法一致性及公开性。1. 基金资产估值频率，基金一般都按照固定的时间间隔对基金资产进行估值，通常相关法规会规定一个最小的估值频率。我国的开放式基金于每个交易日估值，并不晚于下一交易日公告份额净值:封闭式基金和定期开放式基金的封闭期每个交易日都进行估值，但每周披露一次基金份额净值。2. 估值方法的一致性是指基金在进行资产估值时均应采用同样估值方法，遵守同样的估值规则。估值方法公开性是指基金采用估值方法需要在法定募集文件中公开披露。若基金变更了估值方法，必须及时进行披露。3.公允性。当基金投资标的为交易活跃的证券时，对其资产进行估值较为容易。在这种情况下，市场交易价格是可获得并被接受的，也是公允，因此，也是可信，直接采用市场交易价格就可以对标的资产估值。"},{"id":"n-bas1-117","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公募基金公司正处于筹建过程中，近期，公募基金公司设立筹建工作组，拟对公司\n基金资产估值、费用及其计提方式、利润分配相关控制措施与流程进行梳理，在考虑相关业\n务规则的基础上，制定相关业务管理制度，并逐步予以完善，从而确保基金依法合规有席运\n作。请根据上述背景信息回答以下问题。\n\n【问题】下列关于该公司基金费用及计提方式说法，正确的有()。","options":["基金管理费、基金托管费及基金销售服务费均是按照前一日基金资产净值一定比例逐日计提，按年支付","申购费(认购费)、赎回费及基金转换费由基金投资者承担，不参与基金会计核算","基金管理费、托管费、持有人大会费、信息披露费由基金资产承担，直接从基金资产中列","与侧袋账户有关的费用需从侧袋账户中列支，但应待特定资产变现后方可列支，并收取管理费及业绩报酬"],"answer":"BC","explain":"(1) 基金管理费是指基金管理人管理基金资产而向基金收取的费用。我国的基金管理费、基金托管费及基金销售服务费均是按照前一日基金资产净值的一定比例逐日计提，按月支付。(2)在基金运作过程中涉及费用可以分为两大类:①一类是基金销售过程中发生由基金投资者承担的费用，主要包括申购费(认购费)、赎回费及基金转换费等；②另一类是基金管理过程中发生的费用，主要包括基金管理费、基金托管费、持有人大会费用、信息披露费等，这些费用由基金资产承担。上述两大类费用的性质是不同。第一类费用并不参与基金的会计核算，而第二类费用则需要直接从基金资产中列支，其种类及计提标准需在基金合同及基金招募说明书中明确规定。(3)“并收取管理费及业绩报酬”表述错误，应该是“并不收取管理费及业绩报酬”。"},{"id":"n-bas1-118","subject":"basics","source":"2026.11 LC 300题","type":"案例","q":"【资料】某公募基金公司正处于筹建过程中，近期，公募基金公司设立筹建工作组，拟对公司\n基金资产估值、费用及其计提方式、利润分配相关控制措施与流程进行梳理，在考虑相关业\n务规则的基础上，制定相关业务管理制度，并逐步予以完善，从而确保基金依法合规有席运\n作。请根据上述背景信息回答以下问题。\n\n【问题】下列关于该公司基金利润分配的说法，正确的有()。","options":["开放式基金要求基金利润分配后基金份额净值不得低于面值","基金利润主要来自基金收入减去基金费用后的净额、公允价值变动损益","封闭式基金的收益分配每年不得少于一次，可采取现金分红和红利再投资两种方式","当日赎回的货币市场基金份额自赎回当日起不享有基金的分配权益"],"answer":"AB","explain":"(1) 根据有关规定，封闭式基金的收益分配每年不得少于一次，封闭式基金年度收益分配比例不得低于基金年度可供分配利润90%。基金分配后，基金份额净值不得低于面值。封闭式基金只能采用现金方式分红。(2) 根据有关规定，一般开放式基金利润分配默认方式应当采用现金分红。开放式基金的基金份额持有人可以事先选择分红再投资。基金份额持有人事先未作出选择的，基金管理人应当支付现金。(3) 对于每日按照面值进行报价的货币市场基金，可以在基金合同中将收益分配方式约定为红利再投资，并应当每日进行收益分配。(4) 基金利润是指基金在一定会计期间经营成果。基金利润主要来自基金收入减去基金费用后的净额、公允价值变动损盖等。基金收入主要包括利息收入、投资收益以及其他收入。"}]}];
